def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts and ratios
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.18:
            return Tool.INDUSTRIAL
        if c_r < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dynamic plant placement based on population
    base_plants = [(30, 50), (90, 50)]
    extra_plants = []
    if pop > 100:
        extra_plants += [(60, 25), (60, 75)]
    if pop > 400:
        extra_plants += [(10, 25), (110, 25), (10, 75), (110, 75)]
    if pop > 800:
        extra_plants += [(30, 15), (90, 15), (30, 85), (90, 85)]
    if pop > 1500:
        extra_plants += [(60, 10), (60, 90), (20, 50), (100, 50)]
    if pop > 2500:
        extra_plants += [(45, 5), (75, 5), (45, 95), (75, 95)]
        extra_plants += [(5, 50), (115, 50), (5, 20), (115, 20), (5, 80), (115, 80)]

    all_plants = base_plants + extra_plants

    # Ensure plants exist
    for px, py in all_plants:
        found = any(
            ib(px+dx, py+dy) and pm[py+dy, px+dx]
            for dy in range(-4, 5) for dx in range(-4, 5)
        )
        if not found and ib(px, py):
            return (Tool.COALPOWER, px, py)

    # Build wire network: ensure plants are connected
    # Horizontal wire spine at row 50
    for x in range(1, WORLD_W - 1):
        if em[50, x] and not pm[50, x] and not wm[50, x]:
            left_ok = ib(x-1,50) and (wm[50,x-1] or pm[50,x-1])
            right_ok = ib(x+1,50) and (wm[50,x+1] or pm[50,x+1])
            if left_ok or right_ok:
                return (Tool.WIRE, x, 50)

    # Vertical wire spines from each plant hub
    for px, py in all_plants:
        extent = min(45, 12 + pop // 80)
        spine_top = max(3, py - extent)
        spine_bot = min(WORLD_H - 4, py + extent)
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (wm[r, px] or pm[r, px])]
        if col_wires:
            mn, mx = min(col_wires), max(col_wires)
            if mx < spine_bot:
                ny = mx + 1
                if ib(px, ny) and em[ny, px] and not pm[ny, px]:
                    return (Tool.WIRE, px, ny)
            if mn > spine_top:
                ny = mn - 1
                if ib(px, ny) and em[ny, px] and not pm[ny, px]:
                    return (Tool.WIRE, px, ny)

    # Horizontal cross-wires at strategic rows
    cross_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    if pop > 200:
        cross_rows += [15, 25, 35, 45, 55, 65, 75, 85]
    if pop > 600:
        cross_rows += [5, 95]

    for cr in cross_rows:
        if not ib(0, cr):
            continue
        for x in range(1, WORLD_W - 1):
            if em[cr, x] and not pm[cr, x] and not wm[cr, x]:
                left_has = ib(x-1, cr) and (wm[cr, x-1] or pm[cr, x-1])
                right_has = ib(x+1, cr) and (wm[cr, x+1] or pm[cr, x+1])
                if left_has or right_has:
                    return (Tool.WIRE, x, cr)

    # Cross-connect vertical spines with horizontal wires
    for px, py in all_plants:
        for cr in cross_rows:
            if abs(cr - py) <= 45:
                if ib(px, cr) and em[cr, px] and not pm[cr, px] and not wm[cr, px]:
                    above = ib(px, cr-1) and (wm[cr-1, px] or pm[cr-1, px])
                    below = ib(px, cr+1) and (wm[cr+1, px] or pm[cr+1, px])
                    if above or below:
                        return (Tool.WIRE, px, cr)

    # Build road network
    # Vertical roads flanking wire spines
    for px, py in all_plants:
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (wm[r, px] or pm[r, px])]
        if not col_wires:
            continue
        mn_w, mx_w = min(col_wires), max(col_wires)
        for roff in [-1, 1]:
            rc = px + roff
            if not ib(rc, 0):
                continue
            for wr in range(mn_w, mx_w + 1):
                if ib(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # Horizontal roads at strategic rows (offset from wire rows)
    h_road_rows = [9, 19, 29, 39, 49, 51, 61, 71, 81, 91]
    if pop > 300:
        h_road_rows += [14, 24, 34, 44, 56, 66, 76, 86]
    if pop > 800:
        h_road_rows += [4, 96]

    for hr in h_road_rows:
        if not ib(0, hr):
            continue
        wire_above = hr > 0 and (wm[hr-1, :] | pm[hr-1, :]).any()
        wire_below = hr < WORLD_H-1 and (wm[hr+1, :] | pm[hr+1, :]).any()
        if wire_above or wire_below:
            for x in range(2, WORLD_W - 2):
                if ib(x, hr) and em[hr, x] and not pm[hr, x] and not rm[hr, x]:
                    return (Tool.ROAD, x, hr)

    # Proximity masks for zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Place zones: prefer near plants and roads
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in all_plants:
            d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
            min_dist = np.minimum(min_dist, d)
        # Also prefer locations near existing zones (clustering)
        if total_zones > 1:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                for i in range(0, len(zone_xs), max(1, len(zone_xs)//50)):
                    d2 = np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])
                    zone_dist = np.minimum(zone_dist, d2)
                # blend: prefer near infrastructure but also cluster
                combined = min_dist * 0.6 + zone_dist * 0.4
            else:
                combined = min_dist
        else:
            combined = min_dist

        order = np.argsort(combined)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services based on population
    if pop > 80:
        fire_spots = [(28, 40), (32, 40), (88, 40), (92, 40),
                      (28, 60), (32, 60), (88, 60), (92, 60),
                      (58, 20), (62, 20), (58, 78), (62, 78),
                      (10, 25), (10, 75), (110, 25), (110, 75)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 250:
        police_spots = [(25, 38), (35, 38), (85, 38), (95, 38),
                        (25, 62), (35, 62), (85, 62), (95, 62),
                        (55, 20), (65, 20), (55, 80), (65, 80),
                        (10, 50), (110, 50)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        for stx, sty in [(42, 32), (78, 32), (42, 68), (78, 68),
                         (20, 50), (100, 50), (60, 15), (60, 85)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 900:
        for apx, apy in [(55, 8), (55, 92), (10, 40), (110, 40)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1200:
        for spx, spy in [(8, 50), (112, 50), (60, 5), (60, 95)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Parks to improve land value
    if pop > 400:
        park_spots = [(50, 45), (70, 45), (50, 55), (70, 55),
                      (40, 35), (80, 35), (40, 65), (80, 65)]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    # Fallback: extend roads near existing roads with wire access
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire and road spines."""
    actions = []
    # Three power plants at strategic positions
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Wire spines vertical from each plant
    for dy in range(-10, 11):
        actions.append((Tool.WIRE, 20, 50 + dy))
        actions.append((Tool.WIRE, 60, 50 + dy))
        actions.append((Tool.WIRE, 100, 50 + dy))
    # Flanking roads on both sides of each wire spine
    for dy in range(-10, 11):
        for wc in [20, 60, 100]:
            actions.append((Tool.ROAD, wc - 1, 50 + dy))
            actions.append((Tool.ROAD, wc + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone type selector: balance I/C/R
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Build proximity masks using numpy shifts
    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Configuration: wire columns and plant rows
    # More columns as population grows
    all_wire_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    all_plant_rows = [15, 35, 55, 75, 90]

    def num_active_cols():
        if pop < 50:   return 3
        if pop < 200:  return 4
        if pop < 500:  return 5
        if pop < 1000: return 6
        if pop < 2000: return 7
        if pop < 4000: return 8
        if pop < 7000: return 9
        return 10

    n_cols = num_active_cols()
    # Choose columns spread across the map
    col_indices = np.linspace(0, len(all_wire_cols) - 1, n_cols, dtype=int)
    active_cols = [all_wire_cols[i] for i in col_indices]

    # How many plant rows to use
    def num_plant_rows():
        if pop < 500:  return 2
        if pop < 2000: return 3
        if pop < 5000: return 4
        return 5

    n_prows = num_plant_rows()
    active_plant_rows = all_plant_rows[:n_prows]

    # ---- ENSURE POWER PLANTS ----
    for wc in active_cols:
        for pr in active_plant_rows:
            has_plant = bool(np.any(pm[max(0, pr-8):min(WORLD_H, pr+9),
                                      max(0, wc-8):min(WORLD_W, wc+9)]))
            if not has_plant:
                # Find nearest empty spot
                for r in range(0, 20):
                    placed = False
                    for dy2 in range(-r, r + 1):
                        for dx2 in range(-r, r + 1):
                            if r > 0 and abs(dx2) != r and abs(dy2) != r:
                                continue
                            nx, ny = wc + dx2, pr + dy2
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # ---- EXTEND WIRE SPINES ----
    spine_half = min(45, 12 + pop // 15)
    for wc in active_cols:
        col_wires = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not col_wires:
            # Seed wire near nearest plant
            for pr in active_plant_rows:
                for dy2 in range(-10, 11):
                    ny = pr + dy2
                    if ib(wc, ny) and not bool(pm[ny, wc]):
                        if bool(em[ny, wc]) or bool(wm[ny, wc]):
                            return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(col_wires)
            max_wr = max(col_wires)
            target_top = max(2, 50 - spine_half)
            target_bot = min(WORLD_H - 3, 50 + spine_half)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)

    # ---- EXTEND ROADS flanking wire spines ----
    road_half = min(45, 10 + pop // 20)
    for idx, wc in enumerate(active_cols):
        rl, rr = wc - 1, wc + 1
        col_wires = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not col_wires:
            continue
        target_top = max(2, 50 - road_half)
        target_bot = min(WORLD_H - 3, 50 + road_half)
        cycle = (step + idx * 3) % 3
        for wr in col_wires[cycle::3]:
            if wr < target_top or wr > target_bot:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL WIRE CONNECTIONS between adjacent columns ----
    # Connect at multiple y-levels spanning the active plant rows + midpoints
    conn_ys = sorted(set([pr for pr in active_plant_rows] + [25, 50, 75]))
    for i in range(len(active_cols) - 1):
        c1 = active_cols[i]
        c2 = active_cols[i + 1]
        for conn_y in conn_ys:
            if not (0 <= conn_y < WORLD_H):
                continue
            # Check if wire already connects them at this y
            connected = all(
                bool(wm[conn_y, cx]) or bool(pm[conn_y, cx])
                for cx in range(c1, c2 + 1) if ib(cx, conn_y)
            )
            if not connected:
                for cx in range(c1, c2 + 1):
                    if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                        return (Tool.WIRE, cx, conn_y)

    # ---- HORIZONTAL ROAD CONNECTIONS between columns ----
    # Roads one row above/below wire connections to avoid overwriting wire
    if pop > 50:
        road_conn_ys = [pr - 1 for pr in active_plant_rows if pr - 1 >= 2] + [23, 48, 73]
        road_conn_ys = sorted(set(road_conn_ys))
        for conn_y in road_conn_ys:
            if not (0 <= conn_y < WORLD_H):
                continue
            for i in range(len(active_cols) - 1):
                c1 = active_cols[i] - 1  # road is beside wire col
                c2 = active_cols[i + 1] - 1
                row_roads = [c for c in range(c1, c2 + 1) if ib(c, conn_y) and bool(rm[conn_y, c])]
                if not row_roads:
                    # Seed the road
                    for cx in range(c1, c2 + 1):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)
                else:
                    # Extend existing road
                    min_r2 = min(row_roads)
                    max_r2 = max(row_roads)
                    if min_r2 > c1:
                        for cx in range(c1, min_r2):
                            if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                                return (Tool.ROAD, cx, conn_y)
                    if max_r2 < c2:
                        for cx in range(max_r2 + 1, c2 + 1):
                            if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                                return (Tool.ROAD, cx, conn_y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    # Keep away from edges
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer near active wire columns and balanced vertically
        best_dist = np.full(len(cxs), 999999.0)
        for wc in active_cols:
            d = (np.abs(cxs - wc).astype(float) +
                 np.abs(cys - 50).astype(float) * 0.2)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- EXTEND ROADS from existing road ends near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx2, ry + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 80:
        fire_spots = []
        for fy in range(15, 90, 18):
            for fx in range(15, 115, 25):
