                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any wire ----
    wire_ys_arr2, wire_xs_arr2 = np.where(wm)
    if len(wire_xs_arr2) > 0:
        k = step % len(wire_xs_arr2)
        wx, wy = int(wire_xs_arr2[k]), int(wire_ys_arr2[k])
