def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dynamic plant list based on population
    all_plants = [(30, 50), (90, 50)]
    if pop > 50:
        all_plants += [(60, 25), (60, 75)]
    if pop > 200:
        all_plants += [(10, 25), (110, 25), (10, 75), (110, 75)]
    if pop > 500:
        all_plants += [(30, 10), (90, 10), (30, 90), (90, 90)]
    if pop > 900:
        all_plants += [(60, 10), (60, 90), (10, 50), (110, 50)]
    if pop > 1500:
        all_plants += [(20, 35), (100, 35), (20, 65), (100, 65)]
    if pop > 2500:
        all_plants += [(45, 5), (75, 5), (45, 95), (75, 95),
                       (5, 15), (115, 15), (5, 85), (115, 85)]

    # Ensure plants exist (check if plant is present near expected location)
    for px, py in all_plants:
        found = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px+dx, py+dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found and ib(px, py):
            return (Tool.COALPOWER, px, py)

    # Build wire network reactively: find wire/plant endpoints and extend
    # Horizontal wire spine at row 50
    for x in range(1, WORLD_W - 1):
        if em[50, x] and not pm[50, x] and not wm[50, x]:
            left_ok = (ib(x-1,50) and (wm[50,x-1] or pm[50,x-1]))
            right_ok = (ib(x+1,50) and (wm[50,x+1] or pm[50,x+1]))
            if left_ok or right_ok:
                return (Tool.WIRE, x, 50)

    # Vertical wire spines from each plant
    for px, py in all_plants:
        extent = min(48, 15 + pop // 60)
        spine_top = max(2, py - extent)
        spine_bot = min(WORLD_H - 3, py + extent)
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (wm[r, px] or pm[r, px])]
        if col_wires:
            mn, mx = min(col_wires), max(col_wires)
            if mx < spine_bot:
                ny = mx + 1
                if ib(px, ny) and em[ny, px] and not pm[ny, px]:
                    return (Tool.WIRE, px, ny)
            if mn > spine_top:
                ny = mn - 1
                if ib(px, ny) and em[ny, px] and not pm[ny, px]:
                    return (Tool.WIRE, px, ny)

    # Horizontal cross-wires at many rows to connect spines
    cross_rows = list(range(5, 96, 5))
    for cr in cross_rows:
        if not ib(0, cr):
            continue
        for x in range(1, WORLD_W - 1):
            if em[cr, x] and not pm[cr, x] and not wm[cr, x]:
                left_has = ib(x-1, cr) and (wm[cr, x-1] or pm[cr, x-1])
                right_has = ib(x+1, cr) and (wm[cr, x+1] or pm[cr, x+1])
                if left_has or right_has:
                    return (Tool.WIRE, x, cr)

    # Fill cross-spine horizontal wires adjacent to vertical spines
    for px, py in all_plants:
        for cr in cross_rows:
            if ib(px, cr) and em[cr, px] and not pm[cr, px] and not wm[cr, px]:
                above = ib(px, cr-1) and (wm[cr-1, px] or pm[cr-1, px])
                below = ib(px, cr+1) and (wm[cr+1, px] or pm[cr+1, px])
                if above or below:
                    return (Tool.WIRE, px, cr)

    # Build road network reactively
    # Vertical roads flanking each plant's wire spine
    for px, py in all_plants:
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (wm[r, px] or pm[r, px])]
        if not col_wires:
            continue
        mn_w, mx_w = min(col_wires), max(col_wires)
        for roff in [-1, 1]:
            rc = px + roff
            if not ib(rc, 0):
                continue
            for wr in range(mn_w, mx_w + 1):
                if ib(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # Horizontal roads at rows adjacent to cross-wire rows
    h_road_rows = list(range(6, 95, 5))  # offset from wire rows by 1
    for hr in h_road_rows:
        if not ib(0, hr):
            continue
        wire_above = hr > 0 and (wm[hr-1, :] | pm[hr-1, :]).any()
        wire_below = hr < WORLD_H-1 and (wm[hr+1, :] | pm[hr+1, :]).any()
        if wire_above or wire_below:
            for x in range(2, WORLD_W - 2):
                if ib(x, hr) and em[hr, x] and not pm[hr, x] and not rm[hr, x]:
                    return (Tool.ROAD, x, hr)

    # Also build roads at rows between zones to improve connectivity
    more_road_rows = list(range(4, 96, 5))
    for hr in more_road_rows:
        if hr in h_road_rows:
            continue
        if not ib(0, hr):
            continue
        has_wire_nearby = False
        for dy2 in range(-2, 3):
            cr2 = hr + dy2
            if ib(0, cr2) and (wm[cr2, :] | pm[cr2, :]).any():
                has_wire_nearby = True
                break
        if has_wire_nearby:
            for x in range(2, WORLD_W - 2):
                if ib(x, hr) and em[hr, x] and not pm[hr, x] and not rm[hr, x]:
                    return (Tool.ROAD, x, hr)

    # Build proximity masks for zones
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Zone placement: prefer areas near both roads and wire/plants
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Distance to nearest plant
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in all_plants:
            d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
            min_dist = np.minimum(min_dist, d)

        # Clustering bonus
        if total_zones > 3:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                sample_step = max(1, len(zone_xs)//80)
                for i in range(0, len(zone_xs), sample_step):
                    d2 = np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])
                    zone_dist = np.minimum(zone_dist, d2)
                combined = min_dist * 0.5 + zone_dist * 0.5
            else:
                combined = min_dist
        else:
            combined = min_dist

        order = np.argsort(combined)
        step_off = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Services based on population
    if pop > 60:
        fire_spots = [(28, 45), (32, 45), (88, 45), (92, 45),
                      (28, 55), (32, 55), (88, 55), (92, 55),
                      (58, 22), (62, 22), (58, 77), (62, 77),
                      (15, 25), (15, 75), (105, 25), (105, 75),
                      (45, 15), (75, 15), (45, 85), (75, 85)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_spots = [(25, 43), (35, 43), (85, 43), (95, 43),
                        (25, 57), (35, 57), (85, 57), (95, 57),
                        (55, 20), (65, 20), (55, 80), (65, 80),
                        (10, 50), (110, 50),
                        (40, 30), (80, 30), (40, 70), (80, 70)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 450:
        for stx, sty in [(42, 32), (78, 32), (42, 68), (78, 68),
                         (20, 50), (100, 50), (60, 15), (60, 85),
                         (15, 35), (105, 35), (15, 65), (105, 65)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 300:
        park_spots = [(50, 45), (70, 45), (50, 55), (70, 55),
                      (40, 35), (80, 35), (40, 65), (80, 65),
                      (25, 50), (95, 50), (60, 30), (60, 70),
                      (35, 25), (85, 25), (35, 75), (85, 75)]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 800:
        for apx, apy in [(55, 5), (65, 5), (55, 94), (65, 94),
                         (5, 40), (5, 60), (114, 40), (114, 60)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        for spx, spy in [(5, 50), (114, 50), (60, 3), (60, 96)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend roads near existing roads with wire access
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire spines and road seeds."""
    actions = []
    # Left cluster plant at (30, 50), right cluster plant at (90, 50)
    for cx in [30, 90]:
        actions.append((Tool.COALPOWER, cx, 50))
        for dx in range(-6, 7):
            actions.append((Tool.WIRE, cx + dx, 50))
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, cx, 50 + dy))
        for dx in range(-6, 7):
            actions.append((Tool.ROAD, cx + dx, 48))
            actions.append((Tool.ROAD, cx + dx, 52))
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, cx - 2, 50 + dy))
            actions.append((Tool.ROAD, cx + 2, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # More aggressive zone mix: 45% res, 35% com, 20% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # 6-cluster layout: 2 columns x 3 rows for broad coverage
    # Pop-scaled cluster activation
    all_clusters = [
        (30, 25), (90, 25),
        (30, 50), (90, 50),
        (30, 75), (90, 75),
    ]
    # Also add mid-column clusters when pop grows
    extended_clusters = [
        (60, 15), (60, 40), (60, 65), (60, 90),
        (15, 50), (105, 50),
        (15, 25), (105, 25),
        (15, 75), (105, 75),
    ]

    def active_clusters():
        if pop < 200:
            return [(30, 50), (90, 50)]
        if pop < 600:
            return [(30, 50), (90, 50), (30, 25), (90, 25)]
        if pop < 1200:
            return all_clusters
        if pop < 2500:
            return all_clusters + [(60, 15), (60, 40), (60, 65), (60, 90)]
        return all_clusters + extended_clusters

    clusters = active_clusters()

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            for r in range(15):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- EXTEND WIRE CROSSES FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(22, 6 + pop // 25)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS WITH WIRE (horizontal) ----
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy_row in active_rows_set:
        row_cx = sorted(cx for cx, cy in clusters if abs(cy - cy_row) <= 5)
        for i in range(len(row_cx) - 1):
            c1, c2 = row_cx[i], row_cx[i + 1]
            row_wire = [bool(wm[cy_row, x] or pm[cy_row, x])
                        for x in range(c1, c2 + 1) if ib(x, cy_row)]
            if not all(row_wire):
                for x in range(c1, c2 + 1):
                    if ib(x, cy_row) and not bool(pm[cy_row, x]) and bool(em[cy_row, x]):
                        return (Tool.WIRE, x, cy_row)

    # ---- CONNECT CLUSTERS WITH WIRE (vertical) ----
    for cx_col in active_cols_set:
        col_cy = sorted(cy for cx, cy in clusters if abs(cx - cx_col) <= 5)
        for i in range(len(col_cy) - 1):
            r1, r2 = col_cy[i], col_cy[i + 1]
            col_wire = [bool(wm[y, cx_col] or pm[y, cx_col])
                        for y in range(r1, r2 + 1) if ib(cx_col, y)]
            if not all(col_wire):
                for y in range(r1, r2 + 1):
                    if ib(cx_col, y) and not bool(pm[y, cx_col]) and bool(em[y, cx_col]):
                        return (Tool.WIRE, cx_col, y)

    # ---- BUILD DENSER ROAD GRID AROUND EACH CLUSTER ----
    road_reach = min(20, 5 + pop // 40)
    for cx, cy in clusters:
        # Roads at multiple offsets from cluster center for denser coverage
        for road_offset in [-3, -1, 1, 3]:
            # Horizontal roads
            road_y = cy + road_offset
            if ib(cx, road_y):
                for dx in range(-road_reach, road_reach + 1):
                    nx4, ny4 = cx + dx, road_y
                    if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                        if not bool(rm[ny4, nx4]):
                            return (Tool.ROAD, nx4, ny4)
            # Vertical roads
            road_x = cx + road_offset
            if ib(road_x, cy):
                for dy in range(-road_reach, road_reach + 1):
                    nx4, ny4 = road_x, cy + dy
                    if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                        if not bool(rm[ny4, nx4]):
                            return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS ----
    if pop > 150:
        for cy_row in active_rows_set:
            row_cx2 = sorted(cx for cx, cy in clusters if abs(cy - cy_row) <= 12)
            for i in range(len(row_cx2) - 1):
                c1, c2 = row_cx2[i], row_cx2[i + 1]
                for road_y in [cy_row - 4, cy_row + 4]:
                    if not (0 <= road_y < WORLD_H): continue
                    row_roads = [x for x in range(c1, c2 + 1)
                                 if ib(x, road_y) and bool(rm[road_y, x])]
                    if len(row_roads) < (c2 - c1):
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) +
                 np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(12, 95, 18) for fx in range(12, 115, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px, py) for py in range(10, 95, 22) for px in range(10, 115, 24)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 8), (65, 8), (105, 8),
                         (25, 92), (65, 92), (105, 92)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(5, 15), (5, 50), (5, 85),
                      (115, 15), (115, 50), (115, 85),
                      (60, 5), (60, 95)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 90), (115, 90), (5, 10), (115, 10)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 50)):
                k = (step * 5 + i * 11) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

