                      (58, 15), (62, 15), (58, 85), (62, 85),
                      (10, 25), (10, 50), (10, 75), (110, 25), (110, 50), (110, 75),
                      (45, 10), (75, 10), (45, 90), (75, 90)]
        for fsx, fsy in fire_spots:
