                         (20, 65), (100, 65), (60, 10), (60, 90),
                         (15, 50), (105, 50)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        for apx, apy in [(55, 5), (65, 5), (55, 95), (65, 95),
                         (5, 45), (115, 45), (5, 55), (115, 55)]:
