        for px in range(5, 116, 10):
            for py in range(5, 96, 10):
                plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        found = False
        for dy in range(-8, 9):
            for dx in range(-8, 9):
                nx, ny = px+dx, py+dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            # Only place if not overwriting important stuff
            return (Tool.COALPOWER, px, py)

    # ---- Phase 2: Wire network -- ensure full map coverage ----
    # Dense wire grid every 5 tiles horizontally and vertically
    wire_step = 5 if pop > 500 else 10
