        if left > 3:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        if right < WORLD_W - 4:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left, right):
            if em[wr, x]:
                return (Tool.WIRE, x, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 4:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot):
            if em[y, wc]:
                return (Tool.WIRE, wc, y)

    # ---- Phase 3: Road network -- dense grid ----
    road_step = 4 if pop > 600 else 6
    road_rows = list(range(4, WORLD_H-4, road_step))
    road_cols = list(range(4, WORLD_W-4, road_step))

    # Build horizontal roads
    for rr in road_rows:
        # Check wire proximity
        has_wire = False
        for dy in range(-4, 5):
            nr = rr + dy
            if 0 <= nr < WORLD_H and (wm[nr, :] | pm[nr, :]).any():
                has_wire = True
                break
        if not has_wire:
            continue
        row_road = rm[rr, :]
        if not row_road.any():
            cx = 60
            if ib(cx, rr) and em[rr, cx] and not pm[rr, cx]:
                return (Tool.ROAD, cx, rr)
            # Try any empty spot in this row
            for cx2 in range(5, WORLD_W-5, 10):
                if ib(cx2, rr) and em[rr, cx2] and not pm[rr, cx2]:
                    return (Tool.ROAD, cx2, rr)
        else:
            indices = np.where(row_road)[0]
            left = int(indices[0])
            right = int(indices[-1])
            if left > 4 and em[rr, left-1] and not pm[rr, left-1]:
                return (Tool.ROAD, left-1, rr)
            if right < WORLD_W-5 and em[rr, right+1] and not pm[rr, right+1]:
                return (Tool.ROAD, right+1, rr)
            # Fill gaps
            for x in range(left, right):
                if em[rr, x] and not pm[rr, x]:
                    return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        has_wire = False
        for dx in range(-4, 5):
            nc = rc + dx
            if 0 <= nc < WORLD_W and (wm[:, nc] | pm[:, nc]).any():
                has_wire = True
                break
        if not has_wire:
            continue
        col_road = rm[:, rc]
        if not col_road.any():
            cy = 50
            if ib(rc, cy) and em[cy, rc] and not pm[cy, rc]:
                return (Tool.ROAD, rc, cy)
            for cy2 in range(5, WORLD_H-5, 10):
                if ib(rc, cy2) and em[cy2, rc] and not pm[cy2, rc]:
                    return (Tool.ROAD, rc, cy2)
        else:
            indices = np.where(col_road)[0]
            top = int(indices[0])
            bot = int(indices[-1])
            if top > 4 and em[top-1, rc] and not pm[top-1, rc]:
                return (Tool.ROAD, rc, top-1)
            if bot < WORLD_H-5 and em[bot+1, rc] and not pm[bot+1, rc]:
                return (Tool.ROAD, rc, bot+1)
            for y in range(top, bot):
                if em[y, rc] and not pm[y, rc]:
                    return (Tool.ROAD, rc, y)

    # ---- Phase 4: Zone placement ----
    # Compute road and wire proximity (vectorized)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: cluster near existing zones, spread across map
        zone_score = np.zeros(len(cxs_arr))

        # Spread bonus: prefer less-dense areas
        # Divide map into 4x4 grid, prefer cells with fewer zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d2)
                # Mild clustering: not too far, not too close
                zone_score = np.abs(zone_dist - 8.0)
            else:
                # Spread from center
                zone_score = np.abs(cxs_arr - 60).astype(float) + np.abs(cys_arr - 50).astype(float)
        else:
            # Start near center
            zone_score = np.abs(cxs_arr - 60).astype(float) + np.abs(cys_arr - 50).astype(float)

        order = np.argsort(zone_score)
        off = (step * 3 + pop * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # ---- Phase 5: Civic services scattered across map ----
    # Fire stations: dense grid
    if pop > 50:
        fire_grid = [(x, y) for x in range(15, 110, 20) for y in range(15, 90, 20)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_grid = [(x, y) for x in range(25, 105, 25) for y in range(20, 85, 25)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_grid = [(x, y) for x in range(12, 108, 15) for y in range(12, 88, 15)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 600:
        for stx, sty in [(40, 35), (80, 35), (40, 65), (80, 65),
                          (20, 50), (100, 50), (60, 15), (60, 85),
                          (15, 25), (105, 25), (15, 75), (105, 75)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        for apx, apy in [(10, 8), (110, 8), (10, 92), (110, 92),
                          (55, 5), (65, 5), (55, 95), (65, 95)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        for spx, spy in [(5, 48), (115, 48), (5, 52), (115, 52),
                          (58, 2), (62, 2), (58, 97), (62, 97)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: wire near plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 30)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: road near wire ----
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 60)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0,2),(0,-2),(2,0),(-2,0),(0,1),(0,-1),(1,0),(-1,0)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place 4 coal plants with wire spines and flanking roads."""
    actions = []
    # Four power plants spread across the map
    plants = [(15, 50), (45, 50), (75, 50), (105, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire spines from each plant (vertical)
    for px, py in plants:
        for dy in range(-12, 13):
            actions.append((Tool.WIRE, px, py + dy))
    # Flanking roads on both sides of each wire spine
    for px, py in plants:
        for dy in range(-12, 13):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- BUILD PROXIMITY MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ACTIVE WIRE COLUMNS: dense grid across the map ----
    # 8 columns at x = 10, 25, 40, 55, 70, 85, 100, 115
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    # Plant rows at 3 vertical positions
    plant_rows = [18, 50, 82]

    def num_active_cols():
        if pop < 30:
            return 2
        elif pop < 100:
            return 3
        elif pop < 300:
            return 4
        elif pop < 600:
            return 5
        elif pop < 1000:
            return 6
        elif pop < 2000:
            return 7
        else:
            return 8

    n_cols = num_active_cols()
    active_cols = wire_cols[:n_cols]

    n_plant_rows = max(1, min(3, 1 + pop // 200))
    active_plant_rows = plant_rows[:n_plant_rows]

    # ---- ENSURE POWER PLANTS exist in active columns ----
    for wc in active_cols:
        for pr in active_plant_rows:
            has_plant = False
            for dx in range(-8, 9):
                for dy in range(-8, 9):
                    nx, ny = wc + dx, pr + dy
                    if ib(nx, ny) and bool(pm[ny, nx]):
                        has_plant = True
                        break
                if has_plant:
                    break
            if not has_plant:
                # Try to place a coal plant near (wc, pr)
                for r in range(0, 12):
                    placed = False
                    for dy2 in range(-r, r + 1):
                        for dx2 in range(-r, r + 1):
                            if r > 0 and abs(dx2) != r and abs(dy2) != r:
                                continue
                            nx, ny = wc + dx2, pr + dy2
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # ---- EXTEND WIRE SPINES (vertical) from plants ----
    spine_half = min(45, 12 + pop // 15)
    for wc in active_cols:
        wire_in_col = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not wire_in_col:
            for pr in active_plant_rows:
                for dy2 in range(-10, 11):
                    ny = pr + dy2
                    if ib(wc, ny) and (bool(em[ny, wc]) or bool(wm[ny, wc])) and not bool(pm[ny, wc]):
                        return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            # Target: extend from top plant row up and bottom plant row down
            target_top = max(2, min(active_plant_rows) - spine_half)
            target_bot = min(WORLD_H - 3, max(active_plant_rows) + spine_half)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- EXTEND ROADS flanking wire spines ----
    road_half = min(45, 10 + pop // 20)
    for idx, wc in enumerate(active_cols):
        rl, rr = wc - 1, wc + 1
        wire_in_col = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not wire_in_col:
            continue
        target_top = max(2, 50 - road_half)
        target_bot = min(WORLD_H - 3, 50 + road_half)
        cycle = (step + idx * 5) % 5
        for wr in wire_in_col[cycle::5]:
            if wr < target_top or wr > target_bot:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL WIRE CONNECTIONS between columns (at multiple y-levels) ----
    horiz_wire_ys = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    for i in range(len(active_cols) - 1):
        c1 = active_cols[i]
        c2 = active_cols[i + 1]
        for conn_y in horiz_wire_ys:
            connected = all(
                not ib(cx, conn_y) or bool(wm[conn_y, cx]) or bool(pm[conn_y, cx]) or bool(rm[conn_y, cx])
                for cx in range(c1, c2 + 1)
            )
            if not connected:
                for cx in range(c1, c2 + 1):
                    if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                        return (Tool.WIRE, cx, conn_y)

    # ---- HORIZONTAL ROADS between columns ----
    if pop > 50:
        horiz_road_ys = [8, 18, 28, 38, 48, 58, 68, 78, 88, 95]
        for conn_y in horiz_road_ys:
            road_in_row = [c for c in range(WORLD_W) if ib(c, conn_y) and bool(rm[conn_y, c])]
            # Build horizontal roads connecting active columns
            for i in range(len(active_cols) - 1):
                c1 = active_cols[i]
                c2 = active_cols[i + 1]
                road_left = c1 - 1
                road_right = c2 + 1
                # Check if road already spans c1-1 to c2+1
                span_complete = all(
                    ib(cx, conn_y) and bool(rm[conn_y, cx])
                    for cx in range(road_left, road_right + 1)
                )
                if not span_complete:
                    for cx in range(road_left, road_right + 1):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)

    # ---- ZONE PLACEMENT: zones near road+wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active wire columns
        best_dist = np.full(len(cxs), 999999.0)
        for wc in active_cols:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - 50).astype(float) * 0.2
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- EXTEND ROADS from existing road ends near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx2, ry + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES: fire stations ----
    if pop > 80:
        fire_grid = [(x, y) for x in range(15, WORLD_W, 25) for y in range(15, WORLD_H, 25)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    # ---- CIVIC SERVICES: police stations ----
    if pop > 300:
        police_grid = [(x, y) for x in range(20, WORLD_W, 30) for y in range(20, WORLD_H, 30)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # ---- STADIUMS ----
    if pop > 800:
        stadium_spots = [
            (30, 8), (70, 8), (110, 8),
            (30, 92), (70, 92), (110, 92),
            (5, 35), (5, 65),
            (60, 35), (60, 65),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- NUCLEAR PLANTS for extra power ----
    if pop > 1500:
        nuke_spots = [
            (30, 5), (80, 5), (30, 95), (80, 95),
            (5, 20), (5, 50), (5, 80),
            (115, 20), (115, 50), (115, 80),
        ]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    # ---- AIRPORTS ----
    if pop > 3000:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 95)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- SEAPORTS ----
    if pop > 5000:
        for sp in [(5, 92), (115, 92), (60, 95), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys, zone_xs = np.where(zone_map)
        if len(zone_xs) > 0:
            for i in range(min(len(zone_xs), 30)):
                k = (step * 3 + i * 17) % len(zone_xs)
                zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

