    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 anchors: 3 columns x 3 rows covering the map
    # Each anchor: (plant_x, plant_y, wire_col, road_l, road_r)
    all_anchors = [
        (20, 25, 20, 19, 21),
        (60, 25, 60, 59, 61),
        (100, 25, 100, 99, 101),
        (20, 50, 20, 19, 21),
        (60, 50, 60, 59, 61),
        (100, 50, 100, 99, 101),
        (20, 75, 20, 19, 21),
        (60, 75, 60, 59, 61),
        (100, 75, 100, 99, 101),
    ]

    def num_active():
        if pop < 80:    return 3
        if pop < 200:   return 4
        if pop < 400:   return 5
        if pop < 700:   return 6
        if pop < 1000:  return 7
        if pop < 1500:  return 8
        return 9

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            # Try exact spot first
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Search nearby
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) per anchor ----
    spine_half = min(30, 10 + pop // 10)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            max_wr = max(wire_in_col)
            min_wr = min(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            wc1 = row_anchors[i][2]
            wc2 = row_anchors[i + 1][2]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows ----
    wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
    for wc in wc_cols:
        col_anchors = sorted(
            [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
            key=lambda a: a[1]
        )
        for i in range(len(col_anchors) - 1):
            py1 = col_anchors[i][1]
            py2 = col_anchors[i + 1][1]
            for cy in range(py1 + 1, py2):
                if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                    return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at y-levels ----
    if pop > 20:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            for horiz_y in [yl - 4, yl + 4]:
                if not (ib(rl1, horiz_y) and ib(rr_last, horiz_y)):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- CROSS-ROADS connecting y rows ----
    if pop > 60 and len(y_levels) >= 2:
        for col_x in [20, 60, 100]:
            for rx in [col_x - 4, col_x + 4]:
                if not ib(rx, 0):
                    continue
                for i in range(len(y_levels) - 1):
                    y1 = y_levels[i]
                    y2 = y_levels[i + 1]
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (8, 25), (35, 25), (75, 25), (112, 25),
            (8, 50), (35, 50), (85, 50), (112, 50),
            (8, 75), (35, 75), (85, 75), (112, 75),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (45, 15), (85, 15), (10, 38), (110, 38),
            (45, 38), (85, 38), (10, 62), (110, 62),
            (45, 62), (85, 62), (45, 85), (85, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadium_spots = [
            (10, 10), (60, 10), (110, 10),
            (10, 50), (110, 50),
            (10, 90), (60, 90), (110, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [
            (40, 12), (80, 12), (40, 87), (80, 87),
            (5, 35), (115, 35), (5, 65), (115, 65),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55, 6), (55, 93), (6, 50), (113, 50)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants at key positions with wire+road seeds."""
    actions = []
    # Three power plants: left, center, right
    for px, py in [(20, 50), (60, 50), (100, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from each plant
        for d in range(-6, 7):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px, py + d))
        # Flanking roads
        for d in range(-5, 6):
            actions.append((Tool.ROAD, px - 2, py + d))
            actions.append((Tool.ROAD, px + 2, py + d))
            actions.append((Tool.ROAD, px + d, py - 2))
            actions.append((Tool.ROAD, px + d, py + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- CLUSTER GRID: 5 columns x 4 rows covering most of 120x100 ----
    # Scale active clusters with population
    all_cluster_cols = [12, 32, 60, 88, 108]
    all_cluster_rows = [15, 38, 62, 85]

    def active_clusters():
        if pop < 80:
            return [(60, 50)]
        if pop < 300:
            return [(32, 50), (60, 50), (88, 50)]
        if pop < 700:
            return [(12, 50), (32, 38), (60, 50), (88, 38), (108, 50)]
        if pop < 1500:
            return [(cx, cy) for cy in [38, 62]
                    for cx in [12, 32, 60, 88, 108]]
        if pop < 3000:
            return [(cx, cy) for cy in [15, 50, 85]
                    for cx in [12, 32, 60, 88, 108]]
        # Full grid
        return [(cx, cy) for cy in all_cluster_rows for cx in all_cluster_cols]

    clusters = active_clusters()

    # ---- 1. ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            for r in range(16):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- 2. EXTEND WIRE CROSSES FROM PLANTS ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(22, 6 + pop // 25)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Horizontal wire
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            # Vertical wire
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- 3. CONNECT CLUSTERS WITH WIRE (horizontal + vertical) ----
    active_cols_set = sorted(set(cx for cx, cy in clusters))
    active_rows_set = sorted(set(cy for cx, cy in clusters))

    # Horizontal: connect adjacent columns at each active row
    for cy in active_rows_set:
        row_cls = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 14])
        for i in range(len(row_cls) - 1):
            c1, c2 = row_cls[i], row_cls[i + 1]
            # Check connection
            gap_filled = all(
                bool(wm[cy, x]) or bool(pm[cy, x])
                for x in range(c1, c2 + 1) if ib(x, cy)
            )
            if not gap_filled:
                for x in range(c1, c2 + 1):
                    if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]):
                        return (Tool.WIRE, x, cy)

    # Vertical: connect adjacent rows at each active column
    for cx in active_cols_set:
        for i in range(len(active_rows_set) - 1):
            r1, r2 = active_rows_set[i], active_rows_set[i + 1]
            gap_filled = all(
                bool(wm[y, cx]) or bool(pm[y, cx])
                for y in range(r1, r2 + 1) if ib(cx, y)
            )
            if not gap_filled:
                for y in range(r1, r2 + 1):
                    if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]):
                        return (Tool.WIRE, cx, y)

    # ---- 4. BUILD ROAD GRID AROUND EACH CLUSTER ----
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        for road_y in [cy - 2, cy + 2]:
            if not ib(cx, road_y): continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)
        for road_x in [cx - 2, cx + 2]:
            if not ib(road_x, cy): continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)

    # ---- 5. INTER-CLUSTER ROADS ----
    if pop > 150:
        for cy in active_rows_set:
            row_cls2 = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 14])
            for i in range(len(row_cls2) - 1):
                c1, c2 = row_cls2[i], row_cls2[i + 1]
                for road_y in [cy - 3, cy + 3]:
                    if not (0 <= road_y < WORLD_H): continue
                    row_roads = [x for x in range(c1, c2 + 1) if ib(x, road_y) and bool(rm[road_y, x])]
                    if not row_roads:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)
        # Vertical inter-cluster roads
        for cx in active_cols_set:
            for i in range(len(active_rows_set) - 1):
                r1, r2 = active_rows_set[i], active_rows_set[i + 1]
                for road_x in [cx - 3, cx + 3]:
                    if not (0 <= road_x < WORLD_W): continue
                    col_roads = [y for y in range(r1, r2 + 1) if ib(road_x, y) and bool(rm[y, road_x])]
                    if not col_roads:
                        for y in range(r1, r2 + 1):
                            if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]):
                                return (Tool.ROAD, road_x, y)

    # ---- 6. ZONE PLACEMENT (reactive: find powered+roaded empty tiles) ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- 7. CIVIC SERVICES ----
    if pop > 60:
        for fy in range(10, 95, 18):
            for fx in range(8, 115, 20):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for py in range(12, 90, 20):
            for px in range(10, 115, 22):
                if ib(px, py) and bool(em[py, px]):
                    return (Tool.POLICESTATION, px, py)

    if pop > 600:
        for sx, sy in [(25, 6), (60, 6), (95, 6), (25, 93), (60, 93), (95, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [(5, 15), (5, 50), (5, 85),
                      (115, 15), (115, 50), (115, 85),
                      (40, 3), (80, 3), (40, 96), (80, 96)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for ax, ay in [(60, 4), (4, 50), (115, 50), (60, 95)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sx2, sy2 in [(4, 90), (115, 90), (4, 10), (115, 10)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- 8. PARKS near zones ----
    if pop > 120:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 40)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- 9. FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- 10. FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

