def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% RES, 25% COM, 25% IND
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dynamic plants based on population
    base_plants = [(30, 30), (90, 30), (30, 70), (90, 70), (60, 50)]
    extra_plants = []
    if pop > 200:
        extra_plants += [(60, 15), (60, 85), (10, 50), (110, 50)]
    if pop > 600:
        extra_plants += [(10, 15), (110, 15), (10, 85), (110, 85)]
    if pop > 1200:
        extra_plants += [(30, 5), (90, 5), (30, 95), (90, 95)]
        extra_plants += [(5, 30), (115, 30), (5, 70), (115, 70)]
    if pop > 2000:
        extra_plants += [(45, 25), (75, 25), (45, 75), (75, 75)]
        extra_plants += [(20, 50), (100, 50)]
    if pop > 3000:
        extra_plants += [(60, 35), (60, 65), (20, 20), (100, 20), (20, 80), (100, 80)]

    all_plants = base_plants + extra_plants

    # Ensure plants exist
    for px, py in all_plants:
        found = any(
            ib(px+dx, py+dy) and pm[py+dy, px+dx]
            for dy in range(-4, 5) for dx in range(-4, 5)
        )
        if not found and ib(px, py):
            return (Tool.COALPOWER, px, py)

    # Build horizontal wire spines at key rows
    wire_rows = [30, 50, 70]
    if pop > 300:
        wire_rows += [20, 80]
    if pop > 700:
        wire_rows += [10, 90]
    if pop > 1500:
        wire_rows += [5, 95, 40, 60]

    for wr in wire_rows:
        if not ib(0, wr):
            continue
        for x in range(1, WORLD_W - 1):
            if em[wr, x] and not pm[wr, x] and not wm[wr, x]:
                left_ok = ib(x-1, wr) and (wm[wr, x-1] or pm[wr, x-1])
                right_ok = ib(x+1, wr) and (wm[wr, x+1] or pm[wr, x+1])
                if left_ok or right_ok:
                    return (Tool.WIRE, x, wr)

    # Build vertical wire spines at key columns
    wire_cols = [30, 60, 90]
    if pop > 300:
        wire_cols += [15, 45, 75, 105]
    if pop > 700:
        wire_cols += [5, 20, 100, 115]
    if pop > 1500:
        wire_cols += [35, 55, 65, 85]

    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        for y in range(1, WORLD_H - 1):
            if em[y, wc] and not pm[y, wc] and not wm[y, wc]:
                above_ok = ib(wc, y-1) and (wm[y-1, wc] or pm[y-1, wc])
                below_ok = ib(wc, y+1) and (wm[y+1, wc] or pm[y+1, wc])
                if above_ok or below_ok:
                    return (Tool.WIRE, wc, y)

    # Build road network: horizontal roads
    h_roads = [20, 40, 60, 80]
    if pop > 200:
        h_roads += [10, 90, 30, 70]
    if pop > 600:
        h_roads += [5, 95, 25, 50, 75]
    if pop > 1200:
        h_roads += [15, 35, 45, 55, 65, 85]
    if pop > 2000:
        h_roads += list(range(3, 98, 5))

    for hr in h_roads:
        if not ib(0, hr):
            continue
        for x in range(2, WORLD_W - 2):
            if ib(x, hr) and em[hr, x] and not pm[hr, x] and not rm[hr, x]:
                return (Tool.ROAD, x, hr)

    # Build road network: vertical roads
    v_roads = [20, 45, 75, 100]
    if pop > 200:
        v_roads += [10, 35, 55, 65, 85, 110]
    if pop > 600:
        v_roads += [5, 25, 60, 95, 115]
    if pop > 1200:
        v_roads += list(range(5, 115, 8))

    for vr in v_roads:
        if not ib(vr, 0):
            continue
        for y in range(2, WORLD_H - 2):
            if ib(vr, y) and em[y, vr] and not pm[y, vr] and not rm[y, vr]:
                return (Tool.ROAD, vr, y)

    # Proximity masks for zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Place zones: prefer near existing zones AND near roads/wires
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Distance to nearest plant
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in all_plants:
            d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
            min_dist = np.minimum(min_dist, d)

        # Cluster near existing zones
        if total_zones > 3:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                sample_step = max(1, len(zone_xs) // 80)
                for i in range(0, len(zone_xs), sample_step):
                    d2 = np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])
                    zone_dist = np.minimum(zone_dist, d2)
                combined = min_dist * 0.4 + zone_dist * 0.6
            else:
                combined = min_dist
        else:
            combined = min_dist

        order = np.argsort(combined)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services - fire stations
    if pop > 50:
        fire_spots = [
            (22, 22), (38, 22), (58, 22), (78, 22), (98, 22),
            (22, 42), (38, 42), (58, 42), (78, 42), (98, 42),
            (22, 62), (38, 62), (58, 62), (78, 62), (98, 62),
            (22, 82), (38, 82), (58, 82), (78, 82), (98, 82),
        ]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [
            (25, 25), (50, 25), (75, 25), (100, 25),
            (25, 50), (50, 50), (75, 50), (100, 50),
            (25, 75), (50, 75), (75, 75), (100, 75),
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        stadium_spots = [
            (40, 35), (80, 35), (40, 65), (80, 65),
            (20, 50), (100, 50), (60, 18), (60, 82),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        for apx, apy in [(55, 6), (55, 93), (8, 40), (112, 60), (8, 60), (112, 40)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        for spx, spy in [(6, 50), (114, 50), (60, 4), (60, 96), (25, 10), (95, 10)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 300:
        park_spots = [
            (32, 32), (62, 32), (88, 32),
            (32, 50), (62, 50), (88, 50),
            (32, 68), (62, 68), (88, 68),
        ]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    # Fallback: extend roads near existing roads with wire access
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

