    for y in [25, 50, 75]:
        for x in range(27, 93):
            actions.append((Tool.WIRE, x, y))
    # Vertical wire spines at x=25, x=60, x=95
    for x in [25, 60, 95]:
        for y in range(27, 73):
            actions.append((Tool.WIRE, x, y))
    # Seed roads along main corridors
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 20))
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 60))
        actions.append((Tool.ROAD, x, 80))
