def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 50% residential, 25% commercial, 25% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dynamic plant placement based on population
    base_plants = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50)]
    extra_plants = []
    if pop > 200:
        extra_plants += [(60, 20), (60, 80), (10, 50), (110, 50)]
    if pop > 600:
        extra_plants += [(40, 10), (80, 10), (40, 90), (80, 90)]
    if pop > 1200:
        extra_plants += [(10, 20), (110, 20), (10, 80), (110, 80)]
    if pop > 2000:
        extra_plants += [(25, 50), (95, 50), (60, 30), (60, 70)]
    if pop > 3000:
        extra_plants += [(5, 10), (115, 10), (5, 90), (115, 90)]
        extra_plants += [(45, 5), (75, 5), (45, 95), (75, 95)]

    all_plants = base_plants + extra_plants

    # Ensure plants exist
    for px, py in all_plants:
        found = any(
            ib(px+dx, py+dy) and pm[py+dy, px+dx]
            for dy in range(-4, 5) for dx in range(-4, 5)
        )
        if not found and ib(px, py):
            return (Tool.COALPOWER, px, py)

    # Wire grid: horizontal spines at multiple rows
    wire_rows = [10, 20, 25, 30, 40, 50, 60, 70, 75, 80, 90]
    if pop > 400:
        wire_rows += [15, 35, 45, 55, 65, 85]
    if pop > 1000:
        wire_rows += [5, 95]

    for cr in wire_rows:
        if not ib(0, cr):
            continue
        for x in range(1, WORLD_W - 1):
            if em[cr, x] and not pm[cr, x] and not wm[cr, x] and not rm[cr, x]:
                left_has = ib(x-1, cr) and (wm[cr, x-1] or pm[cr, x-1])
                right_has = ib(x+1, cr) and (wm[cr, x+1] or pm[cr, x+1])
                if left_has or right_has:
                    return (Tool.WIRE, x, cr)

    # Wire grid: vertical spines at multiple columns
    wire_cols = [10, 20, 25, 35, 45, 60, 75, 85, 95, 100, 110]
    if pop > 400:
        wire_cols += [15, 30, 40, 55, 65, 80, 90, 105]
    if pop > 1000:
        wire_cols += [5, 115]

    for cc in wire_cols:
        if not ib(cc, 0):
            continue
        for y in range(1, WORLD_H - 1):
            if em[y, cc] and not pm[y, cc] and not wm[y, cc] and not rm[y, cc]:
                above = ib(cc, y-1) and (wm[y-1, cc] or pm[y-1, cc])
                below = ib(cc, y+1) and (wm[y+1, cc] or pm[y+1, cc])
                if above or below:
                    return (Tool.WIRE, cc, y)

    # Road network: grid at regular intervals
    road_rows = [19, 21, 39, 41, 59, 61, 79, 81]
    if pop > 300:
        road_rows += [9, 11, 29, 31, 49, 51, 69, 71, 89, 91]
    if pop > 800:
        road_rows += [14, 16, 24, 26, 34, 36, 44, 46, 54, 56, 64, 66, 74, 76, 84, 86]

    for hr in road_rows:
        if not ib(0, hr):
            continue
        # Check if wire is nearby (above or below)
        wire_near = False
        for dy in range(-3, 4):
            ny = hr + dy
            if ib(0, ny) and (wm[ny, :] | pm[ny, :]).any():
                wire_near = True
                break
        if wire_near:
            for x in range(2, WORLD_W - 2):
                if ib(x, hr) and bool(em[hr, x]) and not pm[hr, x] and not rm[hr, x]:
                    return (Tool.ROAD, x, hr)

    road_cols = [19, 21, 44, 46, 74, 76, 99, 101]
    if pop > 300:
        road_cols += [9, 11, 34, 36, 59, 61, 84, 86, 109, 111]
    if pop > 800:
        road_cols += [4, 6, 14, 16, 24, 26, 29, 31, 39, 41, 49, 51, 54, 56, 64, 66, 69, 71, 79, 81, 89, 91, 94, 96, 104, 106, 114, 116]

    for vc in road_cols:
        if not ib(vc, 0):
            continue
        wire_near = False
        for dx in range(-3, 4):
            nx = vc + dx
            if ib(nx, 0) and (wm[:, nx] | pm[:, nx]).any():
                wire_near = True
                break
        if wire_near:
            for y in range(2, WORLD_H - 2):
                if ib(vc, y) and bool(em[y, vc]) and not pm[y, vc] and not rm[y, vc]:
                    return (Tool.ROAD, vc, y)

    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Place zones in good locations
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Distance to nearest plant
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in all_plants:
            d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
            min_dist = np.minimum(min_dist, d)

        # Also cluster near existing zones
        if total_zones > 3:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                for i in range(0, len(zone_xs), max(1, len(zone_xs)//80)):
                    d2 = np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])
                    zone_dist = np.minimum(zone_dist, d2)
                combined = min_dist * 0.5 + zone_dist * 0.5
            else:
                combined = min_dist
        else:
            combined = min_dist

        order = np.argsort(combined)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services based on population - place strategically across the grid
    if pop > 50:
        fire_spots = [
            (22, 22), (48, 22), (72, 22), (98, 22),
            (22, 48), (48, 48), (72, 48), (98, 48),
            (22, 72), (48, 72), (72, 72), (98, 72),
        ]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [
            (35, 15), (65, 15), (35, 35), (65, 35),
            (35, 55), (65, 55), (35, 85), (65, 85),
            (15, 50), (105, 50), (10, 30), (110, 30),
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        stadium_spots = [
            (40, 30), (80, 30), (40, 70), (80, 70),
            (20, 50), (100, 50), (60, 15), (60, 85),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        # Nuclear power for more coverage
        nuke_spots = [(15, 15), (105, 15), (15, 85), (105, 85), (60, 5), (60, 95)]
        for npx, npy in nuke_spots:
            if ib(npx, npy):
                near_plant = any(
                    ib(npx+dx, npy+dy) and pm[npy+dy, npx+dx]
                    for dy in range(-5, 6) for dx in range(-5, 6)
                )
                if not near_plant:
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1000:
        airport_spots = [(55, 7), (55, 93), (8, 45), (112, 45), (8, 55), (112, 55)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [(7, 50), (113, 50), (60, 4), (60, 96)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Parks to improve land value
    if pop > 300:
        park_spots = [
            (50, 45), (70, 45), (50, 55), (70, 55),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (60, 35), (60, 65), (40, 50), (80, 50),
        ]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    # Fallback: extend roads near existing roads with wire access
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not pm[ny2, nx2] and nbr_wire[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not pm[ny3, nx3]:
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place two coal plants with wire connections and initial roads."""
    actions = []
    # Primary plant at (58, 50)
    actions.append((Tool.COALPOWER, 58, 50))
    # Wire spine from plant upward and downward
    for y in range(45, 55):
        actions.append((Tool.WIRE, 60, y))
    # Secondary plant
    actions.append((Tool.COALPOWER, 80, 50))
    for y in range(45, 55):
        actions.append((Tool.WIRE, 82, y))
    # Horizontal wire bridge between plants
    for x in range(61, 81):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    # ---- Phase state ----
    if 'phase' not in state:
        state['phase'] = 0
        state['plant_count'] = 0
        state['cluster_idx'] = 0

    # ---- Ensure we have power plants ----
    plant_ys, plant_xs = np.where(pm)
    num_plants = len(plant_xs) // 9 if len(plant_xs) > 0 else 0  # rough count

    # Define cluster centers spread across the map
    clusters = [
        (60, 50), (90, 50), (30, 50),
        (60, 25), (60, 75), (90, 25),
        (90, 75), (30, 25), (30, 75),
    ]

    # For each cluster, power plant is offset by (-4, 0) from center
    def plant_pos(cx, cy):
        return (cx - 6, cy)

    # ---- Build power infrastructure first ----
    # Check which cluster plants exist
    for i, (cx, cy) in enumerate(clusters):
        ppx, ppy = plant_pos(cx, cy)
        if not in_bounds(ppx, ppy):
            continue
        # Check if plant exists in 5x5 neighborhood
        has_plant = False
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = ppx + dx, ppy + dy
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Place plant if we have enough pop or it's one of the first few
            threshold = i * 150
            if pop >= threshold or i < 2:
                if in_bounds(ppx, ppy) and (bool(em[ppy, ppx]) or True):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- Build wire network ----
    # Each cluster has a vertical wire spine at cx+2
    # Connect clusters with horizontal wires at y=50

    # First, ensure vertical spines exist for active clusters
    active_clusters = []
    for i, (cx, cy) in enumerate(clusters):
        threshold = max(0, (i - 1) * 150)
        if pop >= threshold or i < 3:
            active_clusters.append((i, cx, cy))

    # Build vertical wire spines
    for i, cx, cy in active_clusters:
        wire_col = cx  # wire spine at cluster center x
        # Spine extends cy-12 to cy+12
        spine_top = max(2, cy - 12)
        spine_bot = min(WORLD_H - 3, cy + 12)

        # Check if spine is built
        spine_wires = [(r, wire_col) for r in range(spine_top, spine_bot + 1)
                       if in_bounds(wire_col, r) and bool(wm[r, wire_col])]

        if len(spine_wires) < (spine_bot - spine_top):
            # Find gaps in spine
            for r in range(spine_top, spine_bot + 1):
                if in_bounds(wire_col, r) and not bool(wm[r, wire_col]) and not bool(pm[r, wire_col]):
                    return (Tool.WIRE, wire_col, r)

    # Horizontal wire connections between clusters at their y level
    # Connect first cluster to all others
    if len(active_clusters) >= 2:
        for i in range(len(active_clusters) - 1):
            _, cx1, cy1 = active_clusters[i]
            _, cx2, cy2 = active_clusters[i + 1]
            # Connect at midpoint y (cy of first cluster spine)
            bridge_y = cy1
            # Check if we need to extend wire horizontally
            x_start = min(cx1, cx2)
            x_end = max(cx1, cx2)
            for bx in range(x_start, x_end + 1):
                if in_bounds(bx, bridge_y) and not bool(wm[bridge_y, bx]) and not bool(pm[bridge_y, bx]):
                    return (Tool.WIRE, bx, bridge_y)

    # ---- Build road infrastructure ----
    # For each active cluster, build road columns flanking the wire spine
    for i, cx, cy in active_clusters:
        wire_col = cx
        road_l = wire_col - 2
        road_r = wire_col + 2
        spine_top = max(2, cy - 12)
        spine_bot = min(WORLD_H - 3, cy + 12)

        # Check road columns
        for road_col in [road_l, road_r]:
            if not in_bounds(road_col, cy):
                continue
            road_in_col = [r for r in range(spine_top, spine_bot + 1)
                           if in_bounds(road_col, r) and bool(rm[r, road_col])]
            # Need roads along the spine range
            for r in range(spine_top, spine_bot + 1):
                if in_bounds(road_col, r) and bool(em[r, road_col]) and not bool(pm[r, road_col]):
                    return (Tool.ROAD, road_col, r)

    # Also add horizontal roads at cluster center and edges to connect neighborhoods
    for i, cx, cy in active_clusters:
        for road_y in [cy - 13, cy + 13]:
            if not in_bounds(cx, road_y):
                continue
            road_l = cx - 2
            road_r = cx + 2
            for road_x in range(road_l, road_r + 1):
                if in_bounds(road_x, road_y) and bool(em[road_y, road_x]) and not bool(pm[road_y, road_x]):
                    return (Tool.ROAD, road_x, road_y)

    # ---- Compute proximity masks ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- Place zones near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active cluster centers
        best_score = np.full(len(cxs), 999999.0)
        for i, cx, cy in active_clusters:
            d = np.abs(cxs - cx) + np.abs(cys - cy)
            best_score = np.minimum(best_score, d)

        order = np.argsort(best_score)
        step_off = int(step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # ---- Services ----
    if pop > 300:
        for ci, (cx, cy) in enumerate(clusters[:3]):
            for fpos in [(cx - 8, cy - 8), (cx + 8, cy - 8), (cx - 8, cy + 8), (cx + 8, cy + 8)]:
                fsx, fsy = fpos
                if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 600:
        for ci, (cx, cy) in enumerate(clusters[:3]):
            for ppos in [(cx - 8, cy), (cx + 8, cy)]:
                psx, psy = ppos
                if in_bounds(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 1000:
        # Stadiums
        for ci, (cx, cy) in enumerate(clusters[:2]):
            sx, sy = cx + 12, cy - 12
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- Extend roads from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Extend wires laterally ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

