def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Cluster definitions: (center_x, center_y) ----
    # We spread clusters across the entire 120x100 map
    clusters = [
        (60, 50),  # center
        (85, 50),  # right
        (35, 50),  # left
        (60, 25),  # top center
        (60, 75),  # bottom center
        (85, 25),  # top right
        (85, 75),  # bottom right
        (35, 25),  # top left
        (35, 75),  # bottom left
        (110, 50), # far right
        (12, 50),  # far left
        (110, 25), # far top right
        (110, 75), # far bottom right
        (12, 25),  # far top left
        (12, 75),  # far bottom left
    ]

    # Plant for each cluster is placed at (cx-8, cy)
    def plant_pos(cx, cy):
        px = cx - 8
        py = cy
        return (max(2, min(WORLD_W - 3, px)), max(2, min(WORLD_H - 3, py)))

    # How many clusters are active based on population
    def num_active_clusters():
        if pop < 100:
            return 2
        elif pop < 300:
            return 3
        elif pop < 600:
            return 5
        elif pop < 1000:
            return 7
        elif pop < 2000:
            return 10
        else:
            return len(clusters)

    n_active = num_active_clusters()
    active_clusters = clusters[:n_active]

    # ---- 1. Ensure power plants for active clusters ----
    for i, (cx, cy) in enumerate(active_clusters):
        ppx, ppy = plant_pos(cx, cy)
        # Check if a plant exists nearby (within 4 tiles)
        has_plant = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = ppx + dx, ppy + dy
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if in_bounds(ppx, ppy):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- 2. Wire spines for active clusters ----
    for i, (cx, cy) in enumerate(active_clusters):
        ppx, ppy = plant_pos(cx, cy)
        # Wire spine runs vertically at cx (cluster center x)
        wire_x = cx
        spine_top = max(2, cy - 13)
        spine_bot = min(WORLD_H - 3, cy + 13)
        for r in range(spine_top, spine_bot + 1):
            if in_bounds(wire_x, r) and not bool(wm[r, wire_x]) and not bool(pm[r, wire_x]):
                return (Tool.WIRE, wire_x, r)

    # ---- 3. Connect plant to wire spine with horizontal wire ----
    for i, (cx, cy) in enumerate(active_clusters):
        ppx, ppy = plant_pos(cx, cy)
        wire_x = cx
        # Connect from plant right edge to wire spine at cy
        x_start = ppx + 2  # right side of plant (plant is 3x3, center at ppx)
        x_end = wire_x
        if x_start < x_end:
            for bx in range(x_start, x_end + 1):
                if in_bounds(bx, ppy) and not bool(wm[ppy, bx]) and not bool(pm[ppy, bx]):
                    return (Tool.WIRE, bx, ppy)

    # ---- 4. Horizontal wire bridge between adjacent clusters ----
    # Connect cluster wire spines at their y level
    for i in range(len(active_clusters) - 1):
        cx1, cy1 = active_clusters[i]
        cx2, cy2 = active_clusters[i + 1]
        # Connect at the y of the higher cluster's center
        # Choose a bridge y that is within both clusters' spine ranges
        bridge_y = cy1
        x_start = min(cx1, cx2)
        x_end = max(cx1, cx2)
        for bx in range(x_start, x_end + 1):
            if in_bounds(bx, bridge_y) and not bool(wm[bridge_y, bx]) and not bool(pm[bridge_y, bx]):
                return (Tool.WIRE, bx, bridge_y)

    # ---- 5. Road columns flanking wire spine for each cluster ----
    for i, (cx, cy) in enumerate(active_clusters):
        spine_top = max(2, cy - 13)
        spine_bot = min(WORLD_H - 3, cy + 13)
        for road_x in [cx - 3, cx + 3]:
            if not in_bounds(road_x, cy):
                continue
            for r in range(spine_top, spine_bot + 1):
                if in_bounds(road_x, r) and bool(em[r, road_x]) and not bool(pm[r, road_x]):
                    return (Tool.ROAD, road_x, r)

    # ---- 6. Horizontal roads at top and bottom of each cluster ----
    for i, (cx, cy) in enumerate(active_clusters):
        for road_y in [cy - 14, cy + 14]:
            if not in_bounds(cx, road_y):
                continue
            for road_x in range(cx - 3, cx + 4):
                if in_bounds(road_x, road_y) and bool(em[road_y, road_x]) and not bool(pm[road_y, road_x]):
                    return (Tool.ROAD, road_x, road_y)

    # ---- 7. Proximity masks for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm
    res_count = int(np.sum(resm)) // 9
    com_count = int(np.sum(comm)) // 9
    ind_count = int(np.sum(indm)) // 9
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                cell = tm[nr2, nc2]
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    # ---- 8. Place zones near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer tiles close to active cluster centers
        best_score = np.full(len(cxs), 999999.0)
        for cx, cy in active_clusters:
            d = np.abs(cxs - cx) + np.abs(cys - cy)
            best_score = np.minimum(best_score, d)

        order = np.argsort(best_score)
        # Use step to vary which candidate we try first (avoid getting stuck)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- 9. Place civic services based on population ----
    if pop > 200:
        for ci, (cx, cy) in enumerate(active_clusters[:min(n_active, 6)]):
            for fpos in [(cx - 10, cy - 10), (cx + 10, cy - 10),
                         (cx - 10, cy + 10), (cx + 10, cy + 10)]:
                fsx, fsy = fpos
                if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 500:
        for ci, (cx, cy) in enumerate(active_clusters[:min(n_active, 6)]):
            for ppos in [(cx - 10, cy), (cx + 10, cy)]:
                psx, psy = ppos
                if in_bounds(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 1500:
        for ci, (cx, cy) in enumerate(active_clusters[:min(n_active, 4)]):
            sx, sy = cx + 12, cy - 12
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        # Seaport near bottom of map
        if in_bounds(60, 90) and bool(em[90, 60]):
            return (Tool.SEAPORT, 60, 90)
        # Airport
        if in_bounds(100, 15) and bool(em[15, 100]):
            return (Tool.AIRPORT, 100, 15)

    # ---- 10. Extend roads from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 50)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (in_bounds(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- 11. Extend wires from existing wires ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- 12. Parks in empty spaces near zones ----
    if pop > 800:
        zone_nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                zone_nbr[r0:r1, c0:c1] |= zone_tiles[sr0:sr1, sc0:sc1]
        park_cand = em & zone_nbr
        pys, pxs = np.where(park_cand)
        if len(pxs) > 0:
            k = (step * 17) % len(pxs)
            return (Tool.PARK, int(pxs[k]), int(pys[k]))

    return None

