        {'cx': 30, 'cy': 35, 'wx': 30, 'wy': 35},
        {'cx': 90, 'cy': 35, 'wx': 90, 'wy': 35},
        {'cx': 30, 'cy': 65, 'wx': 30, 'wy': 65},
        {'cx': 90, 'cy': 65, 'wx': 90, 'wy': 65},
    ]
    plant_positions = [(30, 35), (90, 35), (30, 65), (90, 65)]

    # ---- Ensure all 4 primary plants exist ----
    for px, py in plant_positions:
        has_plant = False
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = px + dx, py + dy
                if in_bounds(nx, ny) and pm[ny, nx]:
                    has_plant = True
        if not has_plant:
            return (Tool.COALPOWER, px, py)

    # ---- Ensure horizontal wire spine at row 35 ----
    for x in range(32, 89):
        if in_bounds(x, 35) and em[35, x] and not pm[35, x]:
            return (Tool.WIRE, x, 35)

    # ---- Ensure horizontal wire spine at row 65 ----
    for x in range(32, 89):
        if in_bounds(x, 65) and em[65, x] and not pm[65, x]:
            return (Tool.WIRE, x, 65)

    # ---- Ensure vertical wire at x=30 between rows 35-65 ----
    for y in range(37, 64):
        if in_bounds(30, y) and em[y, 30] and not pm[y, 30]:
            return (Tool.WIRE, 30, y)

    # ---- Ensure vertical wire at x=90 between rows 35-65 ----
    for y in range(37, 64):
        if in_bounds(90, y) and em[y, 90] and not pm[y, 90]:
            return (Tool.WIRE, 90, y)

    # ---- Extend wire network outward from each cluster based on pop ----
    pop_factor = min(30, obs.city_pop // 15)
    extent = 12 + pop_factor

    for cl in clusters:
        wc = cl['wx']
        wr_center = cl['wy']
        top = max(3, wr_center - extent)
        bot = min(WORLD_H - 4, wr_center + extent)
        left = max(3, wc - extent)
        right = min(WORLD_W - 4, wc + extent)

        # Extend vertical wire from cluster center
        wire_col = [r for r in range(WORLD_H) if in_bounds(wc, r) and wm[r, wc]]
        if wire_col:
            mn = min(wire_col)
            mx = max(wire_col)
            if mx < bot:
                ny = mx + 1
                if in_bounds(wc, ny) and not pm[ny, wc]:
                    return (Tool.WIRE, wc, ny)
            if mn > top:
                ny = mn - 1
                if in_bounds(wc, ny) and not pm[ny, wc]:
                    return (Tool.WIRE, wc, ny)

        # Extend horizontal wire from cluster center
        wire_row = [c for c in range(WORLD_W) if in_bounds(c, wr_center) and wm[wr_center, c]]
        if wire_row:
            mn = min(wire_row)
            mx = max(wire_row)
            if mx < right:
                nx = mx + 1
                if in_bounds(nx, wr_center) and not pm[wr_center, nx]:
                    return (Tool.WIRE, nx, wr_center)
            if mn > left:
                nx = mn - 1
                if in_bounds(nx, wr_center) and not pm[wr_center, nx]:
                    return (Tool.WIRE, nx, wr_center)

    # ---- Road grid: horizontal roads every 6 rows, vertical roads at cluster flanks ----
    # Build a grid of roads around each cluster
    for cl in clusters:
        wc = cl['wx']
        wy = cl['wy']
        pop_f = min(25, obs.city_pop // 15)
        sp_ext = min(12 + pop_f, 28)
        top = max(3, wy - sp_ext)
        bot = min(WORLD_H - 4, wy + sp_ext)
        left_e = max(3, wc - sp_ext)
        right_e = min(WORLD_W - 4, wc + sp_ext)

        # Horizontal roads every 6 rows
        for road_y in range(top, bot + 1, 6):
            for rx in range(left_e, right_e + 1):
                if in_bounds(rx, road_y) and em[road_y, rx] and not pm[road_y, rx]:
                    return (Tool.ROAD, rx, road_y)

        # Vertical roads at wc-1, wc+1 (flanking wire)
        for road_x in [wc - 1, wc + 1]:
            if not in_bounds(road_x, wy):
                continue
            wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and wm[r, wc]]
            for wr2 in wire_rows:
                if in_bounds(road_x, wr2) and em[wr2, road_x] and not pm[wr2, road_x]:
                    return (Tool.ROAD, road_x, wr2)

    # ---- Add extra power plants mid-game ----
    if obs.city_pop > 300:
        extra_plants = [(60, 20), (60, 50), (60, 80)]
        for epx, epy in extra_plants:
            has_p = any(pm[epy + dy, epx + dx]
                        for dy in range(-3, 4) for dx in range(-3, 4)
                        if in_bounds(epx + dx, epy + dy))
            if not has_p and in_bounds(epx, epy) and em[epy, epx]:
                return (Tool.COALPOWER, epx, epy)
            if not has_p:
                # Wire toward cluster spine
                for wx_t in range(min(epx, 30) + 1, max(epx, 90)):
                    if in_bounds(wx_t, epy) and em[epy, wx_t] and not pm[epy, wx_t]:
                        return (Tool.WIRE, wx_t, epy)

    if obs.city_pop > 600:
        nuclear_plants = [(15, 50), (105, 50)]
        for npx, npy in nuclear_plants:
            has_p = any(pm[npy + dy, npx + dx]
                        for dy in range(-3, 4) for dx in range(-3, 4)
                        if in_bounds(npx + dx, npy + dy))
            if not has_p and in_bounds(npx, npy) and em[npy, npx]:
                return (Tool.NUCLEARPOWER, npx, npy)

    # ---- Build proximity masks ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not em[nr2, nc2] and not zone_tiles[nr2, nc2]:
                    return False
        return True

    # ---- Place zones near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Sort by distance to nearest cluster
        min_dist = np.full(len(cxs_arr), 999999.0)
        for cl in clusters:
            d = np.abs(cxs_arr - cl['cx']) + np.abs(cys_arr - cl['cy'])
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- Services based on population ----
    if obs.city_pop > 100:
        fire_spots = [(22, 28), (82, 28), (22, 72), (82, 72),
                      (22, 42), (82, 42), (22, 58), (82, 58)]
        for fsx, fsy in fire_spots:
            if in_bounds(fsx, fsy) and em[fsy, fsx]:
                return (Tool.FIRESTATION, fsx, fsy)

    if obs.city_pop > 300:
        police_spots = [(38, 28), (98, 28), (38, 72), (98, 72),
                        (38, 42), (98, 42), (38, 58), (98, 58)]
        for psx, psy in police_spots:
            if in_bounds(psx, psy) and em[psy, psx]:
                return (Tool.POLICESTATION, psx, psy)

    if obs.city_pop > 700:
        stadium_spots = [(55, 20), (55, 50), (55, 80)]
        for stx, sty in stadium_spots:
            if in_bounds(stx, sty) and em[sty, stx]:
                return (Tool.STADIUM, stx, sty)

    if obs.city_pop > 1000:
        # Airport and seaport for large cities
        for apx, apy in [(60, 10), (60, 90)]:
            if in_bounds(apx, apy) and em[apy, apx]:
                return (Tool.AIRPORT, apx, apy)
        for spx, spy in [(10, 50), (110, 50)]:
            if in_bounds(spx, spy) and em[spy, spx]:
                return (Tool.SEAPORT, spx, spy)

    # ---- Parks for happiness ----
    if obs.city_pop > 500:
        park_spots = [(35, 35), (85, 35), (35, 65), (85, 65), (60, 50)]
        for pkx, pky in park_spots:
            if in_bounds(pkx, pky) and em[pky, pkx]:
                return (Tool.PARK, pkx, pky)

    # ---- Extend roads near existing wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2] and nbr_wire[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # ---- Expand wire as fallback ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and em[ny3, nx3] and not pm[ny3, nx3]:
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place coal plant + initial wire/road grid seed."""
    actions = []
    # Primary coal plant at center-left area
    actions.append((Tool.COALPOWER, 40, 50))
    # Wire spine going up and down from plant
    for y in range(47, 54):
        actions.append((Tool.WIRE, 42, y))
    # Road columns flanking wire
    for y in range(47, 54):
        actions.append((Tool.ROAD, 41, y))
        actions.append((Tool.ROAD, 43, y))
    # Second coal plant on right side
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire spine for second plant
    for y in range(47, 54):
        actions.append((Tool.WIRE, 82, y))
    # Road columns for second plant
    for y in range(47, 54):
        actions.append((Tool.ROAD, 81, y))
        actions.append((Tool.ROAD, 83, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    zone_tiles = resm | comm | indm

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Count zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- Ensure power plants exist ---
    if not np.any(pm):
        return (Tool.COALPOWER, 40, 50)

    plant_ys, plant_xs = np.where(pm)

    # --- Multi-neighborhood approach ---
    # We build 3 neighborhoods: left (cx=35), center (cx=60), right (cx=85)
    # Each neighborhood has: wire spine, flanking roads, zones
    neighborhoods = [
        {'cx': 35, 'cy': 50, 'wire_col': 37, 'road_l': 36, 'road_r': 38, 'plant_x': 34, 'plant_y': 50},
        {'cx': 60, 'cy': 50, 'wire_col': 62, 'road_l': 61, 'road_r': 63, 'plant_x': 60, 'plant_y': 50},
        {'cx': 85, 'cy': 50, 'wire_col': 87, 'road_l': 86, 'road_r': 88, 'plant_x': 85, 'plant_y': 50},
    ]

    # Pop-based spine extension
    pop_factor = min(35, obs.city_pop // 20)
    spine_top = max(3, 50 - 14 - pop_factor)
    spine_bot = min(WORLD_H - 4, 50 + 14 + pop_factor)

    # --- Phase 1: Ensure each neighborhood has a power plant ---
    for nb in neighborhoods:
        px, py_n = nb['plant_x'], nb['plant_y']
        # Check if plant exists nearby (within 6 tiles)
        has_plant = any(
            in_bounds(px + dx, py_n + dy) and bool(pm[py_n + dy, px + dx])
            for dy in range(-6, 7) for dx in range(-6, 7)
            if in_bounds(px + dx, py_n + dy)
        )
        # Place plant if not present and we have enough pop or it's the first two
        nb_idx = neighborhoods.index(nb)
        pop_thresh = nb_idx * 200  # 0, 200, 400
        if not has_plant and obs.city_pop >= pop_thresh:
            if in_bounds(px, py_n) and bool(em[py_n, px]):
                return (Tool.COALPOWER, px, py_n)

    # --- Phase 2: Build wire spines for each active neighborhood ---
    for nb in neighborhoods:
        px, py_n = nb['plant_x'], nb['plant_y']
        wc = nb['wire_col']
        nb_idx = neighborhoods.index(nb)
        pop_thresh = nb_idx * 150

        # Check if this neighborhood's plant is active
        has_plant = any(
            in_bounds(px + dx, py_n + dy) and bool(pm[py_n + dy, px + dx])
            for dy in range(-6, 7) for dx in range(-6, 7)
            if in_bounds(px + dx, py_n + dy)
        )
        if not has_plant and obs.city_pop < pop_thresh:
            continue

        wire_in_col = [r for r in range(WORLD_H)
                       if 0 <= wc < WORLD_W and bool(wm[r, wc])]

        if not wire_in_col:
            # Seed wire adjacent to plant
            for dy in range(-3, 4):
                ny = py_n + dy
                if in_bounds(wc, ny) and (bool(em[ny, wc]) or bool(wm[ny, wc])) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            # Grow downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            # Grow upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # --- Phase 3: Build road columns flanking wire spines ---
    for nb in neighborhoods:
        px, py_n = nb['plant_x'], nb['plant_y']
        wc = nb['wire_col']
        rl = nb['road_l']
        rr = nb['road_r']
        nb_idx = neighborhoods.index(nb)

        wire_in_col = [r for r in range(WORLD_H)
                       if 0 <= wc < WORLD_W and bool(wm[r, wc])]
        if not wire_in_col:
            continue

        # Alternate which side to build this step
        step_mod = (obs.step + nb_idx) % 4
        rows_to_check = wire_in_col[::2] if step_mod < 2 else wire_in_col[1::2]
        for wr in rows_to_check:
            if step_mod % 2 == 0:
                if in_bounds(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                    return (Tool.ROAD, rl, wr)
            else:
                if in_bounds(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                    return (Tool.ROAD, rr, wr)

    # --- Phase 4: Horizontal road connectors between neighborhoods ---
    # Connect neighborhoods with horizontal roads at key rows
    connector_rows = [spine_top + 2, 50, spine_bot - 2]
    for cr in connector_rows:
        if not in_bounds(0, cr):
            continue
        # Scan for gaps in horizontal roads between neighborhoods
        for x in range(30, 95):
            if in_bounds(x, cr) and bool(em[cr, x]) and not bool(pm[cr, x]):
                # Only place if adjacent to existing road or wire
                has_nbr = False
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = x + dx, cr + dy
                    if in_bounds(nx, ny) and (bool(rm[ny, nx]) or bool(wm[ny, nx])):
                        has_nbr = True
                        break
                if has_nbr:
                    return (Tool.ROAD, x, cr)

    # --- Phase 5: Build proximity masks for zone placement ---
    # Efficient neighbor computation using shift
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        # Target: 30% industrial, 30% commercial, 40% residential
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Place zones near roads and power ---
    cand_mask = em & nbr_road & nbr_wire
    # Keep safe margins
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near multiple wire spines
        # Distance to nearest wire spine
        wire_cols = [nb['wire_col'] for nb in neighborhoods]
        min_wire_dist = np.minimum.reduce([np.abs(cxs - wc) for wc in wire_cols])
        row_dist = np.abs(cys - 50) // 4
        dists = min_wire_dist + row_dist
        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Extend roads near wire to fill gaps ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (in_bounds(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # --- Services scaled with population ---
    if obs.city_pop > 200:
        service_spots = [
            (Tool.FIRESTATION, 45, 40), (Tool.FIRESTATION, 75, 40),
            (Tool.FIRESTATION, 45, 60), (Tool.FIRESTATION, 75, 60),
        ]
        for tool, sx, sy in service_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (tool, sx, sy)

    if obs.city_pop > 500:
        police_spots = [
            (Tool.POLICESTATION, 50, 45), (Tool.POLICESTATION, 70, 45),
            (Tool.POLICESTATION, 50, 55), (Tool.POLICESTATION, 70, 55),
        ]
        for tool, sx, sy in police_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (tool, sx, sy)

    if obs.city_pop > 1000:
        if in_bounds(60, 35) and bool(em[35, 60]):
            return (Tool.STADIUM, 60, 35)
        if in_bounds(60, 65) and bool(em[65, 60]):
            return (Tool.STADIUM, 60, 65)

    if obs.city_pop > 1500:
        if in_bounds(30, 50) and bool(em[50, 30]):
            return (Tool.NUCLEARPOWER, 30, 50)
        if in_bounds(90, 50) and bool(em[50, 90]):
            return (Tool.NUCLEARPOWER, 90, 50)

    # --- Expand wire laterally as fallback ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- Add extra neighborhoods when city grows large ---
    if obs.city_pop > 800:
        # Add 4th and 5th neighborhoods
        extra_nbs = [
            {'plant_x': 20, 'plant_y': 50, 'wire_col': 22, 'road_l': 21, 'road_r': 23},
            {'plant_x': 100, 'plant_y': 50, 'wire_col': 102, 'road_l': 101, 'road_r': 103},
        ]
        for nb in extra_nbs:
            px, py_n = nb['plant_x'], nb['plant_y']
            wc = nb['wire_col']
            has_plant = any(
                in_bounds(px + dx, py_n + dy) and bool(pm[py_n + dy, px + dx])
                for dy in range(-6, 7) for dx in range(-6, 7)
                if in_bounds(px + dx, py_n + dy)
            )
            if not has_plant and in_bounds(px, py_n) and bool(em[py_n, px]):
                return (Tool.COALPOWER, px, py_n)
            if has_plant:
                wire_in_col = [r for r in range(WORLD_H)
                               if 0 <= wc < WORLD_W and bool(wm[r, wc])]
                if not wire_in_col:
                    for dy in range(-3, 4):
                        ny = py_n + dy
                        if in_bounds(wc, ny) and (bool(em[ny, wc])) and not bool(pm[ny, wc]):
                            return (Tool.WIRE, wc, ny)
                else:
                    min_wr = min(wire_in_col)
                    max_wr = max(wire_in_col)
                    if max_wr < spine_bot:
                        nr = max_wr + 1
                        if in_bounds(wc, nr) and bool(em[nr, wc]) and not bool(pm[nr, wc]):
                            return (Tool.WIRE, wc, nr)
                    if min_wr > spine_top:
                        nr = min_wr - 1
                        if in_bounds(wc, nr) and bool(em[nr, wc]) and not bool(pm[nr, wc]):
                            return (Tool.WIRE, wc, nr)
                    for wr in wire_in_col:
                        if in_bounds(nb['road_l'], wr) and bool(em[wr, nb['road_l']]) and not bool(pm[wr, nb['road_l']]):
                            return (Tool.ROAD, nb['road_l'], wr)
                        if in_bounds(nb['road_r'], wr) and bool(em[wr, nb['road_r']]) and not bool(pm[wr, nb['road_r']]):
                            return (Tool.ROAD, nb['road_r'], wr)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in a 3x3 grid with wire crosses and flanking roads."""
    actions = []
    for px in [20, 60, 100]:
