        (5, 10), (115, 10), (5, 90), (115, 90),
        (40, 5), (80, 5), (40, 95), (80, 95),
        (10, 50), (110, 50), (60, 5), (60, 95),
    ]

    plant_grid = base_plants[:]
    if pop >= 0:
        plant_grid += extra_plants_200
    if pop > 500:
        plant_grid += extra_plants_500
    if pop > 1000:
        plant_grid += extra_plants_1000
    if pop > 2000:
        plant_grid += extra_plants_2000

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        found = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px+dx, py+dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # ---- Phase 2: Wire network - denser than parent ----
    # Wire rows every 5 tiles, wire cols every 8 tiles
    wire_rows = list(range(5, 100, 5))
    wire_cols = list(range(5, 120, 8))

    # First ensure each row with a plant gets connected
    for wr in wire_rows:
        if not ib(0, wr):
            continue
        row_has_plant = bool(pm[wr, :].any())
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Seed wire from nearest plant
            for px2, py2 in plant_grid:
                if ib(px2, wr) and em[wr, px2]:
                    return (Tool.WIRE, px2, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left, right):
            if em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            for px2, py2 in plant_grid:
                if ib(wc, py2) and em[py2, wc]:
                    return (Tool.WIRE, wc, py2)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot):
            if em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # ---- Phase 3: Dense road grid ----
    # Roads every 4 tiles in both directions -> more road access than parent
    road_rows = list(range(4, 100, 4))
    road_cols = list(range(4, 120, 4))

    for rr in road_rows:
        if not ib(0, rr):
            continue
        # Check wire/plant proximity (within 3 tiles)
        wire_near = False
        for dy in range(-3, 4):
            nr = rr + dy
            if 0 <= nr < WORLD_H and (wm[nr, :].any() or pm[nr, :].any()):
                wire_near = True
                break
        if not wire_near:
            continue
        row_road = rm[rr, :]
        if not row_road.any():
            # Seed at center or nearest wire col
            if ib(60, rr) and em[rr, 60]:
                return (Tool.ROAD, 60, rr)
            for wc in road_cols:
                if ib(wc, rr) and em[rr, wc] and not pm[rr, wc]:
                    return (Tool.ROAD, wc, rr)
        else:
            indices = np.where(row_road)[0]
            left = int(indices[0])
            right = int(indices[-1])
            if left > 2 and em[rr, left-1] and not pm[rr, left-1]:
                return (Tool.ROAD, left-1, rr)
            if right < WORLD_W-3 and em[rr, right+1] and not pm[rr, right+1]:
                return (Tool.ROAD, right+1, rr)
            # Fill gaps
            for x in range(left, right):
                if em[rr, x] and not pm[rr, x]:
                    return (Tool.ROAD, x, rr)

    for rc in road_cols:
        if not ib(rc, 0):
            continue
        wire_near = False
        for dx in range(-3, 4):
            nc = rc + dx
            if 0 <= nc < WORLD_W and (wm[:, nc].any() or pm[:, nc].any()):
                wire_near = True
                break
        if not wire_near:
            continue
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc]:
                return (Tool.ROAD, rc, 50)
            for wr in road_rows:
                if ib(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
        else:
            indices = np.where(col_road)[0]
            top = int(indices[0])
            bot = int(indices[-1])
            if top > 2 and em[top-1, rc] and not pm[top-1, rc]:
                return (Tool.ROAD, rc, top-1)
            if bot < WORLD_H-3 and em[bot+1, rc] and not pm[bot+1, rc]:
                return (Tool.ROAD, rc, bot+1)
            for y in range(top, bot):
                if em[y, rc] and not pm[y, rc]:
                    return (Tool.ROAD, rc, y)

    # ---- Phase 4: Zone placement ----
    # Compute neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: prefer clustering near existing zones AND near power
        min_plant_dist = np.full(len(cxs_arr), 999999.0)
        for px2, py2 in plant_grid[:15]:
            if ib(px2, py2):
                d = np.abs(cxs_arr - px2).astype(float) + np.abs(cys_arr - py2).astype(float)
                min_plant_dist = np.minimum(min_plant_dist, d)

        zone_score = min_plant_dist.copy()
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 150)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d2)
                zone_score = zone_dist * 0.4 + min_plant_dist * 0.6

        order = np.argsort(zone_score)
        # Deterministic offset based on step and pop for variety
        off = (step * 11 + pop * 7) % max(len(order), 1)
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # ---- Phase 5: Civic services ----
    if pop > 10:
        fire_spots = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 115, 15)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 50:
        police_spots = [(px2, py2) for py2 in range(15, 90, 15) for px2 in range(15, 110, 20)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150:
        park_spots = [(pkx, pky) for pky in range(20, 85, 12) for pkx in range(20, 105, 15)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300:
        stadium_spots = [
            (40, 20), (80, 20), (40, 50), (80, 50), (40, 80), (80, 80),
            (20, 35), (100, 35), (20, 65), (100, 65), (60, 15), (60, 85),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        airport_spots = [
            (10, 8), (60, 8), (110, 8), (10, 92), (60, 92), (110, 92),
            (8, 30), (8, 70), (112, 30), (112, 70),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        seaport_spots = [
            (5, 50), (115, 50), (30, 5), (90, 5), (30, 95), (90, 95),
            (5, 20), (115, 20), (5, 80), (115, 80),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Phase 6: Nuclear upgrades for high pop ----
    if pop > 3000:
        nuclear_spots = [
            (25, 25), (95, 25), (25, 75), (95, 75), (60, 50),
            (45, 10), (75, 10), (45, 90), (75, 90),
        ]
        for nx2, ny2 in nuclear_spots:
            if not ib(nx2, ny2):
                continue
            found = False
            for dy in range(-3, 4):
                for dx in range(-3, 4):
                    nnx, nny = nx2+dx, ny2+dy
                    if ib(nnx, nny) and tm[nny, nnx] in PLANT_TILES:
                        # Check if already nuclear (just skip coal ones)
                        found = True
                        break
                if found:
                    break
            # Place nuclear if empty
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- Fallback: extend wire from plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 13) % len(pxs)
        for offset in range(min(len(pxs), 50)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: extend road near wire ----
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 17) % len(wxs)
        for offset in range(min(len(wxs), 100)):
            k = (sk2 + offset * 3) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in 2 rows with horizontal wire connections."""
    actions = []
    # Two rows of 3 plants each
    plant_positions = [
        (20, 35), (60, 35), (100, 35),
        (20, 65), (60, 65), (100, 65),
    ]
    for (px, py) in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Short wire spine to start
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px, py + dy))
        # Horizontal wire connection stubs
        for dx in range(-3, 4):
            actions.append((Tool.WIRE, px + dx, py))
        # Roads flanking
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 40% res, 30% com, 30% ind at start, shift to more res as pop grows
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 anchor neighborhoods on a 3x2 grid
    # Each anchor: (plant_x, plant_y)
    all_anchors = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 3
        if pop < 300:   return 4
        if pop < 600:   return 5
        if pop < 1000:  return 6
        if pop < 1800:  return 7
        if pop < 3000:  return 8
        return 9

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS at each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant nearby
            for r in range(0, 10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- SPINE WIRES: horizontal + vertical cross pattern ----
    spine_half = min(18, 4 + pop // 15)
    for (px, py) in active_anchors:
        # Horizontal wire spine
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, py) and bool(wm[py, c])]
        if not wire_in_row:
            for dx2 in range(-3, 4):
                nx = px + dx2
                if ib(nx, py) and bool(em[py, nx]) and not bool(pm[py, nx]):
                    return (Tool.WIRE, nx, py)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, py) and not bool(pm[py, nc]):
                    return (Tool.WIRE, nc, py)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, py) and not bool(pm[py, nc]):
                    return (Tool.WIRE, nc, py)

        # Vertical wire spine
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy2 in range(-3, 4):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # ---- CONNECT ANCHORS HORIZONTALLY at anchor y-levels ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_pxs = sorted(px for (px, py) in active_anchors if py == yl)
        for i in range(len(row_pxs) - 1):
            x1, x2 = row_pxs[i], row_pxs[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and not bool(pm[yl, cx]):
                    if bool(em[yl, cx]):
                        return (Tool.WIRE, cx, yl)

    # ---- CONNECT ANCHORS VERTICALLY at anchor x-levels ----
    x_levels = sorted(set(px for (px, _) in active_anchors))
    for xl in x_levels:
        col_pys = sorted(py for (px, py) in active_anchors if px == xl)
        for i in range(len(col_pys) - 1):
            y1, y2 = col_pys[i], col_pys[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(xl, cy) and not bool(pm[cy, xl]):
                    if bool(em[cy, xl]):
                        return (Tool.WIRE, xl, cy)

    # ---- ROADS: build grid roads around each anchor ----
    # Roads at offset ±2 from each anchor in both directions
    for idx, (px, py) in enumerate(active_anchors):
        spine_half2 = min(18, 4 + pop // 15)
        spine_left = max(2, px - spine_half2)
        spine_right = min(WORLD_W - 3, px + spine_half2)
        spine_top = max(2, py - spine_half2)
        spine_bot = min(WORLD_H - 3, py + spine_half2)

        # Horizontal roads above and below the wire row
        for ry in [py - 2, py + 2]:
            if not ib(spine_left, ry) or not ib(spine_right, ry):
                continue
            for cx in range(spine_left, spine_right + 1):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    return (Tool.ROAD, cx, ry)

        # Vertical roads left and right of the wire column
        for rx in [px - 2, px + 2]:
            if not ib(rx, spine_top) or not ib(rx, spine_bot):
                continue
            cycle = (step + idx * 5) % 3
            for cy in range(spine_top + cycle, spine_bot + 1, 3):
                if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                    return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC: Fire stations ----
    if pop > 80:
        fire_spots = []
        for yl in [15, 35, 55, 75, 92]:
            for xl in [10, 35, 60, 85, 110]:
                fire_spots.append((xl, yl))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    # ---- CIVIC: Police stations ----
    if pop > 300:
        police_spots = []
        for yl in [25, 50, 75]:
            for xl in [15, 45, 75, 105]:
                police_spots.append((xl, yl))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # ---- CIVIC: Stadiums ----
    if pop > 700:
        stadium_spots = [(40, 10), (80, 10), (40, 90), (80, 90), (5, 50), (115, 50)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- UPGRADE: Nuclear power for later growth ----
    if pop > 1200:
        nuke_spots = [(10, 10), (110, 10), (10, 90), (110, 90), (60, 5), (60, 95)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- AIRPORT ----
    if pop > 2500:
        for asp in [(50, 5), (5, 50), (115, 50), (50, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- SEAPORT ----
    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 20)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

