def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    n_steps = obs.n_steps
    powered = obs.powered_zones

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- State initialization ----
    if 'sub_step' not in state:
        state['sub_step'] = 0
        state['last_pop'] = 0
        state['infra_phase'] = 0  # 0=wire, 1=road, 2=zone

    # ---- Define cluster layout: 9 clusters across the map ----
    # 3 columns x 3 rows, well-separated
    clusters = []
    for row, cy in enumerate([25, 50, 75]):
        for col, cx in enumerate([20, 60, 100]):
            clusters.append((cx, cy))

    # Power plants for each cluster: offset (-4,0) but clamped
    def plant_pos(cx, cy):
        px = max(3, cx - 8)
        py = cy
        return (px, py)

    # ---- Priority 1: Ensure plants exist for active clusters ----
    # Unlock clusters progressively by population
    def cluster_unlocked(i):
        thresholds = [0, 0, 0, 200, 400, 600, 800, 1200, 1600]
        return pop >= thresholds[i]

    # Check each cluster for a plant
    for i, (cx, cy) in enumerate(clusters):
        if not cluster_unlocked(i):
            continue
        ppx, ppy = plant_pos(cx, cy)
        if not in_bounds(ppx, ppy):
            continue
        # Check 5x5 neighborhood for existing plant
        has_plant = False
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = ppx + dx, ppy + dy
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            return (Tool.COALPOWER, ppx, ppy)

    # ---- Priority 2: Wire spines - connect plants to zones ----
    # Vertical spine at cx, horizontal bridge at cy
    active_clusters = [(i, cx, cy) for i, (cx, cy) in enumerate(clusters) if cluster_unlocked(i)]

    # Build vertical wire spines for each active cluster
    for i, cx, cy in active_clusters:
        spine_top = max(2, cy - 18)
        spine_bot = min(WORLD_H - 3, cy + 18)
        # Check gaps in spine
        for r in range(spine_top, spine_bot + 1):
            if in_bounds(cx, r) and not bool(wm[r, cx]) and not bool(pm[r, cx]) and not bool(rm[r, cx]):
                return (Tool.WIRE, cx, r)

    # Build horizontal wire bridges between clusters at each row
    # Connect clusters in same row
    row_groups = {0: [], 1: [], 2: []}
    for i, cx, cy in active_clusters:
        row = i // 3
        row_groups[row].append((cx, cy))

    for row_idx, group in row_groups.items():
        if len(group) < 2:
            continue
        group_sorted = sorted(group, key=lambda t: t[0])
        for j in range(len(group_sorted) - 1):
            cx1, cy1 = group_sorted[j]
            cx2, cy2 = group_sorted[j + 1]
            bridge_y = cy1
            for bx in range(cx1, cx2 + 1):
                if in_bounds(bx, bridge_y) and not bool(wm[bridge_y, bx]) and not bool(pm[bridge_y, bx]) and not bool(rm[bridge_y, bx]):
                    return (Tool.WIRE, bx, bridge_y)

    # Also connect vertically between rows for same column
    col_groups = {0: [], 1: [], 2: []}
    for i, cx, cy in active_clusters:
        col = i % 3
        col_groups[col].append((cx, cy))

    for col_idx, group in col_groups.items():
        if len(group) < 2:
            continue
        group_sorted = sorted(group, key=lambda t: t[1])
        for j in range(len(group_sorted) - 1):
            cx1, cy1 = group_sorted[j]
            cx2, cy2 = group_sorted[j + 1]
            bridge_x = cx1
            for by in range(cy1, cy2 + 1):
                if in_bounds(bridge_x, by) and not bool(wm[by, bridge_x]) and not bool(pm[by, bridge_x]) and not bool(rm[by, bridge_x]):
                    return (Tool.WIRE, bridge_x, by)

    # ---- Priority 3: Road grid around each cluster ----
    # Roads at cx-3, cx+3 (vertical) and cy-3, cy+3 (horizontal) create a grid
    for i, cx, cy in active_clusters:
        spine_top = max(2, cy - 18)
        spine_bot = min(WORLD_H - 3, cy + 18)

        # Vertical roads flanking the wire spine
        for road_x in [cx - 4, cx + 4]:
            if not in_bounds(road_x, cy):
                continue
            for r in range(spine_top, spine_bot + 1):
                if in_bounds(road_x, r) and bool(em[r, road_x]) and not bool(pm[r, road_x]):
                    return (Tool.ROAD, road_x, r)

        # Horizontal roads at top and bottom of spine
        for road_y in [spine_top, cy, spine_bot]:
            if not in_bounds(cx, road_y):
                continue
            for c in range(max(2, cx - 10), min(WORLD_W - 2, cx + 11)):
                if in_bounds(c, road_y) and bool(em[road_y, c]) and not bool(pm[road_y, c]) and not bool(wm[road_y, c]):
                    return (Tool.ROAD, c, road_y)

    # ---- Priority 4: Place zones near roads + wire ----
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # Balance: 25% industrial, 30% commercial, 45% residential
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        """Check 3x3 zone area is all empty or zone tiles."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate mask: empty, near road, near wire, away from edges
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: distance to nearest active cluster center
        best_score = np.full(len(cxs), 999999.0)
        for i, cx, cy in active_clusters:
            d = np.abs(cxs - cx) + np.abs(cys - cy)
            best_score = np.minimum(best_score, d)

        order = np.argsort(best_score)
        # Use step to cycle through candidates
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 150)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- Priority 5: Services based on population ----
    if pop > 400:
        for ci, (cx, cy) in enumerate(clusters[:6]):
            if not cluster_unlocked(ci):
                continue
            for fpos in [(cx - 10, cy - 10), (cx + 10, cy - 10),
                         (cx - 10, cy + 10), (cx + 10, cy + 10)]:
                fsx, fsy = fpos
                if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 800:
        for ci, (cx, cy) in enumerate(clusters[:6]):
            if not cluster_unlocked(ci):
                continue
            for ppos in [(cx - 9, cy), (cx + 9, cy),
                         (cx, cy - 9), (cx, cy + 9)]:
                psx, psy = ppos
                if in_bounds(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 1500:
        for ci, (cx, cy) in enumerate(clusters[:4]):
            if not cluster_unlocked(ci):
                continue
            sx, sy = cx + 14, cy
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        # Add nuclear plants for big cities
        for ci, (cx, cy) in enumerate(clusters):
            if not cluster_unlocked(ci):
                continue
            npx, npy = cx + 10, cy - 15
            if in_bounds(npx, npy):
                has_near_plant = any(bool(pm[npy + dy, npx + dx])
                                     for dy in range(-4, 5) for dx in range(-4, 5)
                                     if in_bounds(npx + dx, npy + dy))
                if not has_near_plant and bool(em[npy, npx]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    # ---- Fallback: Extend roads from existing road ends ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (in_bounds(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2])
                        and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: Extend wires from existing wires ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (in_bounds(nx3, ny3) and bool(em[ny3, nx3])
                        and not bool(pm[ny3, nx3])
                        and not bool(rm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in a 3x2 grid with wire spines and flanking roads."""
    actions = []
    for px in [20, 60, 100]:
        for py in [33, 67]:
            actions.append((Tool.COALPOWER, px, py))
            for dy in range(-7, 8):
                actions.append((Tool.WIRE, px, py + dy))
            for dy in range(-7, 8):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 12 anchors in a 3x4 grid for dense coverage
    # cols at 20, 60, 100; rows at 20, 40, 60, 80
    base_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [20, 40, 60, 80]:
            base_anchors.append((col_x, row_y, col_x, col_x - 1, col_x + 1))

    def num_active():
        if pop < 40:    return 1
        if pop < 100:   return 2
        if pop < 200:   return 3
        if pop < 350:   return 4
        if pop < 550:   return 5
        if pop < 800:   return 6
        if pop < 1100:  return 8
        if pop < 1500:  return 10
        return 12

    n_active = num_active()
    active_anchors = base_anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) ----
    spine_half = min(30, 8 + pop // 12)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows ----
    if n_active >= 2:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                _, py1, _, _, _ = col_anchors[i]
                _, py2, _, _, _ = col_anchors[i + 1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels (above and below) ----
    if pop > 20:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            for horiz_y in [yl - 3, yl + 3]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting row levels ----
    if pop > 60 and len(y_levels) >= 2:
        for col_x in [20, 60, 100]:
            for rx in [col_x - 3, col_x + 3]:
                if not ib(rx, 2) or not ib(rx, WORLD_H - 3):
                    continue
                yl_list = sorted(y_levels)
                for i in range(len(yl_list) - 1):
                    y1v = yl_list[i]
                    y2v = yl_list[i + 1]
                    for cy in range(y1v, y2v + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (8, 15), (35, 15), (75, 15), (108, 15),
            (8, 35), (35, 35), (75, 35), (108, 35),
            (8, 55), (35, 55), (75, 55), (108, 55),
            (8, 75), (35, 75), (75, 75), (108, 75),
            (8, 92), (35, 92), (75, 92), (108, 92),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (22, 10), (55, 10), (88, 10),
            (22, 30), (55, 30), (88, 30),
            (22, 50), (55, 50), (88, 50),
            (22, 70), (55, 70), (88, 70),
            (22, 90), (55, 90), (88, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10),
            (10, 50), (50, 50), (90, 50),
            (10, 90), (50, 90), (90, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94), (10, 6), (110, 6)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: multiple power plants with wire connections and road seeds"""
    actions = []
    # Primary power cluster - center
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from center plant
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Secondary plants at quadrant centers
    actions.append((Tool.COALPOWER, 30, 25))
    actions.append((Tool.COALPOWER, 90, 25))
    actions.append((Tool.COALPOWER, 30, 75))
    actions.append((Tool.COALPOWER, 90, 75))
    # Seed roads near center
    for x in range(50, 71):
        actions.append((Tool.ROAD, x, 44))
    for x in range(50, 71):
        actions.append((Tool.ROAD, x, 56))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 50, y))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 70, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone ratio: 50% RES, 25% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood centers - 6 neighborhoods across the map
    neighborhoods = [
        (30, 25),   # NW
        (60, 20),   # N
        (90, 25),   # NE
        (30, 75),   # SW
        (60, 80),   # S
        (90, 75),   # SE
        (15, 50),   # W
        (105, 50),  # E
        (60, 50),   # Center
    ]

    # Power plant positions - one per neighborhood roughly
    plant_targets = [
        (28, 23), (60, 18), (92, 23),
        (28, 77), (60, 82), (92, 77),
        (13, 50), (107, 50), (60, 50),
        (45, 40), (75, 40), (45, 60), (75, 60),
    ]

    # Phase 1: ensure power plants exist at key locations
    if funds > 2500:
        for ppx, ppy in plant_targets:
            if not ib(ppx, ppy):
                continue
            found = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    nx, ny = ppx + dx, ppy + dy
                    if ib(nx, ny) and pm[ny, nx]:
                        found = True
                        break
                if found:
                    break
            if not found:
                return (Tool.COALPOWER, ppx, ppy)

    # Wire grid: horizontal spines every 6 rows
    wire_rows = list(range(6, 97, 6))
    wire_cols = list(range(6, 116, 6))

    # Build complete horizontal wire lines
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Only seed near power plants
            if ib(60, wr) and (em[wr, 60] or wm[wr, 60]):
                if em[wr, 60]:
                    return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left to edge
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Extend right to edge
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left, right + 1):
            if ib(x, wr) and em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Build complete vertical wire lines
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot + 1):
            if ib(wc, y) and em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # Road grid: offset from wire lines by 3
    road_rows = []
    road_cols = []
    for wr in wire_rows:
        for off in [-3, 3]:
            r = wr + off
            if 3 < r < WORLD_H - 3:
                road_rows.append(r)
    for wc in wire_cols:
        for off in [-3, 3]:
            c = wc + off
            if 3 < c < WORLD_W - 3:
                road_cols.append(c)
    road_rows = sorted(set(road_rows))
    road_cols = sorted(set(road_cols))

    # Build horizontal roads
    for rr in road_rows:
        row_road = rm[rr, :]
        if not row_road.any():
            # Seed from center
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_road)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and ib(left - 1, rr) and em[rr, left - 1] and not pm[rr, left - 1]:
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 3 and ib(right + 1, rr) and em[rr, right + 1] and not pm[rr, right + 1]:
            return (Tool.ROAD, right + 1, rr)
        for x in range(left, right + 1):
            if ib(x, rr) and em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_road)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and ib(rc, top - 1) and em[top - 1, rc] and not pm[top - 1, rc]:
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 3 and ib(rc, bot + 1) and em[bot + 1, rc] and not pm[bot + 1, rc]:
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top, bot + 1):
            if ib(rc, y) and em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # Zone placement
    # Compute "near road" mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute "near wire or plant" mask (within 3 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone locations
    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H - 3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score candidates: cluster near existing zones, spread to neighborhoods
        if total_zones > 10:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                zone_score = zone_dist
            else:
                zone_score = (np.abs(cxs_arr - 60).astype(float) +
                              np.abs(cys_arr - 50).astype(float))
        else:
            zone_score = (np.abs(cxs_arr - 60).astype(float) +
                          np.abs(cys_arr - 50).astype(float))

        # Spread to multiple neighborhood centers
        if pop > 100:
            min_nbhd = np.full(len(cxs_arr), 999999.0)
            for nx, ny in neighborhoods:
                d = (np.abs(cxs_arr - nx).astype(float) +
                     np.abs(cys_arr - ny).astype(float))
                min_nbhd = np.minimum(min_nbhd, d)
            zone_score = zone_score * 0.4 + min_nbhd * 0.6

        order = np.argsort(zone_score)
        # Vary starting position by step/pop
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # Civic services - place them reactively based on pop
    if pop > 10:
        # Fire stations on 20x20 grid
        fire_grid = [(fx, fy) for fy in range(15, 95, 20)
                     for fx in range(15, 115, 20)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(18, 92, 22)
                       for px2 in range(18, 112, 22)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150:
        park_grid = [(pkx, pky) for pky in range(12, 92, 10)
                     for pkx in range(12, 112, 10)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300:
        stadium_locs = [
            (25, 20), (95, 20), (25, 80), (95, 80),
            (60, 15), (60, 85), (10, 50), (110, 50),
            (45, 35), (75, 35), (45, 65), (75, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 5000:
        nuclear_locs = [
            (15, 15), (105, 15), (15, 85), (105, 85),
            (60, 10), (60, 90), (10, 50), (110, 50),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            found = False
            for dy in range(-5, 6):
                for dx in range(-5, 6):
                    nx2, ny2 = npx + dx, npy + dy
                    if ib(nx2, ny2) and pm[ny2, nx2]:
                        found = True
                        break
                if found:
                    break
            if not found and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        airport_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 700:
        seaport_locs = [
            (5, 50), (115, 50), (60, 5), (60, 95),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: connect plants with wires
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: place roads near wires
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 80)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0, 3), (0, -3), (3, 0), (-3, 0),
                             (0, 4), (0, -4), (4, 0), (-4, 0)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire and road seeds across the map."""
    actions = []
    # Three starter plants spread horizontally at mid-height
    starts = [(20, 50), (60, 50), (100, 50)]
    for px, py in starts:
        actions.append((Tool.COALPOWER, px, py))
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px + 2, py + dy))
        for dy in range(-2, 3):
            actions.append((Tool.ROAD, px + 1, py + dy))
            actions.append((Tool.ROAD, px + 3, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 cluster layout: 3 rows x 3 cols spread across the 120x100 map
    # Each cluster: (plant_x, plant_y, wire_col, road_left, road_right)
    all_clusters = [
        (20,  25, 22, 21, 23),
        (60,  25, 62, 61, 63),
        (100, 25, 102, 101, 103),
        (20,  50, 22, 21, 23),
        (60,  50, 62, 61, 63),
        (100, 50, 102, 101, 103),
        (20,  75, 22, 21, 23),
        (60,  75, 62, 61, 63),
        (100, 75, 102, 101, 103),
    ]

    def num_active():
        if pop < 100:   return 1
        if pop < 300:   return 2
        if pop < 600:   return 3
        if pop < 1000:  return 4
        if pop < 1500:  return 5
        if pop < 2500:  return 6
        if pop < 4000:  return 7
        if pop < 6000:  return 8
        return 9

    n_active = num_active()
    active_clusters = all_clusters[:n_active]
    active_centers = [(px, py) for (px, py, wc, rl, rr) in active_clusters]

    # --- ENSURE POWER PLANTS ---
    for (px, py, wc, rl, rr) in active_clusters:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- WIRE SPINE (vertical) per cluster ---
    spine_half = min(30, 10 + pop // 10)
    for (px, py, wc, rl, rr) in active_clusters:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # --- HORIZONTAL WIRE connecting clusters in same row ---
    row_ys = sorted(set(py for (px, py, wc, rl, rr) in active_clusters))
    for yl in row_ys:
        row_cs = sorted([(wc, py) for (px, py, wc, rl, rr) in active_clusters if py == yl], key=lambda a: a[0])
        for i in range(len(row_cs) - 1):
            wc1 = row_cs[i][0]
            wc2 = row_cs[i + 1][0]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # --- VERTICAL WIRE connecting same column clusters ---
    if n_active >= 4:
        col_xs = sorted(set(wc for (px, py, wc, rl, rr) in active_clusters))
        for xc in col_xs:
            col_cs = sorted([(wc, py) for (px, py, wc, rl, rr) in active_clusters if wc == xc], key=lambda a: a[1])
            for i in range(len(col_cs) - 1):
                y1c = col_cs[i][1]
                y2c = col_cs[i + 1][1]
                for cy in range(y1c + 1, y2c):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # --- ROAD flanking wire spines ---
    for idx, (px, py, wc, rl, rr) in enumerate(active_clusters):
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 5) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # --- HORIZONTAL ROADS between clusters (connecting row roads) ---
    if pop > 30:
        for yl in row_ys:
            row_cs_data = sorted([(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_clusters if py == yl],
                                 key=lambda a: a[0])
            if len(row_cs_data) < 2:
                continue
            x_left = row_cs_data[0][3]
            x_right = row_cs_data[-1][4]
            for horiz_y in [yl - 4, yl + 4]:
                if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                    continue
                for cx in range(x_left, x_right + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # Extra horizontal roads at wider spacing for denser coverage
    if pop > 300:
        for yl in row_ys:
            row_cs_data = sorted([(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_clusters if py == yl],
                                 key=lambda a: a[0])
            if len(row_cs_data) < 2:
                continue
            x_left = row_cs_data[0][3]
            x_right = row_cs_data[-1][4]
            for horiz_y in [yl - 8, yl + 8, yl - 12, yl + 12]:
                if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                    continue
                for cx in range(x_left, x_right + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # --- BUILD NEIGHBOR MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_clusters:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES ---
    if pop > 60:
        fire_spots = [
            (8, 20), (30, 20), (50, 20), (70, 20), (90, 20), (112, 20),
            (8, 40), (30, 40), (50, 40), (70, 40), (90, 40), (112, 40),
            (8, 60), (30, 60), (50, 60), (70, 60), (90, 60), (112, 60),
            (8, 80), (30, 80), (50, 80), (70, 80), (90, 80), (112, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (15, 70), (45, 70), (75, 70), (105, 70),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (35, 10), (75, 10), (110, 10),
            (35, 90), (75, 90), (110, 90),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear upgrade
    if pop > 2000:
        nuke_spots = [
            (40, 5), (80, 5), (5, 50), (115, 50),
            (40, 95), (80, 95), (5, 15), (115, 15),
            (5, 85), (115, 85),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PARKS to boost land value ---
    if pop > 300:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- FALLBACK: extend wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: road near zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious multi-cluster city policy
# Strategy: 4 large power plant clusters spread across the map
# Grid-based road network with dense zone placement
# Progressive unlocking of more clusters and civic services

def init(obs, state):
    """Bootstrap: place first coal plant + wire + roads at primary cluster."""
    actions = []
    # Primary cluster center-left
    actions.append((Tool.COALPOWER, 20, 50))
    # Wire spine vertical
    for dy in range(-3, 4):
        actions.append((Tool.WIRE, 22, 50 + dy))
    # Roads flanking
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, 21, 50 + dy))
        actions.append((Tool.ROAD, 23, 50 + dy))
    # Horizontal road at midpoint
    for dx in range(18, 27):
        actions.append((Tool.ROAD, dx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- CLUSTER DEFINITIONS ----
    # Each cluster: (plant_x, plant_y, center_x, center_y, grid_size)
    # We'll build a grid road network around each cluster center
    clusters = [
        # (plant_x, plant_y, cx, cy)
        (20, 50,  30, 50),   # left-center
        (65, 50,  75, 50),   # right-center
        (20, 25,  30, 25),   # left-top
        (65, 25,  75, 25),   # right-top
        (20, 75,  30, 75),   # left-bottom
        (65, 75,  75, 75),   # right-bottom
        (43, 50,  43, 38),   # center-left-mid
        (95, 50,  95, 38),   # far-right
    ]

    # Unlock clusters progressively
    def num_active():
        if pop < 200:   return 1
        if pop < 600:   return 2
        if pop < 1200:  return 3
        if pop < 2000:  return 4
        if pop < 3000:  return 5
        if pop < 4500:  return 6
        if pop < 6000:  return 7
        return 8

    active = clusters[:num_active()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, cx, cy) in active:
        # Check for plant nearby
        has_plant = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place plant
            for r in range(0, 6):
                placed = False
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- BUILD GRID ROAD NETWORK ----
    # For each active cluster, build a grid of roads
    # Grid: horizontal roads every 4 rows, vertical roads every 4 cols
    # around the cluster center, spanning +-20 tiles

    grid_half = 18  # half-size of grid
    grid_spacing = 4  # road every 4 tiles

    def build_cluster_grid(cx, cy):
        """Return list of road positions for this cluster's grid."""
        roads = []
        # Horizontal roads
        for gy in range(cy - grid_half, cy + grid_half + 1, grid_spacing):
            if not ib(cx, gy):
                continue
            for gx in range(cx - grid_half, cx + grid_half + 1):
                if ib(gx, gy):
                    roads.append((gx, gy))
        # Vertical roads
        for gx in range(cx - grid_half, cx + grid_half + 1, grid_spacing):
            if not ib(gx, cy):
                continue
            for gy in range(cy - grid_half, cy + grid_half + 1):
                if ib(gx, gy):
                    roads.append((gx, gy))
        return roads

    # Build roads for active clusters
    for (px, py, cx, cy) in active:
        grid_roads = build_cluster_grid(cx, cy)
        # Find first road position that needs building
        step_off = step % max(len(grid_roads), 1)
        for i in range(min(len(grid_roads), 50)):
            k = (step_off + i * 7) % len(grid_roads)
            gx, gy = grid_roads[k]
            if bool(em[gy, gx]):
                return (Tool.ROAD, gx, gy)

    # ---- WIRE GRID TO CONNECT PLANTS TO ZONES ----
    # Build wire along the diagonals between plant and cluster center
    for (px, py, cx, cy) in active:
        # Wire from plant outward along a spine
        # Find plant position
        plant_pos = None
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = px+dx, py+dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    plant_pos = (nx, ny)
                    break
            if plant_pos:
                break

        if plant_pos is None:
            continue

        ppx, ppy = plant_pos

        # Build wire spine from plant toward cluster center and beyond
        # Vertical wire spine at plant_x+2
        wire_col = ppx + 2
        if ib(wire_col, ppy):
            for gy in range(max(2, cy - grid_half - 2), min(WORLD_H-2, cy + grid_half + 2)):
                if ib(wire_col, gy) and bool(em[gy, wire_col]) and not bool(pm[gy, wire_col]):
                    return (Tool.WIRE, wire_col, gy)

        # Horizontal wire at cluster center connecting to vertical spine
        for gx in range(max(2, cx - grid_half - 2), min(WORLD_W-2, cx + grid_half + 2)):
            if ib(gx, cy) and bool(em[cy, gx]) and not bool(pm[cy, gx]):
                return (Tool.WIRE, gx, cy)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% res, 30% com, 30% ind
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road/wire masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active cluster centers
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, cx, cy) in active:
            d = np.abs(cxs - cx).astype(float) + np.abs(cys - cy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND ROADS near wires ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- EXTEND WIRE laterally ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- CIVIC SERVICES ----
    if pop > 200:
        fire_spots = [
            (30, 40), (30, 60), (75, 40), (75, 60),
            (50, 25), (50, 75), (10, 50), (95, 50),
            (30, 20), (75, 20), (30, 80), (75, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        police_spots = [
            (40, 35), (65, 35), (40, 65), (65, 65),
            (20, 30), (90, 30), (20, 70), (90, 70),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        for (sx, sy) in [(50, 50), (50, 15), (50, 85), (100, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        for (sx, sy) in [(110, 20), (110, 80), (5, 20), (5, 80)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    if pop > 2000:
        for (sx, sy) in [(55, 90), (55, 5)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    return None

def init(obs, state):
