def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # ---- Helper: fast dilation ----
    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # ---- Zone tool picker: 50% RES, 30% COM, 20% IND ----
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Dense power plant grid ----
    # Plants every 15 tiles covering full map
    plant_grid = []
    for py in range(12, 95, 15):
        for px in range(12, 115, 15):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Reactive wire expansion ----
    # Find wire candidates: empty tiles adjacent to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~rm & ~zone_tiles
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Find plants not yet connected to power network
        unconnected = [(px, py) for px, py in plant_grid
                       if ib(px, py) and not bool(near_power[py, px])]
        if unconnected:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in unconnected)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward zones lacking power
        unpowered_zones = zone_tiles & ~near_power
        zys_u, zxs_u = np.where(unpowered_zones)
        if len(zxs_u) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs_u[:50], zys_u[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward map areas lacking power (on wire grid)
        wire_grid_rows = list(range(8, 97, 8))
        wire_grid_cols = list(range(8, 117, 8))
        unpowered_wire_pts = [(gx, gy) for gy in wire_grid_rows for gx in wire_grid_cols
                               if ib(gx, gy) and not bool(near_power[gy, gx])]
        if unpowered_wire_pts:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in unpowered_wire_pts[:30])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Dense road grid ----
    # Roads every 6 tiles where powered, expanding from existing roads
    road_grid_targets = []
    for gy in range(6, 97, 6):
        for gx in range(6, 117, 6):
            road_grid_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles & ~wm
        road_cand[0:3, :] = False
        road_cand[WORLD_H-3:, :] = False
        road_cand[:, 0:3] = False
        road_cand[:, WORLD_W-3:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets = uncovered_road[:30]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Seed road directly at target if empty
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]) and not bool(wm[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 150)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                rd_stride = max(1, len(road_xs) // 150)
                road_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(road_xs), rd_stride):
                    d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                    road_dist = np.minimum(road_dist, d)
                # Spread across map using neighborhood centers
                neighborhoods = [(30,25),(90,25),(30,75),(90,75),(60,50),
                                  (15,50),(105,50),(60,15),(60,85),
                                  (45,37),(75,37),(45,62),(75,62),
                                  (20,12),(100,12),(20,87),(100,87)]
                nbhd_dist = np.full(len(cxs_arr), 9999.0)
                for nx, ny in neighborhoods:
                    d = (np.abs(cxs_arr - nx) + np.abs(cys_arr - ny)).astype(float)
                    nbhd_dist = np.minimum(nbhd_dist, d)
                score = zone_dist * 0.3 + road_dist * 0.8 + nbhd_dist * 0.4
            else:
                score = zone_dist
        else:
            score = (np.abs(cxs_arr - 30) + np.abs(cys_arr - 25)).astype(float)

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services tiered by population ----
    if pop > 30:
        fire_grid = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 115, 10)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(12, 92, 12) for px2 in range(12, 112, 12)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(8, 95, 8) for pkx in range(8, 115, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(25,20),(85,20),(25,70),(85,70),(55,15),(55,85),
                        (15,45),(105,45),(40,50),(80,50),(60,35),(60,65)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800 and funds > 5000:
        nuke_locs = [(60,50),(20,25),(100,25),(20,75),(100,75),
                     (60,12),(60,88),(10,50),(110,50)]
        for nx, ny in nuke_locs:
            if not ib(nx, ny): continue
            x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
            y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
            if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(55,8),(75,8),(55,91),(75,91),
                        (8,30),(110,30),(8,65),(110,65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(10,50),(110,50),(60,8),(60,91),
                        (15,20),(105,20),(15,80),(105,80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from any plant ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        for i in range(min(len(pwr_xs), 20)):
            k = (step * 7 + i) % len(pwr_xs)
            px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
            for dx2, dy2 in [(5,0),(-5,0),(0,5),(0,-5),(4,4),(-4,4),(4,-4),(-4,-4)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(wm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from plant ----
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            nx3, ny3 = px3+dx3, py3+dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + seed roads + initial zones"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines from center outward
    for x in range(48, 73):
        actions.append((Tool.WIRE, x, 50))
    for y in range(38, 63):
        actions.append((Tool.WIRE, 60, y))
    # Seed horizontal roads near center
    for x in range(45, 76):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    # Seed vertical roads
    for y in range(44, 57):
        actions.append((Tool.ROAD, 54, y))
        actions.append((Tool.ROAD, 66, y))
    # Seed some initial zones near center
    actions.append((Tool.RESIDENTIAL, 57, 47))
    actions.append((Tool.INDUSTRIAL, 63, 47))
    actions.append((Tool.COMMERCIAL, 57, 53))
    actions.append((Tool.RESIDENTIAL, 63, 53))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---- Determine zone ratio ----
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Place power plants in a dense grid ----
    # Plants every 20 cols, 18 rows — denser than parent
    plant_grid_xs = list(range(10, WORLD_W - 5, 20))
    plant_grid_ys = list(range(10, WORLD_H - 5, 18))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            # Check if there's already a plant nearby (within 8 tiles)
            x0, x1 = max(0, ppx - 8), min(WORLD_W, ppx + 9)
            y0, y1 = max(0, ppy - 8), min(WORLD_H, ppy + 9)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network — connect plants together ----
    # Strategy: grow wire from existing power sources toward uncovered areas
    # Horizontal wire rows every 18 rows
    wire_rows = list(range(10, WORLD_H - 5, 18))
    # Vertical wire cols every 20 cols
    wire_cols = list(range(10, WORLD_W - 5, 20))

    # Extend horizontal wires across each designated row
    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            # Seed from nearest plant column
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                nearest = pxs[np.argmin(np.abs(pys - wr))]
                if ib(int(nearest), wr) and bool(em[wr, int(nearest)]):
                    return (Tool.WIRE, int(nearest), wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left
        if left > 2 and bool(em[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        # Extend right
        if right < WORLD_W - 3 and bool(em[wr, right+1]):
            return (Tool.WIRE, right+1, wr)
        # Fill gaps
        for x in range(left+1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and bool(em[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads are placed 6 tiles from wire rows/cols so zones can fit between
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 6)
        road_rows.append(wr + 6)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 6)
        road_cols.append(wc + 6)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    # Build horizontal roads
    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: CLOSED-LOOP Zone placement ----
    # Find best candidate: empty, near road, near power, far from existing zones
    zone_cand = em & near_road & near_power
    # Keep away from edges
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Don't place on wire rows or road rows to preserve infrastructure
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        """Check 3x3 area is empty or already zoned"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer spots near roads but spread from existing zones
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        # Distance to nearest road
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Distance to nearest existing zone (want some spacing)
        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 0.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                zone_dist = np.maximum(zone_dist, -d)  # maximize min distance = spread out
            zone_dist = -zone_dist  # lower = farther from existing = better spread
        else:
            # No zones yet: go toward center
            zone_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Combined score: close to roads, spread from existing zones
        score = road_dist * 1.5 + zone_dist * 0.5

        order = np.argsort(score)
        # Use step to vary starting point for diversity
        off = (step * 11 + pop) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 30:
        fire_spots = [(fx, fy) for fy in range(10, 96, 10) for fx in range(10, 112, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [(px2, py2) for py2 in range(12, 92, 14) for px2 in range(12, 110, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(14, 90, 9) for pkx in range(14, 108, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_spots = [(sx, sy) for sy in range(18, 88, 22) for sx in range(18, 102, 28)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 900:
        airport_spots = [
            (55, 7), (65, 7), (55, 92), (65, 92),
            (7, 44), (112, 44), (7, 56), (112, 56),
            (30, 7), (90, 7), (30, 92), (90, 92),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [
            (7, 50), (112, 50), (60, 4), (60, 95),
            (24, 4), (96, 4), (24, 95), (96, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: place road near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(7,0),(-7,0),(0,7),(0,-7),(4,0),(-4,0),(0,4),(0,-4)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
