def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        rr = res_count / tz
        # Target: 25% ind, 30% com, 45% res
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Power plant placement ----
    # 4 clusters: NW, NE, SW, SE + center + mid-left + mid-right
    plant_grid = [
        # Left column
        (30, 20), (30, 50), (30, 80),
        # Right column
        (90, 20), (90, 50), (90, 80),
        # Center column
        (60, 20), (60, 50), (60, 80),
        # Extra density
        (15, 35), (15, 65), (105, 35), (105, 65),
        (45, 35), (45, 65), (75, 35), (75, 65),
    ]
    for ppx, ppy in plant_grid:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
        y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network ----
    # Horizontal wire rows at y=20,35,50,65,80
    wire_rows = [20, 35, 50, 65, 80]
    # Vertical wire cols at x=15,30,45,60,75,90,105
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Try to start from a plant in this row vicinity
            for try_x in [60, 30, 90, 45, 75]:
                if ib(try_x, wr) and bool(em[wr, try_x]):
                    return (Tool.WIRE, try_x, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 4 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            for try_y in [50, 35, 65, 20, 80]:
                if ib(wc, try_y) and bool(em[try_y, wc]):
                    return (Tool.WIRE, wc, try_y)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads between wire rows/cols, offset by ~6 tiles
    # Horizontal roads at y=26,29,41,44,56,59,71,74
    road_rows = [14, 17, 26, 29, 41, 44, 56, 59, 71, 74, 83, 86]
    road_rows = [r for r in road_rows if 3 < r < WORLD_H - 3]
    # Vertical roads at x=21,24,36,39,51,54,66,69,81,84,96,99
    road_cols = [6, 9, 21, 24, 36, 39, 51, 54, 66, 69, 81, 84, 96, 99, 111, 114]
    road_cols = [c for c in road_cols if 3 < c < WORLD_W - 3]

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            for try_x in [60, 30, 90]:
                if ib(try_x, rr) and bool(em[rr, try_x]) and not bool(pm[rr, try_x]):
                    return (Tool.ROAD, try_x, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            for try_y in [50, 35, 65]:
                if ib(rc, try_y) and bool(em[try_y, rc]) and not bool(pm[try_y, rc]):
                    return (Tool.ROAD, rc, try_y)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Also exclude wire rows and cols (don't zone over infrastructure spine)
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                t = tm[nr, nc]
                if bool(pm[nr, nc]) or bool(rm[nr, nc]) or bool(wm[nr, nc]):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer near roads, near existing zones, spread across map
        if total_zones > 0:
            zys2, zxs2 = np.where(zone_tiles)
            road_ys, road_xs = np.where(rm)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            if len(zxs2) > 0:
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d)
            road_dist = np.full(len(cxs_arr), 9999.0)
            if len(road_xs) > 0:
                stride2 = max(1, len(road_xs) // 80)
                for i in range(0, len(road_xs), stride2):
                    d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                    road_dist = np.minimum(road_dist, d)
            score = zone_dist * 0.35 + road_dist * 0.65
        else:
            # Seed near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        # Vary starting offset to avoid getting stuck
        off = (step * 11 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services (closed-loop based on pop) ----
    if pop > 40:
        # Fire stations spread across map
        fire_grid = [(fx, fy) for fy in range(15, 90, 18) for fx in range(15, 110, 22)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_grid = [(px2, py2) for py2 in range(18, 88, 20) for px2 in range(18, 108, 26)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_grid = [(pkx, pky) for pky in range(12, 92, 12) for pkx in range(12, 112, 16)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_grid = [(sx, sy) for sy in range(25, 85, 28) for sx in range(25, 100, 35)]
        for stx, sty in stadium_grid:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        # Nuclear plants for more power
        nuke_spots = [(18, 10), (102, 10), (18, 90), (102, 90), (60, 10), (60, 90)]
        for npx, npy in nuke_spots:
            if ib(npx, npy):
                x0, x1 = max(0, npx - 8), min(WORLD_W, npx + 9)
                y0, y1 = max(0, npy - 8), min(WORLD_H, npy + 9)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[npy, npx]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        airport_spots = [
            (60, 8), (60, 91), (8, 50), (111, 50),
            (30, 8), (90, 8), (30, 91), (90, 91),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_spots = [
            (10, 50), (109, 50), (60, 5), (60, 94),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend power wires toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:
            shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:
            shifted[1:, :] = power_src[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0:
        if len(uzxs) > 0:
            best_d = 1e9
            best_k = 0
            stride = max(1, len(uzxs) // 30)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - uzxs[j]) + abs(cy - uzys[j]) for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
        else:
            k = step % len(wxs_c)
            return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- Fallback: roads near power ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        for i in range(len(pwr_xs)):
            k = (step * 13 + i) % len(pwr_xs)
            px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
            for dx2, dy2 in [(6, 0), (-6, 0), (0, 6), (0, -6), (4, 0), (-4, 0), (0, 4), (0, -4)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire spines and road seeds."""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire spines from each plant
    for dx in range(-12, 13):
        actions.append((Tool.WIRE, 30 + dx, 50))
        actions.append((Tool.WIRE, 90 + dx, 50))
    for dy in range(-12, 13):
        actions.append((Tool.WIRE, 30, 50 + dy))
        actions.append((Tool.WIRE, 90, 50 + dy))
    # Seed roads flanking horizontal wire spines
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, 30 + dx, 48))
        actions.append((Tool.ROAD, 30 + dx, 52))
        actions.append((Tool.ROAD, 90 + dx, 48))
        actions.append((Tool.ROAD, 90 + dx, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 45% res, 30% com, 25% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    # Reactive: check what's actually on the map
    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === CLUSTER LAYOUT ===
    # 5 columns x 4 rows = 20 clusters covering whole map
    cluster_cols = [12, 35, 60, 85, 108]
    cluster_rows = [15, 38, 62, 85]

    def active_clusters():
        if pop < 50:
            return [(30, 50), (90, 50)]
        if pop < 200:
            return [(30, 38), (60, 50), (90, 38), (30, 62), (90, 62)]
        if pop < 600:
            return [(12, 38), (35, 38), (60, 38), (85, 38), (108, 38),
                    (12, 62), (35, 62), (60, 62), (85, 62), (108, 62)]
        if pop < 1500:
            return [(cx, cy) for cy in [15, 38, 62, 85]
                    for cx in [12, 35, 60, 85, 108]]
        # Full grid
        return [(cx, cy) for cy in cluster_rows for cx in cluster_cols]

    clusters = active_clusters()

    # === ENSURE POWER PLANTS ===
    # Each cluster gets its own plant if none nearby
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            # Try to place plant; prefer empty spot near center
            for r in range(15):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # === WIRE INFRASTRUCTURE: extend from each plant ===
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(22, 6 + pop // 25)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Extend wire horizontally and vertically
            for axis in ['h', 'v']:
                for sign in [-1, 1]:
                    for dist in range(1, spine_reach + 1):
                        if axis == 'h':
                            nx3, ny3 = px2 + sign * dist, py2
                        else:
                            nx3, ny3 = px2, py2 + sign * dist
                        if not ib(nx3, ny3):
                            break
                        if bool(pm[ny3, nx3]):
                            break
                        if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                            return (Tool.WIRE, nx3, ny3)

    # === CONNECT CLUSTERS WITH WIRE (horizontal) ===
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows_set:
        cols_this_row = sorted(cx for cx, c_cy in clusters if abs(c_cy - cy) <= 5)
        for i in range(len(cols_this_row) - 1):
            c1, c2 = cols_this_row[i], cols_this_row[i + 1]
            for x in range(c1, c2 + 1):
                if ib(x, cy) and not bool(pm[cy, x]) and not bool(wm[cy, x]):
                    if bool(em[cy, x]):
                        return (Tool.WIRE, x, cy)

    # === CONNECT CLUSTERS WITH WIRE (vertical) ===
    for cx in active_cols_set:
        rows_this_col = sorted(cy for c_cx, cy in clusters if abs(c_cx - cx) <= 5)
        for i in range(len(rows_this_col) - 1):
            r1, r2 = rows_this_col[i], rows_this_col[i + 1]
            for y in range(r1, r2 + 1):
                if ib(cx, y) and not bool(pm[y, cx]) and not bool(wm[y, cx]):
                    if bool(em[y, cx]):
                        return (Tool.WIRE, cx, y)

    # === BUILD ROAD GRID AROUND EACH CLUSTER ===
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        # Multiple parallel road pairs for denser zones
        for road_offset in [2, 5, 8]:
            for road_y in [cy - road_offset, cy + road_offset]:
                if not (0 < road_y < WORLD_H - 1):
                    continue
                for dx in range(-road_reach, road_reach + 1):
                    nx4, ny4 = cx + dx, road_y
                    if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                        if not bool(rm[ny4, nx4]):
                            return (Tool.ROAD, nx4, ny4)
            for road_x in [cx - road_offset, cx + road_offset]:
                if not (0 < road_x < WORLD_W - 1):
                    continue
                for dy in range(-road_reach, road_reach + 1):
                    nx4, ny4 = road_x, cy + dy
                    if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                        if not bool(rm[ny4, nx4]):
                            return (Tool.ROAD, nx4, ny4)

    # === INTER-CLUSTER ROADS (horizontal connectors) ===
    if pop > 100:
        for cy in active_rows_set:
            cols_this_row2 = sorted(cx for cx, c_cy in clusters if abs(c_cy - cy) <= 5)
            for i in range(len(cols_this_row2) - 1):
                c1, c2 = cols_this_row2[i], cols_this_row2[i + 1]
                for road_y in [cy - 3, cy + 3]:
                    if not (0 < road_y < WORLD_H - 1):
                        continue
                    has_road = any(bool(rm[road_y, x]) for x in range(c1, c2 + 1) if ib(x, road_y))
                    if not has_road:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    # === ZONE PLACEMENT (fully reactive) ===
    cand_mask = em & nbr_road & nbr_wire
    # Keep margins
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active cluster centers
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) +
                 np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # === CIVIC SERVICES (reactive to pop) ===
    if pop > 40:
        fire_spots = [(fx, fy) for fy in range(8, 96, 16)
                      for fx in range(8, 116, 18)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px, py) for py in range(10, 94, 20)
                        for px in range(10, 114, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 7), (60, 7), (95, 7),
                         (25, 92), (60, 92), (95, 92)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Nuclear power for denser areas
        nuke_spots = [(5, 15), (5, 50), (5, 85),
                      (115, 15), (115, 50), (115, 85),
                      (30, 5), (60, 5), (90, 5),
                      (30, 94), (60, 94), (90, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94), (5, 5), (115, 5)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 92), (115, 92), (5, 7), (115, 7)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # === PARKS near zones to boost land value ===
    if pop > 100:
        zone_map2 = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map2)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 50)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(4, 0), (-4, 0), (0, 4), (0, -4),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # === FALLBACK: grow roads reactively from existing road edges ===
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # === FALLBACK: grow wire from existing wire ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in a 3x3 grid with wire spines and flanking roads."""
    actions = []
    for px in [20, 60, 100]:
        for py in [25, 50, 75]:
            actions.append((Tool.COALPOWER, px, py))
            for dy in range(-6, 7):
                actions.append((Tool.WIRE, px, py + dy))
            for dy in range(-6, 7):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connectors
    for py in [25, 50, 75]:
        for cx in range(21, 60):
            actions.append((Tool.WIRE, cx, py))
        for cx in range(61, 100):
            actions.append((Tool.WIRE, cx, py))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # All 9 plant anchors (col_x, row_y)
    all_plant_pos = [(px, py) for px in [20, 60, 100] for py in [25, 50, 75]]

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 2
        if pop < 300:  return 3
        if pop < 500:  return 4
        if pop < 750:  return 5
        if pop < 1000: return 6
        if pop < 1500: return 7
        if pop < 2000: return 8
        return 9

    n_active = num_active()
    step_size = len(all_plant_pos) / max(n_active, 1)
    active_plants = [all_plant_pos[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (px, py) in active_plants:
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: VERTICAL WIRE SPINES ----
    spine_half = min(35, 8 + pop // 8)
    for (px, py) in active_plants:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy in range(-6, 7):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 3: HORIZONTAL WIRE connecting plants in same row ----
    y_levels = sorted(set(py for (px, py) in active_plants))
    for yl in y_levels:
        row_plants = sorted([px for (px, py) in active_plants if py == yl])
        for i in range(len(row_plants) - 1):
            x1r, x2r = row_plants[i], row_plants[i + 1]
            for cx in range(x1r + 1, x2r):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]) and not bool(rm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- PHASE 4: VERTICAL WIRE connecting columns ----
    if n_active >= 3:
        x_cols = sorted(set(px for (px, py) in active_plants))
        for xc in x_cols:
            col_plants = sorted([py for (px, py) in active_plants if px == xc])
            for i in range(len(col_plants) - 1):
                y1c, y2c = col_plants[i], col_plants[i + 1]
                for cy in range(y1c + 1, y2c):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]) and not bool(rm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # ---- PHASE 5: FLANKING ROADS alongside wire spines ----
    for (px, py) in active_plants:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        rl, rr = px - 1, px + 1
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(px, r) and bool(wm[r, px])]
        for wr in wire_rows:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- PHASE 6: HORIZONTAL ROADS at each y-level ----
    if pop > 10 or step > 50:
        for yl in y_levels:
            row_plants = sorted([px for (px, py) in active_plants if py == yl])
            if not row_plants:
                continue
            xl = row_plants[0] - 2
            xr = row_plants[-1] + 2
            for horiz_y in [yl - 5, yl + 5]:
                if not (0 <= horiz_y < WORLD_H):
                    continue
                for cx in range(max(2, xl), min(WORLD_W - 2, xr + 1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- PHASE 7: VERTICAL CROSS ROADS connecting y levels ----
    if pop > 40 or step > 150:
        x_cols = sorted(set(px for (px, py) in active_plants))
        for xc in x_cols:
            for rx in [xc - 3, xc + 3]:
                if not (0 < rx < WORLD_W - 1):
                    continue
                for i in range(len(y_levels) - 1):
                    y1v = y_levels[i]
                    y2v = y_levels[i + 1]
                    for cy in range(y1v - 5, y2v + 6):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_road = dilate(rm, 3)
    near_power = dilate(wm | pm, 5)

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 8: ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Don't place ON wire/plant rows
    for (px, py) in active_plants:
        cand_mask[py, :] = False
        cand_mask[:, px] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest active plant anchor
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_plants:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7 + pop) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- PHASE 9: EXTEND ROADS from existing roads near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 10: WIRE extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    power_src = wm | pm
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        else: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d, best_k = 1e9, 0
        stride = max(1, len(uzxs) // 30)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d, best_k = d, i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 11: ROAD extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        else: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d, best_k = 1e9, 0
        stride = max(1, len(usxs) // 30)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d, best_k = d, i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- PHASE 12: CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(10, 95, 18) for fx in range(10, 115, 22)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_spots = [(px2, py2) for py2 in range(12, 92, 20) for px2 in range(12, 112, 25)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150:
        zone_arr_y, zone_arr_x = np.where(zone_tiles)
        if len(zone_arr_x) > 0:
            for i in range(min(len(zone_arr_x), 50)):
                k = (step * 3 + i * 17) % len(zone_arr_x)
                zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 500:
        stadium_spots = [(sx, sy) for sy in range(15, 90, 30) for sx in range(15, 110, 35)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuke_spots = [(5, 5), (115, 5), (5, 95), (115, 95),
                      (60, 5), (60, 95), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
    if len(zone_arr_x2) > 0:
        k = (step * 19) % len(zone_arr_x2)
        zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in a diamond pattern with wire/road stubs."""
    actions = []
    # 4 strategic plants to bootstrap power across the map
    plants = [(30, 30), (90, 30), (30, 70), (90, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire stubs in 4 directions
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            actions.append((Tool.WIRE, px+dx, py+dy))
        # Road stubs
        for dx, dy in [(3,0),(-3,0),(0,3),(0,-3)]:
            actions.append((Tool.ROAD, px+dx, py+dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ── CLUSTER GRID ──────────────────────────────────────────────────────────
    # 4x3 = 12 clusters covering the map, activated progressively
    ALL_CLUSTERS = [
        (15, 20), (45, 20), (75, 20), (105, 20),
        (15, 50), (45, 50), (75, 50), (105, 50),
        (15, 80), (45, 80), (75, 80), (105, 80),
    ]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 3
        if pop < 300:   return 4
        if pop < 600:   return 6
        if pop < 1000:  return 8
        if pop < 2000:  return 10
        return 12

    active_clusters = ALL_CLUSTERS[:num_active()]

    # ── ZONE MIX ──────────────────────────────────────────────────────────────
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ── EXPAND MASK HELPER ────────────────────────────────────────────────────
    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return result
        # Use simple loop over small radius
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 3)
    nbr_wire = expand_mask(wm | pm, 7)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ── PHASE TRACKER ─────────────────────────────────────────────────────────
    # Rotate through phases to avoid getting stuck
    if 'phase' not in state:
        state['phase'] = 0
    state['phase'] = (state['phase'] + 1) % 8

    phase = state['phase']

    # ── 1. ENSURE POWER PLANTS ────────────────────────────────────────────────
    for cx, cy in active_clusters:
        x0, x1 = max(0, cx - 8), min(WORLD_W, cx + 9)
        y0, y1 = max(0, cy - 8), min(WORLD_H, cy + 9)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            # Find nearest empty spot
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ── 2. EXTEND WIRE FROM EACH PLANT ───────────────────────────────────────
    spine_reach = min(22, 8 + pop // 25)
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        # Find plant nearest to each active cluster and extend wire
        for cx, cy in active_clusters:
            # Find the plant for this cluster
            dists = np.abs(plant_xs - cx) + np.abs(plant_ys - cy)
            best_i = int(np.argmin(dists))
            px2, py2 = int(plant_xs[best_i]), int(plant_ys[best_i])
            # Extend wire in all 4 directions
            for sign in [-1, 1]:
                # Horizontal
                for dist in range(1, spine_reach + 1):
                    nx, ny = px2 + sign * dist, py2
                    if not ib(nx, ny) or bool(pm[ny, nx]):
                        break
                    if bool(em[ny, nx]) and not bool(wm[ny, nx]):
                        return (Tool.WIRE, nx, ny)
                # Vertical
                for dist in range(1, spine_reach + 1):
                    nx, ny = px2, py2 + sign * dist
                    if not ib(nx, ny) or bool(pm[ny, nx]):
                        break
                    if bool(em[ny, nx]) and not bool(wm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ── 3. CONNECT CLUSTERS WITH WIRE HORIZONTALLY ───────────────────────────
    cluster_rows_set = sorted(set(cy for cx, cy in active_clusters))
    cluster_cols_set = sorted(set(cx for cx, cy in active_clusters))

    for cy_row in cluster_rows_set:
        row_cls = sorted([cx for cx, cy in active_clusters if cy == cy_row])
        for i in range(len(row_cls) - 1):
            c1x, c2x = row_cls[i], row_cls[i + 1]
            # Check connectivity
            connected = all(
                bool(wm[cy_row, x]) or bool(pm[cy_row, x])
                for x in range(c1x, c2x + 1) if ib(x, cy_row)
            )
            if not connected:
                for x in range(c1x, c2x + 1):
                    if ib(x, cy_row) and bool(em[cy_row, x]) and not bool(pm[cy_row, x]):
                        return (Tool.WIRE, x, cy_row)

    # ── 4. CONNECT CLUSTERS WITH WIRE VERTICALLY ─────────────────────────────
    for cx_col in cluster_cols_set:
        col_cls = sorted([cy for cx, cy in active_clusters if cx == cx_col])
        for i in range(len(col_cls) - 1):
            c1y, c2y = col_cls[i], col_cls[i + 1]
            connected = all(
                bool(wm[y, cx_col]) or bool(pm[y, cx_col])
                for y in range(c1y, c2y + 1) if ib(cx_col, y)
            )
            if not connected:
                for y in range(c1y, c2y + 1):
                    if ib(cx_col, y) and bool(em[y, cx_col]) and not bool(pm[y, cx_col]):
                        return (Tool.WIRE, cx_col, y)

    # ── 5. BUILD ROAD GRID AROUND EACH CLUSTER ───────────────────────────────
    road_reach = min(18, 6 + pop // 40)
    for cx, cy in active_clusters:
        # Roads at offsets ±3 and ±6 from cluster center (both axes)
        for road_offset in [3, 6, -3, -6]:
            # Horizontal road (varying x, fixed y = cy + offset)
            road_y = cy + road_offset
            if 2 <= road_y < WORLD_H - 2:
                for dx in range(-road_reach, road_reach + 1):
                    nx, ny = cx + dx, road_y
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and not bool(rm[ny, nx]):
                        return (Tool.ROAD, nx, ny)
            # Vertical road (fixed x = cx + offset, varying y)
            road_x = cx + road_offset
            if 2 <= road_x < WORLD_W - 2:
                for dy in range(-road_reach, road_reach + 1):
                    nx, ny = road_x, cy + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and not bool(rm[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # ── 6. INTER-CLUSTER ROADS ────────────────────────────────────────────────
    if pop > 100:
        for cy_row in cluster_rows_set:
            row_cls = sorted([cx for cx, cy in active_clusters if cy == cy_row])
            for road_off in [-4, 4, -7, 7]:
                ry = cy_row + road_off
                if not (2 <= ry < WORLD_H - 2):
                    continue
                for i in range(len(row_cls) - 1):
                    c1x, c2x = row_cls[i], row_cls[i + 1]
                    has_road = any(bool(rm[ry, x]) for x in range(c1x, c2x + 1) if ib(x, ry))
                    if not has_road:
                        for x in range(c1x, c2x + 1):
                            if ib(x, ry) and bool(em[ry, x]) and not bool(pm[ry, x]):
                                return (Tool.ROAD, x, ry)

    # ── 7. ZONE PLACEMENT ─────────────────────────────────────────────────────
    cand_mask = em & nbr_road & nbr_wire
    # Margin
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to nearest active cluster
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in active_clusters:
            d = np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ── 8. CIVIC SERVICES ─────────────────────────────────────────────────────
    if pop > 60:
        fire_spots = [(fx, fy) for fy in range(8, 95, 18) for fx in range(8, 115, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for py2 in range(10, 92, 20) for px2 in range(10, 114, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(25, 5), (60, 5), (95, 5), (25, 93), (60, 93), (95, 93),
                         (5, 35), (5, 65), (113, 35), (113, 65)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        # Upgrade to nuclear power
        nuke_spots = [(5, 10), (60, 5), (115, 10), (5, 50), (115, 50),
                      (5, 90), (60, 94), (115, 90), (30, 5), (90, 5),
                      (30, 94), (90, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94), (5, 5), (115, 5), (5, 94), (115, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (5, 7), (115, 7), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # Parks to boost land value
    if pop > 200:
        zone_map2 = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map2)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 50)):
                k = (step * 5 + i * 11) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ── 9. FALLBACK: EXTEND ROADS NEAR WIRE ──────────────────────────────────
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ── 10. FALLBACK: EXTEND WIRE FROM EXISTING WIRE ─────────────────────────
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    # ── 11. LAST RESORT: road near any zone ──────────────────────────────────
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (4, 0), (-4, 0)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in a 3x3 grid with wire spines and flanking roads."""
    actions = []
    # 3 columns x 3 rows covering the map well
    for px in [20, 60, 100]:
        for py in [25, 50, 75]:
            actions.append((Tool.COALPOWER, px, py))
            # Wire spine vertically around plant
            for dy in range(-5, 6):
                ny = py + dy
                if 0 <= ny < 100:
                    actions.append((Tool.WIRE, px, ny))
            # Roads flanking wire
            for dy in range(-5, 6):
                ny = py + dy
                if 0 <= ny < 100:
                    if px - 1 >= 0:
                        actions.append((Tool.ROAD, px - 1, ny))
                    if px + 1 < 120:
                        actions.append((Tool.ROAD, px + 1, ny))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% res, 30% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 neighborhoods in a 3x3 grid
    base_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [25, 50, 75]:
            base_anchors.append((col_x, row_y, col_x, col_x - 1, col_x + 1))

    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 3
        if pop < 400:   return 4
        if pop < 700:   return 5
        if pop < 1100:  return 6
        if pop < 1600:  return 7
        if pop < 2200:  return 8
        return 9

    n_active = num_active()
    active_anchors = base_anchors[:n_active]

    # Spine size grows with population
    spine_half = min(35, 10 + pop // 10)

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Try to place plant
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) ----
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-5, 6):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same column X (vertical linking) ----
    # Connect between anchor rows within same column
    col_xs = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
    for cxv in col_xs:
        col_as = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if wc == cxv],
            key=lambda a: a[1]
        )
        for i in range(len(col_as) - 1):
            _, py1, _, _, _ = col_as[i]
            _, py2, _, _, _ = col_as[i + 1]
            for cy in range(py1 + 1, py2):
                if ib(cxv, cy) and bool(em[cy, cxv]) and not bool(pm[cy, cxv]):
                    return (Tool.WIRE, cxv, cy)

    # ---- HORIZONTAL WIRE connecting anchors at same row Y ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_as = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_as) - 1):
            _, _, wc1, _, _ = row_as[i]
            _, _, wc2, _, _ = row_as[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 5) % 3
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels connecting neighborhoods ----
    if pop > 20:
        for yl in y_levels:
            row_as = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_as) < 2:
                continue
            rl1 = row_as[0][3]
            rr_last = row_as[-1][4]
            for horiz_y in [yl - 4, yl + 4]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # Cross-roads connecting the rows vertically
    if pop > 60 and len(y_levels) >= 2:
        for col_x in [20, 60, 100]:
            for yi in range(len(y_levels) - 1):
                y1 = y_levels[yi]
                y2 = y_levels[yi + 1]
                for rx in [col_x - 3, col_x + 3]:
                    if not ib(rx, y1) or not ib(rx, y2):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 15), (35, 15), (65, 15), (95, 15), (115, 15),
            (8, 40), (35, 40), (65, 40), (95, 40), (115, 40),
            (8, 62), (35, 62), (65, 62), (95, 62), (115, 62),
            (8, 85), (35, 85), (65, 85), (95, 85), (115, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (12, 10), (45, 10), (75, 10), (108, 10),
            (12, 35), (45, 35), (75, 35), (108, 35),
            (12, 58), (45, 58), (75, 58), (108, 58),
            (12, 82), (45, 82), (75, 82), (108, 82),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10), (110, 10),
            (10, 90), (50, 90), (90, 90), (110, 90),
            (30, 50), (90, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        # Add nuclear power plants at corners/edges for more power
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        airport_spots = [(55, 6), (55, 92), (5, 48), (113, 48)]
        for (ax, ay) in airport_spots:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        seaport_spots = [(5, 93), (115, 93), (5, 5), (115, 5), (60, 97)]
        for (sx2, sy2) in seaport_spots:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value near zones ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place central coal plant + cross of wires + initial roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross extending from plant
    for x in range(54, 67):
        actions.append((Tool.WIRE, x, 50))
    for y in range(44, 57):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads parallel to wire spines (offset by 2)
    for x in range(54, 67):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    zone_tiles = resm | comm | indm

    # --- NEIGHBORHOOD GRID ---
    # Dense grid of neighborhood centers across the whole map
    # Unlock more neighborhoods as population grows
    all_hoods = []
    for hy in range(15, 95, 18):
        for hx in range(15, 115, 18):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:    return 2
        if pop < 200:   return 4
        if pop < 500:   return 7
        if pop < 1000:  return 10
        if pop < 2000:  return 14
        if pop < 4000:  return 20
        if pop < 7000:  return 28
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: ENSURE POWER PLANTS ---
    # Each active hood should have a coal plant nearby
    if funds > 2000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
            y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Place plant at hood center if empty, else nearby
                for r in range(10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: WIRE GRID ---
    # For each active hood, build wire spines (cross pattern)
    # Wire row at hy, wire col at hx; extent ±15 from center
    for (hx, hy) in active_hoods:
        spine_top  = max(2, hy - 15)
        spine_bot  = min(WORLD_H - 3, hy + 15)
        spine_left = max(2, hx - 15)
        spine_right= min(WORLD_W - 3, hx + 15)

        # Connect plant to wire spine first (vertical spine at hx)
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]
        col_wire  = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        # Extend vertical spine
        if col_wire:
            min_wr = min(col_wire)
            max_wr = max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Connect plant to horizontal wire spine at hy
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]
        row_wire  = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        # Extend horizontal spine
        if row_wire:
            min_wc = min(row_wire)
            max_wc = max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: CONNECT WIRE SPINES BETWEEN ADJACENT HOODS ---
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hx2 <= hx1:
                continue
            if abs(hy1 - hy2) > 6:
                continue
            mid_y = (hy1 + hy2) // 2
            for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                    return (Tool.WIRE, cx, mid_y)

    # --- PHASE 4: ROAD GRID ---
    # Roads run parallel to wire spines, offset by ±2 tiles
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy):
                continue
            if not col_wire:
                continue
            # Subsample for speed
            cyc = step % 5
            for wr in col_wire[cyc::5]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry):
                continue
            if not row_wire:
                continue
            cyc = (step + 2) % 5
            for wc in row_wire[cyc::5]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT ---
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (within 4 tiles of wire/plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: closest active hood + slight density bonus
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Also reward proximity to existing zones (clustering)
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES ---
    if pop > 10:
        fire_grid = [(fx, fy) for fy in range(15, 95, 18)
                     for fx in range(15, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(20, 90, 20)
                       for px2 in range(20, 110, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 5 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 400:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
            y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1000:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from any plant ---
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants arranged across the map with wire/road spines."""
    actions = []
    # Three columns, two rows of power plants
    for px in [20, 60, 100]:
        for py in [25, 65]:
            actions.append((Tool.COALPOWER, px, py))
            # Vertical wire spine
            for dy in range(-8, 9):
                actions.append((Tool.WIRE, px, py + dy))
            # Flanking roads
            for dy in range(-8, 9):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 primary power plant anchor positions (col, row)
    PLANT_ANCHORS = [
        (20, 25), (60, 25), (100, 25),
        (20, 65), (60, 65), (100, 65),
    ]

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 3
        if pop < 500:   return 4
        if pop < 800:   return 5
        if pop < 1200:  return 6
        return 6

    n_active = num_active()
    active_plants = PLANT_ANCHORS[:n_active]

    # ---- ENSURE POWER PLANTS EXIST ----
    for (px, py) in active_plants:
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot
        placed = False
        for r in range(0, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- BUILD VERTICAL WIRE SPINES at each plant column ----
    spine_half = min(35, 10 + pop // 8)
    for (px, py) in active_plants:
        top = max(2, py - spine_half)
        bot = min(WORLD_H - 3, py + spine_half)
        # Check if wire exists in this column
        wire_rows = [r for r in range(top, bot + 1)
                     if ib(px, r) and bool(wm[r, px])]
        if not wire_rows:
            # Place wire near plant
            for dy in range(-2, 3):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            max_wr = max(wire_rows)
            min_wr = min(wire_rows)
            if max_wr < bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting same-row plants ----
    for row_y_idx in [0, 1]:
        row_plants = [(px, py) for (px, py) in active_plants if py == PLANT_ANCHORS[row_y_idx * 3][1]]
        row_plants_sorted = sorted(row_plants, key=lambda a: a[0])
        for i in range(len(row_plants_sorted) - 1):
            x1w = row_plants_sorted[i][0]
            x2w = row_plants_sorted[i + 1][0]
            yw = row_plants_sorted[i][1]
            for cx in range(x1w + 1, x2w):
                if ib(cx, yw) and bool(em[yw, cx]) and not bool(pm[yw, cx]):
                    return (Tool.WIRE, cx, yw)

    # ---- VERTICAL WIRE connecting top row to bottom row (at each column) ----
    col_xs = sorted(set(px for (px, py) in active_plants))
    for cx in col_xs:
        col_plants = sorted([(px, py) for (px, py) in active_plants if px == cx], key=lambda a: a[1])
        for i in range(len(col_plants) - 1):
            y1w = col_plants[i][1]
            y2w = col_plants[i + 1][1]
            mid = (y1w + y2w) // 2
            # Check connectivity gap
            for cy in range(y1w + 1, y2w):
                if ib(cx, cy) and bool(em[cy, cx]) and not bool(pm[cy, cx]):
                    return (Tool.WIRE, cx, cy)

    # ---- BUILD ROAD GRID ----
    # Flanking roads along wire spines
    for (px, py) in active_plants:
        top = max(2, py - spine_half)
        bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(top, bot + 1) if ib(px, r) and bool(wm[r, px])]
        if not wire_rows:
            continue
        cycle = step % 2
        for rl, rr in [(px - 1, px + 1)]:
            for wr in wire_rows[cycle::2]:
                if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                    return (Tool.ROAD, rl, wr)
                if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                    return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at fixed y-levels for cross-connectivity ----
    road_y_levels = [15, 35, 45, 55, 75, 85]
    if pop > 30:
        for ryl in road_y_levels[:max(2, pop // 100 + 2)]:
            for cx in range(2, WORLD_W - 2):
                if ib(cx, ryl) and bool(em[ryl, cx]) and not bool(pm[ryl, cx]):
                    return (Tool.ROAD, cx, ryl)

    # ---- VERTICAL ROADS at fixed x-levels ----
    road_x_levels = [10, 30, 40, 50, 70, 80, 90, 110]
    if pop > 80:
        for rxl in road_x_levels[:max(2, pop // 150 + 2)]:
            for cy in range(2, WORLD_H - 2):
                if ib(rxl, cy) and bool(em[cy, rxl]) and not bool(pm[cy, rxl]):
                    return (Tool.ROAD, rxl, cy)

    # ---- NEIGHBORHOOD EXPANSION: wire to new areas ----
    # Extra plant columns to expand power coverage
    if pop > 400:
        extra_plants = [(40, 25), (80, 25), (40, 65), (80, 65),
                        (20, 45), (60, 45), (100, 45),
                        (20, 85), (60, 85), (100, 85)]
        for (px, py) in extra_plants[:max(0, (pop - 400) // 150)]:
            y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
            x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
            if np.any(pm[y0:y1, x0:x1]):
                continue
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_plants:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.9
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (placed reactively based on pop) ----
    if pop > 60:
        fire_spots = [
            (8, 15), (35, 15), (75, 15), (108, 15),
            (8, 35), (35, 35), (75, 35), (108, 35),
            (8, 55), (35, 55), (75, 55), (108, 55),
            (8, 75), (35, 75), (75, 75), (108, 75),
            (8, 92), (35, 92), (75, 92), (108, 92),
            (22, 5), (55, 5), (88, 5),
            (22, 45), (55, 45), (88, 45),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 30), (45, 30), (75, 30), (105, 30),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (15, 70), (45, 70), (75, 70), (105, 70),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10),
            (10, 50), (50, 50), (90, 50),
            (10, 90), (50, 90), (90, 90),
            (30, 30), (70, 30), (30, 70), (70, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94), (10, 6), (110, 6), (30, 94), (90, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5), (60, 3)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- EXTEND WIRE from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants arranged in a cross pattern with wire spines."""
    actions = []
    # Primary power plants at strategic locations
    for px, py in [(20, 20), (100, 20), (20, 80), (100, 80)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spines extending from each plant
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    for dy in range(-4, 5):
        actions.append((Tool.WIRE, 60, 50 + dy))
    for dx in range(-4, 5):
        actions.append((Tool.WIRE, 60 + dx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target ratios: 55% res, 25% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 5x4 grid of neighborhoods = 20 anchor points covering the full map
    col_xs = [12, 36, 60, 84, 108]
    row_ys = [15, 38, 62, 85]
    all_anchors = [(cx, ry) for ry in row_ys for cx in col_xs]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 500:   return 8
        if pop < 750:   return 10
        if pop < 1000:  return 12
        if pop < 1500:  return 15
        if pop < 2000:  return 18
        return 20

    n_active = num_active()
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS near each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot
        for r in range(0, 14):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- BUILD WIRE SPINES: vertical + horizontal through each anchor ----
    spine_half = min(12, 5 + pop // 15)

    # First fill vertical spines
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        for wy in range(spine_top, spine_bot + 1):
            if ib(px, wy) and not bool(pm[wy, px]):
                if bool(em[wy, px]):
                    return (Tool.WIRE, px, wy)

    # Horizontal spines at each anchor y-level
    y_levels = sorted(set(py for (_, py) in active_anchors))
    x_levels = sorted(set(px for (px, _) in active_anchors))

    for yl in y_levels:
        row_anchors = sorted([px for (px, py) in active_anchors if py == yl])
        if len(row_anchors) >= 2:
            x_min = row_anchors[0]
            x_max = row_anchors[-1]
            for cx in range(x_min, x_max + 1):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # Vertical connections between anchor rows in same column
    for xl in x_levels:
        col_anchors = sorted([py for (px, py) in active_anchors if px == xl])
        if len(col_anchors) >= 2:
            for i in range(len(col_anchors) - 1):
                y_start = col_anchors[i]
                y_end = col_anchors[i + 1]
                for cy in range(y_start, y_end + 1):
                    if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                        return (Tool.WIRE, xl, cy)

    # ---- BUILD ROADS flanking wire spines ----
    # Left and right of vertical wire spines
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)

        # Check wire coverage
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue

        cycle = (step + px) % 2
        for side_dx in [-1, 1]:
            rx = px + side_dx
            if not ib(rx, spine_top):
                continue
            for wy in wire_in_col[cycle::2]:
                if ib(rx, wy) and bool(em[wy, rx]) and not bool(pm[wy, rx]):
                    return (Tool.ROAD, rx, wy)

    # ---- HORIZONTAL ROADS at row y-levels (offset by 3 above/below anchor) ----
    if pop > 10:
        for yl in y_levels:
            row_anchors_x = sorted([px for (px, py) in active_anchors if py == yl])
            if len(row_anchors_x) < 2:
                continue
            x_min = row_anchors_x[0] - 1
            x_max = row_anchors_x[-1] + 1
            for horiz_y in [yl - 3, yl + 3]:
                if not ib(x_min, horiz_y) or not ib(x_max, horiz_y):
                    continue
                for cx in range(x_min, x_max + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting row levels ----
    if pop > 40:
        for xl in x_levels:
            for road_dx in [-2, 2]:
                rx = xl + road_dx
                if not ib(rx, 0):
                    continue
                col_anchors_y = sorted([py for (px, py) in active_anchors if px == xl])
                for i in range(len(col_anchors_y) - 1):
                    y_start = col_anchors_y[i] - 3
                    y_end = col_anchors_y[i + 1] + 3
                    for cy in range(y_start, y_end + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    # Road proximity (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/power proximity (within 6 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES based on population ----
    if pop > 40:
        # Fire stations distributed across the map
        fire_spots = []
        for fx in [10, 30, 50, 70, 90, 110]:
            for fy in [10, 33, 55, 77, 95]:
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = []
        for px2 in [15, 45, 75, 105]:
            for py2 in [20, 50, 80]:
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 5), (65, 5), (105, 5), (25, 95), (65, 95), (105, 95)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Add nuclear plants for more power coverage
        nuke_spots = [(8, 8), (112, 8), (8, 92), (112, 92), (60, 5), (60, 95),
                      (8, 50), (112, 50), (35, 5), (85, 5), (35, 95), (85, 95)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 95)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 90), (115, 90), (60, 98), (5, 6), (115, 6)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious multi-neighborhood city builder
# Strategy: Dense grid of neighborhoods across the full map
# Better power/road connectivity, smarter zone ratios, more civic services

def init(obs, state):
    """Bootstrap: two central coal plants + wire cross + roads."""
    actions = []
    # Two power plants near center
    cx1, cy1 = 40, 50
    cx2, cy2 = 80, 50
    actions.append((Tool.COALPOWER, cx1, cy1))
    actions.append((Tool.COALPOWER, cx2, cy2))
    # Wire connecting them horizontally
    for x in range(cx1 + 2, cx2 - 1):
        actions.append((Tool.WIRE, x, cy1))
    # Vertical wires from each plant
    for dy in range(1, 8):
        actions.append((Tool.WIRE, cx1, cy1 - dy))
        actions.append((Tool.WIRE, cx1, cy1 + dy))
        actions.append((Tool.WIRE, cx2, cy2 - dy))
        actions.append((Tool.WIRE, cx2, cy2 + dy))
    # Roads flanking plant 1
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx1 - 2, cy1 + dy))
        actions.append((Tool.ROAD, cx1 + 2, cy1 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 8 cols x 6 rows = 48 neighborhoods ----
    # Spaced 14 apart horizontally, 16 apart vertically
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [10, 26, 42, 58, 74, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 8
        if pop < 800:   return 14
        if pop < 1500:  return 20
        if pop < 3000:  return 28
        if pop < 6000:  return 38
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly across the list
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
        y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center if empty, else nearby
            for r in range(15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: BUILD WIRE CROSS AT EACH HOOD ----
    spine_range = 8
    h_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[h_idx]
    # Vertical spine
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        # Only extend if adjacent to wire/plant
        for adj in [-1, 1]:
            ay = wy + adj
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)
    # Horizontal spine
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj in [-1, 1]:
            ax = wx + adj
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        # Connect to right neighbor (14 apart)
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and hx2 == hx1 + 14:
                mid_y = hy1
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Connect to bottom neighbor (16 apart)
            if hx1 == hx2 and hy2 == hy1 + 16:
                mid_x = hx1
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Roads at hx-1 and hx+1 (flanking vertical spine)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, 0): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Roads at hy-1 and hy+1 (flanking horizontal spine)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(0, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 45% RES, 30% COM, 25% IND
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 22) for py2 in range(18, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(35, 35), (85, 35), (35, 65), (85, 65),
                    (60, 20), (60, 80), (15, 50), (105, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 88), (110, 88), (10, 12), (110, 12), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 5), (75, 5), (45, 93), (75, 93), (5, 45), (5, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop cities ----
    if pop > 2500 and step % 4 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (15, 50), (105, 50), (60, 15), (60, 85)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants + wire grid + seed roads + initial zones"""
    actions = []
    # Three power plants across the map
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Wire connecting them horizontally
    for x in range(18, 103):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at each plant
    for y in range(35, 66):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Seed roads near each plant
    for x in range(12, 30):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for x in range(52, 70):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for x in range(92, 110):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    # Seed initial zones in 3 clusters
    for cx in [20, 60, 100]:
        actions.append((Tool.RESIDENTIAL, cx-3, 47))
        actions.append((Tool.INDUSTRIAL, cx+3, 47))
        actions.append((Tool.COMMERCIAL, cx-3, 53))
        actions.append((Tool.RESIDENTIAL, cx+3, 53))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        # Target: 40% res, 30% com, 30% ind
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Power plants in a dense 3x3 grid ----
    # Plants at 3 columns x 3 rows = 9 plants total
    plant_xs = [20, 60, 100]
    plant_ys = [20, 50, 80]
    for ppy in plant_ys:
        for ppx in plant_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 6), min(WORLD_W, ppx + 7)
            y0, y1 = max(0, ppy - 6), min(WORLD_H, ppy + 7)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire backbone — horizontal spines at plant rows, verticals connecting ----
    wire_rows = plant_ys  # rows 20, 50, 80
    wire_cols = plant_xs  # cols 20, 60, 100

    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                nearest = pxs_arr[np.argmin(np.abs(pys_arr - wr))]
                if ib(int(nearest), wr) and bool(em[wr, int(nearest)]):
                    return (Tool.WIRE, int(nearest), wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right+1]):
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and bool(em[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road grid — roads offset from wire rows/cols ----
    # Roads 5 tiles above/below wire rows, and left/right of wire cols
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 5)
        road_rows.append(wr + 5)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 5)
        road_cols.append(wc + 5)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement closed-loop ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Protect infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Want zones to be close enough to form clusters but not on top of each other
            # Penalize being too far (want density) but also too close (overlap)
            zone_dist = np.abs(min_zone_dist - 4.0)  # ideal spacing ~4 tiles
        else:
            zone_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 2.0 + zone_dist * 0.5
        order = np.argsort(score)
        off = (step * 7 + pop % 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 20:
        fire_spots = [(fx, fy) for fy in range(8, 96, 12) for fx in range(8, 114, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_spots = [(px2, py2) for py2 in range(10, 94, 14) for px2 in range(10, 112, 24)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_spots = [(pkx, pky) for pky in range(12, 90, 10) for pkx in range(12, 110, 14)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 500:
        stadium_spots = [(sx, sy) for sy in range(15, 88, 25) for sx in range(15, 105, 30)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        airport_spots = [
            (10, 10), (90, 10), (10, 85), (90, 85),
            (50, 5), (50, 90),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1200:
        seaport_spots = [
            (5, 50), (110, 50), (60, 5), (60, 90),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: place road near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6,0),(-6,0),(0,6),(0,-6),(4,0),(-4,0),(0,4),(0,-4)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Dense grid city with 6 coal plants forming a backbone power grid
# 3x3 neighborhood grid covering most of the map
# Mixed zoning with emphasis on balanced R/C/I
# Roads form a tight grid, wire runs along major axes
# Civic services placed early and often

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spine + initial road grid at center"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 40, 45))
    actions.append((Tool.COALPOWER, 80, 45))
    # Wire connecting them horizontally
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 45))
    # Vertical wire spines from each plant
    for y in range(35, 45):
        actions.append((Tool.WIRE, 40, y))
        actions.append((Tool.WIRE, 80, y))
    for y in range(46, 56):
        actions.append((Tool.WIRE, 40, y))
        actions.append((Tool.WIRE, 80, y))
    # Initial road grid near center
    for x in range(34, 90, 6):
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 50))
    for y in range(38, 55):
        actions.append((Tool.ROAD, 36, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 84, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- GRID-BASED CITY DESIGN ----
    # 6 power plants arranged in 2 rows of 3
    # Wire grid at fixed corridors
    # Road grid parallel to wire corridors
    # Dense 3x3 zone blocks filling the spaces

    # Power plant locations
    plant_locs = [(20, 20), (60, 20), (100, 20),
                  (20, 70), (60, 70), (100, 70)]

    # Wire corridors: horizontal at y=20,45,70 and vertical at x=20,45,70,95
    wire_rows = [20, 45, 70]
    wire_cols = [20, 45, 70, 95]

    # Road corridors: parallel to wire, offset by 3
    # Between wire corridors, roads at every 6 tiles
    road_rows = [17, 23, 42, 48, 67, 73, 90]
    road_cols = [15, 27, 39, 51, 63, 75, 87, 105]

    # ---- ENSURE POWER PLANTS ----
    # Check each plant location - if no plant nearby, place one
    for px, py in plant_locs:
        x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
        y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find empty spot near target
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- WIRE NETWORK ----
    # Build horizontal wire corridors first, then vertical
    # Priority: extend from existing wire/plant

    wire_phase = step % 6

    if wire_phase < 2:
        # Build horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if ib(wx, wr) and not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    # Check if adjacent to existing wire or plant
                    for adx in [-1, 1]:
                        ax = wx + adx
                        if ib(ax, wr) and (bool(wm[wr, ax]) or bool(pm[wr, ax])):
                            return (Tool.WIRE, wx, wr)

    elif wire_phase < 4:
        # Build vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if ib(wc, wy) and not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    for ady in [-1, 1]:
                        ay = wy + ady
                        if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                            return (Tool.WIRE, wc, wy)

    else:
        # Connect wire corridors: place wire to bridge gaps
        # Find horizontal gap: scan row, find two wire cells with gap
        for wr in wire_rows:
            last_w = -1
            for wx in range(0, WORLD_W):
                if bool(wm[wr, wx]) or bool(pm[wr, wx]):
                    if last_w >= 0 and wx - last_w > 1:
                        # Fill the gap
                        mid = (last_w + wx) // 2
                        if bool(em[wr, mid]):
                            return (Tool.WIRE, mid, wr)
                    last_w = wx

    # ---- ROAD NETWORK ----
    road_phase = step % 4

    if road_phase == 0:
        # Horizontal roads
        for rr in road_rows:
            if not ib(0, rr):
                continue
            for rx in range(1, WORLD_W - 1):
                if ib(rx, rr) and bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    # Check adjacent road
                    for adx in [-1, 1]:
                        ax = rx + adx
                        if ib(ax, rr) and bool(rm[rr, ax]):
                            return (Tool.ROAD, rx, rr)

    elif road_phase == 1:
        # Vertical roads
        for rc in road_cols:
            if not ib(rc, 0):
                continue
            for ry in range(1, WORLD_H - 1):
                if ib(rc, ry) and bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    for ady in [-1, 1]:
                        ay = ry + ady
                        if ib(rc, ay) and bool(rm[ay, rc]):
                            return (Tool.ROAD, rc, ry)

    elif road_phase == 2:
        # Build initial road segments adjacent to plants/wires
        # Start roads from wire corridors
        for wr in wire_rows:
            for offset in [-3, 3]:
                rr = wr + offset
                if not ib(0, rr):
                    continue
                # Find a seed: road adjacent to vertical road corridor or plant
                for rx in range(1, WORLD_W - 1):
                    if ib(rx, rr) and bool(em[rr, rx]) and not bool(pm[rr, rx]):
                        # Check if wire exists above/below
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            # Check adjacent road exists
                            for adx in [-1, 1]:
                                ax = rx + adx
                                if ib(ax, rr) and bool(rm[rr, ax]):
                                    return (Tool.ROAD, rx, rr)
                            # Or start a new road here if there's a road col nearby
                            for rc in road_cols:
                                if abs(rx - rc) <= 1 and ib(rc, rr) and bool(rm[ry, rc] if False else False):
                                    pass
                            if rx in road_cols and bool(em[rr, rx]):
                                return (Tool.ROAD, rx, rr)

    else:
        # Connect vertical roads between horizontal road rows
        for rc in road_cols:
            for ry in range(1, WORLD_H - 1):
                if ib(rc, ry) and bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    for ady in [-1, 1]:
                        ay = ry + ady
                        if ib(rc, ay) and bool(rm[ay, rc]):
                            return (Tool.ROAD, rc, ry)

    # ---- BUILD ROAD PROXIMITY MAP ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power proximity map
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- ZONE PLACEMENT ----
    # Tool selection: aim for 40% RES, 30% COM, 30% IND
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr2 = res_count / t
        # Keep a good commercial/industrial base
        if pop < 100:
            # Early: mostly residential with some industrial
            if ir < 0.35:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        elif pop < 500:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        tool = pick_tool()
        # Prefer locations closer to center of map for denser city
        cx_center = WORLD_W // 2
        cy_center = WORLD_H // 2
        # Score: distance to center (closer = better) + small random variation
        dist_to_center = np.abs(cxs - cx_center) + np.abs(cys - cy_center)
        # Vary by step to avoid always picking same location
        noise = ((cxs * 3 + cys * 7 + step * 11) % 20).astype(float)
        scores = dist_to_center.astype(float) + noise
        order = np.argsort(scores)
        for i in range(min(len(order), 500)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    # Place fire stations in a grid
    if pop > 50:
        fire_grid = [
            (30, 30), (60, 30), (90, 30),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (30, 65), (60, 65), (90, 65),
            (20, 85), (60, 85), (100, 85),
        ]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_grid = [
            (25, 25), (55, 25), (85, 25), (110, 25),
            (10, 50), (40, 50), (70, 50), (100, 50),
            (25, 75), (55, 75), (85, 75),
            (10, 90), (60, 90), (110, 90),
        ]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(30, 40), (80, 40), (30, 60), (80, 60),
                    (55, 25), (55, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(10, 85), (110, 85), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 93), (70, 93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 150 and step % 7 == 0:
        pys, pxs = np.where(em & nbr_road & nbr_power)
        if len(pxs) > 0:
            idx = (step * 17 + 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend roads from existing road ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        k0 = (step * 13) % len(road_xs2)
        for i in range(min(len(road_xs2), 80)):
            k = (k0 + i * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    all_power = wm | pm
    pow_ys, pow_xs = np.where(all_power)
    if len(pow_xs) > 0:
        k0 = (step * 11) % len(pow_xs)
        for i in range(min(len(pow_xs), 60)):
            k = (k0 + i * 5) % len(pow_xs)
            wx2, wy2 = int(pow_xs[k]), int(pow_ys[k])
            for dx3, dy3 in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FINAL FALLBACK: new coal plant ----
    # Try to place near unpowered zones
    unpowered_zone = (resm | comm | indm) & ~nbr_power
    uys, uxs = np.where(unpowered_zone)
    if len(uxs) > 0:
        k = (step * 7) % len(uxs)
        tx, ty = int(uxs[k]), int(uys[k])
        for r in range(2, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = tx + dx, ty + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

# Ambitious multi-neighborhood city builder
# Strategy: Dense grid of neighborhoods across the full map
# Each neighborhood has its own power plant, wire grid, road grid, and zones
# Progressive expansion based on population

def init(obs, state):
    """Bootstrap: two coal plants + wire connections + initial roads."""
    actions = []
    # Plant 1: left side
    actions.append((Tool.COALPOWER, 20, 50))
    # Wire horizontal from plant 1
    for dx in range(1, 8):
        actions.append((Tool.WIRE, 20 + dx, 50))
    # Wire vertical from plant 1
    for dy in range(-4, 5):
        if dy != 0:
            actions.append((Tool.WIRE, 20, 50 + dy))
    # Roads flanking wire
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, 19, 50 + dy))
        actions.append((Tool.ROAD, 21, 50 + dy))
    # Plant 2: right side
    actions.append((Tool.COALPOWER, 80, 50))
    for dx in range(-4, 5):
        if dx != 0:
            actions.append((Tool.WIRE, 80 + dx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Dense neighborhood grid: 8 cols x 7 rows = 56 neighborhoods
    # Spaced 14 apart horizontally, 13 apart vertically
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [10, 23, 36, 50, 63, 76, 89]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 30:    return 2
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 700:   return 14
        if pop < 1500:  return 22
        if pop < 3000:  return 32
        if pop < 6000:  return 44
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly across the grid
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # ---- PHASE 1: ENSURE POWER PLANTS at each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center or nearby empty spot
            for r in range(10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE CROSS from each plant through hood ----
    spine_range = 6
    # Round-robin through hoods
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant to this hood
    px_best, py_best = hx, hy
    best_pd = 999
    for yr in range(max(0, hy-7), min(WORLD_H, hy+8)):
        for xr in range(max(0, hx-7), min(WORLD_W, hx+8)):
            if bool(pm[yr, xr]):
                d = abs(xr - hx) + abs(yr - hy)
                if d < best_pd:
                    best_pd = d
                    px_best, py_best = xr, yr

    # Wire vertical spine at plant x
    for dy in range(-spine_range, spine_range + 1):
        wy = py_best + dy
        if not ib(px_best, wy): continue
        if bool(wm[wy, px_best]) or bool(pm[wy, px_best]): continue
        if not bool(em[wy, px_best]): continue
        # Check adjacency to existing wire/plant
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(px_best, ay) and (bool(wm[ay, px_best]) or bool(pm[ay, px_best])):
                return (Tool.WIRE, px_best, wy)

    # Wire horizontal spine at plant y
    for dx in range(-spine_range, spine_range + 1):
        wx = px_best + dx
        if not ib(wx, py_best): continue
        if bool(wm[py_best, wx]) or bool(pm[py_best, wx]): continue
        if not bool(em[py_best, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, py_best) and (bool(wm[py_best, ax]) or bool(pm[py_best, ax])):
                return (Tool.WIRE, wx, py_best)

    # ---- PHASE 3: WIRE MESH connecting adjacent hoods ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Connect right neighbor
            if hy1 == hy2 and hx2 == hx1 + 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Connect bottom neighbor
            if hx1 == hx2 and hy2 == hy1 + 13:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods), 1) not in range(max(1, len(active_hoods) // 2 + 1)):
            continue
        # Roads flanking vertical wire at hx
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Only if wire/plant exists at this row on the spine
                    if ib(hx, ry) and (bool(wm[ry, hx]) or bool(pm[ry, hx])):
                        return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal wire at hy
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if ib(rcx, hy) and (bool(wm[hy, rcx]) or bool(pm[hy, rcx])):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 35% RES, 35% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        if rr < 0.33:
            return Tool.RESIDENTIAL
        return Tool.COMMERCIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road coverage mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power coverage mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        # Fire stations on 20-tile grid
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 20) for fy in range(15, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 22) for py2 in range(18, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 50), (75, 50), (55, 35), (65, 65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5),
                    (30, 95), (90, 95), (30, 5), (90, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 45), (6, 65),
                    (106, 45), (106, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for large cities ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (10, 50), (110, 50), (60, 10), (60, 90)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant for uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

