def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Track phase in state
    if 'phase' not in state:
        state['phase'] = 0
        state['left_spine_done'] = False
        state['right_spine_done'] = False
        state['center_started'] = False

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Two main clusters: LEFT (center ~x=32) and RIGHT (center ~x=91)
    # Plus a CENTER cluster at x=60 when city grows

    # Cluster configs: (wire_col, road_l, road_r, plant_x, plant_y, spine_top, spine_bot)
    clusters = [
        {'wire_col': 32, 'road_l': 31, 'road_r': 33, 'plant_x': 30, 'plant_y': 50,
         'spine_top': 30, 'spine_bot': 70},
        {'wire_col': 91, 'road_l': 90, 'road_r': 92, 'plant_x': 89, 'plant_y': 50,
         'spine_top': 30, 'spine_bot': 70},
    ]

    # Add center cluster when pop grows
    if obs.city_pop > 300 or total_zones > 15:
        clusters.append({
            'wire_col': 61, 'road_l': 60, 'road_r': 62, 'plant_x': 59, 'plant_y': 50,
            'spine_top': 30, 'spine_bot': 70
        })

    # Add even more clusters when city is large
    if obs.city_pop > 800 or total_zones > 40:
        clusters.append({
            'wire_col': 15, 'road_l': 14, 'road_r': 16, 'plant_x': 13, 'plant_y': 50,
            'spine_top': 35, 'spine_bot': 65
        })
        clusters.append({
            'wire_col': 105, 'road_l': 104, 'road_r': 106, 'plant_x': 107, 'plant_y': 50,
            'spine_top': 35, 'spine_bot': 65
        })

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        # Target: 30% industrial, 30% commercial, 40% residential
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Build/extend plants and spines ---
    for cl in clusters:
        wc = cl['wire_col']
        pl_x, pl_y = cl['plant_x'], cl['plant_y']
        s_top = cl['spine_top']
        s_bot = cl['spine_bot']

        # Ensure plant exists
        if in_bounds(pl_x, pl_y) and not bool(pm[pl_y, pl_x]):
            # Check if this plant location is empty enough
            if bool(em[pl_y, pl_x]):
                return (Tool.COALPOWER, pl_x, pl_y)

        # Build vertical wire spine
        wire_rows = [r for r in range(WORLD_H) if 0 <= wc < WORLD_W and bool(wm[r, wc])]
        if not wire_rows:
            # Seed wire adjacent to plant
            for dy in range(-2, 3):
                ny = pl_y + dy
                if in_bounds(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            # Grow based on population
            pop_ext = min(20, obs.city_pop // 30)
            ext_top = max(s_top, pl_y - 10 - pop_ext)
            ext_bot = min(s_bot, pl_y + 10 + pop_ext)
            if max_wr < ext_bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > ext_top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

        # Build flanking roads
        rl, rr = cl['road_l'], cl['road_r']
        wire_rows2 = [r for r in range(WORLD_H) if 0 <= wc < WORLD_W and bool(wm[r, wc])]
        if wire_rows2:
            step_mod = obs.step % 4
            rows_batch = wire_rows2[::2] if step_mod < 2 else wire_rows2[1::2]
            for wr in rows_batch:
                if in_bounds(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                    return (Tool.ROAD, rl, wr)
                if in_bounds(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                    return (Tool.ROAD, rr, wr)

    # --- Horizontal connector roads between clusters when pop is high ---
    if obs.city_pop > 200:
        # Connect left cluster road (x=33) to center cluster road (x=60) at y=50
        conn_y = 50
        for cx in range(34, 60):
            if in_bounds(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                return (Tool.ROAD, cx, conn_y)
        # Wire bridge too
        for cx in range(34, 60):
            if in_bounds(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                return (Tool.WIRE, cx, conn_y)

    if obs.city_pop > 500:
        # Connect center to right
        conn_y = 50
        for cx in range(63, 90):
            if in_bounds(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                return (Tool.ROAD, cx, conn_y)
        for cx in range(63, 90):
            if in_bounds(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                return (Tool.WIRE, cx, conn_y)

    # --- Proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Place zones near roads and power
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Distribute across all cluster wire columns
        wire_cols = [cl['wire_col'] for cl in clusters]
        # Find closest wire col for each candidate
        min_dists = np.array([np.min([abs(cxs - wc) for wc in wire_cols], axis=0)]).flatten()
        # Add vertical penalty
        center_y = 50
        vert_dist = np.abs(cys - center_y) // 4
        dists = min_dists + vert_dist

        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # Extend roads along wire rows from existing roads
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 25)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Services scaled to population
    if obs.city_pop > 200:
        service_spots = [(28, 40), (34, 40), (87, 40), (93, 40)]
        for sx, sy in service_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if obs.city_pop > 500:
        police_spots = [(28, 60), (34, 60), (87, 60), (93, 60)]
        for sx, sy in police_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if obs.city_pop > 1000:
        # Stadiums boost commercial demand
        for sx, sy in [(60, 35), (60, 65)]:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Expand wire laterally as fallback
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central plant + cross wires + seed roads."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from center
    for x in range(50, 71):
        actions.append((Tool.WIRE, x, 50))
    for y in range(40, 61):
        actions.append((Tool.WIRE, 60, y))
