def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 50% RES, 25% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 neighborhood centers spread across map
    neighborhoods = [
        (20, 20), (60, 15), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 85), (100, 80),
    ]

    # Power plant targets - one per neighborhood + extras
    plant_targets = [
        (20, 20), (60, 15), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 85), (100, 80),
        (40, 35), (80, 35), (40, 65), (80, 65),
        (10, 35), (110, 35), (10, 65), (110, 65),
    ]

    # Phase 1: ensure power plants at key locations (if funded)
    if funds > 2000:
        for ppx, ppy in plant_targets:
            if not ib(ppx, ppy):
                continue
            # Check if plant already nearby
            found = False
            for dy in range(-5, 6):
                for dx in range(-5, 6):
                    nx, ny = ppx + dx, ppy + dy
                    if ib(nx, ny) and pm[ny, nx]:
                        found = True
                        break
                if found:
                    break
            if not found:
                return (Tool.COALPOWER, ppx, ppy)

    # Wire grid: connect all power plants with horizontal+vertical lines
    # Use a dense wire grid every 5 rows/cols
    wire_rows = list(range(5, WORLD_H - 4, 5))
    wire_cols = list(range(5, WORLD_W - 4, 5))

    # Build horizontal wire lines - extend existing ones
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Seed from a known plant location
            seeded = False
            for ppx, ppy in plant_targets:
                if abs(ppy - wr) <= 2 and ib(ppx, wr) and (em[wr, ppx] or wm[wr, ppx]):
                    if em[wr, ppx]:
                        return (Tool.WIRE, ppx, wr)
                    seeded = True
                    break
            if not seeded:
                if ib(60, wr) and em[wr, 60]:
                    return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        for x in range(left, right + 1):
            if ib(x, wr) and em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Build vertical wire lines
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot + 1):
            if ib(wc, y) and em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # Road grid: roads run between wire rows/cols (offset by ~2-3)
    # Roads every 6 tiles offset from wire grid
    road_rows = []
    road_cols = []
    for wr in wire_rows:
        for off in [-2, 3]:
            r = wr + off
            if 3 < r < WORLD_H - 3:
                road_rows.append(r)
    for wc in wire_cols:
        for off in [-2, 3]:
            c = wc + off
            if 3 < c < WORLD_W - 3:
                road_cols.append(c)
    road_rows = sorted(set(road_rows))
    road_cols = sorted(set(road_cols))

    # Build horizontal roads
    for rr in road_rows:
        row_road = rm[rr, :]
        if not row_road.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            # Try seeding near a neighborhood
            for nx, ny in neighborhoods:
                if abs(ny - rr) <= 3 and ib(nx, rr) and em[rr, nx] and not pm[rr, nx]:
                    return (Tool.ROAD, nx, rr)
            continue
        indices = np.where(row_road)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and ib(left - 1, rr) and em[rr, left - 1] and not pm[rr, left - 1]:
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 3 and ib(right + 1, rr) and em[rr, right + 1] and not pm[rr, right + 1]:
            return (Tool.ROAD, right + 1, rr)
        for x in range(left, right + 1):
            if ib(x, rr) and em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            for nx, ny in neighborhoods:
                if abs(nx - rc) <= 3 and ib(rc, ny) and em[ny, rc] and not pm[ny, rc]:
                    return (Tool.ROAD, rc, ny)
            continue
        indices = np.where(col_road)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and ib(rc, top - 1) and em[top - 1, rc] and not pm[top - 1, rc]:
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 3 and ib(rc, bot + 1) and em[bot + 1, rc] and not pm[bot + 1, rc]:
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top, bot + 1):
            if ib(rc, y) and em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # Zone placement: find good locations near roads and wires
    # Compute "near road" mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute "near wire or plant" mask
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H - 3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: prefer near neighborhoods, cluster near existing zones
        min_nbhd = np.full(len(cxs_arr), 999999.0)
        for nx, ny in neighborhoods:
            d = (np.abs(cxs_arr - nx).astype(float) +
                 np.abs(cys_arr - ny).astype(float))
            min_nbhd = np.minimum(min_nbhd, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                # Balance: cluster near existing but also spread to neighborhoods
                zone_score = zone_dist * 0.3 + min_nbhd * 0.7
            else:
                zone_score = min_nbhd
        else:
            zone_score = min_nbhd

        order = np.argsort(zone_score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # Civic services based on population
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(15, 95, 18)
                     for fx in range(15, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(20, 90, 20)
                       for px2 in range(20, 110, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(10, 95, 8)
                     for pkx in range(10, 115, 8)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 400 and funds > 3000:
        stadium_locs = [
            (20, 15), (60, 10), (100, 15),
            (20, 85), (60, 90), (100, 85),
            (10, 50), (110, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 30), (85, 30), (35, 70), (85, 70),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            found = False
            for dy in range(-5, 6):
                for dx in range(-5, 6):
                    nx2, ny2 = npx + dx, npy + dy
                    if ib(nx2, ny2) and pm[ny2, nx2]:
                        found = True
                        break
                if found:
                    break
            if not found and ib(npx, npy) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500 and funds > 3000:
        airport_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 800 and funds > 2000:
        seaport_locs = [
            (5, 50), (115, 50), (60, 5), (60, 95),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend wires from plants
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 80)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: place roads near wires
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 100)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0, 3), (0, -3), (3, 0), (-3, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power plant with wire cross and road seeds"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from center
    for x in range(50, 71):
        actions.append((Tool.WIRE, x, 50))
    for y in range(40, 61):
        actions.append((Tool.WIRE, 60, y))
    # Four quadrant power plants
    actions.append((Tool.COALPOWER, 25, 25))
    actions.append((Tool.COALPOWER, 95, 25))
    actions.append((Tool.COALPOWER, 25, 75))
    actions.append((Tool.COALPOWER, 95, 75))
    # Seed roads in a grid pattern near center
    for x in range(48, 73):
        actions.append((Tool.ROAD, x, 43))
    for x in range(48, 73):
        actions.append((Tool.ROAD, x, 57))
    for y in range(43, 58):
        actions.append((Tool.ROAD, 48, y))
    for y in range(43, 58):
        actions.append((Tool.ROAD, 72, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone ratios: 50% RES, 30% COM, 20% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 neighborhoods across the map
    neighborhoods = [
        (20, 20), (60, 15), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 85), (100, 80),
    ]

    # Power plant targets - one per neighborhood + extras
    plant_targets = [
        (20, 20), (60, 15), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 85), (100, 80),
        (40, 35), (80, 35), (40, 65), (80, 65),
    ]

    # Phase 1: ensure power plants
    if funds > 2500:
        for ppx, ppy in plant_targets:
            if not ib(ppx, ppy):
                continue
            found = False
            for dy in range(-7, 8):
                for dx in range(-7, 8):
                    nx, ny = ppx + dx, ppy + dy
                    if ib(nx, ny) and pm[ny, nx]:
                        found = True
                        break
                if found:
                    break
            if not found:
                return (Tool.COALPOWER, ppx, ppy)

    # Wire grid: horizontal every 5 rows, vertical every 5 cols
    wire_rows = list(range(5, 96, 5))
    wire_cols = list(range(5, 116, 5))

    # Build horizontal wire lines
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            if ib(60, wr) and em[wr, 60]:
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        for x in range(left, right + 1):
            if ib(x, wr) and em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Build vertical wire lines
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot + 1):
            if ib(wc, y) and em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # Road grid: between wire lines
    road_rows = []
    road_cols = []
    for wr in wire_rows:
        for off in [-2, 2]:
            r = wr + off
            if 3 < r < WORLD_H - 3:
                road_rows.append(r)
    for wc in wire_cols:
        for off in [-2, 2]:
            c = wc + off
            if 3 < c < WORLD_W - 3:
                road_cols.append(c)
    road_rows = sorted(set(road_rows))
    road_cols = sorted(set(road_cols))

    # Build horizontal roads
    for rr in road_rows:
        row_road = rm[rr, :]
        if not row_road.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_road)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and ib(left - 1, rr) and em[rr, left - 1] and not pm[rr, left - 1]:
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 3 and ib(right + 1, rr) and em[rr, right + 1] and not pm[rr, right + 1]:
            return (Tool.ROAD, right + 1, rr)
        for x in range(left, right + 1):
            if ib(x, rr) and em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_road)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and ib(rc, top - 1) and em[top - 1, rc] and not pm[top - 1, rc]:
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 3 and ib(rc, bot + 1) and em[bot + 1, rc] and not pm[bot + 1, rc]:
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top, bot + 1):
            if ib(rc, y) and em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # Zone placement - closed loop based on current state
    # Compute "near road" mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute "near wire or plant" mask (within 3 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H - 3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: spread to neighborhoods, cluster near existing zones
        nbhd_score = np.full(len(cxs_arr), 999999.0)
        for nx, ny in neighborhoods:
            d = (np.abs(cxs_arr - nx).astype(float) +
                 np.abs(cys_arr - ny).astype(float))
            nbhd_score = np.minimum(nbhd_score, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                # Mix: prefer near existing zones AND near neighborhoods
                zone_score = zone_dist * 0.5 + nbhd_score * 0.5
            else:
                zone_score = nbhd_score
        else:
            zone_score = nbhd_score

        order = np.argsort(zone_score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # Civic services placed reactively
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(12, 95, 18)
                     for fx in range(12, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(15, 92, 20)
                       for px2 in range(15, 112, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(10, 92, 8)
                     for pkx in range(10, 112, 8)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300:
        stadium_locs = [
            (20, 20), (100, 20), (20, 80), (100, 80),
            (60, 15), (60, 85), (10, 50), (110, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 400 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            found = False
            for dy in range(-5, 6):
                for dx in range(-5, 6):
                    nx2, ny2 = npx + dx, npy + dy
                    if ib(nx2, ny2) and pm[ny2, nx2]:
                        found = True
                        break
                if found:
                    break
            if not found and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        airport_locs = [(10, 10), (110, 10), (10, 90), (110, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 600:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend wires from plants
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                              (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: place roads near wires
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 80)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0, 2), (0, -2), (2, 0), (-2, 0),
                              (0, 3), (0, -3), (3, 0), (-3, 0)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at columns 15,45,75,105 row 50, with vertical wire spines and flanking roads."""
    actions = []
    for px in [15, 45, 75, 105]:
        actions.append((Tool.COALPOWER, px, 50))
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, px, 50 + dy))
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, 50 + dy))
            actions.append((Tool.ROAD, px + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 5 columns x 5 rows = 25 neighborhood anchors covering the full map
    # Each anchor: (plant_x, plant_y, wire_col, road_left, road_right)
    anchors = []
    col_xs = [12, 33, 57, 81, 105]
    row_ys = [12, 30, 50, 70, 88]
    for ry in row_ys:
        for cx in col_xs:
            anchors.append((cx, ry, cx, cx - 1, cx + 1))

    def num_active():
        if pop < 20:    return 2
        if pop < 80:    return 4
        if pop < 200:   return 6
        if pop < 400:   return 9
        if pop < 700:   return 12
        if pop < 1200:  return 16
        if pop < 2000:  return 20
        if pop < 3500:  return 23
        return 25

    n_active = min(num_active(), len(anchors))
    # Spread active anchors across the grid evenly
    if n_active >= len(anchors):
        active_anchors = anchors
    else:
        step_size = len(anchors) / n_active
        active_anchors = [anchors[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active anchor ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Try exact location first
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        # Search nearby
        for r in range(1, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: VERTICAL WIRE SPINES ----
    spine_half = min(25, 8 + pop // 15)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Find existing wire in this column
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            # Start wire adjacent to plant
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)

    # ---- PHASE 3: HORIZONTAL WIRE connecting anchors in same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            wc1 = row_anchors[i][2]
            wc2 = row_anchors[i + 1][2]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- PHASE 4: VERTICAL WIRE connecting anchor columns ----
    if n_active >= 6:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                py1 = col_anchors[i][1]
                py2 = col_anchors[i + 1][1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- PHASE 5: ROAD SPINES flanking wire ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- PHASE 6: HORIZONTAL ROADS at anchor y-levels ----
    if pop > 30:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            for horiz_y in [yl - 2, yl + 2]:
                if horiz_y < 2 or horiz_y >= WORLD_H - 2:
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 7: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.2
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 8: EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 9: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(cx, ry) for ry in [20, 40, 60, 80] for cx in [12, 33, 57, 81, 105]]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [(cx, ry) for ry in [25, 45, 65, 85] for cx in [22, 45, 68, 92]]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadium_spots = [
            (20, 6), (57, 6), (95, 6),
            (20, 93), (57, 93), (95, 93),
            (6, 30), (6, 60), (6, 90),
            (113, 30), (113, 60), (113, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [
            (24, 5), (57, 5), (93, 5),
            (24, 94), (57, 94), (93, 94),
            (5, 25), (5, 50), (5, 75),
            (114, 25), (114, 50), (114, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55, 5), (5, 50), (114, 50), (55, 94), (90, 5), (90, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (114, 93), (60, 97), (5, 6), (114, 6)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 200 and step % 5 == 0:
        park_cands = em & nbr_road & nbr_wire
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place plant near unpowered anchor ----
    for (px, py, wc, rl, rr) in active_anchors:
        if not bool(nbr_wire[py, wc]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants arranged in a cross pattern with wire + road spines."""
    actions = []
    # Four power plant positions: corners of a central diamond
    plants = [(30, 20), (90, 20), (30, 70), (90, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine horizontally
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
        # Wire spine vertically
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads above and below wire
        for dx in range(-4, 5):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 50% residential, 30% commercial, 20% industrial
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 16 neighborhoods in a 4x4 grid across the map
    # Using columns: 15, 45, 75, 105 and rows: 15, 35, 55, 75, 90
    anchor_xs = [15, 40, 65, 90, 112]
    anchor_ys = [15, 35, 55, 75, 90]

    all_anchors = []
    for ax in anchor_xs:
        for ay in anchor_ys:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 30:    return 2
        if pop < 100:   return 4
        if pop < 250:   return 6
        if pop < 450:   return 8
        if pop < 700:   return 10
        if pop < 1000:  return 12
        if pop < 1500:  return 15
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 8); y1 = min(WORLD_H, ay + 9)
        x0 = max(0, ax - 8); x1 = min(WORLD_W, ax + 9)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            # Find nearest empty spot for plant
            for r in range(0, 15):
                found = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if found:
                    break

    # ---- HORIZONTAL WIRE SPINE per anchor ----
    wire_half = min(18, 5 + pop // 15)
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            # Start wire near center
            for dx in range(-3, 4):
                nx = ax + dx
                if ib(nx, ay) and bool(em[ay, nx]) and not bool(pm[ay, nx]):
                    return (Tool.WIRE, nx, ay)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, ay) and (bool(em[ay, nc]) or bool(wm[ay, nc])) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, ay) and (bool(em[ay, nc]) or bool(wm[ay, nc])) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)

    # ---- VERTICAL WIRE SPINE per anchor ----
    vert_half = min(12, 4 + pop // 20)
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            for dy in range(-3, 4):
                ny = ay + dy
                if ib(ax, ny) and bool(em[ny, ax]) and not bool(pm[ny, ax]):
                    return (Tool.WIRE, ax, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(ax, nr) and (bool(em[nr, ax]) or bool(wm[nr, ax])) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(ax, nr) and (bool(em[nr, ax]) or bool(wm[nr, ax])) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)

    # ---- WIRE CONNECTIONS between anchors in same column ----
    if n_active >= 3:
        xs_set = sorted(set(ax for (ax, ay) in active_anchors))
        for col_x in xs_set:
            col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1 = col_anchors[i]
                _, y2 = col_anchors[i + 1]
                for cy in range(y1 + 1, y2):
                    if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                        return (Tool.WIRE, col_x, cy)

    # ---- WIRE CONNECTIONS between anchors in same row ----
    if n_active >= 2:
        ys_set = sorted(set(ay for (ax, ay) in active_anchors))
        for row_y in ys_set:
            row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
            for i in range(len(row_anchors) - 1):
                x1, _ = row_anchors[i]
                x2, _ = row_anchors[i + 1]
                for cx in range(x1 + 1, x2):
                    if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING: roads above and below wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            continue
        cycle = (step + idx * 5) % 4
        for wc in wire_in_row[cycle::4]:
            for road_y in [ay - 2, ay + 2]:
                if ib(wc, road_y) and bool(em[road_y, wc]) and not bool(pm[road_y, wc]):
                    return (Tool.ROAD, wc, road_y)

    # ---- VERTICAL ROADS flanking vertical wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        vert_half2 = min(12, 4 + pop // 20)
        spine_top = max(2, ay - vert_half2)
        spine_bot = min(WORLD_H - 3, ay + vert_half2)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 3) % 4
        for wr in wire_in_col[cycle::4]:
            for road_x in [ax - 2, ax + 2]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- HORIZONTAL CROSS ROADS connecting anchors at same y ----
    if pop > 10:
        ys_set = sorted(set(ay for (ax, ay) in active_anchors))
        for row_y in ys_set:
            row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
            for horiz_y_off in [-3, 3]:
                horiz_y = row_y + horiz_y_off
                if len(row_anchors) >= 2:
                    x_start = row_anchors[0][0] - 3
                    x_end = row_anchors[-1][0] + 3
                    for cx in range(max(2, x_start), min(WORLD_W - 2, x_end + 1)):
                        if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                            return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL CROSS ROADS connecting anchors in same column ----
    if pop > 30:
        xs_set = sorted(set(ax for (ax, ay) in active_anchors))
        for col_x in xs_set:
            col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
            for vert_x_off in [-3, 3]:
                vert_x = col_x + vert_x_off
                if len(col_anchors) >= 2:
                    y_start = col_anchors[0][1] - 3
                    y_end = col_anchors[-1][1] + 3
                    for cy in range(max(2, y_start), min(WORLD_H - 2, y_end + 1)):
                        if ib(vert_x, cy) and bool(em[cy, vert_x]) and not bool(pm[cy, vert_x]):
                            return (Tool.ROAD, vert_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = [
            (7, 10), (30, 10), (55, 10), (80, 10), (105, 10),
            (7, 30), (30, 30), (55, 30), (80, 30), (105, 30),
            (7, 50), (30, 50), (55, 50), (80, 50), (105, 50),
            (7, 70), (30, 70), (55, 70), (80, 70), (105, 70),
            (7, 88), (30, 88), (55, 88), (80, 88), (105, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (10, 5), (35, 5), (60, 5), (85, 5), (110, 5),
            (10, 25), (35, 25), (60, 25), (85, 25), (110, 25),
            (10, 45), (35, 45), (60, 45), (85, 45), (110, 45),
            (10, 65), (35, 65), (60, 65), (85, 65), (110, 65),
            (10, 85), (35, 85), (60, 85), (85, 85), (110, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (20, 5), (60, 5), (100, 5),
            (20, 92), (60, 92), (100, 92),
            (5, 48), (115, 48),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94),
            (5, 50), (115, 50),
            (30, 5), (90, 5),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92), (30, 6), (85, 6)]:
            ax2, ay2 = asp
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in a 3x2 grid with wire spines and flanking roads."""
    actions = []
    # 3 columns x 2 rows of power plants
    for px in [20, 60, 100]:
        for py in [33, 67]:
            actions.append((Tool.COALPOWER, px, py))
            # Wire spine vertical through plant
            for dy in range(-8, 9):
                actions.append((Tool.WIRE, px, py + dy))
            # Roads flanking wire spine
            for dy in range(-8, 9):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connections between plants at each row
    for py in [33, 67]:
        for x in range(21, 60):
            actions.append((Tool.WIRE, x, py))
        for x in range(61, 100):
            actions.append((Tool.WIRE, x, py))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Define anchors dynamically based on population
    # 3 cols x 4 rows = 12 anchors covering the whole map
    all_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [20, 40, 60, 80]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 500:   return 8
        if pop < 800:   return 10
        return 12

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if funds < 500:
            break
        # Find nearest empty spot
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE VERTICAL ----
    # Grow wires up/down from each active anchor's plant column
    spine_half = min(35, 10 + pop // 10)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        col_wire = [r for r in range(spine_top, spine_bot + 1)
                    if ib(px, r) and bool(wm[r, px])]
        col_plant = [r for r in range(spine_top, spine_bot + 1)
                     if ib(px, r) and bool(pm[r, px])]
        connected = sorted(set(col_wire + col_plant))
        if not connected:
            # Seed wire near plant location
            for dy in range(-3, 4):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_w = min(connected)
            max_w = max(connected)
            if max_w < spine_bot:
                nr = max_w + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    if bool(em[nr, px]) or bool(wm[nr, px]):
                        return (Tool.WIRE, px, nr)
            if min_w > spine_top:
                nr = min_w - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    if bool(em[nr, px]) or bool(wm[nr, px]):
                        return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting same-row anchors ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1w = row_anchors[i][0]
            x2w = row_anchors[i + 1][0]
            # Connect horizontally at yl
            for cx in range(x1w + 1, x2w):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows in same column ----
    col_levels = sorted(set(px for (px, _) in active_anchors))
    for col_x in col_levels:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            y1v = col_anchors[i][1]
            y2v = col_anchors[i + 1][1]
            for cy in range(y1v + 1, y2v):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    return (Tool.WIRE, col_x, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        rl = px - 1
        rr = px + 1
        cycle = (step + idx * 5) % 3
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at y_levels +/- offset ----
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        if len(row_anchors) < 1:
            continue
        x_left = row_anchors[0][0] - 1
        x_right = row_anchors[-1][0] + 1
        for horiz_y in [yl - 3, yl + 3]:
            if not (ib(x_left, horiz_y) and ib(x_right, horiz_y)):
                continue
            for cx in range(x_left, x_right + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting y_levels ----
    if len(y_levels) >= 2:
        for col_x in col_levels:
            for rx in [col_x - 3, col_x + 3]:
                if not ib(rx, 2):
                    continue
                yl_list = sorted(y_levels)
                for i in range(len(yl_list) - 1):
                    y1v = yl_list[i] - 3
                    y2v = yl_list[i + 1] + 3
                    for cy in range(max(2, y1v), min(WORLD_H - 2, y2v + 1)):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- EXTENDED ROAD NETWORK: cross-roads between columns ----
    if pop > 100:
        # Add roads at x=40 and x=80 (between the 3 column groups)
        for mid_x in [40, 80]:
            for yl in y_levels:
                for dy in range(-spine_half, spine_half + 1):
                    cy = yl + dy
                    if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                        # Only if near wire
                        x0 = max(0, mid_x - 6); x1x = min(WORLD_W, mid_x + 7)
                        y0 = max(0, cy - 6); y1y = min(WORLD_H, cy + 7)
                        if np.any(wm[y0:y1y, x0:x1x]) or np.any(pm[y0:y1y, x0:x1x]):
                            return (Tool.ROAD, mid_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by proximity to active anchors
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs_arr - px).astype(float) * 1.0
                 + np.abs(cys_arr - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)

        # When pop is high, also spread toward edges/corners
        if pop > 300:
            spread_targets = [(15, 15), (105, 15), (15, 85), (105, 85),
                              (60, 10), (60, 90), (10, 50), (110, 50),
                              (35, 10), (85, 10), (35, 90), (85, 90)]
            corner_dist = np.full(len(cxs_arr), 999999.0)
            for cx, cy in spread_targets:
                d = (np.abs(cxs_arr - cx).astype(float) +
                     np.abs(cys_arr - cy).astype(float))
                corner_dist = np.minimum(corner_dist, d)
            spread_w = min(0.8, (pop - 300) / 2000.0)
            best_dist = best_dist * (1 - spread_w) + corner_dist * spread_w

        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS near wire from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 15), (35, 15), (75, 15), (108, 15),
            (8, 35), (35, 35), (75, 35), (108, 35),
            (8, 55), (35, 55), (75, 55), (108, 55),
            (8, 75), (35, 75), (75, 75), (108, 75),
            (8, 92), (35, 92), (75, 92), (108, 92),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (22, 10), (55, 10), (88, 10),
            (22, 30), (55, 30), (88, 30),
            (22, 50), (55, 50), (88, 50),
            (22, 70), (55, 70), (88, 70),
            (22, 90), (55, 90), (88, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150:
        # Parks near zones to boost land value
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 500:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10),
            (10, 50), (50, 50), (90, 50),
            (10, 90), (50, 90), (90, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and funds > 5000:
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94), (10, 6), (110, 6)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in a 2x2 grid with wire spines and flanking roads."""
    actions = []
    # Four plants at corners of map coverage
    for px in [30, 85]:
        for py in [30, 70]:
            actions.append((Tool.COALPOWER, px, py))
            # Wire spine vertically
            for dy in range(-6, 7):
                actions.append((Tool.WIRE, px, py + dy))
            # Roads flanking wire
            for dy in range(-6, 7):
                actions.append((Tool.ROAD, px - 2, py + dy))
                actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 50% residential, 30% commercial, 20% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 neighborhoods: 2 columns x 3 rows, spread across map
    # Each anchor: (plant_x, plant_y, wire_col, road_left, road_right)
    def get_anchors():
        anchors = []
        for col_x in [30, 85]:
            for row_y in [30, 55, 75]:
                wc = col_x
                rl = col_x - 2
                rr = col_x + 2
                anchors.append((col_x, row_y, wc, rl, rr))
        return anchors

    anchors = get_anchors()

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 3
        if pop < 600:   return 4
        if pop < 1000:  return 5
        return 6

    n_active = num_active()
    active_anchors = anchors[:n_active]

    spine_half = min(25, 8 + pop // 15)

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        has_plant = False
        y0 = max(0, py - 9); y1 = min(WORLD_H, py + 10)
        x0 = max(0, px - 9); x1 = min(WORLD_W, px + 10)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) ----
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-5, 6):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting the two columns at each y-level ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting rows within each column ----
    if n_active >= 3:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                _, py1, _, _, _ = col_anchors[i]
                _, py2, _, _, _ = col_anchors[i + 1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 5) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS connecting neighborhoods ----
    if pop > 10:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            # Build horizontal road at y-level and at +/-5
            for horiz_y in [yl - 5, yl, yl + 5]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting the three row-levels ----
    if pop > 30 and len(y_levels) >= 2:
        for col_x in [28, 32, 83, 87]:
            y_sorted = sorted(y_levels)
            for i in range(len(y_sorted) - 1):
                y1 = y_sorted[i]
                y2 = y_sorted[i + 1]
                for cy in range(y1, y2 + 1):
                    if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                        return (Tool.ROAD, col_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = [
            (18, 20), (45, 20), (72, 20), (100, 20),
            (18, 45), (45, 45), (72, 45), (100, 45),
            (18, 65), (45, 65), (72, 65), (100, 65),
            (18, 88), (45, 88), (72, 88), (100, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 15), (50, 15), (80, 15), (110, 15),
            (15, 42), (50, 42), (80, 42), (110, 42),
            (15, 62), (50, 62), (80, 62), (110, 62),
            (15, 88), (50, 88), (80, 88), (110, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (12, 8), (55, 8), (100, 8),
            (12, 92), (55, 92), (100, 92),
            (12, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (57, 5), (57, 94), (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Compact dense city with multiple power plants, grid roads, and mixed zones
# Uses a structured grid approach with proper power distribution
# Focuses on building a dense core first, then expanding

def init(obs, state):
    """Bootstrap: three coal plants in a triangle + wire grid + initial roads."""
    actions = []
    # Three power plants forming a triangle
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 60, 35))
    actions.append((Tool.COALPOWER, 80, 50))
    actions.append((Tool.COALPOWER, 60, 65))
    # Connect them with horizontal wires
    for x in range(41, 60):
        actions.append((Tool.WIRE, x, 50))
    for x in range(61, 80):
        actions.append((Tool.WIRE, x, 50))
    # Vertical connections
    for y in range(36, 50):
        actions.append((Tool.WIRE, 60, y))
    for y in range(51, 65):
        actions.append((Tool.WIRE, 60, y))
    # Initial roads forming a cross
    for x in range(35, 86):
        actions.append((Tool.ROAD, x, 42))
        actions.append((Tool.ROAD, x, 58))
    for y in range(36, 65):
        actions.append((Tool.ROAD, 45, y))
        actions.append((Tool.ROAD, 75, y))
        actions.append((Tool.ROAD, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- BUILD POWER NEIGHBOR MASK ----
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # ---- BUILD ROAD NEIGHBOR MASK ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- DEFINE GRID OF NEIGHBORHOODS ----
    # Dense 10x8 grid covering most of the map
    # Columns spaced 11 apart, rows spaced 11 apart
    nh_cols = list(range(10, 115, 11))  # ~10 cols
    nh_rows = list(range(10, 95, 11))   # ~8 rows
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # How many neighborhoods to activate based on population
    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 8
        if pop < 400:   return 16
        if pop < 800:   return 28
        if pop < 1500:  return 42
        if pop < 3000:  return 58
        if pop < 5000:  return 68
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        # Pick hoods spiraling outward from center
        cx, cy = 60, 50
        sorted_hoods = sorted(all_hoods, key=lambda h: abs(h[0]-cx) + abs(h[1]-cy))
        active_hoods = sorted_hoods[:n_active]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood cluster ----
    # Group hoods into clusters of 4 and ensure one plant per cluster
    cluster_size = 4
    plant_checks = []
    for i in range(0, len(active_hoods), cluster_size):
        cluster = active_hoods[i:i+cluster_size]
        avg_x = int(np.mean([h[0] for h in cluster]))
        avg_y = int(np.mean([h[1] for h in cluster]))
        plant_checks.append((avg_x, avg_y))

    for (hx, hy) in plant_checks:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 12):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID connecting all active hoods ----
    # Build a grid of horizontal and vertical wires at hood positions
    # Find all plants and extend wires between them
    plant_ys, plant_xs = np.where(pm)

    if len(plant_xs) > 0:
        # Try to connect nearest unwired empty tile adjacent to existing wire/plant
        hood_idx = step % max(len(active_hoods), 1)
        hx, hy = active_hoods[hood_idx]

        # Draw wire toward nearest plant from hood center
        min_dist = 9999
        nearest_px, nearest_py = hx, hy
        for i in range(len(plant_xs)):
            d = abs(int(plant_xs[i]) - hx) + abs(int(plant_ys[i]) - hy)
            if d < min_dist:
                min_dist = d
                nearest_px, nearest_py = int(plant_xs[i]), int(plant_ys[i])

        # Walk wire from hood toward plant
        if min_dist > 2:
            # Try horizontal then vertical path
            for step_dir in range(min_dist):
                if hx < nearest_px:
                    wx, wy = hx + step_dir + 1, hy
                elif hx > nearest_px:
                    wx, wy = hx - step_dir - 1, hy
                else:
                    wx, wy = hx, hy + (1 if hy < nearest_py else -1) * (step_dir + 1)
                if not ib(wx, wy): break
                if bool(em[wy, wx]) and not bool(pm[wy, wx]):
                    # Check if adjacent to existing wire or plant
                    for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ax, ay = wx+adx, wy+ady
                        if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                            return (Tool.WIRE, wx, wy)
                break

    # Extend wires along grid lines (rows and columns of active hoods)
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Horizontal wire row at hy
    for dx in range(-15, 16):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(pm[hy, wx]): continue
        if bool(wm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adx in [-1, 1]:
            ax = wx + adx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # Vertical wire at hx
    for dy in range(-15, 16):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(pm[wy, hx]): continue
        if bool(wm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for ady in [-1, 1]:
            ay = wy + ady
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # ---- PHASE 3: ROAD GRID ----
    # Build roads along grid lines flanking wires
    # For each active hood, roads at hx±1 and hy±1

    # Cross-hood road connections: horizontal road rows
    road_row_ys = sorted(set(hy for (hx, hy) in active_hoods))
    road_col_xs = sorted(set(hx for (hx, hy) in active_hoods))

    hx, hy = active_hoods[hood_idx]

    # Road along hy±1
    for ry in [hy - 1, hy + 1, hy + 2]:
        if not ib(hx, ry): continue
        for dx in range(-14, 15):
            rx = hx + dx
            if not ib(rx, ry): continue
            if bool(pm[ry, rx]): continue
            if bool(rm[ry, rx]): continue
            if bool(em[ry, rx]) and bool(nbr_power[ry, rx]):
                # Only place if near wire
                near_wire = False
                for ady in [-2,-1,0,1,2]:
                    ay = ry + ady
                    if ib(rx, ay) and (bool(wm[ay, rx]) or bool(pm[ay, rx])):
                        near_wire = True
                        break
                if near_wire:
                    return (Tool.ROAD, rx, ry)

    # Road along hx±1
    for rx in [hx - 1, hx + 1, hx + 2]:
        if not ib(rx, hy): continue
        for dy in range(-14, 15):
            ry = hy + dy
            if not ib(rx, ry): continue
            if bool(pm[ry, rx]): continue
            if bool(rm[ry, rx]): continue
            if bool(em[ry, rx]) and bool(nbr_power[ry, rx]):
                near_wire = False
                for adx in [-2,-1,0,1,2]:
                    ax = rx + adx
                    if ib(ax, ry) and (bool(wm[ry, ax]) or bool(pm[ry, ax])):
                        near_wire = True
                        break
                if near_wire:
                    return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool(step_mod):
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 35% RES, 35% COM, 30% IND
        # Vary by step to create mixed zones
        m = step_mod % 10
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        if rr < 0.33:
            return Tool.RESIDENTIAL
        # Cycle based on step
        if m < 4: return Tool.RESIDENTIAL
        if m < 7: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Zone placement: find candidates near roads and power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Also prioritize by distance to nearest road (want zones right next to roads)
        road_ys_arr, road_xs_arr = np.where(rm)
        if len(road_xs_arr) > 0:
            # Approximate: use distance to center of road cluster
            road_cx = int(np.mean(road_xs_arr))
            road_cy = int(np.mean(road_ys_arr))
            road_dist = np.abs(cxs - road_cx) + np.abs(cys - road_cy)
            score = best_dist * 0.7 + road_dist * 0.3
        else:
            score = best_dist

        order = np.argsort(score)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool(step)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 5: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    # Fire stations in a grid
    if pop > 60:
        fire_grid_x = list(range(12, WORLD_W, 20))
        fire_grid_y = list(range(12, WORLD_H, 20))
        for fy in fire_grid_y:
            for fx in fire_grid_x:
                if ib(fx, fy) and bool(em[fy, fx]):
                    x0, x1 = max(0, fx-8), min(WORLD_W, fx+9)
                    y0, y1 = max(0, fy-8), min(WORLD_H, fy+9)
                    has_fire = False
                    for ty in range(y0, y1):
                        for tx in range(x0, x1):
                            if tm[ty, tx] == 427:  # fire station tile
                                has_fire = True
                                break
                    if not has_fire:
                        return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        police_grid_x = list(range(15, WORLD_W, 25))
        police_grid_y = list(range(15, WORLD_H, 25))
        for py in police_grid_y:
            for px in police_grid_x:
                if ib(px, py) and bool(em[py, px]):
                    return (Tool.POLICESTATION, px, py)

    if pop > 600:
        stadium_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (100, 50),
            (20, 80), (60, 80), (100, 80)
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaport_spots = [(10, 90), (60, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # Nuclear power upgrades
    if pop > 2000 and step % 3 == 0:
        nuclear_spots = [
            (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (15, 50), (105, 50), (60, 15), (60, 85),
            (45, 40), (75, 40), (45, 60), (75, 60)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 4000:
        airport_spots = [
            (15, 15), (105, 15), (15, 85), (105, 85),
            (60, 8), (60, 92)
        ]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 100 and step % 5 == 0:
        park_mask = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_mask)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants spread across map with wire and road spines."""
    actions = []
    # 4 power plant positions: corners of a cross pattern
    plants = [(20, 20), (100, 20), (20, 80), (100, 80), (60, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads above and below wire
        for dx in range(-4, 5):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 45% res, 30% com, 25% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 12 neighborhoods in a 4x3 grid across the map
    # anchor: (plant_x, plant_y, wire_col, road_left, road_right)
    all_neighborhoods = []
    for col_x in [15, 40, 65, 90, 115]:
        for row_y in [20, 50, 80]:
            all_neighborhoods.append((col_x, row_y))

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 6
        if pop < 500:  return 8
        if pop < 800:  return 10
        if pop < 1200: return 12
        return len(all_neighborhoods)

    n_active = num_active()
    if n_active >= len(all_neighborhoods):
        active_nh = all_neighborhoods
    else:
        step_size = len(all_neighborhoods) / n_active
        active_nh = [all_neighborhoods[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS near each active neighborhood ----
    for (px, py) in active_nh:
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot
        placed = False
        for r in range(0, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if placed:
                break

    # ---- WIRE GRID: horizontal and vertical spines ----
    # Each neighborhood gets cross-shaped wire
    spine_r = min(15, 6 + pop // 30)
    for (px, py) in active_nh:
        # Horizontal wire
        for dx in range(-spine_r, spine_r + 1):
            cx = px + dx
            if ib(cx, py) and (bool(em[py, cx]) or bool(wm[py, cx])) and not bool(pm[py, cx]):
                if not bool(wm[py, cx]):
                    return (Tool.WIRE, cx, py)
        # Vertical wire
        for dy in range(-spine_r, spine_r + 1):
            cy = py + dy
            if ib(px, cy) and (bool(em[cy, px]) or bool(wm[cy, px])) and not bool(pm[cy, px]):
                if not bool(wm[cy, px]):
                    return (Tool.WIRE, px, cy)

    # ---- CONNECT NEIGHBORHOODS with wire grid ----
    # Horizontal connections between neighborhoods at same row_y
    y_levels = sorted(set(py for (_, py) in active_nh))
    x_levels = sorted(set(px for (px, _) in active_nh))

    for yl in y_levels:
        row_nhs = sorted([(px, py) for (px, py) in active_nh if py == yl], key=lambda a: a[0])
        for i in range(len(row_nhs) - 1):
            x1, _ = row_nhs[i]
            x2, _ = row_nhs[i + 1]
            # wire between
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # Vertical connections between neighborhoods at same col_x
    for xl in x_levels:
        col_nhs = sorted([(px, py) for (px, py) in active_nh if px == xl], key=lambda a: a[1])
        for i in range(len(col_nhs) - 1):
            _, y1 = col_nhs[i]
            _, y2 = col_nhs[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: roads flanking wire spines ----
    for (px, py) in active_nh:
        # Roads above and below horizontal wire
        for dx in range(-spine_r, spine_r + 1):
            cx = px + dx
            for road_y in [py - 2, py + 2]:
                if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    return (Tool.ROAD, cx, road_y)
        # Roads left and right of vertical wire
        for dy in range(-spine_r, spine_r + 1):
            cy = py + dy
            for road_x in [px - 2, px + 2]:
                if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    return (Tool.ROAD, road_x, cy)

    # ---- CONNECTING ROADS between neighborhoods ----
    # Horizontal roads at row_y ± 6
    for yl in y_levels:
        row_nhs = sorted([(px, py) for (px, py) in active_nh if py == yl], key=lambda a: a[0])
        if len(row_nhs) < 2:
            continue
        x1 = row_nhs[0][0] - 3
        x2 = row_nhs[-1][0] + 3
        for road_y in [yl - 4, yl + 4]:
            for cx in range(max(0, x1), min(WORLD_W, x2 + 1)):
                if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    return (Tool.ROAD, cx, road_y)

    # Vertical roads connecting row levels
    if pop > 80 and len(y_levels) >= 2:
        for xl in x_levels:
            for road_x in [xl - 3, xl + 3]:
                for i in range(len(y_levels) - 1):
                    y1 = y_levels[i]
                    y2 = y_levels[i + 1]
                    for cy in range(y1, y2 + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_nh:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [
            (7, 10), (30, 10), (55, 10), (80, 10), (105, 10),
            (7, 35), (30, 35), (55, 35), (80, 35), (105, 35),
            (7, 60), (30, 60), (55, 60), (80, 60), (105, 60),
            (7, 85), (30, 85), (55, 85), (80, 85), (105, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (10, 25), (40, 25), (70, 25), (100, 25),
            (10, 55), (40, 55), (70, 55), (100, 55),
            (10, 75), (40, 75), (70, 75), (100, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        # Upgrade some coal to nuclear for better power coverage
        nuke_spots = [(30, 20), (90, 20), (30, 80), (90, 80), (60, 50)]
        for (nx2, ny2) in nuke_spots:
            x0 = max(0, nx2 - 8); x1 = min(WORLD_W, nx2 + 9)
            y0 = max(0, ny2 - 8); y1 = min(WORLD_H, ny2 + 9)
            if not np.any(pm[y0:y1, x0:x1]):
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 600:
        stadium_spots = [
            (12, 12), (60, 12), (108, 12),
            (12, 90), (60, 90), (108, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for asp in [(50, 5), (5, 50), (114, 50), (50, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 95), (114, 95), (5, 5), (114, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious city builder: dense grid of neighborhoods across full map
# Key improvements: pre-planned wire backbone, faster zone placement,
# better power distribution, civic services triggered by pop thresholds

def init(obs, state):
    """Bootstrap: 3 coal plants forming a triangle + wire connections."""
    actions = []
    # Three initial coal plants
    plants = [(30, 25), (90, 25), (60, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire from first plant rightward toward second
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 25))
    # Wire from center of that line down to third plant
    for y in range(26, 75):
        actions.append((Tool.WIRE, 60, y))
    # Initial roads near first plant
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, 29, 25 + dy))
        actions.append((Tool.ROAD, 31, 25 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 8 cols x 6 rows = 48 neighborhoods ----
    # Tighter spacing: 14 apart to pack more zones
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [10, 26, 42, 58, 74, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 8
        if pop < 1200:  return 14
        if pop < 2500:  return 20
        if pop < 5000:  return 30
        if pop < 8000:  return 40
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods across the map
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # ---- POWER PLANT PLACEMENT ----
    # Each neighborhood needs a coal plant within range
    # Place plants at every 3rd hood to cover multiple neighborhoods
    plant_positions = []
    for i, (hx, hy) in enumerate(active_hoods):
        if i % 3 == 0:
            plant_positions.append((hx, hy))

    # Ensure each active hood has nearby power
    for (hx, hy) in plant_positions:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find nearest empty cell
            for r in range(15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- WIRE BACKBONE: connect all active hoods ----
    # Wire along row lines connecting same-row hoods
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Horizontal wire through hy
        for dx in range(-7, 8):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            # Check if adjacent to existing wire/plant
            for adx in [-1, 1]:
                ax = wx + adx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)
        # Vertical wire through hx
        for dy in range(-7, 8):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

    # ---- WIRE CONNECTION BETWEEN NEIGHBORING HOODS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            # Connect horizontally adjacent hoods (same row)
            if hy1 == hy2 and abs(hx2 - hx1) == 14:
                mid_y = hy1
                x_start, x_end = min(hx1, hx2) + 1, max(hx1, hx2)
                for cx2 in range(x_start, x_end):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Connect vertically adjacent hoods (same col)
            if hx1 == hx2 and abs(hy2 - hy1) == 16:
                mid_x = hx1
                y_start, y_end = min(hy1, hy2) + 1, max(hy1, hy2)
                for cy2 in range(y_start, y_end):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- ROAD GRID: flanking spines and cross roads ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        rmod = (step + idx_h) % max(1, len(active_hoods) // 2)
        if rmod > max(1, len(active_hoods) // 4):
            continue
        # Two flanking roads on each side of vertical wire spine
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-6, 7):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Two flanking roads above/below horizontal wire spine
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-6, 7):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 45% RES, 30% COM, 25% IND
        # Vary by step to create diverse neighborhoods
        phase = (step // 50) % 3
        if phase == 0:
            if ir < 0.22: return Tool.INDUSTRIAL
            if cr < 0.28: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif phase == 1:
            if cr < 0.28: return Tool.COMMERCIAL
            if ir < 0.22: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            if rr < 0.45: return Tool.RESIDENTIAL
            if cr < 0.28: return Tool.COMMERCIAL
            return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers: empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates: prefer close to active hoods
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step offset to vary placements
        offset = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    # Fire stations on a dense grid
    if pop > 80:
        fire_grid_x = range(12, WORLD_W, 18)
        fire_grid_y = range(12, WORLD_H, 18)
        fire_spots = [(fx, fy) for fy in fire_grid_y for fx in fire_grid_x]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_grid_x = range(15, WORLD_W, 22)
        police_grid_y = range(15, WORLD_H, 22)
        police_spots = [(px2, py2) for py2 in police_grid_y for px2 in police_grid_x]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        # Stadiums spread across map
        stadiums = [(x, y) for y in range(20, WORLD_H, 30) for x in range(20, WORLD_W, 40)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(6, 50), (6, 20), (6, 80), (113, 50), (113, 20), (113, 80),
                    (40, 95), (80, 95), (40, 5), (80, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(20, 6), (60, 6), (100, 6), (20, 94), (60, 94), (100, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for dense areas ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(x, y) for y in range(25, WORLD_H, 30) for x in range(25, WORLD_W, 40)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS to boost land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a row at y=50, with wire spines and flanking roads."""
    actions = []
    # Three power plants spread across the map
    for px in [20, 60, 100]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertically
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE MANAGEMENT ---
    # We use state to track a "current focus" anchor index
    if 'anchor_idx' not in state:
        state['anchor_idx'] = 0

    # Define a comprehensive grid of anchor points covering the whole map
    # 5 columns x 5 rows = 25 anchors for dense city coverage
    anchor_cols = [12, 32, 60, 88, 108]
    anchor_rows = [12, 30, 50, 70, 88]

    # Build all anchors
    all_anchors = []
    for col_x in anchor_cols:
        for row_y in anchor_rows:
            all_anchors.append((col_x, row_y))

    # Determine which anchors are "active" based on population
    def num_active():
        if pop < 30:    return 3
        if pop < 100:   return 5
        if pop < 250:   return 8
        if pop < 500:   return 12
        if pop < 800:   return 16
        if pop < 1200:  return 20
        return 25

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # --- HELPER: check if a 3x3 zone area is clear ---
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- STEP 1: Ensure each active anchor has a power plant nearby ---
    for (px, py) in active_anchors:
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot for plant
        placed = False
        for r in range(0, 12):
            if placed:
                break
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # --- STEP 2: Build wire spines from each plant toward all anchors ---
    # Find all plant locations
    plant_ys, plant_xs = np.where(pm)

    # Extend wire from existing wire/plant toward nearest anchor without wire
    # Use a reactive approach: find wire frontier and extend it

    # Build wire adjacency: find cells near wire but not yet wired
    # For each active anchor, ensure wire reaches it
    for (px, py) in active_anchors:
        # Check if this anchor area already has wire
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(wm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1]):
            continue
        # Need to extend wire to this anchor - find closest wire/plant cell
        if len(plant_xs) == 0 and np.sum(wm) == 0:
            continue
        # Find nearest wire or plant cell
        all_wm = wm | pm
        wire_ys_arr, wire_xs_arr = np.where(all_wm)
        if len(wire_xs_arr) == 0:
            continue
        dists = np.abs(wire_xs_arr - px) + np.abs(wire_ys_arr - py)
        closest_idx = np.argmin(dists)
        wx, wy = int(wire_xs_arr[closest_idx]), int(wire_ys_arr[closest_idx])
        # Step one tile toward anchor from wire endpoint
        dx = px - wx; dy = py - wy
        if abs(dx) >= abs(dy):
            nx = wx + (1 if dx > 0 else -1)
            ny = wy
        else:
            nx = wx
            ny = wy + (1 if dy > 0 else -1)
        if ib(nx, ny) and not bool(pm[ny, nx]):
            return (Tool.WIRE, nx, ny)

    # --- STEP 3: Extend wire spines vertically and horizontally ---
    # Vertical wire spine at each anchor column
    spine_half = min(40, 10 + pop // 8)

    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)

        # Check vertical spine
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]

        if not wire_in_col:
            # Start wire near plant
            for dy2 in range(-3, 4):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            max_wr = max(wire_in_col)
            min_wr = min(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # Horizontal wire connecting anchors in same row
    for row_y in anchor_rows:
        row_aps = sorted([(px, py) for (px, py) in active_anchors if py == row_y], key=lambda a: a[0])
        for i in range(len(row_aps) - 1):
            x1, _ = row_aps[i]
            x2, _ = row_aps[i + 1]
            for cx in range(x1, x2 + 1):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # Vertical wire connecting anchor rows in same column
    for col_x in anchor_cols:
        col_aps = sorted([(px, py) for (px, py) in active_anchors if px == col_x], key=lambda a: a[1])
        for i in range(len(col_aps) - 1):
            _, y1 = col_aps[i]
            _, y2 = col_aps[i + 1]
            for cy in range(y1, y2 + 1):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    return (Tool.WIRE, col_x, cy)

    # --- STEP 4: Build roads flanking wire spines ---
    # Roads at px-1 and px+1 for each anchor's wire spine
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)

        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not wire_rows:
            continue

        cycle = step % 4
        for wr in wire_rows[cycle::4]:
            for rx in [px - 1, px + 1]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # --- STEP 5: Build horizontal roads at each anchor row level ---
    for row_y in anchor_rows:
        row_aps = sorted([(px, py) for (px, py) in active_anchors if py == row_y], key=lambda a: a[0])
        if len(row_aps) < 2:
            continue
        x_start = row_aps[0][0] - 1
        x_end = row_aps[-1][0] + 1

        # Horizontal roads at row_y - 3 and row_y + 3
        for horiz_y in [row_y - 3, row_y + 3]:
            if not ib(x_start, horiz_y) or not ib(x_end, horiz_y):
                continue
            for cx in range(x_start, x_end + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # --- STEP 6: Build vertical connecting roads ---
    if pop > 50:
        for col_x in anchor_cols:
            for rx in [col_x - 3, col_x + 3]:
                if not ib(rx, 2) or not ib(rx, WORLD_H - 3):
                    continue
                col_aps = sorted([(px, py) for (px, py) in active_anchors if px == col_x], key=lambda a: a[1])
                for i in range(len(col_aps) - 1):
                    _, y1v = col_aps[i]
                    _, y2v = col_aps[i + 1]
                    for cy in range(y1v - 3, y2v + 4):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # --- STEP 7: Zone placement ---
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    all_power = wm | pm
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= all_power[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates by proximity to active anchors
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.9)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # --- STEP 8: Reactive road extension near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- STEP 9: CIVIC SERVICES ---
    if pop > 60:
        # Fire stations spread across map
        fire_spots = []
        for col_x in [10, 35, 65, 95, 115]:
            for row_y in [8, 25, 45, 65, 85, 96]:
                fire_spots.append((col_x, row_y))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = []
        for col_x in [18, 45, 75, 102]:
            for row_y in [15, 35, 55, 75, 92]:
                police_spots.append((col_x, row_y))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (15, 20), (55, 20), (95, 20),
            (15, 50), (55, 50), (95, 50),
            (15, 80), (55, 80), (95, 80),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Add nuclear plants for more power capacity
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 94), (90, 94),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 93), (10, 6), (110, 6)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 94), (115, 94), (60, 97), (5, 5), (115, 5), (60, 2)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- STEP 10: Parks near zones ---
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- STEP 11: Fallback - extend wire from existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- STEP 12: Last resort - place road near any zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in corners + central cross of wires + seed roads"""
    actions = []
    # 4 corner plants
    plants = [(20, 20), (100, 20), (20, 80), (100, 80)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spines at y=20, y=50, y=80
    for x in range(18, 103):
        actions.append((Tool.WIRE, x, 20))
        actions.append((Tool.WIRE, x, 50))
        actions.append((Tool.WIRE, x, 80))
    # Vertical wire spines at x=20, x=60, x=100
    for y in range(18, 83):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Seed roads along major axes
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 30))
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 60))
        actions.append((Tool.ROAD, x, 75))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target ratio: 45% RES, 30% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 1: Power plant grid ----
    # Dense plant grid: every ~20 tiles in both dimensions
    plant_grid_base = []
    for py in range(20, 90, 20):
        for px in range(20, 110, 20):
            plant_grid_base.append((px, py))

    extra_plants = []
    if pop >= 0:
        for py in range(10, 100, 20):
            for px in range(10, 115, 25):
                extra_plants.append((px, py))
    if pop > 300:
        for py in range(5, 100, 15):
            for px in range(5, 120, 20):
                extra_plants.append((px, py))

    all_plants = plant_grid_base[:]
    for p in extra_plants:
        if p not in all_plants:
            all_plants.append(p)

    for px, py in all_plants:
        if not ib(px, py):
            continue
        # Check if plant already nearby (within 6 tiles)
        found = False
        y0 = max(0, py-5); y1 = min(WORLD_H, py+6)
        x0 = max(0, px-5); x1 = min(WORLD_W, px+6)
        if pm[y0:y1, x0:x1].any():
            found = True
        if not found:
            return (Tool.COALPOWER, px, py)

    # ---- Phase 2: Wire network - horizontal + vertical grid every 10 tiles ----
    # Wire rows at every 10 y
    wire_rows = list(range(10, 100, 10))
    wire_cols = list(range(10, 120, 10))

    for wr in wire_rows:
        if not ib(0, wr):
            continue
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            for px2, py2 in all_plants:
                if ib(px2, wr) and em[wr, px2]:
                    return (Tool.WIRE, px2, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and em[wr, left-1]:
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W-2 and em[wr, right+1]:
            return (Tool.WIRE, right+1, wr)
        for x in range(left, right):
            if em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            for px2, py2 in all_plants:
                if ib(wc, py2) and em[py2, wc]:
                    return (Tool.WIRE, wc, py2)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and em[top-1, wc]:
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H-2 and em[bot+1, wc]:
            return (Tool.WIRE, wc, bot+1)
        for y in range(top, bot):
            if em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # ---- Phase 3: Road grid every 5 tiles (denser than parent) ----
    road_rows = list(range(5, 100, 5))
    road_cols = list(range(5, 120, 5))

    for rr in road_rows:
        if not ib(0, rr):
            continue
        # Only build roads where power infrastructure is nearby
        y0 = max(0, rr-5); y1 = min(WORLD_H, rr+6)
        if not (wm[y0:y1, :].any() or pm[y0:y1, :].any()):
            continue
        row_road = rm[rr, :]
        if not row_road.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            for sc in range(5, 115, 5):
                if ib(sc, rr) and em[rr, sc] and not pm[rr, sc]:
                    return (Tool.ROAD, sc, rr)
        else:
            indices = np.where(row_road)[0]
            left = int(indices[0])
            right = int(indices[-1])
            if left > 2 and em[rr, left-1] and not pm[rr, left-1]:
                return (Tool.ROAD, left-1, rr)
            if right < WORLD_W-3 and em[rr, right+1] and not pm[rr, right+1]:
                return (Tool.ROAD, right+1, rr)
            for x in range(left, right):
                if em[rr, x] and not pm[rr, x]:
                    return (Tool.ROAD, x, rr)

    for rc in road_cols:
        if not ib(rc, 0):
            continue
        x0 = max(0, rc-5); x1 = min(WORLD_W, rc+6)
        if not (wm[:, x0:x1].any() or pm[:, x0:x1].any()):
            continue
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            for sr in range(5, 95, 5):
                if ib(rc, sr) and em[sr, rc] and not pm[sr, rc]:
                    return (Tool.ROAD, rc, sr)
        else:
            indices = np.where(col_road)[0]
            top = int(indices[0])
            bot = int(indices[-1])
            if top > 2 and em[top-1, rc] and not pm[top-1, rc]:
                return (Tool.ROAD, rc, top-1)
            if bot < WORLD_H-3 and em[bot+1, rc] and not pm[bot+1, rc]:
                return (Tool.ROAD, rc, bot+1)
            for y in range(top, bot):
                if em[y, rc] and not pm[y, rc]:
                    return (Tool.ROAD, rc, y)

    # ---- Phase 4: Zone placement ----
    zone_tiles = resm | comm | indm

    # Build neighbor masks: road within 2 tiles, wire/plant within 5 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    # Keep safe margin from edges
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: prefer near zones (clustering) and near power
        min_plant_dist = np.full(len(cxs_arr), 999999.0)
        for px2, py2 in all_plants[:20]:
            if ib(px2, py2):
                d = (np.abs(cxs_arr - px2).astype(float) +
                     np.abs(cys_arr - py2).astype(float))
                min_plant_dist = np.minimum(min_plant_dist, d)

        zone_score = min_plant_dist.copy()
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                # Strongly prefer clustering but keep power proximity
                zone_score = zone_dist * 0.5 + min_plant_dist * 0.5

        order = np.argsort(zone_score)
        off = (step * 13 + pop * 11) % max(len(order), 1)
        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # ---- Phase 5: Civic services (pop-gated) ----
    if pop > 5:
        fire_spots = [(fx, fy) for fy in range(8, 95, 8) for fx in range(8, 115, 12)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 30:
        police_spots = [(px2, py2) for py2 in range(12, 92, 12) for px2 in range(12, 112, 15)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100:
        park_spots = [(pkx, pky) for pky in range(15, 90, 10) for pkx in range(15, 110, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 200:
        stadium_spots = [
            (30, 15), (60, 15), (90, 15),
            (30, 50), (60, 50), (90, 50),
            (30, 85), (60, 85), (90, 85),
            (15, 30), (105, 30), (15, 70), (105, 70),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500:
        airport_spots = [
            (8, 5), (60, 5), (112, 5),
            (8, 95), (60, 95), (112, 95),
            (5, 30), (5, 70), (115, 30), (115, 70),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 800:
        seaport_spots = [
            (5, 50), (115, 50), (30, 5), (90, 5),
            (30, 95), (90, 95), (5, 15), (115, 15),
            (5, 85), (115, 85),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 2000:
        nuclear_spots = [
            (20, 10), (60, 10), (100, 10),
            (20, 50), (60, 50), (100, 50),
            (20, 90), (60, 90), (100, 90),
        ]
        for nx2, ny2 in nuclear_spots:
            if not ib(nx2, ny2):
                continue
            y0 = max(0, ny2-4); y1 = min(WORLD_H, ny2+5)
            x0 = max(0, nx2-4); x1 = min(WORLD_W, nx2+5)
            if not pm[y0:y1, x0:x1].any() and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- Fallback: extend wire from plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 13) % len(pxs)
        for offset in range(min(len(pxs), 50)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: extend road near wire ----
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 17) % len(wxs)
        for offset in range(min(len(wxs), 100)):
            k = (sk2 + offset * 3) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire+road spines to seed the city quickly."""
    actions = []
    # Three starting plants: left, center, right at mid-height
    starts = [(20, 50), (60, 50), (100, 50)]
    for px, py in starts:
        actions.append((Tool.COALPOWER, px, py))
        for dy in range(-4, 5):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense neighborhood grid: 8 cols x 7 rows = 56 neighborhoods
    nh_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    nh_rows = [10, 22, 35, 50, 65, 78, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 350:   return 7
        if pop < 700:   return 12
        if pop < 1500:  return 20
        if pop < 3000:  return 30
        if pop < 6000:  return 42
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: BUILD WIRE SPINES ----
    # Vertical wire at each hood's column, horizontal at each hood's row
    spine_range = 14
    # Only process a rotating subset to spread effort
    hood_subset = [h for i, h in enumerate(active_hoods) if (step + i) % max(len(active_hoods) // 4 + 1, 1) < max(len(active_hoods) // 4 + 1, 3)]

    for (hx, hy) in hood_subset:
        # Vertical wire spine
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wy = hy + sign * dist
                if not ib(hx, wy):
                    break
                if bool(pm[wy, hx]):
                    break
                if not bool(wm[wy, hx]):
                    # Need adjacency to power
                    prev_y = hy + sign * (dist - 1)
                    if ib(hx, prev_y) and (bool(wm[prev_y, hx]) or bool(pm[prev_y, hx])):
                        if bool(em[wy, hx]):
                            return (Tool.WIRE, hx, wy)
                    break

        # Horizontal wire spine
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wx = hx + sign * dist
                if not ib(wx, hy):
                    break
                if bool(pm[hy, wx]):
                    break
                if not bool(wm[hy, wx]):
                    prev_x = hx + sign * (dist - 1)
                    if ib(prev_x, hy) and (bool(wm[hy, prev_x]) or bool(pm[hy, prev_x])):
                        if bool(em[hy, wx]):
                            return (Tool.WIRE, wx, hy)
                    break

    # ---- PHASE 3: CONNECT WIRE BETWEEN HOODS ----
    # Connect horizontally adjacent hoods
    nh_col_spacing = 15
    nh_row_spacing_arr = [12, 13, 15, 15, 13, 12]  # spacing between rows
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and abs(hx2 - hx1) == 15 and hx2 > hx1:
                for cx in range(hx1 + 1, hx2):
                    if ib(cx, hy1) and not bool(pm[hy1, cx]):
                        if not bool(wm[hy1, cx]) and bool(em[hy1, cx]):
                            for adx in [-1, 1]:
                                ax = cx + adx
                                if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                                    return (Tool.WIRE, cx, hy1)
            if hx1 == hx2 and hy2 > hy1 and abs(hy2 - hy1) < 20:
                for cy in range(hy1 + 1, hy2):
                    if ib(hx1, cy) and not bool(pm[cy, hx1]):
                        if not bool(wm[cy, hx1]) and bool(em[cy, hx1]):
                            for ady in [-1, 1]:
                                ay = cy + ady
                                if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                                    return (Tool.WIRE, hx1, cy)

    # ---- PHASE 4: BUILD ROADS flanking wire spines ----
    road_subset = [h for i, h in enumerate(active_hoods) if (step + i * 3) % max(len(active_hoods) // 3 + 1, 1) < max(len(active_hoods) // 3 + 1, 4)]

    for (hx, hy) in road_subset:
        # Roads flanking vertical wire (columns hx-1 and hx+1)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy):
                continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Roads flanking horizontal wire (rows hy-1 and hy+1)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2):
                continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- PHASE 6: EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (8, 16), (28, 16), (48, 16), (68, 16), (88, 16), (108, 16),
            (8, 30), (28, 30), (48, 30), (68, 30), (88, 30), (108, 30),
            (8, 44), (28, 44), (48, 44), (68, 44), (88, 44), (108, 44),
            (8, 58), (28, 58), (48, 58), (68, 58), (88, 58), (108, 58),
            (8, 72), (28, 72), (48, 72), (68, 72), (88, 72), (108, 72),
            (8, 86), (28, 86), (48, 86), (68, 86), (88, 86), (108, 86),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [
            (18, 8), (48, 8), (78, 8), (108, 8),
            (18, 28), (48, 28), (78, 28), (108, 28),
            (18, 48), (48, 48), (78, 48), (108, 48),
            (18, 68), (48, 68), (78, 68), (108, 68),
            (18, 88), (48, 88), (78, 88), (108, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (30, 5), (60, 5), (90, 5),
            (30, 95), (60, 95), (90, 95),
            (5, 25), (5, 50), (5, 75),
            (115, 25), (115, 50), (115, 75),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [
            (3, 5), (58, 5), (116, 5),
            (3, 95), (58, 95), (116, 95),
            (3, 50), (116, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        seaports = [(5, 92), (115, 92), (5, 7), (115, 7), (60, 96)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(48, 5), (72, 5), (48, 93), (72, 93), (5, 48), (115, 48)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 200 and step % 3 == 0:
        zone_ys2, zone_xs2 = np.where(zone_tiles)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants at strategic positions with wire spines and flanking roads."""
    actions = []
    # Place 6 coal plants: 3 columns x 2 rows
    for px in [20, 60, 100]:
        for py in [25, 65]:
            actions.append((Tool.COALPOWER, px, py))
            # Vertical wire spine through the plant
            for dy in range(-8, 9):
                ny = py + dy
                if 0 <= ny < 100:
                    actions.append((Tool.WIRE, px, ny))
            # Flanking roads on both sides
            for dy in range(-8, 9):
                ny = py + dy
                if 0 <= ny < 100:
                    actions.append((Tool.ROAD, px - 1, ny))
                    actions.append((Tool.ROAD, px + 1, ny))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- NEIGHBORHOOD ANCHORS: 5x4 = 20 neighborhoods ----
    # Columns at x=12,32,52,72,92,112 (6 cols), rows at y=15,35,55,75 (4 rows)
    # Power plants at x=12,52,92, rows 25,65
    all_anchors = []
    for col_x in [12, 32, 52, 72, 92, 112]:
        for row_y in [15, 35, 55, 75, 90]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 500:   return 8
        if pop < 750:   return 10
        if pop < 1000:  return 12
        if pop < 1400:  return 15
        if pop < 1800:  return 18
        return 20

    n_active = min(num_active(), len(all_anchors))
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS near each anchor cluster ----
    # Power plant columns: 12, 52, 92 at rows 25, 65
    plant_targets = [(12, 25), (52, 25), (92, 25), (12, 65), (52, 65), (92, 65)]
    # Add more plants as population grows
    if pop > 400:
        plant_targets += [(32, 45), (72, 45), (112, 45)]
    if pop > 800:
        plant_targets += [(32, 10), (72, 10), (112, 10), (32, 80), (72, 80), (112, 80)]
    if pop > 1200:
        plant_targets += [(12, 10), (52, 10), (92, 10), (12, 90), (52, 90), (92, 90)]

    for (px, py) in plant_targets:
        if not ib(px, py):
            continue
        # Check if plant exists nearby (within 6)
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Place plant if possible
        if bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        # Find nearest empty spot
        for r in range(1, 8):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- BUILD WIRE NETWORK ----
    # Vertical wire spines at x=12,52,92 connecting top to bottom
    # Horizontal wire connections at multiple y-levels
    wire_spine_xs = [12, 52, 92]
    if pop > 400:
        wire_spine_xs += [32, 72, 112]

    # Extend vertical wire spines
    for wx in wire_spine_xs:
        if not ib(wx, 0):
            continue
        wire_col = [r for r in range(WORLD_H) if ib(wx, r) and bool(wm[r, wx])]
        plant_col = [r for r in range(WORLD_H) if ib(wx, r) and bool(pm[r, wx])]
        all_energized = sorted(set(wire_col + plant_col))
        if not all_energized:
            # No wire in this column; skip for now (plant should handle it)
            continue
        # Extend downward
        max_wr = max(all_energized)
        target_bot = WORLD_H - 3
        if max_wr < target_bot:
            ny = max_wr + 1
            if ib(wx, ny) and not bool(pm[ny, wx]):
                if bool(em[ny, wx]) or bool(wm[ny, wx]):
                    return (Tool.WIRE, wx, ny)
        # Extend upward
        min_wr = min(all_energized)
        target_top = 2
        if min_wr > target_top:
            ny = min_wr - 1
            if ib(wx, ny) and not bool(pm[ny, wx]):
                if bool(em[ny, wx]) or bool(wm[ny, wx]):
                    return (Tool.WIRE, wx, ny)

    # Horizontal wire connections between spine columns at every ~10 rows
    h_wire_rows = [5, 15, 25, 35, 45, 55, 65, 75, 85, 95]
    for hy in h_wire_rows:
        if not ib(0, hy):
            continue
        # Connect all active spine columns at this y
        active_spines = [wx for wx in wire_spine_xs if ib(wx, hy)]
        if len(active_spines) < 2:
            continue
        for i in range(len(active_spines) - 1):
            x1s = active_spines[i]
            x2s = active_spines[i + 1]
            for cx in range(x1s, x2s + 1):
                if ib(cx, hy) and bool(em[hy, cx]) and not bool(pm[hy, cx]):
                    return (Tool.WIRE, cx, hy)

    # ---- BUILD ROAD NETWORK ----
    # Vertical roads flanking wire spines (at wx-1 and wx+1)
    road_spine_xs = [12, 52, 92]
    if pop > 300:
        road_spine_xs += [32, 72, 112]

    for wx in road_spine_xs:
        for rx in [wx - 1, wx + 1]:
            if not ib(rx, 2):
                continue
            road_col = [r for r in range(WORLD_H) if ib(rx, r) and bool(rm[r, rx])]
            if not road_col:
                # Place first road segment near wire
                wire_col = [r for r in range(WORLD_H) if ib(wx, r) and (bool(wm[r, wx]) or bool(pm[r, wx]))]
                if wire_col:
                    mid_y = wire_col[len(wire_col) // 2]
                    if ib(rx, mid_y) and bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]):
                        return (Tool.ROAD, rx, mid_y)
            else:
                # Extend road downward
                max_rr = max(road_col)
                if max_rr < WORLD_H - 3:
                    ny = max_rr + 1
                    if ib(rx, ny) and bool(em[ny, rx]) and not bool(pm[ny, rx]):
                        return (Tool.ROAD, rx, ny)
                # Extend upward
                min_rr = min(road_col)
                if min_rr > 2:
                    ny = min_rr - 1
                    if ib(rx, ny) and bool(em[ny, rx]) and not bool(pm[ny, rx]):
                        return (Tool.ROAD, rx, ny)

    # Horizontal roads at regular y intervals
    h_road_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    if pop > 200:
        h_road_rows += [5, 15, 25, 35, 45, 55, 65, 75, 85, 95]
    for ry in h_road_rows:
        if not ib(0, ry):
            continue
        for cx in range(2, WORLD_W - 2):
            if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                # Only place if near wire
                x0, x1 = max(0, cx - 4), min(WORLD_W, cx + 5)
                y0, y1 = max(0, ry - 4), min(WORLD_H, ry + 5)
                if np.any(wm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1]):
                    return (Tool.ROAD, cx, ry)

    # ---- BUILD ZONES ----
    # Compute neighbor masks for roads and power
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Zone placement: find candidates near roads and power
    cand_mask = em & nbr_road & nbr_wire
    # Border margins
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Avoid placing on road/wire columns
    for wx in wire_spine_xs:
        if 0 <= wx < WORLD_W:
            cand_mask[:, wx] = False
        for rx in [wx - 1, wx + 1]:
            if 0 <= rx < WORLD_W:
                cand_mask[:, rx] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active anchors + prefer spread
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2])
                        and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to pop) ----
    if pop > 60:
        fire_spots = [
            (8, 8), (40, 8), (80, 8), (112, 8),
            (8, 30), (40, 30), (80, 30), (112, 30),
            (8, 50), (40, 50), (80, 50), (112, 50),
            (8, 70), (40, 70), (80, 70), (112, 70),
            (8, 90), (40, 90), (80, 90), (112, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (20, 5), (60, 5), (100, 5),
            (20, 45), (60, 45), (100, 45),
            (20, 85), (60, 85), (100, 85),
            (5, 25), (5, 65),
            (115, 25), (115, 65),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 12), (60, 12), (110, 12),
            (10, 50), (60, 50), (110, 50),
            (10, 88), (60, 88), (110, 88),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Nuclear power for extra juice
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0, x1 = max(0, nx2 - 5), min(WORLD_W, nx2 + 6)
                y0, y1 = max(0, ny2 - 5), min(WORLD_H, ny2 + 6)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 4), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_arr_y2, zone_arr_x2 = np.where(resm | comm | indm)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 40)):
                k = (step * 3 + i * 17) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y3, zone_arr_x3 = np.where(zone_tiles)
    if len(zone_arr_x3) > 0:
        k = (step * 19) % len(zone_arr_x3)
        zx2, zy2 = int(zone_arr_x3[k]), int(zone_arr_y3[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire spines and flanking roads in a central column."""
    actions = []
    # Place 3 coal plants at strategic positions
    for px, py in [(30, 30), (60, 50), (90, 70)]:
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            ny = py + dy
            if 0 <= ny < WORLD_H:
                actions.append((Tool.WIRE, px, ny))
        # Flanking roads
        for dy in range(-8, 9):
            ny = py + dy
            if 0 <= ny < WORLD_H:
                actions.append((Tool.ROAD, px - 1, ny))
                actions.append((Tool.ROAD, px + 1, ny))
    # Horizontal wire connectors between plants
    for cx in range(31, 60):
        actions.append((Tool.WIRE, cx, 30))
    for cx in range(61, 90):
        actions.append((Tool.WIRE, cx, 70))
    # Cross-connect at mid level
    for cy in range(31, 50):
        actions.append((Tool.WIRE, 60, cy))
    for cy in range(51, 70):
        actions.append((Tool.WIRE, 60, cy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['plant_idx'] = 0
        state['road_extend_step'] = 0

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Determine active plant targets based on population
    all_plant_targets = [
        (30, 30), (90, 30), (60, 50),
        (30, 70), (90, 70), (15, 50),
        (105, 50), (60, 15), (60, 85)
    ]

    def num_active_plants():
        if pop < 100:   return 2
        if pop < 300:   return 3
        if pop < 600:   return 4
        if pop < 1000:  return 5
        if pop < 1500:  return 6
        if pop < 2500:  return 7
        if pop < 4000:  return 8
        return 9

    n_active = num_active_plants()
    active_plants = all_plant_targets[:n_active]

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_road = dilate(rm, 3)
    near_power = dilate(wm | pm, 6)

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                t = tm[nr, nc]
                # Allow empty or existing zone tiles
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: ENSURE POWER PLANTS ARE PLACED ----
    for (px, py) in active_plants:
        # Check if plant exists nearby
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Try to place at target or nearby empty spot
        for r in range(0, 12):
            placed = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r and r > 0:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(zone_tiles[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if placed:
                break

    # ---- PHASE 2: WIRE SPINES FROM EACH PLANT ----
    spine_half = min(40, 10 + pop // 6)
    for (px, py) in active_plants:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            # Start wire right above/below plant
            for dy in range(-8, 9):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            # Extend downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            # Extend upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 3: HORIZONTAL WIRE connecting plants ----
    # Connect all plants to form a grid
    y_levels = sorted(set(py for (px, py) in active_plants))
    for yl in y_levels:
        row_plants = sorted([px for (px, py) in active_plants if py == yl])
        for i in range(len(row_plants) - 1):
            x1r, x2r = row_plants[i], row_plants[i + 1]
            for cx in range(x1r + 1, x2r):
                if ib(cx, yl) and not bool(pm[yl, cx]) and not bool(rm[yl, cx]):
                    if bool(em[yl, cx]) or bool(wm[yl, cx]):
                        if not bool(wm[yl, cx]):
                            return (Tool.WIRE, cx, yl)

    # Vertical wire connections between column plants
    x_cols = sorted(set(px for (px, py) in active_plants))
    for xc in x_cols:
        col_plants = sorted([py for (px, py) in active_plants if px == xc])
        for i in range(len(col_plants) - 1):
            y1c, y2c = col_plants[i], col_plants[i + 1]
            for cy in range(y1c + 1, y2c):
                if ib(xc, cy) and not bool(pm[cy, xc]) and not bool(rm[cy, xc]):
                    if bool(em[cy, xc]) or bool(wm[cy, xc]):
                        if not bool(wm[cy, xc]):
                            return (Tool.WIRE, xc, cy)

    # ---- PHASE 4: ROAD NETWORK ----
    # Build a grid-like road network across the map
    # Main horizontal roads at key y positions
    road_y_positions = []
    for py in sorted(set(py for (px, py) in active_plants)):
        road_y_positions.extend([py - 5, py + 5])

    # Add roads across full map width near wire spines
    for yl in road_y_positions:
        if not (3 <= yl < WORLD_H - 3):
            continue
        # Scan for gaps in road at this y
        for cx in range(5, WORLD_W - 5):
            if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]) and not bool(wm[yl, cx]):
                return (Tool.ROAD, cx, yl)

    # Flanking roads alongside wire spines
    for (px, py) in active_plants:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        for side in [-1, 1]:
            rx = px + side
            if not (0 < rx < WORLD_W - 1):
                continue
            for row in range(spine_top, spine_bot + 1):
                if ib(rx, row) and bool(em[row, rx]) and not bool(pm[row, rx]) and not bool(wm[row, rx]):
                    return (Tool.ROAD, rx, row)

    # Vertical connector roads
    for xc in x_cols:
        for rx in [xc - 2, xc + 2]:
            if not (0 < rx < WORLD_W - 1):
                continue
            for i in range(len(y_levels) - 1):
                y1v = y_levels[i] - 5
                y2v = y_levels[i + 1] + 5
                for cy in range(y1v, y2v + 1):
                    if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]) and not bool(wm[cy, rx]):
                        return (Tool.ROAD, rx, cy)

    # Cross roads to improve connectivity
    if step > 100 or pop > 50:
        for y_cross in range(10, WORLD_H - 10, 15):
            for cx in range(5, WORLD_W - 5):
                if ib(cx, y_cross) and bool(em[y_cross, cx]) and not bool(pm[y_cross, cx]) and not bool(wm[y_cross, cx]):
                    return (Tool.ROAD, cx, y_cross)

    # ---- PHASE 5: ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    # Margins
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Don't place on wire spine columns or plant rows
    for (px, py) in active_plants:
        cand_mask[py, :] = False
        cand_mask[:, px] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active plants
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_plants:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.9
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND POWER to unserved areas ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    if len(uzxs) > 0:
        power_src = wm | pm
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy == -1: shifted[:-1, :] = power_src[1:, :]
            elif dy == 1: shifted[1:, :] = power_src[:-1, :]
            elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
            else: shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & adj_to_power & ~zone_tiles & ~rm
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False
        wys_c, wxs_c = np.where(wire_cand)

        if len(wxs_c) > 0:
            best_d, best_k = 1e9, 0
            stride = max(1, len(uzxs) // 20)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                        for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d, best_k = d, i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 7: EXTEND ROADS to unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    if len(usxs) > 0:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            else: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
        road_cand2[0:2, :] = False
        road_cand2[WORLD_H - 2:, :] = False
        road_cand2[:, 0:2] = False
        road_cand2[:, WORLD_W - 2:] = False
        rys_c, rxs_c = np.where(road_cand2)

        if len(rxs_c) > 0:
            best_d, best_k = 1e9, 0
            stride = max(1, len(usxs) // 20)
            for i in range(len(rxs_c)):
                cx, cy = int(rxs_c[i]), int(rys_c[i])
                d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                        for j in range(0, len(usxs), stride))
                if d < best_d:
                    best_d, best_k = d, i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- PHASE 8: CIVIC SERVICES ----
    if pop > 30:
        fire_spots = [(fx, fy) for fy in range(8, 95, 15) for fx in range(8, 115, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and not bool(pm[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_spots = [(px2, py2) for py2 in range(10, 92, 18) for px2 in range(10, 112, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]) and not bool(pm[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 80:
        # Parks near zone clusters
        zone_arr_y, zone_arr_x = np.where(zone_tiles)
        if len(zone_arr_x) > 0:
            for i in range(min(len(zone_arr_x), 40)):
                k = (step * 3 + i * 17) % len(zone_arr_x)
                zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 400:
        stadium_spots = [(sx, sy) for sy in range(12, 90, 25) for sx in range(12, 110, 30)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]) and not bool(pm[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuke_spots = [(10, 10), (110, 10), (10, 90), (110, 90),
                      (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 45), (112, 45), (55, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]) and not bool(pm[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 92), (112, 92), (58, 95), (5, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]) and not bool(pm[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PHASE 9: WIRE EXTENSION from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- PHASE 10: ROAD extension from existing road near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: place road near a zone ----
    zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
    if len(zone_arr_x2) > 0:
        k = (step * 19) % len(zone_arr_x2)
        zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire + road spines in a central cluster."""
    actions = []
    # Two central power plants
    plants = [(40, 45), (80, 45)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire horizontally
        for dx in range(-6, 7):
            actions.append((Tool.WIRE, px + dx, py))
        # Wire vertically
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads above and below
        for dx in range(-5, 6):
            actions.append((Tool.ROAD, px + dx, py - 3))
            actions.append((Tool.ROAD, px + dx, py + 3))
        # Roads left and right of wire
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, px - 3, py + dy))
            actions.append((Tool.ROAD, px + 3, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 45% residential, 35% commercial, 20% industrial
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense grid of neighborhoods across the whole map
    # 6 columns x 7 rows = 42 anchors
    anchor_xs = [10, 28, 46, 64, 82, 100, 115]
    anchor_ys = [10, 22, 35, 50, 65, 78, 90]

    all_anchors = []
    for ax in anchor_xs:
        for ay in anchor_ys:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 20:    return 2
        if pop < 60:    return 4
        if pop < 150:   return 7
        if pop < 300:   return 10
        if pop < 500:   return 14
        if pop < 800:   return 18
        if pop < 1200:  return 24
        if pop < 2000:  return 32
        if pop < 3000:  return 40
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS for each active anchor ----
    plant_radius = 12
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - plant_radius); y1 = min(WORLD_H, ay + plant_radius + 1)
        x0 = max(0, ax - plant_radius); x1 = min(WORLD_W, ax + plant_radius + 1)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(0, 15):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- HORIZONTAL WIRE SPINES ----
    wire_half = min(20, 6 + pop // 10)
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            for dx in range(-3, 4):
                nx = ax + dx
                if ib(nx, ay) and bool(em[ay, nx]) and not bool(pm[ay, nx]):
                    return (Tool.WIRE, nx, ay)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, ay) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, ay) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)

    # ---- VERTICAL WIRE SPINES ----
    vert_half = min(15, 5 + pop // 15)
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            for dy in range(-3, 4):
                ny = ay + dy
                if ib(ax, ny) and bool(em[ny, ax]) and not bool(pm[ny, ax]):
                    return (Tool.WIRE, ax, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(ax, nr) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(ax, nr) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)

    # ---- INTER-ANCHOR WIRE CONNECTIONS (columns) ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1_ = col_anchors[i]
            _, y2_ = col_anchors[i + 1]
            for cy in range(y1_ + 1, y2_):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    return (Tool.WIRE, col_x, cy)

    # ---- INTER-ANCHOR WIRE CONNECTIONS (rows) ----
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1_, _ = row_anchors[i]
            x2_, _ = row_anchors[i + 1]
            for cx in range(x1_ + 1, x2_):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- ROAD GRID: horizontal roads above/below wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            continue
        cycle = (step + idx * 3) % 3
        for wc in wire_in_row[cycle::3]:
            for road_y_off in [-2, 2]:
                road_y = ay + road_y_off
                if ib(wc, road_y) and bool(em[road_y, wc]) and not bool(pm[road_y, wc]):
                    return (Tool.ROAD, wc, road_y)

    # ---- ROAD GRID: vertical roads flanking wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 4) % 3
        for wr in wire_in_col[cycle::3]:
            for road_x_off in [-2, 2]:
                road_x = ax + road_x_off
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- HORIZONTAL CONNECTING ROADS between anchors ----
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for horiz_y_off in [-3, 3]:
            hy = row_y + horiz_y_off
            if not (0 < hy < WORLD_H - 1):
                continue
            if len(row_anchors) >= 2:
                x_start = max(2, row_anchors[0][0] - 4)
                x_end = min(WORLD_W - 2, row_anchors[-1][0] + 4)
                for cx in range(x_start, x_end + 1):
                    if ib(cx, hy) and bool(em[hy, cx]) and not bool(pm[hy, cx]):
                        return (Tool.ROAD, cx, hy)

    # ---- VERTICAL CONNECTING ROADS between anchors ----
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for vert_x_off in [-3, 3]:
            vx = col_x + vert_x_off
            if not (0 < vx < WORLD_W - 1):
                continue
            if len(col_anchors) >= 2:
                y_start = max(2, col_anchors[0][1] - 4)
                y_end = min(WORLD_H - 2, col_anchors[-1][1] + 4)
                for cy in range(y_start, y_end + 1):
                    if ib(vx, cy) and bool(em[cy, vx]) and not bool(pm[cy, vx]):
                        return (Tool.ROAD, vx, cy)

    # ---- NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 1200:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scaled to population) ----
    # Fire stations early
    if pop > 20:
        fire_spots = []
        for fax in [10, 28, 46, 64, 82, 100, 115]:
            for fay in [10, 25, 40, 55, 70, 85]:
                fire_spots.append((fax, fay))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = []
        for pax in [15, 35, 55, 75, 95, 112]:
            for pay in [8, 22, 38, 52, 68, 82, 95]:
                police_spots.append((pax, pay))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (20, 5), (60, 5), (100, 5),
            (20, 93), (60, 93), (100, 93),
            (5, 45), (115, 45), (5, 70), (115, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 94), (90, 94),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 93), (30, 5), (85, 5), (5, 25), (115, 25)]:
            ax2, ay2 = asp
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5), (60, 2)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3), (3, -3), (-3, 3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder
# Strategy: dense grid of neighborhoods across the full map
# Each neighborhood has its own coal plant, wire cross, road grid, and zones
# Reactive: reads tile_map every step to decide next action

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-4, 5):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-4, 5):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-4, 5):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Dense neighborhood grid: 10 cols x 8 rows = 80 neighborhoods
    # Spaced ~12 apart horizontally, ~12 vertically
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [8, 20, 32, 44, 56, 68, 80, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 45
        if pop < 8000:  return 60
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active hood should have a plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center or nearby empty
            for r in range(8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CROSSES ----
    # For each hood, build horizontal and vertical wire spines through hood center
    spine_r = 10
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step // max(len(active_hoods), 1) + idx_h) % 5 != 0 and step % 5 != idx_h % 5:
            continue

        # Vertical spine at hx
        for dy in range(-spine_r, spine_r + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Need adjacency to power
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal spine at hy
        for dx in range(-spine_r, spine_r + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        # Connect to right neighbor
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 16:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Connect to bottom neighbor
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 16:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            # Rotate which hood we process each step to spread work
            pass

        # Roads at hx±1 (flanking vertical wire spine)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

        # Roads at hy±1 (flanking horizontal wire spine)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road neighbor mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [
            (16, 16), (40, 16), (64, 16), (88, 16), (112, 16),
            (16, 32), (40, 32), (64, 32), (88, 32), (112, 32),
            (16, 48), (40, 48), (64, 48), (88, 48), (112, 48),
            (16, 64), (40, 64), (64, 64), (88, 64), (112, 64),
            (16, 80), (40, 80), (64, 80), (88, 80), (112, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (28, 24), (56, 24), (84, 24), (112, 24),
            (14, 44), (42, 44), (70, 44), (98, 44),
            (28, 60), (56, 60), (84, 60), (112, 60),
            (14, 76), (42, 76), (70, 76), (98, 76),
            (28, 90), (56, 90), (84, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [
            (30, 30), (70, 30), (110, 30),
            (10, 55), (50, 55), (90, 55),
            (30, 75), (70, 75), (110, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(6, 88), (114, 88), (6, 10), (114, 10), (60, 6), (60, 94)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 8: PARKS to boost land value ----
    if pop > 200 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central power plant + cross-shaped wire + road seeds"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire across center
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire through center
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads on the main grid lines
    for x in range(10, 110, 1):
        if x < 58 or x > 62:
            actions.append((Tool.ROAD, x, 45))
    for x in range(10, 110, 1):
        if x < 58 or x > 62:
            actions.append((Tool.ROAD, x, 55))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Track state
    if 'phase' not in state:
        state['phase'] = 0
        state['plant_index'] = 0
        state['wire_row_index'] = 0
        state['wire_col_index'] = 0
        state['road_row_index'] = 0
        state['road_col_index'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone ratio: 45% RES, 30% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Power plant grid: 5x4 grid of plants ----
    # Spread across map with clear separation
    plant_xs = [15, 35, 55, 75, 95, 115]
    plant_ys = [15, 35, 55, 75, 90]

    # Build plant list prioritized by population thresholds
    plant_grid = []
    # Core plants (always needed)
    for py in [35, 55, 75]:
        for px in [20, 40, 60, 80, 100]:
            plant_grid.append((px, py))
    # Extended plants
    if pop >= 0:
        for py in [15, 90]:
            for px in [20, 40, 60, 80, 100]:
                plant_grid.append((px, py))
    if pop > 200:
        for px in [10, 110]:
            for py in [25, 50, 75]:
                plant_grid.append((px, py))
    if pop > 500:
        for py in [35, 55, 75]:
            for px in [30, 50, 70, 90]:
                plant_grid.append((px, py))

    # Place missing plants
    for ppx, ppy in plant_grid:
        if not ib(ppx, ppy):
            continue
        # Check if plant already near this location
        found = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = ppx+dx, ppy+dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            # Make sure we don't destroy a road
            if bool(em[ppy, ppx]) or bool(pm[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- Wire network: horizontal wires every 10 rows, vertical every 10 cols ----
    # Dense wire grid connecting all plants
    wire_rows = list(range(5, 100, 5))
    wire_cols = list(range(5, 120, 5))

    for wr in wire_rows:
        if not ib(0, wr):
            continue
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Seed from center
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and bool(em[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and bool(em[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left+1, right):
            if bool(em[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and bool(em[ny, wc]):
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and bool(em[ny, wc]):
                return (Tool.WIRE, wc, ny)
        for y in range(top+1, bot):
            if bool(em[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- Road grid: every 6 rows and cols ----
    road_rows = list(range(6, 100, 6))
    road_cols = list(range(6, 120, 6))

    for rr in road_rows:
        if not ib(0, rr):
            continue
        row_road = rm[rr, :]
        if not row_road.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_road)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-2 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        if not ib(rc, 0):
            continue
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_road)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-3 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- Zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    cand[0:4, :] = False
    cand[WORLD_H-4:, :] = False
    cand[:, 0:4] = False
    cand[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: prefer locations near roads AND wires AND existing zones
        # Use multiple scoring criteria
        min_plant_dist = np.full(len(cxs_arr), 999999.0)
        for ppx, ppy in plant_grid[:20]:
            if ib(ppx, ppy):
                d = (np.abs(cxs_arr - ppx).astype(float) + 
                     np.abs(cys_arr - ppy).astype(float))
                min_plant_dist = np.minimum(min_plant_dist, d)

        zone_score = min_plant_dist.copy()

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) + 
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                zone_score = zone_dist * 0.5 + min_plant_dist * 0.5

        order = np.argsort(zone_score)
        # Deterministic offset for variety
        off = (step * 13 + pop * 3) % max(len(order), 1)
        placed = 0
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # ---- Civic services based on population ----
    if pop > 5:
        fire_spots = [(fx, fy) for fy in range(12, 95, 12) for fx in range(12, 112, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and not bool(pm[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 30:
        police_spots = [(px2, py2) for py2 in range(18, 88, 14) for px2 in range(18, 108, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]) and not bool(pm[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100:
        park_spots = [(pkx, pky) for pky in range(10, 95, 10) for pkx in range(10, 115, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]) and not bool(pm[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 200:
        stadium_spots = [
            (30, 20), (60, 20), (90, 20),
            (30, 50), (60, 50), (90, 50),
            (30, 80), (60, 80), (90, 80),
            (15, 35), (105, 35), (15, 65), (105, 65),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]) and not bool(pm[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500:
        airport_spots = [
            (10, 8), (55, 8), (105, 8),
            (10, 92), (55, 92), (105, 92),
            (8, 30), (8, 70), (112, 30), (112, 70),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]) and not bool(pm[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 800:
        seaport_spots = [
            (5, 50), (115, 50), (30, 5), (90, 5),
            (30, 95), (90, 95), (60, 5), (60, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]) and not bool(pm[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 2000:
        nuclear_spots = [
            (25, 25), (95, 25), (25, 75), (95, 75),
            (60, 50), (45, 10), (75, 10), (45, 90), (75, 90),
            (10, 50), (110, 50),
        ]
        for nx2, ny2 in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- Fallback: extend wire from plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 30)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: road near wire ----
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 17) % len(wxs)
        for offset in range(min(len(wxs), 80)):
            k = (sk2 + offset * 3) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0,2),(0,-2),(2,0),(-2,0),(0,3),(0,-3),(3,0),(-3,0)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place 2 coal plants with wire+road connections"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally through center
    for x in range(33, 88, 1):
        actions.append((Tool.WIRE, x, 50))
    # Roads above and below center plants
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Count how many plants exist
    plant_count = int(np.sum(pm))

    # ---- PHASE 1: Ensure enough coal plants spread across map ----
    # Dense grid of plants: one every 18 tiles in x, 16 in y
    plant_grid = []
    for py in range(12, 95, 16):
        for px in range(12, 115, 18):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire expansion - connect plants to each other ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)

    # Find unpowered plants to connect
    unpowered_plants = [(px, py) for px, py in plant_grid
                        if ib(px, py) and np.any(pm[max(0,py-4):min(WORLD_H,py+5),
                                                     max(0,px-4):min(WORLD_W,px+5)])
                        and not bool(near_power[py, px])]

    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(len(wxs)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants)
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid - horizontal roads every 6 rows, vertical every 8 cols ----
    # Build road grid reactively based on what's powered
    road_rows = list(range(8, 97, 6))
    road_cols = list(range(8, 117, 8))

    # Find road grid intersections that need roads
    for ry in road_rows:
        for rx in road_cols:
            if not ib(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            # Only build road if near power
            if not bool(near_power[ry, rx]):
                continue
            # Check if there's existing road nearby to connect to
            x0, x1 = max(0, rx-10), min(WORLD_W, rx+11)
            y0, y1 = max(0, ry-10), min(WORLD_H, ry+11)
            if np.any(rm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1]):
                if bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Connect road row segments
    for ry in road_rows:
        if not bool(near_power[ry, WORLD_W//2]):
            continue
        for rx in range(5, WORLD_W-5):
            if not ib(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            if bool(zone_tiles[ry, rx]):
                continue
            if bool(near_power[ry, rx]) and bool(em[ry, rx]):
                # Check neighbor is road
                has_road_neighbor = False
                for dx in [-1, 1]:
                    if ib(rx+dx, ry) and bool(rm[ry, rx+dx]):
                        has_road_neighbor = True
                if has_road_neighbor:
                    return (Tool.ROAD, rx, ry)

    # Connect road col segments
    for rx in road_cols:
        for ry in range(5, WORLD_H-5):
            if not ib(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            if bool(zone_tiles[ry, rx]):
                continue
            if bool(near_power[ry, rx]) and bool(em[ry, rx]):
                has_road_neighbor = False
                for dy in [-1, 1]:
                    if ib(rx, ry+dy) and bool(rm[ry+dy, rx]):
                        has_road_neighbor = True
                if has_road_neighbor:
                    return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Wire to extend power reach ----
    if len(wxs) > 0:
        # Extend wire toward zones that need power
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered road tiles
        unpowered_roads = rm & ~near_power
        ury, urx = np.where(unpowered_roads)
        if len(urx) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 200)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - rx2) + abs(cy - ry2) for rx2, ry2 in zip(urx[:50], ury[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 5: Zone placement (reactive, zone-mix aware) ----
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Zone candidates: empty, near road, near power, not at edge
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False
    # Don't place zones on road rows/cols (keep them clear)
    for ry in road_rows:
        if 0 <= ry < WORLD_H:
            zone_cand[ry, :] = False
    for rx in road_cols:
        if 0 <= rx < WORLD_W:
            zone_cand[:, rx] = False

    def zone_clear(zx, zy):
        """Check 3x3 footprint is clear"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer positions with nearby roads and power, spread across map
        road_near = dilate(rm, 1)
        road_score = road_near[cys_arr, cxs_arr].astype(float)

        # Spread: prefer areas with fewer existing zones nearby
        zone_density = dilate(zone_tiles, 4)
        density_score = zone_density[cys_arr, cxs_arr].astype(float)

        # Combine: want near road, low zone density
        score = -road_score * 2.0 + density_score * 1.5

        # Add some spatial spread by quadrant
        # Prefer quadrant with fewest zones
        quad_counts = np.zeros((2, 2))
        quad_counts[0, 0] = np.sum(zone_tiles[:50, :60])
        quad_counts[0, 1] = np.sum(zone_tiles[:50, 60:])
        quad_counts[1, 0] = np.sum(zone_tiles[50:, :60])
        quad_counts[1, 1] = np.sum(zone_tiles[50:, 60:])
        # Bonus for underserved quadrant
        for i in range(len(cxs_arr)):
            qx = 1 if cxs_arr[i] >= 60 else 0
            qy = 1 if cys_arr[i] >= 50 else 0
            score[i] += quad_counts[qy, qx] * 0.01

        order = np.argsort(score)
        tool = pick_tool()
        # Use step-based offset for variety
        off = (step * 17 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 6: Civic services (reactive to pop) ----
    if pop > 100:
        fire_locs = [(fx, fy) for fy in range(10, 95, 12) for fx in range(10, 115, 12)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]) and bool(near_road[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_locs = [(px2, py2) for py2 in range(14, 90, 14) for px2 in range(14, 112, 14)]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_locs = [(px3, py3) for py3 in range(12, 90, 8) for px3 in range(12, 112, 8)]
        for pkx, pky in park_locs:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_power[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 800:
        stadium_locs = [(25, 25), (95, 25), (25, 75), (95, 75),
                        (60, 15), (60, 85), (15, 50), (105, 50),
                        (45, 40), (75, 40), (45, 60), (75, 60)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (60, 20), (60, 80), (40, 50), (80, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-5), min(WORLD_W, nx+6)
                y0, y1 = max(0, ny-5), min(WORLD_H, ny+6)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2500:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 92), (5, 45), (112, 45)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(10, 50), (110, 50), (60, 10), (60, 90),
                        (20, 20), (100, 20), (20, 80), (100, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from existing plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dist in [3, 6, 9]:
            for dx2, dy2 in [(dist, 0), (-dist, 0), (0, dist), (0, -dist),
                              (dist, dist), (-dist, dist), (dist, -dist), (-dist, -dist)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire ----
    if len(pwr_xs) > 0:
        k = (step * 3) % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1),
                          (2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire/road seeds across the map."""
    actions = []
    # Three initial plants spread horizontally at mid-height
    plants = [(30, 50), (60, 50), (90, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire column seeds
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px + 2, py + dy))
        # Road seeds flanking wire
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px + 1, py + dy))
            actions.append((Tool.ROAD, px + 3, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- Define a grid of neighborhoods across the full map ---
    # 6 cols x 5 rows = 30 neighborhoods
    # cols at x: 10, 30, 50, 70, 90, 110
    # rows at y: 10, 28, 46, 64, 82 (avoiding edges and spacing ~18 apart)
    nh_cols = [10, 30, 50, 70, 90, 110]
    nh_rows = [10, 28, 46, 64, 82]
    nh_positions = [(cx, cy) for cy in nh_rows for cx in nh_cols]

    # Unlock neighborhoods progressively
    def get_active_hoods():
        if pop < 200:
            return [(50, 46), (70, 46), (30, 46), (50, 28), (70, 28)]
        elif pop < 500:
            return [(cx, cy) for cy in [28, 46, 64] for cx in [30, 50, 70, 90]]
        elif pop < 1200:
            return [(cx, cy) for cy in [10, 28, 46, 64, 82] for cx in [10, 30, 50, 70, 90, 110]
                    if 0 < cx < 120 and 0 < cy < 100]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # --- Power plant anchors: one per active neighborhood cluster ---
    # One plant per ~3 neighborhoods (every other column, every other row)
    def get_plant_anchors():
        if pop < 200:
            return [(32, 46), (62, 46)]
        elif pop < 500:
            return [(32, 28), (62, 28), (92, 28),
                    (32, 46), (62, 46), (92, 46),
                    (32, 64), (62, 64), (92, 64)]
        else:
            return [(32, y) for y in [10, 28, 46, 64, 82]] + \
                   [(62, y) for y in [10, 28, 46, 64, 82]] + \
                   [(92, y) for y in [10, 28, 46, 64, 82]]

    plant_anchors = get_plant_anchors()

    # Wire spine columns and road columns for each cluster
    # Pattern: plant at (px, py), wire at (px+2, *), roads at (px+1, *) and (px+3, *)
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (px, py) in plant_anchors:
        # Check if plant exists nearby
        x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
        y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place at or near anchor
            for r in range(8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    # For each plant anchor, build a vertical wire spine
    # Wire col = px+2, extend to cover neighborhood zone range
    phase = step % 8

    if phase in (0, 1):
        for (px, py) in plant_anchors:
            wc = px + 2
            if not ib(wc, py):
                continue
            # Find extent of wire in this column
            col_wire = [(r, wm[r, wc] or pm[r, wc]) for r in range(WORLD_H) if ib(wc, r)]
            wrows = [r for (r, w) in col_wire if w]

            # Desired spine extent based on population
            half_ext = min(14 + pop // 50, 40)
            spine_top = max(2, py - half_ext)
            spine_bot = min(WORLD_H - 3, py + half_ext)

            if not wrows:
                # Seed wire at anchor
                if ib(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                    return (Tool.WIRE, wc, py)
                continue

            min_wr, max_wr = min(wrows), max(wrows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)

    elif phase == 2:
        # Horizontal wire connections between adjacent spine columns at anchor rows
        anchor_ys = list(set(py for (px, py) in plant_anchors))
        for ay in anchor_ys:
            # Get wire cols at this y row that have wire
            cols_with_wire = [px + 2 for (px, py) in plant_anchors if py == ay and
                              ib(px + 2, ay) and (bool(wm[ay, px + 2]) or bool(pm[ay, px + 2]))]
            if len(cols_with_wire) < 2:
                continue
            cols_with_wire.sort()
            for i in range(len(cols_with_wire) - 1):
                c1, c2 = cols_with_wire[i], cols_with_wire[i + 1]
                for cx in range(c1, c2 + 1):
                    if ib(cx, ay) and bool(em[ay, cx]) and not bool(pm[ay, cx]):
                        return (Tool.WIRE, cx, ay)

    elif phase in (3, 4):
        # Roads flanking wire spines
        for (px, py) in plant_anchors:
            wc = px + 2
            rl, rr = px + 1, px + 3
            wire_in_col = [r for r in range(WORLD_H)
                           if ib(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]
            if not wire_in_col:
                continue
            sub = wire_in_col[(step // 2) % max(len(wire_in_col), 1)::4]
            for wr in sub:
                if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                    return (Tool.ROAD, rl, wr)
                if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                    return (Tool.ROAD, rr, wr)

    elif phase == 5:
        # Horizontal connector roads between neighborhoods
        # Build horizontal roads at anchor rows connecting road columns
        anchor_ys = list(set(py for (_, py) in plant_anchors))
        for ay in anchor_ys:
            for road_y_off in [-1, 1]:
                ry = ay + road_y_off
                if not (0 < ry < WORLD_H - 1):
                    continue
                # Find existing roads in this row
                row_roads = rm[ry, :]
                if not np.any(row_roads):
                    continue
                for cx in range(1, WORLD_W - 1):
                    if bool(em[ry, cx]) and not bool(pm[ry, cx]):
                        # Check if adjacent road
                        if (ib(cx - 1, ry) and bool(rm[ry, cx - 1])) or \
                           (ib(cx + 1, ry) and bool(rm[ry, cx + 1])):
                            if bool(near_power[ry, cx]):
                                return (Tool.ROAD, cx, ry)

    elif phase in (6, 7):
        # Zone placement
        cand_mask = em & near_road & near_power
        cand_mask[0:3, :] = False
        cand_mask[WORLD_H - 3:, :] = False
        cand_mask[:, 0:3] = False
        cand_mask[:, WORLD_W - 3:] = False

        # Avoid wire spines (to protect infrastructure)
        for (px, py) in plant_anchors:
            wc = px + 2
            if 0 <= wc < WORLD_W:
                cand_mask[:, wc] = False

        cys2, cxs2 = np.where(cand_mask)
        if len(cxs2) > 0:
            best_dist = np.full(len(cxs2), 999999.0)
            for (hx, hy) in active_hoods:
                d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
                best_dist = np.minimum(best_dist, d)
            order = np.argsort(best_dist)
            offset = (step * 7 + pop * 3) % max(len(order), 1)
            tool = pick_tool()
            checked = 0
            for i in range(len(order)):
                k = order[(offset + i) % len(order)]
                zx, zy = int(cxs2[k]), int(cys2[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)
                checked += 1
                if checked > 400:
                    break

    # ---- ZONE PLACEMENT FALLBACK (every step if above didn't return) ----
    cand_mask2 = em & near_road & near_power
    cand_mask2[0:3, :] = False
    cand_mask2[WORLD_H - 3:, :] = False
    cand_mask2[:, 0:3] = False
    cand_mask2[:, WORLD_W - 3:] = False
    cys3, cxs3 = np.where(cand_mask2)
    if len(cxs3) > 0:
        best_dist2 = np.full(len(cxs3), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs3 - hx).astype(float) + np.abs(cys3 - hy).astype(float)
            best_dist2 = np.minimum(best_dist2, d)
        order2 = np.argsort(best_dist2)
        offset2 = (step * 11 + pop * 5) % max(len(order2), 1)
        tool2 = pick_tool()
        checked2 = 0
        for i in range(len(order2)):
            k = order2[(offset2 + i) % len(order2)]
            zx2, zy2 = int(cxs3[k]), int(cys3[k])
            if zone_clear(zx2, zy2):
                return (tool2, zx2, zy2)
            checked2 += 1
            if checked2 > 300:
                break

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [(20, 20), (60, 20), (100, 20),
                      (20, 46), (60, 46), (100, 46),
                      (20, 72), (60, 72), (100, 72)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [(35, 28), (75, 28), (110, 46),
                        (10, 46), (55, 64), (95, 64),
                        (35, 82), (75, 82), (20, 10), (100, 10)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(45, 40), (75, 40), (45, 64), (75, 64),
                    (20, 52), (100, 52), (10, 25), (110, 25)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [(5, 5), (115, 5), (5, 93), (115, 93),
                      (58, 5), (58, 93), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(10, 93), (110, 93), (10, 5), (110, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(50, 5), (65, 5), (50, 93), (65, 93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near zones to boost land value
    if pop > 200 and step % 9 == 0:
        pk = em & near_road & near_power
        pys, pxs = np.where(pk)
        if len(pxs) > 0:
            idx = (step * 37) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire toward unpowered active hoods ----
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            thx, thy = unpowered[0]
            dists = np.abs(wire_xs_a - thx) + np.abs(wire_ys_a - thy)
            bi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[bi]), int(wire_ys_a[bi])
            dx = 0 if thx == bwx else (1 if thx > bwx else -1)
            dy = 0 if thy == bwy else (1 if thy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend road from existing roads near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend any wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: multiple power plants + wire spines + seed roads + initial zones"""
    actions = []
    # Three power plants spread across map
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine connecting all plants
    for x in range(28, 93):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for y in range(36, 65):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 90, y))
    # Seed roads for three neighborhoods
    for x in range(22, 42):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for x in range(52, 72):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for x in range(82, 102):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # Zone ratio: 50% res, 25% com, 25% ind
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure enough power plants ----
    # Dense grid: every 15 cols, 15 rows
    plant_grid_xs = list(range(8, WORLD_W - 5, 15))
    plant_grid_ys = list(range(8, WORLD_H - 5, 15))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network ----
    # Horizontal wire rows every 15 rows
    wire_rows = list(range(8, WORLD_H - 5, 15))
    # Vertical wire cols every 15 cols
    wire_cols = list(range(8, WORLD_W - 5, 15))

    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                nearest = pxs[np.argmin(np.abs(pys - wr))]
                if ib(int(nearest), wr) and bool(em[wr, int(nearest)]):
                    return (Tool.WIRE, int(nearest), wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right+1]):
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and bool(em[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads placed between wire rows (6 tiles offset from each wire row)
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 5)
        road_rows.append(wr + 5)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 5)
        road_cols.append(wc + 5)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement (closed-loop) ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Don't place on infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer spots that are close to existing zones (for density) but not on top
            zone_score = np.where(min_zone_dist < 3, 1000.0, np.where(min_zone_dist > 20, min_zone_dist, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Score: prefer close to roads, not too far from existing zones
        score = road_dist * 2.0 + zone_score * 0.3

        order = np.argsort(score)
        off = (step * 7 + pop) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(8, 95, 8) for fx in range(8, 114, 14)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_spots = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 16)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_spots = [(pkx, pky) for pky in range(12, 90, 8) for pkx in range(12, 110, 10)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 800:
        stadium_spots = [(sx, sy) for sy in range(16, 88, 20) for sx in range(16, 104, 24)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        # Nuclear power for large cities
        nuclear_spots = [(nx, ny) for ny in range(12, 90, 20) for nx in range(12, 110, 20)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx-12), min(WORLD_W, npx+13)
                y0, y1 = max(0, npy-12), min(WORLD_H, npy+13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [
            (55, 7), (65, 7), (55, 92), (65, 92),
            (7, 44), (112, 44), (7, 56), (112, 56),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_spots = [
            (7, 50), (112, 50), (60, 4), (60, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: place road near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(7,0),(-7,0),(0,7),(0,-7),(5,0),(-5,0),(0,5),(0,-5)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants arranged in a 2x2 grid with wire and road spines."""
    actions = []
    # Plants at 4 corners of a central cluster
    plant_positions = [(30, 25), (90, 25), (30, 75), (90, 75)]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine horizontally
        for dx in range(-8, 9):
            actions.append((Tool.WIRE, px + dx, py))
        # Wire spine vertically
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads above and below wire spine
        for dx in range(-8, 9):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 45% residential, 35% commercial, 20% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 neighborhoods in a 3x3 grid spread across the map
    anchors_all = []
    for col_x in [20, 60, 100]:
        for row_y in [20, 50, 80]:
            anchors_all.append((col_x, row_y))

    def num_active():
        if pop < 30:    return 1
        if pop < 100:   return 2
        if pop < 250:   return 3
        if pop < 500:   return 5
        if pop < 900:   return 7
        return 9

    n_active = num_active()
    active_anchors = anchors_all[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        has_plant = False
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE CROSS PATTERN (horizontal + vertical from each anchor) ----
    wire_reach = min(25, 6 + pop // 10)
    for (px, py) in active_anchors:
        # Horizontal wire
        for dx in range(-wire_reach, wire_reach + 1):
            wx = px + dx
            if ib(wx, py) and bool(em[py, wx]) and not bool(pm[py, wx]):
                return (Tool.WIRE, wx, py)
        # Vertical wire
        for dy in range(-wire_reach, wire_reach + 1):
            wy = py + dy
            if ib(px, wy) and bool(em[wy, px]) and not bool(pm[wy, px]):
                return (Tool.WIRE, px, wy)

    # ---- CONNECT ANCHORS WITH WIRE GRID ----
    # Horizontal connections between anchors at same row
    y_levels = sorted(set(py for (_, py) in active_anchors))
    x_levels = sorted(set(px for (px, _) in active_anchors))
    for yl in y_levels:
        row_xs = sorted([px for (px, py) in active_anchors if py == yl])
        for i in range(len(row_xs) - 1):
            for cx in range(row_xs[i], row_xs[i+1] + 1):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)
    # Vertical connections
    for xl in x_levels:
        col_ys = sorted([py for (px, py) in active_anchors if px == xl])
        for i in range(len(col_ys) - 1):
            for cy in range(col_ys[i], col_ys[i+1] + 1):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: roads parallel to wire spines ----
    road_offsets = [-2, 2]  # roads run parallel to wire at offset 2
    for (px, py) in active_anchors:
        # Horizontal roads (above and below horizontal wire)
        for ro in road_offsets:
            ry = py + ro
            for dx in range(-wire_reach, wire_reach + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)
        # Vertical roads (left and right of vertical wire)
        for ro in road_offsets:
            rx = px + ro
            for dy in range(-wire_reach, wire_reach + 1):
                ry = py + dy
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (placed near active anchors) ----
    if pop > 60:
        fire_spots = [
            (8, 10), (38, 10), (68, 10), (98, 10), (118, 10),
            (8, 40), (38, 40), (68, 40), (98, 40), (118, 40),
            (8, 70), (38, 70), (68, 70), (98, 70), (118, 70),
            (8, 90), (38, 90), (68, 90), (98, 90), (118, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 85), (45, 85), (75, 85), (105, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (12, 35), (55, 35), (95, 35),
            (12, 60), (55, 60), (95, 60),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Add nuclear plants at corners
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# High-reactivity closed-loop city builder
# Strategy: dense neighborhood grid, aggressive infrastructure expansion,
# reactive zone placement, strong civic services

def init(obs, state):
    """Bootstrap: 3 coal plants with wire+road connections."""
    actions = []
    # Three starting plants spread across map
    plants = [(30, 50), (60, 50), (90, 50)]
    for cx, cy in plants:
        actions.append((Tool.COALPOWER, cx, cy))
        # Wire cross
        for dx in range(-2, 3):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-2, 3):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Roads flanking
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID ----
    # 10 cols x 9 rows = 90 neighborhoods, spaced ~12 apart
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [8, 19, 30, 42, 53, 64, 75, 86, 97]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock
    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 32
        if pop < 4000:  return 50
        if pop < 8000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly across map
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    # ---- PHASE 1: POWER PLANTS ----
    # Each active hood needs a plant within 10 tiles
    plant_ys, plant_xs = np.where(pm)

    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center if empty, else spiral out
            for r in range(12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    # Vertical wire at each hood's column, horizontal at each hood's row
    # Only process a rotating subset per step
    n_hoods = len(active_hoods)
    hood_batch = max(1, n_hoods // 4)
    batch_start = (step % max(1, n_hoods // hood_batch)) * hood_batch

    for idx_h in range(hood_batch):
        hood_idx = (batch_start + idx_h) % n_hoods
        hx, hy = active_hoods[hood_idx]
        spine_r = 10

        # Vertical wire spine at hx
        for dy in range(-spine_r, spine_r + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Need adjacency to existing power
            for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                ax, ay = hx + adx, wy + ady
                if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal wire spine at hy
        for dx in range(-spine_r, spine_r + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                ax, ay = wx + adx, hy + ady
                if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN HOODS ----
    # Build horizontal/vertical wire bridges between neighboring hood pairs
    hood_set = set(active_hoods)
    col_spacing = 12
    row_spacing = 11

    bridge_batch = (step // 3) % max(1, n_hoods)
    for bidx in range(min(n_hoods, 8)):
        hood_idx = (bridge_batch + bidx) % n_hoods
        hx1, hy1 = active_hoods[hood_idx]

        # Horizontal bridge to right neighbor
        hx2 = hx1 + col_spacing
        hy2 = hy1
        if (hx2, hy2) in hood_set or any(abs(h[0]-hx2)<3 and abs(h[1]-hy2)<3 for h in active_hoods):
            for cx in range(hx1+1, hx2):
                if not ib(cx, hy1): continue
                if bool(wm[hy1, cx]) or bool(pm[hy1, cx]): continue
                if not bool(em[hy1, cx]): continue
                for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = cx+adx, hy1+ady
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        return (Tool.WIRE, cx, hy1)

        # Vertical bridge to bottom neighbor
        hx3, hy3 = hx1, hy1 + row_spacing
        if (hx3, hy3) in hood_set or any(abs(h[0]-hx3)<3 and abs(h[1]-hy3)<3 for h in active_hoods):
            for cy in range(hy1+1, hy3):
                if not ib(hx1, cy): continue
                if bool(wm[cy, hx1]) or bool(pm[cy, hx1]): continue
                if not bool(em[cy, hx1]): continue
                for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = hx1+adx, cy+ady
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        return (Tool.WIRE, hx1, cy)

    # ---- PHASE 4: ROADS along wire spines ----
    road_batch = (step // 2) % max(1, n_hoods)
    for bidx in range(min(n_hoods, 6)):
        hood_idx = (road_batch + bidx) % n_hoods
        hx, hy = active_hoods[hood_idx]
        spine_r = 10

        # Roads at hx-1, hx+1 flanking vertical spine
        for offset_x in [-1, 1]:
            rx = hx + offset_x
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                # Only place road if wire/plant exists in spine at this y
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

        # Roads at hy-1, hy+1 flanking horizontal spine
        for offset_y in [-1, 1]:
            ry2 = hy + offset_y
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- BUILD POWER/ROAD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H-dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W-dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H+dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W+dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H-dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W-dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H+dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W+dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 100:
        # Dense fire station grid
        fire_spacing = 20
        fire_spots = []
        for fy in range(15, WORLD_H-5, fire_spacing):
            for fx in range(15, WORLD_W-5, fire_spacing):
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spacing = 25
        police_spots = []
        for py in range(20, WORLD_H-5, police_spacing):
            for px in range(20, WORLD_W-5, police_spacing):
                police_spots.append((px, py))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (25, 25), (55, 25), (85, 25), (110, 25),
            (25, 50), (55, 50), (85, 50), (110, 50),
            (25, 75), (55, 75), (85, 75), (110, 75),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(5, 80), (114, 80), (5, 20), (114, 20), (60, 5), (60, 94)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 5), (75, 5), (45, 93), (75, 93), (5, 45), (113, 45)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS to boost land value ----
    if pop > 200 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % len(wire_xs2)
        for offset in range(min(len(wire_xs2), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx)==r or abs(dy)==r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in a grid with wire spines and flanking roads."""
    actions = []
    # Plant positions: 2 rows x 2 cols, spread across map
    plant_positions = [(30, 30), (90, 30), (30, 70), (90, 70)]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-5, 6):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 30% ind, 30% com, 40% res
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Expand cluster set as population grows - full 3x4 grid of clusters
    all_clusters = [
        (20, 20), (50, 20), (80, 20), (110, 20),
        (20, 50), (50, 50), (80, 50), (110, 50),
        (20, 80), (50, 80), (80, 80), (110, 80),
    ]

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 3
        if pop < 300:  return 4
        if pop < 500:  return 5
        if pop < 800:  return 6
        if pop < 1200: return 8
        if pop < 2000: return 10
        return 12

    n_active = num_active()
    active_centers = all_clusters[:n_active]

    # --- ENSURE POWER PLANTS ---
    for (px, py) in active_centers:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            # Try center first
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Spiral search
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- WIRE SPINE (vertical) per cluster ---
    spine_half = min(30, 10 + pop // 10)
    for (px, py) in active_centers:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check which parts of spine exist
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(px, r) and bool(wm[r, px])]
        if not wire_rows:
            # Build initial spine near plant
            for dy2 in range(-5, 6):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            max_wr = max(wire_rows)
            min_wr = min(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # --- HORIZONTAL WIRE connecting clusters in same row ---
    row_ys = sorted(set(py for (px, py) in active_centers))
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl], key=lambda a: a[0])
        for i in range(len(row_cs) - 1):
            x1c = row_cs[i][0]
            x2c = row_cs[i + 1][0]
            for cx in range(x1c + 1, x2c):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # --- VERTICAL WIRE connecting rows ---
    if n_active >= 4:
        col_xs = sorted(set(px for (px, py) in active_centers))
        for xc in col_xs:
            col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc], key=lambda a: a[1])
            for i in range(len(col_cs) - 1):
                y1c = col_cs[i][1]
                y2c = col_cs[i + 1][1]
                for cy in range(y1c + 1, y2c):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # --- ROAD flanking wire spines (both sides) ---
    for idx, (px, py) in enumerate(active_centers):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(px, r) and bool(wm[r, px])]
        if not wire_rows:
            continue
        cycle = (step + idx * 7) % 2
        for side_dx in [-2, 2]:
            rl = px + side_dx
            for wr in wire_rows[cycle::2]:
                if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                    return (Tool.ROAD, rl, wr)

    # --- HORIZONTAL ROADS connecting clusters at row y-levels ---
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl], key=lambda a: a[0])
        if len(row_cs) < 2:
            continue
        x_left = row_cs[0][0] - 2
        x_right = row_cs[-1][0] + 2
        for horiz_offset in [-4, 4, -8, 8]:
            horiz_y = yl + horiz_offset
            if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                continue
            for cx in range(x_left, x_right + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # --- VERTICAL ROADS connecting row clusters ---
    if pop > 100:
        col_xs_r = sorted(set(px for (px, py) in active_centers))
        for xc in col_xs_r:
            col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc], key=lambda a: a[1])
            for i in range(len(col_cs) - 1):
                y1c = col_cs[i][1]
                y2c = col_cs[i + 1][1]
                for road_off in [-2, 2]:
                    rxc = xc + road_off
                    for cy in range(y1c, y2c + 1):
                        if ib(rxc, cy) and bool(em[cy, rxc]) and not bool(pm[cy, rxc]):
                            return (Tool.ROAD, rxc, cy)

    # --- BUILD NEIGHBOR MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_centers:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES ---
    # Fire stations distributed across active clusters
    if pop > 60:
        fire_offsets = [(-8, -8), (8, -8), (-8, 8), (8, 8), (0, -10), (0, 10)]
        for (px, py) in active_centers:
            for fo_x, fo_y in fire_offsets:
                sx, sy = px + fo_x, py + fo_y
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_offsets = [(-10, 0), (10, 0), (0, -10), (0, 10)]
        for (px, py) in active_centers:
            for po_x, po_y in police_offsets:
                sx, sy = px + po_x, py + po_y
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 50), (115, 50),
            (5, 95), (60, 95), (115, 95),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear power for extra capacity
    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PARKS to boost land value near zones ---
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- FALLBACK: extend wire from existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: road near zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

