    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Dense neighborhood grid: 8 cols x 6 rows = 48 neighborhoods
    nh_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    nh_rows = [12, 27, 42, 57, 72, 87]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 300:   return 10
        if pop < 600:   return 16
        if pop < 1200:  return 24
        if pop < 2500:  return 34
        if pop < 5000:  return 44
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        # Find nearest empty spot
        for r in range(12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    spine_range = 14

    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Rotate through hoods each step to avoid always picking first
        if (step + idx_h) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 1):
            continue

        # Vertical wire at column hx from hy-spine_range to hy+spine_range
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            # Must be adjacent to existing wire/plant to extend
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap: if no wire in column yet, start from plant neighbors
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy from hx-spine_range to hx+spine_range
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        # Connect to horizontal neighbor
        for (hx2, hy2) in [(hx1 + 15, hy1), (hx1 + 25, hy1)]:
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        # Connect to vertical neighbor
        for (hx2, hy2) in [(hx1, hy1 + 15), (hx1, hy1 + 13)]:
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 3) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 1):
            continue

        # Flanking vertical spine (roads at hx-1 and hx+1)
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Flanking horizontal spine (roads at hy-1 and hy+1)
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 7 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [
            (8, 12), (30, 12), (52, 12), (74, 12), (96, 12), (115, 12),
            (8, 32), (30, 32), (52, 32), (74, 32), (96, 32), (115, 32),
            (8, 52), (30, 52), (52, 52), (74, 52), (96, 52), (115, 52),
            (8, 72), (30, 72), (52, 72), (74, 72), (96, 72), (115, 72),
            (8, 90), (30, 90), (52, 90), (74, 90), (96, 90), (115, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (18, 20), (48, 20), (78, 20), (108, 20),
            (18, 45), (48, 45), (78, 45), (108, 45),
            (18, 65), (48, 65), (78, 65), (108, 65),
            (18, 85), (48, 85), (78, 85), (108, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [
            (33, 33), (83, 33), (33, 63), (83, 63),
            (58, 15), (58, 85), (8, 50), (112, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        seaports = [(8, 90), (112, 90), (8, 8), (112, 8), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(50, 6), (70, 6), (50, 93), (70, 93), (5, 48), (113, 48)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 200 and step % 3 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two central coal plants + wire cross + initial roads."""
    actions = []
    # Two power plants near center
    actions.append((Tool.COALPOWER, 55, 50))
    actions.append((Tool.COALPOWER, 65, 50))
    # Horizontal wire connecting them
    for x in range(50, 71):
        if x not in (55, 65):
            actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(44, 57):
        if y != 50:
            actions.append((Tool.WIRE, 55, y))
            actions.append((Tool.WIRE, 65, y))
    # Roads flanking spines
    for y in range(44, 57):
        actions.append((Tool.ROAD, 53, y))
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
        actions.append((Tool.ROAD, 67, y))
    # Horizontal roads
    for x in range(50, 71):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Dense neighborhood grid: 18-tile spacing covers whole map
    all_hoods = []
    for hy in range(15, 95, 14):
        for hx in range(12, 115, 14):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 8
        if pop < 800:   return 14
        if pop < 1500:  return 22
        if pop < 3000:  return 32
        if pop < 6000:  return 48
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # Build neighbor-power mask (within 5 tiles of wire/plant)
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Build neighbor-road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT PER ACTIVE HOOD ----
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
            y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(12):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # ---- PHASE 2: WIRE BACKBONE ----
    # For each active hood: build cross spine of wires
    # Priority: connect plant to wire, then extend spine
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 10)
        spine_bot   = min(WORLD_H - 3, hy + 10)
        spine_left  = max(2, hx - 10)
        spine_right = min(WORLD_W - 3, hx + 10)

        # Vertical spine at hx
        col_wire = []
        col_plant_rows = []
        for r in range(WORLD_H):
            if ib(hx, r):
                if bool(wm[r, hx]):
                    col_wire.append(r)
                if bool(pm[r, hx]):
                    col_plant_rows.append(r)

        if col_plant_rows and not col_wire:
            py_l = col_plant_rows[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        if col_wire:
            min_wr = min(col_wire)
            max_wr = max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine at hy
        row_wire = []
        row_plant_cols = []
        for c in range(WORLD_W):
            if ib(c, hy):
                if bool(wm[hy, c]):
                    row_wire.append(c)
                if bool(pm[hy, c]):
                    row_plant_cols.append(c)

        if row_plant_cols and not row_wire:
            px_l = row_plant_cols[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wire:
            min_wc = min(row_wire)
            max_wc = max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: CONNECT ADJACENT HOODS WITH WIRE ----
    hood_idx = step % max(len(active_hoods), 1)
    hx0, hy0 = active_hoods[hood_idx]
    for (hx2, hy2) in active_hoods:
        if hx2 == hx0 and hy2 == hy0:
            continue
        # Horizontal connection on same row
        if abs(hy2 - hy0) <= 4 and hx2 > hx0:
            mid_y = (hy0 + hy2) // 2
            for cx in range(hx0 + 1, hx2):
                if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                    # Only lay if adjacent to existing wire
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx, mid_y)
        # Vertical connection on same column
        if abs(hx2 - hx0) <= 4 and hy2 > hy0:
            mid_x = (hx0 + hx2) // 2
            for cy in range(hy0 + 1, hy2):
                if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                    for ady in [-1, 1]:
                        ay = cy + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy)

    # ---- PHASE 4: BUILD ROADS FLANKING WIRE SPINES ----
    hx, hy = active_hoods[hood_idx]
    spine_range = 10

    # Vertical spine roads (±2 from hx)
    for rx in [hx - 2, hx + 2]:
        if not ib(rx, hy):
            continue
        cyc = step % 7
        for di in range(cyc, spine_range * 2 + 1, 7):
            dy = di - spine_range
            ry = hy + dy
            if not ib(rx, ry):
                continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]) and bool(nbr_power[ry, rx]):
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

    # Horizontal spine roads (±2 from hy)
    for ry2 in [hy - 2, hy + 2]:
        if not ib(hx, ry2):
            continue
        cyc = (step + 3) % 7
        for di in range(cyc, spine_range * 2 + 1, 7):
            dx = di - spine_range
            rcx = hx + dx
            if not ib(rcx, ry2):
                continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]) and bool(nbr_power[ry2, rcx]):
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        # Target: 40% RES, 30% COM, 30% IND
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ahx, ahy) in active_hoods:
            d = np.abs(cxs - ahx) + np.abs(cys - ahy)
            best_dist = np.minimum(best_dist, d)

        # Clustering bonus: reward proximity to existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride2 = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride2):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (reactive to pop) ----
    if pop > 30:
        fire_grid = [(fx, fy) for fy in range(12, 95, 16)
                     for fx in range(12, 115, 16)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(18, 90, 18)
                       for px2 in range(18, 110, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 4 == 0:
        park_ys_c, park_xs_c = np.where(em & nbr_road & nbr_power)
        if len(park_xs_c) > 0:
            idx = (step * 17 + pop) % len(park_xs_c)
            py2, px2 = int(park_ys_c[idx]), int(park_xs_c[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 400:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
            (30, 30), (90, 30), (30, 70), (90, 70),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 25), (60, 75),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        airport_locs = [
            (10, 10), (100, 10), (10, 85), (100, 85),
            (50, 5), (70, 5), (50, 92), (70, 92),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (ahx, ahy) in active_hoods:
        if not bool(nbr_power[ahy, ahx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = ahx + dx, ahy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants spread across the map with wire spines and roads."""
    actions = []
    # Four anchor plants in a 2x2 grid
    for px in [30, 75]:
        for py in [30, 70]:
            actions.append((Tool.COALPOWER, px, py))
            # Short wire spine
            for dy in range(-4, 5):
                actions.append((Tool.WIRE, px, py + dy))
            # Flanking roads
            for dy in range(-4, 5):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 55% residential, 25% commercial, 20% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 anchor points in a 3x3 grid for denser coverage
    # Columns at x=20, 60, 100; Rows at y=20, 50, 80
    all_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [20, 50, 80]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 30:    return 1
        if pop < 100:   return 2
        if pop < 250:   return 3
        if pop < 500:   return 4
        if pop < 800:   return 6
        if pop < 1200:  return 7
        return 9

    n_active = num_active()
    # Order anchors outward from center for nicer growth
    anchor_order = [
        (60, 50),  # center first
        (20, 50), (100, 50),
        (60, 20), (60, 80),
        (20, 20), (100, 20),
        (20, 80), (100, 80),
    ]
    active_anchors = anchor_order[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        # Check if there's a plant within radius 8
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Place plant at anchor or nearest empty
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) for each anchor ----
    spine_half = min(30, 10 + pop // 10)
    for (px, py) in active_anchors:
        wc = px
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            # Start wire adjacent to plant
            for dy in range(-5, 6):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            max_wr = max(wire_rows)
            min_wr = min(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            wc1 = row_anchors[i][0]
            wc2 = row_anchors[i + 1][0]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows ----
    if n_active >= 3:
        x_cols = sorted(set(px for (px, _) in active_anchors))
        for xc in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                py1 = col_anchors[i][1]
                py2 = col_anchors[i + 1][1]
                for cy in range(py1 + 1, py2):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        wc = px
        rl = px - 1
        rr = px + 1
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cycle = (step + idx * 5) % 3
        for wr in wire_rows[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at multiple offsets from anchor y-levels ----
    if pop > 20:
        for yl in y_levels:
            row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
            if len(row_anchors) < 1:
                continue
            x_min = row_anchors[0][0] - 2
            x_max = row_anchors[-1][0] + 2
            for horiz_y in [yl - 3, yl + 3, yl - 6, yl + 6]:
                if not ib(x_min, horiz_y) or not ib(x_max, horiz_y):
                    continue
                for cx in range(x_min, x_max + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting y-level rows ----
    if pop > 60 and len(y_levels) >= 2:
        for xc in [19, 21, 59, 61, 99, 101]:
            yl_list = sorted(y_levels)
            for i in range(len(yl_list) - 1):
                y1 = yl_list[i]
                y2 = yl_list[i + 1]
                for cy in range(y1 + 1, y2):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.ROAD, xc, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    # Road proximity: within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/power proximity: within 6 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) +
                 np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 150)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scale with pop) ----
    if pop > 60:
        # Fire stations spread across map
        fire_spots = [
            (10, 10), (35, 10), (65, 10), (90, 10), (115, 10),
            (10, 35), (35, 35), (65, 35), (90, 35), (115, 35),
            (10, 60), (35, 60), (65, 60), (90, 60), (115, 60),
            (10, 85), (35, 85), (65, 85), (90, 85), (115, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 25), (45, 25), (75, 25), (105, 25),
            (15, 55), (45, 55), (75, 55), (105, 55),
            (15, 75), (45, 75), (75, 75), (105, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 10), (55, 10), (100, 10),
            (10, 90), (55, 90), (100, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        # Add nuclear power plants for more power coverage
        nuke_spots = [
            (40, 5), (80, 5), (40, 95), (80, 95),
            (5, 40), (115, 40), (5, 70), (115, 70),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 94), (115, 94), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3), (3, -3), (-3, 3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- DENSE ZONE INFILL: scan road adjacency more aggressively ----
    # Try to place zones directly adjacent to roads we already have
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k3 = (step * 17) % max(len(road_xs2), 1)
        checked2 = 0
        for offset in range(min(len(road_xs2), 300)):
            k = (step_k3 + offset * 11) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (2, -2), (-2, -2)]:
                zx3, zy3 = rx3 + dx3, ry3 + dy3
                if ib(zx3, zy3) and bool(nbr_wire[zy3, zx3]) and zone_clear(zx3, zy3):
                    return (pick_tool(), zx3, zy3)
            checked2 += 1
            if checked2 > 200:
                break

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at cardinal positions with wire spines and seed roads."""
    actions = []
    # Four plants forming a diamond pattern for wide coverage
    plants = [(30, 30), (90, 30), (30, 70), (90, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-3, 4):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px, py + dy))
    # Seed central road cross
    for x in range(25, 96):
        actions.append((Tool.ROAD, x, 50))
    for y in range(25, 76):
        actions.append((Tool.ROAD, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 40% RES, 30% COM, 30% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Define plant target positions that scale with population
    # We start with 4 plants and add more as population grows
    all_plant_targets = [
        (30, 30), (90, 30), (30, 70), (90, 70),   # core 4
        (60, 15), (60, 85), (5, 50), (115, 50),    # cross extensions
        (15, 15), (105, 15), (15, 85), (105, 85),  # corners
        (45, 50), (75, 50), (60, 40), (60, 60),    # inner cluster
        (20, 50), (100, 50), (60, 50),              # more spread
    ]

    def num_plants_needed():
        if pop < 100:   return 4
        if pop < 300:   return 6
        if pop < 600:   return 8
        if pop < 1000:  return 10
        if pop < 2000:  return 12
        return min(len(all_plant_targets), 16)

    n_plants = num_plants_needed()
    active_plants = all_plant_targets[:n_plants]

    # --- PHASE 1: Ensure power plants exist ---
    for ppx, ppy in active_plants:
        if not ib(ppx, ppy):
            continue
        # Check if a plant exists nearby
        x0, x1 = max(0, ppx - 6), min(WORLD_W, ppx + 7)
        y0, y1 = max(0, ppy - 6), min(WORLD_H, ppy + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if funds > 500:
                # Find nearest empty spot
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)
                for r in range(1, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: Wire network - extend from plants and existing wires ---
    # Build a grid of wire corridors at fixed rows/cols
    # Wire rows: every 10 rows from 10..90
    # Wire cols: every 10 cols from 10..110
    wire_row_targets = list(range(10, 91, 10))
    wire_col_targets = list(range(10, 111, 10))

    # For each wire row, extend wire across the map
    # Priority: rows/cols near plants get wired first
    # Scan wire rows and extend
    for wr in wire_row_targets:
        row_has_power = bool(np.any(wm[wr, :] | pm[wr, :]))
        if not row_has_power:
            # Seed from nearest plant
            best_px, best_dist = -1, 999
            for ppx, ppy in active_plants:
                d = abs(ppy - wr)
                if d < best_dist:
                    best_dist = d
                    best_px = ppx
            # Check if plant is close enough and place connecting wire
            if best_dist <= 15 and ib(best_px, wr) and bool(em[wr, best_px]):
                return (Tool.WIRE, best_px, wr)
            continue
        # Extend wire row leftward and rightward
        row_wp = wm[wr, :] | pm[wr, :]
        idxs = np.where(row_wp)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        # Fill gaps first
        for x in range(left, right + 1):
            if ib(x, wr) and bool(em[wr, x]) and not bool(pm[wr, x]):
                return (Tool.WIRE, x, wr)
        # Extend left
        if left > 3:
            nx = left - 1
            if ib(nx, wr) and bool(em[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 4:
            nx = right + 1
            if ib(nx, wr) and bool(em[wr, nx]):
                return (Tool.WIRE, nx, wr)

    # Extend vertical wire cols
    for wc in wire_col_targets:
        col_has_power = bool(np.any(wm[:, wc] | pm[:, wc]))
        if not col_has_power:
            best_py, best_dist = -1, 999
            for ppx, ppy in active_plants:
                d = abs(ppx - wc)
                if d < best_dist:
                    best_dist = d
                    best_py = ppy
            if best_dist <= 15 and ib(wc, best_py) and bool(em[best_py, wc]):
                return (Tool.WIRE, wc, best_py)
            continue
        col_wp = wm[:, wc] | pm[:, wc]
        idxs = np.where(col_wp)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        for y in range(top, bot + 1):
            if ib(wc, y) and bool(em[y, wc]) and not bool(pm[y, wc]):
                return (Tool.WIRE, wc, y)
        if top > 3:
            ny = top - 1
            if ib(wc, ny) and bool(em[ny, wc]):
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 4:
            ny = bot + 1
            if ib(wc, ny) and bool(em[ny, wc]):
                return (Tool.WIRE, wc, ny)

    # --- PHASE 3: Road network ---
    # Road rows offset +4/-4 from wire rows, road cols offset +4/-4 from wire cols
    road_row_targets = []
    for wr in wire_row_targets:
        for off in [-4, 4]:
            r = wr + off
            if 3 <= r <= WORLD_H - 4:
                road_row_targets.append(r)
    road_col_targets = []
    for wc in wire_col_targets:
        for off in [-4, 4]:
            c = wc + off
            if 3 <= c <= WORLD_W - 4:
                road_col_targets.append(c)
    road_row_targets = sorted(set(road_row_targets))
    road_col_targets = sorted(set(road_col_targets))

    # Build horizontal roads
    for rr in road_row_targets:
        row_road = rm[rr, :]
        if not row_road.any():
            # Seed near a wire row
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            # Seed near any wire
            for x in range(5, WORLD_W - 5):
                if ib(x, rr) and bool(em[rr, x]) and not bool(pm[rr, x]):
                    # Check near wire
                    wr_near = any(abs(rr - wr) <= 5 and bool(np.any(wm[wr, max(0,x-3):min(WORLD_W,x+4)]))
                                  for wr in wire_row_targets)
                    if wr_near:
                        return (Tool.ROAD, x, rr)
            continue
        idxs = np.where(row_road)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        # Fill gaps
        for x in range(left, right + 1):
            if ib(x, rr) and bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)
        # Extend
        if left > 4 and ib(left - 1, rr) and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and ib(right + 1, rr) and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    # Build vertical roads
    for rc in road_col_targets:
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        idxs = np.where(col_road)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        for y in range(top, bot + 1):
            if ib(rc, y) and bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)
        if top > 4 and ib(rc, top - 1) and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and ib(rc, bot + 1) and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- PHASE 4: Zone placement ---
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone cells: empty, near road, near wire, not on edge
    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H - 3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: proximity to existing zones (clustering) + spread to corners for big pop
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 300)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                score = zone_dist
            else:
                score = (np.abs(cxs_arr - 60).astype(float) +
                         np.abs(cys_arr - 50).astype(float))
        else:
            # Initially cluster near center
            score = (np.abs(cxs_arr - 60).astype(float) +
                     np.abs(cys_arr - 50).astype(float))

        # As population grows, spread toward corners
        if pop > 300:
            corners = [(15, 15), (105, 15), (15, 85), (105, 85),
                       (60, 10), (60, 90), (10, 50), (110, 50),
                       (30, 30), (90, 30), (30, 70), (90, 70)]
            min_corner = np.full(len(cxs_arr), 999999.0)
            for cx, cy in corners:
                d = (np.abs(cxs_arr - cx).astype(float) +
                     np.abs(cys_arr - cy).astype(float))
                min_corner = np.minimum(min_corner, d)
            spread_w = min(0.8, (pop - 300) / 2000.0)
            score = score * (1 - spread_w) + min_corner * spread_w

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services ---
    if pop > 50:
        # Fire stations: dense grid
        fire_grid = [(fx, fy) for fy in range(8, 93, 12)
                     for fx in range(8, 113, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_grid = [(px2, py2) for py2 in range(12, 90, 16)
                       for px2 in range(12, 110, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(10, 92, 8)
                      for pkx in range(10, 112, 8)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 500:
        stadium_spots = [
            (30, 20), (90, 20), (30, 80), (90, 80),
            (60, 20), (60, 80), (15, 50), (105, 50),
            (45, 40), (75, 40), (45, 60), (75, 60),
            (20, 35), (100, 35), (20, 65), (100, 65),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800 and funds > 5000:
        nuclear_spots = [(20, 50), (100, 50), (60, 20), (60, 80),
                         (20, 25), (100, 25), (20, 75), (100, 75),
                         (40, 10), (80, 10), (40, 90), (80, 90)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy):
                x0, x1 = max(0, npx-5), min(WORLD_W, npx+6)
                y0, y1 = max(0, npy-5), min(WORLD_H, npy+6)
                if not np.any(pm[y0:y1, x0:x1]):
                    if bool(em[npy, npx]):
                        return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 700:
        airport_spots = [
            (55, 5), (65, 5), (55, 94), (65, 94),
            (5, 44), (114, 44), (5, 54), (114, 54),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1200:
        seaport_spots = [
            (5, 50), (114, 50), (60, 3), (60, 96),
            (20, 3), (100, 3), (20, 96), (100, 96),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- FALLBACK: extend wires from existing wire/plant ---
    pys_arr, pxs_arr = np.where(pm)
    if len(pxs_arr) > 0:
        sk = (step * 11) % len(pxs_arr)
        for offset in range(min(len(pxs_arr), 40)):
            k = (sk + offset * 7) % len(pxs_arr)
            px2, py2 = int(pxs_arr[k]), int(pys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: place road near any wire
    if len(wxs_arr) > 0:
        sk3 = (step * 17) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk3 + offset * 3) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                              (4, 0), (-4, 0), (0, 4), (0, -4)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

