    # Vertical wire spines
    for y in range(22, 80, 2):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 100, y))
    # Cross wires to center
    for x in range(22, 60, 2):
        actions.append((Tool.WIRE, x, 50))
    for x in range(62, 100, 2):
        actions.append((Tool.WIRE, x, 50))
    # Initial road grid
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 15))
        actions.append((Tool.ROAD, x, 25))
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
        actions.append((Tool.ROAD, x, 75))
        actions.append((Tool.ROAD, x, 85))
    for y in range(5, 95):
        actions.append((Tool.ROAD, 15, y))
        actions.append((Tool.ROAD, 35, y))
        actions.append((Tool.ROAD, 55, y))
        actions.append((Tool.ROAD, 75, y))
        actions.append((Tool.ROAD, 95, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    powered_zones = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: 50% res, 25% com, 25% ind
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Check if zone 3x3 area is safe to place
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                # Roads are ok around zones; plants block
                if bool(pm[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: Ensure dense power plant coverage ----
    # Target one plant per ~15x15 block
    plant_grid = []
    for py in range(10, 95, 15):
        for px in range(10, 115, 15):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant on empty tile, avoid existing zones
            if bool(em[py, px]) and not bool(zone_tiles[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire to connect unpowered regions ----
    # Extend wires from existing power sources toward unpowered areas
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)

    if len(wxs) > 0:
        # Find plant grid positions not yet near power
        uncovered_plants = [(px, py) for px, py in plant_grid
                            if ib(px, py) and not bool(near_power[py, px])]
        if uncovered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in uncovered_plants)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire to unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 200)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(len(zxs), 50)))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid — dense grid every 6 tiles ----
    road_grid_targets = []
    for gy in range(6, 97, 6):
        for gx in range(6, 117, 6):
            road_grid_targets.append((gx, gy))

    # Find road grid points that are powered but lack roads
    uncovered_road = [(gx, gy) for gx, gy in road_grid_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        # Check if existing roads are adjacent so we can connect
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:3, :] = False
        road_cand[WORLD_H-3:, :] = False
        road_cand[:, 0:3] = False
        road_cand[:, WORLD_W-3:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:30]
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Place road directly at uncovered target
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Dense zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False
    # Don't place on roads/wires/plants
    zone_cand &= ~rm & ~wm & ~pm

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Compute scores: prefer distance from existing zones (spread), but close to roads
        road_ys, road_xs = np.where(rm)
        if total_zones > 0:
            zone_ys_w, zone_xs_w = np.where(zone_tiles)
            stride_z = max(1, len(zone_xs_w) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs_w), stride_z):
                d = (np.abs(cxs_arr - zone_xs_w[i]) + np.abs(cys_arr - zone_ys_w[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)

            if len(road_xs) > 0:
                stride_r = max(1, len(road_xs) // 80)
                road_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(road_xs), stride_r):
                    d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                    road_dist = np.minimum(road_dist, d)
                # Score: want near roads (low road_dist), some spread from zones
                score = zone_dist * (-0.3) + road_dist * 1.5
            else:
                score = -zone_dist
        else:
            # Start near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        # Use step/pop offset to vary placement and spread across map
        off = (step * 17 + pop * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 200:
        # Fire stations in a grid
        fire_grid = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 115, 10)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 500:
        police_grid = [(px2, py2) for py2 in range(12, 92, 12) for px2 in range(12, 112, 12)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 800:
        park_grid = [(px3, py3) for py3 in range(8, 95, 8) for px3 in range(8, 115, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 1500:
        stadium_locs = [(30, 30), (90, 30), (30, 70), (90, 70),
                        (60, 20), (60, 80), (20, 50), (100, 50),
                        (45, 45), (75, 55), (15, 15), (105, 85)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 2000:
        # Add nuclear plants for more power
        nuke_locs = [(60, 10), (10, 50), (110, 50), (60, 90),
                     (35, 35), (85, 35), (35, 65), (85, 65)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3000:
        airport_locs = [(55, 5), (80, 5), (55, 94), (80, 94),
                        (5, 35), (114, 35), (5, 65), (114, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 5000:
        seaport_locs = [(8, 50), (112, 50), (60, 5), (60, 94),
                        (20, 10), (100, 10), (20, 90), (100, 90)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: try to extend road from existing road or plant ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (4, 3), (-4, 3), (3, -4), (-3, -4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: wire extension ----
    if len(pwr_xs) > 0:
        k = (step * 3) % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    # ---- Last resort: scan for empty powered+roaded spot ----
    zone_cand2 = em & near_road & near_power & ~rm & ~wm & ~pm
    ys2, xs2 = np.where(zone_cand2)
    if len(xs2) > 0:
        k = (step * 31) % len(xs2)
        return (pick_tool(), int(xs2[k]), int(ys2[k]))

    return None

def init(obs, state):
    """Bootstrap: place a central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-5, 6):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-4, 5):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # --- Neighborhood grid: 10 cols x 8 rows = 80 neighborhoods ---
    # Each hood is a "mini-city" with its own plant, wires, roads, zones
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [8, 20, 32, 44, 56, 68, 80, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 30:    return 4
        if pop < 100:   return 8
        if pop < 300:   return 15
        if pop < 600:   return 22
        if pop < 1000:  return 30
        if pop < 2000:  return 40
        if pop < 4000:  return 55
        if pop < 8000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        # Spread hoods evenly, starting from center
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]
    active_set = set(active_hoods)

    spine_r = 8  # wire/road spine half-length

    # ---- PHASE 1: POWER PLANTS ----
    # Each active hood should have a power plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant at hood center or nearest empty
            for r in range(10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE SPINES ----
    # Grow wire cross from each active hood's plant outward
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Only process a subset of hoods per step for performance
        if step % 4 != idx_h % 4:
            continue

        # Vertical spine at hx
        for dy in range(-spine_r, spine_r + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            # Check adjacency to power
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal spine at hy
        for dx in range(-spine_r, spine_r + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT HOODS WITH WIRES ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Connect horizontally adjacent hoods on same row
            if hy1 == hy2 and 0 < hx2 - hx1 <= 16:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1):
                        continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]):
                        continue
                    if not bool(em[hy1, cx2]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Connect vertically adjacent hoods on same col
            if hx1 == hx2 and 0 < hy2 - hy1 <= 16:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2):
                        continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]):
                        continue
                    if not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % 3 != idx_h % 3:
            continue

        # Roads at hx-1 and hx+1 (flanking vertical wire spine)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy):
                continue
            for dy in range(-spine_r, spine_r + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]):
                    continue
                # Only place if wire is present on spine
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

        # Roads at hy-1 and hy+1 (flanking horizontal wire spine)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2):
                continue
            for dx in range(-spine_r, spine_r + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]):
                    continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks for roads and power (vectorized)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates by proximity to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Also weight by proximity to existing zones (encourage clustering)
        if total_zones > 0:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs), 9999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d = np.abs(cxs - zxs2[i]) + np.abs(cys - zys2[i])
                    zone_dist = np.minimum(zone_dist, d)
                score = best_dist * 0.5 + zone_dist * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (16, 16), (40, 16), (64, 16), (88, 16), (112, 16),
            (16, 32), (40, 32), (64, 32), (88, 32), (112, 32),
            (16, 48), (40, 48), (64, 48), (88, 48), (112, 48),
            (16, 64), (40, 64), (64, 64), (88, 64), (112, 64),
            (16, 80), (40, 80), (64, 80), (88, 80), (112, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (28, 24), (56, 24), (84, 24), (112, 24),
            (14, 44), (42, 44), (70, 44), (98, 44),
            (28, 60), (56, 60), (84, 60), (112, 60),
            (14, 76), (42, 76), (70, 76), (98, 76),
            (28, 90), (56, 90), (84, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (70, 30), (110, 30),
            (10, 55), (50, 55), (90, 55),
            (30, 75), (70, 75), (110, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(6, 88), (114, 88), (6, 10), (114, 10), (60, 6), (60, 94)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 8: PARKS to boost land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wires toward unserved hoods ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        # Find hoods without power
        unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
        if unpowered_hoods:
            # Pick the closest wire tile to the nearest unpowered hood
            best_wire_k = 0
            best_dist2 = 1e9
            step_k2 = (step * 13) % len(wire_xs_arr)
            for offset in range(min(len(wire_xs_arr), 100)):
                k = (step_k2 + offset * 5) % len(wire_xs_arr)
                wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
                for (uhx, uhy) in unpowered_hoods:
                    d = abs(wx2 - uhx) + abs(wy2 - uhy)
                    if d < best_dist2:
                        best_dist2 = d
                        best_wire_k = k
            wx2, wy2 = int(wire_xs_arr[best_wire_k]), int(wire_ys_arr[best_wire_k])
            # Extend toward nearest unpowered hood
            best_target = min(unpowered_hoods, key=lambda h: abs(wx2 - h[0]) + abs(wy2 - h[1]))
            dx3 = best_target[0] - wx2
            dy3 = best_target[1] - wy2
            if abs(dx3) >= abs(dy3):
                step_x = 1 if dx3 > 0 else -1
                nx3, ny3 = wx2 + step_x, wy2
            else:
                step_y = 1 if dy3 > 0 else -1
                nx3, ny3 = wx2, wy2 + step_y
            if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)
        else:
            # Just extend wire outward from any existing wire
            step_k2 = (step * 13) % len(wire_xs_arr)
            for offset in range(min(len(wire_xs_arr), 80)):
                k = (step_k2 + offset * 5) % len(wire_xs_arr)
                wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new plant near uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Ambitious closed-loop city builder v2
# Strategy: Dense grid of coal plants, comprehensive wire+road mesh,
# aggressive balanced R/C/I zoning across entire map with civic services

def init(obs, state):
    """Bootstrap: central power cluster + initial road/wire cross"""
    actions = []
    # 4 coal plants near center
    plants = [(55, 45), (65, 45), (55, 55), (65, 55)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire connecting them horizontally and vertically
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Initial roads grid near center
    for x in range(50, 71):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 70, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- PLANNED INFRASTRUCTURE GRID ----
    # Wire corridors every 10 tiles on both axes
    # Road corridors parallel, offset by 1
    WIRE_COLS = list(range(10, WORLD_W, 10))   # 10,20,...,110
    WIRE_ROWS = list(range(10, WORLD_H, 10))   # 10,20,...,90

    # Power plant positions: every 20 tiles on wire crossings
    PLANT_POS = []
    for px in range(10, WORLD_W, 20):
        for py in range(10, WORLD_H, 20):
            PLANT_POS.append((px, py))

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Check each planned plant position
    for (px, py) in PLANT_POS:
        # Check if a plant exists nearby (5 tile radius)
        x0, x1 = max(0, px-5), min(WORLD_W, px+6)
        y0, y1 = max(0, py-5), min(WORLD_H, py+6)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Try nearby empty cells
            for r in range(1, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px+dx, py+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: BUILD WIRE GRID ----
    # Fill wire corridors connecting all plants
    # Horizontal wire rows
    if step % 6 == 0:
        for wr in WIRE_ROWS:
            for wx in range(1, WORLD_W-1):
                if ib(wx, wr) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                    # Check adjacency to wire or plant
                    for adx in [-1, 1]:
                        ax = wx + adx
                        if ib(ax, wr) and (bool(wm[wr, ax]) or bool(pm[wr, ax])):
                            return (Tool.WIRE, wx, wr)

    # Vertical wire columns
    if step % 6 == 1:
        for wc in WIRE_COLS:
            for wy in range(1, WORLD_H-1):
                if ib(wc, wy) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                    for ady in [-1, 1]:
                        ay = wy + ady
                        if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                            return (Tool.WIRE, wc, wy)

    # Bridge gaps between disconnected wire segments
    if step % 6 == 2:
        # Look for wire endpoints that need bridging
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            k = (step * 7) % len(wire_xs)
            for i in range(min(len(wire_xs), 50)):
                idx = (k + i) % len(wire_xs)
                wx, wy = int(wire_xs[idx]), int(wire_ys[idx])
                for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx, ny = wx+dx, wy+dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        # Check if this would bridge toward another wire
                        nx2, ny2 = nx+dx, ny+dy
                        if ib(nx2, ny2) and (bool(wm[ny2, nx2]) or bool(pm[ny2, nx2])):
                            return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: ROAD NETWORK ----
    # Roads at wire_row ± 1 and wire_col ± 1
    # Also cross-streets every 5 tiles between corridors

    if step % 6 == 3:
        # Horizontal roads parallel to wire rows
        for wr in WIRE_ROWS:
            for offset in [-1, 1]:
                ry = wr + offset
                if not ib(0, ry):
                    continue
                for rx in range(1, WORLD_W-1):
                    if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    if step % 6 == 4:
        # Vertical roads parallel to wire cols
        for wc in WIRE_COLS:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not ib(rcx, 0):
                    continue
                for ry in range(1, WORLD_H-1):
                    if ib(rcx, ry) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    if step % 6 == 5:
        # Cross streets: extend roads that have road neighbors
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            k = (step * 11) % len(road_xs)
            for i in range(min(len(road_xs), 80)):
                idx = (k + i*3) % len(road_xs)
                rx, ry = int(road_xs[idx]), int(road_ys[idx])
                for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx, ny = rx+dx, ry+dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        # Only extend if there's power nearby
                        pw_near = False
                        for pdy in range(-3, 4):
                            for pdx in range(-3, 4):
                                ax, ay = nx+pdx, ny+pdy
                                if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                                    pw_near = True
                                    break
                            if pw_near:
                                break
                        if pw_near:
                            return (Tool.ROAD, nx, ny)

    # ---- PHASE 4: ZONE PLACEMENT ----
    # Target ratio: 40% RES, 30% COM, 30% IND
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy+dr, zx+dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Zone candidate mask
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance from center to fill outward
        cx_center, cy_center = WORLD_W//2, WORLD_H//2
        dist_center = np.abs(cxs - cx_center) + np.abs(cys - cy_center)
        # Prefer closer to center first, with some variation
        order = np.argsort(dist_center)
        offset = (step * 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        # Fire stations at grid intersections
        fire_positions = []
        for fx in range(20, WORLD_W, 20):
            for fy in range(20, WORLD_H, 20):
                fire_positions.append((fx, fy))
        for (sx, sy) in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_positions = []
        for px2 in range(30, WORLD_W, 30):
            for py2 in range(30, WORLD_H, 30):
                police_positions.append((px2, py2))
        for (sx, sy) in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(30,30),(90,30),(30,70),(90,70),(60,50),(60,20),(60,80)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(10,85),(110,85),(10,15),(110,15),(60,90),(60,10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50,5),(70,5),(50,94),(70,94),(5,45),(114,45)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near roads for land value
    if pop > 100 and step % 7 == 0:
        park_mask = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_mask)
        if len(park_xs) > 0:
            idx = (step * 31) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        k = (step * 17) % len(wire_xs_arr)
        for i in range(min(len(wire_xs_arr), 60)):
            idx = (k + i*3) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[idx]), int(wire_ys_arr[idx])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- FALLBACK: new coal plant for uncovered area ----
    for (px, py) in PLANT_POS:
        if not bool(nbr_power[py, px]):
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 6):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px+dx, py+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
