        actions.append((Tool.ROAD, 60 + dx, 28))
        actions.append((Tool.ROAD, 60 + dx, 32))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.18:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # More neighborhoods spread across the map
    # 6 columns x 5 rows = 30 anchor points
    anchor_xs = [12, 30, 50, 70, 90, 108]
    anchor_ys = [12, 28, 46, 64, 82]

    all_anchors = []
    for ax in anchor_xs:
        for ay in anchor_ys:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 20:    return 3
        if pop < 80:    return 6
        if pop < 200:   return 10
        if pop < 400:   return 15
        if pop < 700:   return 20
        if pop < 1200:  return 25
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ENSURE POWER PLANTS near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 10); y1 = min(WORLD_H, ay + 11)
        x0 = max(0, ax - 10); x1 = min(WORLD_W, ax + 11)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- BUILD WIRE SPINES: horizontal + vertical cross per anchor ----
    # Grow wire outward reactively from existing wire or plant
    wire_half_h = min(20, 6 + pop // 10)
    wire_half_v = min(14, 5 + pop // 15)

    # Horizontal wire growth
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half_h)
        spine_right = min(WORLD_W - 3, ax + wire_half_h)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            # Check if plant nearby: place wire adjacent to plant or at anchor
            plant_in_row = [c for c in range(spine_left, spine_right + 1)
                            if ib(c, ay) and bool(pm[ay, c])]
            start_c = plant_in_row[0] if plant_in_row else ax
            for dx in range(-4, 5):
                nx = start_c + dx
                if ib(nx, ay) and bool(em[ay, nx]) and not bool(pm[ay, nx]):
                    return (Tool.WIRE, nx, ay)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, ay) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, ay) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)

    # Vertical wire growth
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - wire_half_v)
        spine_bot = min(WORLD_H - 3, ay + wire_half_v)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            plant_in_col = [r for r in range(spine_top, spine_bot + 1)
                            if ib(ax, r) and bool(pm[r, ax])]
            start_r = plant_in_col[0] if plant_in_col else ay
            for dy in range(-4, 5):
                ny = start_r + dy
                if ib(ax, ny) and bool(em[ny, ax]) and not bool(pm[ny, ax]):
                    return (Tool.WIRE, ax, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(ax, nr) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(ax, nr) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)

    # ---- CONNECT ANCHORS WITH WIRE (vertical links in same column) ----
    if n_active >= 3:
        xs_set = sorted(set(ax for (ax, ay) in active_anchors))
        for col_x in xs_set:
            col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1 = col_anchors[i]
                _, y2 = col_anchors[i + 1]
                for cy in range(y1 + 1, y2):
                    if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                        return (Tool.WIRE, col_x, cy)

    # ---- CONNECT ANCHORS WITH WIRE (horizontal links in same row) ----
    if n_active >= 2:
        ys_set = sorted(set(ay for (ax, ay) in active_anchors))
        for row_y in ys_set:
            row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
            for i in range(len(row_anchors) - 1):
                x1, _ = row_anchors[i]
                x2, _ = row_anchors[i + 1]
                for cx in range(x1 + 1, x2):
                    if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING: roads parallel to wire spines ----
    # Roads at wire_y ± 2 (above/below horizontal wire)
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_left = max(2, ax - wire_half_h)
        spine_right = min(WORLD_W - 3, ax + wire_half_h)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            continue
        cycle = (step + idx * 7) % 4
        for wc in wire_in_row[cycle::4]:
            for road_y in [ay - 2, ay + 2]:
                if ib(wc, road_y) and bool(em[road_y, wc]) and not bool(pm[road_y, wc]):
                    return (Tool.ROAD, wc, road_y)

    # Roads at wire_x ± 2 (left/right of vertical wire)
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_top = max(2, ay - wire_half_v)
        spine_bot = min(WORLD_H - 3, ay + wire_half_v)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 5) % 4
        for wr in wire_in_col[cycle::4]:
            for road_x in [ax - 2, ax + 2]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- HORIZONTAL CROSS ROADS connecting row of anchors ----
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        if len(row_anchors) >= 2:
            for horiz_y_off in [-3, 3]:
                horiz_y = row_y + horiz_y_off
                x_start = max(2, row_anchors[0][0] - 5)
                x_end = min(WORLD_W - 2, row_anchors[-1][0] + 5)
                for cx in range(x_start, x_end + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL CROSS ROADS connecting column of anchors ----
    if pop > 20:
        xs_set = sorted(set(ax for (ax, ay) in active_anchors))
        for col_x in xs_set:
            col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
            if len(col_anchors) >= 2:
                for vert_x_off in [-3, 3]:
                    vert_x = col_x + vert_x_off
                    y_start = max(2, col_anchors[0][1] - 5)
                    y_end = min(WORLD_H - 2, col_anchors[-1][1] + 5)
                    for cy in range(y_start, y_end + 1):
                        if ib(vert_x, cy) and bool(em[cy, vert_x]) and not bool(pm[cy, vert_x]):
                            return (Tool.ROAD, vert_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- ZONE PLACEMENT: place zones near roads + wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = np.sqrt((cxs.astype(float) - ax)**2 + (cys.astype(float) - ay)**2)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES: fire stations ----
    if pop > 30:
        fire_grid_xs = [8, 25, 42, 60, 78, 95, 112]
        fire_grid_ys = [8, 25, 42, 60, 78, 93]
        for fy in fire_grid_ys:
            for fx in fire_grid_xs:
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    # ---- POLICE STATIONS ----
    if pop > 150:
        police_grid_xs = [15, 35, 55, 75, 95, 110]
        police_grid_ys = [15, 35, 55, 75, 90]
        for py2 in police_grid_ys:
            for px2 in police_grid_xs:
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    # ---- STADIUMS ----
    if pop > 500:
        for (sx, sy) in [(20, 6), (60, 6), (100, 6), (20, 93), (60, 93), (100, 93), (6, 50), (114, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- NUCLEAR POWER for high pop ----
    if pop > 600:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94),
                      (60, 5), (60, 94), (5, 50), (115, 50),
                      (30, 5), (90, 5), (30, 94), (90, 94)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- AIRPORTS ----
    if pop > 1500:
        for (ax2, ay2) in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    # ---- SEAPORTS ----
    if pop > 2500:
        for (sx2, sy2) in [(5, 94), (115, 94), (60, 97), (5, 5), (115, 5)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (0, 3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road extension ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire and road seeds."""
    actions = []
    # Three starter plants at mid-height
    starts = [(20, 50), (60, 50), (100, 50)]
    for px, py in starts:
        actions.append((Tool.COALPOWER, px, py))
        # Wire column adjacent to plant
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px + 2, py + dy))
        # Roads flanking wire
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px + 1, py + dy))
            actions.append((Tool.ROAD, px + 3, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9-cluster grid: 3 rows x 3 cols spread across map
    # Each: (plant_x, plant_y, wire_col, road_left, road_right)
    ALL_CLUSTERS = [
        (20,  25, 22, 21, 23),
        (60,  25, 62, 61, 63),
        (100, 25, 102, 101, 103),
        (20,  50, 22, 21, 23),
        (60,  50, 62, 61, 63),
        (100, 50, 102, 101, 103),
        (20,  75, 22, 21, 23),
        (60,  75, 62, 61, 63),
        (100, 75, 102, 101, 103),
    ]

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 2
        if pop < 500:   return 3
        if pop < 900:   return 4
        if pop < 1500:  return 5
        if pop < 2500:  return 6
        if pop < 4000:  return 7
        if pop < 6000:  return 8
        return 9

    n_active = num_active()
    active_clusters = ALL_CLUSTERS[:n_active]

    # -------------------------------------------------------
    # 1. ENSURE POWER PLANTS for each active cluster
    # -------------------------------------------------------
    for (px, py, wc, rl, rr) in active_clusters:
        y0, y1 = max(0, py-5), min(WORLD_H, py+6)
        x0, x1 = max(0, px-5), min(WORLD_W, px+6)
        if not np.any(pm[y0:y1, x0:x1]):
            # Try exact spot first
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Spiral search
            for r in range(1, 15):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # -------------------------------------------------------
    # 2. WIRE SPINE (vertical) per active cluster
    # -------------------------------------------------------
    spine_half = min(35, 12 + pop // 8)
    for (px, py, wc, rl, rr) in active_clusters:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H-3, py + spine_half)
        wires_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wires_in_col:
            # Seed wire near plant
            for dy2 in range(-5, 6):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            mn = min(wires_in_col)
            mx = max(wires_in_col)
            if mx < spine_bot:
                nr = mx + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if mn > spine_top:
                nr = mn - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # -------------------------------------------------------
    # 3. HORIZONTAL WIRE connecting clusters in same row
    # -------------------------------------------------------
    row_ys = sorted(set(py for (px, py, wc, rl, rr) in active_clusters))
    for yl in row_ys:
        row_wcs = sorted([wc for (px, py, wc, rl, rr) in active_clusters if py == yl])
        for i in range(len(row_wcs)-1):
            wc1, wc2 = row_wcs[i], row_wcs[i+1]
            for cx in range(wc1+1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # -------------------------------------------------------
    # 4. VERTICAL WIRE connecting same-column clusters
    # -------------------------------------------------------
    if n_active >= 4:
        col_xs = sorted(set(wc for (px, py, wc, rl, rr) in active_clusters))
        for xc in col_xs:
            col_pys = sorted([py for (px, py, wc, rl, rr) in active_clusters if wc == xc])
            for i in range(len(col_pys)-1):
                y1c, y2c = col_pys[i], col_pys[i+1]
                for cy in range(y1c+1, y2c):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # -------------------------------------------------------
    # 5. ROADS flanking wire spines (reactive: read wire positions)
    # -------------------------------------------------------
    for idx, (px, py, wc, rl, rr) in enumerate(active_clusters):
        wires_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wires_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wires_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # -------------------------------------------------------
    # 6. HORIZONTAL ROADS connecting row clusters
    # -------------------------------------------------------
    for yl in row_ys:
        row_data = sorted([(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_clusters if py == yl],
                          key=lambda a: a[0])
        if len(row_data) < 2:
            continue
        x_left = row_data[0][3]
        x_right = row_data[-1][4]
        # Multiple horizontal road layers for dense coverage
        offsets = [-4, 4]
        if pop > 200:
            offsets += [-8, 8]
        if pop > 600:
            offsets += [-12, 12, -16, 16]
        for horiz_y in offsets:
            hy = yl + horiz_y
            if not ib(x_left, hy) or not ib(x_right, hy):
                continue
            for cx in range(x_left, x_right+1):
                if ib(cx, hy) and bool(em[hy, cx]) and not bool(pm[hy, cx]):
                    return (Tool.ROAD, cx, hy)

    # -------------------------------------------------------
    # 7. BUILD NEIGHBOR MASKS for zone placement
    # -------------------------------------------------------
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0=max(0,-dy); sr1=min(WORLD_H,WORLD_H-dy)
            sc0=max(0,-dx); sc1=min(WORLD_W,WORLD_W-dx)
            r0=max(0,dy);   r1=min(WORLD_H,WORLD_H+dy)
            c0=max(0,dx);   c1=min(WORLD_W,WORLD_W+dx)
            nbr_road[r0:r1,c0:c1] |= rm[sr0:sr1,sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0=max(0,-dy); sr1=min(WORLD_H,WORLD_H-dy)
            sc0=max(0,-dx); sc1=min(WORLD_W,WORLD_W-dx)
            r0=max(0,dy);   r1=min(WORLD_H,WORLD_H+dy)
            c0=max(0,dx);   c1=min(WORLD_W,WORLD_W+dx)
            nbr_wire[r0:r1,c0:c1] |= wm[sr0:sr1,sc0:sc1]
            nbr_wire[r0:r1,c0:c1] |= pm[sr0:sr1,sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # -------------------------------------------------------
    # 8. ZONE PLACEMENT (reactive: find best candidate near power+road)
    # -------------------------------------------------------
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :]  = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2]  = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_clusters:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # -------------------------------------------------------
    # 9. EXTEND ROADS from existing roads near wire
    # -------------------------------------------------------
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(nbr_wire[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # -------------------------------------------------------
    # 10. CIVIC SERVICES (reactive on population)
    # -------------------------------------------------------
    if pop > 50:
        fire_spots = [
            (8,20),(30,20),(50,20),(70,20),(90,20),(112,20),
            (8,40),(30,40),(50,40),(70,40),(90,40),(112,40),
            (8,60),(30,60),(50,60),(70,60),(90,60),(112,60),
            (8,80),(30,80),(50,80),(70,80),(90,80),(112,80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (15,15),(45,15),(75,15),(105,15),
            (15,45),(45,45),(75,45),(105,45),
            (15,70),(45,70),(75,70),(105,70),
            (15,90),(45,90),(75,90),(105,90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (35,10),(75,10),(110,10),
            (35,90),(75,90),(110,90),
            (5,50),(115,50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear upgrade when rich
    if pop > 1500:
        nuke_spots = [
            (40,5),(80,5),(5,50),(115,50),
            (40,95),(80,95),(5,15),(115,15),
            (5,85),(115,85),(60,5),(60,95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2,ny2) and bool(em[ny2,nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55,5),(5,50),(115,50),(55,94)]:
            ax, ay = asp
            if ib(ax,ay) and bool(em[ay,ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5,93),(115,93),(60,97)]:
            sx2, sy2 = sp
            if ib(sx2,sy2) and bool(em[sy2,sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # -------------------------------------------------------
    # 11. PARKS near existing zones to boost land value
    # -------------------------------------------------------
    if pop > 200:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step*3 + i*17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2),(3,3),(-3,3),(3,-3),(-3,-3)]:
                    nx2, ny2 = zx2+dx2, zy2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]):
                        return (Tool.PARK, nx2, ny2)

    # -------------------------------------------------------
    # 12. EXTEND WIRE fallback
    # -------------------------------------------------------
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step*13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset*5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # -------------------------------------------------------
    # 13. LAST RESORT: road adjacent to any zone
    # -------------------------------------------------------
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step*19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder
# Strategy: Build a dense grid of neighborhoods across the full map
# with coal plants every ~20 tiles, road grid, and reactive zone placement

def init(obs, state):
    """Bootstrap: central power plant + wire/road cross to get started quickly."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking wire
    for x in range(55, 66):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Vertical roads
    for y in range(45, 56):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- INITIALIZE STATE ----
    if 'phase' not in state:
        state['phase'] = 0
        state['plant_grid'] = []  # list of (px, py) plant positions
        state['road_cursor'] = 0
        state['wire_cursor'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% res, 30% com, 20% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- DEFINE DENSE NEIGHBORHOOD GRID ----
    # 6 columns x 7 rows = 42 neighborhoods across full map
    # Plant positions interspersed
    neighborhood_xs = [12, 30, 48, 66, 84, 102]  # 6 columns
    neighborhood_ys = [10, 24, 38, 52, 66, 80, 92]  # 7 rows

    # Power plants at every 3rd neighborhood intersection
    plant_positions = []
    for ix, nx in enumerate(neighborhood_xs):
        for iy, ny in enumerate(neighborhood_ys):
            if (ix + iy) % 3 == 0:
                plant_positions.append((nx, ny))

    # Number of active neighborhoods based on population
    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 300:   return 10
        if pop < 500:   return 15
        if pop < 800:   return 20
        if pop < 1200:  return 28
        if pop < 2000:  return 35
        return 42

    n_active = num_active()
    all_neighborhoods = [(nx, ny) for ny in neighborhood_ys for nx in neighborhood_xs]
    active_neighborhoods = all_neighborhoods[:n_active]

    # Which power plants are needed for active neighborhoods
    active_plants_needed = [p for p in plant_positions
                            if any(abs(p[0]-nx) <= 30 and abs(p[1]-ny) <= 20
                                   for nx, ny in active_neighborhoods)]

    # ---- STEP 1: ENSURE POWER PLANTS ----
    for (px, py) in active_plants_needed:
        y0, y1 = max(0, py-3), min(WORLD_H, py+4)
        x0, x1 = max(0, px-3), min(WORLD_W, px+4)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Try nearby empty spot
            for r in range(1, 6):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx2, ny2 = px+dx, py+dy
                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                            return (Tool.COALPOWER, nx2, ny2)

    # ---- STEP 2: BUILD WIRE GRID ----
    # Horizontal wires along neighborhood rows
    for (ax, ay) in active_neighborhoods:
        # Wire to connect to nearest plant horizontally
        # Check if wire exists at this neighborhood center
        has_wire_nearby = False
        for dx in range(-2, 3):
            for dy in range(-2, 3):
                nx2, ny2 = ax+dx, ay+dy
                if ib(nx2, ny2) and (bool(wm[ny2, nx2]) or bool(pm[ny2, nx2])):
                    has_wire_nearby = True
                    break
            if has_wire_nearby:
                break

        if not has_wire_nearby:
            # Place wire at center if empty
            if ib(ax, ay) and bool(em[ay, ax]) and not bool(pm[ay, ax]):
                return (Tool.WIRE, ax, ay)

    # Extend wire horizontally along each row
    for row_y in neighborhood_ys:
        row_neighborhoods = [(nx, ny) for (nx, ny) in active_neighborhoods if ny == row_y]
        if len(row_neighborhoods) < 2:
            continue
        xs = sorted([nx for (nx, ny) in row_neighborhoods])
        x_start, x_end = xs[0], xs[-1]
        # Find gaps in wire along this row
        for cx in range(x_start, x_end+1):
            if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                # Check if there's wire on either side within 3 tiles
                has_left = any(ib(cx-d, row_y) and (bool(wm[row_y, cx-d]) or bool(pm[row_y, cx-d]))
                               for d in range(1, 4))
                has_right = any(ib(cx+d, row_y) and (bool(wm[row_y, cx+d]) or bool(pm[row_y, cx+d]))
                                for d in range(1, 4))
                if has_left or has_right:
                    return (Tool.WIRE, cx, row_y)

    # Extend wire vertically along each column
    for col_x in neighborhood_xs:
        col_neighborhoods = [(nx, ny) for (nx, ny) in active_neighborhoods if nx == col_x]
        if len(col_neighborhoods) < 2:
            continue
        ys = sorted([ny for (nx, ny) in col_neighborhoods])
        y_start, y_end = ys[0], ys[-1]
        for cy in range(y_start, y_end+1):
            if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                has_top = any(ib(col_x, cy-d) and (bool(wm[cy-d, col_x]) or bool(pm[cy-d, col_x]))
                              for d in range(1, 4))
                has_bot = any(ib(col_x, cy+d) and (bool(wm[cy+d, col_x]) or bool(pm[cy+d, col_x]))
                              for d in range(1, 4))
                if has_top or has_bot:
                    return (Tool.WIRE, col_x, cy)

    # ---- STEP 3: BUILD ROAD GRID ----
    # Road rows: offset by 2 from wire rows
    road_row_offsets = [-2, 2]
    road_col_offsets = [-2, 2]

    # Horizontal roads parallel to wire rows
    for row_y in neighborhood_ys:
        row_neighborhoods = [(nx, ny) for (nx, ny) in active_neighborhoods if ny == row_y]
        if not row_neighborhoods:
            continue
        xs = sorted([nx for (nx, ny) in row_neighborhoods])
        x_start, x_end = xs[0], xs[-1]
        for ry_off in road_row_offsets:
            road_y = row_y + ry_off
            if not ib(0, road_y):
                continue
            for cx in range(max(2, x_start-2), min(WORLD_W-2, x_end+3)):
                if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    # Only place if near wire or existing road
                    near_wire = any(ib(cx+dx, road_y+dy) and (bool(wm[road_y+dy, cx+dx]) or bool(pm[road_y+dy, cx+dx]))
                                    for dx in range(-4, 5) for dy in range(-1, 2))
                    near_road = any(ib(cx+dx, road_y) and bool(rm[road_y, cx+dx])
                                    for dx in [-1, 1])
                    if near_wire or near_road:
                        return (Tool.ROAD, cx, road_y)

    # Vertical roads parallel to wire columns
    for col_x in neighborhood_xs:
        col_neighborhoods = [(nx, ny) for (nx, ny) in active_neighborhoods if nx == col_x]
        if not col_neighborhoods:
            continue
        ys = sorted([ny for (nx, ny) in col_neighborhoods])
        y_start, y_end = ys[0], ys[-1]
        for rx_off in road_col_offsets:
            road_x = col_x + rx_off
            if not ib(road_x, 0):
                continue
            for cy in range(max(2, y_start-2), min(WORLD_H-2, y_end+3)):
                if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    near_wire = any(ib(road_x+dx, cy+dy) and (bool(wm[cy+dy, road_x+dx]) or bool(pm[cy+dy, road_x+dx]))
                                    for dy in range(-4, 5) for dx in range(-1, 2))
                    near_road = any(ib(road_x, cy+dy) and bool(rm[cy+dy, road_x])
                                    for dy in [-1, 1])
                    if near_wire or near_road:
                        return (Tool.ROAD, road_x, cy)

    # ---- STEP 4: ZONE PLACEMENT ----
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate cells: empty + near road + near wire + away from map edge
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active neighborhoods
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_neighborhoods:
            d = np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- STEP 5: EXTEND ROADS reactively ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- STEP 6: CIVIC SERVICES ----
    if pop > 30:
        # Fire stations: reactive - place near zones that lack coverage
        fire_grid = []
        for ix in range(0, WORLD_W, 20):
            for iy in range(0, WORLD_H, 20):
                fire_grid.append((ix+10, iy+10))
        for (fx, fy) in fire_grid:
            fx = min(fx, WORLD_W-2)
            fy = min(fy, WORLD_H-2)
            if ib(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if pop > 100:
        police_grid = []
        for ix in range(0, WORLD_W, 25):
            for iy in range(0, WORLD_H, 25):
                police_grid.append((ix+12, iy+8))
        for (px2, py2) in police_grid:
            px2 = min(px2, WORLD_W-2)
            py2 = min(py2, WORLD_H-2)
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.POLICESTATION, px2, py2)

    if pop > 400:
        stadium_spots = [(20, 5), (60, 5), (100, 5), (20, 93), (60, 93), (100, 93), (5, 50), (115, 50)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [(5, 5), (115, 5), (5, 93), (115, 93), (60, 3), (60, 96), (3, 50), (117, 50)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for asp in [(55, 5), (5, 50), (114, 50), (55, 93)]:
            ax2, ay2 = asp
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for sp in [(3, 93), (116, 93), (3, 5), (116, 5), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- STEP 7: PARKS near zones ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0)]:
                    nx2, ny2 = zx2+dx2, zy2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

