def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Zone ratio: 45% RES, 30% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense plant grid covering whole map
    plant_positions = []
    for px in [15, 35, 55, 75, 95, 110]:
        for py in [15, 32, 50, 68, 85]:
            plant_positions.append((px, py))

    # Phase 1: ensure power plants exist (check 6-tile radius for existing plant)
    if funds > 3000:
        for ppx, ppy in plant_positions:
            if not ib(ppx, ppy):
                continue
            found = False
            x0, x1 = max(0, ppx-6), min(WORLD_W, ppx+7)
            y0, y1 = max(0, ppy-6), min(WORLD_H, ppy+7)
            if np.any(pm[y0:y1, x0:x1]):
                found = True
            if not found and bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # Wire grid: dense horizontal spines every 6 rows and vertical every 6 cols
    wire_rows = list(range(6, 98, 6))
    wire_cols = list(range(6, 118, 6))

    # Extend horizontal wires across full map
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Seed near center or a plant
            pys_r, pxs_r = np.where(pm)
            if len(pxs_r) > 0:
                # Find nearest plant row
                dists = np.abs(pys_r - wr)
                best_p = np.argmin(dists)
                px_seed = int(pxs_r[best_p])
                if ib(px_seed, wr) and em[wr, px_seed]:
                    return (Tool.WIRE, px_seed, wr)
            if ib(60, wr) and em[wr, 60]:
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        for x in range(left, right + 1):
            if ib(x, wr) and em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            pys_c, pxs_c = np.where(pm)
            if len(pxs_c) > 0:
                dists = np.abs(pxs_c - wc)
                best_p = np.argmin(dists)
                py_seed = int(pys_c[best_p])
                if ib(wc, py_seed) and em[py_seed, wc]:
                    return (Tool.WIRE, wc, py_seed)
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot + 1):
            if ib(wc, y) and em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # Road grid: offset 3 tiles from wire lines
    road_rows = []
    road_cols = []
    for wr in wire_rows:
        for off in [-3, 3]:
            r = wr + off
            if 2 < r < WORLD_H - 2:
                road_rows.append(r)
    for wc in wire_cols:
        for off in [-3, 3]:
            c = wc + off
            if 2 < c < WORLD_W - 2:
                road_cols.append(c)
    road_rows = sorted(set(road_rows))
    road_cols = sorted(set(road_cols))

    # Build horizontal roads
    for rr in road_rows:
        row_road = rm[rr, :]
        if not row_road.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_road)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and ib(left-1, rr) and em[rr, left-1] and not pm[rr, left-1]:
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-3 and ib(right+1, rr) and em[rr, right+1] and not pm[rr, right+1]:
            return (Tool.ROAD, right+1, rr)
        for x in range(left, right+1):
            if ib(x, rr) and em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_road)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and ib(rc, top-1) and em[top-1, rc] and not pm[top-1, rc]:
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-3 and ib(rc, bot+1) and em[bot+1, rc] and not pm[bot+1, rc]:
            return (Tool.ROAD, rc, bot+1)
        for y in range(top, bot+1):
            if ib(rc, y) and em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # Compute neighborhood masks
    # Near road: within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Near wire or plant: within 4 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Zone placement: closed-loop, near road and wire
    cand = em & nbr_road & nbr_wire
    cand[0:4, :] = False
    cand[WORLD_H-4:, :] = False
    cand[:, 0:4] = False
    cand[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                zone_score = zone_dist
            else:
                zone_score = (np.abs(cxs_arr - 60).astype(float) +
                              np.abs(cys_arr - 50).astype(float))
        else:
            zone_score = (np.abs(cxs_arr - 60).astype(float) +
                          np.abs(cys_arr - 50).astype(float))

        # Spread outward when pop grows
        if pop > 300:
            corners = [(20, 20), (100, 20), (20, 80), (100, 80),
                       (60, 10), (60, 90), (10, 50), (110, 50),
                       (40, 20), (80, 20), (40, 80), (80, 80)]
            min_corner = np.full(len(cxs_arr), 999999.0)
            for cx, cy in corners:
                d = (np.abs(cxs_arr - cx).astype(float) +
                     np.abs(cys_arr - cy).astype(float))
                min_corner = np.minimum(min_corner, d)
            zone_score = zone_score * 0.4 + min_corner * 0.6

        order = np.argsort(zone_score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # Civic services - aggressive thresholds
    if pop > 15:
        fire_spots = [(fx, fy) for fy in range(10, 95, 8)
                      for fx in range(10, 115, 12)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_spots = [(px2, py2) for py2 in range(12, 92, 10)
                        for px2 in range(12, 112, 14)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150:
        park_spots = [(pkx, pky) for pky in range(10, 95, 10)
                      for pkx in range(10, 115, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300:
        stadium_spots = [
            (25, 20), (60, 20), (95, 20),
            (25, 50), (95, 50),
            (25, 80), (60, 80), (95, 80),
            (45, 35), (75, 35), (45, 65), (75, 65),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 5000:
        nuclear_spots = [
            (15, 50), (105, 50), (60, 15), (60, 85),
            (15, 25), (105, 25), (15, 75), (105, 75),
            (40, 15), (80, 15), (40, 85), (80, 85),
        ]
        for npx, npy in nuclear_spots:
            if ib(npx, npy):
                x0, x1 = max(0, npx-5), min(WORLD_W, npx+6)
                y0, y1 = max(0, npy-5), min(WORLD_H, npy+6)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[npy, npx]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        airport_spots = [
            (55, 5), (65, 5), (55, 94), (65, 94),
            (5, 44), (114, 44), (5, 55), (114, 55),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 700:
        seaport_spots = [
            (5, 50), (114, 50), (60, 4), (60, 95),
            (20, 4), (100, 4), (20, 95), (100, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend wires from plants toward empty areas
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        sk = (step * 11) % len(pxs2)
        for offset in range(min(len(pxs2), 60)):
            k = (sk + offset * 7) % len(pxs2)
            px3, py3 = int(pxs2[k]), int(pys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = px3+dx2, py3+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: roads from existing wires
    wys3, wxs3 = np.where(wm)
    if len(wxs3) > 0:
        sk2 = (step * 13) % len(wxs3)
        for offset in range(min(len(wxs3), 80)):
            k = (sk2 + offset * 5) % len(wxs3)
            wx3, wy3 = int(wxs3[k]), int(wys3[k])
            for dx3, dy3 in [(0,3),(0,-3),(3,0),(-3,0),(0,4),(0,-4),(4,0),(-4,0)]:
                nx3, ny3 = wx3+dx3, wy3+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

