        # Vertical wire spine
        for dy in range(-8, 9):
            if 0 <= py + dy < WORLD_H:
                actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-8, 9):
            if 0 <= py + dy < WORLD_H:
                actions.append((Tool.ROAD, px - 2, py + dy))
                actions.append((Tool.ROAD, px + 2, py + dy))
    # Horizontal wire connecting all three plants
    for x in range(20, 101):
        actions.append((Tool.WIRE, x, 50))
