def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # Target zone mix: 50% residential, 25% commercial, 25% industrial
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Power plants on a dense grid ----
    # Plants every 20 cols, 20 rows
    plant_grid_xs = list(range(10, WORLD_W - 5, 20))
    plant_grid_ys = list(range(10, WORLD_H - 5, 20))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network ----
    # Horizontal wire rows at plant y positions
    wire_rows = list(range(10, WORLD_H - 5, 20))
    wire_cols = list(range(10, WORLD_W - 5, 20))

    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                nearest = pxs[np.argmin(np.abs(pys - wr))]
                if ib(int(nearest), wr) and bool(em[wr, int(nearest)]):
                    return (Tool.WIRE, int(nearest), wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 3 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads placed between wire rows/cols
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 6)
        road_rows.append(wr + 6)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 6)
        road_cols.append(wc + 6)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            spread_score = zone_dist * 0.3
        else:
            spread_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 2.0 + spread_score
        order = np.argsort(score)
        off = (step * 7 + pop // 10) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services (more aggressive thresholds) ----
    if pop > 10:
        fire_spots = [(fx, fy) for fy in range(6, 96, 10) for fx in range(6, 114, 12)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 50:
        police_spots = [(px2, py2) for py2 in range(8, 94, 14) for px2 in range(8, 112, 14)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100:
        park_spots = [(pkx, pky) for pky in range(10, 92, 8) for pkx in range(10, 110, 8)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300:
        stadium_spots = [(sx, sy) for sy in range(14, 88, 18) for sx in range(14, 106, 22)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        airport_spots = [
            (55, 7), (65, 7), (55, 92), (65, 92),
            (7, 44), (112, 44), (7, 56), (112, 56),
            (30, 7), (90, 7), (30, 92), (90, 92),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        seaport_spots = [
            (7, 50), (112, 50), (60, 4), (60, 95),
            (24, 4), (96, 4), (24, 95), (96, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:
            shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:
            shifted[1:, :] = power_src[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1:
            shifted[:-1, :] = rm[1:, :]
        elif dy == 1:
            shifted[1:, :] = rm[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = rm[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: place road near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6, 0), (-6, 0), (0, 6), (0, -6), (4, 0), (-4, 0), (0, 4), (0, -4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle, initial wire+road spines"""
    actions = []
    # Three power plants
    actions.append((Tool.COALPOWER, 20, 25))
    actions.append((Tool.COALPOWER, 60, 75))
    actions.append((Tool.COALPOWER, 100, 25))
    # Horizontal wire connecting plants at y=25
    for x in range(18, 103):
        actions.append((Tool.WIRE, x, 25))
    # Vertical wire from y=25 down to y=75
    for y in range(25, 77):
        actions.append((Tool.WIRE, 60, y))
    # Seed horizontal roads near each plant
    for x in range(12, 32):
        actions.append((Tool.ROAD, x, 32))
    for x in range(52, 72):
        actions.append((Tool.ROAD, x, 68))
    for x in range(92, 112):
        actions.append((Tool.ROAD, x, 32))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # --- DILATE helper ---
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure power plants on a dense grid ---
    # One plant every ~20 cols, 20 rows
    plant_xs = list(range(10, WORLD_W - 5, 20))
    plant_ys = list(range(10, WORLD_H - 5, 20))

    for ppy in plant_ys:
        for ppx in plant_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # --- PHASE 2: Wire grid --- 
    # Horizontal wires every 10 rows (at rows 10,20,30,...)
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    # Extend horizontal wires
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            # Start wire from nearest plant row
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 2 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 2 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # --- PHASE 3: Road grid ---
    # Roads at rows midway between wire rows
    road_rows = sorted(set(r for r in [wr + 5 for wr in wire_rows] if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in [wc + 5 for wc in wire_cols] if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- PHASE 4: Zone placement (closed-loop, reactive) ---
    zone_cand = em & near_road & near_power
    # Keep margin
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Block infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist > 15, min_zone_dist * 0.5, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.4
        order = np.argsort(score)
        off = (step * 11 + pop % 17) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services (reactive to population) ---
    if pop > 30:
        fire_ys = list(range(15, WORLD_H - 5, 12))
        fire_xs = list(range(15, WORLD_W - 5, 18))
        for fsy in fire_ys:
            for fsx in fire_xs:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        pol_ys = list(range(18, WORLD_H - 5, 14))
        pol_xs = list(range(18, WORLD_W - 5, 20))
        for psy in pol_ys:
            for psx in pol_xs:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_ys = list(range(12, WORLD_H - 5, 10))
        park_xs = list(range(12, WORLD_W - 5, 12))
        for pky in park_ys:
            for pkx in park_xs:
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 600:
        stad_spots = [(sx, sy) for sy in range(20, 85, 25) for sx in range(20, 100, 30)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuc_spots = [(nx, ny) for ny in range(15, 90, 25) for nx in range(15, 110, 25)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 14), min(WORLD_W, npx + 15)
                y0, y1 = max(0, npy - 14), min(WORLD_H, npy + 15)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(55, 7), (65, 7), (55, 92), (65, 92), (7, 45), (112, 45)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- PHASE 6: Wire extension toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 7: Road extension toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- Fallback: road near existing plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6, 0), (-6, 0), (0, 6), (0, -6), (4, 0), (-4, 0), (0, 4), (0, -4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in a 3x2 grid with wire spines and flanking roads."""
    actions = []
    for px in [20, 60, 100]:
        for py in [30, 70]:
            actions.append((Tool.COALPOWER, px, py))
            for dy in range(-8, 9):
                actions.append((Tool.WIRE, px, py + dy))
            for dy in range(-8, 9):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 50% res, 30% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 12 neighborhoods: 4 columns x 3 rows — use more of the map
    anchors = []
    for col_x in [15, 45, 75, 105]:
        for row_y in [25, 50, 75]:
            anchors.append((col_x, row_y, col_x, col_x - 1, col_x + 1))

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 3
        if pop < 500:   return 4
        if pop < 750:   return 5
        if pop < 1100:  return 6
        if pop < 1600:  return 7
        if pop < 2200:  return 8
        if pop < 3000:  return 9
        if pop < 4000:  return 10
        if pop < 5000:  return 11
        return 12

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) — grow with pop ----
    spine_half = min(35, 10 + pop // 12)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-5, 6):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows ----
    if n_active >= 3:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                _, py1, _, _, _ = col_anchors[i]
                _, py2, _, _, _ = col_anchors[i + 1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels ----
    if pop > 20:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            for horiz_y in [yl - 4, yl + 4, yl - 8, yl + 8]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # Cross-roads connecting rows
    if pop > 60 and len(y_levels) >= 2:
        for col_x in [15, 45, 75, 105]:
            y_sorted = sorted(y_levels)
            for i in range(len(y_sorted) - 1):
                y1 = y_sorted[i]
                y2 = y_sorted[i + 1]
                for rx in [col_x - 3, col_x + 3]:
                    if not ib(rx, y1) or not ib(rx, y2):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float)
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scaled to population) ----
    if pop > 60:
        fire_spots = [
            (6, 12), (30, 12), (55, 12), (80, 12), (110, 12),
            (6, 38), (30, 38), (55, 38), (80, 38), (110, 38),
            (6, 62), (30, 62), (55, 62), (80, 62), (110, 62),
            (6, 87), (30, 87), (55, 87), (80, 87), (110, 87),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (10, 18), (38, 18), (65, 18), (92, 18), (116, 18),
            (10, 44), (38, 44), (65, 44), (92, 44), (116, 44),
            (10, 68), (38, 68), (65, 68), (92, 68), (116, 68),
            (10, 92), (38, 92), (65, 92), (92, 92), (116, 92),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (10, 6), (50, 6), (90, 6), (115, 6),
            (10, 93), (50, 93), (90, 93), (115, 93),
            (10, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 94), (90, 94),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92), (28, 6), (88, 6), (28, 92), (88, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 95), (115, 95), (60, 97), (5, 3), (115, 3)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3),
                                  (4, 0), (-4, 0), (0, 4), (0, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Hybrid city builder: combines Parent A's neighborhood system with Parent B's
# wire corridor grid, plus more aggressive expansion and civic services.

def init(obs, state):
    """Bootstrap: 6 coal plants + wire cross-grid + flanking roads."""
    actions = []
    # 6 strategically placed coal plants
    plants = [(20, 25), (60, 25), (100, 25),
              (20, 75), (60, 75), (100, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire corridors
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 75))
    # Vertical wire corridors
    for y in range(1, 99):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Roads flanking horizontal corridors
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 74))
        actions.append((Tool.ROAD, x, 76))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire + road corridor definitions
    wire_rows = [25, 40, 55, 75, 90]
    wire_cols = [20, 40, 60, 80, 100]

    # Dense neighborhood grid: 10 cols x 8 rows
    nh_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106, 118]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 600:   return 16
        if pop < 1200:  return 28
        if pop < 2500:  return 45
        if pop < 5000:  return 64
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Build proximity masks efficiently
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # ---- PHASE 0: ENSURE POWER PLANTS near active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    l = ib(wx-1, wr) and bool(row_wire[wx-1])
                    r2 = ib(wx+1, wr) and bool(row_wire[wx+1])
                    if (l or r2) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    u = ib(wc, wy-1) and bool(col_wire[wy-1])
                    d = ib(wc, wy+1) and bool(col_wire[wy+1])
                    if (u or d) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Wire spines through neighborhood centers (vertical)
        spine_r = 8
        for (hx, hy) in active_hoods:
            for dy in range(-spine_r, spine_r + 1):
                wy = hy + dy
                if not ib(hx, wy): continue
                if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
                if not bool(em[wy, hx]): continue
                for adj_dy in [-1, 1]:
                    ay = wy + adj_dy
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, wy)

    elif phase == 5:
        # Roads flanking vertical wire spines
        spine_r = 8
        for (hx, hy) in active_hoods:
            for rx in [hx - 1, hx + 1]:
                if not ib(rx, hy): continue
                for dy in range(-spine_r, spine_r + 1):
                    ry = hy + dy
                    if not ib(rx, ry): continue
                    if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 6:
        # Cross roads at mid-points between wire corridors
        for wc_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            mid_x = (c1 + c2) // 2
            for wr_idx in range(len(wire_rows) - 1):
                r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
                mid_y = (r1 + r2) // 2
                for rx in range(c1 + 2, c2 - 1):
                    if ib(rx, mid_y) and bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                        adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                              (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)
                for ry in range(r1 + 2, r2 - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                              (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 7:
        # Extend roads from existing road near power
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % len(road_xs2)
            for offset in range(min(len(road_xs2), 150)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Wire connection between neighborhoods
        for (hx1, hy1) in active_hoods:
            for (hx2, hy2) in active_hoods:
                if hy1 == hy2 and 0 < hx2 - hx1 <= 14:
                    for cx2 in range(hx1 + 1, hx2):
                        if not ib(cx2, hy1): continue
                        if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                        if not bool(em[hy1, cx2]): continue
                        for adx in [-1, 1]:
                            ax = cx2 + adx
                            if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                                return (Tool.WIRE, cx2, hy1)
                if hx1 == hx2 and 0 < hy2 - hy1 <= 14:
                    for cy2 in range(hy1 + 1, hy2):
                        if not ib(hx1, cy2): continue
                        if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                        if not bool(em[cy2, hx1]): continue
                        for ady in [-1, 1]:
                            ay = cy2 + ady
                            if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                                return (Tool.WIRE, hx1, cy2)

    # ---- ZONE PLACEMENT (every step) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors for zones
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_grid = [
            (10, 5), (35, 5), (60, 5), (85, 5), (110, 5),
            (10, 18), (35, 18), (60, 18), (85, 18), (110, 18),
            (10, 35), (35, 35), (60, 35), (85, 35), (110, 35),
            (10, 50), (35, 50), (85, 50), (110, 50),
            (10, 65), (35, 65), (60, 65), (85, 65), (110, 65),
            (10, 85), (35, 85), (60, 85), (85, 85), (110, 85),
        ]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_grid = [
            (22, 12), (52, 12), (82, 12), (112, 12),
            (12, 30), (42, 30), (72, 30), (102, 30),
            (22, 47), (52, 47), (82, 47), (112, 47),
            (12, 62), (42, 62), (72, 62), (102, 62),
            (22, 80), (52, 80), (82, 80), (112, 80),
        ]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (30, 10), (60, 10), (90, 10),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (30, 68), (60, 68), (90, 68),
            (15, 88), (45, 88), (75, 88), (105, 88),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (5, 50), (115, 50), (60, 5), (60, 94),
            (30, 94), (90, 94), (30, 5), (90, 5),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 88), (115, 88), (5, 10), (115, 10),
                    (60, 5), (60, 94), (30, 5), (90, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [(45, 5), (75, 5), (45, 93), (75, 93),
                    (5, 40), (5, 55), (113, 40), (113, 55)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: target unpowered hoods with wire ----
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- LAST RESORT: new coal plant at unpowered hood ----
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants with wire spines and flanking roads."""
    actions = []
    # 6 plants in 2 rows x 3 cols covering the map
    plants = [(20, 30), (60, 30), (100, 30), (20, 70), (60, 70), (100, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-5, 6):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connecting plants in each row
    for y_level in [30, 70]:
        for x in range(20, 101):
            actions.append((Tool.WIRE, x, y_level))
    # Horizontal roads along y=28,32 and y=68,72
    for y_level in [30, 70]:
        for offset in [-2, 2]:
            for x in range(1, 119):
                actions.append((Tool.ROAD, x, y_level + offset))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 cluster centers (plant positions)
    cluster_centers = [(20, 30), (60, 30), (100, 30), (20, 70), (60, 70), (100, 70)]

    # Scale active clusters with population
    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 3
        if pop < 300:  return 4
        if pop < 600:  return 5
        return 6

    n_active = num_active()
    active_centers = cluster_centers[:n_active]

    # Dilate helper
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (px, py) in active_centers:
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            # Try to place plant near cluster center
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE INFRASTRUCTURE ----
    # Horizontal wire at y=30 and y=70
    wire_rows = [30, 70]
    wire_cols = [20, 60, 100]

    phase = step % 8

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left_has = wx > 0 and bool(row_wire[wx - 1])
                    right_has = wx < WORLD_W - 1 and bool(row_wire[wx + 1])
                    if (left_has or right_has) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up_has = wy > 0 and bool(col_wire[wy - 1])
                    dn_has = wy < WORLD_H - 1 and bool(col_wire[wy + 1])
                    if (up_has or dn_has) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Add middle horizontal wire at y=50
        mid_row = 50
        col_wire_30 = wm[:, 60] | pm[:, 60]
        if np.any(col_wire_30):
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[mid_row, wx]) and not bool(pm[mid_row, wx]):
                    left_has = wx > 0 and (bool(wm[mid_row, wx-1]) or bool(pm[mid_row, wx-1]))
                    right_has = wx < WORLD_W-1 and (bool(wm[mid_row, wx+1]) or bool(pm[mid_row, wx+1]))
                    col_has = bool(wm[mid_row, wx]) or bool(pm[mid_row, wx])
                    # check vertical wire at this x
                    if wx in wire_cols:
                        col_w = wm[:, wx] | pm[:, wx]
                        up_has = mid_row > 0 and bool(col_w[mid_row - 1])
                        dn_has = mid_row < WORLD_H-1 and bool(col_w[mid_row + 1])
                        if (up_has or dn_has) and bool(em[mid_row, wx]):
                            return (Tool.WIRE, wx, mid_row)
                    if (left_has or right_has) and bool(em[mid_row, wx]):
                        return (Tool.WIRE, wx, mid_row)

    elif phase == 3:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Extend vertical wire for new clusters at intermediate columns
        extra_cols = [40, 80]
        for wc in extra_cols:
            if pop < 200:
                break
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                # Seed from horizontal wire
                for wr in wire_rows:
                    if bool(wm[wr, wc]) or bool(pm[wr, wc]):
                        # Already connected
                        break
                    # Try to place wire connecting from nearest existing wire
                    for dx in range(-3, 4):
                        nx = wc + dx
                        if ib(nx, wr) and (bool(wm[wr, nx]) or bool(pm[wr, nx])):
                            # Walk from nx to wc
                            direction = 1 if wc > nx else -1
                            for step_x in range(nx + direction, wc + direction, direction):
                                if ib(step_x, wr) and bool(em[wr, step_x]):
                                    return (Tool.WIRE, step_x, wr)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_wire[wy]):
                        up_has = wy > 0 and bool(col_wire[wy - 1])
                        dn_has = wy < WORLD_H - 1 and bool(col_wire[wy + 1])
                        if (up_has or dn_has) and bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 6:
        # Extra horizontal roads connecting neighborhoods
        for wr in wire_rows:
            for extra_y in [wr - 5, wr + 5]:
                if not (2 < extra_y < WORLD_H - 2):
                    continue
                row_wire = wm[wr, :] | pm[wr, :]
                for rx in range(2, WORLD_W - 2):
                    if bool(row_wire[rx]) and bool(em[extra_y, rx]) and not bool(pm[extra_y, rx]):
                        return (Tool.ROAD, rx, extra_y)

    elif phase == 7:
        # Extend road network outward from existing roads near power
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % max(len(road_xs2), 1)
            for offset in range(min(len(road_xs2), 120)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Don't place zones on wire corridors
    for wr in wire_rows:
        cand_mask[wr, :] = False
    for wc in wire_cols:
        cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (10, 20), (35, 20), (60, 20), (85, 20), (110, 20),
            (10, 40), (35, 40), (85, 40), (110, 40),
            (10, 60), (35, 60), (60, 60), (85, 60), (110, 60),
            (10, 80), (35, 80), (60, 80), (85, 80), (110, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (20, 15), (60, 15), (100, 15),
            (20, 50), (60, 50), (100, 50),
            (20, 85), (60, 85), (100, 85),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (40, 10), (80, 10), (10, 50), (110, 50),
            (40, 90), (80, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (30, 50), (90, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (50, 94), (5, 45), (115, 45)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PARKS to boost land value ----
    if pop > 200 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: connect unpowered areas ----
    # Find wire/plant and extend toward areas without power
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        # Find empty cells near active clusters not yet powered
        for (hx, hy) in active_centers:
            if not bool(near_power[hy, hx]):
                dists = np.abs(wire_xs_arr - hx) + np.abs(wire_ys_arr - hy)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                dx = 0 if hx == bwx else (1 if hx > bwx else -1)
                dy = 0 if hy == bwy else (1 if hy > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy), (bwx + dx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % max(len(wire_xs3), 1)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# High-density city builder: compact neighborhoods with proper power+road grids
# Strategy: 6x5 grid of neighborhoods, each with coal plant, wire cross, road grid, and zones
# Closed-loop: reacts to actual map state each step

def init(obs, state):
    """Bootstrap: 3 coal plants with wire connections to seed power distribution."""
    actions = []
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire horizontal from center plant
    for dx in range(1, 10):
        actions.append((Tool.WIRE, 60 + dx, 50))
        actions.append((Tool.WIRE, 60 - dx, 50))
    # Wire vertical from center plant
    for dy in range(1, 8):
        actions.append((Tool.WIRE, 60, 50 + dy))
        actions.append((Tool.WIRE, 60, 50 - dy))
    # Left plant
    actions.append((Tool.COALPOWER, 20, 25))
    actions.append((Tool.WIRE, 21, 25))
    actions.append((Tool.WIRE, 22, 25))
    # Right plant
    actions.append((Tool.COALPOWER, 100, 75))
    actions.append((Tool.WIRE, 99, 75))
    actions.append((Tool.WIRE, 98, 75))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # 6 cols x 5 rows = 30 neighborhoods, spaced 18 apart horiz, 18 apart vert
    nh_cols = [12, 30, 48, 66, 84, 102]
    nh_rows = [12, 28, 44, 60, 76, 92]
    # Use 6x5 grid: 30 hoods total, but limit rows to 5 valid rows
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock
    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 400:   return 10
        if pop < 800:   return 15
        if pop < 1500:  return 20
        if pop < 3000:  return 24
        if pop < 5000:  return 28
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        # Spread evenly across grid
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # ---- PHASE 1: POWER PLANTS at each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant close to hood center
            for r in range(12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CROSS from each plant ----
    spine_range = 8
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant to this hood
    px_best, py_best = hx, hy
    best_pd = 999
    for yr in range(max(0, hy - 9), min(WORLD_H, hy + 10)):
        for xr in range(max(0, hx - 9), min(WORLD_W, hx + 10)):
            if bool(pm[yr, xr]):
                d = abs(xr - hx) + abs(yr - hy)
                if d < best_pd:
                    best_pd = d
                    px_best, py_best = xr, yr

    # Wire vertical spine at plant x
    for dy in range(-spine_range, spine_range + 1):
        wy = py_best + dy
        if not ib(px_best, wy): continue
        if bool(wm[wy, px_best]) or bool(pm[wy, px_best]): continue
        if not bool(em[wy, px_best]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(px_best, ay) and (bool(wm[ay, px_best]) or bool(pm[ay, px_best])):
                return (Tool.WIRE, px_best, wy)

    # Wire horizontal spine at plant y
    for dx in range(-spine_range, spine_range + 1):
        wx = px_best + dx
        if not ib(wx, py_best): continue
        if bool(wm[py_best, wx]) or bool(pm[py_best, wx]): continue
        if not bool(em[py_best, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, py_best) and (bool(wm[py_best, ax]) or bool(pm[py_best, ax])):
                return (Tool.WIRE, wx, py_best)

    # ---- PHASE 3: WIRE CONNECTIONS between adjacent hoods ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            # Right neighbor (same row, next col)
            if hy1 == hy2 and abs(hx2 - hx1) == 18:
                mid_y = hy1
                for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx, mid_y): continue
                    if bool(wm[mid_y, cx]) or bool(pm[mid_y, cx]): continue
                    if not bool(em[mid_y, cx]): continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx, mid_y)
            # Bottom neighbor (same col, next row)
            if hx1 == hx2 and abs(hy2 - hy1) == 16:
                mid_x = hx1
                for cy in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(mid_x, cy): continue
                    if bool(wm[cy, mid_x]) or bool(pm[cy, mid_x]): continue
                    if not bool(em[cy, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy)

    # ---- PHASE 4: ROAD GRID ----
    # Build roads in a cross pattern offset from wire spine
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step // max(len(active_hoods), 1)) % 2 == 0 and idx_h % 3 != step % 3:
            continue
        # Road flanking vertical wire
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if ib(hx, ry) and (bool(wm[ry, hx]) or bool(pm[ry, hx])):
                        return (Tool.ROAD, rx, ry)
        # Road flanking horizontal wire
        for ry2 in [hy - 2, hy + 2]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if ib(rcx, hy) and (bool(wm[hy, rcx]) or bool(pm[hy, rcx])):
                        return (Tool.ROAD, rcx, ry2)
        # Also roads 1 off spine for denser coverage
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range // 2, spine_range // 2 + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if ib(hx, ry) and (bool(wm[ry, hx]) or bool(pm[ry, hx])):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 40% RES, 30% COM, 30% IND
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        if rr < 0.38:
            return Tool.RESIDENTIAL
        # Cycle based on step for variety
        cycle = step % 3
        if cycle == 0: return Tool.RESIDENTIAL
        if cycle == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road coverage mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    shifts = range(-3, 4)
    for dy2 in shifts:
        for dx2 in shifts:
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            if sr1 > sr0 and sc1 > sc0 and r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power coverage mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            if sr1 > sr0 and sc1 > sc0 and r1 > r0 and c1 > c0:
                nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W, 20) for py2 in range(15, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(24, 20), (72, 20), (24, 50), (72, 50), (24, 80), (72, 80),
                    (48, 35), (96, 35), (48, 65), (96, 65), (12, 65), (108, 35)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(6, 85), (114, 85), (6, 15), (114, 15), (60, 94), (60, 6),
                    (25, 94), (85, 94), (35, 6), (95, 6)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40, 5), (80, 5), (40, 94), (80, 94), (5, 40), (5, 65),
                    (105, 40), (105, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for large cities ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(60, 50), (30, 20), (90, 20), (30, 80), (90, 80),
                         (10, 50), (110, 50), (60, 8), (60, 92),
                         (48, 35), (72, 65), (18, 35), (102, 65)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 100 and step % 5 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cand)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: plant for uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Strategy: Dense multi-neighborhood city with systematic power grid,
# road network, and balanced zone placement across the full 120x100 map.
# Uses a structured layout with power spines connecting neighborhoods.

def init(obs, state):
    """Bootstrap: 3 coal plants + wire spines + roads near center."""
    actions = []
    # Center plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from center plant
    for dx in range(-5, 6):
        if dx != 0:
            actions.append((Tool.WIRE, 60 + dx, 50))
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, 60, 50 + dy))
    # Roads flanking vertical wire
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))
    # Left plant
    actions.append((Tool.COALPOWER, 20, 50))
    # Right plant
    actions.append((Tool.COALPOWER, 100, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 9 cols x 8 rows = 72 neighborhoods ----
    # Spacing: 12 cols, 12 rows
    nh_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock
    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 45
        if pop < 7000:  return 60
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        # Pick hoods close to center first, expanding outward
        cx_map, cy_map = 60, 50
        dists = [abs(h[0] - cx_map) + abs(h[1] - cy_map) for h in all_hoods]
        order = np.argsort(dists)
        active_hoods = [all_hoods[order[i]] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS (1 per 3 hoods approx) ----
    # Plant positions: every 3rd hood in a staggered grid
    plant_hoods = active_hoods[::3]

    for (hx, hy) in plant_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(12):
                candidates = []
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                candidates.append((nx, ny))
                if candidates:
                    return (Tool.COALPOWER, candidates[0][0], candidates[0][1])

    # ---- WIRE GRID: horizontal lines at every hood row, vertical at every hood col ----
    # Build horizontal wire spine at each hy in active_hoods
    active_rows = list(set(hy for _, hy in active_hoods))
    active_cols = list(set(hx for hx, _ in active_hoods))

    # Cycle through rows/cols based on step
    # Horizontal wires first
    row_idx = step % max(len(active_rows), 1)
    hy_wire = active_rows[row_idx % len(active_rows)]

    # Extend horizontal wire along this row
    for wx in range(1, WORLD_W - 1):
        if not ib(wx, hy_wire):
            continue
        if bool(pm[hy_wire, wx]):
            continue
        if bool(wm[hy_wire, wx]):
            continue
        if not bool(em[hy_wire, wx]):
            continue
        # Check adjacency
        adj = False
        for adx in [-1, 1]:
            ax = wx + adx
            if ib(ax, hy_wire) and (bool(wm[hy_wire, ax]) or bool(pm[hy_wire, ax])):
                adj = True
                break
        for ady in [-1, 1]:
            ay = hy_wire + ady
            if ib(wx, ay) and (bool(wm[ay, wx]) or bool(pm[ay, wx])):
                adj = True
                break
        if adj:
            return (Tool.WIRE, wx, hy_wire)

    # Vertical wires
    col_idx = (step // max(len(active_rows), 1) + 1) % max(len(active_cols), 1)
    hx_wire = active_cols[col_idx % len(active_cols)]

    for wy in range(1, WORLD_H - 1):
        if not ib(hx_wire, wy):
            continue
        if bool(pm[wy, hx_wire]):
            continue
        if bool(wm[wy, hx_wire]):
            continue
        if not bool(em[wy, hx_wire]):
            continue
        adj = False
        for ady in [-1, 1]:
            ay = wy + ady
            if ib(hx_wire, ay) and (bool(wm[ay, hx_wire]) or bool(pm[ay, hx_wire])):
                adj = True
                break
        for adx in [-1, 1]:
            ax = hx_wire + adx
            if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                adj = True
                break
        if adj:
            return (Tool.WIRE, hx_wire, wy)

    # ---- ROADS: parallel to wire spines, offset by 1 ----
    # Horizontal road lanes at hy +/- 1 for active rows
    r_row_idx = (step + 5) % max(len(active_rows), 1)
    hy_road = active_rows[r_row_idx % len(active_rows)]

    for road_offset in [-1, 1]:
        ry = hy_road + road_offset
        if not ib(0, ry):
            continue
        for rx in range(1, WORLD_W - 1):
            if not ib(rx, ry):
                continue
            if not bool(em[ry, rx]):
                continue
            if bool(pm[ry, rx]):
                continue
            if bool(rm[ry, rx]):
                continue
            # Place road if wire exists on the spine at same x
            if bool(wm[hy_road, rx]) or bool(pm[hy_road, rx]):
                return (Tool.ROAD, rx, ry)

    # Vertical road lanes at hx +/- 1 for active cols
    r_col_idx = (step + 3) % max(len(active_cols), 1)
    hx_road = active_cols[r_col_idx % len(active_cols)]

    for road_offset in [-1, 1]:
        rcx = hx_road + road_offset
        if not ib(rcx, 0):
            continue
        for rcy in range(1, WORLD_H - 1):
            if not ib(rcx, rcy):
                continue
            if not bool(em[rcy, rcx]):
                continue
            if bool(pm[rcy, rcx]):
                continue
            if bool(rm[rcy, rcx]):
                continue
            if bool(wm[rcy, hx_road]) or bool(pm[rcy, hx_road]):
                return (Tool.ROAD, rcx, rcy)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% res, 30% com, 30% ind
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road proximity mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power proximity mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Zone candidate mask
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hood centers (prefer closer)
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use multiple offsets to vary placement
        offset = (step * 7 + total_zones * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS from existing network ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scaled with pop) ----
    fire_grid = [(x, y) for y in range(15, 100, 20) for x in range(15, 120, 20)]
    if pop > 100:
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    police_grid = [(x, y) for y in range(25, 100, 25) for x in range(25, 120, 25)]
    if pop > 400:
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70), (60, 50), (60, 15), (60, 85)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 5), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 5), (75, 5), (45, 95), (75, 95), (5, 45), (115, 45)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS near dense road/power areas ----
    if pop > 200 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23 + pop) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- EXTEND WIRE from existing network ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13 + pop) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: power plants + wire grid + road grid"""
    actions = []
    # Place coal plants at strategic positions
    plant_positions = [
        (10, 10), (40, 10), (70, 10), (100, 10),
        (10, 35), (40, 35), (70, 35), (100, 35),
        (10, 60), (40, 60), (70, 60), (100, 60),
        (10, 85), (40, 85), (70, 85), (100, 85),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire corridors at rows 10, 35, 60, 85
    for wy in [10, 35, 60, 85]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire corridors at cols 10, 40, 70, 100
    for wx in [10, 40, 70, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads alongside wire rows (above and below)
    for wy in [10, 35, 60, 85]:
        for offset in [-1, 1]:
            ry = wy + offset
            if 1 <= ry <= 98:
                for x in range(1, 119):
                    actions.append((Tool.ROAD, x, ry))
    # Roads alongside wire cols (left and right)
    for wx in [10, 40, 70, 100]:
        for offset in [-1, 1]:
            rx = wx + offset
            if 1 <= rx <= 118:
                for y in range(1, 99):
                    actions.append((Tool.ROAD, rx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Wire/power corridors
    wire_rows = [10, 35, 60, 85]
    wire_cols = [10, 40, 70, 100]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                # Allow empty or existing zone tiles
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: ENSURE POWER PLANTS EXIST ----
    # Each quadrant should have at least one plant
    quad_plants = [
        (10, 10), (40, 10), (70, 10), (100, 10),
        (10, 35), (40, 35), (70, 35), (100, 35),
        (10, 60), (40, 60), (70, 60), (100, 60),
        (10, 85), (40, 85), (70, 85), (100, 85),
    ]
    for px, py in quad_plants:
        x0, x1 = max(0, px-5), min(WORLD_W, px+6)
        y0, y1 = max(0, py-5), min(WORLD_H, py+6)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place near target
            for r in range(0, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CORRIDORS (reactive extension) ----
    phase = step % 6

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                # Find nearest plant and walk toward wr
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy, wr, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                # Extend leftward and rightward from existing powered cells
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        left_ok = wx > 0 and bool(row_power[wx-1])
                        right_ok = wx < WORLD_W-1 and bool(row_power[wx+1])
                        if (left_ok or right_ok) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2, wc, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        up_ok = wy > 0 and bool(col_power[wy-1])
                        down_ok = wy < WORLD_H-1 and bool(col_power[wy+1])
                        if (up_ok or down_ok) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (1 <= ry <= WORLD_H - 2):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_power[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (1 <= rcx <= WORLD_W - 2):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_power[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Wire intersections: connect horizontal+vertical corridors
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc-1])) or (wc < WORLD_W-1 and bool(wm[wr, wc+1]))
                col_ok = (wr > 0 and bool(wm[wr-1, wc])) or (wr < WORLD_H-1 and bool(wm[wr+1, wc]))
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    else:
        # Extend roads into powered-but-unroaded areas
        target_mask = near_power & ~near_road & em
        target_mask[0:3, :] = False
        target_mask[WORLD_H-3:, :] = False
        target_mask[:, 0:3] = False
        target_mask[:, WORLD_W-3:] = False
        tys, txs = np.where(target_mask)
        road_ys, road_xs = np.where(rm)
        if len(txs) > 0 and len(road_xs) > 0:
            ti = (step * 17) % len(txs)
            tx, ty = int(txs[ti]), int(tys[ti])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best_ri = np.argmin(dists)
            brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    # Avoid edges and wire/road corridors
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Avoid wire rows and cols (keep them as infrastructure)
    for wr in wire_rows:
        for offset in range(-1, 2):
            wy2 = wr + offset
            if 0 <= wy2 < WORLD_H:
                cand_mask[wy2, :] = False
    for wc in wire_cols:
        for offset in range(-1, 2):
            wx2 = wc + offset
            if 0 <= wx2 < WORLD_W:
                cand_mask[:, wx2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            # Prefer near existing zones (density building)
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            # Prefer areas well-powered and well-roaded
            scores[i] += 1.0 if bool(near_power[y, x]) else 0.0
            scores[i] += 1.0 if bool(near_road[y, x]) else 0.0
            # Slight preference for spread across map
            scores[i] += 0.5 / (1.0 + abs(x - 60)/60.0 + abs(y - 50)/50.0)

        order = np.argsort(-scores)
        offset_idx = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset_idx + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 30:
        # Fire stations spread across the map
        fire_positions = [
            (20, 20), (50, 20), (80, 20), (110, 20),
            (20, 45), (50, 45), (80, 45), (110, 45),
            (20, 70), (50, 70), (80, 70), (110, 70),
            (20, 92), (50, 92), (80, 92), (110, 92),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (25, 25), (55, 25), (85, 25), (115, 25),
            (25, 50), (55, 50), (85, 50), (115, 50),
            (25, 75), (55, 75), (85, 75), (115, 75),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (30, 22), (90, 22), (30, 72), (90, 72),
            (60, 47), (60, 47), (30, 47), (90, 47),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Add nuclear power plants for more capacity
        nuke_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 50), (115, 50),
            (5, 94), (60, 94), (115, 94),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [
            (5, 94), (115, 94), (5, 5), (115, 5),
            (60, 5), (60, 94),
        ]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (65, 5), (50, 92), (65, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value near dense zones
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power & dilate(zone_tiles, 3)
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: power unpowered road areas ----
    needs_power = rm & ~near_power
    npys, npxs = np.where(needs_power)
    if len(npxs) > 0:
        ti = (step * 23) % len(npxs)
        tx, ty = int(npxs[ti]), int(npys[ti])
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs2[best_wi]), int(wire_ys2[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend roads from existing near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants spread across the map with initial wire+road."""
    actions = []
    # Three plants: left, center, right at mid-height
    for px, py in [(20, 50), (60, 50), (100, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from each plant
        for d in range(1, 7):
            actions.append((Tool.WIRE, px, py + d))
            actions.append((Tool.WIRE, px, py - d))
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px - d, py))
        # Roads flanking vertical wire
        for d in range(-5, 6):
            actions.append((Tool.ROAD, px - 1, py + d))
            actions.append((Tool.ROAD, px + 1, py + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- NEIGHBORHOOD GRID ----
    # 8 cols x 6 rows = 48 neighborhoods, covering most of the map
    nh_cols = [12, 26, 40, 54, 68, 82, 96, 110]
    nh_rows = [12, 27, 42, 57, 72, 87]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock
    def num_active():
        if pop < 30:    return 3
        if pop < 100:   return 6
        if pop < 250:   return 10
        if pop < 500:   return 16
        if pop < 1000:  return 24
        if pop < 2000:  return 32
        if pop < 4000:  return 40
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread hoods evenly
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # Zone mix: 40% res, 30% com, 30% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        # Find empty spot near hood center
        for r in range(12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PRECOMPUTE NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 2: WIRE SPINES from plants ----
    spine_range = min(8, 4 + pop // 50)
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant to this hood
    px_best, py_best = hx, hy
    best_pd = 999
    for yr in range(max(0, hy - 8), min(WORLD_H, hy + 9)):
        for xr in range(max(0, hx - 8), min(WORLD_W, hx + 9)):
            if bool(pm[yr, xr]):
                d = abs(xr - hx) + abs(yr - hy)
                if d < best_pd:
                    best_pd = d
                    px_best, py_best = xr, yr

    # Wire vertical spine
    for dy in range(-spine_range, spine_range + 1):
        wy = py_best + dy
        if not ib(px_best, wy): continue
        if bool(wm[wy, px_best]) or bool(pm[wy, px_best]): continue
        if not bool(em[wy, px_best]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(px_best, ay) and (bool(wm[ay, px_best]) or bool(pm[ay, px_best])):
                return (Tool.WIRE, px_best, wy)

    # Wire horizontal spine
    for dx in range(-spine_range, spine_range + 1):
        wx = px_best + dx
        if not ib(wx, py_best): continue
        if bool(wm[py_best, wx]) or bool(pm[py_best, wx]): continue
        if not bool(em[py_best, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, py_best) and (bool(wm[py_best, ax]) or bool(pm[py_best, ax])):
                return (Tool.WIRE, wx, py_best)

    # ---- PHASE 3: WIRE MESH connecting adjacent hoods ----
    col_spacing = nh_cols[1] - nh_cols[0] if len(nh_cols) > 1 else 14
    row_spacing = nh_rows[1] - nh_rows[0] if len(nh_rows) > 1 else 15
    hood_set = set(active_hoods)

    # Only try a subset per step to avoid spending all time here
    start_h = (step * 3) % max(len(active_hoods), 1)
    for hi in range(min(len(active_hoods), 8)):
        hx1, hy1 = active_hoods[(start_h + hi) % len(active_hoods)]
        # Connect to right neighbor
        if (hx1 + col_spacing, hy1) in hood_set:
            hx2 = hx1 + col_spacing
            for cx in range(hx1 + 1, hx2):
                if not ib(cx, hy1): continue
                if bool(wm[hy1, cx]) or bool(pm[hy1, cx]): continue
                if not bool(em[hy1, cx]): continue
                for adx in [-1, 1]:
                    ax = cx + adx
                    if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                        return (Tool.WIRE, cx, hy1)
        # Connect to bottom neighbor
        if (hx1, hy1 + row_spacing) in hood_set:
            hy2 = hy1 + row_spacing
            for cy in range(hy1 + 1, hy2):
                if not ib(hx1, cy): continue
                if bool(wm[cy, hx1]) or bool(pm[cy, hx1]): continue
                if not bool(em[cy, hx1]): continue
                for ady in [-1, 1]:
                    ay = cy + ady
                    if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                        return (Tool.WIRE, hx1, cy)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h in range(min(len(active_hoods), 6)):
        hx2, hy2 = active_hoods[(step * 2 + idx_h) % len(active_hoods)]
        # Find local plant
        px2, py2 = hx2, hy2
        best_pd2 = 999
        for yr in range(max(0, hy2 - 8), min(WORLD_H, hy2 + 9)):
            for xr in range(max(0, hx2 - 8), min(WORLD_W, hx2 + 9)):
                if bool(pm[yr, xr]):
                    d = abs(xr - hx2) + abs(yr - hy2)
                    if d < best_pd2:
                        best_pd2 = d
                        px2, py2 = xr, yr
        # Flanking roads on vertical spine
        for ry in range(py2 - spine_range, py2 + spine_range + 1):
            if not ib(px2, ry): continue
            if not (bool(wm[ry, px2]) or bool(pm[ry, px2])): continue
            for rx in [px2 - 1, px2 + 1]:
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)
        # Flanking roads on horizontal spine
        for rx in range(px2 - spine_range, px2 + spine_range + 1):
            if not ib(rx, py2): continue
            if not (bool(wm[py2, rx]) or bool(pm[py2, rx])): continue
            for ry in [py2 - 1, py2 + 1]:
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx3, hy3) in active_hoods:
            d = np.abs(cxs - hx3).astype(float) + np.abs(cys - hy3).astype(float) * 0.9
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 22) for fy in range(15, WORLD_H, 22)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px3, py3) for px3 in range(18, WORLD_W, 24) for py3 in range(18, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 50), (75, 50), (55, 35), (65, 65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [(5, 5), (115, 5), (5, 95), (115, 95),
                      (60, 5), (60, 95), (5, 50), (115, 50),
                      (30, 50), (90, 50), (60, 30), (60, 70)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10),
                    (60, 95), (60, 5), (30, 95), (90, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94),
                    (6, 40), (6, 60), (106, 40), (106, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 150 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py4, px4 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px4, py4) and bool(em[py4, px4]):
                return (Tool.PARK, px4, py4)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant for uncovered hood ----
    for (hx4, hy4) in active_hoods:
        if not bool(nbr_power[min(hy4, WORLD_H-1), min(hx4, WORLD_W-1)]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx4 + dx, hy4 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# High-reactivity closed-loop city builder
# Strategy: Dense neighborhood grid covering full map, aggressive zone placement,
# proper power grid, roads everywhere, civic services at thresholds

def init(obs, state):
    """Bootstrap: central coal plant + cross of wires + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending 6 tiles
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-5, 6):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 8 cols x 7 rows = 56 neighborhoods ----
    # Spaced 14 apart horizontally, 13 apart vertically — denser coverage
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [8, 21, 34, 50, 66, 79, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 40
        if pop < 8000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods across map evenly
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Precompute neighbor power (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Precompute neighbor road (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active hood should have a power plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
        y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find closest empty tile
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from plants outward ----
    # For each active hood, extend wire cross (vertical + horizontal)
    spine_range = 8
    # Round-robin over hoods to spread work
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Extend vertical wire spine
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        # Only place if adjacent to existing wire or plant
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Extend horizontal wire spine
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Right neighbor
            if hy1 == hy2 and hx2 == hx1 + 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Bottom neighbor
            if hx1 == hx2 and hy2 == hy1 + 13:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    hood_idx2 = (step // 2) % max(len(active_hoods), 1)
    hx2, hy2 = active_hoods[hood_idx2]

    for rx in [hx2 - 1, hx2 + 1]:
        for dy in range(-spine_range, spine_range + 1):
            ry = hy2 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            # Only place road if wire spine is powered nearby
            if bool(nbr_power[ry, rx]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [hy2 - 1, hy2 + 1]:
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx2 + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]): continue
            if bool(pm[ry2, rcx]): continue
            if bool(nbr_power[ry2, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: CROSS ROADS between neighborhoods ----
    # Connect road grids between adjacent neighborhoods
    for (hx1, hy1) in active_hoods:
        for (hx2b, hy2b) in active_hoods:
            if hy1 == hy2b and hx2b == hx1 + 14:
                mid_y = hy1 + 1
                for cx3 in range(hx1 + 2, hx2b - 1):
                    if not ib(cx3, mid_y): continue
                    if not bool(em[mid_y, cx3]): continue
                    if bool(nbr_power[mid_y, cx3]):
                        return (Tool.ROAD, cx3, mid_y)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 45% RES, 30% COM, 25% IND
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx2, zy2 = int(cxs[k]), int(cys[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 7: EXTEND ROADS into powered but unroaded areas ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 150)):
            k = (step_k + offset * 7) % len(road_xs)
            rx3, ry3 = int(road_xs[k]), int(road_ys[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        # Fire stations on 18-tile grid
        for fx in range(12, WORLD_W, 18):
            for fy in range(12, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 300:
        for px3 in range(18, WORLD_W, 22):
            for py3 in range(18, WORLD_H, 22):
                if ib(px3, py3) and bool(em[py3, px3]):
                    return (Tool.POLICESTATION, px3, py3)

    if pop > 800:
        stadium_spots = [(30, 30), (90, 30), (30, 70), (90, 70),
                         (60, 15), (60, 85), (10, 50), (110, 50),
                         (45, 50), (75, 50), (15, 20), (105, 20),
                         (15, 80), (105, 80)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5),
                    (30, 95), (90, 95), (30, 5), (90, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 45), (6, 65),
                    (114, 45), (114, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER at high pop ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (10, 50), (110, 50), (60, 10), (60, 90)]
        for (nx4, ny4) in nuclear_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    # ---- PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py4, px4 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px4, py4) and bool(em[py4, px4]):
                return (Tool.PARK, px4, py4)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx3 + dx4, wy3 + dy4
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # ---- FALLBACK: place new plant near unpowered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx6, ny6 = hx + dx, hy + dy
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

# Ambitious closed-loop city builder - combines best of both parents
# Strategy: Dense 8x7 neighborhood grid, aggressive power/road/zone placement

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- NEIGHBORHOOD GRID: 8 cols x 7 rows = 56 neighborhoods ----
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [10, 22, 36, 50, 64, 78, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 42
        if pop < 8000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
        y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from each hood's plant (round-robin) ----
    spine_range = 12
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0, x1 = max(0, hx - 13), min(WORLD_W, hx + 14)
    y0, y1 = max(0, hy - 13), min(WORLD_H, hy + 14)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0

        # Extend vertical wire from plant toward hood center
        if py_local != hy:
            step_dir = 1 if hy > py_local else -1
            for wy in range(py_local + step_dir, hy + step_dir, step_dir):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        # Extend horizontal wire from plant toward hood center
        if px_local != hx:
            step_dir = 1 if hx > px_local else -1
            for wx in range(px_local + step_dir, hx + step_dir, step_dir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

        # Extend vertical spine from hood
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(pm[wy, hx]) or bool(wm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Extend horizontal spine from hood
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Right neighbor (same row, 14 apart)
            if hy1 == hy2 and hx2 == hx1 + 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Bottom neighbor (same col)
            if hx1 == hx2 and hy2 in [hy1 + 12, hy1 + 14]:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    for rx in [hx3 - 1, hx3 + 1]:
        if not ib(rx, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [hy3 - 1, hy3 + 1]:
        if not ib(hx3, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx3 + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS INTO POWERED AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(16, WORLD_W, 22) for py2 in range(16, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 25), (90, 25), (30, 75), (90, 75),
                    (60, 12), (60, 88), (10, 50), (110, 50),
                    (45, 50), (75, 50), (15, 25), (105, 25),
                    (15, 75), (105, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(6, 92), (114, 92), (6, 8), (114, 8), (60, 96), (60, 4)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(42, 5), (78, 5), (42, 95), (78, 95), (5, 42), (5, 72)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR UPGRADE for mature cities ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(60, 50), (20, 20), (100, 20), (20, 80), (100, 80),
                         (40, 35), (80, 35), (40, 65), (80, 65),
                         (60, 20), (60, 80), (20, 50), (100, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 150 and step % 3 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
