def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure enough power plants spread across map ----
    # Dense plant grid: every 20 cols, every 16 rows
    plant_grid = []
    for py in range(10, 95, 16):
        for px in range(10, 115, 20):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire expansion — connect unpowered plants and zones ----
    # Find tiles adjacent to power sources
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    # Check for unpowered plants
    unpowered_plants = [(px, py) for px, py in plant_grid
                        if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(len(wxs)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants)
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    if len(wxs) > 0:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid — dense horizontal roads every 6 rows, connected ----
    # Horizontal road grid lines
    road_rows = list(range(6, 97, 6))
    for ry in road_rows:
        # Check if this row has gaps in the road
        row_road = rm[ry, :]
        if int(np.sum(row_road)) < 100:  # Not fully built
            # Find first empty spot on this row that's near power
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    # Check if adjacent to existing road (left or right)
                    left_ok = rx > 0 and bool(rm[ry, rx-1])
                    right_ok = rx < WORLD_W-1 and bool(rm[ry, rx+1])
                    up_ok = ry > 0 and bool(rm[ry-1, rx])
                    down_ok = ry < WORLD_H-1 and bool(rm[ry+1, rx])
                    if left_ok or right_ok or up_ok or down_ok:
                        return (Tool.ROAD, rx, ry)
                    # Or just start a new road near a plant
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Vertical connector roads every 12 cols
    road_cols = list(range(12, 116, 12))
    for cx in road_cols:
        for cy in range(4, 96):
            if bool(em[cy, cx]) and bool(near_power[cy, cx]):
                adj = (cy > 0 and bool(rm[cy-1, cx])) or (cy < WORLD_H-1 and bool(rm[cy+1, cx]))
                if adj:
                    return (Tool.ROAD, cx, cy)

    # ---- PHASE 4: Zone placement with zone-mix awareness ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Don't zone on roads or wires
    zone_cand &= ~rm & ~wm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(rm[nr, nc]) or bool(wm[nr, nc]) or bool(pm[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer near roads and near power, avoid clustering too close
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 200)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.ones(len(cxs_arr)) * 9999.0

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 200)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Want some spread but not too far
            score = road_dist * 2.0 - np.clip(zone_dist, 0, 20) * 0.3
        else:
            # Start near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) + road_dist

        order = np.argsort(score)
        tool = pick_tool()
        # Try multiple candidates
        for i in range(min(len(order), 800)):
            k = order[i]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 100:
        fire_grid = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 115, 15)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_grid = [(px2, py2) for py2 in range(12, 92, 12) for px2 in range(12, 112, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_grid = [(pkx, pky) for pky in range(8, 95, 8) for pkx in range(8, 115, 10)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 800:
        stadium_locs = [(20, 15), (60, 15), (100, 15),
                        (20, 50), (60, 50), (100, 50),
                        (20, 85), (60, 85), (100, 85)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (40, 10), (80, 10), (40, 90), (80, 90)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(95, 10), (95, 85), (10, 10), (10, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from any existing road ----
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k = (step * 11) % len(rxs2)
        rx2, ry2 = int(rxs2[k]), int(rys2[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from power ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two central coal plants + wire spine + initial roads."""
    actions = []
    # Two power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire connecting them
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires at each plant
    for y in range(44, 57):
        if y != 50:
            actions.append((Tool.WIRE, 30, y))
            actions.append((Tool.WIRE, 90, y))
    # Seed roads near plants
    for y in range(44, 57):
        actions.append((Tool.ROAD, 29, y))
        actions.append((Tool.ROAD, 31, y))
        actions.append((Tool.ROAD, 89, y))
        actions.append((Tool.ROAD, 91, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Dense neighborhood grid covering the full map
    # 8 cols x 7 rows = 56 neighborhoods, spaced ~14x13 apart
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [8, 21, 34, 50, 63, 76, 91]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock
    def num_active():
        if pop < 20:    return 2
        if pop < 80:    return 6
        if pop < 200:   return 12
        if pop < 500:   return 20
        if pop < 1000:  return 30
        if pop < 2000:  return 42
        if pop < 4000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # Compute neighbor masks once
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 5)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: POWER PLANTS at each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CROSS at each active hood from plant ----
    spine_range = 7
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant to this hood
    px_best, py_best = hx, hy
    best_pd = 999
    for yr in range(max(0, hy - 9), min(WORLD_H, hy + 10)):
        for xr in range(max(0, hx - 9), min(WORLD_W, hx + 10)):
            if bool(pm[yr, xr]):
                d = abs(xr - hx) + abs(yr - hy)
                if d < best_pd:
                    best_pd = d
                    px_best, py_best = xr, yr

    # Wire vertical spine at plant x
    for dy in range(-spine_range, spine_range + 1):
        wy = py_best + dy
        if not ib(px_best, wy): continue
        if bool(wm[wy, px_best]) or bool(pm[wy, px_best]): continue
        if not bool(em[wy, px_best]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(px_best, ay) and (bool(wm[ay, px_best]) or bool(pm[ay, px_best])):
                return (Tool.WIRE, px_best, wy)

    # Wire horizontal spine at plant y
    for dx in range(-spine_range, spine_range + 1):
        wx = px_best + dx
        if not ib(wx, py_best): continue
        if bool(wm[py_best, wx]) or bool(pm[py_best, wx]): continue
        if not bool(em[py_best, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, py_best) and (bool(wm[py_best, ax]) or bool(pm[py_best, ax])):
                return (Tool.WIRE, wx, py_best)

    # ---- PHASE 3: WIRE MESH connecting adjacent hoods ----
    for (hx1, hy1) in active_hoods:
        # Connect right neighbor
        hx2, hy2 = hx1 + 14, hy1
        if (hx2, hy2) in active_hoods or any(abs(c - hx2) <= 1 and r == hy2 for c, r in active_hoods):
            for cx in range(hx1 + 1, min(hx1 + 14, WORLD_W)):
                if not ib(cx, hy1): continue
                if bool(wm[hy1, cx]) or bool(pm[hy1, cx]): continue
                if not bool(em[hy1, cx]): continue
                for adx in [-1, 1]:
                    ax = cx + adx
                    if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                        return (Tool.WIRE, cx, hy1)
        # Connect bottom neighbor
        hx3, hy3 = hx1, hy1 + 13
        if (hx3, hy3) in active_hoods or any(c == hx3 and abs(r - hy3) <= 1 for c, r in active_hoods):
            for cy in range(hy1 + 1, min(hy1 + 13, WORLD_H)):
                if not ib(hx1, cy): continue
                if bool(wm[cy, hx1]) or bool(pm[cy, hx1]): continue
                if not bool(em[cy, hx1]): continue
                for ady in [-1, 1]:
                    ay = cy + ady
                    if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                        return (Tool.WIRE, hx1, cy)

    # ---- PHASE 4: ROADS flanking wire spines ----
    # Road rows/cols: offset from wire spine by 1 tile
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Find plant near this hood
        px_r, py_r = hx, hy
        best_d2 = 999
        for yr in range(max(0, hy - 9), min(WORLD_H, hy + 10)):
            for xr in range(max(0, hx - 9), min(WORLD_W, hx + 10)):
                if bool(pm[yr, xr]):
                    d = abs(xr - hx) + abs(yr - hy)
                    if d < best_d2:
                        best_d2 = d
                        px_r, py_r = xr, yr
        # Roads flanking vertical wire
        for rx in [px_r - 1, px_r + 1]:
            if not ib(rx, py_r): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = py_r + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if ib(px_r, ry) and (bool(wm[ry, px_r]) or bool(pm[ry, px_r])):
                        return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal wire
        for ry2 in [py_r - 1, py_r + 1]:
            if not ib(px_r, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = px_r + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if ib(rcx, py_r) and (bool(wm[py_r, rcx]) or bool(pm[py_r, rcx])):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        if rr < 0.35:
            return Tool.RESIDENTIAL
        return Tool.COMMERCIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: closeness to active hood centers (dense packing)
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        # Also factor in existing zone density (prefer near existing zones)
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            zone_stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(zone_xs), zone_stride):
                d = np.abs(cxs - zone_xs[i]) + np.abs(cys - zone_ys[i])
                zone_dist = np.minimum(zone_dist, d)
            score = best_dist * 1.5 + zone_dist * 0.3
        else:
            score = best_dist.astype(float)

        order = np.argsort(score)
        offset = (step * 7 + pop // 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS toward powered empty areas ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % len(road_xs_arr)
        for off in range(min(len(road_xs_arr), 200)):
            k = (step_k + off * 7) % len(road_xs_arr)
            rx2, ry2 = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W, 22) for py2 in range(15, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150 and step % 3 == 0:
        park_ys_a, park_xs_a = np.where(em & near_road & near_power)
        if len(park_xs_a) > 0:
            idx = (step * 17) % len(park_xs_a)
            py2, px2 = int(park_ys_a[idx]), int(park_xs_a[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 700:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 50), (75, 50), (55, 35), (65, 65),
                    (20, 20), (100, 20), (20, 80), (100, 80)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10),
                    (60, 95), (60, 5), (30, 95), (90, 95), (30, 5), (90, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800 and step % 3 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (10, 50), (110, 50), (60, 10), (60, 90),
                         (45, 40), (75, 40), (45, 60), (75, 60)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3500:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94),
                    (6, 40), (6, 60), (106, 40), (106, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 7: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 8: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1:   shifted[:-1, :] = rm[1:, :]
        elif dy == 1:  shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- FALLBACK: new plant for uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for off in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + off * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at cardinal positions + cross wires + flanking roads."""
    actions = []
    # Central plant
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-5, 6):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, cx - 2, cy + dy))
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    # Second plant top-left
    actions.append((Tool.COALPOWER, 20, 20))
    for dx in range(-3, 4):
        actions.append((Tool.WIRE, 20 + dx, 20))
    for dy in range(-3, 4):
        actions.append((Tool.WIRE, 20, 20 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Dense neighborhood grid: 8 cols x 7 rows = 56 neighborhoods
    nh_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    nh_rows = [10, 22, 35, 48, 61, 74, 87]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 350:   return 10
        if pop < 700:   return 16
        if pop < 1200:  return 24
        if pop < 2000:  return 35
        if pop < 4000:  return 45
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- BUILD NEIGHBOR MASKS ----
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 2: WIRE SPINES from each plant to hood (round-robin) ----
    spine_range = 14
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
    y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0

        # Extend vertical wire from plant toward hood y
        if py_local != hy:
            sd = 1 if hy > py_local else -1
            for wy in range(py_local + sd, hy + sd, sd):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        # Extend horizontal wire from plant toward hood x
        if px_local != hx:
            sd = 1 if hx > px_local else -1
            for wx in range(px_local + sd, hx + sd, sd):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

        # Extend wire along vertical spine
        for dy in range(-spine_range, spine_range + 1):
            wy = py_local + dy
            if not ib(px_local, wy): continue
            if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
            if not bool(em[wy, px_local]): continue
            for adj in [-1, 1]:
                ay2 = wy + adj
                if ib(px_local, ay2) and (bool(wm[ay2, px_local]) or bool(pm[ay2, px_local])):
                    return (Tool.WIRE, px_local, wy)

        # Extend wire along horizontal spine
        for dx in range(-spine_range, spine_range + 1):
            wx = px_local + dx
            if not ib(wx, py_local): continue
            if bool(pm[py_local, wx]) or bool(wm[py_local, wx]): continue
            if not bool(em[py_local, wx]): continue
            for adj in [-1, 1]:
                ax2 = wx + adj
                if ib(ax2, py_local) and (bool(wm[py_local, ax2]) or bool(pm[py_local, ax2])):
                    return (Tool.WIRE, wx, py_local)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    # Connect neighboring hoods (same row or same col)
    hood_set = set(active_hoods)
    check_offset = step % max(len(active_hoods), 1)
    for ii in range(len(active_hoods)):
        hx1, hy1 = active_hoods[(check_offset + ii) % len(active_hoods)]
        # Check right neighbor
        for hx2, hy2 in active_hoods:
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 20:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax3 = cx2 + adx
                        if ib(ax3, hy1) and (bool(wm[hy1, ax3]) or bool(pm[hy1, ax3])):
                            return (Tool.WIRE, cx2, hy1)
            # Check bottom neighbor
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 20:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay3 = cy2 + ady
                        if ib(hx1, ay3) and (bool(wm[ay3, hx1]) or bool(pm[ay3, hx1])):
                            return (Tool.WIRE, hx1, cy2)
        break  # Only check one hood per step to avoid timeout

    # ---- PHASE 4: ROADS flanking wire spines ----
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    # Vertical flanking roads
    for rx in [hx3 - 2, hx3 + 2]:
        if not ib(rx, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                return (Tool.ROAD, rx, ry)

    # Horizontal flanking roads
    for ry2 in [hy3 - 2, hy3 + 2]:
        if not ib(hx3, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx3 + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND ROADS INTO POWERED AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        fstep = (step // 2) % max(len(fire_spots), 1)
        for i in range(len(fire_spots)):
            sx, sy = fire_spots[(fstep + i) % len(fire_spots)]
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W, 22) for py2 in range(15, WORLD_H, 22)]
        ps_step = (step // 3) % max(len(police_spots), 1)
        for i in range(len(police_spots)):
            sx, sy = police_spots[(ps_step + i) % len(police_spots)]
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(25, 25), (85, 25), (25, 75), (85, 75),
                         (55, 12), (55, 87), (8, 50), (112, 50),
                         (40, 50), (80, 50)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94),
                      (60, 5), (60, 94), (5, 50), (115, 50),
                      (30, 5), (90, 5), (30, 94), (90, 94)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaport_spots = [(6, 92), (114, 92), (6, 8), (114, 8), (60, 96), (60, 4)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airport_spots = [(42, 5), (78, 5), (42, 93), (78, 93), (5, 42), (5, 72), (115, 42)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 120 and step % 3 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place plant near uncovered hood ----
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx5 + dx, hy5 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants arranged in a cross pattern with wire connections."""
    actions = []
    # 4 power plants at strategic positions
    plants = [(30, 20), (90, 20), (30, 75), (90, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from each plant
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
    # Horizontal wire spine connecting plants at y=20 and y=75
    for cx in range(30, 91):
        actions.append((Tool.WIRE, cx, 20))
        actions.append((Tool.WIRE, cx, 75))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target ratio: 45% res, 35% com, 20% ind
    def pick_tool():
        r_ratio = res_count / total_zones
        c_ratio = com_count / total_zones
        i_ratio = ind_count / total_zones
        if i_ratio < 0.20:
            return Tool.INDUSTRIAL
        if c_ratio < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhoods: 6 clusters in a 2x3 grid layout
    # Each neighborhood has center, wire column, left/right road columns
    neighborhoods = [
        (30, 20),  (90, 20),   # top row
        (30, 50),  (90, 50),   # middle row
        (30, 75),  (90, 75),   # bottom row
    ]

    def num_active():
        if pop < 50:   return 1
        if pop < 200:  return 2
        if pop < 400:  return 3
        if pop < 600:  return 4
        if pop < 900:  return 5
        return 6

    n_active = num_active()
    active_neighborhoods = neighborhoods[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_neighborhoods:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty tile to place plant
        for r in range(0, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE GRID: vertical spines ----
    spine_half = min(25, 8 + pop // 8)
    for (px, py) in active_neighborhoods:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check vertical wire at px
        wire_col = [r for r in range(spine_top, spine_bot + 1)
                    if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not wire_col:
            for dy in range(-3, 4):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            max_wr = max(wire_col)
            min_wr = min(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting pairs at same y ----
    y_levels = sorted(set(py for (_, py) in active_neighborhoods))
    for yl in y_levels:
        row_nbrs = sorted([(px, py) for (px, py) in active_neighborhoods if py == yl], key=lambda a: a[0])
        for i in range(len(row_nbrs) - 1):
            x1 = row_nbrs[i][0]
            x2 = row_nbrs[i + 1][0]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting same-column neighborhoods ----
    x_cols = sorted(set(px for (px, _) in active_neighborhoods))
    for xc in x_cols:
        col_nbrs = sorted([(px, py) for (px, py) in active_neighborhoods if px == xc], key=lambda a: a[1])
        for i in range(len(col_nbrs) - 1):
            y1 = col_nbrs[i][1]
            y2 = col_nbrs[i + 1][1]
            for cy in range(y1 + 1, y2):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # ---- ROAD GRID around each neighborhood ----
    # Build roads flanking wire spines (left and right of wire)
    for idx, (px, py) in enumerate(active_neighborhoods):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_col = [r for r in range(spine_top, spine_bot + 1)
                    if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not wire_col:
            continue
        cycle = (step + idx * 5) % 2
        for wr in wire_col[cycle::2]:
            for road_x in [px - 1, px + 1, px - 2, px + 2]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- HORIZONTAL ROADS at y-levels ----
    if pop > 10:
        for yl in y_levels:
            row_nbrs = sorted([(px, py) for (px, py) in active_neighborhoods if py == yl], key=lambda a: a[0])
            if len(row_nbrs) < 2:
                continue
            x_left = row_nbrs[0][0] - 4
            x_right = row_nbrs[-1][0] + 4
            for horiz_y in [yl - 3, yl + 3, yl - 6, yl + 6]:
                if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                    continue
                for cx in range(x_left, x_right + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting rows ----
    if pop > 40:
        for xc in x_cols:
            for road_x in [xc - 3, xc + 3]:
                if not ib(road_x, 0):
                    continue
                col_nbrs = sorted([(px, py) for (px, py) in active_neighborhoods if px == xc], key=lambda a: a[1])
                for i in range(len(col_nbrs) - 1):
                    y1 = col_nbrs[i][1]
                    y2 = col_nbrs[i + 1][1]
                    for cy in range(y1, y2 + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_neighborhoods:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.9
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (close-loop: only when pop warrants) ----
    if pop > 50:
        fire_spots = [
            (10, 10), (60, 10), (110, 10),
            (10, 35), (60, 35), (110, 35),
            (10, 60), (60, 60), (110, 60),
            (10, 88), (60, 88), (110, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (15, 15), (55, 15), (95, 15),
            (15, 55), (55, 55), (95, 55),
            (15, 85), (55, 85), (95, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadium_spots = [
            (15, 40), (105, 40),
            (15, 60), (105, 60),
            (60, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 95), (115, 95), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

