def act(obs, state):
    """
    Highly reactive closed-loop policy.
    Strategy: Build a grid city with multiple power plants,
    vertical wire spines, horizontal road arteries, and dense zone placement.
    Adapts based on current map state.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm)) // 9
    com_count = int(np.sum(comm)) // 9
    ind_count = int(np.sum(indm)) // 9
    total_zones = max(res_count + com_count + ind_count, 1)
    pop = obs.city_pop

    # --- Phase management ---
    if 'phase' not in state:
        state['phase'] = 0
        state['plant_cols'] = [60, 80, 40]
        state['spine_cols'] = [62, 82, 42]
        state['road_offsets'] = [(-1, 1), (-1, 1), (-1, 1)]
        state['spine_top'] = 30
        state['spine_bot'] = 70
        state['next_plant_idx'] = 1

    # Update spine extent based on population
    state['spine_top'] = max(5, 50 - 10 - min(20, pop // 50))
    state['spine_bot'] = min(94, 50 + 10 + min(20, pop // 50))

    # --- Tool selection based on zone ratios ---
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # =========================================================
    # PRIORITY 1: Ensure at least one power plant exists
    # =========================================================
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        return (Tool.COALPOWER, 60, 50)

    # =========================================================
    # PRIORITY 2: Add more power plants as city grows
    # =========================================================
    plant_positions = [(int(plant_xs[i]), int(plant_ys[i])) for i in range(len(plant_xs))]

    def need_more_power():
        # Add plant if zones outnumber powered coverage
        n_plants = len(set((px//3, py//3) for px, py in plant_positions))
        return (total_zones > n_plants * 15) or (pop > n_plants * 500)

    if need_more_power():
        # Try to place additional plants at predefined locations
        candidate_plants = [
            (60, 30), (80, 30), (40, 30),
            (60, 70), (80, 70), (40, 70),
            (100, 50), (20, 50),
            (100, 30), (20, 30), (100, 70), (20, 70),
        ]
        for cpx, cpy in candidate_plants:
            # Check if no plant nearby
            nearby = False
            for ppx, ppy in plant_positions:
                if abs(ppx - cpx) < 12 and abs(ppy - cpy) < 12:
                    nearby = True
                    break
            if not nearby and in_bounds(cpx, cpy) and bool(em[cpy, cpx]):
                return (Tool.COALPOWER, cpx, cpy)

    # =========================================================
    # PRIORITY 3: Build wire spines extending from each plant
    # =========================================================
    # Compute nearby-wire mask
    wire_or_plant = wm | pm

    def nearest_wire_col_for_plant(ppx, ppy):
        # Wire spine is 2 tiles right of plant center
        return ppx + 2

    # For each plant, ensure vertical wire spine exists
    for ppx, ppy in plant_positions:
        wc = nearest_wire_col_for_plant(ppx, ppy)
        if not in_bounds(wc, ppy):
            continue
        # Check wire connectivity near plant
        wire_in_col = [r for r in range(WORLD_H) if in_bounds(wc, r) and bool(wm[r, wc])]
        top = state['spine_top']
        bot = state['spine_bot']

        if not wire_in_col:
            # Seed wire adjacent to plant
            for dy in range(-2, 3):
                ny = ppy + dy
                if in_bounds(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and bool(em[nr, wc]) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and bool(em[nr, wc]) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # =========================================================
    # PRIORITY 4: Connect plants with horizontal wire bridges
    # =========================================================
    if len(plant_positions) >= 2:
        # Connect all plants at their wire spine rows
        for i in range(len(plant_positions) - 1):
            p1x, p1y = plant_positions[i]
            p2x, p2y = plant_positions[i + 1]
            wc1 = p1x + 2
            wc2 = p2x + 2
            bridge_y = (p1y + p2y) // 2
            # Find a row where both spines have wire
            wc1_rows = [r for r in range(WORLD_H) if in_bounds(wc1, r) and bool(wm[r, wc1])]
            wc2_rows = [r for r in range(WORLD_H) if in_bounds(wc2, r) and bool(wm[r, wc2])]
            common = set(wc1_rows) & set(wc2_rows)
            if common:
                bridge_y = min(common)
            # Lay horizontal wire between the two spine columns
            x_start = min(wc1, wc2) + 1
            x_end = max(wc1, wc2)
            for bx in range(x_start, x_end):
                if in_bounds(bx, bridge_y) and bool(em[bridge_y, bx]) and not bool(pm[bridge_y, bx]):
                    return (Tool.WIRE, bx, bridge_y)

    # =========================================================
    # PRIORITY 5: Road columns flanking each wire spine
    # =========================================================
    all_wire_rows = {}
    for ppx, ppy in plant_positions:
        wc = ppx + 2
        rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and bool(wm[r, wc])]
        if rows:
            all_wire_rows[wc] = rows

    for wc, wire_rows in all_wire_rows.items():
        rcl = wc - 1
        rcr = wc + 1
        # Check every other row for road gaps
        step_mod = obs.step % 4
        for wr in wire_rows[step_mod::4]:
            if in_bounds(rcl, wr) and bool(em[wr, rcl]) and not bool(pm[wr, rcl]):
                return (Tool.ROAD, rcl, wr)
            if in_bounds(rcr, wr) and bool(em[wr, rcr]) and not bool(pm[wr, rcr]):
                return (Tool.ROAD, rcr, wr)

    # =========================================================
    # PRIORITY 6: Horizontal road arteries connecting spines
    # =========================================================
    # Every 6 rows, lay horizontal roads between spine road columns
    if all_wire_rows:
        wire_cols_sorted = sorted(all_wire_rows.keys())
        # Determine horizontal road rows
        top = state['spine_top']
        bot = state['spine_bot']
        road_rows = list(range(top, bot + 1, 6))

        for rr in road_rows:
            if not (0 <= rr < WORLD_H):
                continue
            # Connect leftmost to rightmost spine road column
            if len(wire_cols_sorted) >= 2:
                xl = wire_cols_sorted[0] - 1
                xr = wire_cols_sorted[-1] + 1
                for x in range(xl, xr + 1):
                    if in_bounds(x, rr) and bool(em[rr, x]) and not bool(pm[rr, x]):
                        return (Tool.ROAD, x, rr)

    # =========================================================
    # PRIORITY 7: Zone placement near roads and power
    # =========================================================
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance from center of all plants
        if plant_positions:
            cx_avg = np.mean([ppx for ppx, _ in plant_positions])
            cy_avg = np.mean([ppy for _, ppy in plant_positions])
        else:
            cx_avg, cy_avg = 60, 50
        dists = np.abs(cxs - cx_avg) + np.abs(cys - cy_avg) * 0.5
        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # =========================================================
    # PRIORITY 8: Extend roads near wire
    # =========================================================
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # =========================================================
    # PRIORITY 9: Civic services
    # =========================================================
    if pop > 200:
        service_spots = [
            (Tool.FIRESTATION, 50, 40), (Tool.FIRESTATION, 70, 40),
            (Tool.FIRESTATION, 50, 60), (Tool.FIRESTATION, 70, 60),
            (Tool.FIRESTATION, 90, 50), (Tool.FIRESTATION, 30, 50),
        ]
        for tool, sx, sy in service_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                # Check not recently placed by checking surroundings
                near = False
                for dy in range(-5, 6):
                    for dx in range(-5, 6):
                        if in_bounds(sx+dx, sy+dy) and bool(pm[sy+dy, sx+dx]):
                            near = True
                            break
                if not near:
                    return (tool, sx, sy)

    if pop > 500:
        police_spots = [
            (Tool.POLICESTATION, 55, 45), (Tool.POLICESTATION, 75, 45),
            (Tool.POLICESTATION, 55, 55), (Tool.POLICESTATION, 75, 55),
        ]
        for tool, sx, sy in police_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (tool, sx, sy)

    if pop > 1000:
        stadium_spots = [(Tool.STADIUM, 50, 50), (Tool.STADIUM, 90, 50)]
        for tool, sx, sy in stadium_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (tool, sx, sy)

    # =========================================================
    # FALLBACK: Extend wire laterally
    # =========================================================
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in cardinal positions with wire spines and roads."""
    actions = []
    # Place coal plants at 4 strategic positions
    plants = [(30, 20), (90, 20), (30, 80), (90, 80)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertically
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    # Center plant
    actions.append((Tool.COALPOWER, 60, 50))
    for dy in range(-6, 7):
        actions.append((Tool.WIRE, 60, 50 + dy))
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Define a denser grid of neighborhoods covering the whole map
    # 5 columns x 5 rows = 25 possible neighborhoods
    col_xs = [15, 35, 60, 85, 105]
    row_ys = [15, 30, 50, 70, 85]
    all_anchors = [(cx, cy) for cx in col_xs for cy in row_ys]

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 5
        if pop < 300:   return 8
        if pop < 500:   return 12
        if pop < 750:   return 16
        if pop < 1000:  return 20
        if pop < 2000:  return 25
        return 25

    n_active = min(num_active(), len(all_anchors))
    # Spread active anchors
    step_size = len(all_anchors) / n_active
    active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS ----
    # Each active anchor needs a plant nearby
    for (px, py) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find empty spot near anchor
        for r in range(1, 14):
            found = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if found:
                break

    # ---- WIRE SPINE (vertical through each anchor) ----
    spine_half = min(40, 8 + pop // 8)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy2 in range(-6, 7):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anch = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anch) - 1):
            wx1 = row_anch[i][0]
            wx2 = row_anch[i + 1][0]
            for cx in range(wx1 + 1, wx2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor columns ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xc in x_cols:
        col_anch = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
        for i in range(len(col_anch) - 1):
            wy1 = col_anch[i][1]
            wy2 = col_anch[i + 1][1]
            for cy in range(wy1 + 1, wy2):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 3
        rl = px - 1
        rr = px + 1
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS connecting neighborhoods ----
    for yl in y_levels:
        row_anch = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        if len(row_anch) < 2:
            continue
        xl1 = row_anch[0][0] - 1
        xl2 = row_anch[-1][0] + 1
        for horiz_y in [yl - 4, yl + 4]:
            if not ib(xl1, horiz_y) or not ib(xl2, horiz_y):
                continue
            for cx in range(xl1, xl2 + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting row levels in each column ----
    if pop > 40:
        for xc in x_cols:
            road_x = xc - 3 if (xc % 2 == 0) else xc + 3
            col_anch = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
            for i in range(len(col_anch) - 1):
                y1 = col_anch[i][1]
                y2 = col_anch[i + 1][1]
                for cy in range(y1, y2 + 1):
                    if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [
            (8, 10), (30, 10), (55, 10), (80, 10), (105, 10),
            (8, 35), (30, 35), (55, 35), (80, 35), (105, 35),
            (8, 55), (30, 55), (55, 55), (80, 55), (105, 55),
            (8, 75), (30, 75), (55, 75), (80, 75), (105, 75),
            (8, 92), (30, 92), (55, 92), (80, 92), (105, 92),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 8), (45, 8), (75, 8), (105, 8),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (12, 20), (60, 20), (108, 20),
            (12, 50), (60, 50), (108, 50),
            (12, 80), (60, 80), (108, 80),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94), (30, 6), (90, 6)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Closed-loop reactive city builder
# Strategy: Expand from power plants outward using wire/road spines,
# then densely zone all powered+roaded areas. React to actual map state.

def init(obs, state):
    """Bootstrap: 3 coal plants + initial wire/road cross."""
    actions = []
    # Center plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines from center
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, 60 + dx, 50))
    # Road parallel to horizontal wire
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, 60 + dx, 51))
    # Left plant
    actions.append((Tool.COALPOWER, 20, 50))
    for dx in range(-3, 4):
        if dx != 0:
            actions.append((Tool.WIRE, 20 + dx, 50))
    # Right plant  
    actions.append((Tool.COALPOWER, 100, 50))
    for dx in range(-3, 4):
        if dx != 0:
            actions.append((Tool.WIRE, 100 + dx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))
    plant_count = int(np.sum(pm))

    # ---- PHASE TRACKING ----
    if 'phase' not in state:
        state['phase'] = 'power'
    if 'last_pop' not in state:
        state['last_pop'] = 0
    if 'expand_idx' not in state:
        state['expand_idx'] = 0

    # ---- GRID OF NEIGHBORHOOD CENTERS (12x10 grid = 120 hoods) ----
    # Tighter spacing for denser city
    nh_xs = list(range(8, WORLD_W - 4, 10))   # ~11 cols
    nh_ys = list(range(8, WORLD_H - 4, 10))   # ~9 rows
    all_hoods = [(x, y) for y in nh_ys for x in nh_xs]

    # Power plant targets: every ~25 tiles
    plant_targets = [(x, y) for y in range(15, WORLD_H - 10, 25)
                     for x in range(15, WORLD_W - 10, 25)]

    # ---- HELPER: nearest empty cell to (cx, cy) within radius ----
    def find_empty_near(cx, cy, radius=8):
        for r in range(1, radius + 1):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (nx, ny)
        return None

    # ---- ENSURE ADEQUATE POWER PLANTS ----
    # Need 1 plant per ~15 zones to keep powered_zones high
    needed_plants = max(3, total_zones // 15 + 2)
    if plant_count < needed_plants:
        # Find uncovered plant target
        for (px, py) in plant_targets:
            x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
            y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                loc = find_empty_near(px, py, 6)
                if loc:
                    return (Tool.COALPOWER, loc[0], loc[1])

    # ---- BUILD POWER PROXIMITY MAP ----
    # Expand from wires+plants using shift operations
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    # ---- DETECT UNPOWERED AREAS NEAR PLANTS ----
    # Extend wire from power sources toward uncovered neighborhoods
    # Find hoods that lack power
    unpowered_hoods = [(hx, hy) for (hx, hy) in all_hoods
                       if ib(hx, hy) and not bool(nbr_power[hy, hx])]

    if unpowered_hoods and wire_count < 2000:
        # Pick the hood closest to an existing power source
        power_ys, power_xs = np.where(power_src)
        if len(power_xs) > 0:
            # Find closest unpowered hood to any power source
            best_hood = None
            best_dist = 999999
            for (hx, hy) in unpowered_hoods[:20]:
                dists = np.abs(power_xs - hx) + np.abs(power_ys - hy)
                d = int(np.min(dists))
                if d < best_dist:
                    best_dist = d
                    best_hood = (hx, hy)

            if best_hood and best_dist < 40:
                hx, hy = best_hood
                # Find closest power source tile to this hood
                dists = np.abs(power_xs - hx) + np.abs(power_ys - hy)
                k = int(np.argmin(dists))
                src_x, src_y = int(power_xs[k]), int(power_ys[k])

                # Step wire toward the hood from source
                dx = hx - src_x
                dy = hy - src_y
                # Find wire frontier (tile adjacent to power, closest to hood)
                wire_frontier = []
                for i in range(len(power_xs)):
                    wx, wy = int(power_xs[i]), int(power_ys[i])
                    for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nx, ny = wx+ddx, wy+ddy
                        if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                            dist_to_hood = abs(nx - hx) + abs(ny - hy)
                            wire_frontier.append((dist_to_hood, nx, ny))

                if wire_frontier:
                    wire_frontier.sort()
                    _, wx, wy = wire_frontier[0]
                    return (Tool.WIRE, wx, wy)

    # ---- EXTEND WIRE ALONG HORIZONTAL SPINES ----
    # For each active plant row, extend wire horizontally
    plant_ys_arr, plant_xs_arr = np.where(pm)
    if len(plant_xs_arr) > 0:
        # Build horizontal wire spines at plant y-coords
        plant_row_ys = list(set(int(y) for y in plant_ys_arr))
        spine_y = plant_row_ys[step % len(plant_row_ys)]

        # Extend wire along this row
        wire_row = wm[spine_y, :]
        power_row = pm[spine_y, :]
        combined = wire_row | power_row

        # Find leftmost gap in combined that is adjacent to existing
        for direction in [1, -1]:
            if direction == 1:
                xs_range = range(1, WORLD_W - 1)
            else:
                xs_range = range(WORLD_W - 2, 0, -1)
            for wx in xs_range:
                if bool(em[spine_y, wx]) and not bool(pm[spine_y, wx]):
                    # Check adjacency to wire/plant on this row
                    adj = (wx > 0 and bool(combined[wx-1])) or \
                          (wx < WORLD_W-1 and bool(combined[wx+1]))
                    if adj and not bool(combined[wx]):
                        # Only extend if within map bounds and not too far from a plant
                        plant_dists = np.abs(plant_xs_arr - wx)
                        if int(np.min(plant_dists)) < 55:
                            return (Tool.WIRE, wx, spine_y)

    # ---- ROADS: build grid of horizontal+vertical roads ----
    # Horizontal roads at each hood row +1
    active_road_rows = list(set(hy + 1 for _, hy in all_hoods if ib(0, hy + 1)))
    active_road_cols = list(set(hx + 1 for hx, _ in all_hoods if ib(hx + 1, 0)))

    # Current road density
    frac_done = step / max(n_steps, 1)

    # Extend horizontal roads in powered areas
    r_row_idx = step % len(active_road_rows)
    ry = active_road_rows[r_row_idx]
    if ib(0, ry):
        for rx in range(1, WORLD_W - 1):
            if bool(em[ry, rx]) and not bool(pm[ry, rx]) and not bool(rm[ry, rx]):
                # Extend if adjacent road or wire at spine
                adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                           (rx < WORLD_W-1 and bool(rm[ry, rx+1]))
                # Also start if nbr_power at this location
                if adj_road and bool(nbr_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Extend vertical roads
    r_col_idx = (step + 17) % len(active_road_cols)
    rcx = active_road_cols[r_col_idx]
    if ib(rcx, 0):
        for rcy in range(1, WORLD_H - 1):
            if bool(em[rcy, rcx]) and not bool(pm[rcy, rcx]) and not bool(rm[rcy, rcx]):
                adj_road = (rcy > 0 and bool(rm[rcy-1, rcx])) or \
                           (rcy < WORLD_H-1 and bool(rm[rcy+1, rcx]))
                if adj_road and bool(nbr_power[rcy, rcx]):
                    return (Tool.ROAD, rcx, rcy)

    # ---- ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% res, 30% com, 30% ind
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer tiles near hood centers and far from existing zones
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in all_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Also penalize being too close to existing zones (spread out)
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            zone_density = np.zeros(len(cxs))
            for i in range(min(len(cxs), 500)):
                near = np.sum((np.abs(zone_xs - cxs[i]) + np.abs(zone_ys - cys[i])) < 6)
                zone_density[i] = near

        order = np.argsort(best_dist)
        offset = (step * 7 + total_zones * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- REACTIVE ROAD EXTENSION FROM EXISTING NETWORK ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for ddx, ddy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+ddx, ry2+ddy
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 150:
        fire_grid = [(x, y) for y in range(15, WORLD_H, 18) for x in range(15, WORLD_W, 18)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_grid = [(x, y) for y in range(20, WORLD_H, 22) for x in range(20, WORLD_W, 22)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 50), (15, 50), (105, 50), (60, 15), (60, 85)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(45, 5), (75, 5), (45, 94), (75, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 300 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23 + pop) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            return (Tool.PARK, px2, py2)

    # ---- EXTEND WIRE from existing network ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13 + pop) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+ddx, wy2+ddy
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new plant in uncovered area ----
    for (hx, hy) in all_hoods:
        if not bool(nbr_power[hy, hx]):
            loc = find_empty_near(hx, hy, 8)
            if loc:
                return (Tool.COALPOWER, loc[0], loc[1])

    return None

# Ambitious city builder - denser grid, more neighborhoods, better power coverage
# Strategy: central spine with nuclear power, dense grid layout, balanced zones

def init(obs, state):
