    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dilate helper (vectorized)
    def dilate(mask, r):
        result = mask.astype(bool).copy()
        for d in range(1, r + 1):
            result[d:, :]  |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:]  |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # ---- INFRASTRUCTURE GRID ----
    # Wire corridors: horizontal at y=10,25,40,55,70,85 vertical at x=15,30,45,60,75,90,105
    wire_rows = [10, 25, 40, 55, 70, 85]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    # Road corridors: offset ±2 from wire rows, offset ±1 from wire cols
    road_row_offsets = [-2, 2]
    road_col_offsets = [-1, 1]

    # Plant locations: at intersections of wire_rows x wire_cols for dense coverage
    # But only activate progressively based on pop
    all_plants = [
        (30, 25), (90, 25), (30, 75), (90, 75),  # primary 4
        (60, 10), (60, 40), (60, 70), (60, 90),   # central column
        (15, 55), (105, 55), (15, 10), (105, 10), # edges
        (45, 40), (75, 40), (45, 70), (75, 70),   # inner grid
    ]

    def num_plant_targets():
        if pop < 100:   return 4
        if pop < 300:   return 6
        if pop < 600:   return 8
        if pop < 1000:  return 10
        if pop < 1500:  return 12
        return 16

    active_plants = all_plants[:num_plant_targets()]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (px, py) in active_plants:
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(1, 10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE NETWORK (reactive: extend from existing wire/plant) ----
    phase = step % 6

    if phase == 0:
        # Extend horizontal wire corridors left-to-right
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            row = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if bool(row[wx]):
                    continue
                # Check left or right neighbor has wire/plant
                left_ok = wx > 0 and bool(row[wx - 1])
                right_ok = wx < WORLD_W - 1 and bool(row[wx + 1])
                if (left_ok or right_ok) and bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors top-to-bottom
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            col = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if bool(col[wy]):
                    continue
                up_ok = wy > 0 and bool(col[wy - 1])
                dn_ok = wy < WORLD_H - 1 and bool(col[wy + 1])
                if (up_ok or dn_ok) and bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Connect plant clusters to nearest wire corridor by bridging gap
        for (px, py) in active_plants:
            # Find nearest wire row
            best_wr = min(wire_rows, key=lambda r: abs(r - py))
            if abs(best_wr - py) > 1:
                # Walk from plant y toward wire row
                step_y = 1 if best_wr > py else -1
                for ty in range(py + step_y, best_wr + step_y, step_y):
                    if ib(px, ty) and bool(em[ty, px]) and not bool(pm[ty, px]):
                        return (Tool.WIRE, px, ty)
            # Find nearest wire col
            best_wc = min(wire_cols, key=lambda c: abs(c - px))
            if abs(best_wc - px) > 1:
                step_x = 1 if best_wc > px else -1
                for tx in range(px + step_x, best_wc + step_x, step_x):
                    if ib(tx, py) and bool(em[py, tx]) and not bool(pm[py, tx]):
                        return (Tool.WIRE, tx, py)

    elif phase == 3:
        # Roads parallel to wire rows
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in road_row_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads parallel to wire cols
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in road_col_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    else:
        # Cross streets between wire columns every ~6 tiles
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            for mid_x in range(c1 + 6, c2, 6):
                if not ib(mid_x, 0):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                        # extend if adjacent to existing road
                        adj = any(ib(mid_x, ry + dy2) and bool(rm[ry + dy2, mid_x]) for dy2 in [-1, 1])
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & near_road & near_power
    # Keep border margin
    cand_mask[:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, :3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Don't zone on wire corridors themselves
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_plants:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES (reactive: only if space exists) ----
    if pop > 60:
        fire_spots = [
            (10, 10), (60, 10), (110, 10),
            (10, 35), (35, 35), (85, 35), (110, 35),
            (10, 55), (35, 55), (85, 55), (110, 55),
            (10, 80), (60, 80), (110, 80),
            (35, 92), (85, 92),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (22, 18), (60, 18), (98, 18),
            (22, 50), (60, 50), (98, 50),
            (22, 82), (60, 82), (98, 82),
            (40, 34), (80, 34), (40, 66), (80, 66),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (45, 10), (75, 10), (10, 50), (110, 50),
            (45, 90), (75, 90), (45, 50), (75, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (30, 50), (90, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (50, 94), (5, 45), (115, 45)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PARKS: boost land value reactively ----
    if pop > 150 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend roads from existing near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset2 in range(min(len(road_xs2), 100)):
            k = (step_k + offset2 * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % max(len(wire_xs3), 1)
        for offset3 in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset3 * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place road near unpowered zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

