def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 cluster centers (plant positions)
    all_centers = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]
    # Additional expansion centers between main clusters
    expansion_centers = [
        (40, 10), (80, 10),
        (10, 35), (40, 35), (80, 35), (110, 35),
        (10, 50), (110, 50),
        (10, 65), (40, 65), (80, 65), (110, 65),
        (40, 90), (80, 90),
    ]

    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 6
        if pop < 1000:  return 9
        return 9

    n_active = num_active()
    active_centers = all_centers[:n_active]

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Wire corridors
    wire_rows = [20, 50, 80]
    wire_cols = [20, 60, 100]
    extra_wire_rows = [35, 65]
    extra_wire_cols = [40, 80]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (px, py) in active_centers:
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE INFRASTRUCTURE ----
    phase = step % 12

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left_has = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right_has = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left_has or right_has) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up_has = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn_has = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up_has or dn_has) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Extra horizontal wires between main corridors
        for wr in extra_wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if np.any(row_wire):
                for wx in range(1, WORLD_W - 1):
                    if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                        left_has = wx > 0 and bool(row_wire[wx-1])
                        right_has = wx < WORLD_W-1 and bool(row_wire[wx+1])
                        if (left_has or right_has) and bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)
            else:
                # Seed from vertical wires
                for wc in wire_cols:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)

    elif phase == 5:
        # Extra vertical wires
        for wc in extra_wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if np.any(col_wire):
                for wy in range(1, WORLD_H - 1):
                    if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                        up_has = wy > 0 and bool(col_wire[wy-1])
                        dn_has = wy < WORLD_H-1 and bool(col_wire[wy+1])
                        if (up_has or dn_has) and bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)
            else:
                for wr in wire_rows:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)

    elif phase == 6:
        # Extra roads along extra wire rows
        for wr in extra_wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 7:
        # Extra roads along extra wire cols
        for wc in extra_wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 8:
        # Cross-connect wires between rows
        mid_x = 60
        col_wire = wm[:, mid_x] | pm[:, mid_x]
        for wy in range(1, WORLD_H - 1):
            if not bool(col_wire[wy]):
                up_has = wy > 0 and bool(col_wire[wy-1])
                dn_has = wy < WORLD_H-1 and bool(col_wire[wy+1])
                if (up_has or dn_has) and bool(em[wy, mid_x]):
                    return (Tool.WIRE, mid_x, wy)

    elif phase == 9:
        # Cross-connect wires between cols
        mid_y = 50
        row_wire = wm[mid_y, :] | pm[mid_y, :]
        for wx in range(1, WORLD_W - 1):
            if not bool(row_wire[wx]):
                left_has = wx > 0 and bool(row_wire[wx-1])
                right_has = wx < WORLD_W-1 and bool(row_wire[wx+1])
                if (left_has or right_has) and bool(em[mid_y, wx]):
                    return (Tool.WIRE, wx, mid_y)

    elif phase == 10:
        # Extend road network from existing roads near power
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % max(len(road_xs2), 1)
            for offset in range(min(len(road_xs2), 150)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 11:
        # Additional cross roads to connect neighborhoods
        all_wire_rows = wire_rows + extra_wire_rows
        for wr in all_wire_rows:
            for extra_y in [wr - 5, wr + 5]:
                if not (2 < extra_y < WORLD_H - 2):
                    continue
                row_wire = wm[wr, :] | pm[wr, :]
                for rx in range(2, WORLD_W - 2):
                    if bool(row_wire[rx]) and bool(em[extra_y, rx]) and not bool(pm[extra_y, rx]):
                        return (Tool.ROAD, rx, extra_y)

    # ---- ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Don't place zones on wire corridors
    for wr in wire_rows + extra_wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols + extra_wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by distance to nearest active center + slight spread
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Also factor in road proximity
        road_ys_arr, road_xs_arr = np.where(rm)
        if len(road_xs_arr) > 0:
            rd_stride = max(1, len(road_xs_arr) // 80)
            road_dist = np.full(len(cxs2), 999999.0)
            for i in range(0, len(road_xs_arr), rd_stride):
                d = np.abs(cxs2 - road_xs_arr[i]).astype(float) + np.abs(cys2 - road_ys_arr[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
            score = best_dist * 0.3 + road_dist * 0.7
        else:
            score = best_dist

        order = np.argsort(score)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (10, 10), (40, 10), (70, 10), (100, 10),
            (10, 30), (40, 30), (70, 30), (100, 30),
            (10, 50), (40, 50), (70, 50), (100, 50),
            (10, 70), (40, 70), (70, 70), (100, 70),
            (10, 90), (40, 90), (70, 90), (100, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (25, 15), (55, 15), (85, 15), (115, 15),
            (25, 40), (55, 40), (85, 40), (115, 40),
            (25, 60), (55, 60), (85, 60), (115, 60),
            (25, 85), (55, 85), (85, 85), (115, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (30, 8), (90, 8), (10, 45), (110, 45),
            (30, 92), (90, 92), (10, 70), (110, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (5, 50), (115, 50), (60, 5), (60, 94),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [
            (5, 90), (115, 90), (5, 10), (115, 10),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [
            (50, 5), (50, 94), (5, 45), (115, 45),
        ]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PARKS to boost land value ----
    if pop > 300 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: connect unpowered zones ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        for (hx, hy) in active_centers:
            if not bool(near_power[hy, hx]):
                dists = np.abs(wire_xs_arr - hx) + np.abs(wire_ys_arr - hy)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                dx = 0 if hx == bwx else (1 if hx > bwx else -1)
                dy = 0 if hy == bwy else (1 if hy > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % max(len(wire_xs3), 1)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power grid with wire+road spines covering the map."""
    actions = []
    # Three power plants along a central horizontal band
    plants = [(20, 50), (60, 50), (100, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-6, 7):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking the wire
        for dx in range(-6, 7):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # More aggressive zone mix: 40% RES, 35% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense 5x6 grid of neighborhoods across the full map
    anchor_xs = [12, 30, 48, 66, 84, 102, 116]
    anchor_ys = [12, 27, 42, 57, 72, 87]

    all_anchors = []
    for ay in anchor_ys:
        for ax in anchor_xs:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 300:   return 14
        if pop < 600:   return 20
        if pop < 1000:  return 28
        if pop < 2000:  return 35
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 10); y1 = min(WORLD_H, ay + 11)
        x0 = max(0, ax - 10); x1 = min(WORLD_W, ax + 11)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(0, 12):
                found = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if found:
                    break

    # ---- HORIZONTAL WIRE SPINE ----
    wire_half = min(20, 6 + pop // 10)
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            for dx in range(-3, 4):
                nx = ax + dx
                if ib(nx, ay) and bool(em[ay, nx]) and not bool(pm[ay, nx]):
                    return (Tool.WIRE, nx, ay)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, ay) and (bool(em[ay, nc]) or bool(wm[ay, nc])) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, ay) and (bool(em[ay, nc]) or bool(wm[ay, nc])) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)

    # ---- VERTICAL WIRE SPINE ----
    vert_half = min(14, 5 + pop // 15)
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            for dy in range(-3, 4):
                ny = ay + dy
                if ib(ax, ny) and bool(em[ny, ax]) and not bool(pm[ny, ax]):
                    return (Tool.WIRE, ax, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(ax, nr) and (bool(em[nr, ax]) or bool(wm[nr, ax])) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(ax, nr) and (bool(em[nr, ax]) or bool(wm[nr, ax])) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)

    # ---- INTER-ANCHOR WIRE: connect anchors vertically ----
    if n_active >= 2:
        xs_set = sorted(set(ax for (ax, ay) in active_anchors))
        for col_x in xs_set:
            col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1 = col_anchors[i]
                _, y2 = col_anchors[i + 1]
                for cy in range(y1 + 1, y2):
                    if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                        return (Tool.WIRE, col_x, cy)

    # ---- INTER-ANCHOR WIRE: connect anchors horizontally ----
    if n_active >= 2:
        ys_set = sorted(set(ay for (ax, ay) in active_anchors))
        for row_y in ys_set:
            row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
            for i in range(len(row_anchors) - 1):
                x1, _ = row_anchors[i]
                x2, _ = row_anchors[i + 1]
                for cx in range(x1 + 1, x2):
                    if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING along wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            continue
        cycle = (step + idx * 7) % 3
        for wc in wire_in_row[cycle::3]:
            for road_y in [ay - 2, ay + 2]:
                if ib(wc, road_y) and bool(em[road_y, wc]) and not bool(pm[road_y, wc]):
                    return (Tool.ROAD, wc, road_y)

    # ---- VERTICAL ROADS flanking vertical wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 5) % 3
        for wr in wire_in_col[cycle::3]:
            for road_x in [ax - 2, ax + 2]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- HORIZONTAL CROSS ROADS between row anchors ----
    if pop > 5:
        ys_set = sorted(set(ay for (ax, ay) in active_anchors))
        for row_y in ys_set:
            row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
            for horiz_y_off in [-3, 3]:
                horiz_y = row_y + horiz_y_off
                if len(row_anchors) >= 2:
                    x_start = row_anchors[0][0] - 3
                    x_end = row_anchors[-1][0] + 3
                    for cx in range(max(2, x_start), min(WORLD_W - 2, x_end + 1)):
                        if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                            return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL CROSS ROADS between column anchors ----
    if pop > 20:
        xs_set = sorted(set(ax for (ax, ay) in active_anchors))
        for col_x in xs_set:
            col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
            for vert_x_off in [-3, 3]:
                vert_x = col_x + vert_x_off
                if len(col_anchors) >= 2:
                    y_start = col_anchors[0][1] - 3
                    y_end = col_anchors[-1][1] + 3
                    for cy in range(max(2, y_start), min(WORLD_H - 2, y_end + 1)):
                        if ib(vert_x, cy) and bool(em[cy, vert_x]) and not bool(pm[cy, vert_x]):
                            return (Tool.ROAD, vert_x, cy)

    # ---- NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 11) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (earlier thresholds for denser city) ----
    if pop > 20:
        fire_spots = [
            (6, 8), (24, 8), (42, 8), (60, 8), (78, 8), (96, 8), (114, 8),
            (6, 22), (24, 22), (42, 22), (60, 22), (78, 22), (96, 22), (114, 22),
            (6, 37), (24, 37), (42, 37), (60, 37), (78, 37), (96, 37), (114, 37),
            (6, 52), (24, 52), (42, 52), (60, 52), (78, 52), (96, 52), (114, 52),
            (6, 67), (24, 67), (42, 67), (60, 67), (78, 67), (96, 67), (114, 67),
            (6, 82), (24, 82), (42, 82), (60, 82), (78, 82), (96, 82), (114, 82),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (15, 5), (33, 5), (51, 5), (69, 5), (87, 5), (105, 5),
            (15, 20), (33, 20), (51, 20), (69, 20), (87, 20), (105, 20),
            (15, 35), (33, 35), (51, 35), (69, 35), (87, 35), (105, 35),
            (15, 50), (33, 50), (51, 50), (69, 50), (87, 50), (105, 50),
            (15, 65), (33, 65), (51, 65), (69, 65), (87, 65), (105, 65),
            (15, 80), (33, 80), (51, 80), (69, 80), (87, 80), (105, 80),
            (15, 93), (33, 93), (51, 93), (69, 93), (87, 93), (105, 93),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (18, 4), (48, 4), (78, 4), (108, 4),
            (18, 94), (48, 94), (78, 94), (108, 94),
            (4, 35), (4, 65), (116, 35), (116, 65),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (4, 4), (116, 4), (4, 95), (116, 95),
            (60, 4), (60, 95),
            (4, 50), (116, 50),
            (30, 4), (90, 4), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for asp in [(54, 4), (4, 48), (115, 48), (54, 93), (28, 4), (84, 4)]:
            ax2, ay2 = asp
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for sp in [(4, 92), (116, 92), (60, 96), (4, 4), (116, 4)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 60:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: roads from existing zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 23) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder v2
# Strategy: denser grid, faster expansion, smarter zone placement
# Key improvements over parent:
# 1. More neighborhood centers (12x9 = 108 hoods vs 10x8=80)
# 2. Faster power/road expansion with less filtering
# 3. Better zone placement prioritization
# 4. Earlier civic services
# 5. Nuclear plants for high-pop areas

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending 5 tiles
    for dx in range(-5, 6):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking the wire cross
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-5, 6):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions[:20]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Denser neighborhood grid: 12 cols x 9 rows = 108 neighborhoods
    # Spacing ~10 horizontally, ~11 vertically
    nh_cols = [6, 16, 26, 36, 46, 56, 66, 76, 86, 96, 106, 116]
    nh_rows = [6, 17, 28, 39, 50, 61, 72, 83, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 100:   return 4
        if pop < 300:   return 9
        if pop < 700:   return 18
        if pop < 1500:  return 30
        if pop < 3000:  return 50
        if pop < 6000:  return 72
        if pop < 10000: return 90
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Select hoods evenly spaced across the full list
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center or nearby empty spot
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (connect plant to area) ----
    spine_r = 8
    # Process all hoods each step rotating through them
    hood_idx = step % max(len(active_hoods), 1)
    for offset_h in range(len(active_hoods)):
        idx_h = (hood_idx + offset_h) % len(active_hoods)
        hx, hy = active_hoods[idx_h]

        # Vertical spine at hx
        for dy in range(-spine_r, spine_r + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal spine at hy
        for dx in range(-spine_r, spine_r + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Connect horizontal neighbors
            if hy1 == hy2 and 0 < hx2 - hx1 <= 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Connect vertical neighbors
            if hx1 == hx2 and 0 < hy2 - hy1 <= 14:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    # Build roads at hx±1 and hy±1 for each hood
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[idx_h]

        # Roads flanking vertical spine
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                # Only place if wire at hx,ry exists (spine is built)
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

        # Roads flanking horizontal spine
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: ~30% ind, ~30% com, ~40% res
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road neighbor mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx) + np.abs(cys2 - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (earlier thresholds) ----
    if pop > 50:
        fire_spots = []
        for fr in range(0, WORLD_H, 18):
            for fc in range(0, WORLD_W, 20):
                fire_spots.append((fc + 8, fr + 8))
        for (sx, sy) in fire_spots:
            sx2, sy2 = min(sx, WORLD_W - 1), min(sy, WORLD_H - 1)
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.FIRESTATION, sx2, sy2)

    if pop > 200:
        police_spots = []
        for pr in range(0, WORLD_H, 22):
            for pc in range(0, WORLD_W, 24):
                police_spots.append((pc + 12, pr + 11))
        for (sx, sy) in police_spots:
            sx2, sy2 = min(sx, WORLD_W - 1), min(sy, WORLD_H - 1)
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.POLICESTATION, sx2, sy2)

    if pop > 800:
        stadiums = []
        for sr2 in range(10, WORLD_H - 10, 30):
            for sc2 in range(10, WORLD_W - 10, 30):
                stadiums.append((sc2, sr2))
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(6, 88), (114, 88), (6, 10), (114, 10), (60, 6), (60, 94), (30, 6), (90, 6)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 50), (114, 50)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear power upgrade for high-pop areas
    if pop > 5000 and step % 4 == 0:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
            y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.NUCLEARPOWER, nx, ny)

    # ---- PHASE 8: PARKS to boost land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central power plant with wire cross and initial roads."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from center
    for d in range(-8, 9):
        if d != 0:
            actions.append((Tool.WIRE, 60 + d, 50))
            actions.append((Tool.WIRE, 60, 50 + d))
    # Initial roads along the cross arms
    for d in range(-8, 9):
        actions.append((Tool.ROAD, 60 + d, 48))
        actions.append((Tool.ROAD, 60 + d, 52))
        actions.append((Tool.ROAD, 58, 50 + d))
        actions.append((Tool.ROAD, 62, 50 + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Zone balance ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 45% res, 30% com, 25% ind
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Neighborhood anchors: 5x4 grid covering map well ----
    # Use more anchors as population grows
    all_anchors = []
    for col_x in [15, 35, 60, 85, 105]:
        for row_y in [12, 30, 55, 75, 92]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 20:    return 2
        if pop < 80:    return 4
        if pop < 200:   return 7
        if pop < 400:   return 10
        if pop < 700:   return 14
        if pop < 1200:  return 18
        return 25

    n_active = min(num_active(), len(all_anchors))
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS at active anchors ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(0, 8):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE CROSS at each anchor ----
    spine_half = min(10, 5 + pop // 20)
    for (px, py) in active_anchors:
        for dx in range(-spine_half, spine_half + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine_half, spine_half + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # ---- CONNECT POWER between anchors horizontally ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1c, _ = row_anchors[i]
            x2c, _ = row_anchors[i + 1]
            for cx in range(x1c + 1, x2c):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- CONNECT POWER between anchors vertically ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1c = col_anchors[i]
            _, y2c = col_anchors[i + 1]
            for cy in range(y1c + 1, y2c):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: horizontal roads above and below wire rows ----
    for (px, py) in active_anchors:
        for road_dy in [-2, 2]:
            ry = py + road_dy
            if not ib(px, ry):
                continue
            for dx in range(-spine_half, spine_half + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- VERTICAL ROADS connecting neighborhood rows ----
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1c = col_anchors[i]
            _, y2c = col_anchors[i + 1]
            for road_dx in [-3, 3]:
                road_x = xl + road_dx
                for cy in range(y1c, y2c + 1):
                    if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD ZONE PLACEMENT MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES based on pop ----
    if pop > 50:
        fire_spots = [
            (10, 12), (40, 12), (70, 12), (100, 12),
            (10, 40), (40, 40), (70, 40), (100, 40),
            (10, 65), (40, 65), (70, 65), (100, 65),
            (10, 88), (40, 88), (70, 88), (100, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 55), (60, 55), (100, 55),
            (20, 85), (60, 85), (100, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (18, 5), (65, 5), (110, 5),
            (18, 95), (65, 95), (110, 95),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value near zones ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, cx - 2, cy + dy))
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    for dx in range(-7, 8):
        actions.append((Tool.ROAD, cx + dx, cy - 2))
        actions.append((Tool.ROAD, cx + dx, cy + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # === NEIGHBORHOOD GRID: dense 6x5 = 30 nodes across the map ===
    all_hoods = []
    for hy in range(12, 95, 16):
        for hx in range(12, 115, 16):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 30:   return 2
        if pop < 100:  return 4
        if pop < 300:  return 7
        if pop < 600:  return 12
        if pop < 1200: return 18
        if pop < 2500: return 24
        if pop < 5000: return 30
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # === BUILD NEIGHBOR MASKS ===
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: POWER PLANTS for each active hood ===
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE SPINES ===
    # Build vertical and horizontal wire spines for each active hood
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 14

    # Find nearest plant for this hood
    x0p, x1p = max(0, hx - 12), min(WORLD_W, hx + 13)
    y0p, y1p = max(0, hy - 12), min(WORLD_H, hy + 13)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        px_l = int(plant_xs[0]) + x0p
        py_l = int(plant_ys[0]) + y0p

        # Wire from plant toward hood (vertical)
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)

        # Wire from plant toward hood (horizontal)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend vertical spine at hx
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    col_plant_r = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                   if ib(hx, r) and bool(pm[r, hx])]

    if col_plant_r and not col_wire:
        py2 = col_plant_r[0]
        for wy in [py2 - 1, py2 + 1]:
            if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                return (Tool.WIRE, hx, wy)

    if col_wire:
        min_wr = min(col_wire)
        max_wr = max(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    # Extend horizontal spine at hy
    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    row_plant_c = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                   if ib(c, hy) and bool(pm[hy, c])]

    if row_plant_c and not row_wire:
        px2 = row_plant_c[0]
        for wx in [px2 - 1, px2 + 1]:
            if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                return (Tool.WIRE, wx, hy)

    if row_wire:
        min_wc = min(row_wire)
        max_wc = max(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # === PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ===
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hx2 <= hx1: continue
            if abs(hy1 - hy2) > 4: continue
            mid_y = (hy1 + hy2) // 2
            for cx2 in range(hx1 + 1, hx2):
                if ib(cx2, mid_y) and bool(em[mid_y, cx2]) and not bool(pm[mid_y, cx2]):
                    if not bool(wm[mid_y, cx2]):
                        # Check there's wire on one side
                        has_left = any(bool(wm[mid_y, c]) or bool(pm[mid_y, c])
                                       for c in range(max(0, cx2 - 3), cx2))
                        has_right = any(bool(wm[mid_y, c]) or bool(pm[mid_y, c])
                                        for c in range(cx2 + 1, min(WORLD_W, cx2 + 4)))
                        if has_left or has_right:
                            return (Tool.WIRE, cx2, mid_y)

        for (hx2, hy2) in active_hoods:
            if hy2 <= hy1: continue
            if abs(hx1 - hx2) > 4: continue
            mid_x = (hx1 + hx2) // 2
            for cy2 in range(hy1 + 1, hy2):
                if ib(mid_x, cy2) and bool(em[cy2, mid_x]) and not bool(pm[cy2, mid_x]):
                    if not bool(wm[cy2, mid_x]):
                        has_top = any(bool(wm[r, mid_x]) or bool(pm[r, mid_x])
                                      for r in range(max(0, cy2 - 3), cy2))
                        has_bot = any(bool(wm[r, mid_x]) or bool(pm[r, mid_x])
                                      for r in range(cy2 + 1, min(WORLD_H, cy2 + 4)))
                        if has_top or has_bot:
                            return (Tool.WIRE, mid_x, cy2)

    # === PHASE 4: ROADS FLANKING WIRE SPINES ===
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    for rx in [hx3 - 2, hx3 + 2]:
        if not ib(rx, hy3): continue
        cyc = step % 4
        for wr in col_wire3[cyc::4]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 2, hy3 + 2]:
        if not ib(hx3, ry): continue
        cyc = (step + 2) % 4
        for wc in row_wire3[cyc::4]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # Additional road from hood center flanks
    for rx in [hx3 - 1, hx3 + 1]:
        if not ib(rx, hy3): continue
        for dy2 in range(-spine, spine + 1):
            ry2 = hy3 + dy2
            if not ib(rx, ry2): continue
            if not bool(em[ry2, rx]) or bool(pm[ry2, rx]): continue
            if bool(wm[ry2, hx3]) or bool(pm[ry2, hx3]):
                return (Tool.ROAD, rx, ry2)

    # === PHASE 5: ZONE PLACEMENT ===
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.27:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Clustering bonus
        if total_zones > 8:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 7: CIVIC SERVICES ===
    if pop > 30:
        fire_grid = [(fx, fy) for fy in range(14, 95, 16)
                     for fx in range(14, 115, 16)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 120:
        police_grid = [(px2, py2) for py2 in range(18, 90, 18)
                       for px2 in range(18, 112, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 350:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
            (30, 30), (90, 30), (30, 70), (90, 70),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700 and funds > 4000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 30), (60, 70),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 900:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 93), (5, 45), (113, 45)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === PHASE 8: UPGRADE COAL TO NUCLEAR for mature cities ===
    if pop > 1500 and step % 3 == 0 and funds > 6000:
        nuc_spots = [(60, 50), (20, 20), (100, 20), (20, 80), (100, 80),
                     (40, 35), (80, 35), (40, 65), (80, 65),
                     (60, 20), (60, 80), (20, 50), (100, 50),
                     (12, 12), (108, 12), (12, 88), (108, 88)]
        for nx2, ny2 in nuc_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # === FALLBACK: extend wire from plants ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: extend wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for uncovered hood ===
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants arranged in a 2x2 grid, with wire spines and roads."""
    actions = []
    # 4 plants: 2 columns x 2 rows, more spread out
    for px in [30, 90]:
        for py in [30, 70]:
            actions.append((Tool.COALPOWER, px, py))
            # Wire spine vertically
            for dy in range(-8, 9):
                actions.append((Tool.WIRE, px, py + dy))
            # Wire spine horizontally
            for dx in range(-8, 9):
                actions.append((Tool.WIRE, px + dx, py))
            # Roads flanking vertical wire
            for dy in range(-8, 9):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
            # Roads flanking horizontal wire
            for dx in range(-8, 9):
                actions.append((Tool.ROAD, px + dx, py - 1))
                actions.append((Tool.ROAD, px + dx, py + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 45% residential, 35% commercial, 20% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 4 neighborhoods in a 2x2 grid, plus expand to 9 neighborhood 3x3 grid as pop grows
    base_anchors = [
        (30, 30), (90, 30),
        (30, 70), (90, 70),
    ]
    extended_anchors = [
        (60, 50),  # center
        (30, 50), (90, 50),  # middle row
        (60, 30), (60, 70),  # middle col
    ]
    all_anchors = base_anchors + extended_anchors

    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 5
        if pop < 1000:  return 7
        return 9

    n_active = num_active()
    # Use base anchors first, then extend
    if n_active <= 4:
        active_anchors = base_anchors[:n_active]
    else:
        active_anchors = base_anchors + extended_anchors[:n_active - 4]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        has_plant = False
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE CROSS (vertical + horizontal spine) ----
    spine_half = min(20, 6 + pop // 20)
    for (px, py) in active_anchors:
        # Vertical spine
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

        # Horizontal spine
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, py) and bool(wm[py, c])]
        if not wire_in_row:
            for dx2 in range(-4, 5):
                nx = px + dx2
                if ib(nx, py) and bool(em[py, nx]) and not bool(pm[py, nx]):
                    return (Tool.WIRE, nx, py)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, py) and (bool(em[py, nc]) or bool(wm[py, nc])) and not bool(pm[py, nc]):
                    return (Tool.WIRE, nc, py)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, py) and (bool(em[py, nc]) or bool(wm[py, nc])) and not bool(pm[py, nc]):
                    return (Tool.WIRE, nc, py)

    # ---- HORIZONTAL WIRE connecting anchors in same row ----
    y_levels = sorted(set(py for (px, py) in active_anchors))
    for yl in y_levels:
        row_anch = sorted([px for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anch) - 1):
            for cx in range(row_anch[i] + 1, row_anch[i + 1]):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor columns ----
    x_levels = sorted(set(px for (px, py) in active_anchors))
    for xl in x_levels:
        col_anch = sorted([py for (px, py) in active_anchors if px == xl])
        for i in range(len(col_anch) - 1):
            for cy in range(col_anch[i] + 1, col_anch[i + 1]):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        cycle = (step + idx * 5) % 4
        for wr in wire_in_col[cycle::4]:
            # Roads left and right of vertical wire
            for side in [px - 1, px + 1]:
                if ib(side, wr) and bool(em[wr, side]) and not bool(pm[wr, side]):
                    return (Tool.ROAD, side, wr)

        # Roads above and below horizontal wire
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, py) and bool(wm[py, c])]
        cycle2 = (step + idx * 7) % 4
        for wc in wire_in_row[cycle2::4]:
            for side in [py - 1, py + 1]:
                if ib(wc, side) and bool(em[side, wc]) and not bool(pm[side, wc]):
                    return (Tool.ROAD, wc, side)

    # ---- HORIZONTAL ROADS at anchor y-levels ----
    if pop > 20:
        for yl in y_levels:
            row_anch = sorted([px for (px, py) in active_anchors if py == yl])
            if len(row_anch) < 2:
                continue
            xl_start = row_anch[0] - spine_half
            xl_end = row_anch[-1] + spine_half
            for horiz_y in [yl - 3, yl + 3]:
                if not (ib(xl_start, horiz_y) and ib(xl_end, horiz_y)):
                    continue
                for cx in range(max(2, xl_start), min(WORLD_W - 2, xl_end + 1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS at anchor x-levels ----
    if pop > 20:
        for xl in x_levels:
            col_anch = sorted([py for (px, py) in active_anchors if px == xl])
            if len(col_anch) < 1:
                continue
            yl_start = col_anch[0] - spine_half
            yl_end = col_anch[-1] + spine_half
            for vert_x in [xl - 3, xl + 3]:
                if not (ib(vert_x, yl_start) and ib(vert_x, yl_end)):
                    continue
                for cy in range(max(2, yl_start), min(WORLD_H - 2, yl_end + 1)):
                    if ib(vert_x, cy) and bool(em[cy, vert_x]) and not bool(pm[cy, vert_x]):
                        return (Tool.ROAD, vert_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (15, 85), (45, 85), (75, 85), (105, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (15, 10), (60, 10), (105, 10),
            (15, 90), (60, 90), (105, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        # Upgrade to nuclear power
        nuke_spots = [(5, 5), (115, 5), (5, 95), (115, 95), (60, 5), (60, 95)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

