def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Ensure power plants across map ----
    # Progressive plant grid based on population
    plant_grid = [
        (20, 20), (60, 50), (100, 20),
        (20, 80), (100, 80), (60, 20),
        (60, 80), (20, 50), (100, 50),
    ]
    if pop > 100:
        plant_grid += [(40, 35), (80, 35), (40, 65), (80, 65)]
    if pop > 300:
        plant_grid += [(10, 10), (110, 10), (10, 90), (110, 90)]
        plant_grid += [(60, 10), (60, 90), (10, 50), (110, 50)]
    if pop > 600:
        plant_grid += [(30, 10), (90, 10), (30, 90), (90, 90)]
        plant_grid += [(10, 30), (110, 30), (10, 70), (110, 70)]
    if pop > 1000:
        plant_grid += [(50, 25), (70, 25), (50, 75), (70, 75)]
        plant_grid += [(25, 40), (95, 40), (25, 60), (95, 60)]
    if pop > 2000:
        plant_grid += [(15, 15), (105, 15), (15, 85), (105, 85)]
        plant_grid += [(45, 10), (75, 10), (45, 90), (75, 90)]

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire network (reactive: extend from existing power) ----
    # Wire rows every 10, cols every 15
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 15))
    if pop > 500:
        wire_rows += [r for r in range(5, WORLD_H - 5, 5) if r not in wire_rows]
        wire_cols += [c for c in range(7, WORLD_W - 5, 8) if c not in wire_cols]
    wire_rows = sorted(set(wire_rows))
    wire_cols = sorted(set(wire_cols))

    # Start wire on rows that have no power yet (seed from plant)
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Find nearest plant row and plant a wire at col 60
            pys_a, pxs_a = np.where(pm)
            if len(pxs_a) > 0:
                idx = np.argmin(np.abs(pys_a - wr))
                sx = int(pxs_a[idx])
                # Try to bridge from plant column to this row
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)
        # Fill gaps
        for x in range(left, right):
            if bool(em[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 3 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)
        for y in range(top, bot):
            if bool(em[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network (reactive: extend from existing roads) ----
    # Roads at rows midway between wire rows
    road_rows = []
    for wr in wire_rows:
        for offset in [5, -5]:
            r = wr + offset
            if 3 < r < WORLD_H - 3 and r not in wire_rows:
                road_rows.append(r)
    road_rows = sorted(set(road_rows))

    road_cols = []
    for wc in wire_cols:
        for offset in [7, -7]:
            c = wc + offset
            if 3 < c < WORLD_W - 3 and c not in wire_cols:
                road_cols.append(c)
    road_cols = sorted(set(road_cols))

    if pop > 400:
        extra_rr = list(range(3, WORLD_H - 3, 4))
        road_rows = sorted(set(road_rows + extra_rr))
        extra_rc = list(range(3, WORLD_W - 3, 5))
        road_cols = sorted(set(road_cols + extra_rc))

    for rr in road_rows:
        if not ib(0, rr):
            continue
        # Only build roads near power
        row_near_power = bool(np.any(near_power[rr, :]))
        if not row_near_power:
            continue
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Seed from wire col or center
            seeded = False
            for wc in wire_cols:
                if ib(wc, rr) and bool(em[rr, wc]) and not bool(pm[rr, wc]):
                    return (Tool.ROAD, wc, rr)
                    seeded = True
                    break
            if not seeded and ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        if not ib(rc, 0):
            continue
        col_near_power = bool(np.any(near_power[:, rc]))
        if not col_near_power:
            continue
        col_rd = rm[:, rc]
        if not col_rd.any():
            for wr in wire_rows:
                if ib(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # ---- PHASE 4: Zone placement (closed-loop, reactive) ----
    zone_cand = em & near_road & near_power
    # Margins
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H - 3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W - 3:] = False
    # Block infrastructure rows/cols to avoid overlap
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cys_a, cxs_a = np.where(zone_cand)
    if len(cxs_a) > 0:
        # Score: prefer close to roads and cluster with other zones
        road_ys, road_xs = np.where(rm)
        zone_ys2, zone_xs2 = np.where(zone_tiles)

        if len(road_xs) > 0:
            stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_a), 9999.0)
            for i in range(0, len(road_xs), stride):
                d = np.abs(cxs_a - road_xs[i]).astype(float) + np.abs(cys_a - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_a - 60) + np.abs(cys_a - 50)).astype(float)

        if len(zone_xs2) > 0:
            stride2 = max(1, len(zone_xs2) // 100)
            min_zone_dist = np.full(len(cxs_a), 9999.0)
            for i in range(0, len(zone_xs2), stride2):
                d2 = np.abs(cxs_a - zone_xs2[i]).astype(float) + np.abs(cys_a - zone_ys2[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d2)
            # Penalize too-close (overlap) and too-far (sprawl)
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            # First zones: go near center of map
            zone_score = (np.abs(cxs_a - 60) + np.abs(cys_a - 50)).astype(float)

        score = road_dist * 1.2 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 13 + pop % 19) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_a[k]), int(cys_a[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services (reactive to population) ----
    if pop > 20:
        fire_spots = [(fx, fy) for fy in range(15, WORLD_H - 5, 12)
                      for fx in range(15, WORLD_W - 5, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_spots = [(px2, py2) for py2 in range(18, WORLD_H - 5, 15)
                        for px2 in range(18, WORLD_W - 5, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_spots = [(pkx, pky) for pky in range(12, WORLD_H - 5, 10)
                      for pkx in range(12, WORLD_W - 5, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 400:
        stad_spots = [(sx, sy) for sy in range(20, 85, 22)
                      for sx in range(20, 100, 28)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        for apx, apy in [(54, 6), (66, 6), (54, 93), (66, 93),
                         (7, 40), (113, 40), (7, 60), (113, 60),
                         (25, 6), (95, 6), (25, 93), (95, 93)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        for npx, npy in [(20, 35), (100, 35), (20, 65), (100, 65),
                         (50, 20), (70, 20), (50, 80), (70, 80),
                         (35, 50), (85, 50)]:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 10), min(WORLD_W, npx + 11)
                y0, y1 = max(0, npy - 10), min(WORLD_H, npy + 11)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        for spx, spy in [(6, 50), (114, 50), (60, 3), (60, 96),
                         (20, 3), (100, 3), (20, 96), (100, 96)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones (reactive) ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                    for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones (reactive) ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                    for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: plant wire near existing plants ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = (step * 7) % len(pxs2)
        for off2 in range(min(len(pxs2), 30)):
            idx = (k + off2 * 3) % len(pxs2)
            px2, py2 = int(pxs2[idx]), int(pys2[idx])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (2, 0), (-2, 0), (0, 2), (0, -2)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Final fallback: road near wire ----
    wys3, wxs3 = np.where(wm)
    if len(wxs3) > 0:
        k2 = (step * 11) % len(wxs3)
        for off3 in range(min(len(wxs3), 50)):
            idx2 = (k2 + off3 * 5) % len(wxs3)
            wx3, wy3 = int(wxs3[idx2]), int(wys3[idx2])
            for dx3, dy3 in [(0, 3), (0, -3), (3, 0), (-3, 0),
                             (0, 5), (0, -5), (5, 0), (-5, 0)]:
                nx3, ny3 = wx3 + dx3, wy3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place 4 coal plants at cardinal positions with wire+road spines."""
    actions = []
    # 4 plants in a cross pattern near center
    for (px, py) in [(30, 30), (90, 30), (30, 70), (90, 70)]:
        actions.append((Tool.COALPOWER, px, py))
        # Short wire spine vertical
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- ANCHOR GRID: 5x4 = 20 neighborhoods across whole map ---
    all_anchors = []
    for col_x in [12, 35, 60, 85, 108]:
        for row_y in [15, 38, 62, 85]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 30:   return 2
        if pop < 80:   return 3
        if pop < 200:  return 5
        if pop < 400:  return 7
        if pop < 700:  return 10
        if pop < 1200: return 14
        if pop < 2000: return 17
        return len(all_anchors)

    n_active = num_active()
    # Spread active anchors: prefer center outward
    center_order = sorted(all_anchors, key=lambda a: abs(a[0]-60)+abs(a[1]-50))
    active_anchors = center_order[:n_active]

    # --- ENSURE POWER PLANTS near each active anchor ---
    for (px, py) in active_anchors:
        x0 = max(0, px-6); x1 = min(WORLD_W, px+7)
        y0 = max(0, py-6); y1 = min(WORLD_H, py+7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty tile
        for r in range(1, 14):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px+dx, py+dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # --- BUILD VERTICAL WIRE SPINE for each active anchor ---
    spine_half = min(28, 8 + pop // 8)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H-3, py + spine_half)
        col_wire = [r for r in range(spine_top, spine_bot+1) if ib(px, r) and bool(wm[r, px])]
        col_plant = [r for r in range(WORLD_H) if ib(px, r) and bool(pm[r, px])]
        if not col_wire and col_plant:
            ply = col_plant[0]
            for wy in [ply-1, ply+1]:
                if ib(px, wy) and bool(em[wy, px]) and not bool(pm[wy, px]):
                    return (Tool.WIRE, px, wy)
        if col_wire:
            max_wr = max(col_wire); min_wr = min(col_wire)
            if max_wr < spine_bot:
                nr = max_wr+1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr-1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # --- BUILD HORIZONTAL WIRE SPINE for each active anchor ---
    h_spine_half = min(20, 6 + pop // 10)
    for (px, py) in active_anchors:
        spine_left = max(2, px - h_spine_half)
        spine_right = min(WORLD_W-3, px + h_spine_half)
        row_wire = [c for c in range(spine_left, spine_right+1) if ib(c, py) and bool(wm[py, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, py) and bool(pm[py, c])]
        if not row_wire and row_plant:
            plx = row_plant[0]
            for wx in [plx-1, plx+1]:
                if ib(wx, py) and bool(em[py, wx]) and not bool(pm[py, wx]):
                    return (Tool.WIRE, wx, py)
        if row_wire:
            max_wc = max(row_wire); min_wc = min(row_wire)
            if max_wc < spine_right:
                nc = max_wc+1
                if ib(nc, py) and not bool(pm[py, nc]) and (bool(em[py, nc]) or bool(wm[py, nc])):
                    return (Tool.WIRE, nc, py)
            if min_wc > spine_left:
                nc = min_wc-1
                if ib(nc, py) and not bool(pm[py, nc]) and (bool(em[py, nc]) or bool(wm[py, nc])):
                    return (Tool.WIRE, nc, py)

    # --- CONNECT WIRE BETWEEN HORIZONTALLY ADJACENT ANCHORS (same row) ---
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors)-1):
            x1a, x2a = row_anchors[i][0], row_anchors[i+1][0]
            for cx in range(x1a+1, x2a):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # --- CONNECT WIRE BETWEEN VERTICALLY ADJACENT ANCHORS ---
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xc in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
        for i in range(len(col_anchors)-1):
            y1a, y2a = col_anchors[i][1], col_anchors[i+1][1]
            for cy in range(y1a+1, y2a):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # --- ROAD BUILDING: flank vertical wire spines ---
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H-3, py + spine_half)
        col_wire = [r for r in range(spine_top, spine_bot+1) if ib(px, r) and bool(wm[r, px])]
        if not col_wire:
            continue
        cycle = (step + idx * 3) % 2
        for rl, rr in [(px-1, px+1)]:
            for wr in col_wire[cycle::2]:
                if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                    return (Tool.ROAD, rl, wr)
                if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                    return (Tool.ROAD, rr, wr)

    # --- HORIZONTAL ROADS at offsets from each anchor y-level ---
    if pop > 15:
        for yl in y_levels:
            row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
            if not row_anchors:
                continue
            x_min = row_anchors[0][0] - 3
            x_max = row_anchors[-1][0] + 3
            for horiz_y in [yl-3, yl+3, yl-6, yl+6, yl-9, yl+9]:
                if not (2 <= horiz_y < WORLD_H-2):
                    continue
                for cx in range(max(2, x_min), min(WORLD_W-2, x_max+1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # --- VERTICAL ROADS connecting anchor rows ---
    if pop > 50:
        for xc in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
            for i in range(len(col_anchors)-1):
                y1a, y2a = col_anchors[i][1], col_anchors[i+1][1]
                for vert_x in [xc-1, xc+1]:
                    for cy in range(y1a+1, y2a):
                        if ib(vert_x, cy) and bool(em[cy, vert_x]) and not bool(pm[cy, vert_x]):
                            return (Tool.ROAD, vert_x, cy)

    # --- NEIGHBOR MASKS for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs-px).astype(float) + np.abs(cys-py).astype(float)*0.9)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # --- EXTEND ROADS near existing wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 200)):
            k = (step_k + offset*7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(nbr_wire[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES ---
    if pop > 50:
        fire_spots = [
            (8,8),(30,8),(55,8),(80,8),(112,8),
            (8,30),(30,30),(55,30),(80,30),(112,30),
            (8,55),(30,55),(55,55),(80,55),(112,55),
            (8,80),(30,80),(55,80),(80,80),(112,80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 180:
        police_spots = [
            (18,18),(45,18),(72,18),(100,18),
            (18,45),(45,45),(72,45),(100,45),
            (18,72),(45,72),(72,72),(100,72),
        ]
        for (sx, sy) in police_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (20,15),(65,15),(110,15),
            (20,50),(65,50),(110,50),
            (20,85),(65,85),(110,85),
        ]
        for (sx,sy) in stadium_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5,5),(115,5),(5,95),(115,95),
            (60,5),(60,95),(5,50),(115,50),
            (35,5),(85,5),(35,95),(85,95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2,ny2) and bool(em[ny2,nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55,5),(5,50),(115,50),(55,94),(5,10),(115,10)]:
            ax, ay = asp
            if ib(ax,ay) and bool(em[ay,ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5,94),(115,94),(60,97),(5,5),(115,5)]:
            sx2, sy2 = sp
            if ib(sx2,sy2) and bool(em[sy2,sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PARKS near zones ---
    if pop > 120:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step*3 + i*13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2),(3,3),(-3,-3),(3,-3),(-3,3)]:
                    nx2, ny2 = zx2+dx2, zy2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- DENSE INFILL: zones adjacent to existing roads ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k3 = (step*17) % max(len(road_xs2), 1)
        checked2 = 0
        for offset in range(min(len(road_xs2), 400)):
            k = (step_k3 + offset*11) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(3,0),(-3,0),(0,3),(0,-3),(2,2),(-2,2),(2,-2),(-2,-2),(4,0),(-4,0),(0,4),(0,-4)]:
                zx3, zy3 = rx3+dx3, ry3+dy3
                if ib(zx3,zy3) and bool(nbr_wire[zy3,zx3]) and zone_clear(zx3,zy3):
                    return (pick_tool(), zx3, zy3)
            checked2 += 1
            if checked2 > 300:
                break

    # --- FALLBACK: extend wire from existing ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step*13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset*5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: road near any zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step*19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

