def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: 40% res, 30% com, 30% ind - more balanced than parent
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense plant grid - every 15 tiles for better coverage
    plant_positions = []
    for py in range(12, 95, 15):
        for px in range(12, 115, 15):
            plant_positions.append((px, py))

    # PHASE 1: Place coal plants in grid
    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # PHASE 2: Wire extension toward unpowered areas
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Connect toward unpowered plants first
        unpowered_plants = [(px, py) for px, py in plant_positions
                            if ib(px, py) and not bool(near_power[py, px])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0:
            best_dist = 1e9
            best_k = 0
            sample = np.random.choice(len(upxs), min(50, len(upxs)), replace=False)
            for i in range(min(len(wxs), 300)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # PHASE 3: Road grid - denser every 4 tiles
    road_targets = []
    for gy in range(4, 98, 4):
        for gx in range(4, 118, 4):
            road_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:30]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # PHASE 4: Dense zone placement with mixed types
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Prefer close to road, spread zones out
        score = road_dist * 1.5 + np.maximum(0, 6 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic services - more aggressive placement
    if pop > 50:
        fire_positions = [(fx, fy) for fy in range(8, 95, 8) for fx in range(8, 115, 8)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_positions = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 10)]
        for psx, psy in police_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_positions = [(pkx, pky) for pky in range(6, 95, 6) for pkx in range(6, 115, 6)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [(20, 15), (60, 15), (100, 15),
                        (20, 50), (60, 50), (100, 50),
                        (20, 85), (60, 85), (100, 85),
                        (40, 30), (80, 30), (40, 70), (80, 70)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuke_locs = [(60, 25), (20, 15), (100, 15),
                     (20, 85), (100, 85), (60, 75),
                     (10, 50), (110, 50), (40, 10), (80, 10),
                     (40, 90), (80, 90)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1500:
        airport_locs = [(55, 8), (75, 8), (10, 20), (110, 20),
                        (55, 91), (75, 91), (10, 75), (110, 75)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91),
                        (15, 20), (105, 20), (15, 80), (105, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: roads near plants
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire crosses and flanking roads."""
    actions = []
    for (cx, cy) in [(30, 25), (90, 75)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for dx in range(-4, 5):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-4, 5):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
        for dx in range(-5, 6):
            actions.append((Tool.ROAD, cx + dx, cy - 1))
            actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # 8 cols x 7 rows = 56 neighborhoods covering the full 120x100 map
    nh_cols = [8, 24, 40, 56, 72, 88, 104, 116]
    nh_rows = [8, 22, 36, 50, 64, 78, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 30:    return 2
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 600:   return 14
        if pop < 1000:  return 20
        if pop < 2000:  return 28
        if pop < 4000:  return 38
        if pop < 7000:  return 48
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- BUILD NEIGHBOR POWER MASK ----
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    # Use slicing for efficiency
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 2: WIRE GRID connecting plants to hoods ----
    # For each active hood, extend wire spines in both directions
    spine_range = 14
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Vertical spine
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj in [-1, 1]:
            ay = wy + adj
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj in [-1, 1]:
            ax = wx + adj
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    # Check connections in a more flexible way
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hx1 == hx2 and abs(hy2 - hy1) in range(12, 20) and hy2 > hy1:
                # vertical connection
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)
            if hy1 == hy2 and abs(hx2 - hx1) in range(12, 20) and hx2 > hx1:
                # horizontal connection
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)

    # ---- PHASE 4: ROADS flanking wire spines (cross-pattern) ----
    road_hood_idx = (step + 1) % max(len(active_hoods), 1)
    rhx, rhy = active_hoods[road_hood_idx]

    # Vertical roads on both sides of vertical wire spine
    for rx in [rhx - 1, rhx + 1]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                    return (Tool.ROAD, rx, ry)

    # Horizontal roads on both sides of horizontal wire spine
    for ry2 in [rhy - 1, rhy + 1]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- BUILD NEIGHBOR ROAD MASK ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 5: ZONE PLACEMENT (primary) ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = (np.abs(cxs - hx2).astype(float) + np.abs(cys - hy2).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scaled with pop) ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 16) for fy in range(10, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(14, WORLD_W, 18) for py2 in range(14, WORLD_H, 18)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (10, 50), (110, 50),
                    (45, 50), (75, 50), (20, 15), (100, 15),
                    (20, 85), (100, 85), (55, 50), (65, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 96), (60, 4), (30, 96), (90, 96)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        # Add nuclear plants for extra power coverage
        nuclear_spots = [
            (15, 50), (105, 50), (60, 10), (60, 90),
            (15, 20), (105, 20), (15, 80), (105, 80),
            (40, 5), (80, 5), (40, 95), (80, 95),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        airports = [(45, 5), (75, 5), (45, 94), (75, 94), (5, 45), (115, 45), (5, 55), (115, 55)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 100 and step % 3 == 0:
        park_candidates = np.where(em & nbr_road & nbr_power)
        park_ys, park_xs = park_candidates
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- DENSE ZONE INFILL near roads ----
    road_ys3, road_xs3 = np.where(rm)
    if len(road_xs3) > 0:
        step_k3 = (step * 17) % len(road_xs3)
        for offset in range(min(len(road_xs3), 250)):
            k = (step_k3 + offset * 11) % len(road_xs3)
            rx3, ry3 = int(road_xs3[k]), int(road_ys3[k])
            for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                              (2, 2), (-2, 2), (2, -2), (-2, -2),
                              (4, 0), (-4, 0), (0, 4), (0, -4),
                              (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                zx3, zy3 = rx3 + dx3, ry3 + dy3
                if ib(zx3, zy3) and bool(nbr_power[zy3, zx3]) and zone_clear(zx3, zy3):
                    return (pick_tool(), zx3, zy3)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx3 + dx, hy3 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- ABSOLUTE FALLBACK: place a coal plant at first empty spot near center ----
    for r in range(1, 20):
        for dy in range(-r, r + 1):
            for dx in range(-r, r + 1):
                if abs(dx) == r or abs(dy) == r:
                    nx, ny = 60 + dx, 50 + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    return None

# Ambitious closed-loop city builder
# Strategy: Grid of neighborhoods across the full map
# Each neighborhood: coal plant + wire grid + road grid + dense zones
# Closed-loop: every action reads current tile_map state

def init(obs, state):
    """Bootstrap: place first coal plant + wire + roads at center."""
    actions = []
    # Primary plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from plant
    for dx in range(-3, 4):
        actions.append((Tool.WIRE, 60 + dx, 50))
    for dy in range(-3, 4):
        actions.append((Tool.WIRE, 60, 50 + dy))
    # Roads flanking wire
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- NEIGHBORHOOD GRID ----
    # 4 columns x 3 rows = 12 neighborhoods across the map
    # Each neighborhood has a coal plant + wire spine + flanking roads
    neighborhood_configs = []
    for col_i, cx in enumerate([20, 45, 75, 100]):
        for row_i, cy in enumerate([20, 50, 80]):
            # wire col is cx, roads at cx-1 and cx+1
            neighborhood_configs.append((cx, cy, cx, cx - 1, cx + 1, col_i * 3 + row_i))

    # How many neighborhoods to activate based on pop
    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 2
        if pop < 500:   return 3
        if pop < 900:   return 5
        if pop < 1500:  return 7
        if pop < 2500:  return 9
        if pop < 4000:  return 11
        return 12

    active = neighborhood_configs[:num_active()]

    # ---- 1. ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr, idx) in active:
        # Check 7x7 around anchor for existing plant
        has_plant = False
        for dx in range(-4, 5):
            for dy in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place plant at anchor
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Search nearby
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- 2. BUILD WIRE SPINES ----
    # Each neighborhood: vertical wire at wc, extending ~20 rows up/down
    pop_ext = min(20, pop // 60)  # extension grows with pop
    for (px, py, wc, rl, rr, idx) in active:
        spine_top = max(2, py - 18 - pop_ext)
        spine_bot = min(WORLD_H - 3, py + 18 + pop_ext)

        # Find current wire extent in this column
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_rows:
            # Seed wire adjacent to plant
            for dy in range(-4, 5):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            # Extend downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            # Extend upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE CONNECTIONS between same-row neighborhoods ----
    # Connect neighborhoods in same row for power sharing
    row_groups = {}
    for (px, py, wc, rl, rr, idx) in active:
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append((px, wc))

    for row_y, group in row_groups.items():
        if len(group) < 2:
            continue
        group_sorted = sorted(group, key=lambda g: g[1])
        for i in range(len(group_sorted) - 1):
            wc1 = group_sorted[i][1]
            wc2 = group_sorted[i + 1][1]
            # Connect horizontally at row_y
            for cx in range(wc1 + 1, wc2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- 4. BUILD ROADS flanking wire spines ----
    # Roads on both sides of each wire column, cycling through rows
    for (px, py, wc, rl, rr, idx) in active:
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        # Use step modulo to cycle through rows, left then right
        cycle = (step + idx * 7) % max(len(wire_rows), 1)
        for offset in range(0, min(len(wire_rows), 8)):
            wr = wire_rows[(cycle + offset) % len(wire_rows)]
            # Left road
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            # Right road
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- 5. HORIZONTAL ROADS connecting neighborhoods ----
    # Add horizontal roads at the anchor Y level to connect areas
    for (px, py, wc, rl, rr, idx) in active:
        # Road at py connecting left/right
        for dx in range(-8, 9):
            rx = wc + dx
            if ib(rx, py) and bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                # Only if near wire
                near_wire = any(bool(wm[py, rx + d]) or bool(pm[py, rx + d]) for d in [-1, 1] if ib(rx + d, py))
                if near_wire:
                    return (Tool.ROAD, rx, py)

    # ---- 6. ZONE PLACEMENT ----
    # Place zones near roads and wires
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.18:
            return Tool.INDUSTRIAL
        if cr < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighborhood masks for road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in [-2, -1, 0, 1, 2]:
        for dx in [-2, -1, 0, 1, 2]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep border clear
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates: closer to active anchor wire columns = better
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr, idx) in active:
            d = np.abs(cxs.astype(float) - wc) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step offset to vary placement
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- 7. EXTEND ROADS near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 40)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- 8. CIVIC SERVICES based on pop ----
    if pop > 200:
        firestations = [
            (35, 20), (55, 20), (85, 20), (105, 20),
            (35, 50), (55, 50), (85, 50), (105, 50),
            (35, 80), (55, 80), (85, 80), (105, 80),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        polices = [
            (30, 35), (60, 35), (90, 35),
            (30, 65), (60, 65), (90, 65),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1200:
        stadiums = [
            (40, 10), (80, 10), (40, 90), (80, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- 9. FALLBACK: extend wire laterally ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (step * 13) % max(len(wire_xs), 1)
        for offset in range(min(len(wire_xs), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- 10. FALLBACK: place nuclear for dense power ----
    if pop > 3000:
        for (px, py, wc, rl, rr, idx) in active:
            # Add nuclear near existing coal for extra capacity
            for dx in range(-5, 6):
                for dy in range(-5, 6):
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.NUCLEARPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3x3 grid of coal plants + wire cross + flanking roads."""
    actions = []
    # Place 9 coal plants in a 3x3 grid covering the map
    plants = [
        (30, 25), (60, 25), (90, 25),
        (30, 50), (60, 50), (90, 50),
        (30, 75), (60, 75), (90, 75),
    ]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire spines connecting all plants horizontally and vertically
    for y in [25, 50, 75]:
        for x in range(28, 93):
            actions.append((Tool.WIRE, x, y))
    for x in [30, 60, 90]:
        for y in range(23, 78):
            actions.append((Tool.WIRE, x, y))
    # Seed roads flanking the wire spines
    for x in range(10, 110):
        for ry in [23, 27, 48, 52, 73, 77]:
            actions.append((Tool.ROAD, x, ry))
    for y in range(10, 90):
        for rx in [28, 32, 58, 62, 88, 92]:
            actions.append((Tool.ROAD, rx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === NEIGHBORHOOD GRID: dense across the whole map ===
    all_hoods = []
    for hy in range(12, 95, 14):
        for hx in range(12, 115, 14):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 45
        if pop < 8000:  return 60
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    stride = max(1, len(all_hoods) // n_active)
    active_hoods = all_hoods[::stride][:n_active]

    # === BUILD NEIGHBOR MASKS ===
    power_src = wm | pm

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: POWER PLANTS for active hoods ===
    if funds > 1000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
            y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Place a plant near the hood center
                for r in range(1, 14):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # === PHASE 2: WIRE SPINES FROM PLANTS TO HOODS ===
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 16

    # Find nearest plant for this hood
    x0p, x1p = max(0, hx - 14), min(WORLD_W, hx + 15)
    y0p, y1p = max(0, hy - 14), min(WORLD_H, hy + 15)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        px_l = int(plant_xs[0]) + x0p
        py_l = int(plant_ys[0]) + y0p
        # Wire vertical from plant to hood
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        # Wire horizontal from plant to hood
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend vertical spine at hx for this hood
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    col_plant_r = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                   if ib(hx, r) and bool(pm[r, hx])]

    if col_plant_r and not col_wire:
        py2 = col_plant_r[0]
        for wy in [py2 - 1, py2 + 1]:
            if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                return (Tool.WIRE, hx, wy)

    if col_wire:
        min_wr = min(col_wire); max_wr = max(col_wire)
        bot_t = min(WORLD_H - 3, hy + spine)
        top_t = max(2, hy - spine)
        if max_wr < bot_t:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_t:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    # Extend horizontal spine at hy
    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    row_plant_c = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                   if ib(c, hy) and bool(pm[hy, c])]

    if row_plant_c and not row_wire:
        px2 = row_plant_c[0]
        for wx in [px2 - 1, px2 + 1]:
            if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                return (Tool.WIRE, wx, hy)

    if row_wire:
        min_wc = min(row_wire); max_wc = max(row_wire)
        right_t = min(WORLD_W - 3, hx + spine)
        left_t = max(2, hx - spine)
        if max_wc < right_t:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_t:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # === PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ===
    # Only check nearby pairs to keep this fast
    for i in range(len(active_hoods)):
        hx1, hy1 = active_hoods[i]
        for j in range(i + 1, min(i + 6, len(active_hoods))):
            hx2, hy2 = active_hoods[j]
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 30:
                continue
            # Try to bridge horizontal
            if abs(hy1 - hy2) <= 3:
                mid_y2 = (hy1 + hy2) // 2
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if ib(cx2, mid_y2) and bool(em[mid_y2, cx2]) and not bool(pm[mid_y2, cx2]) and not bool(wm[mid_y2, cx2]):
                        has_l = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c]) for c in range(max(0, cx2 - 4), cx2))
                        has_r = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c]) for c in range(cx2 + 1, min(WORLD_W, cx2 + 5)))
                        if has_l or has_r:
                            return (Tool.WIRE, cx2, mid_y2)
            # Try to bridge vertical
            if abs(hx1 - hx2) <= 3:
                mid_x2 = (hx1 + hx2) // 2
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if ib(mid_x2, cy2) and bool(em[cy2, mid_x2]) and not bool(pm[cy2, mid_x2]) and not bool(wm[cy2, mid_x2]):
                        has_t = any(bool(wm[r, mid_x2]) or bool(pm[r, mid_x2]) for r in range(max(0, cy2 - 4), cy2))
                        has_b = any(bool(wm[r, mid_x2]) or bool(pm[r, mid_x2]) for r in range(cy2 + 1, min(WORLD_H, cy2 + 5)))
                        if has_t or has_b:
                            return (Tool.WIRE, mid_x2, cy2)

    # === PHASE 4: ROADS FLANKING WIRE SPINES ===
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    # Roads on both sides of vertical wire spine
    for offset in [2, -2, 3, -3]:
        rx = hx3 + offset
        if not ib(rx, hy3): continue
        cyc = step % 4
        for wr in col_wire3[cyc::4]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    # Roads on both sides of horizontal wire spine
    for offset in [2, -2, 3, -3]:
        ry = hy3 + offset
        if not ib(hx3, ry): continue
        cyc = (step + 2) % 4
        for wc in row_wire3[cyc::4]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # Additional road flanking hood center
    for rx_off in [1, -1, 2, -2]:
        rx2 = hx3 + rx_off
        if not ib(rx2, hy3): continue
        for dy2 in range(-spine, spine + 1):
            ry2 = hy3 + dy2
            if not ib(rx2, ry2): continue
            if not bool(em[ry2, rx2]) or bool(pm[ry2, rx2]): continue
            if bool(wm[ry2, hx3]) or bool(pm[ry2, hx3]):
                return (Tool.ROAD, rx2, ry2)

    # === PHASE 5: DENSE ROAD GRID ===
    # Build a grid of roads every ~5 tiles near powered areas
    road_rows_target = list(range(8, 95, 5))
    road_cols_target = list(range(8, 115, 5))

    # Try to extend existing horizontal roads
    for rr in road_rows_target:
        row_road = rm[rr, :]
        if row_road.any():
            idxs = np.where(row_road)[0]
            left = int(idxs[0]); right = int(idxs[-1])
            if left > 4 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]) and bool(nbr_power[rr, left - 1]):
                return (Tool.ROAD, left - 1, rr)
            if right < WORLD_W - 5 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]) and bool(nbr_power[rr, right + 1]):
                return (Tool.ROAD, right + 1, rr)
        elif bool(nbr_power[rr, 60]) and bool(em[rr, 60]):
            return (Tool.ROAD, 60, rr)

    # Try to extend existing vertical roads
    for rc in road_cols_target:
        col_road = rm[:, rc]
        if col_road.any():
            idxs = np.where(col_road)[0]
            top = int(idxs[0]); bot = int(idxs[-1])
            if top > 4 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]) and bool(nbr_power[top - 1, rc]):
                return (Tool.ROAD, rc, top - 1)
            if bot < WORLD_H - 5 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]) and bool(nbr_power[bot + 1, rc]):
                return (Tool.ROAD, rc, bot + 1)
        elif bool(nbr_power[50, rc]) and bool(em[50, rc]):
            return (Tool.ROAD, rc, 50)

    # === PHASE 6: ZONE PLACEMENT ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: distance to nearest active hood + clustering
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 10:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.55 + zone_prox * 0.45
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 7: EXTEND ROADS FROM EXISTING NETWORK ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 8: CIVIC SERVICES (SCALED AGGRESSIVELY) ===
    if pop > 25:
        fire_grid = [(fx, fy) for fy in range(14, 95, 14)
                     for fx in range(14, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(16, 90, 16)
                       for px2 in range(16, 112, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 35), (80, 35), (40, 60), (80, 60),
            (30, 25), (90, 25), (30, 75), (90, 75),
            (55, 40), (65, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 30), (60, 70),
            (25, 35), (95, 35), (25, 65), (95, 65),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        seaport_locs = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (5, 75), (115, 25), (115, 75),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 700:
        airport_locs = [
            (10, 10), (100, 10), (10, 85), (100, 85),
            (55, 5), (55, 93), (5, 45), (113, 45),
            (50, 8), (70, 8), (50, 92), (70, 92),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # Upgrade coal to nuclear for mature cities
    if pop > 1200 and step % 3 == 0 and funds > 5000:
        nuc_spots = [
            (60, 50), (20, 20), (100, 20), (20, 80), (100, 80),
            (40, 35), (80, 35), (40, 65), (80, 65),
            (60, 20), (60, 80), (20, 50), (100, 50),
            (30, 25), (90, 25), (30, 75), (90, 75),
        ]
        for nx2, ny2 in nuc_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # === FALLBACK: extend wire from plants ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 80)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: extend wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for uncovered hood ===
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]) and funds > 800:
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

