def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Dense neighborhood grid covering more of the map
    all_hoods = []
    for hy in range(10, 95, 12):
        for hx in range(10, 115, 12):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:    return 4
        if pop < 200:   return 8
        if pop < 500:   return 16
        if pop < 1000:  return 28
        if pop < 2000:  return 42
        if pop < 4000:  return 60
        if pop < 8000:  return 80
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: ENSURE POWER PLANTS ---
    # One plant per cluster of ~5 hoods
    if funds > 1200:
        for idx_h, (hx, hy) in enumerate(active_hoods):
            if idx_h % 5 != 0:
                continue
            x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
            y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find nearest empty tile
                for r in range(1, 14):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # --- BUILD NEIGHBOR MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # --- PHASE 2: WIRE GRID - reactive extension from existing wires/plants ---
    # For each active hood, extend wire spines toward the hood center
    pys_arr, pxs_arr = np.where(pm)

    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 11)
        spine_bot   = min(WORLD_H - 3, hy + 11)
        spine_left  = max(2, hx - 11)
        spine_right = min(WORLD_W - 3, hx + 11)

        # Vertical spine at hx
        col_wire = [r for r in range(spine_top, spine_bot + 1) if ib(hx, r) and bool(wm[r, hx])]
        col_plant_tiles = [r for r in range(spine_top, spine_bot + 1) if ib(hx, r) and bool(pm[r, hx])]

        if col_plant_tiles and not col_wire:
            for pr in col_plant_tiles:
                for wr in [pr - 1, pr + 1]:
                    if ib(hx, wr) and not bool(pm[wr, hx]) and bool(em[wr, hx]):
                        return (Tool.WIRE, hx, wr)

        if col_wire:
            min_wr = min(col_wire)
            max_wr = max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine at hy
        row_wire = [c for c in range(spine_left, spine_right + 1) if ib(c, hy) and bool(wm[hy, c])]
        row_plant_tiles = [c for c in range(spine_left, spine_right + 1) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant_tiles and not row_wire:
            for pc in row_plant_tiles:
                for wc in [pc - 1, pc + 1]:
                    if ib(wc, hy) and not bool(pm[hy, wc]) and bool(em[hy, wc]):
                        return (Tool.WIRE, wc, hy)

        if row_wire:
            min_wc = min(row_wire)
            max_wc = max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: INTERCONNECT WIRE SPINES BETWEEN NEARBY HOODS ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 25:
                continue
            if abs(hy1 - hy2) <= 2 and hx2 > hx1:
                bridge_y = (hy1 + hy2) // 2
                for cx in range(hx1 + 1, hx2):
                    if ib(cx, bridge_y) and bool(em[bridge_y, cx]) and not bool(pm[bridge_y, cx]):
                        return (Tool.WIRE, cx, bridge_y)
            if abs(hx1 - hx2) <= 2 and hy2 > hy1:
                bridge_x = (hx1 + hx2) // 2
                for cy in range(hy1 + 1, hy2):
                    if ib(bridge_x, cy) and bool(em[cy, bridge_x]) and not bool(pm[cy, bridge_x]):
                        return (Tool.WIRE, bridge_x, cy)

    # --- PHASE 4: ROAD GRID - reactive extension along wire spines ---
    for (hx, hy) in active_hoods:
        spine_top  = max(2, hy - 11)
        spine_bot  = min(WORLD_H - 3, hy + 11)
        spine_left = max(2, hx - 11)
        spine_right= min(WORLD_W - 3, hx + 11)

        col_wire = [r for r in range(spine_top, spine_bot + 1) if ib(hx, r) and bool(wm[r, hx])]
        # Build roads at hx±2 parallel to vertical wire spine
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy):
                continue
            cyc = step % 3
            for wr in col_wire[cyc::3]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wire = [c for c in range(spine_left, spine_right + 1) if ib(c, hy) and bool(wm[hy, c])]
        # Build roads at hy±2 parallel to horizontal wire spine
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry):
                continue
            cyc = (step + 1) % 3
            for wc in row_wire[cyc::3]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT ---
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # Target: 50% res, 25% com, 25% ind
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Cluster bonus: prefer spots near existing zones
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.35 + zone_prox * 0.65
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES ---
    # Fire stations - place early and densely
    if pop > 3:
        fire_grid = [(fx, fy) for fy in range(10, 95, 14) for fx in range(10, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 30:
        police_grid = [(px2, py2) for py2 in range(12, 93, 16) for px2 in range(12, 113, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 200:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (50, 50), (70, 30), (70, 70),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Upgrade to nuclear when rich
    if pop > 500 and funds > 3500:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 25), (60, 75),
            (45, 45), (75, 45), (45, 55), (75, 55),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
            y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75),
                        (30, 5), (90, 5), (30, 95), (90, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 700:
        airport_locs = [(8, 8), (102, 8), (8, 87), (102, 87),
                        (50, 8), (50, 87), (8, 50), (102, 50)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from any plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        sk = (step * 11) % len(pxs2)
        for offset in range(min(len(pxs2), 80)):
            k = (sk + offset * 7) % len(pxs2)
            px2, py2 = int(pxs2[k]), int(pys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                              (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Compact, reactive city-builder policy
# Strategy: dense grid of neighborhoods, each with power+road, placed reactively

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire connections."""
    actions = []
    # Three starter plants at different heights
    for px, py in [(20, 50), (60, 50), (100, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire above and below plant
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px + 2, py + dy))
        # Road on both sides of wire
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px + 1, py + dy))
            actions.append((Tool.ROAD, px + 3, py + dy))
        # Horizontal road connecting outward
        for dx in range(-5, 8):
            actions.append((Tool.ROAD, px + dx, py + 4))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone tool selection: balanced mix
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE MANAGEMENT ----
    # Use state to track which neighborhood we're currently building
    if 'phase' not in state:
        state['phase'] = 0
    if 'plant_placed' not in state:
        state['plant_placed'] = set()

    # Define a dense grid of neighborhoods across the full map
    # Each neighborhood: center (nx, ny), wire column offset, road offset
    # 5 columns x 5 rows = 25 neighborhoods
    neighborhoods = []
    cols = [15, 35, 55, 75, 95, 115]
    rows = [15, 30, 45, 60, 75, 90]
    for cy in rows:
        for cx in cols:
            neighborhoods.append((cx, cy))

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 3
        if pop < 500:   return 4
        if pop < 800:   return 5
        if pop < 1200:  return 6
        if pop < 1800:  return 7
        if pop < 2500:  return 8
        if pop < 3500:  return 9
        if pop < 5000:  return 12
        if pop < 7000:  return 16
        return min(len(neighborhoods), 20)

    n_active = num_active()
    active_nh = neighborhoods[:n_active]

    # ---- ENSURE POWER PLANTS near neighborhoods ----
    # Each neighborhood shares a power plant - place one coal plant per 3 neighborhoods
    plant_anchors = []
    for i, (nhx, nhy) in enumerate(active_nh):
        if i % 3 == 0:
            plant_anchors.append((nhx + 2, nhy))

    for (px, py) in plant_anchors:
        px2 = min(px, WORLD_W - 3)
        py2 = min(py, WORLD_H - 3)
        px2 = max(px2, 2)
        py2 = max(py2, 2)
        # Check if plant already exists nearby
        y0 = max(0, py2 - 8); y1 = min(WORLD_H, py2 + 9)
        x0 = max(0, px2 - 8); x1 = min(WORLD_W, px2 + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.COALPOWER, px2, py2)
            # Search nearby
            for r in range(1, 15):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx2, ny2 = px2 + dx, py2 + dy
                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                            return (Tool.COALPOWER, nx2, ny2)

    # ---- WIRE SPINE: vertical wire connecting each neighborhood to power ----
    # Wire runs from plant down/up to neighborhood areas
    for i, (nhx, nhy) in enumerate(active_nh):
        # Wire column is at nhx+2 or nearby
        wc = nhx + 2
        wc = min(wc, WORLD_W - 1)
        # Check if any wire in this column within range
        y_lo = max(0, nhy - 12)
        y_hi = min(WORLD_H - 1, nhy + 12)
        wire_in_range = [r for r in range(y_lo, y_hi + 1) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_in_range:
            # No wire yet - place one adjacent to plant if possible
            for dy in range(-8, 9):
                ny2 = nhy + dy
                if ib(wc, ny2) and bool(em[ny2, wc]) and not bool(pm[ny2, wc]):
                    # Check if there's a plant nearby to connect from
                    px_check = min(nhx + 2, WORLD_W - 3)
                    px_check = max(px_check, 2)
                    px_y = max(0, nhy - 10)
                    px_yh = min(WORLD_H, nhy + 11)
                    if np.any(pm[px_y:px_yh, max(0, wc-10):min(WORLD_W, wc+11)]):
                        return (Tool.WIRE, wc, ny2)
        else:
            # Extend wire to cover full neighborhood height range
            min_wr = min(wire_in_range)
            max_wr = max(wire_in_range)
            target_top = max(2, nhy - 10)
            target_bot = min(WORLD_H - 3, nhy + 10)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE: connect wire columns across neighborhoods in same row ----
    row_groups = {}
    for (nhx, nhy) in active_nh:
        row_key = nhy
        if row_key not in row_groups:
            row_groups[row_key] = []
        row_groups[row_key].append(nhx + 2)

    for ry, wcols in row_groups.items():
        wcols_sorted = sorted(set(wcols))
        for i in range(len(wcols_sorted) - 1):
            c1, c2 = wcols_sorted[i], wcols_sorted[i+1]
            for cx in range(c1 + 1, c2):
                cx2 = min(cx, WORLD_W - 1)
                if ib(cx2, ry) and bool(em[ry, cx2]) and not bool(pm[ry, cx2]):
                    return (Tool.WIRE, cx2, ry)

    # ---- ROADS: grid roads for each active neighborhood ----
    for (nhx, nhy) in active_nh:
        # Place horizontal roads above and below center
        for road_y in [nhy - 6, nhy - 3, nhy, nhy + 3, nhy + 6]:
            if not ib(nhx - 6, road_y) or not ib(nhx + 6, road_y):
                continue
            for rx in range(nhx - 8, nhx + 9):
                if ib(rx, road_y) and bool(em[road_y, rx]) and not bool(pm[road_y, rx]):
                    # Only near wire coverage
                    wc = nhx + 2
                    if abs(rx - wc) <= 10:
                        return (Tool.ROAD, rx, road_y)

        # Place vertical roads flanking the wire column
        wc = nhx + 2
        for road_x in [wc - 2, wc - 1, wc + 1, wc + 2]:
            for ry in range(nhy - 8, nhy + 9):
                if ib(road_x, ry) and bool(em[ry, road_x]) and not bool(pm[ry, road_x]):
                    # Only if wire is nearby
                    if np.any(wm[max(0, ry-3):min(WORLD_H, ry+4), max(0, road_x-3):min(WORLD_W, road_x+4)]):
                        return (Tool.ROAD, road_x, ry)

    # ---- BUILD NEIGHBOR MASKS FOR ZONE PLACEMENT ----
    # Road within 2 cells
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/plant within 8 cells
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (nhx, nhy) in active_nh:
            d = (np.abs(cxs - nhx).astype(float) + np.abs(cys - nhy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing road near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_grid = []
        for fy in range(10, WORLD_H - 5, 20):
            for fx in range(10, WORLD_W - 5, 25):
                fire_grid.append((fx, fy))
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_grid = []
        for py2 in range(15, WORLD_H - 5, 25):
            for px2 in range(15, WORLD_W - 5, 30):
                police_grid.append((px2, py2))
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (30, 8), (70, 8), (110, 8),
            (30, 92), (70, 92), (110, 92),
            (5, 45), (115, 45), (5, 70), (115, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- NUCLEAR POWER for late game ----
    if pop > 1500:
        nuke_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 50), (115, 50),
            (5, 95), (60, 95), (115, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(50, 5), (5, 48), (115, 48), (50, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 90), (115, 90), (58, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS for land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at quadrant centers with wire spines and roads."""
    actions = []
    # Four power plants at quadrant centers
    plants = [(30, 25), (90, 25), (30, 75), (90, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire spines connecting plants horizontally at y=25 and y=75
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 75))
    # Wire spines connecting plants vertically at x=30 and x=90
    for y in range(26, 75):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Roads near plants for immediate zone access
    for x in range(20, 45):
        actions.append((Tool.ROAD, x, 22))
        actions.append((Tool.ROAD, x, 28))
    for x in range(80, 105):
        actions.append((Tool.ROAD, x, 22))
        actions.append((Tool.ROAD, x, 28))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Dense neighborhood grid covering the whole map
    nh_cols = [10, 27, 44, 60, 76, 93, 110]
    nh_rows = [10, 26, 42, 58, 74, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 14
        if pop < 800:   return 20
        if pop < 1500:  return 28
        if pop < 3000:  return 35
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: Ensure power plant near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire spines from each plant toward uncovered hoods ----
    # Build adjacency-to-power for wire extension
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2, dx2 in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy2 == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy2 == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx2 == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    # Wire candidates: empty, adjacent to power, not a zone
    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False; wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False; wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Find hoods without power
        unpowered_hoods = [(hx, hy) for hx, hy in active_hoods
                           if not bool(near_power[hy, hx])]
        if unpowered_hoods:
            best_dist = 1e9; best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - hx) + abs(cy - hy) for hx, hy in unpowered_hoods)
                if d < best_dist:
                    best_dist = d; best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid near powered areas ----
    # Road targets: dense grid near hoods
    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2, dx2 in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy2 == -1: shifted[:-1, :] = rm[1:, :]
        elif dy2 == 1: shifted[1:, :] = rm[:-1, :]
        elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx2 == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand = em & adj_to_road & near_power & ~zone_tiles & ~wm & ~pm
    road_cand[0:3, :] = False; road_cand[WORLD_H-3:, :] = False
    road_cand[:, 0:3] = False; road_cand[:, WORLD_W-3:] = False

    rys2, rxs2 = np.where(road_cand)
    if len(rxs2) > 0:
        # Find hoods without road access
        unroaded_hoods = [(hx, hy) for hx, hy in active_hoods
                          if not bool(near_road[hy, hx]) and bool(near_power[hy, hx])]
        if unroaded_hoods:
            best_dist = 1e9; best_k = 0
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - hx) + abs(cy - hy) for hx, hy in unroaded_hoods)
                if d < best_dist:
                    best_dist = d; best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Extend roads toward all hoods
            best_dist = 1e9; best_k = 0
            for i in range(min(len(rxs2), 300)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - hx) + abs(cy - hy) for hx, hy in active_hoods)
                if d < best_dist:
                    best_dist = d; best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:3, :] = False; zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, 0:3] = False; zone_cand[:, WORLD_W-3:] = False

    cys, cxs = np.where(zone_cand)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = (np.abs(cxs - hx2).astype(float) + np.abs(cys - hy2).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 5: Infill roads near zones lacking road ----
    unpowered_zones = zone_tiles & ~near_power
    unroaded_zones = zone_tiles & ~near_road
    zone_need_road_ys, zone_need_road_xs = np.where(unroaded_zones)
    if len(zone_need_road_xs) > 0:
        k = (step * 11) % len(zone_need_road_xs)
        zx2, zy2 = int(zone_need_road_xs[k]), int(zone_need_road_ys[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2),(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (tiered by pop) ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 115, 10)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_grid = [(px2, py2) for py2 in range(12, 92, 12) for px2 in range(12, 112, 12)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 3 == 0:
        park_cands = np.where(em & near_road & near_power)
        park_ys, park_xs = park_cands
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 500:
        stadium_locs = [(25, 20), (85, 20), (25, 70), (85, 70),
                        (55, 15), (55, 85), (15, 45), (105, 45),
                        (40, 50), (80, 50), (60, 35), (60, 65)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        seaport_locs = [(8, 90), (110, 90), (8, 8), (110, 8),
                        (60, 95), (60, 4), (30, 95), (90, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1200:
        nuke_locs = [(60, 50), (20, 50), (100, 50), (60, 15), (60, 85),
                     (10, 15), (110, 15), (10, 85), (110, 85)]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2-5), min(WORLD_W, nx2+6)
                y0, y1 = max(0, ny2-5), min(WORLD_H, ny2+6)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        airport_locs = [(50, 6), (70, 6), (50, 93), (70, 93),
                        (6, 40), (113, 40), (6, 60), (113, 60)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from nearest plant toward uncovered hood ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = (step * 7) % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(near_power[hy3, hx3]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx3 + dx, hy3 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants across map with wire spines and flanking roads."""
    actions = []
    # Four starting plants: spread across map
    for cx, cy in [(15, 50), (45, 50), (75, 50), (105, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Vertical wire spine
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Flanking roads
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Denser neighborhood grid: 10 cols x 8 rows = 80 neighborhoods
    # Spread more evenly across the 120x100 map
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 300:   return 14
        if pop < 600:   return 22
        if pop < 1200:  return 32
        if pop < 2500:  return 48
        if pop < 5000:  return 64
        if pop < 8000:  return 72
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active hood needs a plant within 10 tiles
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        # Find nearest empty spot for plant
        for r in range(1, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (vertical + horizontal cross) ----
    spine_range = 16

    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Stagger which hoods we process to spread work
        if (step + idx_h) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 3 + 1):
            continue

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            # Must be adjacent to existing wire/plant
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap from plant neighbors
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        # Connect to horizontal neighbors at various spacings
        for dx_hop in [12, 24, 36]:
            hx2, hy2 = hx1 + dx_hop, hy1
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        # Connect to vertical neighbors
        for dy_hop in [12, 24]:
            hx2, hy2 = hx1, hy1 + dy_hop
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 3) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 3 + 1):
            continue

        # Flanking vertical spine (roads at hx-1 and hx+1)
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Flanking horizontal spine (roads at hy-1 and hy+1)
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

        # Cross roads: add roads along row hy at hx+-2 offset (perpendicular access)
        for ox in range(-spine_range, spine_range + 1):
            rcx = hx + ox
            if not ib(rcx, hy - 2) or not ib(rcx, hy + 2):
                continue
            # roads 2 tiles above/below the horizontal wire spine
            for ry3 in [hy - 2, hy + 2]:
                if bool(em[ry3, rcx]) and not bool(pm[ry3, rcx]):
                    if bool(wm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry3)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road coverage (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power (wire or plant within 8 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (6, 10), (18, 10), (30, 10), (42, 10), (54, 10),
            (66, 10), (78, 10), (90, 10), (102, 10), (114, 10),
            (6, 30), (18, 30), (30, 30), (42, 30), (54, 30),
            (66, 30), (78, 30), (90, 30), (102, 30), (114, 30),
            (6, 50), (18, 50), (30, 50), (42, 50), (54, 50),
            (66, 50), (78, 50), (90, 50), (102, 50), (114, 50),
            (6, 70), (18, 70), (30, 70), (42, 70), (54, 70),
            (66, 70), (78, 70), (90, 70), (102, 70), (114, 70),
            (6, 90), (18, 90), (30, 90), (42, 90), (54, 90),
            (66, 90), (78, 90), (90, 90), (102, 90), (114, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (12, 20), (36, 20), (60, 20), (84, 20), (108, 20),
            (12, 40), (36, 40), (60, 40), (84, 40), (108, 40),
            (12, 60), (36, 60), (60, 60), (84, 60), (108, 60),
            (12, 80), (36, 80), (60, 80), (84, 80), (108, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (24, 24), (60, 24), (96, 24),
            (24, 60), (60, 60), (96, 60),
            (24, 84), (60, 84), (96, 84),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 50), (115, 50),
            (5, 95), (60, 95), (115, 95),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [
            (8, 92), (112, 92), (8, 6), (112, 6),
            (40, 95), (80, 95), (40, 4), (80, 4),
            (5, 48), (115, 48),
        ]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [
            (48, 5), (72, 5), (48, 92), (72, 92),
            (4, 46), (114, 46), (4, 54), (114, 54),
        ]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3),
                                  (4, 0), (-4, 0), (0, 4), (0, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                          (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: multiple coal plants + initial wire grid + roads"""
    actions = []
    # 6 coal plants spread across map
    for px, py in [(20, 25), (60, 25), (100, 25), (20, 75), (60, 75), (100, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at y=25 and y=75
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 75))
    # Vertical wire spines at x=20, 60, 100
    for y in range(1, 99):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Roads flanking horizontal wires
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 74))
        actions.append((Tool.ROAD, x, 76))
    # Roads flanking vertical wires
    for y in range(1, 99):
        actions.append((Tool.ROAD, 19, y))
        actions.append((Tool.ROAD, 21, y))
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
        actions.append((Tool.ROAD, 99, y))
        actions.append((Tool.ROAD, 101, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 50% RES, 25% COM, 25% IND
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Wire corridors: horizontal at fixed rows, vertical at fixed cols
    wire_rows = [10, 25, 40, 55, 75, 88]
    wire_cols = [10, 20, 35, 50, 60, 75, 90, 100, 115]

    # ---- PHASE 1: ENSURE PLANTS EXIST AT KEY LOCATIONS ----
    plant_targets = [
        (20, 25), (60, 25), (100, 25),
        (20, 75), (60, 75), (100, 75),
        (20, 50), (60, 50), (100, 50),
        (40, 10), (80, 10), (40, 90), (80, 90),
    ]
    for px, py in plant_targets:
        x0, x1 = max(0, px-5), min(WORLD_W, px+6)
        y0, y1 = max(0, py-5), min(WORLD_H, py+6)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_has_power = wm[wr, :] | pm[wr, :]
            if np.any(row_has_power):
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_has_power[wx]):
                        if (wx > 0 and bool(row_has_power[wx-1])) or \
                           (wx < WORLD_W-1 and bool(row_has_power[wx+1])):
                            if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                                return (Tool.WIRE, wx, wr)
            else:
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy, wr, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
                    if ib(bpx, wr) and bool(em[wr, bpx]):
                        return (Tool.WIRE, bpx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_has_power = wm[:, wc] | pm[:, wc]
            if np.any(col_has_power):
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_has_power[wy]):
                        if (wy > 0 and bool(col_has_power[wy-1])) or \
                           (wy < WORLD_H-1 and bool(col_has_power[wy+1])):
                            if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                                return (Tool.WIRE, wc, wy)
            else:
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2, wc, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
                    if ib(wc, bpy2) and bool(em[bpy2, wc]):
                        return (Tool.WIRE, wc, bpy2)

    elif phase == 2:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Add cross roads between horizontal wire rows
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx+1]
            for mid_y in range(wr1+2, wr2-1, 6):
                for wc in wire_cols:
                    for offset in [-1, 1]:
                        rcx = wc + offset
                        if not (0 < rcx < WORLD_W - 1):
                            continue
                        if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                            adj = (ib(rcx, mid_y-1) and bool(rm[mid_y-1, rcx])) or \
                                  (ib(rcx, mid_y+1) and bool(rm[mid_y+1, rcx]))
                            if adj:
                                return (Tool.ROAD, rcx, mid_y)

    elif phase == 5:
        # Add horizontal cross roads between wire cols
        for wc_idx in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[wc_idx], wire_cols[wc_idx+1]
            for mid_x in range(wc1+2, wc2-1, 6):
                for wr in wire_rows:
                    for offset in [-1, 1]:
                        ry = wr + offset
                        if not (0 < ry < WORLD_H - 1):
                            continue
                        if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                            adj = (ib(mid_x-1, ry) and bool(rm[ry, mid_x-1])) or \
                                  (ib(mid_x+1, ry) and bool(rm[ry, mid_x+1]))
                            if adj:
                                return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Dense interior road grid: add roads in the blocks between corridors
        # Target areas between wire corridors that are powered but not yet roaded
        needs_road = near_power & em & ~rm
        needs_road[0:3, :] = False
        needs_road[WORLD_H-3:, :] = False
        needs_road[:, 0:3] = False
        needs_road[:, WORLD_W-3:] = False
        # Avoid wire rows and cols
        for wr in wire_rows:
            needs_road[wr, :] = False
        for wc in wire_cols:
            needs_road[:, wc] = False
        nrys, nrxs = np.where(needs_road)
        if len(nrxs) > 0:
            # Find ones adjacent to existing roads
            road_adj = dilate(rm, 1) & needs_road
            rays, raxs = np.where(road_adj)
            if len(raxs) > 0:
                idx = (step * 17) % len(raxs)
                return (Tool.ROAD, int(raxs[idx]), int(rays[idx]))

    elif phase == 7:
        # Wire intersections at corridor crossings
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc-1])) or (wc < WORLD_W-1 and bool(wm[wr, wc+1]))
                col_ok = (wr > 0 and bool(wm[wr-1, wc])) or (wr < WORLD_H-1 and bool(wm[wr+1, wc]))
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 8:
        # Extend roads from existing roads toward powered areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H-3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W-3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    else:
        # Extend wire to unpowered road areas
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        # Score candidates: prefer near existing zones, near center, near roads
        scores = np.zeros(len(cxs2), dtype=float)
        road_dilated2 = dilate(rm, 1)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 0.5 if bool(road_dilated2[y, x]) else 0.0
            # Prefer being in one of the 6 main neighborhood blocks
            # between wire corridors
            in_block = False
            for wri in range(len(wire_rows)-1):
                wr1, wr2 = wire_rows[wri], wire_rows[wri+1]
                if wr1+2 <= y <= wr2-2:
                    for wci in range(len(wire_cols)-1):
                        wc1, wc2 = wire_cols[wci], wire_cols[wci+1]
                        if wc1+2 <= x <= wc2-2:
                            in_block = True
                            break
                if in_block:
                    break
            scores[i] += 1.0 if in_block else 0.0

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES (scaled to pop) ----
    if pop > 30:
        # Fire stations distributed across map
        fire_positions = [
            (30, 15), (70, 15), (110, 15),
            (10, 35), (50, 35), (85, 35), (115, 35),
            (30, 55), (70, 55), (110, 55),
            (10, 70), (50, 70), (85, 70), (115, 70),
            (30, 88), (70, 88), (110, 88),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (30, 45), (60, 45), (90, 45),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (30, 82), (60, 82), (90, 82),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (35, 32), (85, 32), (35, 65), (85, 65),
            (10, 50), (110, 50), (60, 15), (60, 85),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Upgrade to nuclear power at key spots
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (40, 50), (80, 50), (60, 5), (60, 94),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value  
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        # prefer placing parks near zones
        park_near_zone = park_cands & dilate(zone_tiles, 3)
        pys, pxs = np.where(park_near_zone)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: wire toward unpowered road areas ----
    needs_power2 = rm & ~near_power
    npys2, npxs2 = np.where(needs_power2)
    if len(npxs2) > 0:
        ti = (step * 23) % len(npxs2)
        tx, ty = int(npxs2[ti]), int(npys2[ti])
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs2[best_wi]), int(wire_ys2[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend roads ----
    road_ys3, road_xs3 = np.where(rm)
    if len(road_xs3) > 0:
        step_k = (step * 11) % len(road_xs3)
        for offset in range(min(len(road_xs3), 80)):
            k = (step_k + offset * 7) % len(road_xs3)
            rx2, ry2 = int(road_xs3[k]), int(road_ys3[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys4, wire_xs4 = np.where(wm)
    if len(wire_xs4) > 0:
        step_k2 = (step * 13) % len(wire_xs4)
        for offset in range(min(len(wire_xs4), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs4)
            wx2, wy2 = int(wire_xs4[k]), int(wire_ys4[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

