def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # Fast dilation using numpy shifts
    def dilate(mask, radius):
        result = mask.copy().astype(bool)
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure power plant coverage across whole map ----
    # Dense grid of plants every 20 cols x 18 rows
    plant_grid = []
    for py in range(12, 95, 18):
        for px in range(12, 115, 20):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire expansion - connect power to uncovered areas ----
    # Build adjacency to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src, dtype=bool)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)

    if len(wxs) > 0:
        # Find unpowered plant positions to connect first
        unpowered_plants = [(px, py) for px, py in plant_grid
                            if ib(px, py) and np.any(pm[max(0,py-1):py+2, max(0,px-1):px+2])
                            and not bool(near_power[py, px])]

        if unpowered_plants:
            best_dist, best_k = 1e9, 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants[:15])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist, best_k = 1e9, 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered empty areas (spread coverage)
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0:
            best_dist, best_k = 1e9, 0
            sample_idx = np.linspace(0, len(upxs)-1, min(60, len(upxs)), dtype=int)
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid - dense coverage everywhere with power ----
    # Road grid every 6 tiles
    road_grid = []
    for gy in range(5, 97, 6):
        for gx in range(5, 117, 6):
            road_grid.append((gx, gy))

    unpowered_road_targets = [(gx, gy) for gx, gy in road_grid
                              if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if unpowered_road_targets:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm, dtype=bool)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist, best_k = 1e9, 0
            targets_sample = unpowered_road_targets[:40]
            for i in range(min(len(rxs2), 600)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Start isolated road segment at target
            for gx, gy in unpowered_road_targets[:15]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        x0 = max(0, zx-1); x1 = min(WORLD_W, zx+2)
        y0 = max(0, zy-1); y1 = min(WORLD_H, zy+2)
        if x1-x0 < 3 or y1-y0 < 3:
            return False
        patch = tm[y0:y1, x0:x1]
        # Allow empty or existing zone tiles only
        blocked = ~em[y0:y1, x0:x1] & ~zone_tiles[y0:y1, x0:x1]
        return not np.any(blocked)

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer close to road, spread away from existing zones
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Prefer close to road, far from existing zones (spread out)
        score = road_dist * 2.0 + np.maximum(0, 10 - zone_dist) * 3.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled to population ----
    if pop > 80:
        fire_positions = [(fx, fy) for fy in range(10, 95, 12) for fx in range(10, 115, 12)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_positions = [(px2, py2) for py2 in range(14, 92, 14) for px2 in range(14, 112, 14)]
        for psx, psy in police_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_positions = [(pkx, pky) for pky in range(8, 96, 9) for pkx in range(8, 116, 9)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 700:
        stadium_locs = [(20, 15), (60, 15), (100, 15),
                        (20, 50), (60, 50), (100, 50),
                        (20, 82), (60, 82), (100, 82),
                        (40, 30), (80, 30), (40, 70), (80, 70)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        # Upgrade to nuclear power for large areas
        nuke_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                     (60, 10), (60, 88), (10, 50), (110, 50),
                     (45, 45), (75, 55)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-8), min(WORLD_W, nx+9)
                y0, y1 = max(0, ny-8), min(WORLD_H, ny+9)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 8), (75, 8), (55, 90), (75, 90),
                        (8, 30), (110, 30), (8, 65), (110, 65),
                        (30, 8), (95, 8)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]) and bool(near_road[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 90),
                        (15, 20), (105, 20), (15, 80), (105, 80),
                        (35, 8), (85, 8)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]) and bool(near_road[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: Extend road from existing road ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(4, 0), (-4, 0), (0, 4), (0, -4), (3, 3), (-3, 3), (5, 0), (0, 5)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from plant ----
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2), (3, 0), (0, 3)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at corners + center with wire spines and roads."""
    actions = []
    # Power plants at strategic positions
    plants = [(20, 20), (100, 20), (60, 50), (20, 80), (100, 80)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine horizontally and vertically
        for d in range(-4, 5):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px, py + d))
        # Roads adjacent to wire
        for d in range(-4, 5):
            actions.append((Tool.ROAD, px + d, py - 2))
            actions.append((Tool.ROAD, px + d, py + 2))
            actions.append((Tool.ROAD, px - 2, py + d))
            actions.append((Tool.ROAD, px + 2, py + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 55% res, 25% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 5 neighborhoods: corners + center
    neighborhoods = [
        (20, 20), (100, 20), (60, 50), (20, 80), (100, 80)
    ]

    def num_active():
        if pop < 100:   return 1
        if pop < 300:   return 2
        if pop < 600:   return 3
        if pop < 1000:  return 4
        return 5

    n_active = num_active()
    active_hoods = neighborhoods[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_hoods:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot
        for r in range(0, 15):
            placed = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE GRID: cross pattern from each plant ----
    spine_half = min(35, 12 + pop // 8)
    for (px, py) in active_hoods:
        # Vertical wire spine
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        for ny in range(spine_top, spine_bot + 1):
            if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                return (Tool.WIRE, px, ny)
        # Horizontal wire spine
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        for nx in range(spine_left, spine_right + 1):
            if ib(nx, py) and bool(em[py, nx]) and not bool(pm[py, nx]):
                return (Tool.WIRE, nx, py)

    # ---- CONNECT POWER PLANTS WITH WIRE ----
    if n_active >= 2:
        for i in range(len(active_hoods) - 1):
            px1, py1 = active_hoods[i]
            px2, py2 = active_hoods[i + 1]
            # Horizontal segment
            for cx in range(min(px1, px2), max(px1, px2) + 1):
                if ib(cx, py1) and bool(em[py1, cx]) and not bool(pm[py1, cx]):
                    return (Tool.WIRE, cx, py1)
            # Vertical segment
            for cy in range(min(py1, py2), max(py1, py2) + 1):
                if ib(px2, cy) and bool(em[cy, px2]) and not bool(pm[cy, px2]):
                    return (Tool.WIRE, px2, cy)

    # ---- ROAD GRID: ring roads around each neighborhood ----
    road_offsets = [-3, -2, -1, 0, 1, 2, 3]
    for idx, (px, py) in enumerate(active_hoods):
        # Vertical roads flanking wire
        for road_x in [px - 3, px + 3]:
            spine_top = max(2, py - spine_half)
            spine_bot = min(WORLD_H - 3, py + spine_half)
            for ny in range(spine_top, spine_bot + 1):
                if ib(road_x, ny) and bool(em[ny, road_x]) and not bool(pm[ny, road_x]):
                    return (Tool.ROAD, road_x, ny)
        # Horizontal roads flanking wire
        for road_y in [py - 3, py + 3]:
            spine_left = max(2, px - spine_half)
            spine_right = min(WORLD_W - 3, px + spine_half)
            for nx in range(spine_left, spine_right + 1):
                if ib(nx, road_y) and bool(em[road_y, nx]) and not bool(pm[road_y, nx]):
                    return (Tool.ROAD, nx, road_y)

    # ---- CROSS ROADS between neighborhoods ----
    if pop > 50 and n_active >= 2:
        for i in range(len(active_hoods) - 1):
            px1, py1 = active_hoods[i]
            px2, py2 = active_hoods[i + 1]
            mid_x = (px1 + px2) // 2
            mid_y = (py1 + py2) // 2
            # Horizontal road at midpoint
            for cx in range(min(px1, px2), max(px1, px2) + 1):
                if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                    return (Tool.ROAD, cx, mid_y)
            # Vertical road at midpoint
            for cy in range(min(py1, py2), max(py1, py2) + 1):
                if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                    return (Tool.ROAD, mid_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_hoods:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES: fire stations ----
    if pop > 50:
        fire_spots = [
            (10, 10), (60, 10), (110, 10),
            (10, 35), (60, 35), (110, 35),
            (10, 65), (60, 65), (110, 65),
            (10, 90), (60, 90), (110, 90),
            (35, 20), (85, 20), (35, 50), (85, 50), (35, 80), (85, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 15), (60, 15), (105, 15),
            (15, 50), (60, 50), (105, 50),
            (15, 85), (60, 85), (105, 85),
            (40, 30), (80, 30), (40, 70), (80, 70),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (40, 10), (80, 10), (40, 90), (80, 90),
            (10, 50), (110, 50), (60, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95),
            (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder
# Strategy: Multiple power plants spread across map, dense road grid, 
# balanced zones with civic services, reactive to actual tile state

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle + wires + roads."""
    actions = []
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Left plant
    actions.append((Tool.COALPOWER, 20, 30))
    # Right plant  
    actions.append((Tool.COALPOWER, 100, 30))
    # Bottom plant
    actions.append((Tool.COALPOWER, 60, 75))

    # Wires from central plant outward
    for dx in range(-5, 6):
        if dx != 0:
            actions.append((Tool.WIRE, 60 + dx, 50))
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, 60, 50 + dy))

    # Initial roads flanking central plant
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Dense 10x8 neighborhood grid covering most of the map
    nh_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106, 118]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    # Trim to valid positions
    nh_cols = [c for c in nh_cols if c < WORLD_W - 2]
    nh_rows = [r for r in nh_rows if r < WORLD_H - 2]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Power plants target locations - spread across the map
    plant_targets = [
        (60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
        (60, 15), (60, 85), (10, 50), (110, 50),
        (40, 50), (80, 50), (40, 15), (80, 15),
        (40, 85), (80, 85), (15, 10), (105, 10),
        (15, 90), (105, 90), (60, 50)
    ]

    # How many hoods active based on pop
    def num_active():
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 600:   return 14
        if pop < 1000:  return 20
        if pop < 2000:  return 32
        if pop < 4000:  return 45
        if pop < 8000:  return 60
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD PROXIMITY MASKS ----
    # Power proximity (within 8 tiles of wire or plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    # Use efficient numpy dilation
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            if abs(dx2) + abs(dy2) > 10: continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Road proximity (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Check each target; place if area has no plant nearby
    plant_phase = (step // 3) % len(plant_targets)
    for i in range(len(plant_targets)):
        tx, ty = plant_targets[(plant_phase + i) % len(plant_targets)]
        if not ib(tx, ty): continue
        x0, x1 = max(0, tx - 10), min(WORLD_W, tx + 11)
        y0, y1 = max(0, ty - 10), min(WORLD_H, ty + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find empty spot near target
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r: continue
                        nx, ny = tx + dx, ty + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE NETWORK ----
    # For each active hood, connect nearest plant with wires
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant to this hood using tile_map scan
    x0b, x1b = max(0, hx - 20), min(WORLD_W, hx + 21)
    y0b, y1b = max(0, hy - 20), min(WORLD_H, hy + 21)
    plant_ys, plant_xs = np.where(pm[y0b:y1b, x0b:x1b])

    if len(plant_xs) > 0:
        # Pick closest plant
        dists = np.abs(plant_xs - (hx - x0b)) + np.abs(plant_ys - (hy - y0b))
        best = np.argmin(dists)
        px_local = int(plant_xs[best]) + x0b
        py_local = int(plant_ys[best]) + y0b

        # Wire path: go horizontal first then vertical (L-shape)
        # Horizontal segment from plant to hood x
        if px_local != hx:
            step_dir = 1 if hx > px_local else -1
            for wx in range(px_local + step_dir, hx + step_dir, step_dir):
                if not ib(wx, py_local): break
                if bool(pm[py_local, wx]): continue
                if bool(wm[py_local, wx]): continue
                if not bool(em[py_local, wx]): continue
                # Only place if adjacent to existing wire/plant
                for adj in [-1, 1]:
                    ax = wx + adj
                    if ib(ax, py_local) and (bool(wm[py_local, ax]) or bool(pm[py_local, ax])):
                        return (Tool.WIRE, wx, py_local)

        # Vertical segment from hood x to hood y
        if py_local != hy:
            step_dir = 1 if hy > py_local else -1
            for wy in range(py_local + step_dir, hy + step_dir, step_dir):
                if not ib(hx, wy): break
                if bool(pm[wy, hx]): continue
                if bool(wm[wy, hx]): continue
                if not bool(em[wy, hx]): continue
                for adj in [-1, 1]:
                    ay = wy + adj
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, wy)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    # Connect between neighboring hoods on same row/col
    for hi, (hx1, hy1) in enumerate(active_hoods):
        if hi % 4 != step % 4: continue  # Only process 1/4 each step
        for hx2, hy2 in active_hoods:
            col_gap = abs(hx2 - hx1)
            row_gap = abs(hy2 - hy1)
            # Horizontal neighbor
            if hy1 == hy2 and 10 <= col_gap <= 14:
                mnx, mxx = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(mnx + 1, mxx):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical neighbor
            if hx1 == hx2 and 10 <= row_gap <= 14:
                mny, mxy = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(mny + 1, mxy):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROAD GRID ----
    # Build horizontal and vertical roads through powered areas
    # Use a grid pattern: roads every 4 tiles
    road_phase = (step // 2) % max(len(active_hoods), 1)
    hxr, hyr = active_hoods[road_phase]

    # Horizontal road at hyr-1 and hyr+1 (flanking wire spine)
    for ry in [hyr - 1, hyr + 1, hyr - 2, hyr + 2]:
        if not ib(hxr, ry): continue
        # Extend road in both directions from hood center
        for dx in range(-10, 11):
            rx = hxr + dx
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            # Place if adjacent to existing road or near wire
            adj_road = False
            for adx, ady in [(-1,0),(1,0),(0,-1),(0,1)]:
                if ib(rx+adx, ry+ady) and bool(rm[ry+ady, rx+adx]):
                    adj_road = True; break
            if adj_road and bool(nbr_power[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # Vertical road at hxr-1 and hxr+1
    for rx2 in [hxr - 1, hxr + 1, hxr - 2, hxr + 2]:
        if not ib(rx2, hyr): continue
        for dy in range(-10, 11):
            ry2 = hyr + dy
            if not ib(rx2, ry2): continue
            if not bool(em[ry2, rx2]): continue
            if bool(pm[ry2, rx2]): continue
            adj_road2 = False
            for adx2, ady2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                if ib(rx2+adx2, ry2+ady2) and bool(rm[ry2+ady2, rx2+adx2]):
                    adj_road2 = True; break
            if adj_road2 and bool(nbr_power[ry2, rx2]):
                return (Tool.ROAD, rx2, ry2)

    # ---- PHASE 5: EXTEND ROADS from existing road network ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 17) % len(road_xs)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 11) % len(road_xs)
            rxe, rye = int(road_xs[k]), int(road_ys[k])
            # Try to extend toward nearest unpowered hood
            best_dir = None
            best_score = -1
            for dx3, dy3 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx3, ny3 = rxe + dx3, rye + dy3
                if not ib(nx3, ny3): continue
                if not bool(em[ny3, nx3]): continue
                if bool(pm[ny3, nx3]): continue
                # Score: prefer direction toward active hoods without roads
                score = 0
                if bool(nbr_power[ny3, nx3]): score += 2
                # Check if this direction leads to a hood needing roads
                for (ahx, ahy) in active_hoods[:12]:
                    if abs(ahx - nx3) + abs(ahy - ny3) < abs(ahx - rxe) + abs(ahy - rye):
                        score += 1
                if score > best_score:
                    best_score = score
                    best_dir = (nx3, ny3)
            if best_dir and best_score > 1:
                return (Tool.ROAD, best_dir[0], best_dir[1])

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 35% RES, 30% COM, 35% IND
        if ir < 0.32:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        if rr < 0.32:
            return Tool.RESIDENTIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power, not on edge
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hoods
        best_dist2 = np.full(len(cxs2), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs2 - hx4) + np.abs(cys2 - hy4)
            best_dist2 = np.minimum(best_dist2, d)
        order2 = np.argsort(best_dist2)
        offset2 = (step * 7) % max(len(order2), 1)
        tool = pick_tool()
        for i in range(min(len(order2), 500)):
            k = order2[(offset2 + i) % len(order2)]
            zx2, zy2 = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 50:
        # Fire stations grid
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W-2, 18) 
                      for fy in range(12, WORLD_H-2, 18)]
        fs_idx = (step // 5) % max(len(fire_spots), 1)
        for i in range(len(fire_spots)):
            sx, sy = fire_spots[(fs_idx + i) % len(fire_spots)]
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(16, WORLD_W-2, 22) 
                        for py2 in range(16, WORLD_H-2, 22)]
        ps_idx = (step // 6) % max(len(police_spots), 1)
        for i in range(len(police_spots)):
            sx, sy = police_spots[(ps_idx + i) % len(police_spots)]
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75),
                         (60, 15), (60, 85), (12, 50), (108, 50),
                         (45, 45), (75, 45), (45, 55), (75, 55)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaport_spots = [(5, 90), (115, 90), (5, 10), (115, 10),
                         (60, 97), (60, 3), (30, 97), (90, 97)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airport_spots = [(45, 5), (75, 5), (45, 93), (75, 93),
                         (5, 45), (5, 65), (112, 45), (112, 65)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR UPGRADE ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                         (60, 15), (60, 85), (10, 50), (110, 50),
                         (40, 15), (80, 15), (40, 85), (80, 85)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 200 and step % 2 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cands)
        if len(park_xs2) > 0:
            idx2 = (step * 23) % len(park_xs2)
            py3, px3 = int(park_ys2[idx2]), int(park_xs2[idx2])
            if ib(px3, py3) and bool(em[py3, px3]):
                return (Tool.PARK, px3, py3)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k3 = (step * 13) % len(wire_xs2)
        for offset3 in range(min(len(wire_xs2), 100)):
            k3 = (step_k3 + offset3 * 7) % len(wire_xs2)
            wx3, wy3 = int(wire_xs2[k3]), int(wire_ys2[k3])
            # Prefer direction toward nearest unpowered hood
            for dx4, dy4 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx4, ny4 = wx3 + dx4, wy3 + dy4
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    # Check if this extends toward an active hood
                    for (ahx5, ahy5) in active_hoods[:8]:
                        if not bool(nbr_power[ahy5, ahx5]):
                            return (Tool.WIRE, nx4, ny4)

    # ---- FALLBACK: place plant near uncovered hood ----
    for (hxf, hyf) in active_hoods:
        if not bool(nbr_power[hyf, hxf]):
            for r in range(1, 15):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) != r and abs(dy5) != r: continue
                        nx5, ny5 = hxf + dx5, hyf + dy5
                        if ib(nx5, ny5) and bool(em[ny5, nx5]):
                            return (Tool.COALPOWER, nx5, ny5)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire crosses and flanking roads in a triangle."""
    actions = []
    plants = [(30, 25), (90, 25), (60, 75)]
    for (cx, cy) in plants:
        actions.append((Tool.COALPOWER, cx, cy))
        for dx in range(-4, 5):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-4, 5):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 2, cy + dy))
            actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Denser neighborhood grid: 8 cols x 7 rows = 56 neighborhoods
    nh_cols = [8, 24, 40, 56, 72, 88, 104, 116]
    nh_rows = [8, 22, 36, 50, 64, 78, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 20:    return 3
        if pop < 80:    return 6
        if pop < 200:   return 12
        if pop < 500:   return 20
        if pop < 1000:  return 28
        if pop < 2000:  return 36
        if pop < 4000:  return 46
        if pop < 7000:  return 52
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    def pick_tool():
        t = total_zones
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% RES, 35% COM, 25% IND (more commercial than parent)
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- BUILD NEIGHBOR POWER MASK ----
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- BUILD NEIGHBOR ROAD MASK ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    spine_range = 14
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    # Vertical spine
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj in [-1, 1]:
            ay = wy + adj
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)
    # Horizontal spine
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj in [-1, 1]:
            ax = wx + adj
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    col_gap = 16  # ~16 tiles between neighborhood cols
    row_gap = 14
    for (hx1, hy1) in active_hoods:
        for cgap in [col_gap - 1, col_gap, col_gap + 1]:
            right = (hx1 + cgap, hy1)
            if right in hood_set:
                for cx2 in range(hx1 + 1, hx1 + cgap):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
        for rgap in [row_gap - 1, row_gap, row_gap + 1]:
            bot = (hx1, hy1 + rgap)
            if bot in hood_set:
                for cy2 in range(hy1 + 1, hy1 + rgap):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    road_hood_idx = (step + 1) % max(len(active_hoods), 1)
    rhx, rhy = active_hoods[road_hood_idx]
    # Vertical road pairs at +/-2 from spine
    for rx in [rhx - 2, rhx + 2]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                    return (Tool.ROAD, rx, ry)
    # Horizontal road pairs
    for ry2 in [rhy - 2, rhy + 2]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                    return (Tool.ROAD, rcx, ry2)
    # Also flanking at +/-1 for denser road access
    for rx in [rhx - 1, rhx + 1]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                    return (Tool.ROAD, rx, ry)

    # ---- PHASE 5: ZONE PLACEMENT (closed-loop: react to powered+roaded tiles) ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = (np.abs(cxs - hx2).astype(float) + np.abs(cys - hy2).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scaled with pop, more aggressive) ----
    if pop > 50:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 15) for fy in range(10, WORLD_H, 15)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(14, WORLD_W, 18) for py2 in range(14, WORLD_H, 18)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(30, 20), (90, 20), (30, 50), (90, 50),
                    (30, 80), (90, 80), (60, 10), (60, 90),
                    (10, 35), (110, 35), (10, 65), (110, 65),
                    (55, 35), (65, 65), (45, 65), (75, 35)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8),
                    (60, 96), (60, 4), (30, 96), (90, 96)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        # Upgrade to nuclear power plants spread across map
        nuclear_spots = [
            (15, 5), (45, 5), (75, 5), (105, 5),
            (15, 95), (45, 95), (75, 95), (105, 95),
            (5, 25), (5, 50), (5, 75),
            (115, 25), (115, 50), (115, 75),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        airports = [(40, 5), (80, 5), (40, 94), (80, 94),
                    (5, 40), (115, 40), (5, 60), (115, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 100 and step % 3 == 0:
        park_candidates = np.where(em & nbr_road & nbr_power)
        park_ys, park_xs = park_candidates
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- DENSE ZONE INFILL near roads ----
    road_ys3, road_xs3 = np.where(rm)
    if len(road_xs3) > 0:
        step_k3 = (step * 17) % len(road_xs3)
        for offset in range(min(len(road_xs3), 300)):
            k = (step_k3 + offset * 11) % len(road_xs3)
            rx3, ry3 = int(road_xs3[k]), int(road_ys3[k])
            for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                              (2, 2), (-2, 2), (2, -2), (-2, -2),
                              (4, 0), (-4, 0), (0, 4), (0, -4),
                              (5, 0), (-5, 0), (0, 5), (0, -5)]:
                zx3, zy3 = rx3 + dx3, ry3 + dy3
                if ib(zx3, zy3) and bool(nbr_power[zy3, zx3]) and zone_clear(zx3, zy3):
                    return (pick_tool(), zx3, zy3)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx3 + dx, hy3 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                          (1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle + wire spines + road grid."""
    actions = []
    # Three power plants spread across the map
    plants = [(30, 30), (90, 30), (60, 70)]
    for (px, py) in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from each plant
        for dx in range(-6, 7):
            if dx != 0:
                actions.append((Tool.WIRE, px + dx, py))
        for dy in range(-6, 7):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
    # Road grid connecting the plants
    for rx in [28, 32, 58, 62, 88, 92]:
        for ry in range(15, 85, 1):
            actions.append((Tool.ROAD, rx, ry))
    for ry in [28, 32, 68, 72]:
        for rx in range(15, 105, 1):
            actions.append((Tool.ROAD, rx, ry))
    return actions[:80]  # keep init small


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ── NEIGHBORHOOD GRID: 5 rows × 6 cols = 30 nodes ──
    all_hoods = []
    for hy in range(15, 95, 16):
        for hx in range(15, 115, 16):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 10
        if pop < 1000:  return 16
        if pop < 2000:  return 22
        if pop < 4000:  return 28
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    stride = max(1, len(all_hoods) // n_active)
    active_hoods = all_hoods[::stride][:n_active]

    # ── NEIGHBOR MASKS ──
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ── PHASE 1: Ensure each active hood has a nearby power plant ──
    if funds > 2000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
            y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 14):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ── PHASE 2: Wire spines for active hoods ──
    spine = 12
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant for this hood
    x0p, x1p = max(0, hx - 14), min(WORLD_W, hx + 15)
    y0p, y1p = max(0, hy - 14), min(WORLD_H, hy + 15)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        px_l = int(plant_xs[0]) + x0p
        py_l = int(plant_ys[0]) + y0p
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend vertical wire spine
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        min_wr, max_wr = min(col_wire), max(col_wire)
        bot_t = min(WORLD_H - 3, hy + spine)
        top_t = max(2, hy - spine)
        if max_wr < bot_t:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_t:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    # Extend horizontal wire spine
    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        min_wc, max_wc = min(row_wire), max(row_wire)
        right_t = min(WORLD_W - 3, hx + spine)
        left_t = max(2, hx - spine)
        if max_wc < right_t:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_t:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # ── PHASE 3: Connect wires between nearby hoods ──
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i: continue
            if abs(hy1 - hy2) <= 3 and abs(hx1 - hx2) < 30:
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    mid_y2 = (hy1 + hy2) // 2
                    if ib(cx2, mid_y2) and bool(em[mid_y2, cx2]) and not bool(pm[mid_y2, cx2]):
                        if not bool(wm[mid_y2, cx2]):
                            has_l = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c])
                                        for c in range(max(0, cx2-3), cx2))
                            has_r = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c])
                                        for c in range(cx2+1, min(WORLD_W, cx2+4)))
                            if has_l or has_r:
                                return (Tool.WIRE, cx2, mid_y2)

    # ── PHASE 4: Roads flanking wire spines ──
    hood_idx2 = (step + 3) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 3
    for rx in [hx3 - 2, hx3 + 2]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::3]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 2, hy3 + 2]:
        if not ib(hx3, ry): continue
        for wc in row_wire3[cyc::3]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # Also build diagonal connector roads between hoods
    for rx2 in [hx3 - 1, hx3 + 1]:
        if not ib(rx2, hy3): continue
        for dy2 in range(-spine, spine + 1):
            ry2 = hy3 + dy2
            if not ib(rx2, ry2): continue
            if not bool(em[ry2, rx2]) or bool(pm[ry2, rx2]): continue
            if bool(wm[ry2, hx3]) or bool(pm[ry2, hx3]):
                return (Tool.ROAD, rx2, ry2)

    # ── PHASE 5: Zone placement with balanced R/C/I mix ──
    def pick_tool():
        # Target: 40% RES, 30% COM, 30% IND
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)

        # Clustering bonus
        if total_zones > 6:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs_arr), 999999.0)
                stride2 = max(1, len(zxs2) // 80)
                for ii in range(0, len(zxs2), stride2):
                    d2 = (np.abs(cxs_arr - zxs2[ii]).astype(float) +
                          np.abs(cys_arr - zys2[ii]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.55 + zone_prox * 0.45
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 11 + pop * 5) % max(len(order), 1)
        tool = pick_tool()
        for ii in range(min(len(order), 500)):
            k = order[(off + ii) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ── PHASE 6: Extend road network from existing roads ──
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ── PHASE 7: Civic services scaled to population ──
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(10, 95, 14) for fx in range(10, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(12, 90, 15) for px2 in range(12, 112, 15)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 19) % len(park_cands_x)
            py2b, px2b = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2b, py2b) and bool(em[py2b, px2b]):
                return (Tool.PARK, px2b, py2b)

    if pop > 300:
        stadium_locs = [(25, 25), (75, 25), (25, 75), (75, 75),
                        (50, 50), (10, 50), (110, 50), (50, 10), (50, 90),
                        (40, 40), (80, 60), (20, 60), (100, 40)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 5000:
        nuclear_locs = [(10, 10), (110, 10), (10, 90), (110, 90),
                        (60, 5), (5, 50), (115, 50), (60, 95),
                        (35, 20), (85, 20), (35, 80), (85, 80),
                        (20, 50), (100, 50), (60, 30), (60, 70),
                        (45, 15), (75, 15), (45, 85), (75, 85)]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75),
                        (30, 5), (90, 5), (30, 95), (90, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 93), (5, 45), (113, 45),
                        (5, 80), (113, 80)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ── PHASE 8: Nuclear upgrades for large cities ──
    if pop > 1200 and step % 2 == 0 and funds > 7000:
        nuc_spots = [(30, 30), (90, 30), (60, 70), (20, 20), (100, 20),
                     (20, 80), (100, 80), (50, 50), (70, 50),
                     (60, 20), (60, 80), (10, 50), (110, 50),
                     (35, 55), (85, 55), (35, 45), (85, 45)]
        for nx2, ny2 in nuc_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ── FALLBACK: extend wire from plants ──
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 80)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ── FALLBACK: extend wire from existing wire ──
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 17) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ── FALLBACK: new plant for uncovered hood ──
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants along the center spine with wires and roads."""
    actions = []
    # Place coal plants at 3 horizontal positions, vertically centered
    for px in [20, 60, 100]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Define a denser grid of anchors: 5 columns x 5 rows
    anchor_xs = [12, 32, 60, 88, 108]
    anchor_ys = [15, 32, 50, 68, 85]

    all_anchors = []
    for ax in anchor_xs:
        for ay in anchor_ys:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 5
        if pop < 300:   return 7
        if pop < 500:   return 10
        if pop < 750:   return 13
        if pop < 1000:  return 16
        if pop < 1500:  return 19
        if pop < 2000:  return 22
        return len(all_anchors)

    n_active = num_active()
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS for each active anchor ----
    # Each anchor needs a coal plant nearby
    for (px, py) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Try to place at anchor center first
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        # Search nearby
        for r in range(1, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINES: vertical wire through each anchor ----
    spine_half = min(35, 8 + pop // 8)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check wire coverage
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        plant_in_col = [r for r in range(spine_top, spine_bot + 1)
                        if ib(px, r) and bool(pm[r, px])]
        all_covered = wire_in_col + plant_in_col
        if not all_covered:
            for dy in range(-6, 7):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_cov = min(all_covered)
            max_cov = max(all_covered)
            if max_cov < spine_bot:
                nr = max_cov + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    if bool(em[nr, px]) or bool(wm[nr, px]):
                        return (Tool.WIRE, px, nr)
            if min_cov > spine_top:
                nr = min_cov - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    if bool(em[nr, px]) or bool(wm[nr, px]):
                        return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same y-level ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1 = row_anchors[i][0]
            x2 = row_anchors[i + 1][0]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor columns ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xc in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            y1 = col_anchors[i][1]
            y2 = col_anchors[i + 1][1]
            for cy in range(y1 + 1, y2):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # ---- ROAD BUILDING: flanking roads on both sides of each wire spine ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not wire_in_col:
            continue
        cycle = (step + idx * 5) % 2
        for wr in wire_in_col[cycle::2]:
            for rdx in [-1, 1]:
                rx = px + rdx
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- HORIZONTAL ROADS at each y-level (4 above and below anchor) ----
    for yl in y_levels:
        row_anchors_x = sorted([px for (px, py) in active_anchors if py == yl])
        if len(row_anchors_x) < 2:
            continue
        xl = row_anchors_x[0] - 1
        xr = row_anchors_x[-1] + 1
        for horiz_y in [yl - 4, yl + 4]:
            if not (ib(xl, horiz_y) and ib(xr, horiz_y)):
                continue
            for cx in range(xl, xr + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- CROSS ROADS connecting y-levels ----
    if pop > 40:
        for xc in x_cols:
            for rdx in [-2, 2]:
                rx = xc + rdx
                col_yl = sorted([py for (px, py) in active_anchors if px == xc])
                for i in range(len(col_yl) - 1):
                    y1 = col_yl[i]
                    y2 = col_yl[i + 1]
                    if not (ib(rx, y1) and ib(rx, y2)):
                        continue
                    for cy in range(y1 - 3, y2 + 4):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES: Fire stations ----
    if pop > 50:
        fire_spots = []
        for fx in [8, 22, 42, 62, 82, 98, 112]:
            for fy in [10, 25, 40, 55, 70, 85, 95]:
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    # ---- Police stations ----
    if pop > 200:
        police_spots = []
        for px2 in [15, 40, 65, 90, 110]:
            for py2 in [18, 38, 58, 78, 92]:
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # ---- Stadiums ----
    if pop > 500:
        stadium_spots = [
            (10, 10), (55, 10), (100, 10),
            (10, 90), (55, 90), (100, 90),
            (10, 50), (110, 50), (30, 30), (80, 30), (30, 70), (80, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- Nuclear power when pop high ----
    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (45, 45), (75, 45), (45, 55), (75, 55),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- Airports ----
    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94), (30, 6), (90, 6), (5, 25), (115, 25)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- Seaports ----
    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5), (30, 97), (90, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- Parks to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants spread across map + wire spine + initial roads"""
    actions = []
    # Three coal plants: left, center, right
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Wire connecting them horizontally
    for x in range(22, 60):
        actions.append((Tool.WIRE, x, 50))
    for x in range(62, 100):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire from center plant upward and downward
    for y in range(40, 50):
        actions.append((Tool.WIRE, 60, y))
    for y in range(51, 62):
        actions.append((Tool.WIRE, 60, y))
    # Initial roads forming a cross around center plant
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for y in range(38, 63):
        actions.append((Tool.ROAD, 20, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 100, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: ~45% res, 30% com, 25% ind
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Power plant grid (denser than parent, every 16 tiles) ---
    plant_positions = []
    for py in range(12, 96, 16):
        for px in range(12, 116, 16):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Wire expansion toward unpowered areas ---
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        unpowered_plants = [(px, py) for px, py in plant_positions
                            if ib(px, py) and not bool(near_power[py, px])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0:
            best_dist = 1e9
            best_k = 0
            sample = np.random.choice(len(upxs), min(50, len(upxs)), replace=False)
            for i in range(min(len(wxs), 300)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Dense road grid (every 5 tiles for denser zoning) ---
    road_targets = []
    for gy in range(5, 97, 5):
        for gx in range(5, 117, 5):
            road_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:40]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement with explicit mixed zoning ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Prefer close to road, spread from existing zones
        score = road_dist * 1.5 + np.maximum(0, 8 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Explicitly vary tool by step to enforce mix
        step_mod = step % 10
        if step_mod < 5:
            tool = Tool.RESIDENTIAL
        elif step_mod < 7:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL
        # Override with ratio-based pick if ratio very off
        tool = pick_tool() if (ind_count / max(total_zones,1) < 0.15 or 
                                com_count / max(total_zones,1) < 0.20) else tool

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    if pop > 80:
        fire_positions = [(fx, fy) for fy in range(8, 95, 8) for fx in range(8, 115, 8)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_positions = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 10)]
        for psx, psy in police_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_positions = [(pkx, pky) for pky in range(7, 95, 7) for pkx in range(7, 115, 7)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 600:
        stadium_locs = [(25, 20), (85, 20), (25, 70), (85, 70),
                        (55, 15), (55, 85), (15, 50), (105, 50),
                        (45, 35), (75, 65), (45, 65), (75, 35),
                        (35, 50), (95, 50)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (60, 10), (60, 90), (10, 50), (110, 50),
                     (40, 10), (80, 10), (40, 90), (80, 90)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1500:
        airport_locs = [(55, 8), (75, 8), (55, 91), (75, 91),
                        (8, 30), (110, 30), (8, 65), (110, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91),
                        (15, 20), (105, 20), (15, 80), (105, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: roads near power plants ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (4, 0), (0, 4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power plant + cross wire + flanking roads"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Short wire cross from center
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Flanking roads
    for x in range(55, 66):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    for y in range(45, 56):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(pm[nr, nc]):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    # Power/road coverage
    near_power = dilate(wm | pm, 8)
    near_road = dilate(rm, 2)

    # ---- PLANT GRID: 5x5 across map ----
    plant_cols = [12, 32, 52, 72, 92, 112]
    plant_rows = [10, 26, 42, 58, 74, 90]
    plant_positions = [(px, py) for px in plant_cols for py in plant_rows]

    # Wire corridors: horizontal and vertical grid
    wire_rows = [8, 18, 28, 38, 48, 58, 68, 78, 88, 96]
    wire_cols = [6, 18, 30, 42, 54, 66, 78, 90, 102, 114]

    # ---- PHASE 1: ENSURE PLANTS EXIST ----
    # Unlock more plants as population grows
    def num_plants_needed():
        if pop < 100:   return 4
        if pop < 500:   return 8
        if pop < 1000:  return 12
        if pop < 2000:  return 18
        if pop < 4000:  return 24
        return len(plant_positions)

    n_plants = num_plants_needed()
    # Spread plant positions across map
    step_p = max(1, len(plant_positions) // n_plants)
    active_plants = plant_positions[::step_p][:n_plants]

    for px, py in active_plants:
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID ----
    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                # Seed from nearest plant
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy, wr, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
                    if ib(bpx, wr) and bool(em[wr, bpx]):
                        return (Tool.WIRE, bpx, wr)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        if (wx > 0 and bool(row_power[wx - 1])) or \
                           (wx < WORLD_W - 1 and bool(row_power[wx + 1])):
                            if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2, wc, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
                    if ib(wc, bpy2) and bool(em[bpy2, wc]):
                        return (Tool.WIRE, wc, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        if (wy > 0 and bool(col_power[wy - 1])) or \
                           (wy < WORLD_H - 1 and bool(col_power[wy + 1])):
                            if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Wire intersections: connect horizontal and vertical corridors
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc - 1])) or (wc < WORLD_W - 1 and bool(wm[wr, wc + 1]))
                col_ok = (wr > 0 and bool(wm[wr - 1, wc])) or (wr < WORLD_H - 1 and bool(wm[wr + 1, wc]))
                if row_ok and col_ok and bool(em[wr, wc]) and not bool(pm[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 5:
        # Cross-connect roads between wire rows (vertical connectors)
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            mid_y = (wr1 + wr2) // 2
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                        adj = (ib(rcx, mid_y - 1) and bool(rm[mid_y - 1, rcx])) or \
                              (ib(rcx, mid_y + 1) and bool(rm[mid_y + 1, rcx]))
                        if adj:
                            return (Tool.ROAD, rcx, mid_y)

    elif phase == 6:
        # Cross-connect roads between wire cols (horizontal connectors)
        for wc_idx in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            mid_x = (wc1 + wc2) // 2
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not (0 < ry < WORLD_H - 1):
                        continue
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x - 1, ry) and bool(rm[ry, mid_x - 1])) or \
                              (ib(mid_x + 1, ry) and bool(rm[ry, mid_x + 1]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 7:
        # Wire toward unpowered roads
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys2, wire_xs2 = np.where(wm | pm)
            if len(wire_xs2) > 0:
                dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs2[best_wi]), int(wire_ys2[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Extend road network toward powered empty areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H - 3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W - 3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    else:
        # Extend wire from existing wire toward unpowered areas
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            step_k2 = (step * 13) % len(wire_xs3)
            for offset in range(min(len(wire_xs3), 60)):
                k = (step_k2 + offset * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Don't place zones on wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 4)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 0.5 / (1.0 + abs(x - 60) / 60.0 + abs(y - 50) / 50.0)
            # Bonus for being near multiple roads
            if bool(near_road[y, x]):
                scores[i] += 1.0

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_positions = [
            (12, 8), (36, 8), (60, 8), (84, 8), (108, 8),
            (12, 28), (36, 28), (60, 28), (84, 28), (108, 28),
            (12, 48), (36, 48), (60, 48), (84, 48), (108, 48),
            (12, 68), (36, 68), (60, 68), (84, 68), (108, 68),
            (12, 88), (36, 88), (60, 88), (84, 88), (108, 88),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_positions = [
            (24, 18), (48, 18), (72, 18), (96, 18),
            (24, 38), (48, 38), (72, 38), (96, 38),
            (24, 58), (48, 58), (72, 58), (96, 58),
            (24, 78), (48, 78), (72, 78), (96, 78),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 23), (90, 23), (30, 53), (90, 53),
            (30, 73), (90, 73), (60, 13), (60, 83),
            (15, 43), (105, 43), (15, 63), (105, 63),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
            (30, 50), (90, 50), (5, 25), (115, 25),
            (5, 75), (115, 75), (30, 15), (90, 15),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 94), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 100 and step % 4 == 0:
        park_cands_mask = em & near_road & near_power
        pys, pxs = np.where(park_cands_mask)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend roads from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious multi-cluster city builder
# Strategy: 4 power plants spread across map, dense road grid, aggressive zoning
# Closed-loop reactive to population and map state

def init(obs, state):
    """Bootstrap: 4 coal plants at quadrant centers + wire spines + roads."""
    actions = []
    # Four power plant positions (quadrant centers)
    plants = [(30, 25), (90, 25), (30, 75), (90, 75)]
    for (px, py) in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from each plant
        for dx in range(-4, 5):
            if dx != 0:
                actions.append((Tool.WIRE, px + dx, py))
        for dy in range(-4, 5):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
    # Central wire spine connecting all plants
    # Horizontal spine at y=25 from x=30 to x=90
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 25))
    # Horizontal spine at y=75
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 75))
    # Vertical spine at x=30 from y=25 to y=75
    for y in range(26, 75):
        actions.append((Tool.WIRE, 30, y))
    # Vertical spine at x=90
    for y in range(26, 75):
        actions.append((Tool.WIRE, 90, y))
    # Roads near plants
    for (px, py) in plants:
        for dx in range(-3, 4):
            actions.append((Tool.ROAD, px + dx, py - 1))
            actions.append((Tool.ROAD, px + dx, py + 1))
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- DEFINE CLUSTERS across the whole map ----
    # 5 columns x 5 rows = 25 clusters, spaced evenly
    # Columns: 12, 32, 52, 72, 92, 112 -> 6 cols
    # Rows: 10, 25, 42, 58, 75, 90 -> 6 rows
    nh_cols = [12, 32, 52, 72, 92, 112]
    nh_rows = [10, 25, 42, 58, 75, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 10
        if pop < 1000:  return 16
        if pop < 2000:  return 22
        if pop < 4000:  return 30
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- POWER/ROAD NEIGHBOR MAPS ----
    power_src = wm | pm

    def dilate_mask(src, radius):
        out = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                if abs(dx) + abs(dy) > radius:
                    continue
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                if r1 > r0 and c1 > c0:
                    out[r0:r1, c0:c1] |= src[sr0:sr1, sc0:sc1]
        return out

    nbr_power = dilate_mask(power_src, 5)
    nbr_road = dilate_mask(rm, 3)

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANT near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID ----
    # Build a grid of wires: horizontal at each nh_row, vertical at each nh_col
    # Connect plants to grid
    # Process one segment per step
    wire_tasks = []
    for hy in nh_rows:
        for hx in nh_cols:
            wire_tasks.append(('h', hx, hy))
            wire_tasks.append(('v', hx, hy))

    # Add inter-hood wires
    for i, hx1 in enumerate(nh_cols[:-1]):
        hx2 = nh_cols[i + 1]
        for hy in nh_rows:
            for wx in range(hx1 + 1, hx2):
                wire_tasks.append(('segment', wx, hy))

    for i, hy1 in enumerate(nh_rows[:-1]):
        hy2 = nh_rows[i + 1]
        for hx in nh_cols:
            for wy in range(hy1 + 1, hy2):
                wire_tasks.append(('segment', hx, wy))

    spine_range = 6
    task_idx = step % max(len(wire_tasks), 1)
    for i in range(len(wire_tasks)):
        t = wire_tasks[(task_idx + i) % len(wire_tasks)]
        if t[0] == 'h':
            _, hx, hy = t
            for dy in range(-spine_range, spine_range + 1):
                wy = hy + dy
                if not ib(hx, wy): continue
                if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
                if not bool(em[wy, hx]): continue
                for adj in [-1, 1]:
                    ay = wy + adj
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, wy)
        elif t[0] == 'v':
            _, hx, hy = t
            for dx in range(-spine_range, spine_range + 1):
                wx = hx + dx
                if not ib(wx, hy): continue
                if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                for adj in [-1, 1]:
                    ax = wx + adj
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, wx, hy)
        elif t[0] == 'segment':
            _, wx, wy = t
            if bool(wm[wy, wx]) or bool(pm[wy, wx]): continue
            if not bool(em[wy, wx]): continue
            # Place if adjacent wire/plant exists
            for adj_dx, adj_dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                ax, ay = wx + adj_dx, wy + adj_dy
                if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                    return (Tool.WIRE, wx, wy)
        break

    # ---- PHASE 3: ROAD GRID ----
    # Roads flanking wire spines (offset +/-1 from wire spines)
    road_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[road_idx % len(active_hoods)]

    # Build a dense road grid around each hood:
    # Roads at hx-1, hx+1 (vertical roads) and hy-1, hy+1 (horizontal roads)
    for offset_pair in [(-1, 1), (-2, 2)]:
        for rx in [hx + offset_pair[0], hx + offset_pair[1]]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(rm[ry, rx]): continue
                if bool(pm[ry, rx]): continue
                if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
                if bool(nbr_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

        for ry2 in [hy + offset_pair[0], hy + offset_pair[1]]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(rm[ry2, rcx]): continue
                if bool(pm[ry2, rcx]): continue
                if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
                if bool(nbr_power[ry2, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 4: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target mix: 35% RES, 35% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: powered + road access + empty
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 5: EXTEND ROADS from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (population-gated) ----
    if pop > 80:
        for fx in range(10, WORLD_W, 18):
            for fy in range(10, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(nbr_road[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for px2 in range(14, WORLD_W, 20):
            for py2 in range(14, WORLD_H, 20):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(nbr_road[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        for sx in range(20, WORLD_W, 30):
            for sy in range(20, WORLD_H, 30):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaport_spots = [(10, 92), (110, 92), (10, 8), (110, 8),
                         (60, 95), (60, 5), (35, 95), (85, 95)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airport_spots = [(18, 6), (55, 6), (85, 6), (18, 93), (55, 93), (85, 93)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear plants for high-pop efficiency
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(60, 50), (15, 20), (105, 20), (15, 80), (105, 80),
                         (42, 12), (78, 12), (42, 88), (78, 88), (60, 12), (60, 88)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks to boost land value
    if pop > 100 and step % 5 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 23) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: plant at uncovered hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 15):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

# Ambitious city builder combining best of both parents
# Strategy: Dense grid of neighborhoods, smart power/road/zone placement
# More neighborhoods, better coverage, smarter civic services

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-5, 6):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 7 cols x 6 rows = 42 neighborhoods ----
    # Spread across full 120x100 map
    nh_cols = [10, 28, 46, 60, 74, 92, 110]
    nh_rows = [10, 25, 40, 58, 73, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 7
        if pop < 1000:  return 12
        if pop < 2000:  return 18
        if pop < 4000:  return 26
        if pop < 7000:  return 34
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly across the grid
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
        y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try anchor first, then spiral outward
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    # Each hood gets a vertical wire spine at hx and horizontal at hy
    spine_range = 12
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Vertical wire spine at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal wire spine at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Right neighbor
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 20:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Bottom neighbor
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 20:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods) // 2 + 1, 1) != 0:
            continue
        # Roads at hx-1 and hx+1 (flanking vertical spine)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Roads at hy-1 and hy+1 (flanking horizontal spine)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers: empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 22) for py2 in range(18, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (60, 30), (90, 30),
            (30, 50), (60, 50), (90, 50),
            (30, 70), (60, 70), (90, 70),
            (15, 15), (105, 15), (15, 85), (105, 85)
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 45), (6, 65), (114, 45), (114, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop cities ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [
            (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (10, 50), (110, 50), (60, 10), (60, 90),
            (20, 10), (100, 10), (20, 90), (100, 90)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants spread across the map with wire+road seeds."""
    actions = []
    # Three plants at different positions for fast initial coverage
    plants = [(20, 50), (60, 50), (100, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from plant
        for dx in range(-6, 7):
            if dx != 0:
                actions.append((Tool.WIRE, px + dx, py))
        for dy in range(-6, 7):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking vertical wire spine
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- 5 columns x 4 rows = 20 neighborhoods ----
    nh_cols = [12, 35, 60, 85, 108]
    nh_rows = [12, 37, 62, 87]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 5
        if pop < 350:   return 8
        if pop < 700:   return 12
        if pop < 1200:  return 16
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Evenly spread across all 20 hoods
    step_size = len(all_hoods) / n_active
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MASKS ----
    power_src = wm | pm

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: ~33% each, but prioritize industrial early for jobs
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 15):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE SPINES from plant toward hood centers ----
    spine_range = 16
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0, x1 = max(0, hx - 16), min(WORLD_W, hx + 17)
    y0, y1 = max(0, hy - 16), min(WORLD_H, hy + 17)
    local_pm = pm[y0:y1, x0:x1]
    plant_ys_l, plant_xs_l = np.where(local_pm)

    if len(plant_xs_l) > 0:
        px_local = int(plant_xs_l[0]) + x0
        py_local = int(plant_ys_l[0]) + y0

        # Wire from plant to hood (vertical first)
        if py_local != hy:
            sdir = 1 if hy > py_local else -1
            for wy in range(py_local + sdir, hy + sdir, sdir):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        if px_local != hx:
            sdir = 1 if hx > px_local else -1
            for wx in range(px_local + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

        # Extend vertical spine from hood center
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(pm[wy, hx]) or bool(wm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Extend horizontal spine from hood center
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            # Horizontal neighbors (same row)
            if hy1 == hy2 and abs(hx2 - hx1) <= 30:
                mnx, mxx = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(mnx + 1, mxx):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical neighbors (same col)
            if hx1 == hx2 and abs(hy2 - hy1) <= 30:
                mny, mxy = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(mny + 1, mxy):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    # Vertical roads flanking vertical wire spine (spine at hx3)
    for rx in [hx3 - 1, hx3 + 1]:
        if not ib(rx, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                return (Tool.ROAD, rx, ry)

    # Horizontal roads flanking horizontal wire spine (spine at hy3)
    for ry2 in [hy3 - 1, hy3 + 1]:
        if not ib(hx3, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx3 + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: CROSS-ROADS between hoods ----
    if pop > 20:
        for i, (hx1, hy1) in enumerate(active_hoods):
            for j, (hx2, hy2) in enumerate(active_hoods):
                if i >= j: continue
                if hy1 == hy2 and abs(hx2 - hx1) <= 30:
                    mnx2, mxx2 = min(hx1, hx2), max(hx1, hx2)
                    for cy2 in [hy1 - 1, hy1 + 1]:
                        if not ib(mnx2, cy2): continue
                        for cx3 in range(mnx2, mxx2 + 1):
                            if not ib(cx3, cy2): continue
                            if not bool(em[cy2, cx3]) and not bool(rm[cy2, cx3]): continue
                            if bool(pm[cy2, cx3]): continue
                            has_adj = any(ib(cx3+ax2, cy2+ay2) and bool(rm[cy2+ay2, cx3+ax2])
                                         for ax2, ay2 in [(-1,0),(1,0),(0,-1),(0,1)])
                            if has_adj and bool(em[cy2, cx3]):
                                return (Tool.ROAD, cx3, cy2)

    # ---- PHASE 6: ZONE PLACEMENT (primary objective) ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: CIVIC SERVICES (reactive) ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [(px2, py2) for px2 in range(16, WORLD_W, 22) for py2 in range(16, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(24,25),(96,25),(24,75),(96,75),
                    (60,15),(60,85),(12,50),(108,50),(48,50),(72,50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(6,94),(114,94),(6,6),(114,6),(60,97),(60,3)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3500:
        airports = [(40,5),(80,5),(40,94),(80,94),(5,40),(5,70),(114,40),(114,70)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR UPGRADE for mature cities ----
    if pop > 2500 and step % 4 == 0:
        nuclear_spots = [(12,12),(108,12),(12,87),(108,87),
                         (60,50),(35,37),(85,37),(35,62),(85,62),
                         (60,25),(60,75),(25,50),(95,50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 150 and step % 5 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- FALLBACK: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder
# Strategy: 
# - 6 coal plants in a 2x3 grid covering the map
# - Dense wire grid connecting all plants
# - Road grid with 6-tile spacing for maximum zone coverage
# - Reactive zone placement based on actual road/wire coverage
# - Aggressive civic services placement

def init(obs, state):
    """Bootstrap: 2 central coal plants with wire and road starters."""
    actions = []
    # Two central plants to get things going
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Roads flanking the wire
    for x in range(28, 93):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% residential, 30% commercial, 20% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 power plant anchor locations in 2 columns x 3 rows
    plant_anchors = [
        (20, 20), (60, 20), (100, 20),
        (20, 70), (60, 70), (100, 70),
    ]

    def num_active_plants():
        if pop < 50:   return 2
        if pop < 150:  return 3
        if pop < 300:  return 4
        if pop < 600:  return 5
        return 6

    n_plants = num_active_plants()
    active_plants = plant_anchors[:n_plants]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_plants:
        x0 = max(0, px - 10); x1 = min(WORLD_W, px + 11)
        y0 = max(0, py - 10); y1 = min(WORLD_H, py + 11)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Need a plant near this anchor
        for r in range(0, 12):
            placed = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if r > 0 and abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if placed:
                break

    # ---- BUILD WIRE GRID ----
    # Horizontal wires at y=20, y=70 connecting plants
    # Vertical wire at x=20, x=60, x=100 connecting rows
    wire_rows = [20, 70]
    wire_cols = [20, 60, 100]

    # Extend horizontal wires
    for wy in wire_rows:
        for wx in range(0, WORLD_W):
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                # Check if adjacent to existing wire or plant
                has_neighbor = False
                for ddx in [-1, 1]:
                    nx = wx + ddx
                    if ib(nx, wy) and (bool(wm[wy, nx]) or bool(pm[wy, nx])):
                        has_neighbor = True
                if has_neighbor:
                    return (Tool.WIRE, wx, wy)

    # Extend vertical wires
    for wc in wire_cols:
        for wy in range(0, WORLD_H):
            if ib(wc, wy) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                has_neighbor = False
                for ddy in [-1, 1]:
                    ny = wy + ddy
                    if ib(wc, ny) and (bool(wm[ny, wc]) or bool(pm[ny, wc])):
                        has_neighbor = True
                if has_neighbor:
                    return (Tool.WIRE, wc, wy)

    # Additional horizontal wires at y=45 (middle) when we have enough plants
    if n_plants >= 3:
        mid_wire_y = 45
        for wx in range(0, WORLD_W):
            if ib(wx, mid_wire_y) and bool(em[mid_wire_y, wx]) and not bool(pm[mid_wire_y, wx]):
                has_neighbor = False
                for ddx in [-1, 1]:
                    nx = wx + ddx
                    if ib(nx, mid_wire_y) and (bool(wm[mid_wire_y, nx]) or bool(pm[mid_wire_y, nx])):
                        has_neighbor = True
                # Also connect to vertical wire cols
                if wc in wire_cols:
                    pass
                if has_neighbor:
                    return (Tool.WIRE, wx, mid_wire_y)

    # ---- BUILD ROAD GRID ----
    # Horizontal roads at y = 14, 26, 38, 50, 62, 74, 86 (every 12 rows)
    road_row_ys = list(range(14, WORLD_H - 5, 12))
    road_col_xs = list(range(8, WORLD_W - 5, 12))

    # Build horizontal roads first (reactive: extend existing roads)
    for ry in road_row_ys:
        road_cells = [(x, ry) for x in range(WORLD_W) if ib(x, ry) and bool(rm[ry, x])]
        if not road_cells:
            # Start one near a wire
            for rx in range(0, WORLD_W):
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Near wire?
                    near_wire = False
                    for ddy in range(-8, 9):
                        ny = ry + ddy
                        if ib(rx, ny) and (bool(wm[ny, rx]) or bool(pm[ny, rx])):
                            near_wire = True
                    if near_wire:
                        return (Tool.ROAD, rx, ry)
        else:
            # Extend rightward
            max_rx = max(x for (x, y) in road_cells)
            nr = max_rx + 1
            if ib(nr, ry) and bool(em[ry, nr]) and not bool(pm[ry, nr]):
                return (Tool.ROAD, nr, ry)
            # Extend leftward
            min_rx = min(x for (x, y) in road_cells)
            nl = min_rx - 1
            if ib(nl, ry) and bool(em[ry, nl]) and not bool(pm[ry, nl]):
                return (Tool.ROAD, nl, ry)

    # Build vertical roads
    for cx in road_col_xs:
        road_cells_v = [(cx, y) for y in range(WORLD_H) if ib(cx, y) and bool(rm[y, cx])]
        if not road_cells_v:
            for ry in range(0, WORLD_H):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    near_wire = any(bool(wm[ry, x]) or bool(pm[ry, x]) 
                                   for x in range(max(0, cx-8), min(WORLD_W, cx+9)))
                    if near_wire:
                        return (Tool.ROAD, cx, ry)
        else:
            max_ry = max(y for (x, y) in road_cells_v)
            nb = max_ry + 1
            if ib(cx, nb) and bool(em[nb, cx]) and not bool(pm[nb, cx]):
                return (Tool.ROAD, cx, nb)
            min_ry = min(y for (x, y) in road_cells_v)
            nt = min_ry - 1
            if ib(cx, nt) and bool(em[nt, cx]) and not bool(pm[nt, cx]):
                return (Tool.ROAD, cx, nt)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    # Road proximity: within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/power proximity: within 8 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_plants:
            d = (np.abs(cxs - px).astype(float) +
                 np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = [
            (5, 5), (35, 5), (65, 5), (95, 5),
            (5, 33), (35, 33), (65, 33), (95, 33),
            (5, 61), (35, 61), (65, 61), (95, 61),
            (5, 89), (35, 89), (65, 89), (95, 89),
            (115, 5), (115, 33), (115, 61), (115, 89),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (15, 75), (45, 75), (75, 75), (105, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (10, 10), (55, 10), (100, 10),
            (10, 50), (55, 50), (100, 50),
            (10, 90), (55, 90), (100, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (38, 5), (78, 5), (38, 95), (78, 95),
            (5, 38), (115, 38), (5, 68), (115, 68),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 94), (115, 94), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- INFILL: zones near roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k3 = (step * 17) % max(len(road_xs2), 1)
        checked2 = 0
        for offset in range(min(len(road_xs2), 400)):
            k = (step_k3 + offset * 11) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (2, -2), (-2, -2),
                              (4, 0), (-4, 0), (0, 4), (0, -4)]:
                zx3, zy3 = rx3 + dx3, ry3 + dy3
                if ib(zx3, zy3) and bool(nbr_wire[zy3, zx3]) and zone_clear(zx3, zy3):
                    return (pick_tool(), zx3, zy3)
            checked2 += 1
            if checked2 > 300:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 200)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx2, ry2 = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: compact central cluster with power + roads + zones"""
    actions = []
    # Two coal plants near center
    actions.append((Tool.COALPOWER, 55, 48))
    actions.append((Tool.COALPOWER, 65, 48))
    # Wire spine connecting them horizontally
    for x in range(53, 68):
        actions.append((Tool.WIRE, x, 48))
    # Vertical wire spines down from plants
    for y in range(44, 56):
        actions.append((Tool.WIRE, 55, y))
        actions.append((Tool.WIRE, 65, y))
    # Two horizontal roads near center
    for x in range(45, 80):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 54))
    # Two vertical roads
    for y in range(40, 62):
        actions.append((Tool.ROAD, 48, y))
        actions.append((Tool.ROAD, 72, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 'infrastructure'
        state['plant_idx'] = 0
        state['road_idx'] = 0
        state['zone_idx'] = 0

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone ratio: 40% res, 35% com, 25% ind
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Plant grid — place coal plants across map ---
    # Plants every 18 cols, 18 rows, avoiding edges
    plant_positions = []
    for py in range(12, WORLD_H - 12, 18):
        for px in range(12, WORLD_W - 12, 18):
            plant_positions.append((px, py))

    for ppx, ppy in plant_positions:
        x0, x1 = max(0, ppx - 6), min(WORLD_W, ppx + 7)
        y0, y1 = max(0, ppy - 6), min(WORLD_H, ppy + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # --- PHASE 2: Wire grid connecting plants ---
    # Horizontal wires at plant rows
    plant_rows = list(range(12, WORLD_H - 12, 18))
    plant_cols = list(range(12, WORLD_W - 12, 18))

    for wr in plant_rows:
        for x in range(10, WORLD_W - 10):
            if bool(em[wr, x]) and not bool(pm[wr, x]):
                # Check if this row needs wire (no wire yet between two plants)
                if not bool(wm[wr, x]):
                    # Only extend wire if there's power on that row
                    row_power = wm[wr, :] | pm[wr, :]
                    if row_power.any():
                        idx = np.where(row_power)[0]
                        left = int(idx[0])
                        right = int(idx[-1])
                        if right < WORLD_W - 11:
                            nx = right + 1
                            if bool(em[wr, nx]) and not bool(pm[wr, nx]):
                                return (Tool.WIRE, nx, wr)
                        if left > 10:
                            nx = left - 1
                            if bool(em[wr, nx]) and not bool(pm[wr, nx]):
                                return (Tool.WIRE, nx, wr)
                        break

    for wc in plant_cols:
        for y in range(10, WORLD_H - 10):
            if bool(em[y, wc]) and not bool(pm[y, wc]):
                if not bool(wm[y, wc]):
                    col_power = wm[:, wc] | pm[:, wc]
                    if col_power.any():
                        idx = np.where(col_power)[0]
                        top = int(idx[0])
                        bot = int(idx[-1])
                        if bot < WORLD_H - 11:
                            ny = bot + 1
                            if bool(em[ny, wc]) and not bool(pm[ny, wc]):
                                return (Tool.WIRE, wc, ny)
                        if top > 10:
                            ny = top - 1
                            if bool(em[ny, wc]) and not bool(pm[ny, wc]):
                                return (Tool.WIRE, wc, ny)
                        break

    # --- PHASE 3: Dense road grid ---
    # Roads offset from plant/wire rows by 5
    road_rows_target = []
    for wr in plant_rows:
        road_rows_target.append(wr - 5)
        road_rows_target.append(wr + 5)
    road_cols_target = []
    for wc in plant_cols:
        road_cols_target.append(wc - 5)
        road_cols_target.append(wc + 5)

    road_rows_target = sorted(set(r for r in road_rows_target if 4 < r < WORLD_H - 4))
    road_cols_target = sorted(set(c for c in road_cols_target if 4 < c < WORLD_W - 4))

    for rr in road_rows_target:
        row_rd = rm[rr, :]
        if row_rd.any():
            idx = np.where(row_rd)[0]
            right = int(idx[-1])
            if right < WORLD_W - 5:
                nx = right + 1
                if bool(em[rr, nx]) and not bool(pm[rr, nx]):
                    return (Tool.ROAD, nx, rr)
            left = int(idx[0])
            if left > 4:
                nx = left - 1
                if bool(em[rr, nx]) and not bool(pm[rr, nx]):
                    return (Tool.ROAD, nx, rr)
        else:
            # Start road from plant column
            for wc in plant_cols:
                if ib(wc, rr) and bool(em[rr, wc]) and not bool(pm[rr, wc]):
                    return (Tool.ROAD, wc, rr)

    for rc in road_cols_target:
        col_rd = rm[:, rc]
        if col_rd.any():
            idx = np.where(col_rd)[0]
            bot = int(idx[-1])
            if bot < WORLD_H - 5:
                ny = bot + 1
                if bool(em[ny, rc]) and not bool(pm[ny, rc]):
                    return (Tool.ROAD, rc, ny)
            top = int(idx[0])
            if top > 4:
                ny = top - 1
                if bool(em[ny, rc]) and not bool(pm[ny, rc]):
                    return (Tool.ROAD, rc, ny)
        else:
            for wr in plant_rows:
                if ib(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)

    # --- PHASE 4: Zone placement (closed-loop, react to existing infrastructure) ---
    zone_cand = em & near_road & near_power
    # Keep away from edges
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W-3:] = False

    # Don't place on infrastructure rows/cols
    for wr in plant_rows:
        zone_cand[max(0,wr-1):min(WORLD_H,wr+2), :] = False
    for wc in plant_cols:
        zone_cand[:, max(0,wc-1):min(WORLD_W,wc+2)] = False
    for rr in road_rows_target:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for rc in road_cols_target:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Penalize too close (overlap), reward moderate distance
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                         np.where(min_zone_dist < 6, 0.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.3, min_zone_dist * 0.1)))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.05

        score = road_dist * 2.0 + zone_score
        order = np.argsort(score)
        tool = pick_tool()
        # Use step-based offset for variety
        off = (step * 7 + pop % 13) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    if pop > 50:
        # Fire stations grid
        for fsy in range(10, 95, 15):
            for fsx in range(10, 115, 20):
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        for psy in range(12, 95, 18):
            for psx in range(14, 115, 22):
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        for pky in range(8, 95, 10):
            for pkx in range(8, 115, 12):
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 600:
        for sty in range(20, 85, 30):
            for stx in range(20, 105, 35):
                if ib(stx, sty) and bool(em[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

    if pop > 1000 and funds > 5000:
        for ny in range(12, 90, 25):
            for nx in range(12, 110, 25):
                if ib(nx, ny) and bool(em[ny, nx]):
                    x0, x1 = max(0, nx-8), min(WORLD_W, nx+9)
                    y0, y1 = max(0, ny-8), min(WORLD_H, ny+9)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000 and funds > 10000:
        for apy in [7, 92]:
            for apx in [55, 65]:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

    if pop > 2500 and funds > 8000:
        for spy, spx in [(50, 7), (50, 112), (5, 60), (94, 60)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- PHASE 6: Extend wire toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2, dx2 in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy2 == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy2 == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx2 == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx2 == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        stride = max(1, len(uzxs) // 15)
        best_d = 1e9
        best_k = 0
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                    for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 7: Extend roads toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2, dx2 in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy2 == -1: shifted[:-1,:] = rm[1:,:]
        elif dy2 == 1: shifted[1:,:] = rm[:-1,:]
        elif dx2 == -1: shifted[:,:-1] = rm[:,1:]
        elif dx2 == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        stride = max(1, len(usxs) // 15)
        best_d = 1e9
        best_k = 0
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                    for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Fallback: add more roads from existing plant positions
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6,0),(-6,0),(0,6),(0,-6),(4,0),(-4,0),(0,4),(0,-4)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

