def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    zone_tiles = resm | comm | indm

    # Fast dilation
    def dilate(mask, r=3):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 4)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Power plants grid ----
    # Place coal plants on a 24x20 grid
    plant_positions = [(px, py) for py in range(12, WORLD_H - 8, 20)
                       for px in range(12, WORLD_W - 8, 24)]
    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 7), min(WORLD_W, ppx + 8)
        y0, y1 = max(0, ppy - 7), min(WORLD_H, ppy + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            if not bool(rm[ppy, ppx]) and not bool(zone_tiles[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network ----
    # Horizontal wires at rows 8, 16, 24, ... 
    wire_rows = list(range(9, WORLD_H - 4, 9))
    wire_cols = list(range(9, WORLD_W - 4, 9))

    # Build horizontal wire rows
    for wr in wire_rows:
        row_p = wm[wr, :] | pm[wr, :]
        if not row_p.any():
            # Find nearest plant to bootstrap
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                dists = np.abs(pys - wr)
                k = np.argmin(dists)
                wx, wy = int(pxs[k]), int(pys[k])
                if wy != wr:
                    ny = wy + (1 if wr > wy else -1)
                    if ib(wx, ny) and not bool(zone_tiles[ny, wx]) and not bool(rm[ny, wx]):
                        return (Tool.WIRE, wx, ny)
            continue
        idxs = np.where(row_p)[0]
        left, right = int(idxs[0]), int(idxs[-1])
        # Fill gaps first
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(zone_tiles[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)
        # Extend left
        if left > 3:
            nx = left - 1
            if bool(em[wr, nx]) and not bool(zone_tiles[wr, nx]) and not bool(rm[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 4:
            nx = right + 1
            if bool(em[wr, nx]) and not bool(zone_tiles[wr, nx]) and not bool(rm[wr, nx]):
                return (Tool.WIRE, nx, wr)

    # Build vertical wire cols
    for wc in wire_cols:
        col_p = wm[:, wc] | pm[:, wc]
        if not col_p.any():
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                dists = np.abs(pxs - wc)
                k = np.argmin(dists)
                wx, wy = int(pxs[k]), int(pys[k])
                if wx != wc:
                    nx2 = wx + (1 if wc > wx else -1)
                    if ib(nx2, wy) and not bool(zone_tiles[wy, nx2]) and not bool(rm[wy, nx2]):
                        return (Tool.WIRE, nx2, wy)
            continue
        idxs = np.where(col_p)[0]
        top, bot = int(idxs[0]), int(idxs[-1])
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(zone_tiles[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)
        if top > 3:
            ny = top - 1
            if bool(em[ny, wc]) and not bool(zone_tiles[ny, wc]) and not bool(rm[ny, wc]):
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 4:
            ny = bot + 1
            if bool(em[ny, wc]) and not bool(zone_tiles[ny, wc]) and not bool(rm[ny, wc]):
                return (Tool.WIRE, wc, ny)

    # ---- PHASE 3: Road network ----
    # Roads 3 tiles offset from wire rows/cols (between infrastructure and zones)
    road_rows = sorted(set(r for wr in wire_rows for r in [wr - 3, wr + 3]
                           if 4 < r < WORLD_H - 4))
    road_cols = sorted(set(c for wc in wire_cols for c in [wc - 3, wc + 3]
                           if 4 < c < WORLD_W - 4))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            # Try to find nearest road row and extend
            continue
        idxs = np.where(row_rd)[0]
        left, right = int(idxs[0]), int(idxs[-1])
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]) and not bool(wm[rr, x]):
                return (Tool.ROAD, x, rr)
        if left > 4 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]) and not bool(wm[rr, left-1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]) and not bool(wm[rr, right+1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        idxs = np.where(col_rd)[0]
        top, bot = int(idxs[0]), int(idxs[-1])
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]) and not bool(wm[y, rc]):
                return (Tool.ROAD, rc, y)
        if top > 4 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]) and not bool(wm[top-1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]) and not bool(wm[bot+1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W-3:] = False
    # Avoid infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[max(0, rr-1):min(WORLD_H, rr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, max(0, wc-1):min(WORLD_W, wc+2)] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, max(0, rc-1):min(WORLD_W, rc+2)] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        # Score: prefer close to road, cluster zones together
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 200)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 200)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                         np.where(min_zone_dist > 18, min_zone_dist * 0.5, 0.0))
        else:
            # Start from center
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.1

        score = road_dist * 1.5 + zone_score
        order = np.argsort(score)
        off = (step * 11 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 15:
        fire_spots = [(fx, fy) for fy in range(7, 97, 12) for fx in range(7, 117, 14)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and not bool(pm[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 60:
        police_spots = [(px2, py2) for py2 in range(7, 97, 14) for px2 in range(7, 117, 16)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]) and not bool(pm[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 120:
        park_spots = [(pkx, pky) for pky in range(5, 97, 8) for pkx in range(5, 117, 10)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]) and not bool(pm[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300:
        stadium_spots = [(sx, sy) for sy in range(15, 92, 25) for sx in range(15, 115, 30)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]) and not bool(pm[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 5000:
        nuclear_spots = [(nx, ny) for ny in range(15, 90, 20) for nx in range(15, 110, 20)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 8), min(WORLD_W, npx + 9)
                y0, y1 = max(0, npy - 8), min(WORLD_H, npy + 9)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1000:
        airport_spots = [(60, 8), (60, 91), (8, 50), (111, 50),
                         (30, 8), (90, 8), (30, 91), (90, 91)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [(8, 50), (111, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    if len(uzxs) > 0:
        # Find tiles adjacent to power that are empty
        adj_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 < 0:    shifted[:dy2, :] = power_src[-dy2:, :]
            elif dy2 > 0:  shifted[dy2:, :] = power_src[:-dy2, :]
            elif dx2 < 0:  shifted[:, :dx2] = power_src[:, -dx2:]
            elif dx2 > 0:  shifted[:, dx2:] = power_src[:, :-dx2]
            adj_power |= shifted

        wire_cand = em & adj_power & ~zone_tiles & ~rm
        wys_c, wxs_c = np.where(wire_cand)

        if len(wxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(uzxs) // 40)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                        for j in range(0, len(uzxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    if len(usxs) > 0:
        adj_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy2 < 0:    shifted[:dy2, :] = rm[-dy2:, :]
            elif dy2 > 0:  shifted[dy2:, :] = rm[:-dy2, :]
            elif dx2 < 0:  shifted[:, :dx2] = rm[:, -dx2:]
            elif dx2 > 0:  shifted[:, dx2:] = rm[:, :-dx2]
            adj_road |= shifted

        road_cand2 = em & adj_road & ~zone_tiles & ~pm & ~wm
        rys_c, rxs_c = np.where(road_cand2)

        if len(rxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(usxs) // 40)
            for i in range(len(rxs_c)):
                cx, cy = int(rxs_c[i]), int(rys_c[i])
                d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                        for j in range(0, len(usxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: build road/wire near plants ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dist in [4, 6, 8]:
            for dx2, dy2 in [(dist, 0), (-dist, 0), (0, dist), (0, -dist)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

# Closed-loop city builder: reactive, dense, multi-neighborhood strategy
# Key improvements over parent:
# 1. Simpler, more reliable power+wire+road+zone pipeline per hood
# 2. More neighborhoods spread across full map
# 3. Better zone placement logic with clear priority
# 4. Civic services placed reactively

def init(obs, state):
    """Bootstrap: central power plant + minimal wire/road cross."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross from plant
    for d in range(1, 6):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    # Roads flanking the wire cross
    for d in range(1, 5):
        actions.append((Tool.ROAD, cx + d, cy - 1))
        actions.append((Tool.ROAD, cx + d, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD DEFINITIONS ----
    # More neighborhoods spread across the full map
    # Each hood: (center_x, center_y)
    base_hoods = [
        # Center cluster
        (60, 50),
        # Inner ring
        (40, 35), (60, 35), (80, 35),
        (40, 65), (60, 65), (80, 65),
        (35, 50), (85, 50),
        # Outer ring
        (20, 20), (60, 20), (100, 20),
        (20, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
        # Extra density
        (45, 20), (75, 20),
        (15, 35), (110, 35),
        (15, 65), (110, 65),
        (45, 80), (75, 80),
    ]

    def num_active_hoods():
        if pop < 100:   return 1
        if pop < 300:   return 3
        if pop < 700:   return 6
        if pop < 1500:  return 10
        if pop < 3000:  return 15
        if pop < 6000:  return 20
        return len(base_hoods)

    n_active = num_active_hoods()
    active_hoods = base_hoods[:min(n_active, len(base_hoods))]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active hood needs a power plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant at or near hood center
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: CONNECT PLANTS WITH WIRES ----
    # For each hood, build wire spine radiating from plant
    for (hx, hy) in active_hoods:
        # Find plant in hood
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        plant_sub = pm[y0:y1, x0:x1]
        py_arr, px_arr = np.where(plant_sub)
        if len(px_arr) == 0:
            continue
        plx = int(px_arr[0]) + x0
        ply = int(py_arr[0]) + y0

        # Wire spine: horizontal from plant outward
        wire_range_h = 18
        # Right
        for dx in range(1, wire_range_h):
            wx, wy = plx + dx, ply
            if not ib(wx, wy): break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break
        # Left
        for dx in range(1, wire_range_h):
            wx, wy = plx - dx, ply
            if not ib(wx, wy): break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break
        # Down
        for dy in range(1, wire_range_h):
            wx, wy = plx, ply + dy
            if not ib(wx, wy): break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break
        # Up
        for dy in range(1, wire_range_h):
            wx, wy = plx, ply - dy
            if not ib(wx, wy): break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break

    # ---- PHASE 3: CONNECT WIRE SPINES BETWEEN HOODS ----
    # Connect horizontally close hoods with a horizontal wire bridge
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i: continue
            if abs(hy1 - hy2) > 8: continue
            if abs(hx1 - hx2) > 40: continue
            # Bridge at the average Y of closest wire rows
            # Find wire at column hx1
            col1_wire = [r for r in range(WORLD_H) if ib(hx1, r) and bool(wm[r, hx1])]
            col2_wire = [r for r in range(WORLD_H) if ib(hx2, r) and bool(wm[r, hx2])]
            if not col1_wire or not col2_wire:
                continue
            # Pick connecting Y
            bridge_y = col1_wire[len(col1_wire) // 2]
            # Fill gap
            x_lo, x_hi = min(hx1, hx2), max(hx1, hx2)
            for cx in range(x_lo, x_hi + 1):
                if ib(cx, bridge_y) and not bool(wm[bridge_y, cx]) and not bool(pm[bridge_y, cx]):
                    if bool(em[bridge_y, cx]):
                        return (Tool.WIRE, cx, bridge_y)

    # ---- PHASE 4: BUILD ROADS near wire spines ----
    # Compute neighbor-wire mask (zones need road within ~2 tiles AND power)
    # Build roads parallel to wires (offset by 1)
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        plant_sub = pm[y0:y1, x0:x1]
        py_arr, px_arr = np.where(plant_sub)
        if len(px_arr) == 0:
            continue
        plx = int(px_arr[0]) + x0
        ply = int(py_arr[0]) + y0

        # Horizontal road above and below horizontal wire spine
        for road_dy in [-1, 1]:
            ry = ply + road_dy
            if not ib(plx, ry): continue
            # Extend road along same X range as wire
            for dx in range(-16, 17):
                rx = plx + dx
                if not ib(rx, ry): continue
                # Only lay road if there's wire at (rx, ply)
                if bool(wm[ply, rx]) or bool(pm[ply, rx]):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

        # Vertical road left and right of vertical wire spine
        for road_dx in [-1, 1]:
            rx = plx + road_dx
            if not ib(rx, ply): continue
            for dy in range(-16, 17):
                ry2 = ply + dy
                if not ib(rx, ry2): continue
                if bool(wm[ry2, plx]) or bool(pm[ry2, plx]):
                    if bool(em[ry2, rx]) and not bool(pm[ry2, rx]):
                        return (Tool.ROAD, rx, ry2)

    # ---- PHASE 5: PLACE ZONES ----
    # Build neighbor road/wire coverage masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-12, 13):
        for dx2 in range(-12, 13):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                # Must be empty or already a zone tile (not road/wire/plant)
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest active hood center
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs.astype(float) - hx) + np.abs(cys.astype(float) - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- EXTEND ROADS reactively from existing road network ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES based on population ----
    if pop > 150:
        fire_spots = [
            (20, 20), (50, 20), (80, 20), (110, 20),
            (20, 45), (50, 45), (80, 45), (110, 45),
            (20, 70), (50, 70), (80, 70), (110, 70),
            (35, 30), (65, 30), (95, 30),
            (35, 60), (65, 60), (95, 60),
            (35, 85), (65, 85), (95, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [
            (25, 25), (55, 25), (85, 25),
            (25, 55), (55, 55), (85, 55),
            (25, 80), (55, 80), (85, 80),
            (40, 40), (70, 40), (100, 40),
            (40, 70), (70, 70), (100, 70),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadiums = [(40, 40), (80, 40), (40, 70), (80, 70),
                    (60, 15), (60, 85), (20, 55), (100, 55)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(55, 10), (55, 85), (10, 50), (105, 50)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS to boost land value ----
    if pop > 300 and step % 4 == 0:
        park_cands = np.where(em & nbr_road & nbr_power)
        if len(park_cands[0]) > 0:
            idx = (step * 19) % len(park_cands[0])
            py2, px2 = int(park_cands[0][idx]), int(park_cands[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place additional coal plant near unpowered area ----
    if step % 20 == 0:
        for (hx, hy) in active_hoods:
            if not bool(nbr_power[hy, hx]):
                for dr in range(1, 5):
                    for ddy in range(-dr, dr + 1):
                        for ddx in range(-dr, dr + 1):
                            if abs(ddx) != dr and abs(ddy) != dr: continue
                            nx, ny = hx + ddx, hy + ddy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: place two coal plants with wire connections and initial road grid."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from center plant
    for x in range(48, 73):
        actions.append((Tool.WIRE, x, 50))
    for y in range(42, 59):
        actions.append((Tool.WIRE, 60, y))
    # Roads parallel to wires
    for x in range(48, 73):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for y in range(42, 59):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    # Second plant top-left
    actions.append((Tool.COALPOWER, 25, 25))
    for x in range(18, 33):
        actions.append((Tool.WIRE, x, 25))
    for y in range(18, 33):
        actions.append((Tool.WIRE, 25, y))
    # Third plant top-right
    actions.append((Tool.COALPOWER, 95, 25))
    for x in range(88, 103):
        actions.append((Tool.WIRE, x, 25))
    for y in range(18, 33):
        actions.append((Tool.WIRE, 95, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Define a denser grid of neighborhood centers across the whole map
    all_hoods = []
    for hy in range(10, 100, 12):
        for hx in range(10, 120, 12):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:   return 4
        if pop < 200:  return 10
        if pop < 500:  return 20
        if pop < 1000: return 35
        if pop < 2000: return 55
        if pop < 4000: return 75
        if pop < 7000: return 90
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: ENSURE POWER PLANTS (one per cluster of ~5 hoods) ---
    if funds > 1000:
        for idx_h, (hx, hy) in enumerate(active_hoods):
            if idx_h % 5 != 0:
                continue
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find nearest empty cell to place plant
                for r in range(1, 15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- BUILD NEIGHBOR MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # --- PHASE 2: EXTEND WIRES FROM PLANTS TOWARD HOOD CENTERS ---
    pys_arr, pxs_arr = np.where(pm)
    if len(pxs_arr) > 0:
        for (hx, hy) in active_hoods:
            # Check if this hood already has wire coverage
            x0w, x1w = max(0, hx - 8), min(WORLD_W, hx + 9)
            y0w, y1w = max(0, hy - 8), min(WORLD_H, hy + 9)
            has_wire = bool(np.any(wm[y0w:y1w, x0w:x1w]))
            has_plant_near = bool(np.any(pm[y0w:y1w, x0w:x1w]))

            if has_wire or has_plant_near:
                # Extend vertical spine at hx
                spine_top = max(2, hy - 12)
                spine_bot = min(WORLD_H - 3, hy + 12)
                spine_left = max(2, hx - 12)
                spine_right = min(WORLD_W - 3, hx + 12)

                # Extend vertical wire spine
                col_wires = [r for r in range(spine_top, spine_bot + 1)
                             if ib(hx, r) and bool(wm[r, hx])]
                col_plants = [r for r in range(spine_top, spine_bot + 1)
                              if ib(hx, r) and bool(pm[r, hx])]

                if col_plants and not col_wires:
                    for pr in col_plants:
                        for wr in [pr - 1, pr + 1]:
                            if ib(hx, wr) and not bool(pm[wr, hx]) and bool(em[wr, hx]):
                                return (Tool.WIRE, hx, wr)

                if col_wires:
                    min_wr = min(col_wires)
                    max_wr = max(col_wires)
                    if max_wr < spine_bot:
                        nr = max_wr + 1
                        if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                            return (Tool.WIRE, hx, nr)
                    if min_wr > spine_top:
                        nr = min_wr - 1
                        if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                            return (Tool.WIRE, hx, nr)

                # Extend horizontal wire spine
                row_wires = [c for c in range(spine_left, spine_right + 1)
                             if ib(c, hy) and bool(wm[hy, c])]
                row_plants = [c for c in range(spine_left, spine_right + 1)
                              if ib(c, hy) and bool(pm[hy, c])]

                if row_plants and not row_wires:
                    for pc in row_plants:
                        for wc in [pc - 1, pc + 1]:
                            if ib(wc, hy) and not bool(pm[hy, wc]) and bool(em[hy, wc]):
                                return (Tool.WIRE, wc, hy)

                if row_wires:
                    min_wc = min(row_wires)
                    max_wc = max(row_wires)
                    if max_wc < spine_right:
                        nc = max_wc + 1
                        if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                            return (Tool.WIRE, nc, hy)
                    if min_wc > spine_left:
                        nc = min_wc - 1
                        if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                            return (Tool.WIRE, nc, hy)

    # --- PHASE 3: CONNECT WIRE SPINES BETWEEN NEARBY HOODS ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 28:
                continue
            # Horizontal bridge
            if abs(hy1 - hy2) <= 4 and hx2 > hx1:
                bridge_y = (hy1 + hy2) // 2
                for cx in range(hx1, hx2 + 1):
                    if ib(cx, bridge_y) and bool(em[bridge_y, cx]) and not bool(pm[bridge_y, cx]):
                        return (Tool.WIRE, cx, bridge_y)
            # Vertical bridge
            if abs(hx1 - hx2) <= 4 and hy2 > hy1:
                bridge_x = (hx1 + hx2) // 2
                for cy in range(hy1, hy2 + 1):
                    if ib(bridge_x, cy) and bool(em[cy, bridge_x]) and not bool(pm[cy, bridge_x]):
                        return (Tool.WIRE, bridge_x, cy)

    # --- PHASE 4: BUILD ROAD GRID (parallel to wires, offset ±2) ---
    for (hx, hy) in active_hoods:
        spine_top = max(2, hy - 12)
        spine_bot = min(WORLD_H - 3, hy + 12)
        spine_left = max(2, hx - 12)
        spine_right = min(WORLD_W - 3, hx + 12)

        col_wires = [r for r in range(spine_top, spine_bot + 1)
                     if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy):
                continue
            cyc = step % 3
            for wr in col_wires[cyc::3]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wires = [c for c in range(spine_left, spine_right + 1)
                     if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry):
                continue
            cyc = (step + 1) % 3
            for wc in row_wires[cyc::3]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT ---
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # Target: 50% res, 25% com, 25% ind
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Cluster bonus: prefer spots near existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                # Balance between hood-center distance and zone proximity
                score = best_dist * 0.35 + zone_prox * 0.65
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES ---
    if pop > 5:
        fire_grid = [(fx, fy) for fy in range(12, 98, 14) for fx in range(12, 118, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 30:
        police_grid = [(px2, py2) for py2 in range(14, 96, 16) for px2 in range(14, 116, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 200:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (50, 30), (70, 30), (50, 70), (70, 70),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Upgrade to nuclear when rich
    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 25), (60, 75),
            (45, 5), (75, 5), (45, 95), (75, 95),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75),
                        (30, 5), (90, 5), (30, 95), (90, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [(8, 8), (102, 8), (8, 87), (102, 87),
                        (50, 8), (50, 87), (8, 50), (102, 50)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from any plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        sk = (step * 11) % len(pxs2)
        for offset in range(min(len(pxs2), 100)):
            k = (sk + offset * 7) % len(pxs2)
            px2, py2 = int(pxs2[k]), int(pys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                              (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire/road cross skeleton"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # 4 corner plants
    for px, py in [(10, 10), (110, 10), (10, 90), (110, 90)]:
        actions.append((Tool.COALPOWER, px, py))
    # Mid-edge plants
    for px, py in [(60, 10), (60, 90), (10, 50), (110, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for x in range(0, 120):
        for y in [10, 30, 50, 70, 90]:
            actions.append((Tool.WIRE, x, y))
    # Vertical wire spines
    for y in range(0, 100):
        for x in [10, 30, 60, 90, 110]:
            actions.append((Tool.WIRE, x, y))
    # Roads flanking wire spines
    for x in range(0, 120):
        for y in [29, 31, 49, 51, 69, 71]:
            actions.append((Tool.ROAD, x, y))
    for y in range(0, 100):
        for x in [29, 31, 59, 61, 89, 91]:
            actions.append((Tool.ROAD, x, y))
