def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 50% RES, 25% COM, 25% IND
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Wire spines
    wire_rows = [10, 30, 50, 70, 90]
    wire_cols = [10, 30, 60, 90, 110]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Neighborhoods: grid across the map avoiding wire corridors
    # Place neighborhoods between wire rows/cols
    nh_positions = []
    for row_idx, (r1, r2) in enumerate(zip(wire_rows[:-1], wire_rows[1:])):
        for col_idx, (c1, c2) in enumerate(zip(wire_cols[:-1], wire_cols[1:])):
            # Center of each cell
            cx = (c1 + c2) // 2
            cy = (r1 + r2) // 2
            nh_positions.append((cx, cy))

    # Additional hoods at edges
    for cx in [20, 45, 75, 100]:
        for cy in [20, 40, 60, 80]:
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 200:
            # Central cluster first
            return [(45, 40), (75, 40), (45, 60), (75, 60), (60, 50)]
        elif pop < 800:
            return nh_positions[:16]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    phase = step % 12

    # Phase 0-1: Ensure power connectivity via wires
    if phase == 0:
        # Extend horizontal wires
        for wr in wire_rows:
            row_mask = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(row_mask[wx]):
                    left = ib(wx-1, wr) and bool(row_mask[wx-1])
                    right = ib(wx+1, wr) and bool(row_mask[wx+1])
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wires
        for wc in wire_cols:
            col_mask = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if not bool(col_mask[wy]):
                    above = ib(wc, wy-1) and bool(col_mask[wy-1])
                    below = ib(wc, wy+1) and bool(col_mask[wy+1])
                    if (above or below) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads along horizontal wires (both sides)
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (1 <= ry <= WORLD_H - 2):
                    continue
                row_wire = wm[wr, :] | pm[wr, :]
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads along vertical wires (both sides)
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (1 <= rcx <= WORLD_W - 2):
                    continue
                col_wire = wm[:, wc] | pm[:, wc]
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Cross roads between wire corridors (horizontal mid-rows)
        for r_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[r_idx], wire_rows[r_idx + 1]
            mid_y = (r1 + r2) // 2
            for c_idx in range(len(wire_cols) - 1):
                c1, c2 = wire_cols[c_idx], wire_cols[c_idx + 1]
                # Check if road already exists
                road_present = bool(np.any(rm[mid_y, c1:c2+1]))
                if not road_present:
                    # Extend from wire side roads
                    for rx in range(c1 + 2, c2 - 1):
                        adj_road = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                                   (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                        if ib(rx, mid_y) and bool(em[mid_y, rx]) and adj_road and bool(near_power[mid_y, rx]):
                            return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Cross roads vertical
        for c_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[c_idx], wire_cols[c_idx + 1]
            mid_x = (c1 + c2) // 2
            for r_idx in range(len(wire_rows) - 1):
                r1, r2 = wire_rows[r_idx], wire_rows[r_idx + 1]
                road_present = bool(np.any(rm[r1:r2+1, mid_x]))
                if not road_present:
                    for ry in range(r1 + 2, r2 - 1):
                        adj_road = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                                   (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                        if ib(mid_x, ry) and bool(em[ry, mid_x]) and adj_road and bool(near_power[ry, mid_x]):
                            return (Tool.ROAD, mid_x, ry)

    elif phase in [6, 7, 8, 9]:
        # Zone placement: main activity
        cand_mask = em & near_road & near_power
        # Buffer from edges
        cand_mask[0:3, :] = False
        cand_mask[WORLD_H-3:, :] = False
        cand_mask[:, 0:3] = False
        cand_mask[:, WORLD_W-3:] = False
        # Don't zone on wire corridors
        for wr in wire_rows:
            cand_mask[max(0, wr-1):wr+2, :] = False
        for wc in wire_cols:
            cand_mask[:, max(0, wc-1):wc+2] = False

        cys, cxs = np.where(cand_mask)
        if len(cxs) > 0:
            best_dist = np.full(len(cxs), 999999.0)
            for (hx, hy) in active_hoods:
                d = (np.abs(cxs - hx) + np.abs(cys - hy)).astype(float)
                best_dist = np.minimum(best_dist, d)
            order = np.argsort(best_dist)
            offset = (step * 7 + pop * 3) % max(len(order), 1)
            tool = pick_tool()
            for i in range(min(len(order), 500)):
                k = order[(offset + i) % len(order)]
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)

    elif phase == 10:
        # Extend roads from existing roads into empty near-powered areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            step_k = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 80)):
                k = (step_k + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx, ry2 + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 11:
        # Wire toward unpowered zones
        zone_tiles_unpowered = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(zone_tiles_unpowered)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- CIVIC SERVICES (reactive) ----
    if pop > 50:
        fire_spots = [(20, 20), (50, 20), (80, 20), (100, 20),
                      (20, 40), (50, 40), (80, 40), (100, 40),
                      (20, 60), (50, 60), (80, 60), (100, 60),
                      (20, 80), (50, 80), (80, 80), (100, 80)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(25, 25), (60, 25), (95, 25),
                        (25, 55), (60, 55), (95, 55),
                        (25, 75), (60, 75), (95, 75)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(40, 38), (80, 38), (40, 62), (80, 62)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(5, 5), (115, 5), (5, 95), (115, 95),
                      (60, 5), (60, 95), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 93), (113, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire extension from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: zone placement anywhere powered & roaded
    cand_mask2 = em & near_road & near_power
    cand_mask2[0:3, :] = False
    cand_mask2[WORLD_H-3:, :] = False
    cand_mask2[:, 0:3] = False
    cand_mask2[:, WORLD_W-3:] = False
    cys2, cxs2 = np.where(cand_mask2)
    if len(cxs2) > 0:
        tool = pick_tool()
        for i in range(min(len(cxs2), 200)):
            k = (step * 7 + i * 3) % len(cxs2)
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a line with wire crosses and flanking roads."""
    actions = []
    for (cx, cy) in [(30, 50), (60, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for dx in range(-5, 6):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
        for dx in range(-5, 6):
            actions.append((Tool.ROAD, cx + dx, cy - 1))
            actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    zone_tiles = resm | comm | indm

    # Dense neighborhood grid: 12 cols x 9 rows = 108 neighborhoods
    nh_cols = [8, 18, 30, 42, 54, 66, 78, 90, 102, 112]
    nh_rows = [8, 18, 30, 42, 54, 66, 78, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 15
        if pop < 800:   return 25
        if pop < 1500:  return 35
        if pop < 3000:  return 50
        if pop < 6000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- BUILD POWER + ROAD NEIGHBOR MASKS ----
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 2: WIRE SPINES (cross at each hood, reactive) ----
    spine_r = 12
    # Process hoods in round-robin based on step
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Vertical spine
    for dy in range(-spine_r, spine_r + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj in [-1, 1]:
            ay = wy + adj
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine
    for dx in range(-spine_r, spine_r + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj in [-1, 1]:
            ax = wx + adj
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Horizontal connection
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical connection
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 14:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    road_idx = (step + 1) % max(len(active_hoods), 1)
    rhx, rhy = active_hoods[road_idx]

    # Vertical road flanks
    for rx in [rhx - 1, rhx + 1]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_r, spine_r + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                return (Tool.ROAD, rx, ry)

    # Horizontal road flanks
    for ry2 in [rhy - 1, rhy + 1]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_r, spine_r + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT (reactive: near roads + power) ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = (np.abs(cxs - hx2).astype(float) + np.abs(cys - hy2).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: DENSE ZONE INFILL near existing roads ----
    road_ys3, road_xs3 = np.where(rm)
    if len(road_xs3) > 0:
        step_k3 = (step * 17) % len(road_xs3)
        for offset in range(min(len(road_xs3), 200)):
            k = (step_k3 + offset * 11) % len(road_xs3)
            rx3, ry3 = int(road_xs3[k]), int(road_ys3[k])
            for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                              (2, 2), (-2, 2), (2, -2), (-2, -2),
                              (4, 0), (-4, 0), (0, 4), (0, -4),
                              (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                zx3, zy3 = rx3 + dx3, ry3 + dy3
                if ib(zx3, zy3) and bool(nbr_power[zy3, zx3]) and zone_clear(zx3, zy3):
                    return (pick_tool(), zx3, zy3)

    # ---- PHASE 8: CIVIC SERVICES (scaled with pop) ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(14, WORLD_W, 16) for fy in range(14, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(20, WORLD_W, 20) for py2 in range(20, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 25), (60, 25), (90, 25), (15, 50), (45, 50), (75, 50), (105, 50),
                    (30, 75), (60, 75), (90, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(6, 90), (114, 90), (6, 8), (114, 8), (60, 4), (60, 96)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        nuclear_spots = [(15, 5), (45, 5), (75, 5), (105, 5),
                         (15, 95), (45, 95), (75, 95), (105, 95),
                         (5, 25), (5, 50), (5, 75),
                         (115, 25), (115, 50), (115, 75)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 4000:
        airports = [(40, 5), (80, 5), (40, 94), (80, 94), (4, 40), (4, 60), (116, 40), (116, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 9: PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx3 + dx, hy3 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle + initial wire/road connections"""
    actions = []
    # Three coal plants: left, right, center-top
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    actions.append((Tool.COALPOWER, 60, 20))
    # Wire connecting left plant to center horizontally
    for x in range(22, 60):
        actions.append((Tool.WIRE, x, 50))
    # Wire connecting center-top down to horizontal wire
    for y in range(22, 50):
        actions.append((Tool.WIRE, 60, y))
    # Wire connecting right plant to center horizontally
    for x in range(61, 99):
        actions.append((Tool.WIRE, x, 50))
    # Initial roads forming a cross
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    for y in range(5, 95):
        actions.append((Tool.ROAD, 20, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 100, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        # 50% res, 25% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure power plants are distributed across the map ---
    # Dense grid of plants every 20 tiles
    plant_positions = []
    for py in range(10, 96, 20):
        for px in range(10, 116, 20):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Wire extension - BFS-like greedy expansion ---
    # Build wire adjacent to existing power sources toward unpowered areas
    def adj_mask(mask):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        result[1:, :] |= mask[:-1, :]
        result[:-1, :] |= mask[1:, :]
        result[:, 1:] |= mask[:, :-1]
        result[:, :-1] |= mask[:, 1:]
        return result

    adj_to_power = adj_mask(power_src)
    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    # Keep border safe
    wire_cand[:2, :] = False; wire_cand[-2:, :] = False
    wire_cand[:, :2] = False; wire_cand[:, -2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Find unpowered plants first (highest priority)
        unpowered_plants = [(px2, py2) for px2, py2 in plant_positions
                            if ib(px2, py2) and np.any(pm[max(0,py2-2):min(WORLD_H,py2+3),
                                                          max(0,px2-2):min(WORLD_W,px2+3)])
                            and not bool(near_power[py2, px2])]
        if unpowered_plants:
            best_dist = 1e9; best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px2) + abs(cy - py2) for px2, py2 in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d; best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9; best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d; best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered empty areas (spread power coverage)
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0:
            rng = np.random.default_rng(step % 1000)
            sample_idx = rng.choice(len(upxs), min(60, len(upxs)), replace=False)
            best_dist = 1e9; best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_idx)
                if d < best_dist:
                    best_dist = d; best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Road grid - dense, every 6 tiles where power exists ---
    # Multiple road corridors
    road_targets = []
    for gy in range(6, 97, 6):
        for gx in range(6, 117, 6):
            road_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = adj_mask(rm)
        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[:2, :] = False; road_cand[-2:, :] = False
        road_cand[:, :2] = False; road_cand[:, -2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9; best_k = 0
            targets_sample = uncovered_road[:30]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d; best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Start isolated road segment directly
            for gx, gy in uncovered_road[:15]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement - dense, mixed, spread across map ---
    zone_cand = em & near_road & near_power
    zone_cand[:4, :] = False; zone_cand[-4:, :] = False
    zone_cand[:, :4] = False; zone_cand[:, -4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: close to road, spread from existing zones
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Prefer: close to road, somewhat away from existing zones (spread)
        # Also prefer center of map for variety
        cx_center = np.abs(cxs_arr - 60).astype(float)
        cy_center = np.abs(cys_arr - 50).astype(float)
        center_dist = (cx_center + cy_center) * 0.05

        score = road_dist * 1.5 + np.maximum(0, 8 - zone_dist) * 2.0 + center_dist

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    if pop > 80:
        for fsy in range(12, 95, 12):
            for fsx in range(12, 110, 12):
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        for psy in range(15, 90, 15):
            for psx in range(15, 108, 15):
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        for pky in range(9, 95, 9):
            for pkx in range(9, 115, 9):
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 700:
        stadium_locs = [(25, 20), (95, 20), (25, 80), (95, 80),
                        (60, 15), (60, 85), (15, 50), (105, 50),
                        (40, 35), (80, 65), (40, 65), (80, 35),
                        (60, 50), (30, 50), (90, 50)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (60, 10), (60, 90), (10, 50), (110, 50),
                     (40, 15), (80, 15), (40, 85), (80, 85)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 6), min(WORLD_W, nx + 7)
                y0, y1 = max(0, ny - 6), min(WORLD_H, ny + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 8), (75, 8), (55, 92), (75, 92),
                        (8, 30), (110, 30), (8, 65), (110, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 92),
                        (15, 20), (105, 20), (15, 80), (105, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]) and bool(near_road[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend road from existing plant adjacency ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 2), (-2, 2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire from plant ---
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2), (-2, 0), (0, -2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in 3x3 grid + wire spines + flanking roads."""
    actions = []
    for px in [20, 60, 100]:
        for py in [25, 50, 75]:
            actions.append((Tool.COALPOWER, px, py))
            for dy in range(-6, 7):
                actions.append((Tool.WIRE, px, py + dy))
            for dy in range(-6, 7):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal roads connecting columns
    for py in [25, 50, 75]:
        for cx in range(21, 60):
            actions.append((Tool.ROAD, cx, py - 4))
            actions.append((Tool.ROAD, cx, py + 4))
        for cx in range(61, 100):
            actions.append((Tool.ROAD, cx, py - 4))
            actions.append((Tool.ROAD, cx, py + 4))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target zone mix: 50% res, 30% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    # All 9 anchor positions for a full 3x3 grid
    all_anchors = [(px, py) for px in [20, 60, 100] for py in [25, 50, 75]]

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 3
        if pop < 300:  return 4
        if pop < 500:  return 5
        if pop < 750:  return 6
        if pop < 1000: return 7
        if pop < 1500: return 8
        return 9

    n_active = num_active()
    # Spread active anchors evenly
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_sz = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_sz)] for i in range(n_active)]

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: Ensure power plants at active anchors ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire spine (vertical) around each anchor ----
    spine_half = min(35, 8 + pop // 8)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy2 in range(-6, 7):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 3: Horizontal wire connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_xs = sorted([px for (px, py) in active_anchors if py == yl])
        for i in range(len(row_xs) - 1):
            for cx in range(row_xs[i] + 1, row_xs[i + 1]):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- PHASE 4: Vertical wire connecting anchor rows in same column ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xc in x_cols:
        col_ys = sorted([py for (px, py) in active_anchors if px == xc])
        for i in range(len(col_ys) - 1):
            for cy in range(col_ys[i] + 1, col_ys[i + 1]):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # ---- PHASE 5: Flanking roads along wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 3
        rl, rr = px - 1, px + 1
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- PHASE 6: Horizontal roads above/below anchors ----
    for yl in y_levels:
        row_xs = sorted([px for (px, py) in active_anchors if py == yl])
        if len(row_xs) < 2:
            continue
        x_min, x_max = row_xs[0] - 1, row_xs[-1] + 1
        for horiz_y in [yl - 5, yl + 5]:
            if not ib(x_min, horiz_y) or not ib(x_max, horiz_y):
                continue
            for cx in range(x_min, x_max + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- PHASE 7: Cross roads between y-levels ----
    if pop > 50 and len(y_levels) >= 2:
        for xc in [20, 60, 100]:
            for rx in [xc - 3, xc + 3]:
                for i in range(len(y_levels) - 1):
                    y1, y2 = y_levels[i], y_levels[i + 1]
                    if not ib(rx, y1) or not ib(rx, y2):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- PHASE 8: Additional grid roads for zone coverage ----
    if pop > 100:
        for gx in range(10, 115, 8):
            for gy in range(10, 97, 8):
                if ib(gx, gy) and bool(em[gy, gx]) and bool(near_power[gy, gx]) and not bool(pm[gy, gx]):
                    # Check adjacent road or wire connectivity
                    has_adj = False
                    for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nx2, ny2 = gx+dx2, gy+dy2
                        if ib(nx2, ny2) and (bool(rm[ny2, nx2]) or bool(wm[ny2, nx2])):
                            has_adj = True
                            break
                    if has_adj:
                        return (Tool.ROAD, gx, gy)

    # ---- PHASE 9: Zone placement ----
    nbr_road = dilate(rm, 2)
    nbr_wire = dilate(wm | pm, 6)

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- PHASE 10: Extend roads from existing roads near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 15), (35, 15), (65, 15), (95, 15), (113, 15),
            (8, 38), (35, 38), (65, 38), (95, 38), (113, 38),
            (8, 62), (35, 62), (65, 62), (95, 62), (113, 62),
            (8, 85), (35, 85), (65, 85), (95, 85), (113, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (12, 22), (45, 22), (75, 22), (108, 22),
            (12, 47), (45, 47), (75, 47), (108, 47),
            (12, 72), (45, 72), (75, 72), (108, 72),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150:
        zone_ys2, zone_xs2 = np.where(zone_tiles)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 600:
        stadium_spots = [
            (10, 10), (55, 10), (100, 10),
            (10, 90), (55, 90), (100, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0, x1 = max(0, nx2-5), min(WORLD_W, nx2+6)
                y0, y1 = max(0, ny2-5), min(WORLD_H, ny2+6)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94), (30, 6), (90, 6)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: road near plant ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross of wires + seed roads"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(10, 110):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(10, 90):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads near center
    for x in range(10, 110, 2):
        actions.append((Tool.ROAD, x, 45))
    for x in range(10, 110, 2):
        actions.append((Tool.ROAD, x, 55))
    for y in range(10, 90, 2):
        actions.append((Tool.ROAD, 55, y))
    for y in range(10, 90, 2):
        actions.append((Tool.ROAD, 65, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        # Target: 30% ind, 30% com, 40% res
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Power plants on a dense grid ---
    # Plant every ~18 cols, 18 rows for denser coverage
    plant_xs = list(range(9, WORLD_W - 5, 18))
    plant_ys = list(range(9, WORLD_H - 5, 18))

    for ppy in plant_ys:
        for ppx in plant_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # --- PHASE 2: Wire grid (horizontal every 9 rows, vertical every 9 cols) ---
    wire_rows = list(range(9, WORLD_H - 5, 9))
    wire_cols = list(range(9, WORLD_W - 5, 9))

    # Extend horizontal wires
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            # Try to start from nearest plant
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 2 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 2 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # --- PHASE 3: Road grid (midway between wire rows/cols) ---
    road_rows = sorted(set(r for r in [wr + 4 for wr in wire_rows] if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in [wc + 4 for wc in wire_cols] if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- PHASE 4: Zone placement (closed-loop, reactive) ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Block infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer spots near existing zones but not too close (cluster expansion)
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                                  np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Score: favor close to road, moderate cluster density
        score = road_dist * 1.2 + zone_score * 0.3
        order = np.argsort(score)
        off = (step * 7 + pop % 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services (reactive to population) ---
    if pop > 20:
        fire_ys = list(range(12, WORLD_H - 5, 10))
        fire_xs = list(range(12, WORLD_W - 5, 15))
        for fsy in fire_ys:
            for fsx in fire_xs:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        pol_ys = list(range(14, WORLD_H - 5, 12))
        pol_xs = list(range(14, WORLD_W - 5, 18))
        for psy in pol_ys:
            for psx in pol_xs:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_ys = list(range(10, WORLD_H - 5, 8))
        park_xs = list(range(10, WORLD_W - 5, 10))
        for pky in park_ys:
            for pkx in park_xs:
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 500:
        stad_spots = [(sx, sy) for sy in range(15, 90, 20) for sx in range(15, 110, 25)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuc_spots = [(nx, ny) for ny in range(12, 90, 20) for nx in range(12, 110, 20)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
                y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        airport_spots = [(55, 7), (65, 7), (55, 92), (65, 92), (7, 45), (112, 45)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- PHASE 6: Wire extension toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 7: Road extension toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- Fallback: road near existing plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire connections and flanking roads."""
    actions = []
    # Three power plants forming a triangle
    plants = [(20, 20), (60, 50), (100, 20)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire spine connecting all plants horizontally
    for x in range(20, 101):
        actions.append((Tool.WIRE, x, 20))
    # Vertical wire from top to center plant
    for y in range(20, 51):
        actions.append((Tool.WIRE, 60, y))
    # Flanking roads near center plant
    for y in range(44, 57):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID: 8 cols x 7 rows = 56 neighborhoods ----
    nh_cols = [10, 26, 42, 58, 74, 90, 106, 118]
    nh_rows = [10, 22, 36, 50, 64, 78, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 7
        if pop < 600:  return 12
        if pop < 1000: return 18
        if pop < 2000: return 28
        if pop < 4000: return 40
        if pop < 7000: return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR ROAD/POWER MASKS ----
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    nbr_road = dilate(rm, 3)
    nbr_power = dilate(wm | pm, 6)

    # ---- PHASE 1: ENSURE POWER PLANTS PER HOOD ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    spine_range = 14
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Vertical spine
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy) or not bool(em[wy, hx]):
            continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]):
            continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy) or not bool(em[hy, wx]):
            continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]):
            continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and hx1 < hx2 and hx2 - hx1 <= 22:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1) or not bool(em[hy1, cx2]):
                        continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and hy1 < hy2 and hy2 - hy1 <= 22:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or not bool(em[cy2, hx1]):
                        continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods) // 3 + 1, 1) != 0:
            continue
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy):
                continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2):
                continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop % 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS INTO POWERED AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W - 5, 16) for fy in range(12, WORLD_H - 5, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W - 5, 20) for py2 in range(15, WORLD_H - 5, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300 and step % 3 == 0:
        park_ys2, park_xs2 = np.where(em & nbr_road & nbr_power)
        if len(park_xs2) > 0:
            idx = (step * 17) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 700:
        stadiums = [(sx, sy) for sx in range(20, WORLD_W - 10, 28) for sy in range(20, WORLD_H - 10, 28)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5), (8, 50), (112, 50)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800 and step % 4 == 0:
        nuclear_spots = [
            (30, 25), (90, 25), (30, 75), (90, 75),
            (10, 50), (110, 50), (60, 10), (60, 90),
            (20, 10), (100, 10), (20, 90), (100, 90),
            (50, 50), (70, 50)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0, x1 = max(0, nx2 - 12), min(WORLD_W, nx2 + 13)
                y0, y1 = max(0, ny2 - 12), min(WORLD_H, ny2 + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 40), (6, 60), (114, 40), (114, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- EXTEND WIRE FROM EXISTING WIRE ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central power cluster + wire cross + road ring."""
    actions = []
    # Three coal plants in a triangle for good coverage
    plants = [(60, 50), (30, 25), (90, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire horizontal and vertical from center plant
    for x in range(28, 93):
        actions.append((Tool.WIRE, x, 50))
    for y in range(23, 78):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking the wire spines
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(5, 95):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood grid across entire map
    all_hoods = []
    for hy in range(10, 95, 10):
        for hx in range(10, 115, 10):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 100:   return 5
        if pop < 300:   return 12
        if pop < 800:   return 25
        if pop < 2000:  return 45
        if pop < 5000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Select hoods spread across map
    stride = max(1, len(all_hoods) // n_active)
    active_hoods = all_hoods[::stride][:n_active]

    # Build neighbor masks efficiently
    power_src = wm | pm

    def dilate(mask, r):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-r, r + 1):
            for dx in range(-r, r + 1):
                if abs(dx) + abs(dy) > r:
                    continue
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_power = dilate(power_src, 4)
    nbr_road = dilate(rm, 3)

    # === STEP 1: Ensure each active hood has a power plant nearby ===
    if funds > 500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
            y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Find nearest empty tile to place plant
                for r in range(2, 16):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === STEP 2: Wire from each plant toward its hood center ===
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant to this hood
    x0p, x1p = max(0, hx - 20), min(WORLD_W, hx + 21)
    y0p, y1p = max(0, hy - 20), min(WORLD_H, hy + 21)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        # Pick nearest plant
        dists = np.abs(plant_xs - (hx - x0p)) + np.abs(plant_ys - (hy - y0p))
        best = np.argmin(dists)
        px_l = int(plant_xs[best]) + x0p
        py_l = int(plant_ys[best]) + y0p

        # Wire L-shaped path from plant to hood
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if bool(em[wy, px_l]):
                    return (Tool.WIRE, px_l, wy)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

    # === STEP 3: Build roads near wire for zone access ===
    # Road grid: every 6 tiles, extending from existing road network
    road_targets_y = list(range(6, 95, 6))
    road_targets_x = list(range(6, 115, 6))

    # Extend horizontal roads near powered areas
    for rr in road_targets_y[(step // 4) % max(len(road_targets_y), 1)::len(road_targets_y)]:
        if not bool(nbr_power[rr, 60]):
            continue
        row_road = rm[rr, :]
        if row_road.any():
            idxs = np.where(row_road)[0]
            left = int(idxs[0]); right = int(idxs[-1])
            if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
                return (Tool.ROAD, left - 1, rr)
            if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
                return (Tool.ROAD, right + 1, rr)
        elif bool(em[rr, 60]):
            return (Tool.ROAD, 60, rr)

    # Extend vertical roads
    for rc in road_targets_x[(step // 4) % max(len(road_targets_x), 1)::len(road_targets_x)]:
        if not bool(nbr_power[50, rc]):
            continue
        col_road = rm[:, rc]
        if col_road.any():
            idxs = np.where(col_road)[0]
            top = int(idxs[0]); bot = int(idxs[-1])
            if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
                return (Tool.ROAD, rc, top - 1)
            if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
                return (Tool.ROAD, rc, bot + 1)
        elif bool(em[50, rc]):
            return (Tool.ROAD, rc, 50)

    # === STEP 4: Zone placement ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hoods and existing zones
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        score = best_dist.copy()
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride2 = max(1, len(zxs2) // 150)
                for i in range(0, len(zxs2), stride2):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === STEP 5: Extend roads from existing road tiles ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === STEP 6: Civic services scaled by population ===
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(15, 95, 15) for fx in range(15, 115, 15)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(18, 92, 18) for px2 in range(18, 112, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 120 and step % 2 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2):
                return (Tool.PARK, px2, py2)

    if pop > 250:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20), (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50), (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 350:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95), (5, 25), (5, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === STEP 7: Wire extensions from existing wire/plant ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === STEP 8: Emergency plant for unpowered hoods ===
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]) and funds > 500:
            for r in range(2, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# A more ambitious city-builder with a grid-based layout
# Key improvements:
# 1. Compact neighborhood grid with proper power+road+zone interleaving
# 2. Multiple power plants spread across map
# 3. Balanced RCI zoning based on current ratios
# 4. Civic services placed proactively
# 5. Dense road grid for maximum zone connectivity

def init(obs, state):
    """Bootstrap: single central coal plant with wire and road seeds."""
    actions = []
    # Central plant at (60, 50)
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spine going left and right from plant
    for dx in range(1, 8):
        actions.append((Tool.WIRE, 60 + dx, 50))
        actions.append((Tool.WIRE, 60 - dx, 50))
    # Wire spine going up and down
    for dy in range(1, 8):
        actions.append((Tool.WIRE, 60, 50 + dy))
        actions.append((Tool.WIRE, 60, 50 - dy))
    # Seed roads adjacent to plant for zone access
    actions.append((Tool.ROAD, 63, 50))
    actions.append((Tool.ROAD, 57, 50))
    actions.append((Tool.ROAD, 60, 53))
    actions.append((Tool.ROAD, 60, 47))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target ratio: 50% res, 25% com, 25% ind
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- NEIGHBORHOOD DEFINITIONS ---
    # Each neighborhood: (center_x, center_y)
    # We'll build a grid of neighborhoods across the map
    # Layout: 5 cols x 4 rows = 20 neighborhoods
    # Spread: x in [15, 35, 55, 75, 95, 115], y in [15, 35, 55, 75, 95]

    # Power plant positions (one per neighborhood cluster)
    # We'll place plants at strategic locations
    plant_positions = [
        (15, 20), (60, 20), (105, 20),
        (15, 50), (60, 50), (105, 50),
        (15, 80), (60, 80), (105, 80),
    ]

    # Neighborhood centers for zoning (on a 12-unit grid)
    neighborhoods = []
    for cy in range(10, 95, 12):
        for cx in range(10, 115, 12):
            neighborhoods.append((cx, cy))

    def num_active_plants():
        if pop < 50:   return 1
        if pop < 200:  return 2
        if pop < 500:  return 3
        if pop < 900:  return 4
        if pop < 1500: return 5
        if pop < 2500: return 6
        if pop < 4000: return 7
        if pop < 6000: return 8
        return 9

    def num_active_hoods():
        if pop < 50:   return 4
        if pop < 150:  return 8
        if pop < 400:  return 16
        if pop < 800:  return 24
        if pop < 1500: return 36
        if pop < 3000: return 50
        return len(neighborhoods)

    n_plants = num_active_plants()
    n_hoods = num_active_hoods()
    active_plants = plant_positions[:n_plants]
    active_hoods = neighborhoods[:n_hoods]

    # --- ENSURE POWER PLANTS ---
    for (px, py) in active_plants:
        y0 = max(0, py - 3); y1 = min(WORLD_H, py + 4)
        x0 = max(0, px - 3); x1 = min(WORLD_W, px + 4)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find a clear spot near target
            for r in range(0, 6):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- WIRE GRID: Connect all plants with horizontal and vertical wires ---
    # Horizontal wires at plant row heights
    plant_rows = sorted(set(py for (px, py) in active_plants))
    for row_y in plant_rows:
        row_plants = sorted([px for (px, py) in active_plants if py == row_y])
        if len(row_plants) >= 2:
            for i in range(len(row_plants) - 1):
                x1, x2 = row_plants[i], row_plants[i+1]
                for wx in range(x1 + 3, x2 - 2):
                    if ib(wx, row_y) and (bool(em[row_y, wx]) or bool(wm[row_y, wx])) and not bool(pm[row_y, wx]):
                        return (Tool.WIRE, wx, row_y)

    # Vertical wires connecting plant rows
    plant_cols = sorted(set(px for (px, py) in active_plants))
    for col_x in plant_cols:
        col_plants = sorted([py for (px, py) in active_plants if px == col_x])
        if len(col_plants) >= 2:
            for i in range(len(col_plants) - 1):
                y1c, y2c = col_plants[i], col_plants[i+1]
                for wy in range(y1c + 3, y2c - 2):
                    if ib(col_x, wy) and (bool(em[wy, col_x]) or bool(wm[wy, col_x])) and not bool(pm[wy, col_x]):
                        return (Tool.WIRE, col_x, wy)

    # --- ROAD GRID: Build horizontal and vertical roads ---
    # Road grid every 6 tiles, offset from wires
    road_cols = list(range(6, WORLD_W - 2, 6))
    road_rows = list(range(6, WORLD_H - 2, 6))

    # Prioritize road rows near active neighborhoods
    active_hood_ys = sorted(set(cy for (cx, cy) in active_hoods))
    active_hood_xs = sorted(set(cx for (cx, cy) in active_hoods))

    # Find closest road row/col to each active neighborhood
    def nearest(val, lst):
        return min(lst, key=lambda v: abs(v - val))

    priority_road_rows = sorted(set(nearest(hy, road_rows) for hy in active_hood_ys))
    priority_road_cols = sorted(set(nearest(hx, road_cols) for hx in active_hood_xs))

    # Build priority roads first
    for ry in priority_road_rows:
        for rx in range(2, WORLD_W - 2):
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                return (Tool.ROAD, rx, ry)

    for rx in priority_road_cols:
        for ry in range(2, WORLD_H - 2):
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # --- BUILD NEIGHBOR MASKS for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT near active neighborhoods ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 400:
                break

    # --- EXTRA WIRE from existing wire to expand reach ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k2 = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k2 + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES (proactive placement) ---
    # Fire stations: placed early, every ~20 tiles
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(12, WORLD_H - 5, 20) for fx in range(12, WORLD_W - 5, 20)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_grid = [(px2, py2) for py2 in range(18, WORLD_H - 5, 25) for px2 in range(18, WORLD_W - 5, 25)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for (sx, sy) in [(30, 8), (70, 8), (110, 8), (30, 92), (70, 92), (110, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [(20, 5), (60, 5), (100, 5), (20, 95), (60, 95), (100, 95)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PARKS near zones ---
    if pop > 100:
        zone_map2 = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map2)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 20)):
                k = (step * 3 + i * 17) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx3 + dx2, zy3 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- LAST RESORT: road near zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in a 3x3 grid with wire spines and flanking roads."""
    actions = []
    # 9 plants: 3 columns x 3 rows covering the map well
    for px in [20, 60, 100]:
        for py in [25, 50, 75]:
            actions.append((Tool.COALPOWER, px, py))
            # Vertical wire spine
            for dy in range(-8, 9):
                actions.append((Tool.WIRE, px, py + dy))
            # Flanking roads
            for dy in range(-8, 9):
                actions.append((Tool.ROAD, px - 2, py + dy))
                actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 anchor neighborhoods in a 3x3 grid
    all_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [25, 50, 75]:
            all_anchors.append((col_x, row_y))

    # Additional expansion anchors for large cities
    expansion_anchors = []
    for col_x in [10, 40, 80, 112]:
        for row_y in [15, 40, 65, 88]:
            expansion_anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 3
        if pop < 500:   return 4
        if pop < 800:   return 5
        if pop < 1200:  return 6
        if pop < 1800:  return 7
        if pop < 2500:  return 8
        return 9

    def num_expansion():
        if pop < 2000:  return 0
        if pop < 3000:  return 2
        if pop < 4000:  return 4
        if pop < 5000:  return 8
        return len(expansion_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]
    n_exp = num_expansion()
    if n_exp > 0:
        active_anchors = active_anchors + expansion_anchors[:n_exp]

    # ---- ENSURE POWER PLANTS ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 8); y1 = min(WORLD_H, ay + 9)
        x0 = max(0, ax - 8); x1 = min(WORLD_W, ax + 9)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.COALPOWER, ax, ay)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- VERTICAL WIRE SPINE per anchor ----
    spine_half = min(35, 10 + pop // 10)
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - spine_half)
        spine_bot = min(WORLD_H - 3, ay + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            for dy in range(-4, 5):
                ny = ay + dy
                if ib(ax, ny) and bool(em[ny, ax]) and not bool(pm[ny, ax]):
                    return (Tool.WIRE, ax, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(ax, nr) and (bool(em[nr, ax]) or bool(wm[nr, ax])) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(ax, nr) and (bool(em[nr, ax]) or bool(wm[nr, ax])) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(ay for (ax, ay) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor columns ----
    if n_active >= 2:
        x_cols = sorted(set(ax for (ax, ay) in active_anchors))
        for col_x in x_cols:
            col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1 = col_anchors[i]
                _, y2 = col_anchors[i + 1]
                for cy in range(y1 + 1, y2):
                    if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                        return (Tool.WIRE, col_x, cy)

    # ---- ROAD FLANKING wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_top = max(2, ay - spine_half)
        spine_bot = min(WORLD_H - 3, ay + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            for road_x in [ax - 2, ax + 2]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- HORIZONTAL ROADS at y-levels (above and below) ----
    if pop > 20:
        for yl in y_levels:
            row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == yl], key=lambda a: a[0])
            if len(row_anchors) < 2:
                continue
            xl = row_anchors[0][0] - 3
            xr = row_anchors[-1][0] + 3
            for horiz_y in [yl - 3, yl + 3]:
                if not (0 <= horiz_y < WORLD_H):
                    continue
                for cx in range(max(2, xl), min(WORLD_W - 2, xr + 1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting y-levels per column ----
    if pop > 60:
        x_cols = sorted(set(ax for (ax, ay) in active_anchors))
        for col_x in x_cols:
            col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
            if len(col_anchors) < 2:
                continue
            y_top = col_anchors[0][1] - 3
            y_bot = col_anchors[-1][1] + 3
            for vert_x in [col_x - 3, col_x + 3]:
                if not (0 <= vert_x < WORLD_W):
                    continue
                for cy in range(max(2, y_top), min(WORLD_H - 2, y_bot + 1)):
                    if ib(vert_x, cy) and bool(em[cy, vert_x]) and not bool(pm[cy, vert_x]):
                        return (Tool.ROAD, vert_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = []
        for fx in [8, 30, 55, 80, 105, 115]:
            for fy in [8, 20, 35, 50, 65, 80, 92]:
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = []
        for px2 in [15, 38, 62, 85, 110]:
            for py2 in [12, 30, 48, 66, 85]:
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10), (110, 10),
            (10, 90), (50, 90), (90, 90), (110, 90),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92), (30, 6), (85, 6), (30, 92), (85, 92)]:
            ax2, ay2 = asp
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5), (60, 2)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle + wire spine + initial roads"""
    actions = []
    # Three coal plants: left, right, center-top
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    actions.append((Tool.COALPOWER, 60, 20))
    # Wire connecting left to right horizontally
    for x in range(22, 100):
        actions.append((Tool.WIRE, x, 50))
    # Wire from center horizontal line up to top plant
    for y in range(22, 50):
        actions.append((Tool.WIRE, 60, y))
    # Initial horizontal roads (2 lanes above/below wire)
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    # Vertical roads at thirds
    for y in range(5, 95):
        actions.append((Tool.ROAD, 20, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 100, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: 40% res, 30% com, 30% ind — more commercial/industrial than parent
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        rr = res_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        ir = ind_count / max(total_zones, 1)
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense grid of plant positions — every 15 tiles (more plants than parent)
    plant_positions = []
    for py in range(10, 96, 15):
        for px in range(10, 116, 15):
            plant_positions.append((px, py))

    # --- PHASE 1: Ensure dense power plant coverage ---
    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Wire - extend power grid ---
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Find unpowered plant positions first
        unpowered_plants = [(px, py) for px, py in plant_positions
                            if ib(px, py) and pm[py, px] and not bool(near_power[py, px])]
        if not unpowered_plants:
            unpowered_plants = [(px, py) for px, py in plant_positions
                                if ib(px, py) and not bool(near_power[py, px])]

        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered empty areas
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0:
            best_dist = 1e9
            best_k = 0
            rng_idx = np.arange(len(upxs))
            sample_idx = rng_idx[::max(1, len(upxs)//50)][:50]
            for i in range(min(len(wxs), 300)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Dense road grid every 4 tiles (denser than parent's 6) ---
    road_targets = []
    for gy in range(5, 97, 4):
        for gx in range(5, 117, 4):
            road_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:30]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Prefer: close to road, spread out from existing zones
        score = road_dist * 1.5 + np.maximum(0, 8 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    # Fire stations every 8 tiles (denser than parent)
    if pop > 50:
        fire_positions = [(fx, fy) for fy in range(8, 95, 8) for fx in range(8, 115, 8)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_positions = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 10)]
        for psx, psy in police_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_positions = [(pkx, pky) for pky in range(6, 95, 6) for pkx in range(6, 115, 6)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 600:
        stadium_locs = [(25, 25), (95, 25), (25, 75), (95, 75),
                        (60, 50), (60, 15), (60, 85), (15, 50), (105, 50),
                        (40, 40), (80, 40), (40, 60), (80, 60)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (60, 10), (60, 90), (10, 50), (110, 50),
                     (40, 10), (80, 10), (40, 90), (80, 90)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 8), (75, 8), (55, 91), (75, 91),
                        (8, 30), (110, 30), (8, 65), (110, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91),
                        (15, 20), (105, 20), (15, 80), (105, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: place roads near power plants ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (4, 0), (0, 4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
