def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 35% res, 40% com, 25% ind — more commercial than parent
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.40:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # 6 clusters arranged in 3x2 grid covering the map well
    # Cols: 20, 60, 100; Rows: 25, 75
    all_cluster_positions = [
        (20, 25), (60, 25), (100, 25),
        (20, 75), (60, 75), (100, 75),
    ]

    # Scale active clusters with population
    def active_clusters():
        if pop < 200:
            return [(30, 50), (90, 50)]
        if pop < 600:
            return [(20, 25), (100, 25), (20, 75), (100, 75)]
        if pop < 1500:
            return [(20, 25), (60, 25), (100, 25),
                    (20, 75), (60, 75), (100, 75)]
        # Full 6 clusters + central ones
        return [(20, 25), (60, 25), (100, 25),
                (20, 50), (60, 50), (100, 50),
                (20, 75), (60, 75), (100, 75)]

    clusters = active_clusters()

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            for r in range(15):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- EXTEND WIRE FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(20, 6 + pop // 25)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS WITH WIRE HORIZONTALLY ----
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows_set:
        row_clusters = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 12])
        for i in range(len(row_clusters) - 1):
            c1, c2 = row_clusters[i], row_clusters[i + 1]
            for y_off in [0]:
                wy = cy + y_off
                if not ib(0, wy):
                    continue
                all_wired = all(bool(wm[wy, x] or pm[wy, x])
                                for x in range(c1, c2 + 1) if ib(x, wy))
                if not all_wired:
                    for x in range(c1, c2 + 1):
                        if ib(x, wy) and not bool(pm[wy, x]) and bool(em[wy, x]):
                            return (Tool.WIRE, x, wy)

    # ---- CONNECT CLUSTERS WITH WIRE VERTICALLY ----
    for cx in active_cols_set:
        col_clusters = sorted([cy for c_cx, cy in clusters if abs(c_cx - cx) <= 12])
        for i in range(len(col_clusters) - 1):
            r1, r2 = col_clusters[i], col_clusters[i + 1]
            all_wired = all(bool(wm[y, cx] or pm[y, cx])
                            for y in range(r1, r2 + 1) if ib(cx, y))
            if not all_wired:
                for y in range(r1, r2 + 1):
                    if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]):
                        return (Tool.WIRE, cx, y)

    # ---- BUILD ROAD GRID AROUND EACH CLUSTER ----
    # Use 4 parallel road lanes (at ±3 and ±6) for denser coverage
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        for road_y_off in [-3, 3, -6, 6]:
            road_y = cy + road_y_off
            if not ib(cx, road_y):
                continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)
        for road_x_off in [-3, 3, -6, 6]:
            road_x = cx + road_x_off
            if not ib(road_x, cy):
                continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS ----
    if pop > 150:
        for cy in active_rows_set:
            row_cx = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 14])
            for i in range(len(row_cx) - 1):
                c1, c2 = row_cx[i], row_cx[i + 1]
                for road_y in [cy - 4, cy + 4]:
                    if not (0 <= road_y < WORLD_H):
                        continue
                    has_road = any(bool(rm[road_y, x]) for x in range(c1, c2 + 1) if ib(x, road_y))
                    if not has_road:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    if pop > 400:
        for cx in active_cols_set:
            col_cy = sorted([cy for c_cx, cy in clusters if abs(c_cx - cx) <= 14])
            for i in range(len(col_cy) - 1):
                r1, r2 = col_cy[i], col_cy[i + 1]
                for road_x in [cx - 4, cx + 4]:
                    if not (0 <= road_x < WORLD_W):
                        continue
                    has_road = any(bool(rm[y, road_x]) for y in range(r1, r2 + 1) if ib(road_x, y))
                    if not has_road:
                        for y in range(r1, r2 + 1):
                            if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]):
                                return (Tool.ROAD, road_x, y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) +
                 np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(10, 95, 18) for fx in range(10, 115, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px, py) for py in range(12, 90, 16) for px in range(12, 112, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(20, 8), (60, 8), (100, 8),
                         (20, 92), (60, 92), (100, 92)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Nuclear power plants for high-density zones
        nuke_spots = [(10, 12), (60, 12), (110, 12),
                      (10, 88), (60, 88), (110, 88),
                      (10, 50), (110, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 90), (115, 10)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 50)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

# Ambitious closed-loop city builder
# Strategy: Build a dense grid of neighborhoods across the whole map
# Each neighborhood has its own power plant, wire grid, and road network
# Zones are packed tightly between roads with wire connections

def init(obs, state):
    """Bootstrap: place first coal plant and seed infrastructure."""
    actions = []
    # Primary plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spine vertically
    for dy in range(-4, 5):
        actions.append((Tool.WIRE, 60, 50 + dy))
    # Roads flanking wire
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- NEIGHBORHOOD GRID ----
    # Dense grid of neighborhoods covering entire map
    # Plant positions every 20 cols, 20 rows apart
    # Wire spines at plant col, roads at plant_col +/- 1
    # Neighborhoods: centers at (10,10), (30,10), (50,10)... 
    # Actually use a 20-unit grid for plants
    plant_cols = [10, 30, 50, 70, 90, 110]
    plant_rows = [15, 35, 55, 75, 90]

    # Scale active neighborhoods based on population
    def max_neighborhoods():
        if pop < 200:
            return 1
        elif pop < 600:
            return 3
        elif pop < 1500:
            return 6
        elif pop < 3000:
            return 12
        elif pop < 6000:
            return 18
        else:
            return len(plant_cols) * len(plant_rows)

    # Build list of neighborhood centers in priority order
    # Start from center, expand outward
    all_neighborhoods = []
    center_col = 3  # index of col ~60
    center_row = 2  # index of row ~55
    for pr in plant_rows:
        for pc in plant_cols:
            all_neighborhoods.append((pc, pr))

    # Sort by distance from center (60, 50)
    all_neighborhoods.sort(key=lambda nb: abs(nb[0]-60) + abs(nb[1]-50))

    max_nb = max_neighborhoods()
    active_nbs = all_neighborhoods[:max_nb]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_nbs:
        # Check if plant exists within 5 tiles of anchor
        has_plant = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break

        if not has_plant:
            # Find empty spot near anchor for plant
            for r in range(0, 6):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINES ----
    # For each active neighborhood, build vertical wire spine
    pop_reach = min(40, 8 + pop // 50)

    for (px, py) in active_nbs:
        wc = px  # wire column = plant column
        spine_top = max(2, py - pop_reach)
        spine_bot = min(WORLD_H - 3, py + pop_reach)

        # Find connected wire in this column
        wire_in_col = []
        for r in range(WORLD_H):
            if ib(wc, r) and bool(wm[r, wc]):
                wire_in_col.append(r)

        if not wire_in_col:
            # Seed wire adjacent to plant
            for dy in range(-3, 4):
                ny = py + dy
                if ib(wc, ny) and not bool(pm[ny, wc]):
                    if bool(em[ny, wc]):
                        return (Tool.WIRE, wc, ny)
                    # Try column +1
                    if ib(wc+1, ny) and bool(em[ny, wc+1]):
                        return (Tool.WIRE, wc+1, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            # Extend downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and bool(em[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            # Extend upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and bool(em[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE CONNECTIONS ----
    # Connect neighboring wire spines horizontally at their anchor rows
    for i, (px1, py1) in enumerate(active_nbs):
        for j, (px2, py2) in enumerate(active_nbs):
            if i >= j:
                continue
            # Connect if same row and adjacent columns
            if py1 == py2 and abs(px1 - px2) <= 22:
                min_c = min(px1, px2)
                max_c = max(px1, px2)
                for cx in range(min_c, max_c + 1):
                    if ib(cx, py1) and bool(em[py1, cx]) and not bool(pm[py1, cx]):
                        return (Tool.WIRE, cx, py1)
            # Connect vertically if same column and adjacent rows
            if px1 == px2 and abs(py1 - py2) <= 22:
                min_r = min(py1, py2)
                max_r = max(py1, py2)
                for cy in range(min_r, max_r + 1):
                    if ib(px1, cy) and bool(em[cy, px1]) and not bool(pm[cy, px1]):
                        return (Tool.WIRE, px1, cy)

    # ---- ROAD NETWORK ----
    # Roads run parallel to wire spines, plus horizontal connectors
    for (px, py) in active_nbs:
        wc = px
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue

        # Left and right road columns
        for road_col in [wc - 1, wc + 1]:
            if not ib(road_col, py):
                continue
            for wr in wire_in_col:
                if ib(road_col, wr) and bool(em[wr, road_col]) and not bool(pm[wr, road_col]):
                    return (Tool.ROAD, road_col, wr)

        # Horizontal roads every 4 rows through wire extent
        if wire_in_col:
            for hr in range(min(wire_in_col), max(wire_in_col) + 1, 4):
                # Extend road horizontally from wire
                for dx in range(-8, 9):
                    hx = wc + dx
                    if ib(hx, hr) and bool(em[hr, hx]) and not bool(pm[hr, hx]):
                        # Only place if adjacent to existing road or wire
                        has_infra = False
                        for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                            ax, ay = hx+adx, hr+ady
                            if ib(ax, ay) and (bool(rm[ay, ax]) or bool(wm[ay, ax]) or bool(pm[ay, ax])):
                                has_infra = True
                                break
                        if has_infra:
                            return (Tool.ROAD, hx, hr)

    # ---- COMPUTE NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in [-1, 0, 1, 2, -2]:
        for dx in [-1, 0, 1, 2, -2]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Candidate zone spots: empty, near road, near wire, away from edges
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active neighborhood anchors
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_nbs:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 150)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 40)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = rx+dx, ry+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- CIVIC SERVICES ----
    civic_interval = max(200, 1000 // max(len(active_nbs), 1))

    if pop > 200:
        # Fire stations near each neighborhood
        for (px, py) in active_nbs:
            for dx, dy in [(3,0),(-3,0),(0,3),(0,-3),(4,0),(-4,0)]:
                fx, fy = px+dx, py+dy
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 600:
        for (px, py) in active_nbs:
            for dx, dy in [(3,3),(-3,3),(3,-3),(-3,-3),(5,0),(-5,0)]:
                fx, fy = px+dx, py+dy
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.POLICESTATION, fx, fy)

    if pop > 2000:
        stadium_spots = [(55,10),(55,85),(15,50),(100,50),(35,30),(80,30),(35,70),(80,70)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 4000:
        port_spots = [(10,10),(10,85),(105,10),(105,85)]
        for (sx, sy) in port_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- FALLBACK: extend wire laterally ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (step * 13) % max(len(wire_xs), 1)
        for offset in range(min(len(wire_xs), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Only extend toward active neighborhoods
                    for (px, py) in active_nbs:
                        if abs(nx - px) + abs(ny - py) < 20:
                            return (Tool.WIRE, nx, ny)

    return None

# Ambitious closed-loop city builder
# Strategy: Multiple power plant hubs connected by wire grid,
# dense zone clusters with mixed R/C/I, comprehensive road network

def init(obs, state):
    """Bootstrap: 3 coal plants + wire connections + initial roads."""
    actions = []
    # Three power plant hubs
    hubs = [(20, 25), (60, 50), (100, 75)]
    for (px, py) in hubs:
        actions.append((Tool.COALPOWER, px, py))
        # Wire in 4 directions from each plant
        for d in range(1, 6):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px - d, py))
            actions.append((Tool.WIRE, px, py + d))
            actions.append((Tool.WIRE, px, py - d))
    # Initial road spine connecting the hubs
    for x in range(21, 60):
        actions.append((Tool.ROAD, x, 25))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- MULTIPLE NEIGHBORHOOD HUBS scattered across the map ----
    # 6 columns x 5 rows = 30 neighborhoods, well-spread
    nh_cols = [12, 30, 50, 70, 90, 108]
    nh_rows = [12, 28, 50, 72, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Power plant hub locations (one per 2x2 block of neighborhoods)
    hub_locations = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]

    # Progressive unlock
    def num_active():
        if pop < 100:   return 4
        if pop < 400:   return 8
        if pop < 1000:  return 14
        if pop < 2000:  return 20
        if pop < 4000:  return 26
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS across hub locations ----
    # Check how many hubs we need active
    n_hubs_needed = max(1, n_active // 4)
    for i in range(min(n_hubs_needed + 1, len(hub_locations))):
        hx, hy = hub_locations[i]
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place coal plant at hub
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            # Find nearby empty
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- BUILD PROXIMITY MASKS ----
    power_src = wm | pm
    # Fast dilation using slices
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 2: WIRE GRID connecting hubs to neighborhoods ----
    # Round-robin: each step extend wire from one hub toward nearby hoods
    hub_idx = step % len(hub_locations)
    hx_hub, hy_hub = hub_locations[hub_idx]

    # Extend wires in a cross pattern from this hub
    spine_range = 18
    if bool(np.any(pm[max(0,hy_hub-4):min(WORLD_H,hy_hub+5),
                      max(0,hx_hub-4):min(WORLD_W,hx_hub+5)])):
        # Find the plant location
        y0, y1 = max(0, hy_hub-5), min(WORLD_H, hy_hub+6)
        x0, x1 = max(0, hx_hub-5), min(WORLD_W, hx_hub+6)
        pys, pxs = np.where(pm[y0:y1, x0:x1])
        if len(pxs) > 0:
            px_hub = int(pxs[0]) + x0
            py_hub = int(pys[0]) + y0

            # Extend wire horizontally
            for dx in range(-spine_range, spine_range + 1):
                wx = px_hub + dx
                if not ib(wx, py_hub): continue
                if bool(pm[py_hub, wx]) or bool(wm[py_hub, wx]): continue
                if not bool(em[py_hub, wx]): continue
                for adj in [-1, 1]:
                    ax = wx + adj
                    if ib(ax, py_hub) and (bool(wm[py_hub, ax]) or bool(pm[py_hub, ax])):
                        return (Tool.WIRE, wx, py_hub)

            # Extend wire vertically
            for dy in range(-spine_range, spine_range + 1):
                wy = py_hub + dy
                if not ib(px_hub, wy): continue
                if bool(pm[wy, px_hub]) or bool(wm[wy, px_hub]): continue
                if not bool(em[wy, px_hub]): continue
                for adj in [-1, 1]:
                    ay = wy + adj
                    if ib(px_hub, ay) and (bool(wm[ay, px_hub]) or bool(pm[ay, px_hub])):
                        return (Tool.WIRE, px_hub, wy)

    # ---- PHASE 3: INTER-HUB WIRE CONNECTIONS ----
    # Connect adjacent hubs horizontally and vertically
    hood_step = step % max(len(active_hoods), 1)
    hx_h, hy_h = active_hoods[hood_step]

    # Draw wire from nearest powered tile toward this hood
    if not bool(nbr_power[hy_h, hx_h]):
        # Find nearest wire or plant
        best_dist2 = 9999
        best_wx, best_wy = -1, -1
        ws_ys, ws_xs = np.where(power_src)
        if len(ws_xs) > 0:
            dists = np.abs(ws_xs - hx_h) + np.abs(ws_ys - hy_h)
            idx2 = int(np.argmin(dists))
            best_wx, best_wy = int(ws_xs[idx2]), int(ws_ys[idx2])

        if best_wx >= 0:
            # Step toward hood
            dx = hx_h - best_wx
            dy = hy_h - best_wy
            if abs(dx) >= abs(dy):
                step_x = 1 if dx > 0 else -1
                for wx2 in range(best_wx + step_x, hx_h + step_x, step_x):
                    if not ib(wx2, best_wy): break
                    if bool(pm[best_wy, wx2]): continue
                    if bool(wm[best_wy, wx2]): continue
                    if not bool(em[best_wy, wx2]): continue
                    return (Tool.WIRE, wx2, best_wy)
            else:
                step_y = 1 if dy > 0 else -1
                for wy2 in range(best_wy + step_y, hy_h + step_y, step_y):
                    if not ib(best_wx, wy2): break
                    if bool(pm[wy2, best_wx]): continue
                    if bool(wm[wy2, best_wx]): continue
                    if not bool(em[wy2, best_wx]): continue
                    return (Tool.WIRE, best_wx, wy2)

    # ---- PHASE 4: ROAD NETWORK ----
    # Build horizontal and vertical road arteries
    # Main horizontal roads at fixed y positions
    road_y_lines = [12, 28, 50, 72, 88]
    road_x_lines = [12, 30, 50, 70, 90, 108]

    # Build road along horizontal lines
    rl_idx = step % len(road_y_lines)
    ry_line = road_y_lines[rl_idx]
    for x in range(3, WORLD_W - 3):
        if bool(em[ry_line, x]) and not bool(pm[ry_line, x]):
            # Only place road if adjacent to road or near power
            left_ok = x > 0 and bool(rm[ry_line, x-1])
            right_ok = x < WORLD_W-1 and bool(rm[ry_line, x+1])
            if left_ok or right_ok:
                return (Tool.ROAD, x, ry_line)

    # Build road along vertical lines
    rv_idx = (step + 2) % len(road_x_lines)
    rx_line = road_x_lines[rv_idx]
    for y in range(3, WORLD_H - 3):
        if bool(em[y, rx_line]) and not bool(pm[y, rx_line]):
            up_ok = y > 0 and bool(rm[y-1, rx_line])
            dn_ok = y < WORLD_H-1 and bool(rm[y+1, rx_line])
            if up_ok or dn_ok:
                return (Tool.ROAD, rx_line, y)

    # ---- PHASE 5: FLANKING ROADS near wire spines ----
    hood_idx2 = (step + 5) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]
    spine_r = 10
    for rx in [hx3 - 1, hx3 + 1]:
        if not ib(rx, hy3): continue
        for dy in range(-spine_r, spine_r + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                return (Tool.ROAD, rx, ry)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 35% RES, 35% COM, 30% IND
        if ir < 0.27:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS NEAR POWER ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 20)
                      for fy in range(15, WORLD_H, 20)]
        fs_step = (step // 3) % max(len(fire_spots), 1)
        for i in range(len(fire_spots)):
            sx, sy = fire_spots[(fs_step + i) % len(fire_spots)]
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(20, WORLD_W, 25)
                        for py2 in range(20, WORLD_H, 25)]
        ps_step = (step // 4) % max(len(police_spots), 1)
        for i in range(len(police_spots)):
            sx, sy = police_spots[(ps_step + i) % len(police_spots)]
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(25, 40), (95, 40), (25, 60), (95, 60),
                         (60, 15), (60, 85), (10, 50), (110, 50)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaport_spots = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airport_spots = [(40, 5), (80, 5), (40, 93), (80, 93)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear upgrade for large cities
    if pop > 2000 and step % 3 == 0:
        for (nx2, ny2) in hub_locations:
            x0, x1 = max(0, nx2-4), min(WORLD_W, nx2+5)
            y0, y1 = max(0, ny2-4), min(WORLD_H, ny2+5)
            has_nuke = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_nuke and ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # FALLBACK: place plant near uncovered hood
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Compact, dense, closed-loop city builder
# Key differences from parent:
# - Denser neighborhood grid (more hoods, closer spacing)
# - Simpler, more reliable wire/road logic
# - Better zone placement (checks 3x3 clearance properly)
# - Multiple coal plants per major zone
# - Balanced R/C/I mix from the start

def init(obs, state):
    """Bootstrap: central power plant + cross wire/road."""
    actions = []
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from plant
    for d in range(1, 6):
        actions.append((Tool.WIRE, 60 + d, 50))
        actions.append((Tool.WIRE, 60 - d, 50))
        actions.append((Tool.WIRE, 60, 50 + d))
        actions.append((Tool.WIRE, 60, 50 - d))
    # Roads parallel to wire
    for d in range(-4, 5):
        actions.append((Tool.ROAD, 59, 50 + d))
        actions.append((Tool.ROAD, 61, 50 + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- NEIGHBORHOOD DEFINITIONS ---
    # Denser grid: 6 cols x 5 rows = 30 neighborhoods
    # Each hood has a plant location, wire spine, road flanks
    hood_cols = [12, 28, 44, 60, 76, 92, 108]
    hood_rows = [12, 28, 44, 60, 76, 90]
    all_hoods = [(cx, cy) for cx in hood_cols for cy in hood_rows]

    # Unlock hoods progressively
    def n_active():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 700:   return 7
        if pop < 1500:  return 12
        if pop < 3000:  return 18
        if pop < 6000:  return 25
        return len(all_hoods)

    na = n_active()
    # Spread hoods evenly
    if na >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        step_sz = len(all_hoods) / na
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(na)]

    # --- PHASE 1: ENSURE POWER PLANTS ---
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant at or near hood center
            for r in range(0, 10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # --- PHASE 2: WIRE SPINES ---
    # For each active hood, maintain a cross wire spine
    for (hx, hy) in active_hoods:
        # Find plant near hood
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        sub_pm = pm[y0:y1, x0:x1]
        plant_locs = list(zip(*np.where(sub_pm)))
        if not plant_locs:
            continue
        # Plant absolute coords
        pr, pc = plant_locs[0]
        px_abs = x0 + pc
        py_abs = y0 + pr

        # Extend wire from plant outward in 4 directions
        # Target: wire from plant reaching ±15 tiles
        reach = 14
        for direction in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            dx, dy2 = direction
            # Walk from plant outward
            prev_x, prev_y = px_abs, py_abs
            for dist in range(1, reach + 1):
                wx = px_abs + dx * dist
                wy = py_abs + dy2 * dist
                if not ib(wx, wy):
                    break
                if bool(pm[wy, wx]):
                    break  # Don't overwrite another plant
                if not bool(wm[wy, wx]):
                    if bool(em[wy, wx]) or bool(rm[wy, wx]):
                        return (Tool.WIRE, wx, wy)
                    else:
                        break  # Blocked

    # --- PHASE 3: CONNECT WIRE SPINES BETWEEN HOODS ---
    # Connect horizontally adjacent hoods
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods:
            if hx2 <= hx1 or abs(hy1 - hy2) > 8:
                continue
            # Find gap in wire at row hy1
            target_y = (hy1 + hy2) // 2
            # Find nearest wire in this row
            row_wire_cols = [c for c in range(min(hx1, hx2), max(hx1, hx2) + 1)
                             if ib(c, target_y) and bool(wm[target_y, c])]
            if not row_wire_cols:
                # Drop a wire somewhere in the gap
                mid = (hx1 + hx2) // 2
                if ib(mid, target_y) and bool(em[target_y, mid]):
                    return (Tool.WIRE, mid, target_y)
                continue
            max_c = max(row_wire_cols)
            min_c = min(row_wire_cols)
            if max_c < max(hx1, hx2) - 2:
                nc = max_c + 1
                if ib(nc, target_y) and not bool(pm[target_y, nc]):
                    if bool(em[target_y, nc]) or bool(wm[target_y, nc]):
                        return (Tool.WIRE, nc, target_y)
            if min_c > min(hx1, hx2) + 2:
                nc = min_c - 1
                if ib(nc, target_y) and not bool(pm[target_y, nc]):
                    if bool(em[target_y, nc]) or bool(wm[target_y, nc]):
                        return (Tool.WIRE, nc, target_y)

    # Also connect vertically adjacent hoods
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy2 <= hy1 or abs(hx1 - hx2) > 8:
                continue
            target_x = (hx1 + hx2) // 2
            col_wire_rows = [r for r in range(min(hy1, hy2), max(hy1, hy2) + 1)
                             if ib(target_x, r) and bool(wm[r, target_x])]
            if not col_wire_rows:
                mid = (hy1 + hy2) // 2
                if ib(target_x, mid) and bool(em[mid, target_x]):
                    return (Tool.WIRE, target_x, mid)
                continue
            max_r = max(col_wire_rows)
            min_r = min(col_wire_rows)
            if max_r < max(hy1, hy2) - 2:
                nr = max_r + 1
                if ib(target_x, nr) and not bool(pm[nr, target_x]):
                    if bool(em[nr, target_x]) or bool(wm[nr, target_x]):
                        return (Tool.WIRE, target_x, nr)
            if min_r > min(hy1, hy2) + 2:
                nr = min_r - 1
                if ib(target_x, nr) and not bool(pm[nr, target_x]):
                    if bool(em[nr, target_x]) or bool(wm[nr, target_x]):
                        return (Tool.WIRE, target_x, nr)

    # --- PHASE 4: ROAD NETWORK ---
    # Build roads flanking wire spines (at wire_x±1 and wire_y±1)
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        sub_pm = pm[y0:y1, x0:x1]
        plant_locs = list(zip(*np.where(sub_pm)))
        if not plant_locs:
            continue
        pr, pc = plant_locs[0]
        px_abs = x0 + pc
        py_abs = y0 + pr

        reach = 14
        # Roads on either side of vertical wire (px_abs ± 1)
        for rx in [px_abs - 1, px_abs + 1]:
            if not ib(rx, py_abs):
                continue
            for dist in range(-reach, reach + 1):
                ry = py_abs + dist
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Only build road near wire coverage
                    if bool(wm[ry, px_abs]) if ib(px_abs, ry) else False:
                        return (Tool.ROAD, rx, ry)

        # Roads on either side of horizontal wire (py_abs ± 1)
        for ry in [py_abs - 1, py_abs + 1]:
            if not ib(hx, ry):
                continue
            for dist in range(-reach, reach + 1):
                rxc = px_abs + dist
                if not ib(rxc, ry):
                    continue
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    if bool(wm[py_abs, rxc]) if ib(rxc, py_abs) else False:
                        return (Tool.ROAD, rxc, ry)

    # --- PHASE 5: ZONE PLACEMENT ---
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% res, 35% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        # Check 3x3 area around center is clear
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build "near road" mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-2, 3):
        for ddx in range(-2, 3):
            r0s = max(0, -ddy); r1s = min(WORLD_H, WORLD_H - ddy)
            c0s = max(0, -ddx); c1s = min(WORLD_W, WORLD_W - ddx)
            r0d = max(0, ddy); r1d = min(WORLD_H, WORLD_H + ddy)
            c0d = max(0, ddx); c1d = min(WORLD_W, WORLD_W + ddx)
            nbr_road[r0d:r1d, c0d:c1d] |= rm[r0s:r1s, c0s:c1s]

    # Build "near power" mask (within 3 tiles of wire or plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-3, 4):
        for ddx in range(-3, 4):
            r0s = max(0, -ddy); r1s = min(WORLD_H, WORLD_H - ddy)
            c0s = max(0, -ddx); c1s = min(WORLD_W, WORLD_W - ddx)
            r0d = max(0, ddy); r1d = min(WORLD_H, WORLD_H + ddy)
            c0d = max(0, ddx); c1d = min(WORLD_W, WORLD_W + ddx)
            nbr_power[r0d:r1d, c0d:c1d] |= wm[r0s:r1s, c0s:c1s]
            nbr_power[r0d:r1d, c0d:c1d] |= pm[r0s:r1s, c0s:c1s]

    cand_mask = em & nbr_road & nbr_power
    # Keep border margin
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step offset for variety
        offset_base = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(offset_base + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- PHASE 6: EXTEND ROADS from existing network ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 80)):
            k = (sk + off * 3) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2])
                        and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES ---
    if pop > 150:
        fire_spots = [(20, 20), (40, 20), (60, 20), (80, 20), (100, 20),
                      (20, 50), (40, 50), (60, 50), (80, 50), (100, 50),
                      (20, 80), (40, 80), (60, 80), (80, 80), (100, 80)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [(25, 35), (55, 35), (85, 35),
                        (25, 65), (55, 65), (85, 65),
                        (25, 90), (55, 90), (85, 90)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadiums = [(35, 45), (75, 45), (35, 65), (75, 65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        seaports = [(10, 85), (110, 85)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(55, 5), (55, 90)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- PHASE 8: PARKS near dense zones ---
    if pop > 300 and step % 4 == 0:
        pk_cands = np.where(em & nbr_road & nbr_power)
        if len(pk_cands[0]) > 0:
            idx = (step * 19) % len(pk_cands[0])
            py2, px2 = int(pk_cands[0][idx]), int(pk_cands[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- PHASE 9: EXTEND WIRE from existing wire ---
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        sk2 = (step * 13) % len(wire_xs)
        for off in range(min(len(wire_xs), 40)):
            k = (sk2 + off * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a horizontal line with wire and road spines."""
    actions = []
    # Three plants at key positions
    for px, py in [(20, 50), (60, 50), (100, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertical
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connecting the three plants
    for cx in range(21, 60):
        actions.append((Tool.WIRE, cx, 50))
    for cx in range(61, 100):
        actions.append((Tool.WIRE, cx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of plant/hood centers across the whole map
    # 5 columns x 5 rows = 25 potential neighborhoods
    all_plants = []
    for col_x in [10, 30, 55, 80, 110]:
        for row_y in [10, 28, 50, 72, 90]:
            all_plants.append((col_x, row_y))

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 3
        if pop < 500:   return 5
        if pop < 800:   return 7
        if pop < 1200:  return 10
        if pop < 1800:  return 14
        if pop < 2500:  return 18
        return len(all_plants)

    n_active = num_active()
    # Spread active plants evenly across map
    if n_active >= len(all_plants):
        active_plants = all_plants
    else:
        step_size = len(all_plants) / n_active
        active_plants = [all_plants[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_plants:
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        # Find empty spot near center
        for r in range(10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE VERTICAL SPINES ----
    spine_half = min(25, 8 + pop // 10)
    for (px, py) in active_plants:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        col_wire = [r for r in range(spine_top, spine_bot + 1)
                    if ib(px, r) and bool(wm[r, px])]
        col_plant = [r for r in range(WORLD_H) if ib(px, r) and bool(pm[r, px])]

        # Connect plant to wire
        if col_plant and not col_wire:
            ply = col_plant[0]
            for wy in [ply - 1, ply + 1]:
                if ib(px, wy) and bool(em[wy, px]) and not bool(pm[wy, px]):
                    return (Tool.WIRE, px, wy)

        if col_wire:
            min_wr = min(col_wire)
            max_wr = max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
        else:
            # Seed wire near plant
            for dy in range(-3, 4):
                ny2 = py + dy
                if ib(px, ny2) and bool(em[ny2, px]) and not bool(pm[ny2, px]):
                    return (Tool.WIRE, px, ny2)

    # ---- WIRE HORIZONTAL SPINES ----
    for (px, py) in active_plants:
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        row_wire = [c for c in range(spine_left, spine_right + 1)
                    if ib(c, py) and bool(wm[py, c])]

        if row_wire:
            min_wc = min(row_wire)
            max_wc = max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, py) and not bool(pm[py, nc]) and (bool(em[py, nc]) or bool(wm[py, nc])):
                    return (Tool.WIRE, nc, py)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, py) and not bool(pm[py, nc]) and (bool(em[py, nc]) or bool(wm[py, nc])):
                    return (Tool.WIRE, nc, py)

    # ---- CONNECT WIRE BETWEEN ADJACENT HOODS ----
    sorted_by_x = sorted(active_plants, key=lambda p: p[0])
    for i in range(len(sorted_by_x) - 1):
        hx1, hy1 = sorted_by_x[i]
        hx2, hy2 = sorted_by_x[i + 1]
        if abs(hy1 - hy2) <= 10 and hx2 - hx1 < 40:
            mid_y = (hy1 + hy2) // 2
            for cx in range(hx1 + 1, hx2):
                if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                    return (Tool.WIRE, cx, mid_y)

    # ---- CONNECT WIRE VERTICALLY BETWEEN HOODS ----
    sorted_by_y = sorted(active_plants, key=lambda p: p[1])
    for i in range(len(sorted_by_y) - 1):
        hx1, hy1 = sorted_by_y[i]
        hx2, hy2 = sorted_by_y[i + 1]
        if abs(hx1 - hx2) <= 10 and hy2 - hy1 < 35:
            mid_x = (hx1 + hx2) // 2
            for cy in range(hy1 + 1, hy2):
                if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                    return (Tool.WIRE, mid_x, cy)

    # ---- ROADS FLANKING VERTICAL WIRE SPINES ----
    for (px, py) in active_plants:
        col_wire = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not col_wire:
            continue
        cycle = (step) % 3
        for wr in col_wire[cycle::3]:
            for rx in [px - 1, px + 1]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- ROADS FLANKING HORIZONTAL WIRE SPINES ----
    for (px, py) in active_plants:
        row_wire = [c for c in range(WORLD_W) if ib(c, py) and bool(wm[py, c])]
        if not row_wire:
            continue
        cycle = (step + 1) % 3
        for wc in row_wire[cycle::3]:
            for ry in [py - 1, py + 1]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # ---- CROSS ROADS connecting hood rows ----
    if pop > 40:
        y_levels = sorted(set(py for (px, py) in active_plants))
        x_cols = sorted(set(px for (px, py) in active_plants))
        for col_x in x_cols:
            for i in range(len(y_levels) - 1):
                y1v = y_levels[i]
                y2v = y_levels[i + 1]
                for road_x in [col_x - 2, col_x + 2]:
                    if not ib(road_x, y2v):
                        continue
                    for cy in range(y1v, y2v + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_plants:
            d = (np.abs(cxs - px).astype(float) +
                 np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2])
                        and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 8), (35, 8), (65, 8), (95, 8), (115, 8),
            (8, 28), (35, 28), (65, 28), (95, 28), (115, 28),
            (8, 48), (35, 48), (65, 48), (95, 48), (115, 48),
            (8, 68), (35, 68), (65, 68), (95, 68), (115, 68),
            (8, 88), (35, 88), (65, 88), (95, 88), (115, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (20, 18), (50, 18), (80, 18), (110, 18),
            (20, 40), (50, 40), (80, 40), (110, 40),
            (20, 60), (50, 60), (80, 60), (110, 60),
            (20, 80), (50, 80), (80, 80), (110, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (12, 12), (55, 12), (100, 12),
            (12, 50), (55, 50), (100, 50),
            (12, 88), (55, 88), (100, 88),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_arr_y, zone_arr_x = np.where(zone_tiles)
        if len(zone_arr_x) > 0:
            for i in range(min(len(zone_arr_x), 40)):
                k = (step * 3 + i * 17) % len(zone_arr_x)
                zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 0), (-3, 0), (0, 3), (0, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
    if len(zone_arr_x2) > 0:
        k = (step * 19) % len(zone_arr_x2)
        zx3, zy3 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx3 + dx2, zy3 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: dense power grid with 9 coal plants in 3x3 grid + wire mesh"""
    actions = []
    # 9 coal plants in a 3x3 grid pattern
    plants = [
        (15, 15), (58, 15), (102, 15),
