def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        # Aim for 50% RES, 25% COM, 25% IND
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Power plant grid: 5 columns x 4 rows across whole map
    plant_grid = []
    for py in range(12, 92, 20):
        for px in range(12, 112, 24):
            plant_grid.append((px, py))

    # PHASE 1: Ensure enough power plants
    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # PHASE 2: Wire expansion — connect plants and zones to power grid
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    # Find unpowered plants
    unpowered_plants = [(px, py) for px, py in plant_grid
                        if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(len(wxs)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants)
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    if len(wxs) > 0:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # PHASE 3: Dense road grid — horizontal every 5 rows, vertical every 8 cols
    road_rows = list(range(5, 97, 5))
    for ry in road_rows:
        row_road = rm[ry, :]
        if int(np.sum(row_road)) < 110:
            # Build road across this row near power
            for rx in range(3, 117):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)
            # Even without power, extend road if adjacent to existing road
            for rx in range(3, 117):
                if bool(em[ry, rx]):
                    left_ok = rx > 0 and bool(rm[ry, rx-1])
                    right_ok = rx < WORLD_W-1 and bool(rm[ry, rx+1])
                    up_ok = ry > 0 and bool(rm[ry-1, rx])
                    down_ok = ry < WORLD_H-1 and bool(rm[ry+1, rx])
                    if left_ok or right_ok or up_ok or down_ok:
                        return (Tool.ROAD, rx, ry)

    road_cols = list(range(8, 116, 8))
    for cx2 in road_cols:
        for cy2 in range(3, 97):
            if bool(em[cy2, cx2]):
                adj = (cy2 > 0 and bool(rm[cy2-1, cx2])) or (cy2 < WORLD_H-1 and bool(rm[cy2+1, cx2]))
                if adj:
                    return (Tool.ROAD, cx2, cy2)

    # PHASE 4: Zone placement — fill in near roads and power
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    zone_cand &= ~rm & ~wm & ~pm

    def zone_clear(zx, zy):
        # Zone is 3x3, placed by center — check no roads/wires/plants in footprint
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(rm[nr, nc]) or bool(wm[nr, nc]) or bool(pm[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 300)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.ones(len(cxs_arr)) * 9999.0

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 300)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer close to roads, modest spread from other zones
            score = road_dist * 2.0 - np.clip(zone_dist, 0, 15) * 0.4
        else:
            # Start near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) + road_dist

        order = np.argsort(score)
        tool = pick_tool()
        for i in range(min(len(order), 1000)):
            k = order[i]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic services based on population
    if pop > 80:
        fire_grid = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 16)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_grid = [(ppx, ppy) for ppy in range(10, 93, 14) for ppx in range(10, 113, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_grid = [(pkx, pky) for pky in range(6, 97, 7) for pkx in range(6, 116, 9)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 600:
        stadium_locs = [(15, 15), (60, 15), (105, 15),
                        (15, 50), (60, 50), (105, 50),
                        (15, 85), (60, 85), (105, 85)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        # Upgrade to nuclear plants
        nuke_locs = [(60, 25), (20, 25), (100, 25),
                     (60, 75), (20, 75), (100, 75),
                     (40, 50), (80, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-7), min(WORLD_W, nx+8)
                y0, y1 = max(0, ny-7), min(WORLD_H, ny+8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1500:
        airport_locs = [(95, 10), (10, 10), (95, 85), (10, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend existing road
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k = (step * 13) % len(rxs2)
        rx2, ry2 = int(rxs2[k]), int(rys2[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from power
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place central coal plant + wire cross + flanking roads."""
    actions = []
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross
    for dx in range(-5, 6):
        actions.append((Tool.WIRE, 60 + dx, 50))
    for dy in range(-5, 6):
        actions.append((Tool.WIRE, 60, 50 + dy))
    # Flanking roads
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, 58, 50 + dy))
        actions.append((Tool.ROAD, 62, 50 + dy))
    for dx in range(-5, 6):
        actions.append((Tool.ROAD, 60 + dx, 48))
        actions.append((Tool.ROAD, 60 + dx, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- NEIGHBORHOOD GRID: 5 cols x 4 rows = 20 neighborhoods ----
    # Each neighborhood: anchor (cx, cy), wire column at cx
    # Roads at cx-2, cx+2; horizontal roads at cy-3, cy+3
    neighborhoods = []
    for col_i, cx in enumerate([15, 35, 60, 85, 105]):
        for row_i, cy in enumerate([15, 38, 62, 85]):
            neighborhoods.append({
                'cx': cx, 'cy': cy,
                'wc': cx,          # wire column
                'rl': cx - 2,      # left road col
                'rr': cx + 2,      # right road col
                'rt': cy - 3,      # top road row
                'rb': cy + 3,      # bottom road row
                'idx': col_i * 4 + row_i
            })

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 350:   return 4
        if pop < 600:   return 6
        if pop < 900:   return 8
        if pop < 1300:  return 11
        if pop < 2000:  return 14
        if pop < 3000:  return 17
        return 20

    active = neighborhoods[:num_active()]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.18:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- 1. ENSURE POWER PLANTS ----
    for nb in active:
        cx, cy = nb['cx'], nb['cy']
        # Check 9x9 neighborhood for plant
        x0, x1 = max(0, cx - 5), min(WORLD_W, cx + 6)
        y0, y1 = max(0, cy - 5), min(WORLD_H, cy + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant at anchor if empty
            if ib(cx, cy) and bool(em[cy, cx]):
                return (Tool.COALPOWER, cx, cy)
            # Search outward
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- 2. BUILD VERTICAL WIRE SPINES ----
    pop_ext = min(25, 5 + pop // 40)
    for nb in active:
        cx, cy, wc = nb['cx'], nb['cy'], nb['wc']
        spine_top = max(2, cy - 15 - pop_ext)
        spine_bot = min(WORLD_H - 3, cy + 15 + pop_ext)

        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(wc, r) and bool(wm[r, wc])]

        if not wire_rows:
            # Seed near plant
            for dy in range(-5, 6):
                ny = cy + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr, max_wr = min(wire_rows), max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE CONNECTIONS between same-row neighborhoods ----
    row_groups = {}
    for nb in active:
        cy = nb['cy']
        if cy not in row_groups:
            row_groups[cy] = []
        row_groups[cy].append(nb['wc'])

    for row_y, wcs in row_groups.items():
        if len(wcs) < 2:
            continue
        wcs_sorted = sorted(wcs)
        for i in range(len(wcs_sorted) - 1):
            wc1, wc2 = wcs_sorted[i], wcs_sorted[i + 1]
            for cx2 in range(wc1 + 1, wc2):
                if ib(cx2, row_y) and bool(em[row_y, cx2]) and not bool(pm[row_y, cx2]):
                    return (Tool.WIRE, cx2, row_y)

    # ---- 4. VERTICAL WIRE CONNECTIONS between same-column neighborhoods ----
    col_groups = {}
    for nb in active:
        cx2 = nb['cx']
        if cx2 not in col_groups:
            col_groups[cx2] = []
        col_groups[cx2].append(nb['cy'])

    for col_x, cys in col_groups.items():
        if len(cys) < 2:
            continue
        cys_sorted = sorted(cys)
        for i in range(len(cys_sorted) - 1):
            cy1, cy2 = cys_sorted[i], cys_sorted[i + 1]
            for ry in range(cy1 + 1, cy2):
                if ib(col_x, ry) and bool(em[ry, col_x]) and not bool(pm[ry, col_x]):
                    return (Tool.WIRE, col_x, ry)

    # ---- 5. BUILD FLANKING ROADS along wire spines ----
    for nb in active:
        cx, cy, wc = nb['cx'], nb['cy'], nb['wc']
        rl, rr = nb['rl'], nb['rr']
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cycle = (step + nb['idx'] * 7) % max(len(wire_rows), 1)
        for offset in range(min(len(wire_rows), 12)):
            wr = wire_rows[(cycle + offset) % len(wire_rows)]
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- 6. HORIZONTAL ROADS at top/bottom of each neighborhood ----
    for nb in active:
        cx, cy = nb['cx'], nb['cy']
        wc, rl, rr = nb['wc'], nb['rl'], nb['rr']
        rt, rb = nb['rt'], nb['rb']
        # Extend horizontal roads from rl to rr
        for road_y in [rt, rb]:
            if not ib(rl, road_y) or not ib(rr, road_y):
                continue
            for rx in range(rl, rr + 1):
                if ib(rx, road_y) and bool(em[road_y, rx]) and not bool(pm[road_y, rx]) and not bool(wm[road_y, rx]):
                    return (Tool.ROAD, rx, road_y)

    # ---- 7. CROSS ROADS connecting neighborhoods horizontally ----
    if pop > 50:
        for row_y, wcs in row_groups.items():
            if len(wcs) < 2:
                continue
            wcs_sorted = sorted(wcs)
            for road_y_off in [-3, 3]:
                ry2 = row_y + road_y_off
                if not ib(0, ry2):
                    continue
                x_start = max(2, wcs_sorted[0] - 4)
                x_end = min(WORLD_W - 2, wcs_sorted[-1] + 4)
                for rx in range(x_start, x_end + 1):
                    if ib(rx, ry2) and bool(em[ry2, rx]) and not bool(pm[ry2, rx]) and not bool(wm[ry2, rx]):
                        return (Tool.ROAD, rx, ry2)

    # ---- 8. ZONE PLACEMENT ----
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for nb in active:
            d = (np.abs(cxs_arr.astype(float) - nb['wc']) +
                 np.abs(cys_arr.astype(float) - nb['cy']))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- 9. EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for ddx, ddy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + ddx, ry2 + ddy
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- 10. CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (25, 15), (50, 15), (75, 15), (100, 15),
            (25, 38), (50, 38), (75, 38), (100, 38),
            (25, 62), (50, 62), (75, 62), (100, 62),
            (25, 85), (50, 85), (75, 85), (100, 85),
            (10, 50), (115, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (20, 25), (45, 25), (70, 25), (95, 25),
            (20, 50), (45, 50), (70, 50), (95, 50),
            (20, 75), (45, 75), (70, 75), (95, 75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (30, 5), (60, 5), (90, 5),
            (30, 93), (60, 93), (90, 93),
            (5, 50), (115, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 93)]:
            ax2, ay2 = asp
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 3500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- 11. PARKS near zones ----
    if pop > 150:
        zone_ys2, zone_xs2 = np.where(zone_tiles)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for ddx, ddy in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + ddx, zy2 + ddy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- 12. FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + ddx, wy2 + ddy
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- 13. LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for ddx, ddy in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + ddx, zy2 + ddy
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
