        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 40% RES, 35% COM, 25% IND for mixed economy
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of clusters: 5 columns x 4 rows for dense coverage
    # Each cluster has a power plant, wire spine, and flanking roads
    cluster_cols = [12, 35, 60, 85, 108]
    cluster_rows = [20, 42, 62, 82]

    all_clusters = []
    for cy in cluster_rows:
        for cx in cluster_cols:
            # wire col = cx, road left = cx-2, road right = cx+2
            all_clusters.append((cx, cy, cx, cx - 2, cx + 2))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 600:   return 8
        if pop < 1000:  return 10
        if pop < 1500:  return 12
        if pop < 2500:  return 15
        if pop < 4000:  return 18
        return len(all_clusters)

    n_active = min(num_active(), len(all_clusters))
    active_clusters = all_clusters[:n_active]

    # --- ENSURE POWER PLANTS ---
    for (px, py, wc, rl, rr) in active_clusters:
        y0 = max(0, py - 4); y1 = min(WORLD_H, py + 5)
        x0 = max(0, px - 4); x1 = min(WORLD_W, px + 5)
        if not np.any(pm[y0:y1, x0:x1]):
            # Try to place plant at px,py or nearby
            placed = False
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- WIRE SPINE (vertical) per cluster ---
    spine_half = min(35, 8 + pop // 8)
    for (px, py, wc, rl, rr) in active_clusters:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_rows:
            # Seed wire near plant
            for dy in range(-5, 6):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # --- HORIZONTAL WIRE connecting clusters in same row ---
    row_ys = sorted(set(py for (px, py, wc, rl, rr) in active_clusters))
    for yl in row_ys:
        row_wcs = sorted([wc for (px, py, wc, rl, rr) in active_clusters if py == yl])
        for i in range(len(row_wcs) - 1):
            wc1 = row_wcs[i]
            wc2 = row_wcs[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # --- VERTICAL WIRE connecting same column clusters ---
    if n_active >= 5:
        col_xs = sorted(set(wc for (px, py, wc, rl, rr) in active_clusters))
        for xc in col_xs:
            col_ys = sorted([py for (px, py, wc, rl, rr) in active_clusters if wc == xc])
            for i in range(len(col_ys) - 1):
                y1c = col_ys[i]
                y2c = col_ys[i + 1]
                for cy in range(y1c + 1, y2c):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # --- ROAD GRID: flanking wires + horizontal roads between clusters ---
    for idx, (px, py, wc, rl, rr) in enumerate(active_clusters):
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        # Stagger road building per cluster
        cycle = (step + idx * 3) % 6
        for wr in wire_rows[cycle::6]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # Horizontal roads connecting cluster rows
    for yl in row_ys:
        row_data = sorted([(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_clusters if py == yl],
                          key=lambda a: a[0])
        if len(row_data) < 2:
            continue
        x_left = row_data[0][3]
        x_right = row_data[-1][4]
        # Multiple horizontal road offsets for denser grid
        offsets = [-3, 3]
        if pop > 200:
            offsets += [-6, 6]
        if pop > 500:
            offsets += [-9, 9, -12, 12]
        for oy in offsets:
            hy = yl + oy
            if not ib(x_left, hy) or not ib(x_right, hy):
                continue
            for cx in range(x_left, x_right + 1):
                if ib(cx, hy) and bool(em[hy, cx]) and not bool(pm[hy, cx]):
                    return (Tool.ROAD, cx, hy)

    # Vertical roads between row-clusters in same column
    if pop > 100:
        col_data_map = {}
        for (px, py, wc, rl, rr) in active_clusters:
            if wc not in col_data_map:
                col_data_map[wc] = []
            col_data_map[wc].append((px, py, rl, rr))
        for xc, entries in col_data_map.items():
            sorted_e = sorted(entries, key=lambda a: a[1])
            for i in range(len(sorted_e) - 1):
                y1c = sorted_e[i][1]
                y2c = sorted_e[i + 1][1]
                rl2 = sorted_e[i][2]
                rr2 = sorted_e[i][3]
                for road_x in [rl2, rr2]:
                    for cy in range(y1c + 1, y2c):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # --- BUILD NEIGHBOR MASKS for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT: near road and wire ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_clusters:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # --- EXTEND ROADS near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES (closed-loop: place when pop thresholds hit) ---
    if pop > 40:
        fire_spots = [
            (5, 10), (30, 10), (55, 10), (80, 10), (110, 10),
            (5, 30), (30, 30), (55, 30), (80, 30), (110, 30),
            (5, 52), (30, 52), (55, 52), (80, 52), (110, 52),
            (5, 72), (30, 72), (55, 72), (80, 72), (110, 72),
            (5, 90), (30, 90), (55, 90), (80, 90), (110, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (18, 15), (48, 15), (72, 15), (98, 15),
            (18, 38), (48, 38), (72, 38), (98, 38),
            (18, 65), (48, 65), (72, 65), (98, 65),
            (18, 88), (48, 88), (72, 88), (98, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (30, 5), (70, 5), (110, 5),
            (30, 94), (70, 94), (110, 94),
            (5, 30), (5, 70), (115, 30), (115, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear power upgrade
    if pop > 1500:
        nuke_spots = [
            (35, 4), (75, 4), (5, 50), (115, 50),
            (35, 95), (75, 95), (5, 20), (115, 20),
            (5, 80), (115, 80), (60, 4), (60, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(50, 4), (5, 50), (115, 50), (50, 94), (95, 4)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 92), (115, 92), (60, 96), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PARKS to boost land value ---
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- FALLBACK: extend wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: road near zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Combined aggressive city builder
# Strategy: dense grid of neighborhoods with proper power/road infrastructure
# Uses Parent A's spine-based wiring + Parent B's grid structure
# More ambitious: 8x8 neighborhoods, multiple power plants, civic services

def init(obs, state):
    """Bootstrap: multiple coal plants + wire spines + roads."""
    actions = []
    # 9 coal plants in a 3x3 grid
    for px in [20, 60, 100]:
        for py in [20, 50, 80]:
            actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for x in range(1, 119):
        for wy in [20, 50, 80]:
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for y in range(1, 99):
        for wx in [20, 60, 100]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for x in range(1, 119):
        for wy in [20, 50, 80]:
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Wire and road corridors
    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 115]

    # Dense neighborhood grid - 10x8 = 80 neighborhoods
    all_hoods = []
    for col in range(8):
        for row in range(10):
            cx = 7 + col * 15
            cy = 5 + row * 10
            all_hoods.append((cx, cy))

    def get_active_hoods():
        if pop < 50:
            return [(60, 50), (45, 50), (75, 50), (60, 35), (60, 65), (30, 50), (90, 50)]
        elif pop < 150:
            n = 15
        elif pop < 400:
            n = 25
        elif pop < 800:
            n = 40
        elif pop < 1500:
            n = 55
        elif pop < 3000:
            n = 65
        else:
            n = len(all_hoods)
        step_sz = max(1, len(all_hoods) // n)
        return all_hoods[::step_sz][:n]

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Phase 1: Ensure power plants near active hoods
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 18), min(WORLD_W, hx + 19)
        y0, y1 = max(0, hy - 18), min(WORLD_H, hy + 19)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 20):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # Phase 2: Extend horizontal wire corridors
    if step % 8 in (0, 1):
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 3: Extend vertical wire corridors
    if step % 8 in (2, 3):
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 4: Roads flanking wire rows
    if step % 8 == 4:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # Phase 5: Roads flanking wire cols
    if step % 8 == 5:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # Phase 6: Cross-streets at midpoints
    if step % 8 == 6:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 7: Vertical cross-streets
    if step % 8 == 7:
        for wci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wci], wire_cols[wci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Civic services
    if pop > 60:
        fire_spots = [(x, y) for y in range(8, 100, 18) for x in range(8, 120, 22)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(x, y) for y in range(12, 100, 22) for x in range(12, 120, 25)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(30, 30), (90, 30), (30, 70), (90, 70), (60, 50), (15, 50), (105, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [(5, 50), (113, 50), (60, 5), (60, 93), (5, 5), (113, 5), (5, 93), (113, 93), (5, 25), (113, 75)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 93), (113, 93), (5, 5), (113, 5), (60, 93), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(48, 5), (72, 5), (48, 90), (72, 90), (5, 43), (113, 43)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Zone placement - main action
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Parks for land value
    if pop > 80 and step % 4 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Extend road from existing roads into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Wire toward unpowered active hoods
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: new coal plant at any active unpowered hood
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire spine and initial roads"""
