def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    powered_map = wm | pm

    # Dilate road map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            if abs(dx) + abs(dy) > 4:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Dilate power map
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            if abs(dx) + abs(dy) > 7:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= powered_map[sr0:sr1, sc0:sc1]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    plant_count = int(np.sum(pm))

    # 3 main neighborhood clusters: left, center, right
    # Each cluster has multiple sub-nodes
    main_clusters = [
        (25, 35), (25, 50), (25, 65),   # left column
        (60, 25), (60, 50), (60, 75),   # center column
        (95, 35), (95, 50), (95, 65),   # right column
        (42, 42), (42, 58),             # mid-left
        (78, 42), (78, 58),             # mid-right
        (60, 40), (60, 60),             # center spread
        (15, 50), (105, 50),            # extreme sides
        (40, 25), (80, 25),             # top spread
        (40, 75), (80, 75),             # bottom spread
    ]

    # Activate clusters progressively
    num_active = max(3, min(len(main_clusters), 3 + pop // 100 + total_zones // 6))
    active_clusters = main_clusters[:num_active]

    def pick_zone_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: ~35% RES, ~30% COM, ~35% IND
        if ind_count < 4 or ir < 0.28:
            return Tool.INDUSTRIAL
        if com_count < 4 or cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    plant_ys, plant_xs = np.where(pm)

    # === STEP 1: Ensure each active cluster has a power plant within radius 12 ===
    for cx, cy in active_clusters:
        x0 = max(0, cx - 12); x1 = min(WORLD_W, cx + 13)
        y0 = max(0, cy - 12); y1 = min(WORLD_H, cy + 13)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant near cluster
            for r in range(0, 15):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        px, py = cx + dx, cy + dy
                        if not in_bounds(px, py):
                            continue
                        ok = True
                        for ddy in range(-1, 2):
                            for ddx in range(-1, 2):
                                tx, ty = px + ddx, py + ddy
                                if not in_bounds(tx, ty):
                                    ok = False; break
                                if not bool(em[ty, tx]) and not bool(wm[ty, tx]):
                                    ok = False; break
                            if not ok:
                                break
                        if ok:
                            return (Tool.COALPOWER, px, py)
                if placed:
                    break

    # === STEP 2: Build wire grid - horizontal spine at y=25,50,75 and vertical at x=25,60,95 ===
    # Wire horizontal spines
    wire_rows = [25, 35, 50, 65, 75]
    wire_cols = [25, 42, 60, 78, 95]

    for wy in wire_rows:
        for wx in range(5, WORLD_W - 5):
            if bool(em[wy, wx]) and not bool(pm[wy, wx]):
                # Check if adjacent to existing power
                has_nbr_power = False
                for dw in [-1, 1]:
                    nwx = wx + dw
                    if in_bounds(nwx, wy) and bool(powered_map[wy, nwx]):
                        has_nbr_power = True
                if has_nbr_power:
                    return (Tool.WIRE, wx, wy)

    for wx in wire_cols:
        for wy in range(5, WORLD_H - 5):
            if bool(em[wy, wx]) and not bool(pm[wy, wx]):
                has_nbr_power = False
                for dw in [-1, 1]:
                    nwy = wy + dw
                    if in_bounds(wx, nwy) and bool(powered_map[nwy, wx]):
                        has_nbr_power = True
                if has_nbr_power:
                    return (Tool.WIRE, wx, wy)

    # === STEP 3: Connect wire from nearest power to unserved clusters ===
    for cx, cy in active_clusters:
        x0 = max(0, cx - 5); x1 = min(WORLD_W, cx + 6)
        y0 = max(0, cy - 5); y1 = min(WORLD_H, cy + 6)
        if not np.any(powered_map[y0:y1, x0:x1]):
            all_py, all_px = np.where(powered_map)
            if len(all_px) == 0:
                continue
            dists = np.abs(all_px - cx) + np.abs(all_py - cy)
            idx = int(np.argmin(dists))
            wx2, wy2 = int(all_px[idx]), int(all_py[idx])
            dx = cx - wx2; dy = cy - wy2
            if abs(dx) >= abs(dy):
                nx, ny = wx2 + (1 if dx > 0 else -1), wy2
            else:
                nx, ny = wx2, wy2 + (1 if dy > 0 else -1)
            if in_bounds(nx, ny) and not bool(pm[ny, nx]):
                if bool(em[ny, nx]) or bool(wm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # === STEP 4: Build road grid - roads at y=27,37,47,53,63,73 and x offsets per cluster ===
    # Road horizontal grid lines
    road_rows = [27, 33, 37, 43, 47, 53, 57, 63, 67, 73, 77, 83]
    road_cols = [23, 28, 40, 45, 58, 62, 76, 81, 93, 98]

    # Horizontal roads across active area
    for rrow in road_rows:
        if not in_bounds(5, rrow):
            continue
        for rcol in range(5, WORLD_W - 5):
            if bool(em[rrow, rcol]) and not bool(pm[rrow, rcol]) and bool(nbr_power[rrow, rcol]):
                # Only place if near existing road or wire
                near_infra = False
                for dd in [-2, -1, 1, 2]:
                    if in_bounds(rcol + dd, rrow) and bool(rm[rrow, rcol + dd]):
                        near_infra = True
                    if in_bounds(rcol, rrow + dd) and (bool(rm[rrow + dd, rcol]) or bool(powered_map[rrow + dd, rcol])):
                        near_infra = True
                if near_infra:
                    return (Tool.ROAD, rcol, rrow)

    # Vertical roads along active clusters
    for rcol in road_cols:
        if not in_bounds(rcol, 5):
            continue
        for rrow in range(5, WORLD_H - 5):
            if bool(em[rrow, rcol]) and not bool(pm[rrow, rcol]) and bool(nbr_power[rrow, rcol]):
                near_infra = False
                for dd in [-2, -1, 1, 2]:
                    if in_bounds(rcol, rrow + dd) and bool(rm[rrow + dd, rcol]):
                        near_infra = True
                    if in_bounds(rcol + dd, rrow) and (bool(rm[rrow, rcol + dd]) or bool(powered_map[rrow, rcol + dd])):
                        near_infra = True
                if near_infra:
                    return (Tool.ROAD, rcol, rrow)

    # === STEP 5: Place zones near roads and power ===
    zone_tiles = resm | comm | indm

    def zone_clear_fast(zx, zy):
        x0 = max(0, zx - 1); x1 = min(WORLD_W, zx + 2)
        y0 = max(0, zy - 1); y1 = min(WORLD_H, zy + 2)
        if x1 - x0 < 3 or y1 - y0 < 3:
            return False
        patch = em[y0:y1, x0:x1] | zone_tiles[y0:y1, x0:x1]
        return bool(np.all(patch))

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        scores = np.full(len(cxs_arr), 999999.0)
        for cx2, cy2 in active_clusters:
            d = np.abs(cxs_arr - cx2) + np.abs(cys_arr - cy2)
            scores = np.minimum(scores, d.astype(float))
        order = np.argsort(scores)
        tool = pick_zone_tool()
        step_off = (step * 11) % max(len(order), 1)
        for i in range(min(len(order), 100)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear_fast(zx, zy):
                return (tool, zx, zy)

    # === STEP 6: Extend wire network greedily ===
    wire_ys2, wire_xs2 = np.where(powered_map)
    if len(wire_xs2) > 0:
        for cx2, cy2 in active_clusters:
            x0 = max(0, cx2 - 5); x1 = min(WORLD_W, cx2 + 6)
            y0 = max(0, cy2 - 5); y1 = min(WORLD_H, cy2 + 6)
            if np.any(powered_map[y0:y1, x0:x1]):
                continue
            dists2 = np.abs(wire_xs2 - cx2) + np.abs(wire_ys2 - cy2)
            idx2 = int(np.argmin(dists2))
            wx2, wy2 = int(wire_xs2[idx2]), int(wire_ys2[idx2])
            ddx = cx2 - wx2; ddy = cy2 - wy2
            if abs(ddx) >= abs(ddy):
                nnx, nny = wx2 + (1 if ddx > 0 else -1), wy2
            else:
                nnx, nny = wx2, wy2 + (1 if ddy > 0 else -1)
            if in_bounds(nnx, nny) and not bool(pm[nny, nnx]):
                if bool(em[nny, nnx]) or bool(wm[nny, nnx]):
                    return (Tool.WIRE, nnx, nny)

    # === STEP 7: Extend roads near existing roads and power ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k2 = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k2 + offset * 9) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === STEP 8: Civic services ===
    if pop > 150:
        fire_positions = [
            (60, 44), (60, 56), (25, 44), (25, 56),
            (95, 44), (95, 56), (42, 50), (78, 50),
            (15, 35), (105, 35), (15, 65), (105, 65),
            (40, 30), (80, 30), (40, 70), (80, 70),
            (20, 50), (100, 50),
        ]
        for fsx, fsy in fire_positions:
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]) and bool(nbr_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 400:
        police_positions = [
            (58, 47), (62, 53), (22, 47), (28, 53),
            (92, 47), (98, 53), (40, 40), (80, 40),
            (40, 60), (80, 60), (60, 30), (60, 70),
            (15, 45), (105, 45),
        ]
        for psx, psy in police_positions:
            if in_bounds(psx, psy) and bool(em[psy, psx]) and bool(nbr_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 800:
        for ssx, ssy in [(90, 25), (30, 25), (90, 75), (30, 75), (60, 10), (60, 88), (110, 50), (10, 50)]:
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    if pop > 1200:
        for spx, spy in [(115, 50), (5, 50), (60, 5), (60, 94), (115, 25), (5, 75)]:
            if in_bounds(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # === STEP 9: Nuclear power for large cities ===
    if pop > 600 and funds > 6000:
        nuclear_positions = [
            (110, 20), (10, 20), (110, 80), (10, 80),
            (60, 5), (60, 93), (115, 50), (5, 50),
            (90, 15), (30, 15), (90, 85), (30, 85),
        ]
        for nsx, nsy in nuclear_positions:
            if not in_bounds(nsx, nsy):
                continue
            x0 = max(0, nsx - 10); x1 = min(WORLD_W, nsx + 11)
            y0 = max(0, nsy - 10); y1 = min(WORLD_H, nsy + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[nsy, nsx]):
                    return (Tool.NUCLEARPOWER, nsx, nsy)

    # === STEP 10: Additional coal plants if low plant count ===
    extra_plants = [
        (42, 30), (78, 30), (42, 70), (78, 70),
        (15, 30), (105, 30), (15, 70), (105, 70),
        (60, 15), (60, 85),
    ]
    max_plants = 3 + pop // 200
    if plant_count < max_plants:
        for cpx, cpy in extra_plants:
            if not in_bounds(cpx, cpy):
                continue
            x0 = max(0, cpx - 10); x1 = min(WORLD_W, cpx + 11)
            y0 = max(0, cpy - 10); y1 = min(WORLD_H, cpy + 11)
            if not np.any(pm[y0:y1, x0:x1]) and bool(em[cpy, cpx]):
                return (Tool.COALPOWER, cpx, cpy)

    return None

# Ambitious city builder: uses a dense grid layout with multiple power plants,
# comprehensive road network, and reactive zone placement across the whole map.
# Key differences from parent:
# 1. Road-first approach: lay a grid of roads, then wire alongside them
# 2. More power plants distributed across map
# 3. Reactive zone density scaling with population
# 4. Better use of full 120x100 map with 6x5 neighborhood grid
# 5. Mixed zoning strategy that balances R/C/I more aggressively

def init(obs, state):
    """Bootstrap: coal plants at strategic locations + initial wire + roads."""
    actions = []
    # 6 coal plants spread across map
    for px, py in [(15, 15), (60, 15), (105, 15),
                   (15, 85), (60, 85), (105, 85)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at y=15,50,85 connecting power plants
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 15))
        actions.append((Tool.WIRE, x, 50))
        actions.append((Tool.WIRE, x, 85))
    # Vertical wire spines at x=15,60,105
    for y in range(1, 99):
        actions.append((Tool.WIRE, 15, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 105, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Maintain roughly 50% res, 25% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    # Wire corridors (horizontal y, vertical x)
    wire_rows = [15, 32, 50, 67, 85]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]
    # Road corridors offset by 2 from wire spines
    road_rows = [17, 30, 48, 52, 65, 83]  # flanking wire_rows
    road_cols = [17, 28, 43, 47, 58, 62, 73, 77, 88, 92, 103, 107]

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Neighborhood centers: 7 cols x 5 rows = 35 neighborhoods
    all_hoods = []
    for col in range(7):
        for row in range(5):
            cx = 10 + col * 16
            cy = 10 + row * 20
            all_hoods.append((cx, cy))

    def get_active_hoods():
        if pop < 30:
            return [(60, 50), (44, 30), (76, 30), (44, 70), (76, 70)]
        elif pop < 100:
            n = 8
        elif pop < 300:
            n = 15
        elif pop < 700:
            n = 22
        elif pop < 1500:
            n = 28
        elif pop < 3000:
            n = 33
        else:
            n = len(all_hoods)
        step_sz = max(1, len(all_hoods) // n)
        return all_hoods[::step_sz][:n]

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Phase 1: Ensure power plants near active hoods (check radius 20)
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
        y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # Phase 2: Lay horizontal wire spines (extend from existing wire/plant)
    if step % 10 in (0, 1):
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 3: Lay vertical wire spines
    if step % 10 in (2, 3):
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 4: Lay main horizontal roads adjacent to wire rows
    if step % 10 == 4:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (1 <= ry <= WORLD_H - 2):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        adj_wire = (bool(wm[wr, rx]) or bool(pm[wr, rx]))
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or (rx < WORLD_W-1 and bool(rm[ry, rx+1]))
                        if adj_wire or adj_road:
                            return (Tool.ROAD, rx, ry)

    # Phase 5: Lay main vertical roads adjacent to wire cols
    if step % 10 == 5:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (1 <= rcx <= WORLD_W - 2):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        adj_wire = (bool(wm[ry, wc]) or bool(pm[ry, wc]))
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or (ry < WORLD_H-1 and bool(rm[ry+1, rcx]))
                        if adj_wire or adj_road:
                            return (Tool.ROAD, rcx, ry)

    # Phase 6: Cross-streets between wire rows
    if step % 10 == 6:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 7: Cross-streets between wire cols
    if step % 10 == 7:
        for wci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wci], wire_cols[wci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Phase 8: Short wire spurs from main spines toward unpowered areas
    if step % 10 == 8:
        unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
        if unpowered_hoods:
            wire_ys_arr, wire_xs_arr = np.where(wm | pm)
            if len(wire_xs_arr) > 0:
                tx, ty = unpowered_hoods[0]
                dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Civic services (reactive to population)
    if pop > 80:
        fire_spots = [(x, y) for y in range(7, WORLD_H - 7, 16) for x in range(7, WORLD_W - 7, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(x, y) for y in range(10, WORLD_H - 10, 20) for x in range(10, WORLD_W - 10, 24)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50), (60, 25), (60, 75)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(5, 50), (113, 50), (60, 5), (60, 93),
                      (5, 5), (113, 5), (5, 93), (113, 93),
                      (30, 5), (90, 5), (30, 93), (90, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 93), (113, 93), (5, 5), (113, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(48, 5), (72, 5), (48, 90), (72, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Zone placement - main closed-loop action
    # Candidate cells: empty, near road, near power, away from wire spines
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep clear of wire corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score candidates by distance to nearest active hood
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary starting point to avoid always picking same spot
        offset = (step * 11 + pop * 5) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # Parks for land value boost
    if pop > 100 and step % 3 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Extend roads from existing road network into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 250)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Extend any wire toward unpowered areas
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: place coal plant near unpowered active hood
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# High-reactivity closed-loop city builder
# Strategy: Dense neighborhood grid, aggressive zone placement, reactive power/road extension

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking the vertical wire
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Denser neighborhood grid: 8 cols x 7 rows = 56 neighborhoods
    nh_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    nh_rows = [10, 22, 36, 50, 64, 78, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 5
        if pop < 500:   return 10
        if pop < 1000:  return 18
        if pop < 2000:  return 28
        if pop < 4000:  return 40
        if pop < 8000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Select evenly spaced active hoods
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD POWER+WIRE COVERAGE MAP ----
    # Combine wires and plant tiles for power proximity
    power_src = wm | pm

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant in empty spot nearest hood center
            for r in range(1, 15):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: EXTEND WIRE from plants outward reactively ----
    # For each active hood, extend wire toward nearest existing wire/plant
    # Use BFS-like: find empty tiles adjacent to power source not yet wired
    spine_range = 12
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Vertical wire spine at hx
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        # Check if adjacent to existing power
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal wire spine at hy
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Connect horizontally adjacent hoods
            if hy1 == hy2 and abs(hx2 - hx1) == 15:
                mid_y = hy1
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Connect vertically adjacent hoods
            if hx1 == hx2 and abs(hy2 - hy1) in [12, 14, 18]:
                mid_x = hx1
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    # Road at hx-1 and hx+1
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods), 1) != 0:
            continue
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Only place road if wire spine exists here
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal spine
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- BUILD PROXIMITY MAPS ----
    # Neighbor road mask (within 3 tiles Manhattan)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 45% RES, 30% COM, 25% IND
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: empty, near road AND power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Rotate starting offset by step to avoid always picking same spot
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    # Fire stations every 15 tiles grid
    if pop > 80:
        for fx in range(12, WORLD_W, 18):
            for fy in range(12, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 300:
        for px2 in range(18, WORLD_W, 22):
            for py2 in range(18, WORLD_H, 22):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 800:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 50), (75, 50), (20, 20), (100, 20),
                    (20, 80), (100, 80), (60, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5),
                    (30, 95), (90, 95), (30, 5), (90, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 40), (6, 60),
                    (114, 40), (114, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop cities ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (10, 50), (110, 50), (60, 10), (60, 90),
                         (45, 45), (75, 45), (45, 55), (75, 55)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: power plants + wire grid + road grid skeleton"""
    actions = []
    # 6 coal plants spread across map
    for px in [20, 59, 98]:
        for py in [25, 75]:
            actions.append((Tool.COALPOWER, px, py))

    # Horizontal wire spines at multiple rows
    wire_rows = [10, 25, 40, 55, 70, 85]
    for wy in wire_rows:
        for wx in range(1, 119):
            actions.append((Tool.WIRE, wx, wy))

    # Vertical wire spines
    wire_cols = [10, 29, 49, 59, 70, 90, 109]
    for wc in wire_cols:
        for wy in range(1, 99):
            actions.append((Tool.WIRE, wc, wy))

    # Roads flanking all horizontal wire spines
    for wy in wire_rows:
        for wx in range(1, 119):
            actions.append((Tool.ROAD, wx, wy - 1))
            actions.append((Tool.ROAD, wx, wy + 1))

    # Roads flanking vertical wire spines
    for wc in wire_cols:
        for wy in range(1, 99):
            actions.append((Tool.ROAD, wc - 1, wy))
            actions.append((Tool.ROAD, wc + 1, wy))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 40% RES, 35% COM, 25% IND
    def pick_tool():
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [10, 25, 40, 55, 70, 85]
    wire_cols = [10, 29, 49, 59, 70, 90, 109]

    # Dense grid of neighborhood centers between wire grid intersections
    nh_positions = []
    row_mids = [17, 32, 47, 62, 77]  # midpoints between wire rows
    col_mids = [19, 39, 54, 64, 80, 99]  # midpoints between wire cols
    for cy in row_mids:
        for cx in col_mids:
            nh_positions.append((cx, cy))

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Determine active neighborhoods based on pop
    def get_active_hoods():
        if pop < 100:
            # Start with central neighborhoods
            return [(54, 47), (64, 47), (54, 62), (64, 62), (39, 47), (80, 47)]
        elif pop < 500:
            return nh_positions[:12]
        elif pop < 1500:
            return nh_positions[:18]
        elif pop < 3000:
            return nh_positions[:24]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    phase = step % 16

    # Add more power plants near neighborhoods that lack power
    if step % 4 == 0:
        for (hx, hy) in active_hoods[:6]:
            x0, x1 = max(0, hx - 18), min(WORLD_W, hx + 19)
            y0, y1 = max(0, hy - 18), min(WORLD_H, hy + 19)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find nearest empty spot
                for r in range(3, 20):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = hx + dx, hy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)
                    if found:
                        break

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Mid-row horizontal roads connecting neighborhoods
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Mid-col vertical roads
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend roads from existing road network
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase in (8, 9):
        # Civic: fire stations, police, stadiums
        if pop > 15:
            fire_spots = [(5,5),(115,5),(5,95),(115,95),
                          (30,5),(60,5),(90,5),
                          (30,95),(60,95),(90,95),
                          (5,30),(5,60),(115,30),(115,60),
                          (35,35),(85,35),(35,65),(85,65),(60,50)]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 80:
            police_spots = [(20,20),(50,20),(80,20),(110,20),
                            (20,50),(80,50),(110,50),
                            (20,80),(50,80),(80,80),(110,80)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            stadium_spots = [(35,32),(85,32),(35,67),(85,67),(59,50),(20,50),(100,50)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 600:
            nuke_spots = [(5,50),(113,50),(59,5),(59,93),
                          (5,5),(113,5),(5,93),(113,93),
                          (30,50),(90,50)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            seaports = [(5,93),(113,93),(5,5),(113,5),(5,47),(113,47)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2000:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(113,43),(5,55),(113,55)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    elif phase in (10, 11):
        # Add cross-streets within neighborhoods for denser access
        for (hx, hy) in active_hoods:
            for dy in range(-6, 7, 2):
                for dx in range(-6, 7, 2):
                    rx, ry = hx + dx, hy + dy
                    if ib(rx, ry) and bool(em[ry, rx]) and bool(near_power[ry, rx]) and not bool(pm[ry, rx]):
                        # Only if adjacent to existing road
                        adj_road = any(ib(rx+ddx, ry+ddy) and bool(rm[ry+ddy, rx+ddx])
                                      for ddx,ddy in [(1,0),(-1,0),(0,1),(0,-1)])
                        if adj_road:
                            return (Tool.ROAD, rx, ry)

    # ---- MAIN ZONE PLACEMENT (closed-loop) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders and wire/road corridors
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hood centers
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # Parks for land value boost
    if pop > 50 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire toward unpowered neighborhoods
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power plant + cross wire + seed roads"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Seed horizontal roads
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    # Seed vertical roads
    for y in range(10, 90):
        actions.append((Tool.ROAD, 45, y))
        actions.append((Tool.ROAD, 75, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone ratio: 40% res, 35% com, 25% ind
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Multiple neighborhood centers spread across the map ---
    # 6 neighborhoods in a 2x3 grid
    neighborhoods = [
        (25, 25), (60, 25), (95, 25),
        (25, 75), (60, 75), (95, 75),
    ]

    # PHASE 1: Ensure power plants near each neighborhood
    # Each neighborhood needs a coal plant within ~12 tiles
    for nx, ny in neighborhoods:
        x0, x1 = max(0, nx - 15), min(WORLD_W, nx + 16)
        y0, y1 = max(0, ny - 15), min(WORLD_H, ny + 16)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant at neighborhood center offset
            px, py = nx, ny
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Try nearby empty spots
            for d in range(1, 8):
                for dx, dy in [(d,0),(-d,0),(0,d),(0,-d),(d,d),(-d,-d),(d,-d),(-d,d)]:
                    cx, cy = px+dx, py+dy
                    if ib(cx, cy) and bool(em[cy, cx]):
                        return (Tool.COALPOWER, cx, cy)

    # Additional plants at map edges for extra power coverage
    extra_plants = [(10, 50), (110, 50), (60, 10), (60, 90)]
    for epx, epy in extra_plants:
        x0, x1 = max(0, epx-6), min(WORLD_W, epx+7)
        y0, y1 = max(0, epy-6), min(WORLD_H, epy+7)
        if not np.any(pm[y0:y1, x0:x1]):
            if ib(epx, epy) and bool(em[epy, epx]):
                return (Tool.COALPOWER, epx, epy)

    # PHASE 2: Wire grid connecting all neighborhoods
    # Horizontal wire at y=25, 50, 75
    wire_rows = [20, 25, 50, 75, 80]
    for wr in wire_rows:
        if not ib(0, wr):
            continue
        # Check if row needs wires
        row_power = wm[wr, :] | pm[wr, :]
        gaps = np.where(~row_power & em[wr, :])[0]
        # Connect gaps between power sources
        pwr_indices = np.where(row_power)[0]
        if len(pwr_indices) >= 2:
            left = int(pwr_indices[0])
            right = int(pwr_indices[-1])
            for x in range(left, right + 1):
                if bool(em[wr, x]):
                    return (Tool.WIRE, x, wr)
        elif len(pwr_indices) == 1:
            # Extend from single power source
            idx = int(pwr_indices[0])
            for x in range(max(0, idx-50), min(WORLD_W, idx+51)):
                if bool(em[wr, x]):
                    return (Tool.WIRE, x, wr)
        elif len(gaps) > 0:
            # Start a wire near a plant
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                nearest_k = np.argmin(np.abs(pys - wr))
                px = int(pxs[nearest_k])
                if ib(px, wr) and bool(em[wr, px]):
                    return (Tool.WIRE, px, wr)

    # Vertical wire at x=25, 60, 95
    wire_cols = [20, 25, 60, 95, 100]
    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_power = wm[:, wc] | pm[:, wc]
        pwr_indices = np.where(col_power)[0]
        if len(pwr_indices) >= 2:
            top = int(pwr_indices[0])
            bot = int(pwr_indices[-1])
            for y in range(top, bot + 1):
                if bool(em[y, wc]):
                    return (Tool.WIRE, wc, y)
        elif len(pwr_indices) == 1:
            idx = int(pwr_indices[0])
            for y in range(max(0, idx-45), min(WORLD_H, idx+46)):
                if bool(em[y, wc]):
                    return (Tool.WIRE, wc, y)

    # PHASE 3: Dense road grid
    # Horizontal roads every 6 rows in key bands
    road_rows = []
    for ny in [25, 75]:
        for offset in [-8, -5, -2, 2, 5, 8]:
            r = ny + offset
            if 3 < r < WORLD_H - 3:
                road_rows.append(r)
    # Central band
    for offset in range(-10, 11, 3):
        r = 50 + offset
        if 3 < r < WORLD_H - 3:
            road_rows.append(r)
    road_rows = sorted(set(road_rows))

    road_cols = []
    for nx in [25, 60, 95]:
        for offset in [-8, -5, -2, 2, 5, 8]:
            c = nx + offset
            if 3 < c < WORLD_W - 3:
                road_cols.append(c)
    road_cols = sorted(set(road_cols))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Start road at center
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left to x=5
        if left > 5 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        # Extend right to x=115
        if right < 115 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        # Fill gaps
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 5 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < 95 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # PHASE 4: Zone placement - closed-loop, near roads and power
    zone_cand = em & near_road & near_power
    # Buffer from edges
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W-3:] = False

    # Don't place zones on infrastructure
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        # Distance to nearest road
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 150)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Prefer spots near existing zones (density bonus) but not overlapping
        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 150)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Too close = bad, right distance = good, too far = ok
            zone_score = np.where(min_zone_dist < 3, 500.0,
                         np.where(min_zone_dist < 8, -5.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0)))
        else:
            # Spread across neighborhoods
            zone_score = np.zeros(len(cxs_arr))
            for nx, ny in neighborhoods:
                d = (np.abs(cxs_arr - nx) + np.abs(cys_arr - ny)).astype(float)
                zone_score = np.minimum(zone_score if len(neighborhoods) > 0 else d, d)

        score = road_dist * 2.0 + zone_score
        order = np.argsort(score)

        tool = pick_tool()
        # Vary starting offset by step to avoid always same spot
        off = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic services based on population
    if pop > 200:
        # Fire stations spread across map
        fire_grid = [(fx, fy) for fy in range(15, 90, 15) for fx in range(15, 110, 20)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 400:
        police_grid = [(px2, py2) for py2 in range(18, 90, 18) for px2 in range(18, 110, 22)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_grid = [(pkx, pky) for pky in range(10, 95, 8) for pkx in range(10, 115, 10)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_spots = [(30, 10), (90, 10), (30, 90), (90, 90), (60, 50)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        # Upgrade to nuclear power
        nuclear_spots = [(25, 50), (95, 50), (60, 10), (60, 85)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx-8), min(WORLD_W, npx+9)
                y0, y1 = max(0, npy-8), min(WORLD_H, npy+9)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [(10, 50), (110, 50), (60, 5), (60, 94)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # PHASE 6: Extend wires toward unpowered zones
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 30)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # PHASE 7: Extend roads toward unserved zones
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 30)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Fallback: place road near power plant
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(8,0),(-8,0),(0,8),(0,-8),(5,0),(-5,0),(0,5),(0,-5),(10,0),(-10,0)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: compact central power grid + road spines"""
    actions = []
