def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    powered_map = wm | pm
    zone_tiles = resm | comm | indm

    # Build dilated road proximity map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build dilated power proximity map
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            if abs(dx) + abs(dy) > 7:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= powered_map[sr0:sr1, sc0:sc1]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    plant_count = int(np.sum(pm))

    # 15 neighborhood clusters spread across full map
    # Using a 3-column x 5-row layout
    clusters = []
    for cx in [25, 60, 95]:
        for cy in [15, 30, 50, 70, 85]:
            clusters.append((cx, cy))
    # Add extra clusters between main columns
    for cx in [42, 77]:
        for cy in [22, 50, 78]:
            clusters.append((cx, cy))

    # Activate more clusters as city grows
    num_active = max(3, min(len(clusters), 3 + pop // 100 + total_zones // 6))
    num_active = min(num_active, len(clusters))
    active_clusters = clusters[:num_active]

    def pick_zone_tool():
        # Balanced mix: ~30% ind, ~30% com, ~40% res
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ind_count < 4 or ir < 0.28:
            return Tool.INDUSTRIAL
        if com_count < 4 or cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === STEP 1: Ensure plants near each active cluster ===
    for cx, cy in active_clusters:
        x0 = max(0, cx - 8); x1 = min(WORLD_W, cx + 9)
        y0 = max(0, cy - 8); y1 = min(WORLD_H, cy + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(0, 12):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if abs(dx2) != r and abs(dy2) != r:
                            continue
                        px2, py2 = cx + dx2, cy + dy2
                        if not in_bounds(px2, py2):
                            continue
                        ok = True
                        for ddy in range(-1, 2):
                            for ddx in range(-1, 2):
                                tx, ty = px2 + ddx, py2 + ddy
                                if not in_bounds(tx, ty):
                                    ok = False; break
                                if not bool(em[ty, tx]) and not bool(wm[ty, tx]):
                                    ok = False; break
                            if not ok:
                                break
                        if ok:
                            return (Tool.COALPOWER, px2, py2)
                if placed:
                    break

    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        return (Tool.COALPOWER, 60, 50)

    # === STEP 2: Wire network - connect plants to cluster zones ===
    for cx, cy in active_clusters:
        x0 = max(0, cx - 4); x1 = min(WORLD_W, cx + 5)
        y0 = max(0, cy - 4); y1 = min(WORLD_H, cy + 5)
        if not np.any(powered_map[y0:y1, x0:x1]):
            all_py2, all_px2 = np.where(powered_map)
            if len(all_px2) == 0:
                continue
            dists = np.abs(all_px2 - cx) + np.abs(all_py2 - cy)
            idx = int(np.argmin(dists))
            wx, wy = int(all_px2[idx]), int(all_py2[idx])
            dx3 = cx - wx; dy3 = cy - wy
            if abs(dx3) >= abs(dy3):
                nx, ny = wx + (1 if dx3 > 0 else -1), wy
            else:
                nx, ny = wx, wy + (1 if dy3 > 0 else -1)
            if in_bounds(nx, ny) and not bool(pm[ny, nx]):
                if bool(em[ny, nx]) or bool(wm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # === STEP 3: Build road grid - horizontal + vertical around each cluster ===
    for ci, (cx, cy) in enumerate(active_clusters):
        extent = min(14, 6 + pop // 120 + ci // 3)

        # Horizontal roads at cy-4, cy, cy+4
        for row_off in [-4, 0, 4]:
            hry = cy + row_off
            left = max(2, cx - extent)
            right = min(WORLD_W - 3, cx + extent)
            if not in_bounds(left, hry):
                continue
            for hx in range(left, right + 1):
                if bool(em[hry, hx]) and not bool(pm[hry, hx]) and bool(nbr_power[hry, hx]):
                    return (Tool.ROAD, hx, hry)

        # Vertical roads at cx-4, cx, cx+4
        for col_off in [-4, 0, 4]:
            vcx = cx + col_off
            top = max(2, cy - extent)
            bot = min(WORLD_H - 3, cy + extent)
            if not in_bounds(vcx, top):
                continue
            for vy in range(top, bot + 1):
                if bool(em[vy, vcx]) and not bool(pm[vy, vcx]) and bool(nbr_power[vy, vcx]):
                    return (Tool.ROAD, vcx, vy)

    # === STEP 4: Place zones near roads and power ===
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)

    def zone_clear_fast(zx, zy):
        x0 = max(0, zx - 1); x1 = min(WORLD_W, zx + 2)
        y0 = max(0, zy - 1); y1 = min(WORLD_H, zy + 2)
        if x1 - x0 < 3 or y1 - y0 < 3:
            return False
        patch = em[y0:y1, x0:x1] | zone_tiles[y0:y1, x0:x1]
        return bool(np.all(patch))

    if len(cxs_arr) > 0:
        scores = np.full(len(cxs_arr), 999999.0)
        for cx2, cy2 in active_clusters:
            d = np.abs(cxs_arr - cx2) + np.abs(cys_arr - cy2)
            scores = np.minimum(scores, d.astype(float))
        order = np.argsort(scores)
        tool = pick_zone_tool()
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 100)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear_fast(zx, zy):
                return (tool, zx, zy)

    # === STEP 5: Extend wire from existing powered cells ===
    wire_ys2, wire_xs2 = np.where(powered_map)
    if len(wire_xs2) > 0:
        for cx2, cy2 in active_clusters:
            x0 = max(0, cx2 - 4); x1 = min(WORLD_W, cx2 + 5)
            y0 = max(0, cy2 - 4); y1 = min(WORLD_H, cy2 + 5)
            if np.any(powered_map[y0:y1, x0:x1]):
                continue
            dists2 = np.abs(wire_xs2 - cx2) + np.abs(wire_ys2 - cy2)
            idx2 = int(np.argmin(dists2))
            wx2, wy2 = int(wire_xs2[idx2]), int(wire_ys2[idx2])
            ddx = cx2 - wx2; ddy = cy2 - wy2
            if abs(ddx) >= abs(ddy):
                nnx, nny = wx2 + (1 if ddx > 0 else -1), wy2
            else:
                nnx, nny = wx2, wy2 + (1 if ddy > 0 else -1)
            if in_bounds(nnx, nny) and not bool(pm[nny, nnx]):
                if bool(em[nny, nnx]) or bool(wm[nny, nnx]):
                    return (Tool.WIRE, nnx, nny)

        step_k = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 40)):
            k = (step_k + offset * 7) % len(wire_xs2)
            wx3, wy3 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = wx3 + dx3, wy3 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === STEP 6: Extend roads ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k2 = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k2 + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === STEP 7: Civic services ===
    if pop > 150:
        fire_positions = [
            (25, 45), (25, 55), (60, 45), (60, 55), (95, 45), (95, 55),
            (42, 22), (42, 50), (42, 78), (77, 22), (77, 50), (77, 78),
            (15, 25), (15, 75), (105, 25), (105, 75),
        ]
        for fsx, fsy in fire_positions:
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]) and bool(nbr_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 400:
        police_positions = [
            (28, 48), (62, 48), (92, 48), (28, 52), (62, 52), (92, 52),
            (44, 20), (44, 78), (76, 20), (76, 78),
            (15, 50), (105, 50),
        ]
        for psx, psy in police_positions:
            if in_bounds(psx, psy) and bool(em[psy, psx]) and bool(nbr_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 800:
        for ssx, ssy in [(25, 30), (60, 30), (95, 30), (25, 70), (60, 70), (95, 70)]:
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    if pop > 1200:
        for spx, spy in [(10, 50), (110, 50), (60, 10), (60, 90)]:
            if in_bounds(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Nuclear plants for power expansion
    if pop > 600 and funds > 6000:
        nuclear_positions = [
            (25, 15), (60, 15), (95, 15),
            (25, 85), (60, 85), (95, 85),
            (10, 50), (110, 50),
        ]
        for nsx, nsy in nuclear_positions:
            if not in_bounds(nsx, nsy):
                continue
            x0 = max(0, nsx - 8); x1 = min(WORLD_W, nsx + 9)
            y0 = max(0, nsy - 8); y1 = min(WORLD_H, nsy + 9)
            if not np.any(pm[y0:y1, x0:x1]) and bool(em[nsy, nsx]):
                return (Tool.NUCLEARPOWER, nsx, nsy)

    # Additional coal plants if zones outpace power
    if plant_count < 5 and pop > 200:
        extra_plants = [
            (42, 22), (77, 22), (42, 78), (77, 78),
            (10, 30), (110, 30), (10, 70), (110, 70),
        ]
        for cx3, cy3 in extra_plants:
            x0 = max(0, cx3 - 8); x1 = min(WORLD_W, cx3 + 9)
            y0 = max(0, cy3 - 8); y1 = min(WORLD_H, cy3 + 9)
            if not np.any(pm[y0:y1, x0:x1]) and bool(em[cy3, cx3]):
                return (Tool.COALPOWER, cx3, cy3)

    return None

# Closed-loop city builder: reactive, dense, well-powered
# Strategy: scan current map each step, grow infrastructure and zones
# based on what's actually there, not a fixed plan.

def init(obs, state):
    """Bootstrap: 3 coal plants forming a triangle, with initial wire/road."""
    actions = []
    # Three anchor plants
    plants = [(20, 20), (100, 20), (60, 80)]
    for (px, py) in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire in 4 directions from plant
        for d in range(1, 4):
            for dx, dy in [(d,0),(-d,0),(0,d),(0,-d)]:
                nx, ny = px+dx, py+dy
                if 0<=nx<WORLD_W and 0<=ny<WORLD_H:
                    actions.append((Tool.WIRE, nx, ny))
    # Roads flanking first plant
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, 19, 20+dy))
        actions.append((Tool.ROAD, 21, 20+dy))
    return actions[:35]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # Neighborhood grid: 10 cols x 8 rows = 80 neighborhoods
    # Spread across full map with generous spacing
    nh_cols = list(range(8, 120, 12))   # ~10 cols
    nh_rows = list(range(8, 100, 12))   # ~8 rows
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Scale active hoods by population
    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 10
        if pop < 500:   return 20
        if pop < 1000:  return 35
        if pop < 2000:  return 50
        if pop < 4000:  return 65
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    # Precompute power neighbor mask (wire or plant within 4 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            if abs(dx) + abs(dy) > 5: continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Precompute road neighbor mask (road within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE EACH ACTIVE HOOD HAS A NEARBY POWER PLANT ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx-10), min(WORLD_W, hx+11)
        y0, y1 = max(0, hy-10), min(WORLD_H, hy+11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            nearby_zones = int(np.sum(zone_tiles[y0:y1, x0:x1]))
            use_nuclear = nearby_zones > 25 and funds > 8000
            tool_plant = Tool.NUCLEARPOWER if use_nuclear else Tool.COALPOWER
            # Find nearest empty tile to place plant
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (tool_plant, nx, ny)

    # ---- PHASE 2: GROW WIRE FROM EXISTING POWER TOWARD UNCOVERED HOODS ----
    # For each active hood not yet powered, extend wire toward it from nearest wire
    for (hx, hy) in active_hoods:
        if bool(nbr_power[hy, hx]):
            continue
        # Find nearest wire/plant tile and extend toward hood
        wire_ys, wire_xs = np.where(power_src)
        if len(wire_xs) == 0:
            break
        dists = np.abs(wire_xs - hx) + np.abs(wire_ys - hy)
        best = np.argmin(dists)
        wx, wy = int(wire_xs[best]), int(wire_ys[best])
        # Step from (wx,wy) toward (hx,hy)
        dx = np.sign(hx - wx)
        dy = np.sign(hy - wy)
        # Try horizontal then vertical extension
        for (nx, ny) in [(wx+dx, wy), (wx, wy+dy), (wx+dx, wy+dy)]:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: WIRE CROSS AT EACH ACTIVE HOOD ----
    spine_r = 6
    for (hx, hy) in active_hoods:
        # Vertical spine
        for dy in range(-spine_r, spine_r+1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Only lay if adjacent to existing wire/plant
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal spine
        for dx in range(-spine_r, spine_r+1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adx in [-1, 1]:
                ax = wx + adx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 4: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    row_to_hoods = {}
    col_to_hoods = {}
    for (hx, hy) in active_hoods:
        row_to_hoods.setdefault(hy, []).append(hx)
        col_to_hoods.setdefault(hx, []).append(hy)

    # Horizontal connections
    for hy, hxs in row_to_hoods.items():
        hxs_s = sorted(hxs)
        for i in range(len(hxs_s)-1):
            hx1, hx2 = hxs_s[i], hxs_s[i+1]
            if hx2 - hx1 <= 16:
                for cx in range(hx1+1, hx2):
                    if not ib(cx, hy): continue
                    if bool(wm[hy, cx]) or bool(pm[hy, cx]): continue
                    if not bool(em[hy, cx]): continue
                    for adx in [-1, 1]:
                        ax = cx+adx
                        if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                            return (Tool.WIRE, cx, hy)
    # Vertical connections
    for hx, hys in col_to_hoods.items():
        hys_s = sorted(hys)
        for i in range(len(hys_s)-1):
            hy1, hy2 = hys_s[i], hys_s[i+1]
            if hy2 - hy1 <= 16:
                for cy in range(hy1+1, hy2):
                    if not ib(hx, cy): continue
                    if bool(wm[cy, hx]) or bool(pm[cy, hx]): continue
                    if not bool(em[cy, hx]): continue
                    for ady in [-1, 1]:
                        ay = cy+ady
                        if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                            return (Tool.WIRE, hx, cy)

    # ---- PHASE 5: ROADS FLANKING WIRE SPINES ----
    for (hx, hy) in active_hoods:
        # Roads flanking vertical spine (at hx-1 and hx+1)
        for rx in [hx-1, hx+1]:
            for dy in range(-spine_r, spine_r+1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(pm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                # Lay road if wire/plant exists at (hx, ry) or road nearby
                if bool(wm[ry, hx]) or bool(pm[ry, hx]) or bool(rm[ry, hx]):
                    return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal spine (at hy-1 and hy+1)
        for ry2 in [hy-1, hy+1]:
            for dx in range(-spine_r, spine_r+1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(pm[ry2, rcx]): continue
                if not bool(em[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]) or bool(rm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 13) % len(road_xs)
        for offset in range(min(len(road_xs), 200)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% RES, 35% COM, 25% IND
        if rr < 0.40:
            return Tool.RESIDENTIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        if ir < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate centers: empty, road nearby, power nearby, not at edge
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 8: CIVIC SERVICES (reactive to population) ----
    if pop > 30:
        fire_spots = [
            (12,12),(36,12),(60,12),(84,12),(108,12),
            (12,36),(36,36),(60,36),(84,36),(108,36),
            (12,60),(36,60),(60,60),(84,60),(108,60),
            (12,84),(36,84),(60,84),(84,84),(108,84),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (24,10),(48,10),(72,10),(96,10),
            (10,24),(35,24),(60,24),(85,24),(110,24),
            (24,48),(48,48),(72,48),(96,48),
            (10,72),(35,72),(60,72),(85,72),(110,72),
            (24,90),(48,90),(72,90),(96,90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (18,18),(58,18),(98,18),
            (18,50),(58,50),(98,50),
            (18,82),(58,82),(98,82),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        seaports = [(5,90),(115,90),(5,5),(115,5),(58,5),(58,95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(38,5),(78,5),(38,93),(78,93),(5,48),(114,48)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 9: PARKS for land value ----
    if pop > 80 and step % 5 == 0:
        park_ys2, park_xs2 = np.where(em & nbr_road & nbr_power)
        if len(park_xs2) > 0:
            idx = (step * 37) % len(park_xs2)
            px2, py2 = int(park_xs2[idx]), int(park_ys2[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from any wire tile ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 17) % len(wire_xs2)
        for offset in range(min(len(wire_xs2), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: add plant near unpowered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + initial road grid"""
    actions = []
    # Two power plants for better coverage
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally through center
    for x in range(32, 89):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for y in range(5, 48):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    for y in range(52, 95):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Horizontal roads at y=40, y=50, y=60 (near center)
    for x in range(3, 117):
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 60))
    # Vertical roads at x=20, x=60, x=100
    for y in range(35, 65):
        actions.append((Tool.ROAD, 20, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 100, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Ensure power plants cover the whole map ----
    # Grid of plants every 20 tiles
    plant_positions = []
    for py in range(10, 95, 20):
        for px in range(10, 115, 20):
            plant_positions.append((px, py))

    # Check if any plant grid cell lacks a plant nearby
    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire extension from existing power ----
    # Find tiles adjacent to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    # Find unpowered plants to connect
    unpowered_plants = [(px, py) for px, py in plant_positions
                        if ib(px, py) and np.any(pm[max(0,py-1):py+2, max(0,px-1):px+2])
                        and not bool(near_power[py, px])]

    wys, wxs = np.where(wire_cand)

    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(min(len(wxs), 800)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:15])
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # Connect power to unpowered zones
    if len(wxs) > 0:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward regions lacking power
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0 and total_zones < 500:
            sample_n = min(80, len(upxs))
            rng_idx = np.linspace(0, len(upxs)-1, sample_n, dtype=int)
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in rng_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Dense road grid (every 5 tiles) ----
    road_grid = []
    for gy in range(5, 98, 5):
        for gx in range(5, 118, 5):
            road_grid.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])
                      and not bool(zone_tiles[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:60]
            for i in range(min(len(rxs2), 600)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:20]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 150)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs) // 150)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride3):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Prefer close to road, spread from existing zones
        score = road_dist * 1.5 + np.maximum(0, 12 - zone_dist) * 3.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Tool selection based on ratios and step cycle
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)

        step_mod = step % 10
        if step_mod < 5:
            tool = Tool.RESIDENTIAL
        elif step_mod < 8:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

        # Override if ratios are off
        if ir < 0.18:
            tool = Tool.INDUSTRIAL
        elif cr < 0.22:
            tool = Tool.COMMERCIAL
        elif rr < 0.45:
            tool = Tool.RESIDENTIAL

        for i in range(min(len(order), 1200)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled to population ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(7, 95, 8) for fx in range(7, 115, 8)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 10)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(8, 95, 8) for pkx in range(8, 115, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(15, 15), (60, 15), (105, 15),
                        (15, 50), (60, 50), (105, 50),
                        (15, 85), (60, 85), (105, 85)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        nuke_locs = [(20, 20), (100, 20), (20, 80), (100, 80),
                     (60, 10), (60, 90), (10, 50), (110, 50),
                     (40, 40), (80, 40), (40, 60), (80, 60)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 7), min(WORLD_W, nx + 8)
                y0, y1 = max(0, ny - 7), min(WORLD_H, ny + 8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85), (55, 5)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(10, 50), (110, 50), (60, 5), (60, 90)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from existing power plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(4, 0), (-4, 0), (0, 4), (0, -4), (3, 3), (-3, -3), (5, 0), (0, 5)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

# High-reactivity closed-loop city builder
# Strategy: scan existing infrastructure each step, grow outward from it
# Multiple power plants, dense road+wire grid, balanced zones, civic services

def init(obs, state):
    """Bootstrap: place two coal plants and seed roads/wires in center."""
    actions = []
    # Two plants near center
    actions.append((Tool.COALPOWER, 55, 48))
    actions.append((Tool.COALPOWER, 65, 52))
    # Wire connecting them horizontally
    for cx in range(55, 66):
        actions.append((Tool.WIRE, cx, 50))
    # Vertical wire spines from each plant
    for dy in range(-6, 7):
        actions.append((Tool.WIRE, 55, 48 + dy))
        actions.append((Tool.WIRE, 65, 52 + dy))
    # Roads flanking wire spines
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, 54, 48 + dy))
        actions.append((Tool.ROAD, 56, 48 + dy))
        actions.append((Tool.ROAD, 64, 52 + dy))
        actions.append((Tool.ROAD, 66, 52 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- PHASE TRACKING ----
    if 'phase' not in state:
        state['phase'] = 'infra'
        state['plant_attempts'] = set()
        state['wire_frontier'] = []
        state['road_frontier'] = []
        state['civic_idx'] = 0

    # ---- NEIGHBORHOOD ANCHORS ----
    # Dense grid of anchors across the whole map
    # Plants every 18 cols, 18 rows
    plant_grid = []
    for py in range(10, WORLD_H - 5, 18):
        for px in range(8, WORLD_W - 5, 18):
            plant_grid.append((px, py))

    # Sort by Manhattan distance from center
    plant_grid.sort(key=lambda nb: abs(nb[0] - 60) + abs(nb[1] - 50))

    # How many neighborhoods to activate based on pop
    def max_active():
        if pop < 100:   return 2
        if pop < 400:   return 4
        if pop < 1000:  return 8
        if pop < 2500:  return 16
        if pop < 5000:  return 24
        return len(plant_grid)

    active = plant_grid[:max_active()]

    # ---- REACTIVE: count current infrastructure ----
    n_plants = int(np.sum(pm))
    n_wire = int(np.sum(wm))
    n_road = int(np.sum(rm))
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- ENSURE POWER PLANTS at each active anchor ----
    for (px, py) in active:
        # Check if any plant exists within 5 tiles
        has_plant = False
        x0, x1 = max(0, px-5), min(WORLD_W, px+6)
        y0, y1 = max(0, py-5), min(WORLD_H, py+6)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            # Try to place plant at anchor, or nearby empty spot
            for r in range(0, 8):
                placed = False
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            # Don't place on road or wire
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE SPINES: grow vertically from each plant ----
    # For each active anchor, extend wire spine up and down
    pop_reach = min(45, 6 + pop // 30)

    for (px, py) in active:
        # Find the plant near this anchor
        x0, x1 = max(0, px-6), min(WORLD_W, px+7)
        y0, y1 = max(0, py-6), min(WORLD_H, py+7)
        sub = pm[y0:y1, x0:x1]
        plant_locs = np.argwhere(sub)
        if len(plant_locs) == 0:
            continue
        # Use first plant location
        plr, plc = plant_locs[0]
        plr += y0; plc += x0
        wc = plc  # wire column = plant column

        spine_top = max(2, plr - pop_reach)
        spine_bot = min(WORLD_H - 3, plr + pop_reach)

        # Find wire in this column
        col_wire = np.where(wm[:, wc])[0]

        if len(col_wire) == 0:
            # Seed wire adjacent to plant (not on plant)
            for dy in [-1, 1, -2, 2]:
                ny = plr + dy
                if ib(wc, ny) and not bool(pm[ny, wc]) and bool(em[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = int(col_wire.min())
            max_wr = int(col_wire.max())
            # Extend downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and bool(em[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            # Extend upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and bool(em[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE: connect anchors in same row ----
    # Group anchors by row proximity
    for i, (px1, py1) in enumerate(active):
        for j, (px2, py2) in enumerate(active):
            if i >= j:
                continue
            # Horizontal connection: same row, close columns
            if abs(py1 - py2) <= 4 and abs(px1 - px2) <= 20:
                hy = (py1 + py2) // 2
                min_c = min(px1, px2)
                max_c = max(px1, px2)
                # Find first gap in wire
                for cx in range(min_c, max_c + 1):
                    if ib(cx, hy) and bool(em[hy, cx]) and not bool(pm[hy, cx]):
                        return (Tool.WIRE, cx, hy)
            # Vertical connection: same column, close rows
            if abs(px1 - px2) <= 4 and abs(py1 - py2) <= 20:
                vx = (px1 + px2) // 2
                min_r = min(py1, py2)
                max_r = max(py1, py2)
                for cy in range(min_r, max_r + 1):
                    if ib(vx, cy) and bool(em[cy, vx]) and not bool(pm[cy, vx]):
                        return (Tool.WIRE, vx, cy)

    # ---- ROAD NETWORK ----
    # Roads run parallel to wire spines (left and right of wire column)
    for (px, py) in active:
        # Find plant near anchor
        x0, x1 = max(0, px-6), min(WORLD_W, px+7)
        y0, y1 = max(0, py-6), min(WORLD_H, py+7)
        sub = pm[y0:y1, x0:x1]
        plant_locs = np.argwhere(sub)
        if len(plant_locs) == 0:
            continue
        plr, plc = plant_locs[0]
        plr += y0; plc += x0
        wc = plc

        col_wire = np.where(wm[:, wc])[0]
        if len(col_wire) == 0:
            continue

        # Left and right road columns
        for road_col in [wc - 2, wc + 2, wc - 1, wc + 1]:
            if not ib(road_col, py):
                continue
            for wr in col_wire:
                wr = int(wr)
                if ib(road_col, wr) and bool(em[wr, road_col]) and not bool(pm[wr, road_col]) and not bool(wm[wr, road_col]):
                    return (Tool.ROAD, road_col, wr)

        # Horizontal roads every 3 rows through wire extent
        if len(col_wire) > 0:
            for hr in range(int(col_wire.min()), int(col_wire.max()) + 1, 3):
                # Extend horizontally from wire column
                for dx in range(-10, 11):
                    hx = wc + dx
                    if not ib(hx, hr):
                        continue
                    if not bool(em[hr, hx]) or bool(pm[hr, hx]) or bool(wm[hr, hx]):
                        continue
                    # Only if adjacent to existing road/wire/plant
                    adj_infra = False
                    for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ax, ay = hx+adx, hr+ady
                        if ib(ax, ay) and (bool(rm[ay, ax]) or bool(wm[ay, ax]) or bool(pm[ay, ax])):
                            adj_infra = True
                            break
                    if adj_infra:
                        return (Tool.ROAD, hx, hr)

    # ---- ZONE PLACEMENT ----
    # Compute neighbor masks reactively from current map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in [-2, -1, 0, 1, 2]:
        for dx in [-2, -1, 0, 1, 2]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        """Check 3x3 footprint is all empty or zone."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Candidate spots: empty, near road AND wire, away from edges
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, :3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: closest active anchor, prefer spread
        best_dist = np.full(len(cxs), 999999.0)
        for (px2, py2) in active:
            d = np.abs(cxs - px2).astype(float) + np.abs(cys - py2).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        # Stagger by step to avoid always picking same spot
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- EXTEND ROADS reactively from existing road near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 60)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx+dx, ry+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- CIVIC SERVICES (reactive: check area for existing stations) ----
    # Fire stations
    if pop > 300:
        for idx, (px, py) in enumerate(active):
            # Check if fire station already near
            found = False
            for dy in range(-5, 6):
                for dx in range(-5, 6):
                    nx, ny = px+dx, py+dy
                    if ib(nx, ny):
                        tid = int(tm[ny, nx])
                        # Fire station tiles roughly 700-745
                        if 700 <= tid <= 745:
                            found = True
                            break
                if found:
                    break
            if not found:
                for dx, dy in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (-4, 0), (0, 4), (0, -4)]:
                    fx, fy = px+dx, py+dy
                    if ib(fx, fy) and bool(em[fy, fx]):
                        return (Tool.FIRESTATION, fx, fy)

    # Police stations
    if pop > 800:
        for idx, (px, py) in enumerate(active):
            found = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    nx, ny = px+dx, py+dy
                    if ib(nx, ny):
                        tid = int(tm[ny, nx])
                        # Police station tiles roughly 750-795
                        if 750 <= tid <= 800:
                            found = True
                            break
                if found:
                    break
            if not found:
                for dx, dy in [(4, 0), (-4, 0), (0, 4), (0, -4), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    fx, fy = px+dx, py+dy
                    if ib(fx, fy) and bool(em[fy, fx]):
                        return (Tool.POLICESTATION, fx, fy)

    # Stadiums
    if pop > 3000:
        stadium_candidates = [(20, 10), (90, 10), (20, 85), (90, 85),
                               (55, 20), (55, 80), (20, 50), (95, 50),
                               (38, 35), (78, 35), (38, 65), (78, 65)]
        for (sx, sy) in stadium_candidates:
            if ib(sx, sy) and bool(em[sy, sx]):
                # Check 3x3 clear
                all_clear = True
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if not ib(sx+dc, sy+dr) or not bool(em[sy+dr, sx+dc]):
                            all_clear = False
                if all_clear:
                    return (Tool.STADIUM, sx, sy)

    # Seaports
    if pop > 5000:
        for (spx, spy) in [(5, 5), (5, 90), (110, 5), (110, 90), (55, 5), (55, 92)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- FALLBACK: extend wire from existing wire toward active anchor ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (step * 13) % max(len(wire_xs), 1)
        for offset in range(min(len(wire_xs), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            # Pick direction toward nearest active anchor
            best_anc = None
            best_d = 999999
            for (px, py) in active:
                d = abs(wx - px) + abs(wy - py)
                if d < best_d:
                    best_d = d
                    best_anc = (px, py)
            if best_anc is None:
                continue
            # Step toward anchor
            ax, ay = best_anc
            candidates = []
            if ax > wx:
                candidates.append((1, 0))
            elif ax < wx:
                candidates.append((-1, 0))
            if ay > wy:
                candidates.append((0, 1))
            elif ay < wy:
                candidates.append((0, -1))
            for (dx, dy) in candidates:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- LAST RESORT: place a new plant at uncovered active anchor ----
    for (px, py) in active:
        x0, x1 = max(0, px-8), min(WORLD_W, px+9)
        y0, y1 = max(0, py-8), min(WORLD_H, py+9)
        if not np.any(wm[y0:y1, x0:x1]) and not np.any(pm[y0:y1, x0:x1]):
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 6):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire cross and road grid seeds."""
    actions = []
    # Three plants across the map at mid-height
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
        # Horizontal wire from plant
        for x in range(px - 15, px + 16):
            if 0 <= x < 120 and x != px:
                actions.append((Tool.WIRE, x, 50))
        # Vertical wire from plant
        for y in range(35, 65):
            if y != 50:
                actions.append((Tool.WIRE, px, y))
    # Seed roads at y=44 and y=56
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure power plants on a grid ----
    # Scale plant density with population
    plant_spacing = 18 if pop < 500 else 14 if pop < 1500 else 10
    plant_positions = []
    for py in range(10, 95, plant_spacing):
        for px in range(10, 115, plant_spacing):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Search nearby empty
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Extend wire from power sources ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False

    wys, wxs = np.where(wire_cand)

    # Find unpowered plants
    unpowered_plants = [(px, py) for px, py in plant_positions
                        if ib(px, py) and np.any(pm[max(0,py-1):min(WORLD_H,py+2),
                                                     max(0,px-1):min(WORLD_W,px+2)])
                        and not bool(near_power[py, px])]

    if len(wxs) > 0 and len(unpowered_plants) > 0:
        best_dist = 1e9
        best_k = 0
        for i in range(min(len(wxs), 500)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:20])
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # Extend wire toward unpowered empty areas (for zone expansion)
    if len(wxs) > 0:
        unpowered_empty = em & ~near_power
        # Downsample
        upys, upxs = np.where(unpowered_empty[::4, ::4])
        upys = upys * 4
        upxs = upxs * 4
        if len(upxs) > 0 and total_zones < 300:
            best_dist = 1e9
            best_k = 0
            rng_sample = min(40, len(upxs))
            indices = (np.arange(rng_sample) * max(1, len(upxs) // rng_sample)) % len(upxs)
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in indices)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid - denser as city grows ----
    road_step = 6 if pop > 200 else 8
    road_targets = []
    for gy in range(road_step, 97, road_step):
        for gx in range(road_step, 115, road_step):
            if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]):
                road_targets.append((gx, gy))

    if road_targets:
        # Extend roads connected to existing road network
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H - 2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W - 2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            targets_sample = road_targets[:60]
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in road_targets[:10]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        score = road_dist * 1.5 + np.maximum(0, 8 - zone_dist) * 3.0
        order = np.argsort(score)
        off = (step * 17 + pop * 7) % max(len(order), 1)

        # Tool selection with ratio override
        step_mod = step % 10
        if step_mod < 5:
            tool = Tool.RESIDENTIAL
        elif step_mod < 8:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.18:
            tool = Tool.INDUSTRIAL
        elif cr < 0.22:
            tool = Tool.COMMERCIAL

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services ----
    if pop > 60:
        fire_grid = [(fx, fy) for fy in range(8, 95, 10) for fx in range(8, 115, 10)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_grid = [(px2, py2) for py2 in range(12, 92, 12) for px2 in range(12, 112, 12)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_grid = [(pkx, pky) for pky in range(9, 95, 9) for pkx in range(9, 115, 9)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [(25, 15), (65, 15), (105, 15),
                        (25, 50), (65, 50), (105, 50),
                        (25, 83), (65, 83), (105, 83)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuke_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                     (60, 10), (60, 88), (10, 50), (110, 50),
                     (50, 40), (70, 60), (15, 20), (105, 20),
                     (15, 80), (105, 80)]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85), (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91), (5, 30), (5, 70)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: road near power plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 2), (-2, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    # Fallback: extend wire
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        k = (step * 13) % len(wire_xs2)
        for offset in range(min(len(wire_xs2), 60)):
            wk = (k + offset * 7) % len(wire_xs2)
            wx3, wy3 = int(wire_xs2[wk]), int(wire_ys2[wk])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx3 + dx3, wy3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: road near any zone
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx3, zy3 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx3, dy3 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (0, 3)]:
            nx3, ny3 = zx3 + dx3, zy3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    return None

