def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 50% res, 30% com, 20% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of neighborhood anchors covering the whole map
    # 6 columns x 5 rows = 30 neighborhoods
    anchors = []
    for col_x in [10, 30, 50, 70, 90, 110]:
        for row_y in [10, 28, 50, 72, 90]:
            anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:     return 3
        if pop < 150:    return 5
        if pop < 300:    return 8
        if pop < 500:    return 12
        if pop < 800:    return 16
        if pop < 1200:   return 20
        if pop < 1800:   return 24
        return 30

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(0, 12):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE CROSS at each anchor ----
    spine_half = min(10, 5 + pop // 20)
    for (px, py) in active_anchors:
        for dx in range(-spine_half, spine_half + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine_half, spine_half + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # ---- CONNECT POWER BETWEEN ANCHORS horizontally ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1a, _ = row_anchors[i]
            x2a, _ = row_anchors[i + 1]
            for cx in range(x1a + 1, x2a):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- CONNECT POWER BETWEEN ANCHORS vertically ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1a = col_anchors[i]
            _, y2a = col_anchors[i + 1]
            for cy in range(y1a + 1, y2a):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: horizontal roads on both sides of wire spines ----
    for (px, py) in active_anchors:
        for road_dy in [-2, 2]:
            ry = py + road_dy
            if not ib(px, ry):
                continue
            for dx in range(-spine_half, spine_half + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- VERTICAL ROADS connecting neighborhoods ----
    if pop > 30:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1a = col_anchors[i]
                _, y2a = col_anchors[i + 1]
                for road_dx in [-3, 3]:
                    road_x = xl + road_dx
                    for cy in range(y1a, y2a + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD ZONE CANDIDATE MASK ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES based on population ----
    if pop > 60:
        fire_spots = [
            (5, 10), (30, 10), (60, 10), (90, 10), (115, 10),
            (5, 35), (30, 35), (60, 35), (90, 35), (115, 35),
            (5, 60), (30, 60), (60, 60), (90, 60), (115, 60),
            (5, 85), (30, 85), (60, 85), (90, 85), (115, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 5), (50, 5), (80, 5), (110, 5),
            (15, 45), (50, 45), (80, 45), (110, 45),
            (15, 90), (50, 90), (80, 90), (110, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (20, 3), (60, 3), (100, 3),
            (20, 96), (60, 96), (100, 96),
            (3, 50), (116, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Upgrade to nuclear power for more capacity
        nuke_spots = [
            (4, 4), (116, 4), (4, 95), (116, 95),
            (58, 4), (58, 95), (4, 50), (116, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 4), (4, 48), (116, 48), (55, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(4, 92), (116, 92), (58, 96)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value near zones ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (2, -2), (-2, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 power plants with wire+road spines."""
    actions = []
    # Three power plants spread horizontally
    plants = [(30, 50), (60, 50), (90, 50)]
    for (cx, cy) in plants:
        actions.append((Tool.COALPOWER, cx, cy))
        for d in range(1, 5):
            actions.append((Tool.WIRE, cx + d, cy))
            actions.append((Tool.WIRE, cx - d, cy))
            actions.append((Tool.WIRE, cx, cy + d))
            actions.append((Tool.WIRE, cx, cy - d))
        actions.append((Tool.ROAD, cx + 1, cy - 1))
        actions.append((Tool.ROAD, cx - 1, cy - 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID ----
    # Dense 5x4 grid of neighborhoods across the full map
    # Each neighborhood is independently powered and road-served
    base_hoods = []
    for gx in range(5):
        for gy in range(4):
            hx = 15 + gx * 22
            hy = 15 + gy * 23
            base_hoods.append((hx, hy))

    # Additional fringe hoods
    extra_hoods = [
        (7, 50), (112, 50),
        (7, 25), (112, 25),
        (7, 75), (112, 75),
        (30, 90), (60, 90), (90, 90),
        (30, 8), (60, 8), (90, 8),
    ]
    all_hoods = base_hoods + extra_hoods

    def num_active_hoods():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 10
        if pop < 1000:  return 15
        if pop < 2000:  return 20
        if pop < 4000:  return 25
        return len(all_hoods)

    n_active = num_active_hoods()
    active_hoods = all_hoods[:min(n_active, len(all_hoods))]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES FROM EACH PLANT ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        plant_sub = pm[y0:y1, x0:x1]
        py_arr, px_arr = np.where(plant_sub)
        if len(px_arr) == 0:
            continue
        plx = int(px_arr[0]) + x0
        ply = int(py_arr[0]) + y0

        wire_range = 22
        # Horizontal spine right
        for dx in range(1, wire_range):
            wx, wy = plx + dx, ply
            if not ib(wx, wy): break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break
        # Left
        for dx in range(1, wire_range):
            wx, wy = plx - dx, ply
            if not ib(wx, wy): break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break
        # Down
        for dy in range(1, wire_range):
            wx, wy = plx, ply + dy
            if not ib(wx, wy): break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break
        # Up
        for dy in range(1, wire_range):
            wx, wy = plx, ply - dy
            if not ib(wx, wy): break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break

    # ---- PHASE 3: HORIZONTAL WIRE BRIDGES BETWEEN ADJACENT HOODS ----
    # Sort hoods by x, connect horizontally close pairs
    sorted_hoods = sorted(active_hoods, key=lambda h: h[0])
    for i in range(len(sorted_hoods) - 1):
        hx1, hy1 = sorted_hoods[i]
        hx2, hy2 = sorted_hoods[i + 1]
        if abs(hy1 - hy2) > 15: continue
        if abs(hx1 - hx2) > 35: continue
        # Find a row with wire in both columns
        col1_wire = [r for r in range(max(0, hy1 - 5), min(WORLD_H, hy1 + 6))
                     if ib(hx1, r) and bool(wm[r, hx1])]
        col2_wire = [r for r in range(max(0, hy2 - 5), min(WORLD_H, hy2 + 6))
                     if ib(hx2, r) and bool(wm[r, hx2])]
        if not col1_wire or not col2_wire:
            continue
        bridge_y = col1_wire[len(col1_wire) // 2]
        x_lo, x_hi = min(hx1, hx2), max(hx1, hx2)
        for cx in range(x_lo, x_hi + 1):
            if ib(cx, bridge_y) and not bool(wm[bridge_y, cx]) and not bool(pm[bridge_y, cx]):
                if bool(em[bridge_y, cx]):
                    return (Tool.WIRE, cx, bridge_y)

    # Also connect vertically close hoods
    sorted_hoods_y = sorted(active_hoods, key=lambda h: h[1])
    for i in range(len(sorted_hoods_y) - 1):
        hx1, hy1 = sorted_hoods_y[i]
        hx2, hy2 = sorted_hoods_y[i + 1]
        if abs(hx1 - hx2) > 15: continue
        if abs(hy1 - hy2) > 30: continue
        row1_wire = [c for c in range(max(0, hx1 - 5), min(WORLD_W, hx1 + 6))
                     if ib(c, hy1) and bool(wm[hy1, c])]
        if not row1_wire:
            continue
        bridge_x = row1_wire[len(row1_wire) // 2]
        y_lo, y_hi = min(hy1, hy2), max(hy1, hy2)
        for cy in range(y_lo, y_hi + 1):
            if ib(bridge_x, cy) and not bool(wm[cy, bridge_x]) and not bool(pm[cy, bridge_x]):
                if bool(em[cy, bridge_x]):
                    return (Tool.WIRE, bridge_x, cy)

    # ---- PHASE 4: BUILD ROADS ALONGSIDE WIRE SPINES ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        plant_sub = pm[y0:y1, x0:x1]
        py_arr, px_arr = np.where(plant_sub)
        if len(px_arr) == 0:
            continue
        plx = int(px_arr[0]) + x0
        ply = int(py_arr[0]) + y0

        # Roads above/below horizontal wire
        for road_dy in [-1, 1, -2, 2]:
            ry = ply + road_dy
            if not ib(plx, ry): continue
            for dx in range(-20, 21):
                rx = plx + dx
                if not ib(rx, ry): continue
                if bool(wm[ply, rx]) or bool(pm[ply, rx]):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

        # Roads left/right of vertical wire
        for road_dx in [-1, 1, -2, 2]:
            rx2 = plx + road_dx
            if not ib(rx2, ply): continue
            for dy in range(-20, 21):
                ry2 = ply + dy
                if not ib(rx2, ry2): continue
                if bool(wm[ry2, plx]) or bool(pm[ry2, plx]):
                    if bool(em[ry2, rx2]) and not bool(pm[ry2, rx2]):
                        return (Tool.ROAD, rx2, ry2)

    # ---- BUILD COVERAGE MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-14, 15):
        for dx2 in range(-14, 15):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 5: PLACE ZONES ----
    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        # Target: 40% res, 30% com, 30% ind
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs.astype(float) - hx) + np.abs(cys.astype(float) - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- EXTEND ROADS reactively near wire coverage ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 120)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_spots = []
        for gx in range(6):
            for gy in range(5):
                fire_spots.append((10 + gx * 20, 10 + gy * 20))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = []
        for gx in range(5):
            for gy in range(4):
                police_spots.append((15 + gx * 23, 20 + gy * 22))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1200:
        stadiums = [(40, 40), (80, 40), (40, 70), (80, 70),
                    (20, 55), (100, 55), (60, 15), (60, 85),
                    (30, 25), (90, 25), (30, 75), (90, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10),
                    (60, 95), (60, 5), (5, 50), (115, 50)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(55, 10), (55, 85), (10, 50), (105, 50),
                    (25, 10), (90, 85)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 200 and step % 5 == 0:
        park_cands = np.where(em & nbr_road & nbr_power)
        if len(park_cands[0]) > 0:
            idx = (step * 23) % len(park_cands[0])
            py2, px2 = int(park_cands[0][idx]), int(park_cands[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- EXTEND WIRE from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: plant near unpowered active hood ----
    if step % 15 == 0:
        for (hx, hy) in active_hoods:
            if not bool(nbr_power[hy, hx]):
                for r in range(1, 6):
                    for ddy in range(-r, r + 1):
                        for ddx in range(-r, r + 1):
                            if abs(ddx) != r and abs(ddy) != r: continue
                            nx, ny = hx + ddx, hy + ddy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Closed-loop city builder: dense, reactive, ambitious
# Key improvements over parent:
# 1. More neighborhoods (10 cols x 8 rows = 80 hoods)
# 2. Faster unlock schedule
# 3. Direct wire spine building from plant without adjacency check
# 4. Better zone density - pack zones tightly along roads
# 5. More civic services placed earlier

def init(obs, state):
    """Bootstrap: coal plant + cross wire + flanking roads near center."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-4, 5):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-4, 5):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Denser neighborhood grid: 10 cols x 8 rows = 80 neighborhoods
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [8, 20, 32, 44, 56, 68, 80, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 400:   return 12
        if pop < 800:   return 20
        if pop < 1500:  return 32
        if pop < 3000:  return 48
        if pop < 6000:  return 64
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (build outward from plant) ----
    # For each hood, extend wire at hx column and hy row
    spine_range = 10
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Stagger which hood we work on
        if (step + idx_h) % max(len(active_hoods), 1) >= max(2, len(active_hoods) // 4):
            continue

        # Vertical spine at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(pm[wy, hx]):
                continue
            if bool(wm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            # Check adjacency to wire or plant
            adj = False
            for adx, ady in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                ax, ay = hx + adx, wy + ady
                if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                    adj = True
                    break
            if adj:
                return (Tool.WIRE, hx, wy)

        # Horizontal spine at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(pm[hy, wx]):
                continue
            if bool(wm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx, ady in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                ax, ay = wx + adx, hy + ady
                if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                    adj = True
                    break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    # Build inter-hood wire connections along columns and rows
    hood_set = set(all_hoods)
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Try to connect to hood directly below (same col, next row)
        next_hy = hy + 12
        if (hx, next_hy) in hood_set and (hx, next_hy) in active_hoods:
            for cy2 in range(hy + 1, next_hy):
                if ib(hx, cy2) and not bool(wm[cy2, hx]) and not bool(pm[cy2, hx]) and bool(em[cy2, hx]):
                    adj = False
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                            adj = True
                            break
                    if adj:
                        return (Tool.WIRE, hx, cy2)

        # Try to connect to hood directly right (same row, next col)
        next_hx = hx + 12
        if (next_hx, hy) in hood_set and (next_hx, hy) in active_hoods:
            for cx2 in range(hx + 1, next_hx):
                if ib(cx2, hy) and not bool(wm[hy, cx2]) and not bool(pm[hy, cx2]) and bool(em[hy, cx2]):
                    adj = False
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                            adj = True
                            break
                    if adj:
                        return (Tool.WIRE, cx2, hy)

    # ---- PHASE 4: BUILD ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 2) % max(len(active_hoods), 1) >= max(3, len(active_hoods) // 3):
            continue

        # Roads at hx-1 and hx+1 (flanking vertical wire)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy):
                continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Roads at hy-1 and hy+1 (flanking horizontal wire)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2):
                continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: EXTEND ROADS into powered, empty areas ----
    # Precompute neighbor power mask
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 100)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [
            (15, 15), (35, 15), (55, 15), (75, 15), (95, 15), (115, 15),
            (15, 35), (35, 35), (55, 35), (75, 35), (95, 35), (115, 35),
            (15, 55), (35, 55), (55, 55), (75, 55), (95, 55), (115, 55),
            (15, 75), (35, 75), (55, 75), (75, 75), (95, 75), (115, 75),
            (15, 90), (35, 90), (55, 90), (75, 90), (95, 90), (115, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (25, 25), (65, 25), (105, 25),
            (10, 50), (45, 50), (75, 50), (110, 50),
            (25, 70), (65, 70), (105, 70),
            (15, 88), (55, 88), (95, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (90, 30), (30, 70), (90, 70),
            (60, 15), (60, 85), (10, 50), (110, 50),
            (50, 50), (70, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 5), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 5), (75, 5), (45, 93), (75, 93), (5, 40), (5, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 8: PARKS to boost land value ----
    if pop > 200 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (step * 13) % len(wire_xs)
        for offset in range(min(len(wire_xs), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a row + wire connections + flanking roads."""
    actions = []
    # Three plants spread across the map horizontally at center row
    plants = [(30, 50), (60, 50), (90, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire spines between plants horizontally
    for x in range(28, 93):
        actions.append((Tool.WIRE, x, 50))
    # Short vertical wire from each plant
    for px, py in plants:
        for dy in range(-4, 5):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
    # Flanking roads above and below wire spine
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense neighborhood grid: 10 cols x 8 rows = 80 neighborhoods
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [8, 20, 32, 44, 56, 68, 80, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 8
        if pop < 500:   return 15
        if pop < 1000:  return 25
        if pop < 2000:  return 40
        if pop < 4000:  return 55
        if pop < 8000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    spine_r = 10

    # ---- BUILD NEIGHBOR MASKS ----
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and funds > 500:
            for r in range(9):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CROSSES for each hood ----
    # Use step cycling to spread work
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # First check if this hood has a nearby plant to extend wire from
    x0p, x1p = max(0, hx - 12), min(WORLD_W, hx + 13)
    y0p, y1p = max(0, hy - 12), min(WORLD_H, hy + 13)
    plant_ys_loc, plant_xs_loc = np.where(pm[y0p:y1p, x0p:x1p])
    if len(plant_xs_loc) > 0:
        px_l = int(plant_xs_loc[0]) + x0p
        py_l = int(plant_ys_loc[0]) + y0p
        # Wire vertical from plant toward hood
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend vertical spine at hx for this hood
    for dy in range(-spine_r, spine_r + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Extend horizontal spine at hy
    for dx in range(-spine_r, spine_r + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx2_c, hy2_c = active_hoods[hood_idx2]
    for (hx1, hy1) in active_hoods:
        for (hx2b, hy2b) in active_hoods:
            # Horizontal connections
            if hy1 == hy2b and hx2b > hx1 and hx2b - hx1 <= 16:
                for cx2 in range(hx1 + 1, hx2b):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical connections
            if hx1 == hx2b and hy2b > hy1 and hy2b - hy1 <= 16:
                for cy2 in range(hy1 + 1, hy2b):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    hood_idx3 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx3]

    # Roads flanking vertical wire spine (hx3±1)
    for rx_off in [1, -1, 2, -2]:
        rx = hx3 + rx_off
        if not ib(rx, hy3): continue
        for dy in range(-spine_r, spine_r + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                return (Tool.ROAD, rx, ry)

    # Roads flanking horizontal wire spine (hy3±1)
    for ry_off in [1, -1, 2, -2]:
        ry2 = hy3 + ry_off
        if not ib(hx3, ry2): continue
        for dx in range(-spine_r, spine_r + 1):
            rcx = hx3 + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: DENSE ROAD GRID EXTENSION ----
    road_rows_target = list(range(6, 97, 6))
    road_cols_target = list(range(6, 117, 6))

    for rr in road_rows_target:
        row_road = rm[rr, :]
        if row_road.any():
            idxs = np.where(row_road)[0]
            left = int(idxs[0]); right = int(idxs[-1])
            if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]) and bool(nbr_power[rr, left - 1]):
                return (Tool.ROAD, left - 1, rr)
            if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]) and bool(nbr_power[rr, right + 1]):
                return (Tool.ROAD, right + 1, rr)
        elif bool(nbr_power[rr, 60]) and bool(em[rr, 60]):
            return (Tool.ROAD, 60, rr)

    for rc in road_cols_target:
        col_road = rm[:, rc]
        if col_road.any():
            idxs = np.where(col_road)[0]
            top = int(idxs[0]); bot = int(idxs[-1])
            if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]) and bool(nbr_power[top - 1, rc]):
                return (Tool.ROAD, rc, top - 1)
            if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]) and bool(nbr_power[bot + 1, rc]):
                return (Tool.ROAD, rc, bot + 1)
        elif bool(nbr_power[50, rc]) and bool(em[50, rc]):
            return (Tool.ROAD, rc, 50)

    # ---- PHASE 6: ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Add zone clustering bonus
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS FROM EXISTING NETWORK ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (16, 16), (40, 16), (64, 16), (88, 16), (112, 16),
            (16, 32), (40, 32), (64, 32), (88, 32), (112, 32),
            (16, 48), (40, 48), (64, 48), (88, 48), (112, 48),
            (16, 64), (40, 64), (64, 64), (88, 64), (112, 64),
            (16, 80), (40, 80), (64, 80), (88, 80), (112, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (28, 24), (56, 24), (84, 24), (112, 24),
            (14, 44), (42, 44), (70, 44), (98, 44),
            (28, 60), (56, 60), (84, 60), (112, 60),
            (14, 76), (42, 76), (70, 76), (98, 76),
            (28, 90), (56, 90), (84, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150 and step % 3 == 0:
        park_ys_arr, park_xs_arr = np.where(em & nbr_road & nbr_power)
        if len(park_xs_arr) > 0:
            idx = (step * 23) % len(park_xs_arr)
            py2, px2 = int(park_ys_arr[idx]), int(park_xs_arr[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 800:
        stadiums = [
            (30, 30), (70, 30), (110, 30),
            (10, 55), (50, 55), (90, 55),
            (30, 75), (70, 75), (110, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        seaports = [(6, 88), (114, 88), (6, 10), (114, 10), (60, 6), (60, 94)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        sk2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (sk2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]) and funds > 500:
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire connections and road seeds."""
    actions = []
    # Three plants in a triangle
    actions.append((Tool.COALPOWER, 20, 30))
    actions.append((Tool.COALPOWER, 60, 70))
    actions.append((Tool.COALPOWER, 100, 30))
    # Horizontal wire at y=30 connecting left and right plants
    for x in range(18, 103):
        actions.append((Tool.WIRE, x, 30))
    # Vertical wire from y=30 down to y=70 at x=60
    for y in range(30, 72):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads near each plant
    for x in range(14, 30):
        actions.append((Tool.ROAD, x, 37))
    for x in range(54, 70):
        actions.append((Tool.ROAD, x, 63))
    for x in range(94, 110):
        actions.append((Tool.ROAD, x, 37))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Dilate helper ---
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # --- PHASE 1: Ensure power plants on a dense grid ---
    # Grid of plants every 20 cols, 20 rows
    plant_xs = list(range(10, WORLD_W - 5, 20))
    plant_ys = list(range(10, WORLD_H - 5, 20))

    for ppy in plant_ys:
        for ppx in plant_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)
                # Try nearby empty cells
                for r in range(1, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: Wire grid ---
    # Horizontal wires at rows 10, 20, 30, ... 90
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    # Extend horizontal wires
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(10, wr) and bool(em[wr, 10]):
                return (Tool.WIRE, 10, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[wr, left - 1]) and not bool(pm[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 2 and bool(em[wr, right + 1]) and not bool(pm[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top - 1, wc]) and not bool(pm[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 2 and bool(em[bot + 1, wc]) and not bool(pm[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # --- PHASE 3: Road grid ---
    # Roads at rows offset from wire rows
    road_rows = sorted(set(r for r in [wr + 5 for wr in wire_rows] if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in [wc + 5 for wc in wire_cols] if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- PHASE 4: Zone placement (reactive) ---
    zone_cand = em & near_road & near_power
    # Margins
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Don't place on infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys_arr, zone_xs_arr = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs_arr) > 0:
            zn_stride = max(1, len(zone_xs_arr) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs_arr), zn_stride):
                d = np.abs(cxs_arr - zone_xs_arr[i]).astype(float) + np.abs(cys_arr - zone_ys_arr[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer cells not too close or too far from existing zones
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist > 15, min_zone_dist * 0.3, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.4
        order = np.argsort(score)
        off = (step * 11 + pop % 17) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services (reactive) ---
    if pop > 30:
        fire_ys = list(range(13, WORLD_H - 5, 10))
        fire_xs = list(range(13, WORLD_W - 5, 15))
        for fsy in fire_ys:
            for fsx in fire_xs:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        pol_ys = list(range(16, WORLD_H - 5, 12))
        pol_xs = list(range(16, WORLD_W - 5, 18))
        for psy in pol_ys:
            for psx in pol_xs:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_ys = list(range(12, WORLD_H - 5, 8))
        park_xs = list(range(12, WORLD_W - 5, 10))
        for pky in park_ys:
            for pkx in park_xs:
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 600:
        stad_spots = [(sx, sy) for sy in range(18, 88, 20) for sx in range(18, 105, 25)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        # Upgrade to nuclear for more power
        nuc_spots = [(nx, ny) for ny in range(15, 90, 20) for nx in range(15, 110, 20)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
                y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(55, 7), (65, 7), (55, 92), (65, 92), (7, 45), (112, 45)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- PHASE 6: Wire extension toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 7: Road extension toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))
    elif len(rxs_c) > 0:
        k = step % len(rxs_c)
        return (Tool.ROAD, int(rxs_c[k]), int(rys_c[k]))

    # --- Fallback: road near existing plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6, 0), (-6, 0), (0, 6), (0, -6), (4, 0), (-4, 0), (0, 4), (0, -4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Last resort: extend wire from any wire tile ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        k = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            idx = (k + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[idx]), int(wire_ys_arr[idx])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: multiple coal plants with wire grid and road network"""
    actions = []
    # Coal plants at strategic positions across the map
    plant_positions = [
        (10, 10), (35, 10), (60, 10), (85, 10), (110, 10),
        (10, 33), (35, 33), (60, 33), (85, 33), (110, 33),
        (10, 50), (35, 50), (60, 50), (85, 50), (110, 50),
        (10, 66), (35, 66), (60, 66), (85, 66), (110, 66),
        (10, 88), (35, 88), (60, 88), (85, 88), (110, 88),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    wire_rows = [10, 20, 33, 43, 50, 57, 66, 76, 88]
    for wr in wire_rows:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wr))
    # Vertical wire spines
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 110]
    for wc in wire_cols:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wc, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Infrastructure layout
    wire_rows = [10, 20, 33, 43, 50, 57, 66, 76, 88]
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 110]

    # Road rows: one above and one below each wire row (if space)
    road_row_offsets = [-1, 1]
    road_col_offsets = [-1, 1]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 40% res, 30% com, 30% ind
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                t = tm[nr, nc]
                # Allow empty or existing zone tiles
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # ---- REACTIVE INFRASTRUCTURE ----

    # Priority 0: Ensure power plants are distributed
    if step % 10 == 0:
        # Check each quadrant for plant coverage
        plant_grid_xs = [10, 35, 60, 85, 110]
        plant_grid_ys = [10, 33, 50, 66, 88]
        for py in plant_grid_ys:
            for px in plant_grid_xs:
                x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
                y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
                has_plant = bool(np.any(pm[y0:y1, x0:x1]))
                if not has_plant:
                    # Find nearest empty tile near this position
                    for r in range(0, 6):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # Priority 1: Fill wire row gaps (extend wire grid)
    if step % 10 == 1:
        for wr in wire_rows:
            if not (0 <= wr < WORLD_H):
                continue
            # Find first gap in row
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    # Check if adjacent wire exists (to grow connected)
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Priority 2: Fill wire col gaps
    if step % 10 == 2:
        for wc in wire_cols:
            if not (0 <= wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Priority 3: Roads along wire rows
    if step % 10 == 3:
        for wr in wire_rows:
            for offset in road_row_offsets:
                ry = wr + offset
                if not (1 <= ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Place road if wire row is powered and road connects
                        wire_here = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   (ry > 0 and bool(rm[ry-1, rx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        if wire_here and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    # Priority 4: Roads along wire cols
    if step % 10 == 4:
        for wc in wire_cols:
            for offset in road_col_offsets:
                rcx = wc + offset
                if not (1 <= rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        wire_here = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                   bool(rm[ry, max(0, rcx-1)]) or \
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        if wire_here and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # Priority 5: Add cross streets between wire rows (reactive: only in powered areas)
    if step % 10 == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            for frac in [0.33, 0.66]:
                mid_y = int(r1 + (r2 - r1) * frac)
                for rx in range(1, WORLD_W - 1):
                    if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                        adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                              (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    # Priority 6: Cross streets between wire cols
    if step % 10 == 6:
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = int(c1 + (c2 - c1) * 0.5)
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                    adj = (ry > 0 and bool(rm[ry-1, mid_x])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Priority 7: Wire unpowered zones reactively
    if step % 10 == 7:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17 + pop) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (tx, bwy), (bwx, ty)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Priority 8: Extend wire toward unpowered roads
    if step % 10 == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23 + pop) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2), (tx, bwy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 15:
        # Dense fire station grid
        fire_spots = []
        for fy in range(8, WORLD_H - 5, 18):
            for fx in range(7, WORLD_W - 5, 20):
                fire_spots.append((fx, fy))
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = []
        for py2 in range(12, WORLD_H - 5, 20):
            for px2 in range(12, WORLD_W - 5, 22):
                police_spots.append((px2, py2))
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = []
        for sy2 in range(15, WORLD_H - 5, 30):
            for sx2 in range(20, WORLD_W - 5, 30):
                stadium_spots.append((sx2, sy2))
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        # Nuclear power plants for more capacity
        nuke_spots = []
        for ny3 in range(10, WORLD_H - 5, 25):
            for nx3 in range(10, WORLD_W - 5, 28):
                nuke_spots.append((nx3, ny3))
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [
            (5, 90), (115, 90), (5, 10), (115, 10),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (60, 5), (60, 95)
        ]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [
            (50, 5), (70, 5), (50, 92), (70, 92),
            (5, 45), (110, 45), (5, 60), (110, 60)
        ]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value in high-density areas
    if pop > 150 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (primary closed-loop action) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    # Keep zones away from wire/road spines
    for wr in wire_rows:
        y0, y1 = max(0, wr-1), min(WORLD_H, wr+2)
        cand_mask[y0:y1, :] = False
    for wc in wire_cols:
        x0, x1 = max(0, wc-1), min(WORLD_W, wc+2)
        cand_mask[:, x0:x1] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Dense grid of zone centers covering the whole map
        if pop < 80:
            # Focus near center first
            active_centers = []
            for row in range(3):
                for col in range(4):
                    cx = 30 + col * 18
                    cy = 30 + row * 18
                    active_centers.append((cx, cy))
        elif pop < 300:
            # Expand to middle thirds
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 12 + col * 16
                    cy = 12 + row * 16
                    active_centers.append((cx, cy))
        elif pop < 1000:
            # Full map coverage
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 8 + col * 13
                    cy = 8 + row * 12
                    active_centers.append((cx, cy))
        else:
            # Very dense full coverage
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        # Find candidates closest to active centers
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs.astype(float) - hx) + np.abs(cys.astype(float) - hy)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use step and pop for variation
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered empty area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13 + pop) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire toward empty powered-adjacent areas
    wire_ys3, wire_xs3 = np.where(wm | pm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17 + pop) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place two coal plants with wire connections and initial roads."""
    placements = []
    # Primary plant at (30, 50) - left side
    placements.append((Tool.COALPOWER, 30, 50))
    # Wire spine going right from plant
    for x in range(31, 40):
        placements.append((Tool.WIRE, x, 50))
    # Road above and below wire
    for x in range(31, 40):
        placements.append((Tool.ROAD, x, 49))
        placements.append((Tool.ROAD, x, 51))
    # Second plant on right side
    placements.append((Tool.COALPOWER, 90, 50))
    return placements[:20]


def act(obs, state):
    """
    Ambitious closed-loop policy:
    - Horizontal wire backbone across the map
    - Multiple clusters along a spine at y=50
    - Dense road grids per cluster
    - Balanced R/C/I with services
    - Expands with population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Initialize state
    if 'build_queue' not in state:
        state['build_queue'] = []
    if 'phase' not in state:
        state['phase'] = 'backbone'
    if 'wire_progress' not in state:
        state['wire_progress'] = 32  # start extending wire from x=32

    # Cluster centers spread across map (horizontal layout)
    # Each cluster is a neighborhood around a point
    clusters = [
        (30, 50),   # leftmost - anchored on init plant
        (50, 50),   # center-left
        (70, 50),   # center
        (90, 50),   # center-right - anchored on init plant
        (30, 25),   # upper-left
        (50, 25),   # upper-center-left
        (70, 25),   # upper-center
        (90, 25),   # upper-right
        (30, 75),   # lower-left
        (50, 75),   # lower-center-left
        (70, 75),   # lower-center
        (90, 75),   # lower-right
        (110, 50),  # far right
        (110, 25),  # far upper right
        (110, 75),  # far lower right
        (10, 50),   # far left
        (10, 25),   # far upper left
        (10, 75),   # far lower left
    ]

    # How many clusters to activate based on pop/zones
    num_active = max(2, min(len(clusters), 2 + pop // 150 + total_zones // 10))
    num_active = min(num_active, len(clusters))

    def pick_zone_tool():
        t = max(total_zones, 1)
        # Target ratio: 50% R, 25% C, 25% I
        i_r = ind_count / t
        c_r = com_count / t
        if ind_count < 5 or i_r < 0.22:
            return Tool.INDUSTRIAL
        if com_count < 5 or c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === STEP 1: Ensure power plants exist for active clusters ===
    for i in range(num_active):
        cx, cy = clusters[i]
        # Check if plant exists near this cluster (within 12 tiles)
        plant_near = False
        r = 12
        x0, x1 = max(0, cx - r), min(WORLD_W, cx + r + 1)
        y0, y1 = max(0, cy - r), min(WORLD_H, cy + r + 1)
        if np.any(pm[y0:y1, x0:x1]):
            plant_near = True
        if not plant_near:
            # Place plant at cluster center if clear-ish
            if in_bounds(cx, cy) and (bool(em[cy, cx]) or bool(wm[cy, cx])):
                return (Tool.COALPOWER, cx, cy)
            # Try nearby positions
            for r2 in range(1, 6):
                for dx in [-r2, 0, r2]:
                    for dy in [-r2, 0, r2]:
                        px, py = cx + dx * 2, cy + dy * 2
                        if in_bounds(px, py) and bool(em[py, px]):
                            return (Tool.COALPOWER, px, py)

    # === STEP 2: Build horizontal wire backbone at y=50, y=25, y=75 ===
    backbone_rows = [50, 25, 75]
    # Connect clusters at same row with wire
    for by in backbone_rows:
        for x in range(2, WORLD_W - 2):
            if in_bounds(x, by) and not bool(wm[by, x]) and not bool(pm[by, x]):
                # Only build wire if a plant is within 30 tiles on same row
                has_plant_row = False
                for dx2 in range(-35, 36):
                    nx2 = x + dx2
                    if in_bounds(nx2, by) and bool(pm[by, nx2]):
                        has_plant_row = True
                        break
                # Also check if there's wire nearby to extend from
                has_wire_nearby = False
                for dx2 in range(-3, 4):
                    nx2 = x + dx2
                    if in_bounds(nx2, by) and (bool(wm[by, nx2]) or bool(pm[by, nx2])):
                        has_wire_nearby = True
                        break
                if has_wire_nearby and bool(em[by, x]):
                    return (Tool.WIRE, x, by)

    # === STEP 3: Build vertical wire spines connecting backbone rows ===
    # Connect y=50 backbone to y=25 and y=75 at cluster x positions
    for i in range(num_active):
        cx, cy = clusters[i]
        # Vertical wire from cy to backbone at y=50
        if cy != 50:
            y_start = min(cy, 50)
            y_end = max(cy, 50)
            for vy in range(y_start, y_end + 1):
                if in_bounds(cx, vy) and not bool(wm[vy, cx]) and not bool(pm[vy, cx]):
                    # Check if backbone wire exists at this x
                    has_src = bool(pm[cy, cx]) or bool(wm[cy, cx]) or \
                               bool(pm[50, cx]) or bool(wm[50, cx])
                    if has_src and bool(em[vy, cx]):
                        return (Tool.WIRE, cx, vy)

    # === STEP 4: Build road grids around each active cluster ===
    # Each cluster gets a grid: horizontal roads every 4 rows, vertical roads flanking wire
    for i in range(num_active):
        cx, cy = clusters[i]
        extent = min(16, 6 + pop // 80)

        # Check if power is reachable near cluster
        x0, x1 = max(0, cx - 8), min(WORLD_W, cx + 9)
        y0, y1 = max(0, cy - 8), min(WORLD_H, cy + 9)
        if not np.any(wm[y0:y1, x0:x1] | pm[y0:y1, x0:x1]):
            continue  # No power near this cluster yet

        top = max(2, cy - extent)
        bot = min(WORLD_H - 3, cy + extent)
        left = max(2, cx - extent)
        right = min(WORLD_W - 3, cx + extent)

        # Vertical road columns at cx-2 and cx+2 (flanking wire at cx)
        for road_col in [cx - 2, cx + 2]:
            if not in_bounds(road_col, cy):
                continue
            for ry in range(top, bot + 1):
                if in_bounds(road_col, ry) and bool(em[ry, road_col]) and not bool(pm[ry, road_col]):
                    return (Tool.ROAD, road_col, ry)

        # Horizontal road rows every 4 rows
        for row_off in range(-extent, extent + 1, 4):
            hry = cy + row_off
            if not in_bounds(cx, hry):
                continue
            for hx in range(left, right + 1):
                if in_bounds(hx, hry) and bool(em[hry, hx]) and not bool(pm[hry, hx]):
                    return (Tool.ROAD, hx, hry)

    # === STEP 5: Place zones near roads and power ===
    # Build neighborhood masks with vectorized shifts
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        scores = np.full(len(cxs_arr), 999999.0)
        for i in range(min(num_active, len(clusters))):
            cx2, cy2 = clusters[i]
            d = np.abs(cxs_arr - cx2) + np.abs(cys_arr - cy2)
            scores = np.minimum(scores, d.astype(float))
        order = np.argsort(scores)

        def zone_clear(zx, zy):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr2, nc2 = zy + dr, zx + dc
                    if not in_bounds(nc2, nr2):
                        return False
                    if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                        return False
            return True

        step_off = (step * 7) % max(len(order), 1)
        tool = pick_zone_tool()
        for i in range(min(len(order), 150)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === STEP 6: Extend wire network ===
    all_pw_y, all_pw_x = np.where(wm | pm)
    if len(all_pw_x) > 0:
        step_k = (step * 13) % max(len(all_pw_x), 1)
        for offset in range(min(len(all_pw_x), 30)):
            k = (step_k + offset * 7) % len(all_pw_x)
            wx, wy = int(all_pw_x[k]), int(all_pw_y[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx + dx3, wy + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === STEP 7: Extend roads near wire ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k2 = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k2 + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === STEP 8: Services based on population ===
    if pop > 200:
        service_locs = [
            (32, 43), (32, 57), (52, 43), (52, 57),
            (72, 43), (72, 57), (92, 43), (92, 57),
            (32, 18), (52, 18), (72, 18), (92, 18),
            (32, 68), (52, 68), (72, 68), (92, 68),
        ]
        for fsx, fsy in service_locs:
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                x0, x1 = max(0, fsx - 5), min(WORLD_W, fsx + 6)
                y0, y1 = max(0, fsy - 5), min(WORLD_H, fsy + 6)
                if np.any(wm[y0:y1, x0:x1] | pm[y0:y1, x0:x1]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 500:
        police_locs = [
            (40, 50), (60, 50), (80, 50), (100, 50),
            (40, 25), (60, 25), (80, 25), (100, 25),
            (40, 75), (60, 75), (80, 75), (100, 75),
        ]
        for psx, psy in police_locs:
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                x0, x1 = max(0, psx - 6), min(WORLD_W, psx + 7)
                y0, y1 = max(0, psy - 6), min(WORLD_H, psy + 7)
                if np.any(wm[y0:y1, x0:x1] | pm[y0:y1, x0:x1]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 1000:
        stadium_locs = [(55, 50), (75, 50), (35, 50), (55, 25), (75, 25)]
        for ssx, ssy in stadium_locs:
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    if pop > 2000 and funds > 15000:
        nuke_locs = [(15, 10), (105, 10), (15, 90), (105, 90), (60, 10), (60, 90)]
        for nsx, nsy in nuke_locs:
            if in_bounds(nsx, nsy) and bool(em[nsy, nsx]):
                x0, x1 = max(0, nsx - 10), min(WORLD_W, nsx + 11)
                y0, y1 = max(0, nsy - 10), min(WORLD_H, nsy + 11)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, nsx, nsy)

    return None

def init(obs, state):
    """Bootstrap: multiple coal plants + wire grid + road grid skeleton"""
    actions = []
    # Place 4 coal plants at strategic corners/quadrants
    plants = [(30, 25), (90, 25), (30, 75), (90, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))

    # Wire horizontal spines connecting plants
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 25))
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 75))
    # Wire vertical spines
    for y in range(27, 75):
        actions.append((Tool.WIRE, 30, y))
    for y in range(27, 75):
        actions.append((Tool.WIRE, 90, y))

    # Horizontal roads at y=20, 35, 50, 65, 80
    for rx in [20, 35, 50, 65, 80]:
        for x in range(5, 115):
            actions.append((Tool.ROAD, x, rx))
    # Vertical roads at x=15, 30, 45, 60, 75, 90, 105
    for ry in [15, 30, 45, 60, 75, 90, 105]:
        for y in range(5, 95):
            actions.append((Tool.ROAD, ry, y))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Ensure power plants exist on a dense grid ----
    # Plants every 24 tiles in both directions for full coverage
    plant_positions = []
    for py in range(15, 95, 24):
        for px in range(15, 115, 24):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire to connect plants and power zones ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)

    # Find unpowered plants
    unpowered_plants = [(px, py) for px, py in plant_positions
                        if ib(px, py) and np.any(pm[max(0,py-1):py+2, max(0,px-1):px+2])
                        and not bool(near_power[py, px])]

    if len(wxs) > 0:
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:15])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward empty unpowered areas
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0 and total_zones < 500:
            rng_idx = list(range(min(60, len(upxs))))
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in rng_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Dense road grid (every 6 tiles) ----
    road_grid_pts = []
    for gy in range(5, 97, 6):
        for gx in range(5, 116, 6):
            road_grid_pts.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid_pts
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:50]
            for i in range(min(len(rxs2), 600)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:15]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement with balanced RCI ratios ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride3):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Score: close to road, away from existing zones
        score = road_dist * 1.0 + np.maximum(0, 12 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Balanced RCI: target 50% RES, 25% COM, 25% IND
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)

        # Determine tool based on ratios and step cycle
        step_mod = step % 8
        if ir < 0.20:
            tool = Tool.INDUSTRIAL
        elif cr < 0.25:
            tool = Tool.COMMERCIAL
        elif step_mod < 4:
            tool = Tool.RESIDENTIAL
        elif step_mod < 6:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

        for i in range(min(len(order), 1200)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled to population ----
    if pop > 40:
        fire_grid = [(fx, fy) for fy in range(10, 92, 12) for fx in range(10, 112, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(14, 90, 14) for px2 in range(14, 108, 14)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(8, 95, 8) for pkx in range(8, 115, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(20, 15), (60, 15), (100, 15),
                        (20, 50), (60, 50), (100, 50),
                        (20, 85), (60, 85), (100, 85),
                        (40, 32), (80, 32), (40, 68), (80, 68)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        nuke_locs = [(15, 15), (60, 15), (105, 15),
                     (15, 50), (105, 50),
                     (15, 85), (60, 85), (105, 85),
                     (40, 33), (80, 33), (40, 67), (80, 67)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 8), min(WORLD_W, nx + 9)
                y0, y1 = max(0, ny - 8), min(WORLD_H, ny + 9)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(8, 8), (100, 8), (8, 85), (100, 85), (55, 8), (55, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(8, 50), (112, 50), (60, 6), (60, 93), (20, 20), (100, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: wire/road near power plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 2), (-2, 2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2), (-2, 0), (0, -2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious closed-loop city builder
# Strategy: 6x5 grid (30 neighborhoods) covering the full 120x100 map
# Dense power grid with horizontal wire spines + vertical connectors
# Mixed zones: 40% res, 35% com, 25% ind
# Early power plants at multiple locations, aggressive road network

def init(obs, state):
    """Bootstrap: 4 coal plants spread across map with initial wire/road."""
    actions = []
    # 4 plants in a 2x2 arrangement
    plants = [(30, 25), (90, 25), (30, 75), (90, 75)]
    for (px, py) in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertically
        for dy in range(-4, 5):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # Roads on both sides
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 40% res, 35% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 columns x 5 rows = 30 neighborhoods across full map
    nh_cols = [10, 30, 50, 70, 90, 110]
    nh_rows = [10, 28, 50, 72, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 12
        if pop < 800:   return 18
        if pop < 1500:  return 22
        if pop < 3000:  return 26
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick active hoods spread across map
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MASKS ----
    power_src = wm | pm

    # nbr_power: cells within 5 of a wire/plant
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # nbr_road: cells within 3 of a road
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 16):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: HORIZONTAL WIRE SPINE at each hood row ----
    # Connect power plants horizontally across each row
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        if len(row_hoods) < 2:
            continue
        row_hoods.sort(key=lambda h: h[0])
        xl = row_hoods[0][0]
        xr = row_hoods[-1][0]
        # Wire along the hood row
        for cx in range(xl, xr + 1):
            if ib(cx, hy_row) and not bool(wm[hy_row, cx]) and not bool(pm[hy_row, cx]):
                if bool(em[hy_row, cx]):
                    return (Tool.WIRE, cx, hy_row)

    # ---- PHASE 3: VERTICAL WIRE SPINE connecting columns ----
    for hx_col in nh_cols:
        col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
        col_hoods.sort(key=lambda h: h[1])
        for i in range(len(col_hoods) - 1):
            hy1 = col_hoods[i][1]
            hy2 = col_hoods[i + 1][1]
            for cy in range(hy1, hy2 + 1):
                if ib(hx_col, cy) and not bool(wm[cy, hx_col]) and not bool(pm[cy, hx_col]):
                    if bool(em[cy, hx_col]):
                        return (Tool.WIRE, hx_col, cy)

    # ---- PHASE 4: ROADS — horizontal lanes flanking wire spines ----
    # Place roads at hood_row ± 4 as horizontal arteries
    if step % 3 < 2:  # spend 2/3 steps on roads
        for hy_row in nh_rows:
            row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
            if not row_hoods:
                continue
            row_hoods.sort(key=lambda h: h[0])
            xl = max(2, row_hoods[0][0] - 3)
            xr = min(WORLD_W - 3, row_hoods[-1][0] + 3)
            for road_offset in [-4, 4]:
                road_y = hy_row + road_offset
                if not ib(0, road_y):
                    continue
                for cx in range(xl, xr + 1):
                    if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]) and not bool(wm[road_y, cx]):
                        return (Tool.ROAD, cx, road_y)

    # ---- PHASE 5: VERTICAL ROADS connecting hood rows ----
    if pop > 50:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for road_offset in [-4, 4]:
                    rx = hx_col + road_offset
                    for cy in range(hy1, hy2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]) and not bool(wm[cy, rx]):
                            adj_road = any(ib(rx+ddx, cy+ddy) and bool(rm[cy+ddy, rx+ddx])
                                           for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)])
                            if adj_road or cy == hy1 or cy == hy2:
                                return (Tool.ROAD, rx, cy)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: ADDITIONAL POWER PLANTS for coverage ----
    # Add nuclear plants when population grows
    if pop > 500:
        nuke_candidates = [(20, 50), (60, 10), (60, 90), (100, 50),
                           (20, 10), (20, 90), (100, 10), (100, 90),
                           (40, 30), (80, 30), (40, 70), (80, 70)]
        for (nx4, ny4) in nuke_candidates:
            x0, x1 = max(0, nx4 - 15), min(WORLD_W, nx4 + 16)
            y0, y1 = max(0, ny4 - 15), min(WORLD_H, ny4 + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])) and ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    # ---- PHASE 8: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy)
                      for fx in range(15, WORLD_W, 20)
                      for fy in range(15, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2)
                        for px2 in range(18, WORLD_W, 24)
                        for py2 in range(18, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (25, 5), (60, 5), (95, 5),
            (25, 94), (60, 94), (95, 94),
            (5, 25), (5, 50), (5, 75),
            (114, 25), (114, 50), (114, 75),
            (40, 50), (80, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(5, 5), (115, 5), (5, 94), (115, 94), (60, 2), (60, 97)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [
            (35, 5), (85, 5), (35, 94), (85, 94),
            (5, 40), (5, 60), (115, 40), (115, 60),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value boost ----
    if pop > 300 and step % 4 == 0:
        zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 40)):
                k = (step * 3 + i * 13) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # ---- EXTEND ROADS near powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # ---- FALLBACK: new coal plant near uncovered hood ----
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: central power plant with wire cross and road grid."""
    actions = []
    # Central coal plant
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending out
    for d in range(-6, 7):
        if d != 0:
            actions.append((Tool.WIRE, cx + d, cy))
            actions.append((Tool.WIRE, cx, cy + d))
    # Roads flanking the wire
    for d in range(-6, 7):
        actions.append((Tool.ROAD, cx + d, cy - 2))
        actions.append((Tool.ROAD, cx + d, cy + 2))
        actions.append((Tool.ROAD, cx - 2, cy + d))
        actions.append((Tool.ROAD, cx + 2, cy + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Balance: 50% res, 30% com, 20% ind
        if ind_count / total_zones < 0.20:
            return Tool.INDUSTRIAL
        if com_count / total_zones < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Progressive grid of neighborhood anchors across the whole map
    # 6 cols x 5 rows = 30 possible neighborhoods
    all_anchors = []
    for col_x in [15, 35, 55, 75, 95, 115]:
        for row_y in [12, 28, 50, 72, 88]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 20:    return 1
        if pop < 80:    return 3
        if pop < 200:   return 6
        if pop < 400:   return 9
        if pop < 700:   return 12
        if pop < 1000:  return 16
        if pop < 1500:  return 20
        if pop < 2500:  return 25
        return 30

    n_active = min(num_active(), len(all_anchors))
    active_anchors = all_anchors[:n_active]

    # ---- PHASE 1: ENSURE POWER PLANTS at each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant at nearest empty spot
            for r in range(0, 8):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE from each plant outward (closed-loop: scan from plant tiles) ----
    # Find all plant tiles, grow wires reactively toward active anchors
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        # For each active anchor, check if wire reaches it; if not, extend wire
        for (px, py) in active_anchors:
            # Check if wire/plant already near anchor
            r2 = 3
            y0 = max(0, py - r2); y1 = min(WORLD_H, py + r2 + 1)
            x0 = max(0, px - r2); x1 = min(WORLD_W, px + r2 + 1)
            has_wire = np.any(wm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1])
            if not has_wire:
                # Find nearest wire/plant tile, extend toward anchor
                best = None
                best_d = 999999
                for i in range(len(plant_xs)):
                    d = abs(int(plant_xs[i]) - px) + abs(int(plant_ys[i]) - py)
                    if d < best_d:
                        best_d = d
                        best = (int(plant_xs[i]), int(plant_ys[i]))
                wire_ys2, wire_xs2 = np.where(wm)
                for i in range(len(wire_xs2)):
                    d = abs(int(wire_xs2[i]) - px) + abs(int(wire_ys2[i]) - py)
                    if d < best_d:
                        best_d = d
                        best = (int(wire_xs2[i]), int(wire_ys2[i]))
                if best is not None:
                    wx, wy = best
                    # Step toward anchor
                    dx = px - wx
                    dy = py - wy
                    if abs(dx) >= abs(dy):
                        nx, ny = wx + (1 if dx > 0 else -1), wy
                    else:
                        nx, ny = wx, wy + (1 if dy > 0 else -1)
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: Wire cross around each anchor (reactive: only empty spots) ----
    spine = min(10, 4 + pop // 25)
    for (px, py) in active_anchors:
        for dx in range(-spine, spine + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine, spine + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # ---- PHASE 4: Connect wire between anchors in same row/column ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1r, _ = row_anchors[i]
            x2r, _ = row_anchors[i + 1]
            for cx in range(x1r + 1, x2r):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl])
        for i in range(len(col_anchors) - 1):
            _, y1c = col_anchors[i]
            _, y2c = col_anchors[i + 1]
            for cy in range(y1c + 1, y2c):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- PHASE 5: Roads flanking wire at each anchor ----
    for (px, py) in active_anchors:
        for road_dy in [-2, 2]:
            ry = py + road_dy
            if not ib(px, ry): continue
            for dx in range(-spine, spine + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)
        for road_dx in [-2, 2]:
            rx = px + road_dx
            if not ib(rx, py): continue
            for dy in range(-spine, spine + 1):
                ry = py + dy
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- PHASE 6: Vertical roads connecting neighborhood rows ----
    if pop > 30:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl])
            for i in range(len(col_anchors) - 1):
                _, y1c = col_anchors[i]
                _, y2c = col_anchors[i + 1]
                for rdx in [-3, 3]:
                    rx = xl + rdx
                    for cy in range(y1c, y2c + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- COMPUTE NEIGHBOR MASKS ----
    # near_road: any cell within 2 steps of a road
    near_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            near_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # near_power: any cell within 5 steps of wire or plant
    near_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            near_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            near_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    # ---- PHASE 7: ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    # Keep 2-cell border clear
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to nearest active anchor
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Rotate through candidates to avoid getting stuck
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 8: EXTEND ROADS reactively from existing roads near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive thresholds) ----
    if pop > 60:
        fire_spots = [
            (8, 12), (32, 12), (58, 12), (82, 12), (112, 12),
            (8, 35), (32, 35), (58, 35), (82, 35), (112, 35),
            (8, 55), (32, 55), (58, 55), (82, 55), (112, 55),
            (8, 75), (32, 75), (58, 75), (82, 75), (112, 75),
            (8, 92), (32, 92), (58, 92), (82, 92), (112, 92),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (18, 8), (48, 8), (78, 8), (108, 8),
            (18, 45), (48, 45), (78, 45), (108, 45),
            (18, 88), (48, 88), (78, 88), (108, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (12, 5), (60, 5), (108, 5),
            (12, 94), (60, 94), (108, 94),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        # Upgrade to nuclear power
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1800:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones to boost land value ----
    if pop > 150:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: dense coal plants + wire grid + road spines"""
    actions = []
    # Coal plants at key intersections across the map
    plant_positions = [
        (10, 10), (35, 10), (60, 10), (85, 10), (110, 10),
        (10, 33), (35, 33), (60, 33), (85, 33), (110, 33),
        (10, 50), (35, 50), (60, 50), (85, 50), (110, 50),
        (10, 66), (35, 66), (60, 66), (85, 66), (110, 66),
        (10, 90), (35, 90), (60, 90), (85, 90), (110, 90),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [10, 20, 33, 43, 50, 57, 66, 76, 90]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [10, 25, 40, 55, 70, 85, 100, 115]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 35% res, 35% com, 30% ind
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Infrastructure grid definitions
    wire_rows = [10, 20, 33, 43, 50, 57, 66, 76, 90]
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    # Roads between wire rows/cols (in the gaps)
    road_rows = [14, 17, 24, 27, 37, 40, 47, 53, 60, 63, 70, 73, 80, 83, 94, 97]
    road_cols = [5, 15, 18, 30, 33, 45, 48, 60, 63, 75, 78, 90, 93, 108, 111]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 18

    # Phase 0: Ensure power plants cover all regions
    if phase == 0:
        plant_targets = []
        for py in range(10, 95, 20):
            for px in range(10, 115, 25):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 14), min(WORLD_W, px + 15)
            y0, y1 = max(0, py - 14), min(WORLD_H, py + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1-2: Fill wire row gaps
    if phase in (1, 2):
        target_rows = wire_rows if phase == 1 else [15, 25, 38, 53, 61, 71, 83]
        for wr in target_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 3-4: Fill wire col gaps
    if phase in (3, 4):
        target_cols = wire_cols if phase == 3 else [18, 32, 47, 62, 77, 92, 107]
        for wc in target_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 5: Build horizontal road grid
    if phase == 5:
        for rr in road_rows:
            if not (0 < rr < WORLD_H):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    adj = (rx > 0 and bool(rm[rr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or \
                          (rr > 0 and bool(rm[rr-1, rx])) or \
                          (rr < WORLD_H-1 and bool(rm[rr+1, rx]))
                    if adj or rx == 1:
                        return (Tool.ROAD, rx, rr)

    # Phase 6: Build vertical road grid
    if phase == 6:
        for rc in road_cols:
            if not (0 < rc < WORLD_W):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    adj = (ry > 0 and bool(rm[ry-1, rc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or \
                          (rc > 0 and bool(rm[ry, rc-1])) or \
                          (rc < WORLD_W-1 and bool(rm[ry, rc+1]))
                    if adj or ry == 1:
                        return (Tool.ROAD, rc, ry)

    # Phase 7: Wire road gaps to connect roads to power
    if phase == 7:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Wire unpowered zones
    if phase == 8:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 9: Road to unroaded zones
    if phase == 9:
        unroaded_zones = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded_zones)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (closed-loop, scaled to pop) ----
    if pop > 15:
        fire_spots = [
            (5,5),(30,5),(60,5),(90,5),(115,5),
            (5,15),(115,15),(5,28),(115,28),
            (5,40),(115,40),(5,55),(115,55),
            (5,68),(115,68),(5,82),(115,82),
            (5,95),(30,95),(60,95),(90,95),(115,95),
            (20,20),(45,20),(70,20),(95,20),
            (20,50),(45,50),(70,50),(95,50),
            (20,80),(45,80),(70,80),(95,80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (12,8),(37,8),(62,8),(87,8),(112,8),
            (12,22),(37,22),(62,22),(87,22),(112,22),
            (12,38),(37,38),(62,38),(87,38),(112,38),
            (12,52),(37,52),(62,52),(87,52),(112,52),
            (12,68),(37,68),(62,68),(87,68),(112,68),
            (12,82),(37,82),(62,82),(87,82),(112,82),
            (12,95),(37,95),(62,95),(87,95),(112,95),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (25,12),(75,12),(25,38),(75,38),
            (25,62),(75,62),(25,88),(75,88),
            (50,25),(100,25),(50,75),(100,75),
            (10,50),(110,50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
