def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target ratio: 50% res, 25% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire and road corridor definitions
    wire_rows = [15, 30, 50, 65, 85]
    wire_cols = [10, 20, 40, 60, 80, 100, 110]
    road_offsets = [-1, 1]

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 8)
    near_road = dilate(rm, 2)

    # ---- Check for unpowered areas and add plants ----
    # Divide map into 4x4 sectors, ensure each has power
    sector_w = WORLD_W // 4  # 30
    sector_h = WORLD_H // 4  # 25
    for sr in range(4):
        for sc in range(4):
            x0 = sc * sector_w
            y0 = sr * sector_h
            x1 = min(x0 + sector_w, WORLD_W)
            y1 = min(y0 + sector_h, WORLD_H)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                cx = (x0 + x1) // 2
                cy = (y0 + y1) // 2
                # Find empty spot near center of sector
                for r in range(1, 15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = cx + dx, cy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ---- Wire extension phase ----
    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_wire = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left_ok = wx > 0 and bool(row_wire[wx - 1])
                    right_ok = wx < WORLD_W - 1 and bool(row_wire[wx + 1])
                    if (left_ok or right_ok) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_wire = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    up_ok = wy > 0 and bool(col_wire[wy - 1])
                    dn_ok = wy < WORLD_H - 1 and bool(col_wire[wy + 1])
                    if (up_ok or dn_ok) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Add diagonal wire connectors between corridors
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                # Connect plant to horizontal corridor
                for y in range(wr, min(wr + 10, WORLD_H)):
                    if ib(wc, y) and bool(pm[y, wc]):
                        # Wire from plant to corridor
                        for wy in range(min(y, wr), max(y, wr) + 1):
                            if ib(wc, wy) and bool(em[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 3:
        # Roads along horizontal wire corridors (both sides)
        for wr in wire_rows:
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                row_wire = wm[wr, :] | pm[wr, :]
                for rx in range(2, WORLD_W - 2):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads along vertical wire corridors
        for wc in wire_cols:
            for offset in road_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                col_wire = wm[:, wc] | pm[:, wc]
                for ry in range(2, WORLD_H - 2):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Add horizontal cross roads between wire column corridors
        for wr_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            mid_y = (r1 + r2) // 2
            for wc_idx in range(len(wire_cols) - 1):
                c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
                for rx in range(c1 + 1, c2):
                    if ib(rx, mid_y) and bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                        adj = (ib(rx - 1, mid_y) and bool(rm[mid_y, rx - 1])) or \
                              (ib(rx + 1, mid_y) and bool(rm[mid_y, rx + 1]))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    elif phase == 6:
        # Add vertical cross roads between wire row corridors
        for wc_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            mid_x = (c1 + c2) // 2
            for wr_idx in range(len(wire_rows) - 1):
                r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
                for ry in range(r1 + 1, r2):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x, ry - 1) and bool(rm[ry - 1, mid_x])) or \
                              (ib(mid_x, ry + 1) and bool(rm[ry + 1, mid_x]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 7:
        # Extend road from existing road endpoints near power
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            step_k = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 150)):
                k = (step_k + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Add additional wire rows at y=30, 65 if not present
        extra_wire_rows = [30, 65]
        for wr in extra_wire_rows:
            row_has_wire = bool(np.any(wm[wr, :]))
            if not row_has_wire:
                # Find nearest wire/plant to connect from
                wire_ys_arr, wire_xs_arr = np.where(wm | pm)
                if len(wire_xs_arr) > 0:
                    dists = np.abs(wire_ys_arr - wr)
                    best_wi = np.argmin(dists)
                    bwx = int(wire_xs_arr[best_wi])
                    if ib(bwx, wr) and bool(em[wr, bwx]):
                        return (Tool.WIRE, bwx, wr)

    else:
        # phase == 9: Seed wires from plants to nearest corridor
        plant_ys, plant_xs = np.where(pm)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            # Find closest wire row and extend wire toward it
            closest_wr = min(wire_rows, key=lambda r: abs(r - py2))
            if abs(closest_wr - py2) > 1:
                step_y = 1 if closest_wr > py2 else -1
                ny2 = py2 + step_y
                if ib(px2, ny2) and bool(em[ny2, px2]):
                    return (Tool.WIRE, px2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    # Avoid edges and wire/plant corridors
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    for wr in wire_rows:
        y0 = max(0, wr - 1)
        y1 = min(WORLD_H, wr + 2)
        cand_mask[y0:y1, :] = False
    for wc in wire_cols:
        x0 = max(0, wc - 1)
        x1 = min(WORLD_W, wc + 2)
        cand_mask[:, x0:x1] = False

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool((resm | comm | indm)[nr, nc]):
                    return False
        return True

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score candidates by proximity to powered roads
        # Use multiple neighborhood centers spread across map
        nh_centers = []
        for row in range(5):
            for col in range(6):
                cx = 10 + col * 20
                cy = 10 + row * 20
                nh_centers.append((cx, cy))

        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in nh_centers:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_positions = [
            (5, 5), (30, 5), (55, 5), (80, 5), (110, 5),
            (5, 25), (30, 25), (55, 25), (80, 25), (110, 25),
            (5, 45), (30, 45), (55, 45), (80, 45), (110, 45),
            (5, 65), (30, 65), (55, 65), (80, 65), (110, 65),
            (5, 88), (30, 88), (55, 88), (80, 88), (110, 88),
        ]
        for (sx, sy) in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 38), (45, 38), (75, 38), (105, 38),
            (15, 58), (45, 58), (75, 58), (105, 58),
            (15, 78), (45, 78), (75, 78), (105, 78),
            (15, 95), (45, 95), (75, 95), (105, 95),
        ]
        for (sx, sy) in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (35, 35), (85, 35), (35, 60), (85, 60),
            (10, 20), (110, 20), (10, 70), (110, 70),
            (60, 5), (60, 90),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 94), (90, 94),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [
            (10, 94), (110, 94), (10, 5), (110, 5),
            (60, 5), (60, 94), (35, 94), (85, 94),
        ]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [
            (50, 5), (70, 5), (50, 90), (70, 90),
            (5, 45), (5, 55), (110, 45), (110, 55),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near zones for land value boost
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire toward unpowered zones ----
    unpowered_zone_ys, unpowered_zone_xs = np.where(zone_tiles & ~near_power)
    if len(unpowered_zone_xs) > 0:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_zx = int(unpowered_zone_xs[0])
            target_zy = int(unpowered_zone_ys[0])
            dists = np.abs(wire_xs_arr - target_zx) + np.abs(wire_ys_arr - target_zy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_zx == bwx else (1 if target_zx > bwx else -1)
            dy = 0 if target_zy == bwy else (1 if target_zy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: wire extension from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at corners + center, with wire spines and roads."""
    actions = []
    # Plant locations: 4 quadrant centers + middle
    plants = [(25, 20), (90, 20), (25, 75), (90, 75), (57, 48)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertically from plant
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, py + dy))
        # Wire spine horizontally from plant
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
        # Roads flanking vertical wire
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 50% res, 30% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 5 neighborhood anchors covering map widely
    all_anchors = [
        (25, 20),   # top-left
        (90, 20),   # top-right
        (57, 48),   # center
        (25, 75),   # bottom-left
        (90, 75),   # bottom-right
        (57, 20),   # top-center
        (57, 75),   # bottom-center
        (10, 48),   # far left
        (108, 48),  # far right
    ]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 3
        if pop < 300:   return 5
        if pop < 600:   return 6
        if pop < 1000:  return 7
        if pop < 1500:  return 8
        return 9

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 10); y1 = min(WORLD_H, py + 11)
        x0 = max(0, px - 10); x1 = min(WORLD_W, px + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            # Need plant near here
            for r in range(0, 14):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE SPINE (cross: vertical + horizontal) ----
    spine_half = min(18, 7 + pop // 15)
    for (px, py) in active_anchors:
        # Vertical spine
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        for wy in range(spine_top, spine_bot + 1):
            if ib(px, wy) and bool(em[wy, px]) and not bool(pm[wy, px]):
                return (Tool.WIRE, px, wy)
        # Horizontal spine
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        for wx in range(spine_left, spine_right + 1):
            if ib(wx, py) and bool(em[py, wx]) and not bool(pm[py, wx]):
                return (Tool.WIRE, wx, py)

    # ---- HORIZONTAL WIRE connecting anchors at same row level ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_xs = sorted(px for (px, py) in active_anchors if py == yl)
        for i in range(len(row_xs) - 1):
            for cx in range(row_xs[i] + 1, row_xs[i + 1]):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows at same column ----
    x_levels = sorted(set(px for (px, _) in active_anchors))
    for xl in x_levels:
        col_ys = sorted(py for (px, py) in active_anchors if px == xl)
        for i in range(len(col_ys) - 1):
            for cy in range(col_ys[i] + 1, col_ys[i + 1]):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID around each anchor ----
    # Roads at offsets -2 and +2 from anchor (flanking wire cross)
    for idx, (px, py) in enumerate(active_anchors):
        spine_half2 = min(18, 7 + pop // 15)
        spine_top = max(2, py - spine_half2)
        spine_bot = min(WORLD_H - 3, py + spine_half2)
        spine_left = max(2, px - spine_half2)
        spine_right = min(WORLD_W - 3, px + spine_half2)

        # Vertical roads flanking vertical wire
        cycle = (step + idx * 11) % 3
        for road_x in [px - 2, px + 2]:
            if not ib(road_x, py):
                continue
            for wy in range(spine_top + cycle, spine_bot + 1, 3):
                if ib(road_x, wy) and bool(em[wy, road_x]) and not bool(pm[wy, road_x]):
                    return (Tool.ROAD, road_x, wy)

        # Horizontal roads flanking horizontal wire
        for road_y in [py - 2, py + 2]:
            if not ib(px, road_y):
                continue
            for wx in range(spine_left + cycle, spine_right + 1, 3):
                if ib(wx, road_y) and bool(em[road_y, wx]) and not bool(pm[road_y, wx]):
                    return (Tool.ROAD, wx, road_y)

    # ---- CONNECTING ROADS between neighborhoods ----
    if pop > 30:
        # Connect anchor pairs with roads
        connect_pairs = [
            ((25, 20), (90, 20)),
            ((25, 75), (90, 75)),
            ((25, 20), (25, 75)),
            ((90, 20), (90, 75)),
            ((25, 20), (57, 48)),
            ((90, 20), (57, 48)),
            ((25, 75), (57, 48)),
            ((90, 75), (57, 48)),
        ]
        for (ax1, ay1), (ax2, ay2) in connect_pairs:
            if (ax1, ay1) not in active_anchors[:n_active] or (ax2, ay2) not in active_anchors[:n_active]:
                continue
            # Road at y = ay1 from ax1 to ax2
            road_y = (ay1 + ay2) // 2
            if abs(ax1 - ax2) > abs(ay1 - ay2):
                # Mostly horizontal
                for cx in range(min(ax1, ax2) + 1, max(ax1, ax2)):
                    if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                        return (Tool.ROAD, cx, road_y)
            else:
                # Mostly vertical
                road_x = (ax1 + ax2) // 2
                for cy in range(min(ay1, ay2) + 1, max(ay1, ay2)):
                    if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = [
            (8, 10), (40, 10), (75, 10), (108, 10),
            (8, 35), (40, 35), (75, 35), (108, 35),
            (8, 60), (40, 60), (75, 60), (108, 60),
            (8, 85), (40, 85), (75, 85), (108, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 8), (50, 8), (80, 8), (112, 8),
            (15, 45), (50, 45), (80, 45), (112, 45),
            (15, 88), (50, 88), (80, 88), (112, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (15, 5), (57, 5), (100, 5),
            (15, 92), (57, 92), (100, 92),
            (5, 48), (112, 48),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Upgrade to nuclear power
        nuke_spots = [
            (5, 5), (113, 5), (5, 93), (113, 93),
            (57, 5), (57, 93), (5, 48), (113, 48),
            (30, 5), (85, 5), (30, 93), (85, 93),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(53, 5), (5, 48), (113, 48), (53, 93), (30, 5), (85, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (113, 93), (57, 97), (5, 5), (113, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 19) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (2, -2), (-2, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- EXTEND WIRE from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 23) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at corners + cross wire grid"""
    actions = []
    # 4 coal plants near corners + 1 center
    plants = [(10, 10), (109, 10), (10, 89), (109, 89), (59, 49)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
