            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at x=10,30,50,70,90,109
    for y in range(0, 100):
        for wx in [10, 30, 50, 70, 90, 109]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for x in range(0, 120):
        for wy in [10, 30, 50, 70, 89]:
            for off in [-1, 1]:
                ry = wy + off
                if 0 <= ry < 100:
                    actions.append((Tool.ROAD, x, ry))
    # Roads flanking vertical wire spines
    for y in range(0, 100):
