def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === NEIGHBORHOOD GRID: dense across the whole map ===
    # Use a tighter grid for more coverage
    all_hoods = []
    for hy in range(10, 95, 10):
        for hx in range(10, 115, 10):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:    return 5
        if pop < 200:   return 10
        if pop < 500:   return 20
        if pop < 1000:  return 35
        if pop < 2000:  return 50
        if pop < 4000:  return 70
        if pop < 8000:  return 90
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread evenly across all hoods
    stride = max(1, len(all_hoods) // n_active)
    active_hoods = all_hoods[::stride][:n_active]

    # === BUILD NEIGHBOR MASKS ===
    power_src = wm | pm

    # Use faster dilation with cumsum approach
    def dilate_mask(mask, radius):
        h, w = mask.shape
        result = np.zeros((h, w), dtype=bool)
        # Horizontal pass
        cum = np.cumsum(mask.astype(np.int32), axis=1)
        left = np.maximum(0, np.arange(w) - radius)
        right = np.minimum(w - 1, np.arange(w) + radius)
        horiz = cum[:, right] - cum[:, left] + mask[:, left]
        # Actually simpler: just do standard shifts
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                if abs(dx) + abs(dy) > radius * 1.5:
                    continue
                sr0 = max(0, -dy); sr1 = min(h, h - dy)
                sc0 = max(0, -dx); sc1 = min(w, w - dx)
                r0 = max(0, dy);   r1 = min(h, h + dy)
                c0 = max(0, dx);   c1 = min(w, w + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_power = dilate_mask(power_src, 4)
    nbr_road = dilate_mask(rm, 3)

    # === PHASE 1: ENSURE ENOUGH POWER PLANTS ===
    # One plant per ~15x15 area of active hoods
    if funds > 500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Place plant at or near hood center
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE CONNECTIVITY ===
    # For current hood (cycling), extend wires from nearest plant
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant globally
    pys_all, pxs_all = np.where(pm)
    if len(pxs_all) > 0:
        dists = np.abs(pxs_all - hx) + np.abs(pys_all - hy)
        best_p = np.argmin(dists)
        px_near = int(pxs_all[best_p])
        py_near = int(pys_all[best_p])

        # Route wire from plant to hood: first vertical then horizontal
        # Step 1: wire vertically from plant toward hood y
        if py_near != hy:
            sdir = 1 if hy > py_near else -1
            for wy in range(py_near + sdir, hy + sdir, sdir):
                if not ib(px_near, wy): break
                t = tm[wy, px_near]
                if bool(pm[wy, px_near]): break  # hit another plant, stop
                if not bool(wm[wy, px_near]) and bool(em[wy, px_near]):
                    return (Tool.WIRE, px_near, wy)
                elif not bool(wm[wy, px_near]) and not bool(em[wy, px_near]):
                    break  # blocked

        # Step 2: wire horizontally from plant x toward hood x at hood y
        if px_near != hx:
            # Find current wire extent at hy row from px_near
            sdir = 1 if hx > px_near else -1
            # Check if we have vertical wire at px_near up to hy
            if bool(wm[hy, px_near]) or bool(pm[hy, px_near]) or py_near == hy:
                for wx in range(px_near + sdir, hx + sdir, sdir):
                    if not ib(wx, hy): break
                    if bool(pm[hy, wx]): break
                    if not bool(wm[hy, wx]) and bool(em[hy, wx]):
                        return (Tool.WIRE, wx, hy)
                    elif not bool(wm[hy, wx]) and not bool(em[hy, wx]):
                        break

    # === PHASE 3: ROAD NETWORK EXPANSION ===
    # Build roads in a grid pattern, expanding from existing roads
    # Target road rows and columns
    road_rows = list(range(8, 96, 8))
    road_cols = list(range(8, 116, 8))

    # Cycle through road rows/cols based on step
    phase3_idx = (step // 2) % (len(road_rows) + len(road_cols))

    if phase3_idx < len(road_rows):
        rr = road_rows[phase3_idx]
        # Find existing road in this row and extend, or start new if near power
        row_road = rm[rr, :]
        if row_road.any():
            idxs = np.where(row_road)[0]
            left = int(idxs[0]); right = int(idxs[-1])
            # Extend left
            for nx in range(left - 1, max(0, left - 4), -1):
                if ib(nx, rr) and bool(em[rr, nx]) and not bool(pm[rr, nx]):
                    return (Tool.ROAD, nx, rr)
            # Extend right
            for nx in range(right + 1, min(WORLD_W, right + 4)):
                if ib(nx, rr) and bool(em[rr, nx]) and not bool(pm[rr, nx]):
                    return (Tool.ROAD, nx, rr)
        else:
            # Start a road at a powered spot
            for cx in range(5, WORLD_W - 5, 3):
                if ib(cx, rr) and bool(em[rr, cx]) and not bool(pm[rr, cx]) and bool(nbr_power[rr, cx]):
                    return (Tool.ROAD, cx, rr)
    else:
        rc = road_cols[phase3_idx - len(road_rows)]
        col_road = rm[:, rc]
        if col_road.any():
            idxs = np.where(col_road)[0]
            top = int(idxs[0]); bot = int(idxs[-1])
            for ny in range(top - 1, max(0, top - 4), -1):
                if ib(rc, ny) and bool(em[ny, rc]) and not bool(pm[ny, rc]):
                    return (Tool.ROAD, rc, ny)
            for ny in range(bot + 1, min(WORLD_H, bot + 4)):
                if ib(rc, ny) and bool(em[ny, rc]) and not bool(pm[ny, rc]):
                    return (Tool.ROAD, rc, ny)
        else:
            for cy in range(5, WORLD_H - 5, 3):
                if ib(rc, cy) and bool(em[cy, rc]) and not bool(pm[cy, rc]) and bool(nbr_power[cy, rc]):
                    return (Tool.ROAD, rc, cy)

    # === PHASE 4: ZONE PLACEMENT ===
    def zone_clear(zx, zy):
        """Check 3x3 area centered at zx,zy is placeable."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate positions: empty, near road, near power, not at boundary
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_c, cxs_c = np.where(cand_mask)
    if len(cxs_c) > 0:
        # Score candidates: prefer near active hoods and existing zones
        best_dist = np.full(len(cxs_c), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs_c - hx2) + np.abs(cys_c - hy2)
            best_dist = np.minimum(best_dist, d)

        # Also favor clustering with existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs_c), 999999.0)
                stride2 = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride2):
                    d2 = np.abs(cxs_c - zxs2[i]).astype(float) + np.abs(cys_c - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        # Try multiple candidates
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs_c[k]), int(cys_c[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: EXTEND ROADS FROM EXISTING NETWORK ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 6: CIVIC SERVICES ===
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(12, 95, 18)
                     for fx in range(12, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(nbr_road[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(14, 90, 20)
                       for px2 in range(14, 112, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(nbr_road[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 4 == 0:
        park_cands_y2, park_cands_x2 = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x2) > 0:
            idx2 = (step * 17) % len(park_cands_x2)
            py3, px3 = int(park_cands_y2[idx2]), int(park_cands_x2[idx2])
            if ib(px3, py3):
                return (Tool.PARK, px3, py3)

    if pop > 250:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 94), (5, 50), (114, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 30), (60, 70),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 350:
        seaport_locs = [
            (5, 50), (114, 50), (60, 5), (60, 94),
            (5, 25), (5, 75), (114, 25), (114, 75),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [
            (10, 10), (100, 10), (10, 85), (100, 85),
            (55, 5), (55, 92), (5, 45), (112, 45),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === PHASE 7: CONNECT WIRE BETWEEN HOODS ===
    for i in range(len(active_hoods)):
        hx1, hy1 = active_hoods[i]
        for j in range(i + 1, min(i + 4, len(active_hoods))):
            hx2, hy2 = active_hoods[j]
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 25:
                continue
            if abs(hy1 - hy2) <= 2:
                my = (hy1 + hy2) // 2
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if ib(cx2, my) and bool(em[my, cx2]) and not bool(pm[my, cx2]) and not bool(wm[my, cx2]):
                        has_adj = any(bool(wm[my, c]) or bool(pm[my, c])
                                      for c in range(max(0, cx2-3), min(WORLD_W, cx2+4)) if c != cx2)
                        if has_adj:
                            return (Tool.WIRE, cx2, my)
            if abs(hx1 - hx2) <= 2:
                mx = (hx1 + hx2) // 2
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if ib(mx, cy2) and bool(em[cy2, mx]) and not bool(pm[cy2, mx]) and not bool(wm[cy2, mx]):
                        has_adj = any(bool(wm[r, mx]) or bool(pm[r, mx])
                                      for r in range(max(0, cy2-3), min(WORLD_H, cy2+4)) if r != cy2)
                        if has_adj:
                            return (Tool.WIRE, mx, cy2)

    # === FALLBACK: extend wire from existing plant/wire ===
    pys_f, pxs_f = np.where(pm)
    if len(pxs_f) > 0:
        sk = (step * 11) % len(pxs_f)
        for offset in range(min(len(pxs_f), 60)):
            k = (sk + offset * 7) % len(pxs_f)
            px3, py3 = int(pxs_f[k]), int(pys_f[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    wys_f, wxs_f = np.where(wm)
    if len(wxs_f) > 0:
        sk2 = (step * 13) % len(wxs_f)
        for offset in range(min(len(wxs_f), 60)):
            k = (sk2 + offset * 5) % len(wxs_f)
            wx2, wy2 = int(wxs_f[k]), int(wys_f[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === LAST RESORT: place new plant near uncovered hood ===
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]) and funds > 500:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central power cluster with road+wire spines"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Four satellite plants
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 20, 80))
    actions.append((Tool.COALPOWER, 100, 80))
    # Horizontal wire spines at y=20, y=50, y=80
    for x in range(18, 103, 2):
        actions.append((Tool.WIRE, x, 20))
        actions.append((Tool.WIRE, x, 80))
    for x in range(18, 103, 2):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at x=20, x=60, x=100
    for y in range(18, 83, 2):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Road grid seeds
    for x in range(10, 115, 2):
        actions.append((Tool.ROAD, x, 30))
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 60))
        actions.append((Tool.ROAD, x, 70))
    for y in range(10, 95, 2):
        actions.append((Tool.ROAD, 30, y))
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 70, y))
        actions.append((Tool.ROAD, 90, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Balanced zone mix: 50% RES, 25% COM, 25% IND
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        # Early game: seed industrial first for demand
        if total_zones < 20:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # PHASE 1: Ensure power plants on dense grid (one per 15x15 block)
    plant_spacing = 15
    plant_xs = list(range(8, WORLD_W - 5, plant_spacing))
    plant_ys = list(range(8, WORLD_H - 5, plant_spacing))

    for ppy in plant_ys:
        for ppx in plant_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 8), min(WORLD_W, ppx + 9)
            y0, y1 = max(0, ppy - 8), min(WORLD_H, ppy + 9)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # PHASE 2: Wire grid - horizontal wires every 10 rows
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 2 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 2 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # PHASE 3: Dense road grid every 10 cols/rows (offset from wire grid)
    road_rows = sorted(set(r for r in [wr + 5 for wr in wire_rows] if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in [wc + 5 for wc in wire_cols] if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # PHASE 4: Zone placement - fill ALL cells near road+power
    zone_cand = em & near_road & near_power
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H - 3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W - 3:] = False
    # Block infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer spreading outward but not too far from existing zones
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            # Seed near center
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.2 + zone_score * 0.5
        order = np.argsort(score)
        # Use step-based offset for variety
        off = (step * 7 + pop % 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic services - aggressively placed based on pop
    if pop > 20:
        # Fire stations in a dense grid
        fire_grid_y = list(range(12, WORLD_H - 5, 10))
        fire_grid_x = list(range(12, WORLD_W - 5, 15))
        for fsy in fire_grid_y:
            for fsx in fire_grid_x:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        pol_grid_y = list(range(14, WORLD_H - 5, 12))
        pol_grid_x = list(range(14, WORLD_W - 5, 18))
        for psy in pol_grid_y:
            for psx in pol_grid_x:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid_y = list(range(11, WORLD_H - 5, 8))
        park_grid_x = list(range(11, WORLD_W - 5, 10))
        for pky in park_grid_y:
            for pkx in park_grid_x:
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 400:
        stad_spots = [(sx, sy) for sy in range(15, 90, 20) for sx in range(15, 110, 25)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        # Nuclear plants for more power capacity
        nuc_spots = [(nx, ny) for ny in range(12, 92, 20) for nx in range(12, 112, 20)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
                y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        airport_spots = [(55, 5), (65, 5), (55, 94), (65, 94), (5, 45), (114, 45)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_spots = [(5, 50), (114, 50), (60, 5), (60, 94)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # PHASE 6: Wire extension toward unpowered zones
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 30)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # PHASE 7: Road extension toward unserved zones
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 30)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Fallback: lay road near power plant
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# High-reactivity closed-loop city builder
# Strategy: Dense grid of neighborhoods covering most of the 120x100 map
# Each neighborhood has its own power plant, wire grid, roads, and zones
# Reactive: reads tile_map each step to decide next action

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking vertical wire spine
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- DENSE NEIGHBORHOOD GRID: 8 cols x 7 rows = 56 neighborhoods ----
    # Spaced 14 apart to cover more map
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [8, 22, 36, 50, 64, 78, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 8
        if pop < 600:   return 14
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 42
        if pop < 8000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Select hoods outward from center
    center = (60, 50)
    sorted_hoods = sorted(all_hoods, key=lambda h: abs(h[0]-center[0]) + abs(h[1]-center[1]))
    active_hoods = sorted_hoods[:n_active]

    # ---- BUILD nbr_power and nbr_road masks (reactive to current map) ----
    # Power proximity (within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Road proximity (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE EACH ACTIVE HOOD HAS A POWER PLANT ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center or nearest empty
            for r in range(8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from each plant ----
    # For each hood, extend wire vertically and horizontally from plant
    spine_range = 7
    hood_idx = step % max(len(active_hoods), 1)
    for offset in range(len(active_hoods)):
        idx_h = (hood_idx + offset) % len(active_hoods)
        hx, hy = active_hoods[idx_h]

        # Find actual plant location near this hood
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        plant_locs = np.where(pm[y0:y1, x0:x1])
        if len(plant_locs[0]) == 0:
            continue
        px = int(plant_locs[1][0]) + x0
        py = int(plant_locs[0][0]) + y0

        # Extend vertical wire spine at px
        for dy in range(-spine_range, spine_range + 1):
            wy = py + dy
            if not ib(px, wy): continue
            if bool(pm[wy, px]): continue
            if bool(wm[wy, px]): continue
            if not bool(em[wy, px]): continue
            # Only place if adjacent to existing wire or plant
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(px, ay) and (bool(wm[ay, px]) or bool(pm[ay, px])):
                    return (Tool.WIRE, px, wy)

        # Extend horizontal wire spine at py
        for dx in range(-spine_range, spine_range + 1):
            wx = px + dx
            if not ib(wx, py): continue
            if bool(pm[py, wx]): continue
            if bool(wm[py, wx]): continue
            if not bool(em[py, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, py) and (bool(wm[py, ax]) or bool(pm[py, ax])):
                    return (Tool.WIRE, wx, py)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    # Connect horizontally and vertically adjacent hoods
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 20: continue

            # Connect along shortest path
            if hy1 == hy2:  # horizontal neighbors
                xs = range(min(hx1, hx2), max(hx1, hx2) + 1)
                for cx2 in xs:
                    if not ib(cx2, hy1): continue
                    if bool(pm[hy1, cx2]) or bool(wm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    # Check adjacency to wire
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            elif hx1 == hx2:  # vertical neighbors
                ys = range(min(hy1, hy2), max(hy1, hy2) + 1)
                for cy2 in ys:
                    if not ib(hx1, cy2): continue
                    if bool(pm[cy2, hx1]) or bool(wm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for offset in range(len(active_hoods)):
        idx_h = (hood_idx + offset) % len(active_hoods)
        hx, hy = active_hoods[idx_h]

        # Find plant location
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        plant_locs = np.where(pm[y0:y1, x0:x1])
        if len(plant_locs[0]) == 0:
            continue
        px2 = int(plant_locs[1][0]) + x0
        py2 = int(plant_locs[0][0]) + y0

        # Roads flanking vertical spine (at px2-1, px2+1)
        for rx in [px2 - 1, px2 + 1]:
            if not ib(rx, py2): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = py2 + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]): continue
                if bool(pm[ry, rx]): continue
                # Only if adjacent wire exists
                if bool(wm[ry, px2]) or bool(pm[ry, px2]):
                    return (Tool.ROAD, rx, ry)

        # Roads flanking horizontal spine (at py2-1, py2+1)
        for ry2 in [py2 - 1, py2 + 1]:
            if not ib(px2, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = px2 + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]): continue
                if bool(pm[ry2, rcx]): continue
                if bool(wm[py2, rcx]) or bool(pm[py2, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: EXTEND ROADS into powered areas ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) 
                    and not bool(pm[ny2, nx2])
                    and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: empty + near road + near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Prefer zones close to active hoods
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx) + np.abs(cys2 - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 18) for fy in range(10, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px3, py3) for px3 in range(15, WORLD_W, 22) for py3 in range(15, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 50), (75, 50), (30, 50), (90, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 93), (75, 93), (6, 40), (6, 60), (113, 40), (113, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR UPGRADE for high-pop ----
    if pop > 2500 and step % 4 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (15, 50), (105, 50), (60, 20), (60, 80)]
        for (nx3, ny3) in nuclear_spots:
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.NUCLEARPOWER, nx3, ny3)

    # ---- PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx2 = (step * 17) % len(park_xs)
            py3, px3 = int(park_ys[idx2]), int(park_xs[idx2])
            if ib(px3, py3) and bool(em[py3, px3]):
                return (Tool.PARK, px3, py3)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % len(wire_xs2)
        for offset in range(min(len(wire_xs2), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs2)
            wx3, wy3 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx4, ny4 = wx3 + dx4, wy3 + dy4
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    return (Tool.WIRE, nx4, ny4)

    # ---- FALLBACK: new plant near uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx5, ny5 = hx + dx, hy + dy
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    return None

# High-reactivity closed-loop city builder
# Strategy: Dense grid of neighborhoods with multiple power plants
# Each step reads the map and decides what's most needed

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire connections and initial roads."""
    actions = []
    # Three power plants spread across the map
    plants = [(30, 50), (60, 50), (90, 50)]
    for (px, py) in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from each plant
        for d in range(1, 4):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px - d, py))
            actions.append((Tool.WIRE, px, py + d))
            actions.append((Tool.WIRE, px, py - d))
    # Horizontal wire spine connecting plants at y=50
    for x in range(32, 60):
        actions.append((Tool.WIRE, x, 50))
    for x in range(62, 90):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))
    plant_count = int(np.sum(pm))

    # ---- NEIGHBORHOOD GRID ----
    # Dense 6x5 grid of neighborhoods
    hood_cols = [12, 28, 44, 60, 76, 92, 108]
    hood_rows = [12, 28, 44, 60, 76, 90]
    all_hoods = [(c, r) for r in hood_rows for c in hood_cols]

    # Unlock neighborhoods progressively
    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 6
        if pop < 1000:  return 9
        if pop < 2000:  return 12
        if pop < 4000:  return 18
        if pop < 7000:  return 24
        if pop < 10000: return 30
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active neighborhood should have a plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant at hood center or nearby empty spot
            for r in range(10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: BUILD WIRE GRID ----
    # Wire spine: horizontal at each hood_row, vertical at each hood_col
    # Connect every plant to the nearest wire spine

    # First: connect any isolated plants to wire
    plant_ys, plant_xs = np.where(pm)
    for i in range(len(plant_xs)):
        px2, py2 = int(plant_xs[i]), int(plant_ys[i])
        # Check if any adjacent wire
        has_adj_wire = False
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = px2+dx, py2+dy
            if ib(nx, ny) and bool(wm[ny, nx]):
                has_adj_wire = True
                break
        if not has_adj_wire:
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
                nx, ny = px2+dx, py2+dy
                if ib(nx, ny) and bool(em[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # Build horizontal wire spines at hood rows
    for hy in hood_rows:
        # Extend wire leftward and rightward
        row_wires = [c for c in range(WORLD_W) if bool(wm[hy, c])]
        if row_wires:
            min_wc, max_wc = min(row_wires), max(row_wires)
            # Extend right to cover hood columns
            max_hood_x = max(hx for hx, _ in active_hoods)
            if max_wc < min(max_hood_x + 2, WORLD_W - 3):
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            # Extend left
            min_hood_x = min(hx for hx, _ in active_hoods)
            if min_wc > max(min_hood_x - 2, 2):
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # Build vertical wire spines at hood cols
    for hx in hood_cols:
        col_wires = [r for r in range(WORLD_H) if bool(wm[r, hx])]
        if col_wires:
            min_wr, max_wr = min(col_wires), max(col_wires)
            max_hood_y = max(hy for _, hy in active_hoods)
            if max_wr < min(max_hood_y + 2, WORLD_H - 3):
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            min_hood_y = min(hy for _, hy in active_hoods)
            if min_wr > max(min_hood_y - 2, 2):
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)

    # Connect wire spines: if hood col and hood row wires don't meet, fill gap
    for hx in hood_cols:
        for hy in hood_rows:
            if not bool(wm[hy, hx]):
                # Check if there's wire nearby to extend from
                # Try from column wire
                col_wires = [r for r in range(max(0, hy-15), min(WORLD_H, hy+16))
                             if bool(wm[r, hx])]
                if col_wires:
                    closest = min(col_wires, key=lambda r: abs(r - hy))
                    step_dir = 1 if hy > closest else -1
                    next_r = closest + step_dir
                    if ib(hx, next_r) and not bool(pm[next_r, hx]):
                        return (Tool.WIRE, hx, next_r)
                # Try from row wire
                row_wires = [c for c in range(max(0, hx-15), min(WORLD_W, hx+16))
                             if bool(wm[hy, c])]
                if row_wires:
                    closest = min(row_wires, key=lambda c: abs(c - hx))
                    step_dir = 1 if hx > closest else -1
                    next_c = closest + step_dir
                    if ib(next_c, hy) and not bool(pm[hy, next_c]):
                        return (Tool.WIRE, next_c, hy)

    # ---- PHASE 3: BUILD ROAD GRID ----
    # Roads parallel to wire spines (offset by 1)
    # Horizontal roads at hy-1 and hy+1 for each hood row
    # Vertical roads at hx-1 and hx+1 for each hood col

    # Build a power neighbor mask (any wire or plant within 1 tile)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-1, 2):
        for dx in range(-1, 2):
            sr0 = max(0, -dy); sr1 = WORLD_H - max(0, dy)
            sc0 = max(0, -dx); sc1 = WORLD_W - max(0, dx)
            r0 = max(0, dy); r1 = WORLD_H - max(0, -dy)
            c0 = max(0, dx); c1 = WORLD_W - max(0, -dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Wide power neighbor mask for zones
    wide_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = WORLD_H - max(0, dy)
            sc0 = max(0, -dx); sc1 = WORLD_W - max(0, dx)
            r0 = max(0, dy); r1 = WORLD_H - max(0, -dy)
            c0 = max(0, dx); c1 = WORLD_W - max(0, -dx)
            wide_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            wide_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Road neighbor mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = WORLD_H - max(0, dy)
            sc0 = max(0, -dx); sc1 = WORLD_W - max(0, dx)
            r0 = max(0, dy); r1 = WORLD_H - max(0, -dy)
            c0 = max(0, dx); c1 = WORLD_W - max(0, -dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build roads along hood rows (offset +/-1)
    active_hood_rows = sorted(set(hy for _, hy in active_hoods))
    active_hood_cols = sorted(set(hx for hx, _ in active_hoods))

    for hy in active_hood_rows:
        for road_y in [hy - 1, hy + 1]:
            if not ib(0, road_y):
                continue
            # Find road extent and extend
            row_roads = [c for c in range(WORLD_W) if bool(rm[road_y, c])]
            if row_roads:
                min_rc, max_rc = min(row_roads), max(row_roads)
                # Extend right
                target_x = min(max(active_hood_cols) + 3, WORLD_W - 3)
                if max_rc < target_x:
                    nc = max_rc + 1
                    if ib(nc, road_y) and bool(em[road_y, nc]) and not bool(pm[road_y, nc]):
                        return (Tool.ROAD, nc, road_y)
                # Extend left
                target_x_l = max(min(active_hood_cols) - 3, 2)
                if min_rc > target_x_l:
                    nc = min_rc - 1
                    if ib(nc, road_y) and bool(em[road_y, nc]) and not bool(pm[road_y, nc]):
                        return (Tool.ROAD, nc, road_y)
            else:
                # Start a road segment where wire exists at hy
                row_wires_local = [c for c in range(WORLD_W) if bool(wm[hy, c])]
                if row_wires_local:
                    start_c = row_wires_local[len(row_wires_local)//2]
                    if ib(start_c, road_y) and bool(em[road_y, start_c]):
                        return (Tool.ROAD, start_c, road_y)

    for hx in active_hood_cols:
        for road_x in [hx - 1, hx + 1]:
            if not ib(road_x, 0):
                continue
            col_roads = [r for r in range(WORLD_H) if bool(rm[r, road_x])]
            if col_roads:
                min_rr, max_rr = min(col_roads), max(col_roads)
                target_y = min(max(active_hood_rows) + 3, WORLD_H - 3)
                if max_rr < target_y:
                    nr = max_rr + 1
                    if ib(road_x, nr) and bool(em[nr, road_x]) and not bool(pm[nr, road_x]):
                        return (Tool.ROAD, road_x, nr)
                target_y_t = max(min(active_hood_rows) - 3, 2)
                if min_rr > target_y_t:
                    nr = min_rr - 1
                    if ib(road_x, nr) and bool(em[nr, road_x]) and not bool(pm[nr, road_x]):
                        return (Tool.ROAD, road_x, nr)
            else:
                col_wires_local = [r for r in range(WORLD_H) if bool(wm[r, hx])]
                if col_wires_local:
                    start_r = col_wires_local[len(col_wires_local)//2]
                    if ib(road_x, start_r) and bool(em[start_r, road_x]):
                        return (Tool.ROAD, road_x, start_r)

    # ---- PHASE 4: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        # Balance: ~30% industrial, ~30% commercial, ~40% residential
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate positions: empty, near road AND near power, not on border
    cand_mask = em & nbr_road & wide_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer closer to active hood centers
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Cycle through top candidates
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- PHASE 5: EXTEND ROADS from existing road network ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(wide_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 6: CIVIC SERVICES ----
    if pop > 150:
        fire_spots = [
            (20, 20), (45, 20), (70, 20), (95, 20),
            (20, 45), (45, 45), (70, 45), (95, 45),
            (20, 70), (45, 70), (70, 70), (95, 70),
            (20, 90), (45, 90), (70, 90), (95, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (25, 25), (55, 25), (85, 25),
            (25, 55), (55, 55), (85, 55),
            (25, 80), (55, 80), (85, 80),
            (10, 50), (110, 50), (60, 10), (60, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [
            (35, 35), (75, 35), (35, 65), (75, 65),
            (55, 15), (55, 82), (15, 50), (105, 50)
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(8, 85), (108, 85), (8, 15), (108, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(55, 8), (55, 88), (8, 50), (108, 50)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 7: NUCLEAR PLANTS for more power ----
    if pop > 3000 and plant_count < 6:
        nuke_spots = [(20, 20), (100, 20), (20, 80), (100, 80), (60, 50)]
        for (sx, sy) in nuke_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.NUCLEARPOWER, sx, sy)

    # ---- PHASE 8: PARKS for land value ----
    if pop > 300 and step % 4 == 0:
        park_cands = np.where(em & nbr_road & wide_power)
        if len(park_cands[0]) > 0:
            idx = (step * 17) % len(park_cands[0])
            py2, px2 = int(park_cands[0][idx]), int(park_cands[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place coal plant somewhere useful ----
    for (hx, hy) in active_hoods:
        if ib(hx, hy) and bool(em[hy, hx]):
            return (Tool.COALPOWER, hx, hy)

    return None

# Closed-loop city builder - highly reactive, dense, ambitious
# Strategy: Multiple power plants distributed across map, comprehensive road grid,
# dense zone placement, aggressive civic services scaling

def init(obs, state):
    """Bootstrap: 3 coal plants + wires + roads in central area."""
    actions = []
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Left plant
    actions.append((Tool.COALPOWER, 20, 50))
    # Right plant  
    actions.append((Tool.COALPOWER, 100, 50))
    # Wire from central plant in all directions
    for d in range(1, 8):
        actions.append((Tool.WIRE, 60 + d, 50))
        actions.append((Tool.WIRE, 60 - d, 50))
        actions.append((Tool.WIRE, 60, 50 + d))
        actions.append((Tool.WIRE, 60, 50 - d))
    # Roads next to central plant
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID: 10 cols x 8 rows = 80 neighborhoods ----
    nh_cols = [6, 18, 30, 42, 54, 66, 78, 90, 102, 114]
    nh_rows = [6, 18, 30, 42, 54, 66, 78, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Power plant target locations - distributed across the map
    plant_targets = [
        (60, 50), (20, 25), (60, 25), (100, 25),
        (20, 75), (60, 75), (100, 75), (10, 50),
        (110, 50), (40, 50), (80, 50), (20, 50), (100, 50),
        (30, 10), (90, 10), (30, 90), (90, 90),
        (60, 10), (60, 90), (10, 10), (110, 10),
        (10, 90), (110, 90), (50, 40), (70, 40),
        (50, 60), (70, 60), (40, 30), (80, 30),
        (40, 70), (80, 70),
    ]

    def num_plants_needed():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 10
        if pop < 1000:  return 14
        if pop < 2000:  return 18
        if pop < 4000:  return 22
        return len(plant_targets)

    def num_active():
        if pop < 30:    return 4
        if pop < 100:   return 8
        if pop < 300:   return 16
        if pop < 700:   return 28
        if pop < 1500:  return 44
        if pop < 3000:  return 60
        if pop < 6000:  return 72
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MASKS ----
    # Road neighbor mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    n_needed = num_plants_needed()
    existing_plants = int(np.sum(pm))

    if existing_plants < n_needed:
        for (px, py) in plant_targets:
            if not ib(px, py): continue
            # Check if already has plant nearby
            x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
            y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find empty spot near target
                for r in range(12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = px + dx, py + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE FROM EACH PLANT ----
    # For each plant, grow wires outward in 4 directions
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        # Pick a plant to extend wire from (cycle through them)
        k = step % len(plant_xs)
        px2, py2 = int(plant_xs[k]), int(plant_ys[k])
        # Try to extend wire in each direction
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for dx, dy in directions:
            # Walk out until we find a gap
            for dist in range(1, 20):
                wx, wy = px2 + dx * dist, py2 + dy * dist
                if not ib(wx, wy): break
                if bool(pm[wy, wx]): break
                if not bool(wm[wy, wx]) and bool(em[wy, wx]):
                    # Check if previous tile has wire or plant
                    prev_x, prev_y = px2 + dx * (dist - 1), py2 + dy * (dist - 1)
                    if bool(wm[prev_y, prev_x]) or bool(pm[prev_y, prev_x]):
                        return (Tool.WIRE, wx, wy)
                    break
                if bool(wm[wy, wx]):
                    continue
                break

    # ---- PHASE 3: WIRE BACKBONE connecting neighborhoods ----
    # Build wire along rows and columns of neighborhoods
    wire_cycle = step % max(len(active_hoods), 1)
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if idx_h != wire_cycle:
            continue
        # Extend wire from this neighborhood center outward
        if not bool(nbr_power[hy, hx]):
            continue
        # Horizontal wire extension
        for sign in [1, -1]:
            for d in range(1, 15):
                wx, wy = hx + sign * d, hy
                if not ib(wx, wy): break
                if bool(pm[wy, wx]): break
                if bool(wm[wy, wx]): continue
                if bool(em[wy, wx]):
                    prev_x = hx + sign * (d - 1)
                    if ib(prev_x, wy) and (bool(wm[wy, prev_x]) or bool(pm[wy, prev_x])):
                        return (Tool.WIRE, wx, wy)
                break
        # Vertical wire extension
        for sign in [1, -1]:
            for d in range(1, 15):
                wx, wy = hx, hy + sign * d
                if not ib(wx, wy): break
                if bool(pm[wy, wx]): break
                if bool(wm[wy, wx]): continue
                if bool(em[wy, wx]):
                    prev_y = hy + sign * (d - 1)
                    if ib(wx, prev_y) and (bool(wm[prev_y, wx]) or bool(pm[prev_y, wx])):
                        return (Tool.WIRE, wx, wy)
                break

    # ---- PHASE 4: CONNECT WIRE BETWEEN NEAREST PLANT AND EACH HOOD ----
    # Find hoods without power, connect to nearest wire
    for (hx, hy) in active_hoods:
        if bool(nbr_power[hy, hx]):
            continue
        # Find nearest wire/plant
        if len(plant_xs) == 0:
            continue
        # Nearest plant
        dists = np.abs(plant_xs - hx) + np.abs(plant_ys - hy)
        nearest_k = int(np.argmin(dists))
        npx, npy = int(plant_xs[nearest_k]), int(plant_ys[nearest_k])
        # Draw wire from plant toward hood
        dx = hx - npx
        dy = hy - npy
        if abs(dx) >= abs(dy):
            step_x = 1 if dx > 0 else -1
            wx = npx + step_x
            wy = npy
        else:
            step_x = 0
            wx = npx
            wy = npy + (1 if dy > 0 else -1)
        if ib(wx, wy) and bool(em[wy, wx]):
            return (Tool.WIRE, wx, wy)

    # ---- PHASE 5: ROAD GRID ----
    # Build roads flanking wire spines at each neighborhood
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step // max(len(active_hoods), 1) + idx_h) % 3 != 0:
            continue
        if not bool(nbr_power[hy, hx]):
            continue
        # Roads flanking vertical spine (wire at hx)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-8, 9):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Only place road if near wire
                    if bool(nbr_power[ry, rx]):
                        return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal spine
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-8, 9):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(nbr_power[ry2, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 7) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 11) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.27:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers - must have road AND power nearby
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by distance to nearest active hood
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.sqrt((cxs2 - hx) ** 2 + (cys2 - hy) ** 2)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 8: CIVIC SERVICES (scaled by population) ----
    if pop > 50:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 14) for fy in range(10, WORLD_H, 14)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(12, WORLD_W, 18) for py2 in range(12, WORLD_H, 18)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        # Dense stadium grid
        stadium_spots = [(sx, sy) for sx in range(20, WORLD_W, 30) for sy in range(20, WORLD_H, 30)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaport_spots = [(8, 95), (112, 95), (8, 5), (112, 5),
                         (60, 97), (60, 3), (30, 97), (90, 97),
                         (30, 3), (90, 3)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        # Switch to nuclear power for clean energy
        nuclear_spots = [
            (60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
            (40, 10), (80, 10), (40, 90), (80, 90),
            (10, 50), (110, 50), (60, 15), (60, 85),
            (30, 40), (90, 40), (30, 60), (90, 60),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        airport_spots = [(50, 5), (70, 5), (50, 95), (70, 95),
                         (5, 40), (5, 60), (115, 40), (115, 60),
                         (20, 5), (100, 5)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 100 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from any existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: multiple power plants + cross wires + roads grid"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine at x=60
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking central horizontal wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Roads flanking central vertical wire
    for y in range(1, 99):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    # Corner power plants
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 20, 80))
    actions.append((Tool.COALPOWER, 100, 80))
    # Additional plants mid-edge
    actions.append((Tool.COALPOWER, 60, 10))
    actions.append((Tool.COALPOWER, 60, 90))
    actions.append((Tool.COALPOWER, 10, 50))
    actions.append((Tool.COALPOWER, 110, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: ~30% industrial, ~30% commercial, ~40% residential
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Dense grid of wire corridors (tighter spacing for more coverage)
    wire_rows = [8, 18, 28, 38, 48, 50, 52, 58, 68, 78, 88, 96]
    wire_cols = [8, 18, 28, 38, 48, 58, 60, 62, 72, 82, 92, 102, 112]

    # Power plant grid: more plants for better coverage
    plant_positions = []
    for row in range(5):
        for col in range(5):
            px = 10 + col * 25  # 10, 35, 60, 85, 110
            py = 10 + row * 20  # 10, 30, 50, 70, 90
            plant_positions.append((px, py))

    # ---- PHASE 1: ENSURE PLANTS EXIST ----
    for px, py in plant_positions:
        x0, x1 = max(0, px-8), min(WORLD_W, px+9)
        y0, y1 = max(0, py-8), min(WORLD_H, py+9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID CONSTRUCTION ----
    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_has_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy, wr, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
                    if ib(bpx, wr) and bool(em[wr, bpx]):
                        return (Tool.WIRE, bpx, wr)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_has_power[wx]):
                        if (wx > 0 and bool(row_has_power[wx-1])) or \
                           (wx < WORLD_W-1 and bool(row_has_power[wx+1])):
                            if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_has_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2, wc, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
                    if ib(wc, bpy2) and bool(em[bpy2, wc]):
                        return (Tool.WIRE, wc, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_has_power[wy]):
                        if (wy > 0 and bool(col_has_power[wy-1])) or \
                           (wy < WORLD_H-1 and bool(col_has_power[wy+1])):
                            if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads on BOTH sides of each horizontal wire row
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads on BOTH sides of each vertical wire col
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Cross-connect horizontal roads between wire row pairs
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx+1]
            if wr2 - wr1 > 15:
                continue
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    for mid_y in range(wr1+1, wr2):
                        if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                            adj = (ib(rcx, mid_y-1) and bool(rm[mid_y-1, rcx])) or \
                                  (ib(rcx, mid_y+1) and bool(rm[mid_y+1, rcx]))
                            if adj:
                                return (Tool.ROAD, rcx, mid_y)

    elif phase == 5:
        # Cross-connect vertical roads between wire col pairs
        for wc_idx in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[wc_idx], wire_cols[wc_idx+1]
            if wc2 - wc1 > 15:
                continue
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not (0 < ry < WORLD_H - 1):
                        continue
                    for mid_x in range(wc1+1, wc2):
                        if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                            adj = (ib(mid_x-1, ry) and bool(rm[ry, mid_x-1])) or \
                                  (ib(mid_x+1, ry) and bool(rm[ry, mid_x+1]))
                            if adj:
                                return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Wire connection at intersections
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc-1])) or (wc < WORLD_W-1 and bool(wm[wr, wc+1]))
                col_ok = (wr > 0 and bool(wm[wr-1, wc])) or (wr < WORLD_H-1 and bool(wm[wr+1, wc]))
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 7:
        # Extend roads toward powered but unroaded areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H-3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W-3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Place nuclear plants when funded and pop is growing
        if pop > 2000 and funds > 5000:
            nuke_spots = [
                (30, 30), (90, 30), (30, 70), (90, 70),
                (60, 15), (60, 85), (15, 50), (105, 50),
            ]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    else:
        # Wire toward unpowered road areas
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT (main action) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            # Prefer near existing zones and near center
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 0.5 / (1.0 + abs(x - 60)/60.0 + abs(y - 50)/50.0)
            # Prefer powered
            scores[i] += 1.0 if bool(near_power[y, x]) else 0.0

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES (tiered by population) ----
    if pop > 50:
        fire_positions = [
            (20, 8), (50, 8), (80, 8), (110, 8),
            (20, 32), (50, 32), (80, 32), (110, 32),
            (20, 56), (50, 56), (80, 56), (110, 56),
            (20, 76), (50, 76), (80, 76), (110, 76),
            (20, 92), (50, 92), (80, 92), (110, 92),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (35, 15), (65, 15), (95, 15),
            (20, 42), (50, 42), (80, 42), (110, 42),
            (35, 65), (65, 65), (95, 65),
            (20, 84), (50, 84), (80, 84), (110, 84),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (25, 25), (95, 25), (25, 72), (95, 72),
            (60, 12), (60, 87), (10, 50), (110, 50),
            (40, 50), (80, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
            (30, 50), (90, 50), (10, 25), (110, 25),
            (10, 75), (110, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 94)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(48, 4), (72, 4), (48, 93), (72, 93), (4, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value when city is developing
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:2, :] = False
        park_cands[WORLD_H-2:, :] = False
        park_cands[:, 0:2] = False
        park_cands[:, WORLD_W-2:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: wire toward unpowered road areas ----
    needs_power2 = rm & ~near_power
    npys2, npxs2 = np.where(needs_power2)
    if len(npxs2) > 0:
        ti = (step * 23) % len(npxs2)
        tx, ty = int(npxs2[ti]), int(npys2[ti])
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs2[best_wi]), int(wire_ys2[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend roads from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

